def upgrade_db_charges():
    conn = get_db()

    conn.execute("""
                 CREATE TABLE IF NOT EXISTS charges
                 (
                     id           INTEGER PRIMARY KEY AUTOINCREMENT,
                     date_facture DATE,
                     categorie    TEXT,
                     responsable  TEXT,
                     montant      REAL,
                     statut       TEXT      DEFAULT 'non_paye',
                     created_at   TIMESTAMP DEFAULT CURRENT_TIMESTAMP
                 )
                 """)

    # 🆕 Rattachement d'une charge "Gasoil (Transport)" à un chauffeur précis, pour
    # pouvoir afficher son historique de gasoil sur sa fiche (page Personnel hors prof).
    try:
        conn.execute("ALTER TABLE charges ADD COLUMN chauffeur_id INTEGER REFERENCES personnel_hors_prof(id)")
    except sqlite3.OperationalError:
        pass  # La colonne existe déjà

    # 🆕 AGENT ADMIN : on retient qui a ajouté chaque charge, pour qu'un agent-admin ne
    # voie ensuite que les charges qu'il a lui-même ajoutées (l'admin continue de tout voir).
    try:
        conn.execute("ALTER TABLE charges ADD COLUMN ajoute_par_id INTEGER REFERENCES users(id)")
    except sqlite3.OperationalError:
        pass  # La colonne existe déjà

    # 🆕 Sous-type de la charge (ex: catégorie "Fournitures de bureau" → sous-type "Stylos",
    # "Feuilles A4"...) : précision libre saisie par l'utilisateur, propre à chaque charge.
    try:
        conn.execute("ALTER TABLE charges ADD COLUMN sous_categorie TEXT DEFAULT ''")
    except sqlite3.OperationalError:
        pass  # La colonne existe déjà

    # 🆕 Source de financement de la charge : d'où vient l'argent utilisé pour régler cette
    # charge (Scolarité, Scolarité + Transport, Frais d'inscription, Autre facture) — choisie
    # en même temps que le mode d'encaissement (Caisse/Banque), au moment où la charge passe
    # au statut "Payé".
    try:
        conn.execute("ALTER TABLE charges ADD COLUMN source_financement TEXT")
    except sqlite3.OperationalError:
        pass  # La colonne existe déjà

    conn.commit()
    conn.close()
    print("Table 'charges' vérifiée/mise à jour avec succès !")


