# 🩹 RÉPARATION (une seule fois, idempotente) : d'anciennes fiches élèves contiennent un pourcentage
# de réduction arrondi à 2 décimales (ex : 26.67 au lieu de 26.6666…), ce qui donnait des
# montants faux (ex : 1500 avec convenu 1100 -> 1099.95). Si le montant obtenu est à moins de
# l'erreur d'arrondi d'un montant entier (1099.95 -> 1100), on recalcule le pourcentage exact.
# Les fiches dont le pourcentage est déjà précis, ou donne un montant "rond" exact, ne bougent pas.
def _pourcentage_exact_si_arrondi(reference, pct):
    try:
        reference = float(reference or 0)
        pct = float(pct or 0)
    except (TypeError, ValueError):
        return None
    if reference <= 0 or pct <= 0 or pct >= 100:
        return None
    if abs(pct - round(pct, 2)) > 1e-9:
        return None  # déjà précis
    net = reference * (1 - pct / 100)
    cible = round(net)
    ecart = abs(net - cible)
    if ecart < 1e-9 or ecart > reference * 0.00005 + 1e-6:
        return None
    return round((reference - cible) / reference * 100, 8)


def upgrade_db_reduction_precision():
    if not os.path.exists(DB_PATH): return
    conn = get_db()
    try:
        lignes = conn.execute(
            "SELECT id, montant_mensualite, reduction_pourcentage, "
            "montant_transport, reduction_transport_pourcentage FROM eleves").fetchall()
        nb = 0
        for l in lignes:
            nouveau_scol = _pourcentage_exact_si_arrondi(l['montant_mensualite'], l['reduction_pourcentage'])
            nouveau_trans = _pourcentage_exact_si_arrondi(l['montant_transport'], l['reduction_transport_pourcentage'])
            if nouveau_scol is not None:
                conn.execute("UPDATE eleves SET reduction_pourcentage=? WHERE id=?", (nouveau_scol, l['id']))
                nb += 1
            if nouveau_trans is not None:
                conn.execute("UPDATE eleves SET reduction_transport_pourcentage=? WHERE id=?", (nouveau_trans, l['id']))
                nb += 1
        conn.commit()
        if nb:
            print(f"[réparation] {nb} pourcentage(s) de réduction arrondi(s) corrigé(s) avec leur valeur exacte.")
    except Exception as _e_rep:
        print("[réparation] pourcentages de réduction non vérifiés :", _e_rep)
    finally:
        conn.close()


upgrade_db_reduction_precision()


# 🚌 TRANSPORT FIXE À 300 DH + RÈGLE DE RÉPARTITION DE LA RÉDUCTION
# ─────────────────────────────────────────────────────────────────────────────
# • Le transport n'est plus saisi : seule la case « Abonné au transport » (oui/non) compte,
#   le montant est fixe (300 MAD).
# • Le « montant convenu » saisi sur la fiche est le TOTAL payé par la famille. Si l'élève est
#   abonné, ce total inclut le transport. La réduction totale (base scolarité + 300 − convenu)
#   est répartie ainsi : 200 DH de réduction sur le transport (il reste donc 100 DH net) puis le
#   reste sur la scolarité.   Ex : base 1500, convenu 1200, abonné
#       → total réduction 600 = 200 (transport : 300 → 100) + 400 (scolarité : 1500 → 1100).
# • Élève déjà inscrit SANS transport qui s'abonne ensuite, deux tarifs au choix :
#       'inclus'     = « ancien tarif » : le montant convenu reste le même (transport inclus) ;
#       'supplement' = « calcul normal » : +200 DH (transport 300 − 100 DH de réduction).
# • Les pourcentages sont stockés sur la fiche (reduction_pourcentage / reduction_transport_pourcentage),
#   donc la génération des factures, la resynchronisation et le reçu PDF restent INCHANGÉS.
# • Élèves déjà abonnés avant ce changement : transport_tarif vide = tarif conservé tel quel.
TRANSPORT_MONTANT_FIXE = 300.0
TRANSPORT_REDUCTION_INCLUS = 200.0       # réduction sur le transport (300 → 100) quand le convenu l'inclut
TRANSPORT_REDUCTION_SUPPLEMENT = 100.0   # réduction sur le transport (300 → 200) en « calcul normal »


def upgrade_db_transport_tarif():
    if not os.path.exists(DB_PATH): return
    conn = get_db()
    try:
        conn.execute("ALTER TABLE eleves ADD COLUMN transport_tarif TEXT")
    except sqlite3.OperationalError:
        pass  # La colonne existe déjà (ou la table n'existe pas encore)
    conn.commit()
    conn.close()


upgrade_db_transport_tarif()


def _calculer_regle_transport(mensualite, reduction_pct, convenu, transport_abonne, tarif, ancien=None):
    """Retourne (montant_transport, reduction_pourcentage, reduction_transport_pourcentage, tarif_a_stocker)."""
    try:
        M = float(mensualite or 0)
    except (TypeError, ValueError):
        M = 0.0
    try:
        r = float(reduction_pct or 0)
    except (TypeError, ValueError):
        r = 0.0
    if transport_abonne != 'oui':
        return 0.0, r, 0.0, None
    T = TRANSPORT_MONTANT_FIXE
    if tarif == 'legacy' and ancien is not None:
        # Ancien abonné : montant et réduction transport conservés tels quels.
        return (float(ancien['montant_transport'] or 0), r,
                float(ancien['reduction_transport_pourcentage'] or 0), None)
    if tarif == 'supplement':
        rt = round(TRANSPORT_REDUCTION_SUPPLEMENT / T * 100, 8) if r > 0 else 0.0
        return T, r, rt, 'supplement'
    # 'inclus' : le montant convenu est le total (scolarité + transport)
    if convenu is None and r > 0 and M > 0:
        convenu = M * (1 - r / 100.0)
    if convenu is None or M <= 0 or convenu >= M + T - 0.005:
        return T, 0.0, 0.0, 'inclus'
    convenu = max(convenu, 0.0)
    D = M + T - convenu                          # réduction totale à répartir
    red_transport = min(D, TRANSPORT_REDUCTION_INCLUS)
    red_scol = min(D - red_transport, M)
    return (T, round(red_scol / M * 100, 8), round(red_transport / T * 100, 8), 'inclus')


def _regle_transport_depuis_form(conn, eleve_id, form, montant_mensualite, reduction_pct, transport_abonne):
    """Lit « montant convenu » et le tarif transport dans le formulaire, retrouve l'ancien état de
    l'élève (s'il existe) et applique _calculer_regle_transport."""
    raw = form.get('montant_convenu')
    convenu = None
    if raw not in (None, ''):
        try:
            convenu = float(raw)
        except ValueError:
            convenu = None
    ancien = None
    if eleve_id:
        ancien = conn.execute(
            "SELECT transport_abonne, transport_tarif, montant_transport, reduction_transport_pourcentage "
            "FROM eleves WHERE id=?", (eleve_id,)).fetchone()
    deja_abonne = bool(ancien and ancien['transport_abonne'] == 'oui')
    tarif = (form.get('transport_tarif') or '').strip()
    if tarif not in ('inclus', 'supplement', 'legacy'):
        tarif = (ancien['transport_tarif'] or 'legacy') if deja_abonne else 'inclus'
    if tarif == 'legacy' and not deja_abonne:
        tarif = 'inclus'
    if tarif == 'inclus' and deja_abonne and raw is None:
        # Formulaire périmé sans « montant convenu » : on ne retouche pas la réduction transport.
        try:
            r0 = float(reduction_pct or 0)
        except (TypeError, ValueError):
            r0 = 0.0
        return (TRANSPORT_MONTANT_FIXE, r0,
                float(ancien['reduction_transport_pourcentage'] or 0), 'inclus')
    return _calculer_regle_transport(montant_mensualite, reduction_pct, convenu,
                                     transport_abonne, tarif, ancien)


# 🆕 ÉLÈVES SORTANTS : un élève peut quitter l'école en cours d'année (annulation de la scolarité,
# départ…) ou à la fin de l'année (changement d'école). On mémorise le type de sortie, la date, le
# motif et l'école de destination sur la fiche élève, et — pour les sortants « durant l'année » — un
# cumul de RÉGULE par facture (montant déduit du total payé, cf. /paiements/regule_ajax).
def upgrade_db_eleves_sortants():
    if not os.path.exists(DB_PATH): return
    conn = get_db()
    for table, col, type_col in [
        ("eleves", "statut_sortie", "TEXT"),          # NULL = actif · 'sortant_annee' · 'sortant_fin_annee'
        ("eleves", "date_sortie", "DATE"),
        ("eleves", "motif_sortie", "TEXT"),
        ("eleves", "ecole_destination", "TEXT"),
        ("eleves", "commentaire_sortie", "TEXT"),
        ("eleves", "sortie_declaree_par", "TEXT"),
        ("paiements", "montant_regule", "REAL DEFAULT 0"),
    ]:
        try:
            conn.execute(f"ALTER TABLE {table} ADD COLUMN {col} {type_col}")
        except sqlite3.OperationalError:
            pass  # La colonne existe déjà (ou la table n'est pas encore créée : rejoué après init_db)
    # Les factures déjà régularisées avant ce correctif ne doivent plus apparaître « partiel / non payé »
    try:
        conn.execute("UPDATE paiements SET statut='paye' WHERE COALESCE(montant_regule, 0) > 0 AND statut != 'paye'")
    except sqlite3.OperationalError:
        pass
    # 🆕 Factures à 0 DH déjà générées (réduction de 100 %, bourse) : rien à payer → « payé », jamais « non payé / en retard »
    try:
        conn.execute("UPDATE paiements SET statut='paye' WHERE COALESCE(montant_total, 0) <= 0 AND statut != 'paye'")
    except sqlite3.OperationalError:
        pass
    conn.commit()
    conn.close()


upgrade_db_eleves_sortants()


# 🆕 NOUVEAU : Emploi du temps — un créneau horaire par jour/classe, relié optionnellement
# à une matière déjà configurée sur la classe (l'enseignant suit automatiquement la matière).
def upgrade_db_emploi_temps():
    conn = get_db()
    conn.execute("""
                 CREATE TABLE IF NOT EXISTS emploi_temps (
                     id INTEGER PRIMARY KEY AUTOINCREMENT,
                     classe_id INTEGER NOT NULL,
                     jour TEXT NOT NULL,
                     heure_debut TEXT NOT NULL,
                     heure_fin TEXT NOT NULL,
                     matiere_id INTEGER,
                     libelle TEXT DEFAULT '',
                     salle TEXT DEFAULT '',
                     FOREIGN KEY (classe_id) REFERENCES classes(id) ON DELETE CASCADE,
                     FOREIGN KEY (matiere_id) REFERENCES matieres(id) ON DELETE SET NULL
                 )
                 """)
    try:
        conn.execute("CREATE INDEX IF NOT EXISTS idx_emploi_temps_classe_id ON emploi_temps(classe_id)")
    except sqlite3.OperationalError:
        pass
    # 🆕 Un créneau peut désormais être rattaché à une sous-matière précise (ex: Arabe →
    # Dictée), en plus de la matière — même principe que pour les notes. NULL = pas de
    # sous-matière choisie (comportement inchangé pour les créneaux déjà existants).
    try:
        conn.execute("ALTER TABLE emploi_temps ADD COLUMN sous_matiere_id INTEGER REFERENCES sous_matieres(id)")
    except sqlite3.OperationalError:
        pass  # La colonne existe déjà

    # 🆕 PLUSIEURS sous-matières par créneau (ex: Français 8h-10h → Grammaire + Conjugaison
    # affichées ensemble sur le même créneau). La colonne "sous_matiere_id" ci-dessus ne
    # permettait d'en choisir qu'UNE seule ; on ajoute donc une table de liaison qui permet
    # d'en associer plusieurs à un même créneau, tout en gardant la colonne existante intacte
    # (compatibilité avec les créneaux déjà enregistrés).
    conn.execute("""
                 CREATE TABLE IF NOT EXISTS emploi_temps_sous_matieres (
                     id INTEGER PRIMARY KEY AUTOINCREMENT,
                     creneau_id INTEGER NOT NULL,
                     sous_matiere_id INTEGER NOT NULL,
                     FOREIGN KEY (creneau_id) REFERENCES emploi_temps(id) ON DELETE CASCADE,
                     FOREIGN KEY (sous_matiere_id) REFERENCES sous_matieres(id) ON DELETE CASCADE
                 )
                 """)
    try:
        conn.execute("CREATE INDEX IF NOT EXISTS idx_ets_creneau_id ON emploi_temps_sous_matieres(creneau_id)")
    except sqlite3.OperationalError:
        pass
    # Migration ponctuelle et idempotente : on reporte les anciennes sélections "une seule
    # sous-matière" (colonne sous_matiere_id) dans la nouvelle table de liaison, pour que les
    # créneaux déjà configurés continuent d'afficher leur sous-matière après la mise à jour.
    try:
        conn.execute("""
                     INSERT INTO emploi_temps_sous_matieres (creneau_id, sous_matiere_id)
                     SELECT id, sous_matiere_id FROM emploi_temps
                     WHERE sous_matiere_id IS NOT NULL
                       AND id NOT IN (SELECT creneau_id FROM emploi_temps_sous_matieres)
                     """)
    except sqlite3.OperationalError:
        pass
    conn.commit()
    conn.close()


upgrade_db_emploi_temps()


# 🆕 NOUVEAU RÔLE : "Agent Admin" — accès identique à l'admin sauf quelques exceptions
# (gérées côté application). SQLite ne permet pas de modifier une contrainte CHECK
# existante : on reconstruit la table users avec la nouvelle contrainte si besoin.
def upgrade_db_agent_admin_role():
    if not os.path.exists(DB_PATH):
        return
    conn = get_db()
    try:
        row = conn.execute(
            "SELECT sql FROM sqlite_master WHERE type='table' AND name='users'").fetchone()
        if not row or not row['sql']:
            conn.close()
            return
        if 'agent_admin' in row['sql']:
            conn.close()
            return  # déjà migré

        cols_info = conn.execute("PRAGMA table_info(users)").fetchall()
        col_names = [c['name'] for c in cols_info]
        col_defs = []
        for c in cols_info:
            name = c['name']
            if name == 'id':
                col_defs.append("id INTEGER PRIMARY KEY AUTOINCREMENT")
            elif name == 'role':
                col_defs.append(
                    "role TEXT NOT NULL CHECK (role IN ('admin','agent_admin','enseignant','parent'))")
            elif name == 'email':
                col_defs.append("email TEXT UNIQUE NOT NULL")
            else:
                ctype = c['type'] or 'TEXT'
                notnull = ' NOT NULL' if c['notnull'] else ''
                default = f" DEFAULT {c['dflt_value']}" if c['dflt_value'] is not None else ''
                col_defs.append(f"{name} {ctype}{notnull}{default}")

        conn.execute("PRAGMA foreign_keys=OFF")
        conn.execute("ALTER TABLE users RENAME TO users_old_migration_agentadmin")
        conn.execute(f"CREATE TABLE users ({', '.join(col_defs)})")
        cols_csv = ', '.join(col_names)
        conn.execute(
            f"INSERT INTO users ({cols_csv}) SELECT {cols_csv} FROM users_old_migration_agentadmin")
        conn.execute("DROP TABLE users_old_migration_agentadmin")
        conn.execute("PRAGMA foreign_keys=ON")
        conn.commit()
        print("✅ Migration : rôle 'agent_admin' activé sur la table users.")
    except Exception as e:
        conn.rollback()
        print(f"⚠️ Erreur migration rôle agent_admin : {e}")
    finally:
        conn.close()


upgrade_db_agent_admin_role()


# 🆕 NOUVEAU RÔLE : "Secrétaire" — accès restreint : uniquement ses classes assignées
# (table classe_secretaires, même principe que classe_profs pour les enseignants), avec le
# droit de noter les absences et de voir/modifier les devoirs de ces classes.
def upgrade_db_secretaire_role():
    if not os.path.exists(DB_PATH):
        return
    conn = get_db()
    try:
        row = conn.execute(
            "SELECT sql FROM sqlite_master WHERE type='table' AND name='users'").fetchone()
        if row and row['sql'] and 'secretaire' not in row['sql']:
            cols_info = conn.execute("PRAGMA table_info(users)").fetchall()
            col_names = [c['name'] for c in cols_info]
            col_defs = []
            for c in cols_info:
                name = c['name']
                if name == 'id':
                    col_defs.append("id INTEGER PRIMARY KEY AUTOINCREMENT")
                elif name == 'role':
                    col_defs.append(
                        "role TEXT NOT NULL CHECK (role IN ('admin','agent_admin','enseignant','parent','secretaire'))")
                elif name == 'email':
                    col_defs.append("email TEXT UNIQUE NOT NULL")
                else:
                    ctype = c['type'] or 'TEXT'
                    notnull = ' NOT NULL' if c['notnull'] else ''
                    default = f" DEFAULT {c['dflt_value']}" if c['dflt_value'] is not None else ''
                    col_defs.append(f"{name} {ctype}{notnull}{default}")

            conn.execute("PRAGMA foreign_keys=OFF")
            conn.execute("ALTER TABLE users RENAME TO users_old_migration_secretaire")
            conn.execute(f"CREATE TABLE users ({', '.join(col_defs)})")
            cols_csv = ', '.join(col_names)
            conn.execute(
                f"INSERT INTO users ({cols_csv}) SELECT {cols_csv} FROM users_old_migration_secretaire")
            conn.execute("DROP TABLE users_old_migration_secretaire")
            conn.execute("PRAGMA foreign_keys=ON")
            print("✅ Migration : rôle 'secretaire' activé sur la table users.")

        conn.execute("""
            CREATE TABLE IF NOT EXISTS classe_secretaires (
                classe_id INTEGER NOT NULL,
                secretaire_id INTEGER NOT NULL,
                FOREIGN KEY (classe_id) REFERENCES classes(id) ON DELETE CASCADE,
                FOREIGN KEY (secretaire_id) REFERENCES users(id) ON DELETE CASCADE,
                PRIMARY KEY (classe_id, secretaire_id)
            )
        """)
        conn.commit()
    except Exception as e:
        conn.rollback()
        print(f"⚠️ Erreur migration rôle secretaire : {e}")
    finally:
        conn.close()


upgrade_db_secretaire_role()

# 🆕 RESPONSABLES DE DÉPARTEMENT : 3 nouveaux rôles qui ont EXACTEMENT les mêmes droits et autorisations
# qu'un compte ADMIN. À la connexion, la session les traite comme « admin » (voir login()), le rôle réel
# restant dans session['role_reel'] et dans users.role (pour l'organigramme).
ROLES_RESPONSABLES = {
    'responsable_marketing':    {'dept': 'Marketing',    'label': 'Responsable Marketing',    'ico': '📣', 'color': '#EC4899'},
    'responsable_informatique': {'dept': 'Informatique', 'label': 'Responsable Informatique', 'ico': '💻', 'color': '#06B6D4'},
    'responsable_commercial':   {'dept': 'Commercial',   'label': 'Responsable Commercial',   'ico': '💼', 'color': '#F59E0B'},
}
ROLES_ADMIN_SQL = "'admin','responsable_marketing','responsable_informatique','responsable_commercial'"
ROLES_ADMIN_SQL_AGENT = ROLES_ADMIN_SQL + ",'agent_admin'"


def upgrade_db_responsables_role():
    """Autorise les rôles 'responsable_*' dans la contrainte CHECK de users.role (reconstruction
    de la table selon la procédure officielle SQLite : table neuve -> copie -> drop -> rename)."""
    if not os.path.exists(DB_PATH):
        return
    conn = get_db()
    try:
        row = conn.execute("SELECT sql FROM sqlite_master WHERE type='table' AND name='users'").fetchone()
        if not row or not row['sql'] or 'responsable_marketing' in row['sql']:
            return
        sql = row['sql']
        nouveau = re.sub(r"'secretaire'(\s*)\)", r"'secretaire','responsable_marketing','responsable_informatique','responsable_commercial'\1)", sql, count=1)
        if nouveau == sql:
            print("⚠️  Migration responsables : contrainte CHECK introuvable, migration ignorée.")
            return
        nouveau = re.sub(r'(?is)^\s*CREATE\s+TABLE\s+(IF\s+NOT\s+EXISTS\s+)?["`]?users["`]?', 'CREATE TABLE users_new_resp', nouveau, count=1)
        extras = [r['sql'] for r in conn.execute(
            "SELECT sql FROM sqlite_master WHERE tbl_name='users' AND type IN ('index','trigger') AND sql IS NOT NULL").fetchall()]
        cols = ', '.join(c['name'] for c in conn.execute("PRAGMA table_info(users)").fetchall())
        conn.commit()
        conn.execute("PRAGMA foreign_keys=OFF")
        conn.execute("BEGIN")
        conn.execute(nouveau)
        conn.execute(f"INSERT INTO users_new_resp ({cols}) SELECT {cols} FROM users")
        conn.execute("DROP TABLE users")
        conn.execute("ALTER TABLE users_new_resp RENAME TO users")
        for ddl in extras:
            try:
                conn.execute(ddl)
            except Exception:
                pass
        conn.execute("COMMIT")
        conn.execute("PRAGMA foreign_keys=ON")
        print("✅ Migration : rôles 'responsable_marketing/informatique/commercial' activés sur la table users.")
    except Exception as ex:
        try:
            conn.execute("ROLLBACK")
        except Exception:
            pass
        print(f"⚠️  Migration responsables ignorée : {ex}")
    finally:
        conn.close()


upgrade_db_responsables_role()


