# 🆕 ORGANISATION DES PAIEMENTS PAR MOIS + SUIVI RETARD (échéance = le 1er du mois)
# ===================================================================
# - paiements.mois : colonne dédiée (format 'YYYY-MM'), maintenue automatiquement par
#   triggers SQLite à partir de date_echeance, pour un filtrage/groupement par mois fiable
#   quel que soit le point d'insertion (génération auto, ajout manuel, etc.).
# - paiements.notif_retard_envoyee : évite d'envoyer plusieurs fois la même notification
#   de retard au parent pour une même facture.
# ═══ 💳 PAIEMENT PAR CHÈQUE ═══════════════════════════════════════════════════════════
# Un chèque enregistré = montant promis, à déposer à une date précise. Il N'EST PAS compté dans les
# revenus (paiements.montant_paye reste inchangé) tant qu'il n'est pas marqué « payé ». Tant qu'il est
# « en_attente », la part couverte par le chèque est retirée du reste à relancer (notifications + WhatsApp).
_SQL_CHEQUES_ATTENTE = ("COALESCE((SELECT SUM(ch.montant) FROM cheques_paiement ch "
                        "WHERE ch.paiement_id = p.id AND ch.statut = 'en_attente'), 0)")
_SQL_RESTE_COUVERT_CHEQUE = (f"({_SQL_CHEQUES_ATTENTE} > 0 AND "
                             f"(p.montant_total - COALESCE(p.montant_paye, 0) - {_SQL_CHEQUES_ATTENTE}) <= 0.009)")


# « Paiement en cours » : facture entièrement couverte par un/des chèque(s) en attente dont la date de dépôt
# n'est PAS encore écoulée (date_depot >= aujourd'hui). Dès que la date est écoulée sans que le chèque soit marqué
# payé, la facture redevient comptée comme impayée (Non payé / Partiel).
_SQL_CHEQUES_VALIDES = ("COALESCE((SELECT SUM(ch.montant) FROM cheques_paiement ch WHERE ch.paiement_id = p.id "
                        "AND ch.statut = 'en_attente' AND ch.date_depot >= date('now','localtime')), 0)")
_SQL_EN_COURS = (f"(p.statut IN ('non_paye','partiel') AND {_SQL_CHEQUES_VALIDES} > 0 AND "
                 f"(p.montant_total - COALESCE(p.montant_paye, 0) - {_SQL_CHEQUES_VALIDES}) <= 0.009)")


def _assurer_table_cheques(conn=None):
    own = conn is None
    if own:
        if not os.path.exists(DB_PATH):
            return
        conn = get_db()
    try:
        conn.execute("""
            CREATE TABLE IF NOT EXISTS cheques_paiement (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                paiement_id INTEGER NOT NULL,
                montant REAL NOT NULL,
                date_depot DATE NOT NULL,
                numero TEXT,
                statut TEXT DEFAULT 'en_attente',
                mode_encaissement TEXT,
                created_by TEXT,
                created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
                date_statut DATETIME
            )""")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_cheques_paiement ON cheques_paiement(paiement_id, statut)")
        if own:
            conn.commit()
    finally:
        if own:
            conn.close()


def _cheques_attente_map(conn):
    """{paiement_id: (somme en attente, nombre, date de dépôt la plus proche, somme dont la date n'est pas écoulée)}"""
    return {r['paiement_id']: (float(r['s'] or 0), r['n'], r['d'] or '', float(r['sv'] or 0)) for r in conn.execute(
        "SELECT paiement_id, SUM(montant) AS s, COUNT(*) AS n, MIN(date_depot) AS d, "
        "SUM(CASE WHEN date_depot >= date('now','localtime') THEN montant ELSE 0 END) AS sv "
        "FROM cheques_paiement WHERE statut = 'en_attente' GROUP BY paiement_id").fetchall()}


def upgrade_db_organisation_paiements():
    if not os.path.exists(DB_PATH): return
    conn = get_db()
    try:
        try:
            conn.execute("ALTER TABLE paiements ADD COLUMN mois TEXT")
        except sqlite3.OperationalError:
            pass  # La colonne existe déjà
        try:
            conn.execute("ALTER TABLE paiements ADD COLUMN notif_retard_envoyee INTEGER DEFAULT 0")
        except sqlite3.OperationalError:
            pass

        # Rattrapage des factures existantes qui n'ont pas encore de mois renseigné
        conn.execute("""
            UPDATE paiements SET mois = substr(date_echeance, 1, 7)
            WHERE (mois IS NULL OR mois = '') AND date_echeance IS NOT NULL AND date_echeance != ''
        """)

        conn.execute("CREATE INDEX IF NOT EXISTS idx_paiements_mois ON paiements(mois)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_paiements_eleve_mois ON paiements(eleve_id, mois)")

        # Triggers : maintiennent automatiquement 'mois' à jour à partir de 'date_echeance',
        # quel que soit l'endroit du code qui insère/modifie une facture.
        conn.execute("""
            CREATE TRIGGER IF NOT EXISTS trg_paiements_mois_insert
            AFTER INSERT ON paiements
            FOR EACH ROW WHEN NEW.date_echeance IS NOT NULL AND NEW.date_echeance != ''
                AND (NEW.mois IS NULL OR NEW.mois = '')
            BEGIN
                UPDATE paiements SET mois = substr(NEW.date_echeance, 1, 7) WHERE id = NEW.id;
            END;
        """)
        conn.execute("""
            CREATE TRIGGER IF NOT EXISTS trg_paiements_mois_update
            AFTER UPDATE OF date_echeance ON paiements
            FOR EACH ROW WHEN NEW.date_echeance IS NOT NULL AND NEW.date_echeance != ''
            BEGIN
                UPDATE paiements SET mois = substr(NEW.date_echeance, 1, 7) WHERE id = NEW.id;
            END;
        """)

        conn.commit()
        print("Migration : organisation des paiements par mois + suivi retard OK.")
    except Exception as e:
        conn.rollback()
        print(f"Erreur migration organisation paiements : {e}")
    finally:
        conn.close()


upgrade_db_organisation_paiements()
_assurer_table_cheques()



