# 🆕 SYSTÈME DE NOTATION PAR CYCLE — choisi par l'admin depuis sa page Profil.
#   'lettres' : Système 1 — A / B / C (Bon / Moyen / Bas)
#   '10'      : Système 2 — note sur 10
#   '20'      : Système 3 — note sur 20
# En interne, `notes.note` reste TOUJOURS stockée sur 20 (moyennes, bulletins, classements,
# analyses : tout le moteur de calcul existant reste cohérent). La conversion se fait à la saisie
# (note_depuis_saisie) et à l'affichage (note_pour_affichage) selon le système du cycle.
SYSTEMES_NOTES = {
    'lettres': 'Système 1 — Lettres A / B / C',
    '10': 'Système 2 — Note sur 10',
    '20': 'Système 3 — Note sur 20',
}


def upgrade_db_systeme_notes():
    if not os.path.exists(DB_PATH): return
    conn = get_db()
    try:
        try:
            conn.execute("ALTER TABLE cycles ADD COLUMN systeme_notes TEXT")
            conn.commit()
        except sqlite3.OperationalError:
            pass
        # Valeurs par défaut = comportement historique : Maternelle en lettres, le reste sur 20.
        conn.execute("UPDATE cycles SET systeme_notes='lettres' WHERE systeme_notes IS NULL AND nom='Maternelle'")
        conn.execute("UPDATE cycles SET systeme_notes='20' WHERE systeme_notes IS NULL")
        conn.commit()
    except sqlite3.OperationalError:
        pass
    conn.close()


def get_systeme_notes(cycle, conn=None):
    """Retourne 'lettres', '10' ou '20' pour un cycle donné (défaut historique si inconnu)."""
    defaut = 'lettres' if cycle == 'Maternelle' else '20'
    if not cycle:
        return '20'
    _local = conn is None
    try:
        if _local:
            conn = get_db()
        row = conn.execute("SELECT systeme_notes FROM cycles WHERE nom = ?", (cycle,)).fetchone()
        val = row['systeme_notes'] if row else None
        return val if val in SYSTEMES_NOTES else defaut
    except Exception:
        return defaut
    finally:
        if _local and conn is not None:
            conn.close()


def note_max_systeme(systeme):
    return 10 if systeme == '10' else 20


def note_depuis_saisie(valeur, systeme):
    """Convertit la valeur saisie (A/B/C, /10 ou /20) en note interne /20. Lève ValueError si invalide."""
    if systeme == 'lettres':
        v = str(valeur or '').strip().upper()
        if v not in NOTE_LETTRES_MATERNELLE:
            raise ValueError('Lettre invalide (A, B ou C attendu).')
        return NOTE_LETTRES_MATERNELLE[v]
    n = float(str(valeur).replace(',', '.'))
    mx = note_max_systeme(systeme)
    if n < 0 or n > mx:
        raise ValueError(f'La note doit être comprise entre 0 et {mx}.')
    return n * 2 if systeme == '10' else n


def note_pour_affichage(note, systeme):
    """Note interne /20 -> valeur affichable dans le système du cycle (lettre ou nombre arrondi)."""
    if note is None or note == '':
        return ''
    if systeme == 'lettres':
        return _lettre_depuis_note(note)
    try:
        n = float(note)
    except (TypeError, ValueError):
        return ''
    if systeme == '10':
        n = n / 2.0
    n = round(n, 2)
    return int(n) if n == int(n) else n


def conv_note_sys(v, systeme):
    """Valeur interne /20 -> nombre dans l'échelle du système (None si lettres ou vide)."""
    if v is None or systeme == 'lettres':
        return None
    try:
        v = float(v)
    except (TypeError, ValueError):
        return None
    return v / 2.0 if systeme == '10' else v


def fmt_moy_sys(v, systeme, dec=2, suffix=True):
    """Affichage d'une moyenne/note interne /20 : 'A', '7.50/10' ou '15.00/20' selon le système."""
    if v is None or v == '' or v == 'N/A':
        return '—'
    if systeme == 'lettres':
        return _lettre_depuis_note(v) or '—'
    x = conv_note_sys(v, systeme)
    if x is None:
        return '—'
    return f"{x:.{dec}f}" + (f"/{note_max_systeme(systeme)}" if suffix else '')


def libelle_echelle_sys(systeme):
    return 'A/B/C' if systeme == 'lettres' else f"/{note_max_systeme(systeme)}"


app.jinja_env.globals['fmt_moy'] = fmt_moy_sys
app.jinja_env.globals['conv_note'] = conv_note_sys
app.jinja_env.globals['note_max'] = note_max_systeme
app.jinja_env.globals['echelle_notes'] = libelle_echelle_sys


# ── Analyses / exports : système du cycle analysé, mémorisé le temps de la requête (flask.g) ──
def _set_sys_analyse(cycle, conn=None):
    try:
        g.sys_analyse = get_systeme_notes(cycle, conn)
    except Exception:
        pass


def _sa():
    try:
        v = getattr(g, 'sys_analyse', '20')
    except Exception:
        v = '20'
    return v if v in SYSTEMES_NOTES else '20'


def _sn(v, dec=1):
    """Moyenne interne /20 -> texte dans l'échelle du cycle analysé (sans suffixe)."""
    if v is None:
        return '—'
    x = float(v) / 2.0 if _sa() == '10' else float(v)
    return f"{x:.{dec}f}"


def _se():
    """Suffixe d'échelle : '/10' ou '/20'."""
    return '/10' if _sa() == '10' else '/20'


def _sth(n):
    """Seuil exprimé en /20 -> texte dans l'échelle du cycle (ex. 10 -> '5' en /10)."""
    x = n / 2.0 if _sa() == '10' else n
    return f"{x:g}"


def _cv(v):
    """Convertit une valeur interne /20 vers l'échelle du cycle analysé (pour les templates)."""
    if v is None or v == '':
        return v
    try:
        return float(v) / 2.0 if _sa() == '10' else float(v)
    except (TypeError, ValueError):
        return v


app.jinja_env.globals['cv'] = _cv
app.jinja_env.globals['ech'] = _se
app.jinja_env.globals['echmax'] = lambda: 10 if _sa() == '10' else 20
app.jinja_env.filters['cvf'] = _cv


upgrade_db_systeme_notes()


# 🆕 NOUVEAU : convertit un fichier image uploadé (photo de hub/cycle) en data URI
# base64, en le redimensionnant/compressant via PIL pour rester léger dans la base.
def _traiter_photo_cycle(fichier):
    if not fichier or not getattr(fichier, 'filename', ''):
        return None
    try:
        from PIL import Image
        img = Image.open(fichier.stream)
        img = img.convert('RGB')
        img.thumbnail((400, 400), Image.LANCZOS)
        buf = io.BytesIO()
        img.save(buf, format='JPEG', quality=85)
        b64 = base64.b64encode(buf.getvalue()).decode('ascii')
        return f'data:image/jpeg;base64,{b64}'
    except Exception:
        return None


# 🆕 COMPRESSION AUTOMATIQUE DES IMAGES À L'UPLOAD ────────────────────────────────
# Toutes les images envoyées par l'app (photos élèves, personnel, patrimoine, logo,
# bannière, pièces jointes de communications/devoirs/messages) passaient jusqu'ici
# telles quelles (résolution d'origine du téléphone/appareil photo, parfois plusieurs
# Mo par photo) — ce qui gonfle le volume des sauvegardes (et la bande passante) à
# chaque backup. Cette fonction redimensionne et recompresse une image AVANT de
# l'écrire sur le disque, tout en restant totalement transparente pour l'appelant :
#   - Si le fichier n'est pas une image reconnue (PDF, Word, GIF animé...) ou si PIL
#     échoue pour une raison quelconque, on sauvegarde le fichier ORIGINAL sans y
#     toucher (aucune fonctionnalité cassée : rien n'est jamais perdu).
#   - Le format d'origine (PNG/JPEG/WEBP) est conservé (important pour les logos
#     avec transparence) — seules la résolution et la compression sont optimisées.
_EXTENSIONS_IMAGE_COMPRESSIBLES = {'jpg', 'jpeg', 'png', 'webp'}


def _sauvegarder_image_compressee(fichier, chemin_destination, max_dimension=1600, qualite=82):
    """Redimensionne (si besoin) + recompresse `fichier` (objet Werkzeug FileStorage) puis
    l'écrit à `chemin_destination`. Retombe sur une sauvegarde brute si ce n'est pas une image
    compressible ou si la compression échoue pour une raison quelconque."""
    ext = chemin_destination.rsplit('.', 1)[-1].lower() if '.' in chemin_destination else ''
    if ext not in _EXTENSIONS_IMAGE_COMPRESSIBLES:
        fichier.save(chemin_destination)
        return
    try:
        from PIL import Image
        img = Image.open(fichier.stream)
        img_format = (img.format or ('PNG' if ext == 'png' else 'JPEG'))
        # Redimensionne uniquement si l'image dépasse la taille maximale (ne jamais agrandir).
        if img.width > max_dimension or img.height > max_dimension:
            img.thumbnail((max_dimension, max_dimension), Image.LANCZOS)
        if img_format == 'JPEG' and img.mode in ('RGBA', 'P'):
            img = img.convert('RGB')  # JPEG ne supporte pas la transparence
        parametres = {'optimize': True}
        if img_format == 'JPEG':
            parametres['quality'] = qualite
        elif img_format == 'PNG':
            parametres['compress_level'] = 8
        elif img_format == 'WEBP':
            parametres['quality'] = qualite
        img.save(chemin_destination, format=img_format, **parametres)
    except Exception as e:
        print(f"  ⚠️  Compression image échouée ({os.path.basename(chemin_destination)}) : {e} — sauvegarde brute.")
        try:
            fichier.stream.seek(0)
        except Exception:
            pass
        fichier.save(chemin_destination)


# 🆕 NOUVEAU : affiche la photo (ou l'emoji à défaut) d'un cycle sur les boutons des
# 4 pages hub (Élèves / Notes / Paiements / Classes), dans un cadre CIRCULAIRE façon
# "badge/sticker" (anneau coloré + ombre), comme le modèle demandé par l'école.
# `c` est un dict de cycle (issu de get_all_cycles / nav_cycles).
def cycle_icon_html(c, size='84px', bordure='5px'):
    from markupsafe import Markup, escape
    photo = None
    try:
        photo = c.get('photo') if hasattr(c, 'get') else c['photo']
    except (KeyError, IndexError, TypeError):
        photo = None
    couleur = 'blue-mid'
    try:
        couleur = (c.get('couleur') if hasattr(c, 'get') else c['couleur']) or 'blue-mid'
    except (KeyError, IndexError, TypeError):
        pass
    icone = '🏫'
    try:
        icone = (c.get('icone') if hasattr(c, 'get') else c['icone']) or '🏫'
    except (KeyError, IndexError, TypeError):
        pass

    cadre_style = (
        f'width:{size};height:{size};border-radius:50%;overflow:hidden;'
        f'display:inline-flex;align-items:center;justify-content:center;'
        f'background:#fff;border:{bordure} solid var(--{couleur}, #FFD60A);'
        f'box-shadow:0 4px 14px rgba(0,0,0,.18), inset 0 0 0 3px rgba(255,255,255,.75);'
        f'flex-shrink:0;'
    )
    if photo:
        contenu = f'<img src="{escape(photo)}" alt="" loading="lazy" style="width:100%;height:100%;object-fit:cover;">'
    else:
        contenu = f'<span style="font-size:calc({size} * 0.5); line-height:1;">{escape(icone)}</span>'
    return Markup(f'<div style="{cadre_style}">{contenu}</div>')


app.jinja_env.globals['cycle_icon_html'] = cycle_icon_html
