_AVATAR_COULEURS = ['#2563eb', '#7c3aed', '#0d9488', '#d97706', '#db2777', '#16a34a', '#0891b2', '#c2410c']


def avatar_html(photo=None, prenom='', nom='', size=40, initiales=None, extra_style=''):
    """Avatar CIRCULAIRE : la photo si elle existe, sinon les initiales sur fond coloré.
    `size` en pixels (modifiable partout). Utilisable dans les templates : {{ avatar(...) }}"""
    from markupsafe import Markup, escape
    try:
        size = int(size)
    except (TypeError, ValueError):
        size = 40
    base = (f"width:{size}px;height:{size}px;min-width:{size}px;border-radius:50%;flex-shrink:0;"
            f"display:inline-flex;align-items:center;justify-content:center;overflow:hidden;{extra_style}")
    if photo:
        return Markup(f'<img src="/eleves/photo/{escape(photo)}" alt="" '
                      f'style="{base}object-fit:cover;background:#e2e8f0;">')
    ini = initiales
    if ini is None:
        ini = ((str(prenom or '')[:1]) + (str(nom or '')[:1])).upper() or '?'
    couleur = _AVATAR_COULEURS[sum(ord(ch) for ch in f"{prenom}{nom}{ini}") % len(_AVATAR_COULEURS)]
    return Markup(f'<span style="{base}background:{couleur};color:#fff;font-weight:700;'
                  f'font-size:{max(size * 0.38, 9):.0f}px;">{escape(ini)}</span>')


app.jinja_env.globals['avatar'] = avatar_html


def _photo_session_courante():
    """Photo de l'utilisateur connecté (users, ou personnel_hors_prof pour chauffeur/accompagnatrice)."""
    try:
        uid = session.get('user_id')
        role = getattr(flask_g, 'role_reel', None) or session.get('role')
        conn = get_db()
        try:
            if role in ('chauffeur', 'accompagnatrice'):
                r = conn.execute("SELECT photo FROM personnel_hors_prof WHERE id=?", (uid,)).fetchone()
            else:
                r = conn.execute("SELECT photo FROM users WHERE id=?", (uid,)).fetchone()
        finally:
            conn.close()
        return r['photo'] if r and r['photo'] else None
    except Exception:
        return None


def _enregistrer_photo_profil(conn, table, row_id, fichier, prefixe):
    """Valide, compresse et enregistre une photo, supprime l'ancienne, met à jour la colonne photo.
    Retourne (ok, message). `table` est une valeur interne (jamais saisie par l'utilisateur)."""
    assert table in ('users', 'eleves', 'personnel_hors_prof')
    if not fichier or fichier.filename == '':
        return False, 'Veuillez sélectionner une image.'
    ext = fichier.filename.rsplit('.', 1)[-1].lower() if '.' in fichier.filename else ''
    if ext not in ALLOWED_PHOTO_EXTENSIONS:
        return False, (f"Format d'image non autorisé. Formats acceptés : "
                       f"{', '.join(sorted(ALLOWED_PHOTO_EXTENSIONS))}.")
    ts = datetime.datetime.now().strftime('%Y%m%d%H%M%S')
    nom_fichier = f"{prefixe}_{row_id}_{ts}.{ext}"
    ancien = conn.execute(f"SELECT photo FROM {table} WHERE id=?", (row_id,)).fetchone()
    if ancien and ancien['photo']:
        ancien_path = os.path.join(UPLOAD_FOLDER_PHOTOS, ancien['photo'])
        if os.path.exists(ancien_path):
            try:
                os.remove(ancien_path)
            except OSError:
                pass
    _sauvegarder_image_compressee(fichier, os.path.join(UPLOAD_FOLDER_PHOTOS, nom_fichier),
                                  max_dimension=1000, qualite=82)
    conn.execute(f"UPDATE {table} SET photo=? WHERE id=?", (nom_fichier, row_id))
    conn.commit()
    return True, 'Photo de profil mise à jour !'


def _supprimer_photo_profil(conn, table, row_id):
    assert table in ('users', 'eleves', 'personnel_hors_prof')
    ancien = conn.execute(f"SELECT photo FROM {table} WHERE id=?", (row_id,)).fetchone()
    if ancien and ancien['photo']:
        ancien_path = os.path.join(UPLOAD_FOLDER_PHOTOS, ancien['photo'])
        if os.path.exists(ancien_path):
            try:
                os.remove(ancien_path)
            except OSError:
                pass
    conn.execute(f"UPDATE {table} SET photo=NULL WHERE id=?", (row_id,))
    conn.commit()



