# 🆕 Absences — extension du module aux enseignants et au personnel hors prof (en plus des
# élèves, déjà couverts par la table `absences`). Mêmes colonnes que la table existante pour
# rester cohérent (date_absence, justifiee, motif, signale_par).
def upgrade_db_absences_hub():
    if not os.path.exists(DB_PATH):
        return
    conn = get_db()
    conn.execute("""
                 CREATE TABLE IF NOT EXISTS absences_enseignants (
                     id            INTEGER PRIMARY KEY AUTOINCREMENT,
                     enseignant_id INTEGER REFERENCES users(id),
                     date_absence  DATE NOT NULL,
                     justifiee     INTEGER DEFAULT 0,
                     motif         TEXT,
                     signale_par   INTEGER REFERENCES users(id),
                     date_creation DATETIME DEFAULT CURRENT_TIMESTAMP
                 )
                 """)
    conn.execute("""
                 CREATE TABLE IF NOT EXISTS absences_personnel (
                     id            INTEGER PRIMARY KEY AUTOINCREMENT,
                     personnel_id  INTEGER REFERENCES personnel_hors_prof(id),
                     date_absence  DATE NOT NULL,
                     justifiee     INTEGER DEFAULT 0,
                     motif         TEXT,
                     signale_par   INTEGER REFERENCES users(id),
                     date_creation DATETIME DEFAULT CURRENT_TIMESTAMP
                 )
                 """)
    conn.commit()

    # 🩹 CORRECTIF (filet de sécurité) : si ces tables existaient déjà (créées par une
    # version antérieure de l'app, avant l'ajout de certaines colonnes), le CREATE TABLE
    # IF NOT EXISTS ci-dessus ne les met PAS à jour — la table reste figée avec son ancien
    # schéma. Résultat concret côté utilisateur : la page /absences/dashboard/enseignant
    # (ou /personnel) plante avec une "Internal Server Error" dès qu'une requête référence
    # une colonne manquante (ex: "no such column: justifiee"). On répare ici en ajoutant
    # toute colonne manquante, sans jamais toucher aux données déjà présentes.
    colonnes_attendues = [
        ("justifiee", "INTEGER DEFAULT 0"),
        ("motif", "TEXT"),
        ("signale_par", "INTEGER REFERENCES users(id)"),
        ("date_creation", "DATETIME DEFAULT CURRENT_TIMESTAMP"),
    ]
    for table in ('absences_enseignants', 'absences_personnel'):
        try:
            cols_existantes = {c['name'] for c in conn.execute(f"PRAGMA table_info({table})").fetchall()}
        except sqlite3.OperationalError:
            continue
        for col, type_col in colonnes_attendues:
            if col not in cols_existantes:
                try:
                    conn.execute(f"ALTER TABLE {table} ADD COLUMN {col} {type_col}")
                    conn.commit()
                    print(f"  🩹 Colonne '{col}' ajoutée à {table} via le filet de sécurité.")
                except sqlite3.OperationalError as ex_fallback:
                    print(f"  ❌ Échec de l'ajout de la colonne {col} à {table} : {ex_fallback}")
    conn.close()


upgrade_db_absences_hub()

# 🆕 Valeurs par défaut (= couleurs actuelles de l'application) utilisées tant que l'admin
# n'a pas personnalisé, et pré-remplies dans le formulaire de personnalisation.
COULEURS_PAR_DEFAUT = {
    'couleur_texte_clair': '#0F172A', 'couleur_carte_clair': '#FFFFFF', 'couleur_onglet_clair': '#2563EB',
    'couleur_texte_neon': '#F5F5FF', 'couleur_carte_neon': '#121220', 'couleur_onglet_neon': '#00E5FF',
    # 🆕 Couleur de fond en DÉGRADÉ (2 couleurs) avec effet "fondu" en dégradé de l'app.
    'couleur_fond_clair': '#F8FAFC', 'couleur_fond_neon': '#07070C',
    'couleur_fond_clair_2': '#E0E9F5', 'couleur_fond_neon_2': '#12081F',
    # 🆕 Même principe pour le fond des CARTES : dégradé fondu entre 2 couleurs.
    'couleur_carte_clair_2': '#F1F5F9', 'couleur_carte_neon_2': '#1B1B30',
    # 🆕 Couleurs indépendantes : liens de navigation (sidebar), texte à l'intérieur des
    # cartes, et boutons — séparées de la couleur de texte générale et de la couleur des
    # onglets, pour permettre une personnalisation fine de chaque élément.
    'couleur_navlink_clair': '#000000', 'couleur_navlink_neon': '#B8B8D0',
    'couleur_cartetexte_clair': '#0F172A', 'couleur_cartetexte_neon': '#F5F5FF',
    'couleur_bouton_clair': '#2563EB', 'couleur_bouton_neon': '#00E5FF',
}
_HEX_RE = re.compile(r'^#[0-9A-Fa-f]{6}$')


def get_couleurs_personnalisees():
    """🆕 Retourne les 6 couleurs personnalisées actives (texte/carte/onglet × clair/néon),
    en retombant sur COULEURS_PAR_DEFAUT pour toute valeur absente ou invalide. Utilisé par
    nav_html() sur CHAQUE page pour injecter le <style> de personnalisation."""
    couleurs = dict(COULEURS_PAR_DEFAUT)
    if not os.path.exists(DB_PATH):
        return couleurs
    conn = get_db()
    colonnes = ', '.join(COULEURS_PAR_DEFAUT.keys())
    row = conn.execute(f"SELECT {colonnes} FROM parametres_ecole WHERE id=1").fetchone()
    conn.close()
    if row:
        for cle in couleurs:
            valeur = row[cle] if cle in row.keys() else None
            if valeur and _HEX_RE.match(valeur):
                couleurs[cle] = valeur
    return couleurs


def _hex_vers_rgba(hex_color, alpha):
    """Convertit '#RRGGBB' en chaîne 'r, g, b' (sans rgba() englobant) pour composer des
    couleurs translucides à partir d'une couleur personnalisée arbitraire."""
    hex_color = hex_color.lstrip('#')
    r, g, b = int(hex_color[0:2], 16), int(hex_color[2:4], 16), int(hex_color[4:6], 16)
    return f"rgba({r},{g},{b},{alpha})"


# 🆕 À partir d'UNE seule couleur de texte choisie par l'admin, on dérive tout le nuancier de
# gris du design system (--gray-900 à --gray-400, --text-soft) par paliers d'opacité. Ainsi,
# changer « Couleur des textes » ne modifie plus seulement les titres (--text/--gray-900) mais
# TOUS les textes qui utilisent une nuance de gris (texte atténué, libellés, sous-titres...),
# aussi bien dans les pages que hors des cartes.
def _nuancier_texte(hex_color):
    return {
        'text': hex_color,
        'text-soft': _hex_vers_rgba(hex_color, .65),
        'gray-900': _hex_vers_rgba(hex_color, 1),
        'gray-800': _hex_vers_rgba(hex_color, .92),
        'gray-700': _hex_vers_rgba(hex_color, .82),
        'gray-600': _hex_vers_rgba(hex_color, .72),
        'gray-500': _hex_vers_rgba(hex_color, .62),
        'gray-400': _hex_vers_rgba(hex_color, .48),
    }


# 🆕 Toutes les classes "carte" racines de l'application (hors sous-éléments comme
# card-body/card-header/card-title, qui n'ont pas de fond opaque propre et laissent donc
# apparaître le dégradé du conteneur). Utilisé pour que le fond fondu/dégradé personnalisable
# s'applique à TOUTES les cartes de l'appli, pas seulement à la classe générique .card.
_TOUTES_LES_CLASSES_CARTES = [
    'card', 'aide-card', 'aide-form-card', 'chub-actions-card', 'chub-ai-card', 'chub-side-card',
    'classe-card', 'cl-card', 'cl-preview-card', 'cls-card', 'cls-pick-card', 'com-card',
    'com-post-card', 'comdash-top-card', 'conge-card', 'dashia-card', 'ens-card', 'et-classe-card',
    'ga-rank-card', 'hub-card', 'hw-card', 'ia-luxe-card', 'infos-card', 'kclasse-card',
    'kmat-card', 'kp-card', 'kside-card', 'ldg-card', 'login-card', 'lux-add-card', 'lux-chart-card',
    'luxe-card', 'lxn-evt-card', 'lxn-news-card', 'lxn-quick-card', 'lxn-social-card',
    'lxn-stats-circle-card', 'mbiz-card', 'msg-info-card', 'msg-info-eleve-card', 'notes-eleve-card',
    'notes-empty-card', 'pai-access-card', 'parent-pay-card', 'patri-story-card', 'perf-card',
    'phd-eleve-card', 'phd-map-card', 'phd-sidebar-card', 'phd-stat-card', 'php-emp-card',
    'qr-card', 'robot-card', 'robot-reco-card', 'sc-kpi-card', 'sc-stat-card', 'stat-card',
    'sv-job-card', 'sv-status-card',
    # 🆕 Bannières d'en-tête de page (présentes sur la quasi-totalité des pages : élèves,
    # paiement, enseignants, notes, devoirs...) — demande explicite de l'utilisateur : ces
    # bannières doivent suivre EXACTEMENT les mêmes 2 couleurs personnalisées que les cartes,
    # au lieu de rester figées en noir/bleu nuit codé en dur.
    'lux-hero', 'hw-detail-hero',
    # 🆕 'zoom-card' retiré intentionnellement : ce sont les cartes des hubs "Choix du Cycle" /
    # "Choix de la Classe" (Élèves/Notes/Absences), qui doivent garder leur apparence d'origine
    # (fond transparent, icône ronde colorée par cycle/classe comme élément central) — demande
    # explicite de l'utilisateur de ne pas les inclure dans le dégradé personnalisable 2 couleurs.
]


def couleurs_personnalisees_style_html():
    """🆕 Construit le <style> qui applique les couleurs personnalisées (texte, cartes,
    onglets/accent) en mode clair ET néon, en surchargeant les variables CSS du design
    system (--text, --surface, --primary...) ainsi que quelques accents encore codés en
    dur (onglet actif du menu, bouton principal). Injecté par nav_html() sur chaque page,
    donc appliqué automatiquement à toute l'application sans dépendre du chargement d'un
    fichier CSS séparé. Si l'admin n'a rien personnalisé, ce bloc réaffirme simplement les
    couleurs par défaut (aucun changement visuel)."""
    c = get_couleurs_personnalisees()
    onglet_clair_15 = _hex_vers_rgba(c['couleur_onglet_clair'], .15)
    onglet_neon_12 = _hex_vers_rgba(c['couleur_onglet_neon'], .12)
    # 🆕 Nuanciers complets dérivés de chaque couleur de texte : un pour le texte général (hors
    # cartes), un pour le texte à l'intérieur des cartes — indépendants l'un de l'autre.
    nuance_texte_clair = _nuancier_texte(c['couleur_texte_clair'])
    nuance_texte_neon = _nuancier_texte(c['couleur_texte_neon'])
    nuance_cartetexte_clair = _nuancier_texte(c['couleur_cartetexte_clair'])
    nuance_cartetexte_neon = _nuancier_texte(c['couleur_cartetexte_neon'])
    # 🆕 FIX : le dégradé "fondu" ne doit utiliser QUE les 2 couleurs choisies par
    # l'utilisateur pour le fond (jamais la couleur des onglets ni la couleur du texte —
    # cette dernière est sombre par défaut, ce qui faisait apparaître une tache NOIRE au
    # coin du dégradé, quelle que soit la personnalisation). Les 2 teintes du radial-gradient
    # sont donc exactement les 2 couleurs de fond choisies, à intensité maximale avant de
    # s'estomper vers "transparent" (c'est le radial-gradient lui-même qui crée le fondu).
    fond_clair_tint1 = _hex_vers_rgba(c['couleur_fond_clair'], 1)
    fond_clair_tint2 = _hex_vers_rgba(c['couleur_fond_clair_2'], 1)
    fond_neon_tint1 = _hex_vers_rgba(c['couleur_fond_neon'], 1)
    fond_neon_tint2 = _hex_vers_rgba(c['couleur_fond_neon_2'], 1)
    # 🆕 FIX : même principe pour le fond des CARTES — le dégradé ne doit utiliser QUE les
    # 2 couleurs de carte choisies par l'utilisateur (avant : couleur des onglets + couleur du
    # texte, cette dernière étant sombre par défaut → tache NOIRE en bas/à droite de chaque
    # carte, quelle que soit la personnalisation). Désormais les 2 teintes du radial-gradient
    # sont exactement les 2 couleurs de carte choisies, donc TOUTES les cartes (et tout élément
    # qui suit ce même principe, ex. les bannières) restent cohérentes avec ces 2 couleurs.
    carte_clair_tint1 = _hex_vers_rgba(c['couleur_carte_clair'], 1)
    carte_clair_tint2 = _hex_vers_rgba(c['couleur_carte_clair_2'], 1)
    carte_neon_tint1 = _hex_vers_rgba(c['couleur_carte_neon'], 1)
    carte_neon_tint2 = _hex_vers_rgba(c['couleur_carte_neon_2'], 1)
    # 🆕 Sélecteurs CSS pré-construits (hors f-string imbriquée, pour compatibilité < Python 3.12)
    selecteurs_cartes_clair = ','.join('html:not(.theme-neon) .' + cls for cls in _TOUTES_LES_CLASSES_CARTES)
    selecteurs_cartes_neon = ','.join('html.theme-neon .' + cls for cls in _TOUTES_LES_CLASSES_CARTES)
    return f"""<style>
:root{{
  --text:{nuance_texte_clair['text']} !important; --text-soft:{nuance_texte_clair['text-soft']} !important;
  --gray-400:{nuance_texte_clair['gray-400']} !important; --gray-500:{nuance_texte_clair['gray-500']} !important;
  --gray-600:{nuance_texte_clair['gray-600']} !important; --gray-700:{nuance_texte_clair['gray-700']} !important;
  --gray-800:{nuance_texte_clair['gray-800']} !important; --gray-900:{nuance_texte_clair['gray-900']} !important;
  --surface:{c['couleur_carte_clair']} !important;
  --primary:{c['couleur_onglet_clair']} !important; --primary-mid:{c['couleur_onglet_clair']} !important;
  --blue:{c['couleur_onglet_clair']} !important; --blue-mid:{c['couleur_onglet_clair']} !important;
  --bg:{c['couleur_fond_clair']} !important;
}}
.nav-link.active{{ background:{onglet_clair_15} !important; border-left-color:{c['couleur_onglet_clair']} !important; }}
.sidebar-nav .nav-link.active .icon{{ color:{c['couleur_onglet_clair']} !important; }}
/* 🆕 Couleur des liens de navigation (sidebar), indépendante de la couleur de texte générale. */
.nav-link{{ color:{c['couleur_navlink_clair']} !important; }}
.nav-link:hover{{ color:{c['couleur_navlink_clair']} !important; }}
.sidebar-nav .nav-link .icon{{ color:{c['couleur_navlink_clair']} !important; }}
/* 🆕 Couleur des boutons (bouton principal), indépendante de la couleur des onglets. */
.btn-primary{{ background:{c['couleur_bouton_clair']} !important; }}
/* 🆕 Arrière-plan "fondu" (dégradé doux) appliqué à TOUTES les pages en mode clair,
   couleur personnalisable par l'admin depuis « Mon profil ». */
html:not(.theme-neon) body, html:not(.theme-neon) .content{{
  background:
    radial-gradient(circle at 12% 0%, {fond_clair_tint1}, transparent 45%),
    radial-gradient(circle at 88% 6%, {fond_clair_tint2}, transparent 45%),
    linear-gradient(135deg, {c['couleur_fond_clair']}, {c['couleur_fond_clair_2']}) !important;
  background-attachment:fixed !important;
}}
/* 🆕 Fond des CARTES en dégradé fondu (mode clair), couleur personnalisable par l'admin.
   Appliqué à TOUTES les cartes de l'appli (pas seulement .card générique). */
{selecteurs_cartes_clair}{{
  background:
    radial-gradient(circle at 15% 0%, {carte_clair_tint1}, transparent 55%),
    radial-gradient(circle at 90% 100%, {carte_clair_tint2}, transparent 55%),
    linear-gradient(135deg, {c['couleur_carte_clair']}, {c['couleur_carte_clair_2']}) !important;
}}
/* 🆕 Couleur du texte à l'intérieur des cartes, indépendante de la couleur de texte
   générale. On surcharge TOUT le nuancier de gris (--text, --text-soft, --gray-400 à 900)
   dans le périmètre des cartes : tous les éléments internes qui utilisent ces variables
   héritent donc automatiquement de cette couleur, sans casser les accents codés en dur
   (badges, icônes...), et sans être affectés par la couleur de texte générale. */
{selecteurs_cartes_clair}{{
  --text:{nuance_cartetexte_clair['text']} !important; --text-soft:{nuance_cartetexte_clair['text-soft']} !important;
  --gray-400:{nuance_cartetexte_clair['gray-400']} !important; --gray-500:{nuance_cartetexte_clair['gray-500']} !important;
  --gray-600:{nuance_cartetexte_clair['gray-600']} !important; --gray-700:{nuance_cartetexte_clair['gray-700']} !important;
  --gray-800:{nuance_cartetexte_clair['gray-800']} !important; --gray-900:{nuance_cartetexte_clair['gray-900']} !important;
  color:{c['couleur_cartetexte_clair']} !important;
}}
html.theme-neon{{
  --text:{nuance_texte_neon['text']} !important; --text-soft:{nuance_texte_neon['text-soft']} !important;
  --gray-400:{nuance_texte_neon['gray-400']} !important; --gray-500:{nuance_texte_neon['gray-500']} !important;
  --gray-600:{nuance_texte_neon['gray-600']} !important; --gray-700:{nuance_texte_neon['gray-700']} !important;
  --gray-800:{nuance_texte_neon['gray-800']} !important; --gray-900:{nuance_texte_neon['gray-900']} !important;
  --surface:{c['couleur_carte_neon']} !important;
  --primary:{c['couleur_onglet_neon']} !important; --primary-mid:{c['couleur_onglet_neon']} !important;
  --bg:{c['couleur_fond_neon']} !important;
}}
html.theme-neon .nav-link.active{{ background:{onglet_neon_12} !important; border-left-color:{c['couleur_onglet_neon']} !important; }}
html.theme-neon .sidebar-nav .nav-link.active .icon{{ color:{c['couleur_onglet_neon']} !important; }}
/* 🆕 Couleur des liens de navigation (sidebar) en mode néon, indépendante du texte général. */
html.theme-neon .nav-link{{ color:{c['couleur_navlink_neon']} !important; }}
html.theme-neon .nav-link:hover{{ color:{c['couleur_navlink_neon']} !important; }}
html.theme-neon .sidebar-nav .nav-link .icon{{ color:{c['couleur_navlink_neon']} !important; }}
/* 🆕 Couleur des boutons en mode néon, indépendante de la couleur des onglets. */
html.theme-neon .btn-primary{{ background:{c['couleur_bouton_neon']} !important; color:#07070C !important; box-shadow:none !important; }}
/* 🆕 Même principe en mode néon : fondu dégradé, couleur de base personnalisable. */
html.theme-neon body, html.theme-neon .content{{
  background:
    radial-gradient(circle at 12% 0%, {fond_neon_tint1}, transparent 45%),
    radial-gradient(circle at 88% 6%, {fond_neon_tint2}, transparent 45%),
    linear-gradient(135deg, {c['couleur_fond_neon']}, {c['couleur_fond_neon_2']}) !important;
  background-attachment:fixed !important;
}}
/* 🆕 Fond des CARTES en dégradé fondu (mode néon), couleur personnalisable par l'admin.
   Appliqué à TOUTES les cartes de l'appli (pas seulement .card générique). */
{selecteurs_cartes_neon}{{
  background:
    radial-gradient(circle at 15% 0%, {carte_neon_tint1}, transparent 55%),
    radial-gradient(circle at 90% 100%, {carte_neon_tint2}, transparent 55%),
    linear-gradient(135deg, {c['couleur_carte_neon']}, {c['couleur_carte_neon_2']}) !important;
}}
/* 🆕 Couleur du texte à l'intérieur des cartes en mode néon, indépendante du texte général
   (nuancier complet, comme en mode clair). */
{selecteurs_cartes_neon}{{
  --text:{nuance_cartetexte_neon['text']} !important; --text-soft:{nuance_cartetexte_neon['text-soft']} !important;
  --gray-400:{nuance_cartetexte_neon['gray-400']} !important; --gray-500:{nuance_cartetexte_neon['gray-500']} !important;
  --gray-600:{nuance_cartetexte_neon['gray-600']} !important; --gray-700:{nuance_cartetexte_neon['gray-700']} !important;
  --gray-800:{nuance_cartetexte_neon['gray-800']} !important; --gray-900:{nuance_cartetexte_neon['gray-900']} !important;
  color:{c['couleur_cartetexte_neon']} !important;
}}
</style>"""


def luxe_3d_style_html():
    """🆕 Construit le <style> qui donne à TOUTE l'application des mouvements en 3D et un
    rendu "lux" (cartes qui basculent légèrement en profondeur au survol, boutons avec reflet
    lumineux et effet de levée, liens de menu qui glissent en 3D, modales qui apparaissent en
    profondeur, contenu de page qui monte en fondu à l'ouverture). Injecté par nav_html() sur
    chaque page, donc appliqué automatiquement partout sans dépendre d'un fichier séparé.
    Respecte prefers-reduced-motion pour l'accessibilité."""
    return """<style>
:root{ --ease-luxe:cubic-bezier(.19,1,.22,1); --ease-luxe-soft:cubic-bezier(.16,1,.3,1); }

/* 🆕 Cartes : la pulsation de zoom est maintenant gérée par Framer Motion (JS),
   voir motionZoomCards() plus bas — ici on garde juste l'ombre de profondeur au survol.
   Les cartes contenant un graphique/courbe (canvas Chart.js) sont exclues côté JS. */
.card{ will-change:transform; }
.card:hover{
  box-shadow:0 20px 25px -5px rgba(0,0,0,.1), 0 8px 10px -6px rgba(0,0,0,.1) !important;
  z-index:2;
}
html.theme-neon .card:hover{
  box-shadow:0 22px 45px -12px rgba(0,229,255,.20), 0 0 0 1px rgba(0,229,255,.16) !important;
}

/* 🆕 Boutons : levée 3D + reflet lumineux "lux" qui traverse au survol */
.btn{
  position:relative; overflow:hidden;
  transition:transform .3s var(--ease-luxe-soft), box-shadow .3s var(--ease-luxe-soft) !important;
}
.btn::after{
  content:''; position:absolute; top:0; left:-60%; width:35%; height:100%;
  background:linear-gradient(120deg, transparent, rgba(255,255,255,.55), transparent);
  transform:skewX(-20deg); transition:left .65s var(--ease-luxe); pointer-events:none;
}
.btn:hover::after{ left:130%; }
.btn:hover{ transform:perspective(600px) translateY(-3px) scale(1.025) !important; }
.btn:active{ transform:translateY(0) scale(.97) !important; transition-duration:.1s !important; }

/* 🆕 Liens du menu : glissement en 3D au survol */
.nav-link{ transition:transform .3s var(--ease-luxe-soft), background .3s var(--ease-luxe-soft) !important; }
.nav-link:hover{ transform:perspective(500px) translateX(4px) rotateY(-3deg); }

/* 🆕 Modales : apparition en profondeur */
.modal{ animation:luxeModalIn .5s var(--ease-luxe-soft); }
@keyframes luxeModalIn{
  from{ opacity:0; transform:perspective(1000px) translateY(24px) rotateX(6deg) scale(.96); }
  to{ opacity:1; transform:perspective(1000px) translateY(0) rotateX(0) scale(1); }
}

/* 🆕 Avatars, badges, icônes de cycle : petit pop 3D au survol */
.badge{ transition:transform .25s var(--ease-luxe-soft); }
.badge:hover{ transform:translateY(-2px) scale(1.05); }

/* 🆕 Contenu de page : montée en fondu à l'ouverture de chaque page */
.content{ animation:luxeContentIn .5s var(--ease-luxe-soft); }
@keyframes luxeContentIn{
  from{ opacity:0; transform:perspective(800px) translateY(14px) rotateX(2deg); }
  to{ opacity:1; transform:none; }
}

/* 🆕 Lignes de tableau : légère élévation au survol */
table tbody tr{ transition:transform .25s var(--ease-luxe-soft), box-shadow .25s var(--ease-luxe-soft); }
table tbody tr:hover{ transform:translateX(2px); box-shadow:0 4px 14px -8px rgba(0,0,0,.18); position:relative; z-index:1; }

@media (prefers-reduced-motion: reduce){
  .card, .btn, .btn::after, .nav-link, table tbody tr, .modal, .content{
    animation:none !important; transition:none !important; transform:none !important;
  }
}
</style>"""


import html as _html_nom
NOM_ECOLE_DEFAUT = "ETABLISSEMENT PAUL GAUGUIN"
NOM_ECOLE_AR_DEFAUT = "مؤسسة بول غوغان"


def _lire_nom_ecole_brut():
    # (nom, nom_ar) tels que stockés ('' si non renseignés)
    try:
        conn = get_db()
        try:
            r = conn.execute("SELECT nom_ecole, nom_ecole_ar FROM parametres_ecole WHERE id=1").fetchone()
        finally:
            conn.close()
        if r:
            return (r['nom_ecole'] or '').strip(), (r['nom_ecole_ar'] or '').strip()
    except Exception:
        pass
    return '', ''


def get_nom_ecole():
    # Nom de l'école affiché partout (menu, titres, PDF, notifications, messages WhatsApp...)
    return _lire_nom_ecole_brut()[0] or NOM_ECOLE_DEFAUT


def get_nom_ecole_ar():
    # Nom pour les messages en arabe : version arabe saisie ; sinon le nom de l'école
    # (l'ancien nom arabe par défaut n'est gardé que tant que le nom n'a pas été modifié).
    nom, nom_ar = _lire_nom_ecole_brut()
    if nom_ar:
        return nom_ar
    if not nom or nom.upper() == NOM_ECOLE_DEFAUT:
        return NOM_ECOLE_AR_DEFAUT
    return nom


def get_nom_ecole_court():
    # Nom court pour l'icône de l'application : sans le mot de tête « Établissement / École », 14 caractères max
    import re as _re
    complet = get_nom_ecole()
    n = _re.sub(r'^(?:[ÉE]tablissement|[ÉE]cole|Coll[èe]ge|Lyc[ée]e|Groupe scolaire)\s+', '', complet, flags=_re.I).strip() or complet
    return n if len(n) <= 14 else n[:14].rstrip()


def _nom_ecole_html():
    return _html_nom.escape(get_nom_ecole())


def get_ecole_coords(conn):
    """Retourne l'adresse/coordonnées de référence de l'école (point de départ des chauffeurs)."""
    row = conn.execute("SELECT adresse, latitude, longitude FROM parametres_ecole WHERE id=1").fetchone()
    if row:
        return {'adresse': row['adresse'], 'lat': row['latitude'], 'lon': row['longitude']}
    return {'adresse': '', 'lat': None, 'lon': None}


def distance_km(lat1, lon1, lat2, lon2):
    """Distance à vol d'oiseau (formule de haversine), en kilomètres."""
    from math import radians, sin, cos, sqrt, atan2
    r = 6371.0
    phi1, phi2 = radians(lat1), radians(lat2)
    dphi = radians(lat2 - lat1)
    dlambda = radians(lon2 - lon1)
    a = sin(dphi / 2) ** 2 + cos(phi1) * cos(phi2) * sin(dlambda / 2) ** 2
    return 2 * r * atan2(sqrt(a), sqrt(1 - a))


def parser_datetime_sqlite(valeur):
    """🆕 Parse un horodatage tel que stocké par SQLite (CURRENT_TIMESTAMP ou
    datetime.now()), avec ou sans microsecondes. Retourne un objet datetime, ou None si
    la valeur est vide/invalide. Centralise un motif de parsing déjà dupliqué ailleurs
    dans le fichier (ex: suivi_chauffeurs)."""
    if not valeur:
        return None
    for fmt in ('%Y-%m-%d %H:%M:%S.%f', '%Y-%m-%d %H:%M:%S'):
        try:
            return datetime.datetime.strptime(valeur, fmt)
        except ValueError:
            continue
    return None


# 🆕 Seuil de détection "arrivée chez l'élève" pour le suivi chauffeur en direct (admin) :
# quand la position GPS du chauffeur passe sous cette distance de l'adresse d'un élève,
# on considère qu'il est arrivé chez cet élève (marqueur qui change de couleur + notification).
ARRIVEE_ELEVE_SEUIL_KM = 0.15  # 150 mètres


def ordonner_trajet_ramassage(ecole_lat, ecole_lon, eleves):
    """
    Ordonne les élèves (liste de dicts avec 'lat'/'lon') pour un trajet de ramassage scolaire :
    1) on part TOUJOURS de l'élève le PLUS ÉLOIGNÉ de l'école (1er ramassage),
    2) on termine TOUJOURS par l'élève le PLUS PROCHE de l'école (dernier ramassage, juste avant le retour),
    3) entre les deux, à chaque étape, on enchaîne vers l'élève non visité le PLUS PROCHE du point courant
       (sans jamais choisir l'élève le plus proche de l'école tant qu'il en reste d'autres à ramasser).
    Retourne la liste réordonnée, avec pour chaque élève sa distance (km) par rapport à l'école.
    """
    restants = [dict(e) for e in eleves]
    if not restants:
        return []
    for e in restants:
        e['distance_ecole_km'] = round(distance_km(ecole_lat, ecole_lon, e['lat'], e['lon']), 2)

    if len(restants) == 1:
        return restants

    # 🏁 L'élève le plus proche de l'école est réservé pour la toute dernière étape.
    restants.sort(key=lambda e: e['distance_ecole_km'])
    dernier = restants.pop(0)

    # 🚩 Parmi les élèves restants, on démarre par le plus éloigné de l'école.
    restants.sort(key=lambda e: -e['distance_ecole_km'])
    ordre = [restants.pop(0)]
    courant = ordre[0]
    while restants:
        restants.sort(key=lambda e: distance_km(courant['lat'], courant['lon'], e['lat'], e['lon']))
        suivant = restants.pop(0)
        ordre.append(suivant)
        courant = suivant

    # 🏁 On ajoute enfin l'élève le plus proche de l'école, en dernière position.
    ordre.append(dernier)
    return ordre


def distance_totale_trajet_km(ecole_lat, ecole_lon, eleves_ordonnes):
    """
    Calcule la distance RÉELLE totale du trajet complet du chauffeur (à vol d'oiseau) :
    École ➝ élève le plus éloigné (1er ramassage) ➝ ... ➝ élève le plus proche ➝ retour à l'École.
    `eleves_ordonnes` doit déjà être dans l'ordre de ramassage (sortie de ordonner_trajet_ramassage).
    Retourne un float arrondi en km, ou None si le calcul n'est pas possible.
    """
    if not eleves_ordonnes or ecole_lat is None or ecole_lon is None:
        return None

    total = 0.0
    point_precedent = (ecole_lat, ecole_lon)
    # École ➝ 1er élève, puis élève ➝ élève suivant, dans l'ordre de ramassage
    for e in eleves_ordonnes:
        total += distance_km(point_precedent[0], point_precedent[1], e['lat'], e['lon'])
        point_precedent = (e['lat'], e['lon'])
    # Dernier élève ➝ retour à l'école
    total += distance_km(point_precedent[0], point_precedent[1], ecole_lat, ecole_lon)

    return round(total, 1)


def construire_donnees_trajet_chauffeur(chauffeur_id, conn):
    """
    Construit les données du trajet de ramassage d'un chauffeur (élèves assignés,
    élèves localisés/ordonnés pour la carte, distance totale estimée). Utilisé à la
    fois par la fiche admin du chauffeur et par l'espace personnel du chauffeur.
    """
    eleves_assignes = conn.execute("""
                                    SELECT e.id, e.nom, e.prenom, e.transport_abonne, e.adresse as eleve_adresse,
                                           e.latitude, e.longitude, t.ordre,
                                           c.nom as classe_nom, c.niveau as classe_niveau,
                                           u.adresse as parent_adresse, u.telephone as parent_telephone,
                                           e.contact_urgence_tel as eleve_telephone_urgence,
                                           u.prenom || ' ' || u.nom as parent_nom
                                    FROM transport_eleves t
                                             JOIN eleves e ON t.eleve_id = e.id
                                             LEFT JOIN classes c ON e.classe_id = c.id
                                             LEFT JOIN users u ON e.parent_id = u.id
                                    WHERE t.chauffeur_id = ?
                                      AND COALESCE(e.statut_sortie, '') <> 'sortant_annee'
                                    ORDER BY CASE WHEN t.ordre IS NULL THEN 1 ELSE 0 END, t.ordre, c.niveau, c.nom, e.nom
                                    """, (chauffeur_id,)).fetchall()

    ecole = get_ecole_coords(conn)

    eleves_localises = [
        {
            'id': e['id'],
            'nom': f"{e['prenom']} {e['nom']}",
            'adresse': e['eleve_adresse'] or e['parent_adresse'] or '',
            'lat': e['latitude'],
            'lon': e['longitude'],
            'ordre': e['ordre'],  # 🆕 numéro de classement fixé par l'admin (à afficher tel quel côté accompagnatrice)
            # 🆕 Champs complémentaires (classe, contact parent) pour l'affichage de la liste
            # ordonnée (élève le plus éloigné en premier), utilisés à la fois par la fiche
            # admin du chauffeur et par l'espace personnel du chauffeur.
            'classe_nom': e['classe_nom'],
            'classe_niveau': e['classe_niveau'],
            'parent_nom': e['parent_nom'],
            'parent_telephone': e['parent_telephone'],
            # 🆕 Numéro affiché aux chauffeurs/accompagnatrices : le contact d'urgence de
            # l'élève (renseigné sur sa fiche) plutôt que le numéro du parent — voir
            # ESPACE_CHAUFFEUR_HTML, qui utilise désormais ce champ à la place de
            # parent_telephone pour l'affichage.
            'telephone_urgence': e['eleve_telephone_urgence'],
        }
        for e in eleves_assignes if e['latitude'] is not None and e['longitude'] is not None
    ]

    ecole_localisee = ecole['lat'] is not None and ecole['lon'] is not None
    if ecole_localisee:
        eleves_carte = ordonner_trajet_ramassage(ecole['lat'], ecole['lon'], eleves_localises)
    else:
        eleves_carte = eleves_localises

    distance_totale_trajet = None
    if ecole_localisee and eleves_carte:
        distance_totale_trajet = distance_totale_trajet_km(ecole['lat'], ecole['lon'], eleves_carte)

    return {
        'eleves_assignes': eleves_assignes,
        'eleves_carte': eleves_carte,
        'ecole': ecole,
        'ecole_localisee': ecole_localisee,
        'distance_totale_trajet': distance_totale_trajet,
    }


# 🆕 Score de performance du chauffeur — calculé UNIQUEMENT à partir de données réellement
# enregistrées (trajets GPS, conformité du permis). Aucune donnée n'est inventée : un critère
# sans donnée disponible (ex : pas de date de permis renseignée) est simplement exclu du calcul,
# et le total est ramené sur 100 en fonction des critères réellement disponibles.
def calculer_score_chauffeur(chauffeur_id, conn):
    p = conn.execute("SELECT * FROM personnel_hors_prof WHERE id=?", (chauffeur_id,)).fetchone()
    if not p:
        return None

    criteres = []  # (label, points_obtenus, points_max, detail)
    aujourdhui = datetime.date.today()

    # 1) Activité récente : jours distincts avec au moins un trajet enregistré sur 30 jours
    jours_actifs = conn.execute(
        "SELECT COUNT(DISTINCT date_trajet) FROM chauffeur_trajets "
        "WHERE chauffeur_id=? AND date_trajet >= date('now','-30 days')",
        (chauffeur_id,)
    ).fetchone()[0]
    pts_activite = round(min(jours_actifs, 20) / 20 * 40, 1)
    criteres.append(('Activité (30 derniers jours)', pts_activite, 40, f"{jours_actifs} jour(s) avec trajet enregistré"))

    # 2) Expérience : volume total de trajets réalisés (plafonné à 150)
    nb_trajets = conn.execute(
        "SELECT COUNT(*) FROM chauffeur_trajets WHERE chauffeur_id=?", (chauffeur_id,)
    ).fetchone()[0]
    pts_volume = round(min(nb_trajets, 150) / 150 * 30, 1)
    criteres.append(('Expérience (trajets réalisés)', pts_volume, 30, f"{nb_trajets} trajet(s) enregistré(s) au total"))

    # 3) Conformité du permis — seulement si une date d'expiration a été renseignée
    permis_expire = False
    if p['permis_expiration']:
        try:
            exp = datetime.datetime.strptime(p['permis_expiration'], '%Y-%m-%d').date()
        except ValueError:
            exp = None
        if exp:
            jours_restants = (exp - aujourdhui).days
            if jours_restants < 0:
                pts_permis, detail, permis_expire = 0, 'Permis expiré', True
            elif jours_restants < 30:
                pts_permis, detail = 10, f"Permis expire dans {jours_restants} j"
            else:
                pts_permis, detail = 30, f"Permis valide (expire le {p['permis_expiration']})"
            criteres.append(('Conformité du permis', pts_permis, 30, detail))

    max_total = sum(c[2] for c in criteres)
    if max_total == 0:
        return {'score': None, 'badge': 'Non évalué', 'emoji': '⚪', 'criteres': [], 'donnees_suffisantes': False}

    obtenu_total = sum(c[1] for c in criteres)
    score = round(obtenu_total / max_total * 100)

    if score >= 85:
        badge, emoji = 'Chauffeur Excellence', '🏆'
    elif score >= 70:
        badge, emoji = 'Chauffeur Fiable', '🟢'
    elif score >= 50:
        badge, emoji = 'Chauffeur Régulier', '🔵'
    elif score >= 30:
        badge, emoji = 'À surveiller', '🟡'
    else:
        badge, emoji = 'Performance faible', '🟠'

    if permis_expire:
        badge, emoji = 'Priorité sécurité', '🔴'

    return {
        'score': score, 'badge': badge, 'emoji': emoji,
        'criteres': criteres, 'donnees_suffisantes': True,
    }


def parser_coordonnees_ou_lien(texte):
    """
    Détecte si le texte saisi dans le champ "Adresse" est en réalité des coordonnées GPS
    ou un lien OpenStreetMap, et retourne (lat, lon) si c'est le cas, sinon (None, None).
    Formats reconnus :
      - Lien OSM  : https://www.openstreetmap.org/#map=18/34.0066014/-5.0066006
      - Lien OSM  : https://www.openstreetmap.org/?mlat=34.0066014&mlon=-5.0066006
      - Coordonnées format FR (virgule décimale) : 34,0066014 ; -5,0066006
      - Coordonnées format international (point décimal) : 34.0066014, -5.0066006  /  34.0066014 -5.0066006
    """
    if not texte:
        return None, None
    t = texte.strip()

    # Lien OSM : .../#map=zoom/lat/lon
    m = re.search(r'#map=\d+/(-?\d+\.\d+)/(-?\d+\.\d+)', t)
    if m:
        return float(m.group(1)), float(m.group(2))

    # Lien OSM : ...?mlat=..&mlon=..
    m = re.search(r'mlat=(-?\d+\.\d+)[^0-9\-]+mlon=(-?\d+\.\d+)', t)
    if m:
        return float(m.group(1)), float(m.group(2))

    # Coordonnées "34,0066014 ; -5,0066006" (virgule décimale FR, séparées par un point-virgule)
    m = re.match(r'^\s*(-?\d+),(\d+)\s*[;]\s*(-?\d+),(\d+)\s*$', t)
    if m:
        try:
            lat = float(f"{m.group(1)}.{m.group(2)}")
            lon = float(f"{m.group(3)}.{m.group(4)}")
            if -90 <= lat <= 90 and -180 <= lon <= 180:
                return lat, lon
        except ValueError:
            pass

    # Coordonnées "34.0066014, -5.0066006" ou "34.0066014 -5.0066006" (point décimal)
    m = re.match(r'^\s*(-?\d+\.\d+)\s*[,;\s]\s*(-?\d+\.\d+)\s*$', t)
    if m:
        try:
            lat, lon = float(m.group(1)), float(m.group(2))
            if -90 <= lat <= 90 and -180 <= lon <= 180:
                return lat, lon
        except ValueError:
            pass

    return None, None


def geocoder_adresse(adresse):
    """
    Convertit une adresse (texte, coordonnées GPS ou lien OpenStreetMap) en (lat, lon).
    - Si l'utilisateur a directement collé des coordonnées ou un lien OSM, elles sont utilisées
      telles quelles, sans appel réseau (plus rapide et plus précis).
    - Sinon, l'adresse texte est géocodée via Nominatim (OpenStreetMap). Respecte la politique
      d'usage de Nominatim (User-Agent identifié, 1 requête/seconde max gérée par l'appelant
      via time.sleep).
    Retourne (lat, lon) ou (None, None).
    """
    if not adresse or not adresse.strip():
        return None, None

    lat, lon = parser_coordonnees_ou_lien(adresse)
    if lat is not None and lon is not None:
        return lat, lon

    try:
        resp = requests.get(
            "https://nominatim.openstreetmap.org/search",
            params={"q": adresse, "format": "json", "limit": 1},
            headers={"User-Agent": "EcoleApp/1.0 (gestion-scolaire ; transport-eleves)"},
            timeout=8
        )
        data = resp.json()
        if data:
            return float(data[0]["lat"]), float(data[0]["lon"])
    except Exception:
        pass
    return None, None


# ─── NOUVEAU : index pour accélérer la page élève et toutes les pages liées ────
def upgrade_db_indexes():
    if not os.path.exists(DB_PATH): return
    conn = get_db()
    index_defs = [
        ("idx_eleves_classe_id", "eleves(classe_id)"),
        ("idx_eleves_parent_id", "eleves(parent_id)"),
        ("idx_eleves_nom_prenom", "eleves(nom, prenom)"),
        ("idx_eleves_sexe", "eleves(sexe)"),
        ("idx_notes_eleve_id", "notes(eleve_id)"),
        ("idx_notes_eleve_trimestre", "notes(eleve_id, trimestre)"),
        ("idx_notes_matiere_id", "notes(matiere_id)"),
        ("idx_absences_eleve_id", "absences(eleve_id)"),
        ("idx_retards_eleve_id", "retards(eleve_id)"),
        ("idx_paiements_eleve_id", "paiements(eleve_id)"),
        ("idx_matieres_classe_id", "matieres(classe_id)"),
        ("idx_classes_cycle", "classes(cycle)"),
        ("idx_classe_profs_classe_id", "classe_profs(classe_id)"),
    ]
    for idx_name, target in index_defs:
        try:
            conn.execute(f"CREATE INDEX IF NOT EXISTS {idx_name} ON {target}")
        except sqlite3.OperationalError:
            pass  # Table pas encore créée ou index déjà existant
    conn.commit()
    conn.close()


upgrade_db_indexes()


