def jours_ouvrables_mois(mois):
    """🆕 Nombre de jours ouvrables (lundi → vendredi, hors samedi et dimanche) d'un mois 'YYYY-MM'."""
    import calendar as _cal
    try:
        annee, m = int(mois[:4]), int(mois[5:7])
        nb_jours = _cal.monthrange(annee, m)[1]
    except (ValueError, TypeError, IndexError):
        return 0
    return sum(1 for j in range(1, nb_jours + 1) if datetime.date(annee, m, j).weekday() < 5)


def jours_absence_enseignant(conn, enseignant_id, mois):
    """🆕 Nombre de JOURS d'absence d'un enseignant sur un mois 'YYYY-MM', d'après la table
    absences_enseignants (page Absences → Enseignants). Plusieurs créneaux le même jour comptent
    pour 1 seul jour ; les samedis/dimanches ne sont pas des jours ouvrables, donc ignorés."""
    if not enseignant_id or not mois:
        return 0
    try:
        rows = conn.execute(
            "SELECT DISTINCT date_absence FROM absences_enseignants "
            "WHERE enseignant_id=? AND strftime('%Y-%m', date_absence)=?",
            (enseignant_id, mois[:7])).fetchall()
    except sqlite3.OperationalError:
        return 0
    nb = 0
    for r in rows:
        try:
            if datetime.date.fromisoformat(str(r[0])[:10]).weekday() < 5:
                nb += 1
        except ValueError:
            continue
    return nb


def calcul_paie_mensuelle(salaire, jours_ouvrables, jours_absence):
    """🆕 (salaire / jours ouvrables) = montant par jour ; montant par jour × (jours ouvrables − absences) = paie."""
    if not jours_ouvrables:
        return 0.0, round(float(salaire or 0), 2)
    par_jour = float(salaire or 0) / jours_ouvrables
    jours_payes = max(jours_ouvrables - max(jours_absence, 0), 0)
    return round(par_jour, 2), round(par_jour * jours_payes, 2)


