def _normaliser_budget_paie(valeur):
    """Budget d'une paie enseignant / personnel : 'Scolarité' (défaut), "Frais d'inscription"
    ou 'Autre facture'. Accepte aussi les codes courts scol / ins / autre."""
    v = (valeur or '').strip()
    codes = {'scol': 'Scolarité', 'ins': "Frais d'inscription", 'autre': 'Autre facture'}
    if v in codes:
        return codes[v]
    if v in ("Frais d'inscription", 'Autre facture'):
        return v
    if v == 'Autre':
        return 'Autre facture'
    return 'Scolarité'


