    upgrade_db_telephone()
    upgrade_db_charges()
    upgrade_db_traces()
    upgrade_db_personnel_hors_prof()
    upgrade_db_paiements_personnel_hors_prof()
    upgrade_db_paiement_transport_reduction()
    upgrade_db_transport_eleves()
    upgrade_db_transport_eleves_ordre()
    upgrade_db_transport_absences()
    upgrade_db_transport_presences_confirmees()
    upgrade_db_transport_absences_creneau()
    upgrade_db_absences_seances()
    upgrade_db_absences_enseignants_creneaux()
    upgrade_db_paiements_enseignants_absences()
    upgrade_db_paiements_personnel_absences()
    upgrade_db_chauffeur_compte()
    upgrade_db_chauffeur_trajets()
    upgrade_db_transport_notif_arrivee()
    upgrade_db_trajets_positions()
    upgrade_db_accompagnatrice_lien()
