def hash_pw(pw): return hashlib.sha256(pw.encode()).hexdigest()


# ─── WhatsApp SANS API : construction d'un lien wa.me ────────────
def lien_whatsapp(telephone, message):
    """
    Construit un lien https://wa.me/... qui ouvre WhatsApp Web (ou l'appli)
    avec le numéro et le message déjà pré-remplis. Aucune API, aucun token :
    c'est l'utilisateur qui clique ensuite sur "Envoyer" dans WhatsApp.
    telephone : numéro international, avec ou sans '+', espaces ou tirets.
    """
    import urllib.parse
    numero = ''.join(ch for ch in (telephone or '') if ch.isdigit())
    texte = urllib.parse.quote(message or '')
    return f"https://wa.me/{numero}?text={texte}"


# 🆕 Rendu disponible dans tous les templates Jinja (boutons d'action rapide WhatsApp)
app.jinja_env.globals['lien_whatsapp'] = lien_whatsapp




# ─── [ANCIEN] WhatsApp : envoi d'un message texte via API Meta ──
# Conservé mais non utilisé par les pages admin : l'appli n'utilise plus
# l'API WhatsApp Business, tout passe désormais par des liens wa.me
# (voir lien_whatsapp ci-dessus) ouverts dans le navigateur.
def envoyer_whatsapp(telephone, message):
    """
    Envoie un message WhatsApp via Meta Business API.
    telephone : numéro international sans '+' ex: '212612345678'
    Retourne (True, '') en succès ou (False, erreur) en échec.
    """
    if not telephone or not telephone.strip():
        return False, "Numéro de téléphone manquant"
    if WA_TOKEN == 'VOTRE_TOKEN_ICI':
        return False, "WA_TOKEN non configuré"

    # Nettoyage du numéro : retire +, espaces, tirets
    numero = telephone.strip().replace('+', '').replace(' ', '').replace('-', '')

    payload = {
        "messaging_product": "whatsapp",
        "to": numero,
        "type": "text",
        "text": {"body": message}
    }
    headers = {
        "Authorization": f"Bearer {WA_TOKEN}",
        "Content-Type": "application/json"
    }
    try:
        resp = requests.post(WA_API_URL, json=payload, headers=headers, timeout=10)
        data = resp.json()
        if resp.status_code == 200 and 'messages' in data:
            return True, data['messages'][0].get('id', '')
        else:
            erreur = data.get('error', {}).get('message', str(data))
            return False, erreur
    except Exception as e:
        return False, str(e)


# ─── WhatsApp : envoi d'un fichier (document/image) ─────────────
def envoyer_whatsapp_fichier(telephone, filepath, filename, caption=''):
    """
    Envoie un fichier (PDF, Word, Excel, image...) via WhatsApp Business API.
    Étape 1 : upload du fichier vers les serveurs Meta -> media_id
    Étape 2 : envoi du message référençant ce media_id
    Retourne (True, '') en succès ou (False, erreur) en échec.
    """
    if not telephone or not telephone.strip():
        return False, "Numéro de téléphone manquant"
    if WA_TOKEN == 'VOTRE_TOKEN_ICI':
        return False, "WA_TOKEN non configuré"
    if not os.path.exists(filepath):
        return False, "Fichier introuvable"

    numero = telephone.strip().replace('+', '').replace(' ', '').replace('-', '')
    mime_type, _ = mimetypes.guess_type(filename)
    mime_type = mime_type or 'application/octet-stream'
    # Les images jpeg/png bénéficient du type "image" (aperçu dans la conversation),
    # tous les autres formats (pdf, docx, xlsx...) passent en type "document"
    wa_type = 'image' if mime_type in ('image/jpeg', 'image/png') else 'document'

    # Étape 1 : upload du média
    try:
        with open(filepath, 'rb') as f:
            files = {'file': (filename, f, mime_type)}
            data = {'messaging_product': 'whatsapp', 'type': mime_type}
            headers_upload = {"Authorization": f"Bearer {WA_TOKEN}"}
            resp_up = requests.post(WA_MEDIA_URL, headers=headers_upload, files=files, data=data, timeout=30)
        media_data = resp_up.json()
        if resp_up.status_code != 200 or 'id' not in media_data:
            erreur = media_data.get('error', {}).get('message', str(media_data))
            return False, f"Échec de l'envoi du fichier : {erreur}"
        media_id = media_data['id']
    except Exception as e:
        return False, f"Erreur d'envoi du fichier : {e}"

    # Étape 2 : envoi du message avec le média
    contenu = {"id": media_id}
    if wa_type == 'document':
        contenu['filename'] = filename
    if caption:
        contenu['caption'] = caption

    payload = {
        "messaging_product": "whatsapp",
        "to": numero,
        "type": wa_type,
        wa_type: contenu
    }
    headers = {
        "Authorization": f"Bearer {WA_TOKEN}",
        "Content-Type": "application/json"
    }
    try:
        resp = requests.post(WA_API_URL, json=payload, headers=headers, timeout=15)
        data = resp.json()
        if resp.status_code == 200 and 'messages' in data:
            return True, data['messages'][0].get('id', '')
        else:
            erreur = data.get('error', {}).get('message', str(data))
            return False, erreur
    except Exception as e:
        return False, str(e)


# ─── 🆕 Historique des relances WhatsApp (combien de fois un parent a été relancé) ─────
def _assurer_table_relances_wa(conn):
    conn.execute("""
        CREATE TABLE IF NOT EXISTS relances_whatsapp (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            parent_id INTEGER NOT NULL,
            lot_id TEXT,
            langue TEXT,
            user_id INTEGER,
            date_relance DATETIME DEFAULT CURRENT_TIMESTAMP
        )""")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_relances_wa_parent ON relances_whatsapp(parent_id)")
    # 🆕 Type de facture visé par la relance ('' / NULL = relance générale, tous types confondus)
    if 'type_facture' not in [r[1] for r in conn.execute("PRAGMA table_info(relances_whatsapp)").fetchall()]:
        conn.execute("ALTER TABLE relances_whatsapp ADD COLUMN type_facture TEXT")


def _wa_il_y_a(dt_str):
    """'2026-10-20 14:03:11' (UTC, CURRENT_TIMESTAMP de SQLite) → 'il y a 15 min' / 'il y a 3 h' / 'il y a 2 j'."""
    try:
        t = datetime.datetime.strptime(str(dt_str)[:19], '%Y-%m-%d %H:%M:%S')
    except Exception:
        return ''
    sec = (datetime.datetime.now(datetime.timezone.utc).replace(tzinfo=None) - t).total_seconds()
    if sec < 0:
        sec = 0
    if sec < 60:
        return "à l'instant"
    if sec < 3600:
        return f"il y a {int(sec // 60)} min"
    if sec < 86400:
        return f"il y a {int(sec // 3600)} h"
    return f"il y a {int(sec // 86400)} j"


def _relances_wa_resume(conn, parent_id=None, type_facture=None):
    """{parent_id: {'n': nombre de relances, 'derniere': 'JJ/MM/AAAA'}}.
    🆕 type_facture : ne compte que les relances de ce type (+ les relances générales, qui couvraient
    tous les types).
    🆕 Une relance = UNE JOURNÉE : qu'un parent soit relancé 1 ou 10 fois dans la même journée
    (même plusieurs envois), il n'est compté qu'UNE fois pour ce jour-là."""
    _assurer_table_relances_wa(conn)
    sql = ("SELECT parent_id, COUNT(DISTINCT date(date_relance, 'localtime')) AS n, MAX(date_relance) AS d "
           "FROM relances_whatsapp")
    params = []
    conds = []
    if parent_id:
        conds.append("parent_id = ?")
        params.append(parent_id)
    if type_facture:
        conds.append("(type_facture = ? OR type_facture IS NULL OR type_facture = '')")
        params.append(type_facture)
    if conds:
        sql += " WHERE " + " AND ".join(conds)
    sql += " GROUP BY parent_id"
    return {r['parent_id']: {'n': r['n'], 'derniere': _wa_date(r['d']), 'depuis': _wa_il_y_a(r['d'])}
            for r in conn.execute(sql, params).fetchall()}


# ─── 🙏 Remerciement aux parents relancés qui ont payé rapidement (≤ 3 jours après la relance) ───────
WA_MERCI_DELAI_JOURS = 3      # un paiement reçu au plus tard 3 jours après la relance = « payé rapidement »
WA_MERCI_FENETRE_JOURS = 60   # on n'affiche que les paiements rapides des 60 derniers jours


def _assurer_table_remerciements_wa(conn):
    conn.execute("""
        CREATE TABLE IF NOT EXISTS remerciements_whatsapp (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            parent_id INTEGER NOT NULL,
            relance_jour TEXT NOT NULL,
            user_id INTEGER,
            date_envoi DATETIME DEFAULT CURRENT_TIMESTAMP,
            UNIQUE (parent_id, relance_jour)
        )""")


def _relances_payees_vite(conn, parent_id=None, relance_jour=None):
    """Parents relancés (WhatsApp) qui ont payé dans les WA_MERCI_DELAI_JOURS jours suivant la relance.
    Lecture seule. Chaque versement (journal `versements_paiements`, une ligne par somme réellement
    reçue avec sa date) est rattaché à la relance la PLUS RÉCENTE qui le précède de 0 à 3 jours (dates
    calendaires : un paiement le jour même de la relance compte). Une ligne = un parent + un jour de relance,
    avec la somme des versements de cette fenêtre. Retourne une liste triée du plus récent au plus ancien."""
    _assurer_table_relances_wa(conn)
    _assurer_table_remerciements_wa(conn)
    try:
        _assurer_table_versements(conn)
        synchroniser_versements(conn)
        conn.commit()
    except Exception as ex_sync:
        print(f"  ⚠️  remerciements WhatsApp : synchro des versements impossible : {ex_sync}")

    def _jour(s):
        try:
            return datetime.datetime.strptime(str(s)[:10], '%Y-%m-%d').date()
        except (TypeError, ValueError):
            return None

    q_rel = ("SELECT parent_id, date(date_relance, 'localtime') AS jour FROM relances_whatsapp "
             "WHERE date_relance IS NOT NULL")
    p_rel = []
    if parent_id:
        q_rel += " AND parent_id = ?"
        p_rel.append(parent_id)
    q_rel += " GROUP BY parent_id, jour"
    relances = {}
    for r in conn.execute(q_rel, p_rel).fetchall():
        d = _jour(r['jour'])
        if d:
            relances.setdefault(r['parent_id'], []).append(d)
    if not relances:
        return []
    for lst in relances.values():
        lst.sort()

    q_ver = ("SELECT e.parent_id AS parent_id, v.montant AS montant, v.date_versement AS dv, "
             "       e.prenom || ' ' || e.nom AS enfant "
             "FROM versements_paiements v "
             "JOIN paiements p ON p.id = v.paiement_id "
             "JOIN eleves e ON e.id = p.eleve_id "
             "WHERE e.parent_id IS NOT NULL AND v.montant > 0")
    p_ver = []
    if parent_id:
        q_ver += " AND e.parent_id = ?"
        p_ver.append(parent_id)
    groupes = {}
    for v in conn.execute(q_ver, p_ver).fetchall():
        rels = relances.get(v['parent_id'])
        dv = _jour(v['dv'])
        if not rels or not dv:
            continue
        precedentes = [d for d in rels if d <= dv]
        if not precedentes:
            continue
        rj = precedentes[-1]                      # relance la plus récente avant (ou le jour de) ce paiement
        delai = (dv - rj).days
        if delai > WA_MERCI_DELAI_JOURS:
            continue
        g = groupes.setdefault((v['parent_id'], rj), {'montant': 0.0, 'enfants': [], 'premier': dv, 'dernier': dv})
        g['montant'] += float(v['montant'])
        if v['enfant'] and v['enfant'] not in g['enfants']:
            g['enfants'].append(v['enfant'])
        g['premier'] = min(g['premier'], dv)
        g['dernier'] = max(g['dernier'], dv)
    if not groupes:
        return []

    limite = datetime.date.today() - datetime.timedelta(days=WA_MERCI_FENETRE_JOURS)
    ids = sorted({k[0] for k in groupes})
    marques = ",".join("?" * len(ids))
    infos = {u['id']: u for u in conn.execute(
        f"SELECT id, nom, prenom, telephone FROM users WHERE role='parent' AND id IN ({marques})", ids).fetchall()}
    merci = {(m['parent_id'], m['relance_jour']): m['date_envoi'] for m in conn.execute(
        f"SELECT parent_id, relance_jour, date_envoi FROM remerciements_whatsapp WHERE parent_id IN ({marques})", ids).fetchall()}
    out = []
    for (pid, rj), g in groupes.items():
        u = infos.get(pid)
        if not u or g['dernier'] < limite:
            continue
        if relance_jour and rj.isoformat() != relance_jour:
            continue
        delai = (g['premier'] - rj).days
        envoye = merci.get((pid, rj.isoformat()))
        out.append({
            'parent_id': pid,
            'nom': f"{u['prenom'] or ''} {u['nom'] or ''}".strip(),
            'telephone': u['telephone'] or '',
            'enfants': ", ".join(g['enfants']),
            'relance_jour': rj.isoformat(),
            'relance_txt': rj.strftime('%d/%m/%Y'),
            'paiement_jour': g['dernier'].isoformat(),
            'paiement_txt': g['dernier'].strftime('%d/%m/%Y'),
            'delai': delai,
            'delai_txt': "le jour même" if delai == 0 else f"{delai} jour{'s' if delai > 1 else ''} après",
            'montant': round(g['montant'], 2),
            'remercie': bool(envoye),
            'remercie_txt': _wa_date(str(envoye)[:10]) if envoye else '',
        })
    out.sort(key=lambda x: (x['paiement_jour'], x['nom']), reverse=True)
    return out


def _wa_msg_remerciement(lang, parent, enfants, montant, date_paiement):
    """Message de remerciement après un paiement reçu rapidement suite à une relance."""
    pour_fr = f" pour votre enfant *{enfants}*" if enfants else ""
    pour_ar = f" عن التلميذ(ة) *{enfants}*" if enfants else ""
    fr = (
        f"🏫 *{get_nom_ecole()}*\n"
        f"_Remerciements_\n\n"
        f"Bonjour {parent},\n\n"
        f"Nous avons bien reçu votre règlement de *{_wa_montant(montant)} MAD* le {date_paiement}{pour_fr}, "
        f"et nous vous en remercions sincèrement. 🙏\n\n"
        f"Votre réactivité et votre confiance sont très appréciées : elles nous aident à offrir "
        f"le meilleur accompagnement à votre enfant.\n\n"
        f"Nous restons à votre entière disposition pour toute question.\n\n"
        f"Cordialement,\n"
        f"_L'Administration_"
    )
    ar = (
        f"🏫 *{get_nom_ecole_ar()}*\n"
        f"_شكر وتقدير_\n\n"
        f"السلام عليكم ورحمة الله،\n"
        f"السيد(ة) *{parent}* المحترم(ة)،\n\n"
        f"لقد توصلنا بأدائكم بمبلغ *{_wa_montant_ar(montant)} درهم* بتاريخ {date_paiement}{pour_ar}، "
        f"ونشكركم جزيل الشكر على ذلك. 🙏\n\n"
        f"نقدّر كثيراً سرعة استجابتكم وثقتكم بنا، فهي تساعدنا على توفير أفضل متابعة لأبنائكم.\n\n"
        f"ونبقى رهن إشارتكم لأي استفسار.\n\n"
        f"وتفضلوا بقبول فائق الاحترام والتقدير،\n"
        f"_الإدارة_"
    )
    return _wa_assembler(lang, fr, ar)


# ─── Messages WhatsApp aux parents : ton professionnel et chaleureux, FR / AR ──────────
NOTIF_ECOLE_NOM_AR = "مؤسسة بول غوغان"   # nom de l'établissement dans les messages en arabe
_WA_LANGUES = ('fr', 'ar', 'both')
_WA_SEPARATEUR = "\n\n──────────\n\n"
_WA_MOIS_FR = ['Janvier', 'Février', 'Mars', 'Avril', 'Mai', 'Juin', 'Juillet',
               'Août', 'Septembre', 'Octobre', 'Novembre', 'Décembre']
_WA_MOIS_AR = ['يناير', 'فبراير', 'مارس', 'أبريل', 'ماي', 'يونيو', 'يوليوز',
               'غشت', 'شتنبر', 'أكتوبر', 'نونبر', 'دجنبر']


def _mois_fr_label(ym):
    """'2026-10' → 'Octobre 2026'."""
    try:
        return f"{_WA_MOIS_FR[int(ym[5:7]) - 1]} {ym[:4]}"
    except Exception:
        return ym or ''


def _wa_langue(lang):
    lang = (lang or '').strip().lower()
    return lang if lang in _WA_LANGUES else 'both'


def _wa_float(v):
    """Nombre > 0 saisi par l'utilisateur (virgule acceptée) ou None."""
    try:
        x = float(str(v).replace(' ', '').replace('\u00a0', '').replace(',', '.'))
        return x if x > 0 else None
    except Exception:
        return None


def _wa_montant(v):
    """1500 → '1 500.00' (espace insécable : le montant ne se coupe jamais en fin de ligne)."""
    try:
        return f"{float(v):,.2f}".replace(',', '\u00a0')
    except Exception:
        return str(v)


def _wa_montant_ar(v):
    """Montant pour le bloc ARABE : même chiffres que le français (1 000.00), mais isolé en LTR
    (LRE ... PDF) pour que le texte arabe (RTL) ne casse / n'inverse pas le nombre."""
    return "\u202a" + _wa_montant(v) + "\u202c"


def _wa_date(d):
    """YYYY-MM-DD → JJ/MM/AAAA (sinon texte tel quel)."""
    try:
        return datetime.datetime.strptime(str(d)[:10], '%Y-%m-%d').strftime('%d/%m/%Y')
    except Exception:
        return d or ''


def _wa_designation_sans_reduction(description):
    # La description enregistrée sur la facture contient parfois le détail de la réduction
    # appliquée (ex : "Mensualité Scolarité (Réduction 20% appliquée)"). Ce détail est utile en
    # interne mais ne doit pas apparaître dans le message envoyé au parent : celui-ci ne doit voir
    # que le montant à payer, pas le pourcentage ou le montant de la remise dont il bénéficie.
    texte = re.sub(r'\s*\(Réduction[^)]*\)', '', description or 'Mensualité').strip()
    return texte or 'Mensualité'


def _wa_designation_ar(description):
    """Traduit les désignations courantes en arabe ; sinon garde le texte d'origine."""
    d = _wa_designation_sans_reduction(description)
    bas = d.lower()
    base = None
    if 'mensualit' in bas:
        if 'transport' in bas:
            base = 'الواجب الشهري و النقل المدرسي'
        elif 'cantine' in bas:
            base = 'الواجب الشهري للمطعم المدرسي'
        else:
            base = 'الواجب الشهري للتمدرس'
    elif 'inscription' in bas:
        base = 'واجب التسجيل'
    elif 'transport' in bas:
        base = 'واجب النقل المدرسي'
    elif 'cantine' in bas:
        base = 'واجب المطعم المدرسي'
    elif 'assurance' in bas:
        base = 'واجب التأمين'
    elif 'fourniture' in bas or 'livre' in bas:
        base = 'اللوازم المدرسية'
    if not base:
        return d
    m = re.search(r'(janvier|f[ée]vrier|mars|avril|mai|juin|juillet|ao[uû]t|septembre|octobre|novembre|d[ée]cembre)\s*(\d{4})?', bas)
    if m:
        noms = ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre']
        mot = m.group(1).replace('é', 'e').replace('û', 'u')
        for idx, nom in enumerate(noms):
            if nom.replace('é', 'e').replace('û', 'u') == mot:
                base += f" ({_WA_MOIS_AR[idx]}{' ' + m.group(2) if m.group(2) else ''})"
                break
    return base


def _wa_assembler(lang, bloc_fr, bloc_ar):
    lang = _wa_langue(lang)
    if lang == 'fr':
        return bloc_fr
    if lang == 'ar':
        return bloc_ar
    return bloc_fr + _WA_SEPARATEUR + bloc_ar


def _wa_msg_rappel(lang, parent, eleve, designation_brute, reste, echeance):
    """Rappel pour UNE facture."""
    ech = _wa_date(echeance)
    fr = (
        f"🏫 *{get_nom_ecole()}*\n"
        f"_Rappel de paiement_\n\n"
        f"Bonjour {parent},\n\n"
        f"Nous espérons que vous et votre famille allez bien.\n\n"
        f"Nous nous permettons de vous adresser un rappel amical concernant un règlement "
        f"en attente pour votre enfant *{eleve}* :\n\n"
        f"▫️ Désignation : {_wa_designation_sans_reduction(designation_brute)}\n"
        f"▫️ Échéance : {ech or 'non précisée'}\n"
        f"▫️ Montant restant : *{_wa_montant(reste)} MAD*\n\n"
        f"Si ce règlement a déjà été effectué, nous vous prions de ne pas tenir compte de ce message "
        f"et de bien vouloir nous en excuser.\n\n"
        f"Pour toute question, notre équipe reste à votre entière disposition. 🙏\n\n"
        f"Cordialement,\n"
        f"_L'Administration_"
    )
    ar = (
        f"🏫 *{get_nom_ecole_ar()}*\n"
        f"_تذكير بالأداء_\n\n"
        f"السلام عليكم ورحمة الله،\n"
        f"السيد(ة) *{parent}* المحترم(ة)،\n\n"
        f"نأمل أن تكونوا وأسرتكم الكريمة بخير.\n\n"
        f"نتقدم إليكم بتذكير ودّي بخصوص مبلغ مستحق الأداء عن التلميذ(ة) *{eleve}* :\n\n"
        f"▫️ البيان : {_wa_designation_ar(designation_brute)}\n"
        f"▫️ تاريخ الاستحقاق : {ech or 'غير محدد'}\n"
        f"▫️ المبلغ المتبقي : *{_wa_montant_ar(reste)} درهم*\n\n"
        f"إذا سبق لكم أداء هذا المبلغ، المرجو عدم الاعتداد بهذه الرسالة مع اعتذارنا.\n\n"
        f"لأي استفسار، فريق الإدارة رهن إشارتكم. 🙏\n\n"
        f"وتفضلوا بقبول فائق الاحترام والتقدير،\n"
        f"_الإدارة_"
    )
    return _wa_assembler(lang, fr, ar)


def _wa_msg_rappel_tout(lang, parent, nb, groupes, total):
    """Récapitulatif de TOUTES les factures en attente d'un parent (regroupées par enfant).
    groupes = [(nom_eleve, [(ligne_sql, reste), ...]), ...]"""
    corps_fr, corps_ar, n = [], [], 0
    for eleve, items in groupes:
        corps_fr.append(f"👦 *{eleve}*")
        corps_ar.append(f"👦 *{eleve}*")
        for row, reste in items:
            n += 1
            ech = _wa_date(row['date_echeance'])
            ligne_fr = (f"{n}. {_wa_designation_sans_reduction(row['description'])} — échéance "
                        f"{ech or 'non précisée'} — reste *{_wa_montant(reste)} MAD*")
            ligne_ar = (f"{n}. {_wa_designation_ar(row['description'])} — الاستحقاق "
                        f"{ech or 'غير محدد'} — المتبقي *{_wa_montant_ar(reste)} درهم*")
            if row['montant_paye']:
                ligne_fr += f" (déjà réglé : {_wa_montant(row['montant_paye'])} MAD)"
                ligne_ar += f" (سبق أداء : {_wa_montant_ar(row['montant_paye'])} درهم)"
            corps_fr.append(ligne_fr)
            corps_ar.append(ligne_ar)
        corps_fr.append("")
        corps_ar.append("")
    fr = (
        f"🏫 *{get_nom_ecole()}*\n"
        f"_Rappel de paiement_\n\n"
        f"Bonjour {parent},\n\n"
        f"Nous espérons que vous et votre famille allez bien.\n\n"
        f"Nous vous adressons le récapitulatif des règlements en attente ({nb} factures) :\n\n"
        + "\n".join(corps_fr) +
        f"\n▫️ *Total restant à régler ( Pour année scolaire 2026-2027): {_wa_montant(total)} MAD*\n\n"
        f"Si certains de ces règlements ont déjà été effectués, nous vous prions de ne pas tenir compte "
        f"de ce message et de bien vouloir nous en excuser.\n\n"
        f"Pour toute question, notre équipe reste à votre entière disposition. 🙏\n\n"
        f"Cordialement,\n"
        f"_L'Administration_"
    )
    ar = (
        f"🏫 *{get_nom_ecole_ar()}*\n"
        f"_تذكير بالأداء_\n\n"
        f"السلام عليكم ورحمة الله،\n"
        f"السيد(ة) *{parent}* المحترم(ة)،\n\n"
        f"نأمل أن تكونوا وأسرتكم الكريمة بخير.\n\n"
        f"نتقدم إليكم بملخص المبالغ المستحقة الأداء (عدد الفواتير : {nb}) :\n\n"
        + "\n".join(corps_ar) +
        f"\n▫️ *إجمالي المبلغ المتبقي : {_wa_montant_ar(total)} درهم*\n\n"
        f"إذا سبق لكم أداء بعض هذه المبالغ، المرجو عدم الاعتداد بهذه الرسالة مع اعتذارنا.\n\n"
        f"لأي استفسار، فريق الإدارة رهن إشارتكم. 🙏\n\n"
        f"وتفضلوا بقبول فائق الاحترام والتقدير،\n"
        f"_الإدارة_"
    )
    return _wa_assembler(lang, fr, ar)


def _wa_msg_test(lang, parent):
    """Premier message de VÉRIFICATION : confirme que le numéro est le bon, sans rien divulguer
    (ni enfant, ni montant) au cas où le numéro appartiendrait à quelqu'un d'autre."""
    fr = (
        f"🏫 *{get_nom_ecole()}*\n"
        f"_Message de vérification_\n\n"
        f"Bonjour,\n\n"
        f"Nous souhaitons nous assurer que ce numéro est bien celui de *{parent}*.\n\n"
        f"Si c'est le cas, merci de répondre simplement par *OK* à ce message. 🙏\n\n"
        f"Si vous n'êtes pas la personne concernée, nous vous prions de bien vouloir nous excuser pour ce dérangement.\n\n"
        f"Cordialement,\n"
        f"_L'Administration_"
    )
    ar = (
        f"🏫 *{get_nom_ecole_ar()}*\n"
        f"_رسالة تحقق_\n\n"
        f"السلام عليكم ورحمة الله،\n\n"
        f"نود التأكد من أن هذا الرقم هو فعلاً رقم السيد(ة) *{parent}*.\n\n"
        f"إن كان الأمر كذلك، المرجو الرد على هذه الرسالة بكلمة *OK*. 🙏\n\n"
        f"وإن لم تكونوا الشخص المعني، نعتذر عن هذا الإزعاج.\n\n"
        f"مع خالص التقدير،\n"
        f"_الإدارة_"
    )
    return _wa_assembler(lang, fr, ar)


def _wa_where_impayes(classe_id=None, cycle=None, statut=None, mois=None, type_facture=None):
    """Clauses SQL (alias p = paiements, e = eleves, c = classes) partagées par la page
    « Relances paiement » et par la file d'envoi : ce qui s'affiche est exactement ce qui est envoyé."""
    cl, pr = [], []
    if statut in ('non_paye', 'partiel'):
        cl.append("p.statut = ?")
        pr.append(statut)
    else:
        cl.append("p.statut IN ('non_paye', 'partiel')")
    try:
        cid = int(classe_id) if classe_id not in (None, '') else None
    except (TypeError, ValueError):
        cid = None
    cycle = (cycle or '').strip()
    if cid:
        cl.append("e.classe_id = ?")
        pr.append(cid)
    elif cycle:
        cl.append("c.cycle = ?")
        pr.append(cycle)
    mois = (mois or '').strip()
    if re.fullmatch(r'\d{4}-(0[1-9]|1[0-2])', mois):
        cl.append("substr(p.date_echeance, 1, 7) = ?")
        pr.append(mois)
    # 🆕 Type de facture (même logique que la page Paiements : la description commence par « [Type] »)
    type_facture = (type_facture or '').strip()
    if type_facture == 'Scolarité':
        cl.append("p.description LIKE '[Scolarité%'")   # inclut « [Scolarité + Transport] »
    elif type_facture == "Frais d'inscription":
        cl.append("p.description LIKE ?")
        pr.append("[Frais d'inscription]%")
    elif type_facture == 'Autre':
        # Tout ce qui n'est ni scolarité ni frais d'inscription (voyage, achat, service, sans type...)
        cl.append("(p.description IS NULL OR (p.description NOT LIKE '[Scolarité%' AND p.description NOT LIKE ?))")
        pr.append("[Frais d'inscription]%")
    # 💳 Facture entièrement couverte par un chèque en attente : pas de relance
    cl.append(f"NOT {_SQL_RESTE_COUVERT_CHEQUE}")
    return cl, pr


# ─── Construction des rappels impayés (SANS envoi, SANS API) ────
def construire_rappels_impayes(parent_id=None, lang='both', classe_id=None, cycle=None, statut=None,
                               mois=None, montant_min=None, type_facture=None):
    """
    Parcourt les élèves avec un paiement non_paye ou partiel et construit,
    pour chaque parent ayant un numéro renseigné, le message de rappel.
    Ne contacte AUCUNE API : retourne juste une liste prête pour l'assistant
    d'envoi WhatsApp Web (wa.me), qui ouvrira chaque conversation un par un.
    Si parent_id est fourni, ne construit le rappel que pour ce parent.
    🆕 lang ('fr' / 'ar' / 'both') : langue du message.
    🆕 classe_id / cycle / statut / mois (YYYY-MM d'échéance) / montant_min (reste dû minimum par
    parent) : ne relance que les factures qui correspondent à ces filtres.
    """
    lang = _wa_langue(lang)
    conn = get_db()
    try:
        _assurer_table_cheques(conn)
        cl, params = _wa_where_impayes(classe_id, cycle, statut, mois, type_facture)
        cl = cl + ["u.telephone IS NOT NULL", "u.telephone != ''"]
        query = f"""
                SELECT e.prenom || ' ' || e.nom AS eleve_nom,
                       p.montant_total,
                       p.montant_paye,
                       p.description,
                       p.date_echeance,
                       {_SQL_CHEQUES_ATTENTE} AS cheques_attente,
                       u.id                      AS parent_id,
                       TRIM(COALESCE(u.prenom, '') || ' ' || COALESCE(u.nom, '')) AS parent_nom,
                       u.telephone
                FROM paiements p
                         JOIN eleves e ON p.eleve_id = e.id
                         LEFT JOIN users u ON e.parent_id = u.id
                         LEFT JOIN classes c ON e.classe_id = c.id
                WHERE {' AND '.join(cl)}
                """
        if parent_id:
            query += " AND u.id = ?"
            params.append(parent_id)

        query += " ORDER BY u.id, e.id, p.date_echeance, p.id"
        impayes = conn.execute(query, params).fetchall()

        if montant_min:
            reste_parent = {}
            for r in impayes:
                reste_parent[r['parent_id']] = reste_parent.get(r['parent_id'], 0.0) + (r['montant_total'] - r['montant_paye'] - (r['cheques_attente'] or 0))
            impayes = [r for r in impayes if reste_parent[r['parent_id']] >= montant_min]

        def _libelle_facture(row, reste):
            return f"{row['description'] or 'Mensualité'} — {row['eleve_nom']} — reste {reste:.2f} MAD"

        queue = []
        par_parent = {}
        for row in impayes:
            reste = row['montant_total'] - row['montant_paye'] - (row['cheques_attente'] or 0)
            msg = _wa_msg_rappel(lang, row['parent_nom'], row['eleve_nom'], row['description'],
                                 reste, row['date_echeance'])
            item = {
                'parent_id': row['parent_id'],
                'nom': row['parent_nom'],
                'telephone': row['telephone'],
                'message': msg,
                'libelle': _libelle_facture(row, reste),
                'compter': True,
            }
            queue.append(item)
            par_parent.setdefault(row['parent_id'], []).append((row, reste))

        # 🆕 Rappel d'un seul parent ayant PLUSIEURS factures impayées : en plus d'une ligne
        # par facture (ci-dessus), on ajoute une ligne « TOUT » = un seul message qui donne le
        # total dû ET le détail facture par facture (regroupé par enfant).
        if parent_id and len(impayes) > 1:
            premiere = impayes[0]
            lignes = par_parent[premiere['parent_id']]
            total_general = sum(r for _, r in lignes)
            groupes = []
            for row, reste in lignes:
                if not groupes or groupes[-1][0] != row['eleve_nom']:
                    groupes.append((row['eleve_nom'], []))
                groupes[-1][1].append((row, reste))
            msg_tout = _wa_msg_rappel_tout(lang, premiere['parent_nom'], len(lignes), groupes, total_general)
            queue.append({
                'parent_id': premiere['parent_id'],
                'nom': premiere['parent_nom'],
                'telephone': premiere['telephone'],
                'message': msg_tout,
                'libelle': f"TOUT — {len(lignes)} factures — total {total_general:.2f} MAD",
                'tout': True,
                'compter': True,
            })
        return queue
    finally:
        conn.close()


def construire_message_test(parent_id, lang='both'):
    """🆕 Premier message « de test » pour un parent : vérifie que le numéro enregistré est le bon
    avant d'envoyer la vraie relance. Aucun montant, aucun nom d'enfant dans ce message."""
    lang = _wa_langue(lang)
    conn = get_db()
    try:
        u = conn.execute("SELECT id, nom, prenom, telephone FROM users WHERE id = ? AND role = 'parent'",
                         (parent_id,)).fetchone()
        if not u or not (u['telephone'] or '').strip():
            return []
        nom = f"{u['prenom'] or ''} {u['nom'] or ''}".strip()
        return [{
            'parent_id': u['id'],
            'nom': nom,
            'telephone': u['telephone'],
            'message': _wa_msg_test(lang, nom),
            'libelle': '🧪 Message de test — vérification du numéro',
        }]
    finally:
        conn.close()


