def _defaut_niveau(role, module_key):
    m = _MODULES_PAR_CLE.get(module_key)
    if not m or role not in AUTORISATION_ROLES_KEYS:
        return 'modification'
    return _LETTRE_NIVEAU[m['defaut'][AUTORISATION_ROLES_KEYS.index(role)]]


def upgrade_db_autorisations():
    """Crée la table des autorisations et la pré-remplit avec les droits actuels de chaque profil.
    Idempotent (INSERT OR IGNORE : ne jamais écraser un choix de l'admin). Rejoué après restauration."""
    if not os.path.exists(DB_PATH):
        return
    try:
        conn = get_db()
        try:
            conn.execute("""
                CREATE TABLE IF NOT EXISTS autorisations_roles (
                    role        TEXT NOT NULL,
                    module      TEXT NOT NULL,
                    niveau      TEXT NOT NULL CHECK (niveau IN ('aucun','lecture','modification')),
                    modifie_par INTEGER,
                    date_modif  DATETIME DEFAULT CURRENT_TIMESTAMP,
                    PRIMARY KEY (role, module)
                )""")
            for m in AUTORISATION_MODULES:
                for role in AUTORISATION_ROLES_KEYS:
                    conn.execute(
                        "INSERT OR IGNORE INTO autorisations_roles (role, module, niveau) VALUES (?,?,?)",
                        (role, m['key'], _defaut_niveau(role, m['key'])))
            conn.commit()
        finally:
            conn.close()
    except Exception as e:
        print(f"  ⚠️  Migration autorisations_roles a échoué : {e}")


upgrade_db_autorisations()

_AUTORISATIONS_CACHE = {'t': 0.0, 'data': None}


def _autorisations_courantes(force=False):
    """{(role, module): niveau}. Cache de 3 s (plusieurs workers Gunicorn) ; en cas d'erreur de
    lecture on retombe sur les valeurs par défaut = comportement historique de l'application."""
    import time as _t
    now = _t.time()
    if (not force) and _AUTORISATIONS_CACHE['data'] is not None and now - _AUTORISATIONS_CACHE['t'] < 3:
        return _AUTORISATIONS_CACHE['data']
    data = {(r, m['key']): _defaut_niveau(r, m['key'])
            for m in AUTORISATION_MODULES for r in AUTORISATION_ROLES_KEYS}
    try:
        conn = get_db()
        try:
            rows = conn.execute("SELECT role, module, niveau FROM autorisations_roles").fetchall()
        finally:
            conn.close()
        for row in rows:
            cle = (row['role'], row['module'])
            if cle in data and row['niveau'] in AUTORISATION_NIVEAUX:
                data[cle] = row['niveau']
    except Exception:
        pass
    _AUTORISATIONS_CACHE['data'] = data
    _AUTORISATIONS_CACHE['t'] = now
    return data


def niveau_autorisation(role, module_key):
    """'aucun' | 'lecture' | 'modification'. Admin (et rôles non gérés) : toujours 'modification'."""
    if role not in AUTORISATION_ROLES_KEYS or module_key not in _MODULES_PAR_CLE:
        return 'modification'
    return _autorisations_courantes().get((role, module_key), _defaut_niveau(role, module_key))


def role_reel():
    """Rôle réel de l'utilisateur connecté (même si, le temps d'une vue, on l'a élevé)."""
    return getattr(flask_g, 'role_reel', None) or session.get('role')


def peut_voir(module_key):
    """True si l'utilisateur connecté a au moins l'accès en lecture au module."""
    return niveau_autorisation(role_reel(), module_key) != 'aucun'


def peut_modifier(module_key):
    return niveau_autorisation(role_reel(), module_key) == 'modification'


def _role_elevation_autorisation(role, effective_roles):
    """Si l'admin a accordé à un professeur / une secrétaire PLUS que son niveau par défaut sur le
    module de la page demandée, renvoie le rôle sous lequel exécuter la vue (agent admin : mêmes
    écrans que l'agent admin, jamais ceux de l'admin). Sinon None (comportement habituel)."""
    if role not in ('enseignant', 'secretaire'):
        return None
    module_key = ENDPOINT_MODULE.get(request.endpoint)
    if not module_key:
        return None
    niveau = niveau_autorisation(role, module_key)
    if _RANG_NIVEAU[niveau] <= _RANG_NIVEAU[_defaut_niveau(role, module_key)]:
        return None
    return 'agent_admin' if 'agent_admin' in effective_roles else None


def _liens_nav_autorises(role):
    """Menu latéral : liens habituels du rôle, filtrés/complétés selon les autorisations."""
    base = list(NAV_LINKS.get(role, []))
    if role not in AUTORISATION_ROLES_KEYS:
        return base
    try:
        module_par_chemin = {m['nav'][2]: (m['key'], 'lecture') for m in AUTORISATION_MODULES if m.get('nav')}
        module_par_chemin.update(_NAV_LIENS_SUPPLEMENTAIRES)
        if role in ('agent_admin', 'secretaire'):
            module_par_chemin['/absences'] = ('absences_hub', 'lecture')  # /absences y redirige vers le hub
        resultat, chemins = [], set()
        for label, icon, path in base:
            ref = module_par_chemin.get(path)
            if ref and _RANG_NIVEAU[niveau_autorisation(role, ref[0])] < _RANG_NIVEAU[ref[1]]:
                continue
            resultat.append((label, icon, path))
            chemins.add(path)
        ajouts = []
        for m in AUTORISATION_MODULES:
            if not m.get('nav') or m['nav'][2] in chemins:
                continue
            if m.get('nav_roles') and role not in m['nav_roles']:
                continue
            if m['key'] == 'absences_hub' and '/absences' in chemins and role in ('agent_admin', 'secretaire'):
                continue  # pour eux, le lien « Absences » mène déjà au hub
            if niveau_autorisation(role, m['key']) != 'aucun':
                ajouts.append(m['nav'])
        if ajouts:
            idx = next((i for i, l in enumerate(resultat) if l[2] in ('/messages', '/notifications', '/profile')),
                       len(resultat))
            resultat[idx:idx] = ajouts
        return resultat
    except Exception:
        return base


def _accueil_secretaire():
    """Page d'arrivée de la secrétaire : son tableau de bord (toujours accessible)."""
    return url_for('dashboard_secretaire')


def _accueil_secretaire_ancien():
    """(ancien comportement, conservé) hub des absences si autorisé, sinon première page permise."""
    if niveau_autorisation('secretaire', 'absences_hub') != 'aucun':
        return url_for('absences_hub')
    hub_ok = False
    for label, icon, path in _liens_nav_autorises('secretaire'):
        if path in ('/dashboard', '/profile', '/messages', '/notifications'):
            continue
        if path == '/absences' and not hub_ok:
            continue  # cette page redirige vers le hub, refusé
        return path
    return '/profile'


# ─────────────────────────────────────────────
# AUTH DECORATORS
# ─────────────────────────────────────────────
def login_required(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'user_id' not in session:
            return redirect(url_for('login'))
        return f(*args, **kwargs)

    return decorated


def role_required(*roles):
    def decorator(f):
        @wraps(f)
        def decorated(*args, **kwargs):
            # 🆕 AGENT ADMIN : a globalement les mêmes accès qu'un admin, sauf exceptions
            # gérées explicitement à l'intérieur des vues concernées (paiements enseignants,
            # salariés hors prof, historique, modification des comptes utilisateurs).
            effective_roles = set(roles)
            if 'admin' in effective_roles:
                effective_roles.add('agent_admin')
            if session.get('role') not in effective_roles:
                # 🔐 Autorisation accordée par l'admin (page « Autorisation ») au-delà du niveau par
                # défaut du profil : la vue s'exécute le temps de la requête avec les écrans de
                # l'agent admin, puis le vrai rôle est toujours restauré.
                role_vrai = session.get('role')
                role_eleve = _role_elevation_autorisation(role_vrai, effective_roles)
                if role_eleve:
                    flask_g.role_reel = role_vrai
                    session['role'] = role_eleve
                    try:
                        return f(*args, **kwargs)
                    finally:
                        session['role'] = role_vrai
                flash('Accès non autorisé.', 'error')
                return redirect(url_for('dashboard'))
            return f(*args, **kwargs)

        return decorated

    return decorator


# ✅ Rôle "Agent Admin" : accès identique à l'admin, sauf pour les points listés ci-dessous.
AGENT_ADMIN_ROLE = 'agent_admin'


def is_admin_like(role=None):
    role = role or session.get('role')
    return role in ('admin', 'agent_admin')


# 🆕 SECRÉTAIRE : accès restreint à ses classes assignées (table classe_secretaires),
# selon le même principe que classe_profs pour les enseignants.
def _classes_assignees_role(conn, role, user_id):
    """Classes assignées à un enseignant (classe_profs) ou à un(e) secrétaire (classe_secretaires)."""
    table, col = ('classe_profs', 'enseignant_id') if role == 'enseignant' else ('classe_secretaires', 'secretaire_id')
    return conn.execute(
        f"SELECT c.*, (SELECT COUNT(*) FROM eleves e WHERE e.classe_id=c.id) as nb_eleves "
        f"FROM classes c WHERE EXISTS (SELECT 1 FROM {table} t WHERE t.classe_id=c.id AND t.{col}=?) "
        f"ORDER BY c.niveau, c.nom", (user_id,)).fetchall()


