# HELPER
# ─────────────────────────────────────────────
def get_notif_count():
    if 'user_id' not in session: return 0
    if session.get('role') in ('chauffeur', 'accompagnatrice'): return 0
    conn = get_db()
    if session.get('role') == 'enseignant':
        n = sum(1 for r in conn.execute("SELECT message, type FROM notifications WHERE user_id=? AND lu=0",
                                        (session['user_id'],)).fetchall()
                if categoriser_notification(r['message'], r['type']) not in NOTIF_CATS_MASQUEES_ENSEIGNANT)
    else:
        n = conn.execute("SELECT COUNT(*) FROM notifications WHERE user_id=? AND lu=0", (session['user_id'],)).fetchone()[0]
    # 🆕 Messages non lus (nouvelle messagerie v2) : messages reçus dont l'id dépasse le dernier
    # message lu par l'utilisateur dans chaque conversation où il participe.
    msg = conn.execute("""
        SELECT COUNT(*) FROM msg_messages mm
        JOIN msg_conversations c ON c.id = mm.conversation_id
        WHERE (c.user_a_id=? OR c.user_b_id=?) AND mm.expediteur_id != ?
          AND mm.id > COALESCE((SELECT dernier_lu_msg_id FROM msg_participant_etat pe
                                 WHERE pe.conversation_id=mm.conversation_id AND pe.user_id=?), 0)
    """, (session['user_id'], session['user_id'], session['user_id'], session['user_id'])).fetchone()[0]
    conn.close()
    return n + msg


# ═══════════════════════════════════════════════════════════════
# 🆕 NOTIFICATIONS PUSH (navigateur / téléphone) — Web Push standard
# Fonctionne pour tous les rôles (admin, agent_admin, enseignant, parent) : dès qu'une
# notification in-app est créée (nouveau message, devoir publié, communication publiée,
# demande de congé, etc.), on essaie aussi de réveiller le téléphone/l'ordinateur de
# l'utilisateur via une notification push, sur chaque appareil où il a donné son accord.
# ═══════════════════════════════════════════════════════════════
def upgrade_db_push():
    conn = get_db()
    conn.execute("""
        CREATE TABLE IF NOT EXISTS push_subscriptions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL REFERENCES users(id),
            endpoint TEXT NOT NULL UNIQUE,
            p256dh TEXT NOT NULL,
            auth TEXT NOT NULL,
            user_agent TEXT,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    """)
    conn.execute("CREATE INDEX IF NOT EXISTS idx_push_subscriptions_user ON push_subscriptions(user_id)")
    conn.commit()
    conn.close()


upgrade_db_push()


def upgrade_db_notifications_riches():
    """🆕 Colonnes optionnelles pour des notifications « riches » : titre court, lien direct
    (deep-link) et méta-données (icône, couleur, bouton d'action...). Les anciennes
    notifications (colonnes vides) continuent de s'afficher exactement comme avant."""
    try:
        conn = get_db()
    except Exception:
        return
    try:
        for col in ("titre TEXT", "url TEXT", "meta TEXT"):
            try:
                conn.execute(f"ALTER TABLE notifications ADD COLUMN {col}")
            except sqlite3.OperationalError:
                pass  # colonne déjà présente (ou table pas encore créée)
        conn.commit()
    except Exception as ex:
        print(f"  ⚠️  Migration notifications riches : {ex}")
    finally:
        conn.close()


upgrade_db_notifications_riches()


def _notif_icone_push():
    """URL du logo de l'école pour l'icône de la notification push (formats raster seulement :
    Android/iOS n'affichent pas les SVG dans les notifications)."""
    try:
        f = get_logo_filename()
        if f and f.rsplit('.', 1)[-1].lower() in ('png', 'jpg', 'jpeg', 'webp'):
            return '/logo-ecole'
    except Exception:
        pass
    return None


def envoyer_push_utilisateur(user_id, titre, corps, url='/notifications', extra=None):
    """Envoie une notification push à TOUS les appareils abonnés de cet utilisateur.
    Ne lève jamais d'exception vers l'appelant (n'importe quel souci réseau/abonnement
    expiré est avalé ici) : la création de la notification in-app ne doit jamais être
    bloquée ou cassée par un problème côté push."""
    if not user_id or not PYWEBPUSH_DISPONIBLE or not VAPID_PUBLIC_KEY_B64:
        return
    if not notifications_actives():  # 🆕 interrupteur admin
        return
    conn = get_db()
    try:
        abonnements = conn.execute(
            "SELECT * FROM push_subscriptions WHERE user_id=?", (user_id,)
        ).fetchall()
        if not abonnements:
            return
        donnees = {'titre': titre, 'corps': corps, 'url': url}
        if extra:
            donnees.update(extra)
        _icone = _notif_icone_push()
        if _icone:
            donnees.setdefault('icon', _icone)
            donnees.setdefault('badge', _icone)
        payload = json.dumps(donnees)
        # Notification importante (retard de paiement, devoir urgent...) : priorité haute côté serveur push
        _entetes = {'Urgency': 'high'} if (extra or {}).get('prio') == 'haute' else None
        a_supprimer = []
        for ab in abonnements:
            try:
                webpush(
                    subscription_info={
                        'endpoint': ab['endpoint'],
                        'keys': {'p256dh': ab['p256dh'], 'auth': ab['auth']},
                    },
                    data=payload,
                    vapid_private_key=VAPID_PRIVATE_KEY_FILE,
                    vapid_claims={'sub': VAPID_CLAIMS_EMAIL},
                    ttl=86400,
                    headers=_entetes,
                )
            except WebPushException as ex:
                code = None
                if getattr(ex, 'response', None) is not None:
                    code = ex.response.status_code
                if code in (404, 410):
                    # Abonnement expiré ou révoqué côté navigateur → on le supprime.
                    a_supprimer.append(ab['id'])
                else:
                    print(f"  ⚠️  Push non délivré (user {user_id}) : {ex}")
            except Exception as ex:
                print(f"  ⚠️  Erreur envoi push (user {user_id}) : {ex}")
        if a_supprimer:
            conn.executemany("DELETE FROM push_subscriptions WHERE id=?", [(i,) for i in a_supprimer])
            conn.commit()
    finally:
        conn.close()


def envoyer_push_utilisateur_async(user_id, titre, corps, url='/notifications', extra=None):
    """Version non-bloquante : l'envoi réseau vers les serveurs push (Google/Mozilla/
    Apple...) peut prendre plusieurs centaines de ms par appareil, donc on le fait dans
    un thread séparé pour ne jamais ralentir la réponse HTTP de la page en cours."""
    if not user_id or not PYWEBPUSH_DISPONIBLE or not VAPID_PUBLIC_KEY_B64:
        return
    if not notifications_actives():  # 🆕 interrupteur admin
        return
    threading.Thread(
        target=envoyer_push_utilisateur, args=(user_id, titre, corps, url, extra), daemon=True
    ).start()


def notifications_actives(conn=None):
    """True si l'admin a activé les notifications (par défaut : activées).
    Si la lecture échoue (colonne absente, base en cours de migration...), on renvoie True
    pour ne jamais casser le fonctionnement existant."""
    ouvert_ici = False
    try:
        if conn is None:
            conn = get_db()
            ouvert_ici = True
        row = conn.execute("SELECT notifications_actives FROM parametres_ecole WHERE id=1").fetchone()
        if row is None or row[0] is None:
            return True
        return bool(row[0])
    except Exception:
        return True
    finally:
        if ouvert_ici:
            try: conn.close()
            except Exception: pass


# ═══════════════════════════════════════════════════════════════
# 🆕 NOTIFICATIONS V2 (parents) : titre clair, message détaillé, icône/couleur par type,
# lien direct vers la bonne page, bouton d'action, priorité (retards, devoirs urgents),
# regroupement (un seul rappel par parent) et push enrichi (logo, vibration, boutons).
# `notif_to_parent(parent_id, msg, conn)` garde sa signature d'origine : tous les anciens
# appels continuent de fonctionner (catégorie / titre / lien déduits automatiquement).
# ═══════════════════════════════════════════════════════════════
NOTIF_ECOLE_NOM = "ETABLISSEMENT PAUL GAUGUIN"

NOTIF_STYLES = {
    'paiement':      {'ico': '💳', 'titre': 'Paiement',        'url': '/paiements',      'cta': 'Voir mes paiements',  'couleur': '#059669'},
    'devoir':        {'ico': '📚', 'titre': 'Devoirs',         'url': '/devoirs',        'cta': 'Voir le devoir',      'couleur': '#2563EB'},
    'communication': {'ico': '📢', 'titre': 'Communication',   'url': '/communications', 'cta': 'Lire',                'couleur': '#7C3AED'},
    'message':       {'ico': '💬', 'titre': 'Nouveau message', 'url': '/messages',       'cta': 'Répondre',            'couleur': '#DB2777'},
    'note':          {'ico': '📝', 'titre': 'Résultats',       'url': '/notifications',  'cta': 'Voir',                'couleur': '#F59E0B'},
    'autre':         {'ico': '🔔', 'titre': 'Vie scolaire',    'url': '/notifications',  'cta': 'Voir le détail',      'couleur': '#64748B'},
}
NOTIF_ABSENCE_KW = {'categorie': 'autre', 'titre': 'Absence signalée', 'prio': 'haute',
                    'meta': {'ico': '🗓️', 'couleur': '#F59E0B', 'cta': 'Voir le détail'}}

_NOTIF_EMOJI_DEBUT = re.compile(r"^[\s\u2190-\u2BFF\u2600-\u27BF\uFE0F\u200D\U0001F000-\U0001FAFF]+")
_NOTIF_JOURS_FR = ['lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi', 'dimanche']


def _notif_sans_emoji(txt):
    return _NOTIF_EMOJI_DEBUT.sub('', str(txt or '')).strip()


def _notif_liste_prenoms(noms):
    """['Sara'] → 'Sara' ; ['Sara','Adam'] → 'Sara et Adam' ; 3+ → 'Sara, Adam et Lina'."""
    vus = []
    for n in noms:
        n = str(n or '').strip()
        if n and n not in vus:
            vus.append(n)
    if len(vus) <= 1:
        return vus[0] if vus else ''
    return ', '.join(vus[:-1]) + ' et ' + vus[-1]


def _notif_fmt_date(d):
    """'2026-10-15' → '15/10/2026' (texte inchangé si le format est inattendu)."""
    try:
        return datetime.date.fromisoformat(str(d)[:10]).strftime('%d/%m/%Y')
    except Exception:
        return str(d or '')


def _notif_quand(date_str, heure=None):
    """Échéance en langage naturel : « aujourd'hui à 18:00 », « demain », « jeudi 15/10 »..."""
    try:
        d = datetime.date.fromisoformat(str(date_str)[:10])
    except Exception:
        return ''
    delta = (d - datetime.date.today()).days
    if delta == 0:
        base = "aujourd'hui"
    elif delta == 1:
        base = "demain"
    elif delta == -1:
        base = "hier"
    elif 1 < delta < 7:
        base = f"{_NOTIF_JOURS_FR[d.weekday()]} {d.strftime('%d/%m')}"
    else:
        base = f"le {d.strftime('%d/%m/%Y')}"
    if heure and heure != '23:59' and delta >= 0:
        base += f" à {heure}"
    return base


def _notif_extrait(texte, n=110):
    """Début lisible d'un texte (balises HTML retirées, espaces compactés)."""
    t = re.sub(r'<[^>]+>', ' ', str(texte or ''))
    t = re.sub(r'\s+', ' ', t).strip()
    return t if len(t) <= n else t[:n].rsplit(' ', 1)[0] + '…'


def notif_to_parent(parent_id, msg, conn, categorie=None, titre=None, url=None, meta=None,
                    prio='normale', tag=None, push_corps=None):
    # 🆕 Interrupteur admin : notifications désactivées → on ne crée rien et on n'envoie rien.
    if not (parent_id and notifications_actives(conn)):
        return
    cat = categorie if categorie in NOTIF_STYLES else categoriser_notification(msg)
    st = NOTIF_STYLES.get(cat, NOTIF_STYLES['autre'])
    meta = dict(meta or {})
    meta.setdefault('ico', st['ico'])
    meta.setdefault('couleur', st['couleur'])
    meta.setdefault('cta', st['cta'])
    if prio and prio != 'normale':
        meta['prio'] = prio
    titre_final = (titre or st['titre'])[:80]
    url_final = url or st['url']
    try:
        conn.execute(
            "INSERT INTO notifications (user_id,message,type,titre,url,meta) VALUES (?,?,?,?,?,?)",
            (parent_id, msg, cat, titre_final, url_final, json.dumps(meta, ensure_ascii=False)))
    except sqlite3.OperationalError:
        # Colonnes riches absentes (migration pas encore passée) : on retombe sur l'ancien format.
        conn.execute("INSERT INTO notifications (user_id,message,type) VALUES (?,?,'info')", (parent_id, msg))
    extra = {'prio': prio or 'normale', 'cta': meta['cta'], 'couleur': meta['couleur'], 'cat': cat}
    if tag:
        extra['tag'] = tag
    envoyer_push_utilisateur_async(parent_id, f"{meta['ico']} {titre_final}",
                                   push_corps or _notif_sans_emoji(msg), url_final, extra)


def notifier_paiement_confirme(conn, paiement_id, parent_id, eleve_nom):
    """Notification « paiement reçu » : élève, désignation et montant réglé."""
    desc, montant = 'Mensualité', 0
    try:
        p = conn.execute("SELECT description, montant_total, montant_paye FROM paiements WHERE id=?",
                         (paiement_id,)).fetchone()
        if p:
            desc = p['description'] or 'Mensualité'
            montant = p['montant_paye'] or p['montant_total'] or 0
    except Exception:
        pass
    msg = (f"✅ Paiement reçu pour {eleve_nom} — {desc}" + (f" : {montant:.2f} MAD" if montant else "")
           + ". Merci, tout est en règle !")
    notif_to_parent(parent_id, msg, conn, categorie='paiement', titre='Paiement reçu',
                    meta={'ico': '✅', 'cta': 'Voir mes paiements'}, tag=f"paiement-{paiement_id}")


# 🆕 NOTIFICATIONS PAR CATÉGORIE : paiement / devoir / communication / message / note / autre.
# La catégorie est déduite du texte de la notification (donc valable aussi pour l'historique
# existant, sans migration). Si la colonne `type` contient déjà une de ces clés, elle est utilisée.
NOTIF_CATEGORIES = [
    ('paiement',      'Paiements',      '💳', '#059669'),
    ('devoir',        'Devoirs',        '📚', '#2563EB'),
    ('communication', 'Communications', '📢', '#7C3AED'),
    ('message',       'Messages',       '💬', '#DB2777'),
    ('note',          'Notes',          '📝', '#F59E0B'),
    ('autre',         'Autres',         '🔔', '#64748B'),
]
_NOTIF_CAT_KEYS = [c[0] for c in NOTIF_CATEGORIES]
_NOTIF_REGLES = [
    ('message',       re.compile(r"^\W*💬|nouveau message|message transféré|message transfere", re.I)),
    ('communication', re.compile(r"communication|annonce|actualité|actualite", re.I)),
    ('devoir',        re.compile(r"devoir|^\W*rappel\s*:|à rendre|a rendre", re.I)),
    ('paiement',      re.compile(r"paiement|mensualit|facture|échéance|echeance|solde|règlement|reglement|frais", re.I)),
    ('note',          re.compile(r"\bnotes?\b|bulletin|moyenne|résultat|resultat", re.I)),
]

def categoriser_notification(message, type_=''):
    """Retourne la clé de catégorie d'une notification."""
    if type_ in _NOTIF_CAT_KEYS:
        return type_
    txt = str(message or '')
    for cle, rgx in _NOTIF_REGLES:
        if rgx.search(txt):
            return cle
    return 'autre'

# 🆕 Enseignant : les onglets Paiements / Devoirs / Notes n'existent pas dans ses notifications.
NOTIF_CATS_MASQUEES_ENSEIGNANT = ('paiement', 'devoir', 'note')


def notifs_avec_categorie(rows):
    out = []
    masquees = NOTIF_CATS_MASQUEES_ENSEIGNANT if session.get('role') == 'enseignant' else ()
    for r in rows:
        d = dict(r)
        d['categorie'] = categoriser_notification(d.get('message'), d.get('type'))
        if d['categorie'] in masquees:
            continue
        out.append(d)
    return out

def notifs_groupees(notifs):
    """Regroupe des notifications (déjà catégorisées) dans l'ordre d'affichage voulu."""
    groupes = []
    masquees = NOTIF_CATS_MASQUEES_ENSEIGNANT if session.get('role') == 'enseignant' else ()
    for cle, label, icone, couleur in NOTIF_CATEGORIES:
        if cle in masquees:
            continue
        items = [n for n in notifs if n['categorie'] == cle]
        groupes.append({'key': cle, 'label': label, 'icone': icone, 'color': couleur,
                        'liste': items, 'non_lues': sum(1 for n in items if not n.get('lu'))})
    return groupes


