# ✅ TRAÇABILITÉ : enregistre qui a fait quelle action, sur quoi, et quand.
# À appeler à chaque création/modification/suppression sensible (notes, paiements, etc.)
def log_action(conn, action, cible_type, cible_id=None, details='', classe_id=None, eleve_id=None):
    # 🆕 classe_id / eleve_id (facultatifs) : alimentent le filtre par classe du hub Historique.
    # Si absents, ils sont déduits automatiquement (paiement -> élève -> classe).
    try:
        if eleve_id is None and cible_type == 'paiement' and cible_id:
            _r = conn.execute("SELECT eleve_id FROM paiements WHERE id=?", (cible_id,)).fetchone()
            if _r:
                eleve_id = _r[0]
        if classe_id is None and eleve_id:
            _r = conn.execute("SELECT classe_id FROM eleves WHERE id=?", (eleve_id,)).fetchone()
            if _r:
                classe_id = _r[0]
    except Exception:
        pass
    _vals = (
        session.get('user_id'),
        session.get('nom_complet', ''),
        role_reel() or '',
        action,
        cible_type,
        cible_id,
        details,
    )
    try:
        conn.execute(
            "INSERT INTO historique_actions (user_id,user_nom,user_role,action,cible_type,cible_id,details,classe_id,eleve_id) "
            "VALUES (?,?,?,?,?,?,?,?,?)",
            _vals + (classe_id, eleve_id),
        )
    except Exception:
        try:
            conn.execute(
                "INSERT INTO historique_actions (user_id,user_nom,user_role,action,cible_type,cible_id,details) "
                "VALUES (?,?,?,?,?,?,?)",
                _vals,
            )
        except Exception:
            pass  # Le journal d'audit ne doit jamais faire échouer l'action principale


# 🆕 Helpers de traçabilité (hub Historique) : chacun ne doit JAMAIS faire échouer l'action principale.
def _trace_eleve_info(conn, eleve_id):
    """(nom complet, classe_id, nom de la classe) d'un élève."""
    r = conn.execute(
        "SELECT e.prenom, e.nom, e.classe_id, c.nom AS classe_nom FROM eleves e "
        "LEFT JOIN classes c ON c.id=e.classe_id WHERE e.id=?", (eleve_id,)).fetchone()
    if not r:
        return (f"#{eleve_id}", None, None)
    return (f"{r['prenom']} {r['nom']}", r['classe_id'], r['classe_nom'])


def _trace_classes_noms(conn, classes_ids):
    noms = []
    for cid in classes_ids or []:
        r = conn.execute("SELECT nom FROM classes WHERE id=?", (cid,)).fetchone()
        if r:
            noms.append(r['nom'])
    return ", ".join(noms)


def trace_note(conn, action, row, nouvelle=None, note_id=None, commentaire=''):
    """row : ligne de notes AVANT modification/suppression (ou dict eleve_id/matiere_id/trimestre/note)."""
    try:
        nom, cid, cnom = _trace_eleve_info(conn, row['eleve_id'])
        m = conn.execute("SELECT nom FROM matieres WHERE id=?", (row['matiere_id'],)).fetchone()
        mat = m['nom'] if m else '—'
        if action == 'creation':
            txt = f"Note {nouvelle} ajoutée"
        elif action == 'modification':
            txt = f"Note modifiée : {row['note']} → {nouvelle}"
        else:
            txt = f"Note supprimée (valeur : {row['note']})"
        det = (f"{txt} — Élève : {nom} — Classe : {cnom or '—'} — Matière : {mat} — "
               f"Trimestre : {row['trimestre']}")
        if commentaire:
            det += f" — Commentaire : {commentaire}"
        log_action(conn, action, 'note', note_id, det, classe_id=cid, eleve_id=row['eleve_id'])
    except Exception:
        pass


def trace_absence_eleve(conn, action, eleve_id, texte, motif='', absence_id=None):
    try:
        nom, cid, cnom = _trace_eleve_info(conn, eleve_id)
        det = f"{texte} — Élève : {nom} — Classe : {cnom or '—'}"
        if motif:
            det += f" — Motif : {motif}"
        log_action(conn, action, 'absence_eleve', absence_id, det, classe_id=cid, eleve_id=eleve_id)
    except Exception:
        pass


def trace_absence_prof(conn, action, enseignant_id, texte, motif='', absence_id=None):
    try:
        u = conn.execute("SELECT prenom, nom FROM users WHERE id=?", (enseignant_id,)).fetchone()
        nom = f"{u['prenom']} {u['nom']}" if u else f"#{enseignant_id}"
        det = f"{texte} — Enseignant : {nom}"
        if motif:
            det += f" — Motif : {motif}"
        log_action(conn, action, 'absence_enseignant', absence_id, det)
    except Exception:
        pass


def trace_absence_hub(conn, action, type_hub, row, texte, motif=''):
    """Trace une modification/suppression d'absence faite depuis l'historique des absences."""
    try:
        if type_hub == 'eleve':
            trace_absence_eleve(conn, action, row['eleve_id'], texte, motif, row['id'])
        elif type_hub == 'enseignant':
            trace_absence_prof(conn, action, row['enseignant_id'], texte, motif, row['id'])
    except Exception:
        pass


def trace_devoir(conn, action, devoir_id, texte, classes_ids=None, titre=None):
    try:
        if titre is None:
            d = conn.execute("SELECT titre FROM devoirs WHERE id=?", (devoir_id,)).fetchone()
            titre = d['titre'] if d else '—'
        if not classes_ids:
            classes_ids = [r['classe_id'] for r in conn.execute(
                "SELECT classe_id FROM devoir_classes WHERE devoir_id=?", (devoir_id,)).fetchall()]
            if not classes_ids:
                d = conn.execute("SELECT classe_id FROM devoirs WHERE id=?", (devoir_id,)).fetchone()
                classes_ids = [d['classe_id']] if d and d['classe_id'] else []
        noms = _trace_classes_noms(conn, classes_ids)
        det = f"{texte} — Devoir : « {titre} » — Classe(s) : {noms or '—'}"
        log_action(conn, action, 'devoir', devoir_id, det,
                   classe_id=int(classes_ids[0]) if classes_ids else None)
    except Exception:
        pass


# 🆕 TRAÇABILITÉ « Saisi par » — pour un lot de lignes (paiements élèves, paiements
# enseignants ou charges), renvoie {id: {'nom','role','date','action'}} donnant le DERNIER
# compte ayant créé ou modifié chaque ligne, d'après le journal d'audit (historique_actions).
# Alimente la colonne "Saisi par" des tableaux de paiements/charges ; le nom y est ensuite
# cliquable pour ouvrir (via /api/historique_ligne) la liste complète de tous les comptes
# ayant touché cette ligne, du plus récent au plus ancien.
def dernier_auteur_map(conn, cible_type, ids):
    ids = list({i for i in ids if i is not None})
    if not ids:
        return {}
    placeholders = ",".join("?" for _ in ids)
    rows = conn.execute(f"""
        SELECT h.cible_id, h.user_nom, h.user_role, h.action, h.date_action
        FROM historique_actions h
        INNER JOIN (
            SELECT cible_id, MAX(id) as max_id
            FROM historique_actions
            WHERE cible_type=? AND cible_id IN ({placeholders})
            GROUP BY cible_id
        ) dernier ON dernier.max_id = h.id
    """, [cible_type] + ids).fetchall()
    return {
        r['cible_id']: {
            'nom': r['user_nom'] or '—',
            'role': r['user_role'] or '',
            'date': r['date_action'],
            'action': r['action'],
        }
        for r in rows
    }


