@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        email = request.form.get('email', '').strip()
        pw = request.form.get('password', '')
        conn = get_db()
        user = conn.execute("SELECT * FROM users WHERE LOWER(email)=LOWER(?) AND password=?", (email, hash_pw(pw))).fetchone()
        if user:
            session.permanent = True
            session['user_id'] = user['id']
            # 🆕 Responsables de département (Marketing / Informatique / Commercial) : mêmes droits
            # et autorisations qu'un ADMIN -> la session les traite comme 'admin' ; le rôle réel
            # est conservé dans session['role_reel'] (affichage, organigramme).
            session['role_reel'] = user['role']
            session['role'] = 'admin' if user['role'] in ROLES_RESPONSABLES else user['role']
            session['nom_complet'] = f"{user['prenom']} {user['nom']}"
            conn.close()
            _act_connexion()  # 📊 registre d'activité
            return redirect(url_for('dashboard'))

        # 🆕 Comptes chauffeurs ET accompagnatrices (personnel_hors_prof avec mission
        # 'Chauffeur' ou 'Accompagnatrice' + accès activé) — même mécanique de connexion.
        transport_staff = conn.execute(
            "SELECT * FROM personnel_hors_prof WHERE mission IN ('Chauffeur','Accompagnatrice') AND LOWER(email)=LOWER(?) "
            "AND email IS NOT NULL AND email != '' AND password=?",
            (email, hash_pw(pw))
        ).fetchone()
        conn.close()
        if transport_staff:
            session.permanent = True
            session['user_id'] = transport_staff['id']
            session['role'] = 'chauffeur' if transport_staff['mission'] == 'Chauffeur' else 'accompagnatrice'
            session['nom_complet'] = f"{transport_staff['prenom']} {transport_staff['nom']}"
            _act_connexion()  # 📊 registre d'activité
            return redirect(url_for('espace_chauffeur'))

        _act_echec(email)  # 📊 registre d'activité
        flash('Email ou mot de passe incorrect.', 'error')
    # 🆕 Logo + bannière de l'école (mêmes images que celles gérées depuis le profil admin)
    # affichés sur la page de connexion si l'admin les a uploadés, sinon repli gracieux.
    logo_ecole_fn = get_logo_filename()
    banniere_ecole_fn = get_banniere_bulletin_filename()
    return render_template_string(
        LOGIN_HTML,
        a_logo_ecole=bool(logo_ecole_fn),
        a_banniere_ecole=bool(banniere_ecole_fn),
    )


@app.route('/logout')
def logout():
    _act_deconnexion()  # 📊 registre d'activité (avant d'effacer la session)
    session.clear()
    return redirect(url_for('login'))


