# DASHBOARD
# ─────────────────────────────────────────────
# 🆕 API de filtrage de la carte "Taux de paiement" du dashboard admin : recalcule le taux
# selon le type (Élèves / Enseignants / Personnel hors-prof / Charges), la classe, le cycle
# et une période de dates, sans recharger la page (appelée en AJAX par le JS de la carte).
@app.route('/api/dashboard/taux-paiement')
@login_required
@role_required('admin', 'agent_admin')
def api_dashboard_taux_paiement():
    conn = get_db()
    type_ = (request.args.get('type') or 'eleves').strip()
    classe_id = (request.args.get('classe_id') or '').strip()
    cycle = (request.args.get('cycle') or '').strip()
    date_debut = (request.args.get('date_debut') or '').strip()
    date_fin = (request.args.get('date_fin') or '').strip()
    # 🆕 Type de facture (Frais d'inscription / Scolarité / Voyage / Achat / Service / Autre),
    # uniquement pertinent pour le type "eleves" : la catégorie est stockée en préfixe de la
    # colonne description, ex "[Scolarité] ..." (même convention que la page /paiements).
    type_facture = (request.args.get('type_facture') or '').strip()

    result = {'type': type_, 'taux': 0, 'total_paye': 0, 'total_du': 0,
              'unite': 'MAD', 'label_du': 'Total dû', 'label_paye': 'Payé'}

    if type_ == 'personnel':
        # Personnel hors-prof (agents, chauffeurs, femmes de ménage...) : montant dû / payé
        sql = "SELECT SUM(montant_total) as t, SUM(montant_paye) as pay FROM paiements_personnel_hors_prof WHERE 1=1"
        params = []
        if date_debut:
            sql += " AND date_paiement >= ?"; params.append(date_debut)
        if date_fin:
            sql += " AND date_paiement <= ?"; params.append(date_fin)
        row = conn.execute(sql, params).fetchone()
        total_du, total_paye = row['t'] or 0, row['pay'] or 0
        result.update(taux=round((total_paye / total_du * 100) if total_du else 0, 1),
                       total_du=total_du, total_paye=total_paye,
                       label_du='Total dû', label_paye='Payé')

    elif type_ == 'charges':
        # Charges diverses de l'école : montant total / montant réglé (statut='paye')
        sql = "SELECT SUM(montant) as t, SUM(CASE WHEN statut='paye' THEN montant ELSE 0 END) as pay FROM charges WHERE 1=1"
        params = []
        if date_debut:
            sql += " AND date_facture >= ?"; params.append(date_debut)
        if date_fin:
            sql += " AND date_facture <= ?"; params.append(date_fin)
        row = conn.execute(sql, params).fetchone()
        total_du, total_paye = row['t'] or 0, row['pay'] or 0
        result.update(taux=round((total_paye / total_du * 100) if total_du else 0, 1),
                       total_du=total_du, total_paye=total_paye,
                       label_du='Total charges', label_paye='Réglé')

    elif type_ == 'enseignants':
        # Pas de "montant dû" fiable stocké pour les enseignants (paiements_enseignants ne
        # trace que les paiements effectués) : on affiche donc le taux de couverture, c-à-d
        # la part des enseignants ayant reçu au moins un paiement sur la période choisie.
        total_ens = conn.execute("SELECT COUNT(*) FROM users WHERE role='enseignant'").fetchone()[0]
        sql = "SELECT COUNT(DISTINCT enseignant_id) FROM paiements_enseignants WHERE 1=1"
        params = []
        if date_debut:
            sql += " AND date_paiement >= ?"; params.append(date_debut)
        if date_fin:
            sql += " AND date_paiement <= ?"; params.append(date_fin)
        payes = conn.execute(sql, params).fetchone()[0]
        result.update(taux=round((payes / total_ens * 100) if total_ens else 0, 1),
                       total_du=total_ens, total_paye=payes, unite='enseignants',
                       label_du='Total enseignants', label_paye='Payés')

    else:
        # Élèves (par défaut) : montant total dû / payé, filtrable par classe et/ou cycle
        sql = """SELECT SUM(p.montant_total - COALESCE(p.montant_regule, 0)) as t, SUM(p.montant_paye) as pay
                 FROM paiements p JOIN eleves e ON p.eleve_id = e.id JOIN classes c ON e.classe_id = c.id
                 WHERE 1=1"""
        params = []
        if classe_id:
            sql += " AND c.id = ?"; params.append(classe_id)
        if cycle:
            sql += " AND COALESCE(NULLIF(c.cycle,''),'Primaire') = ?"; params.append(cycle)
        if type_facture:
            sql += " AND p.description LIKE ?"; params.append(f"[{type_facture}]%")
        if date_debut:
            sql += " AND p.date_echeance >= ?"; params.append(date_debut)
        if date_fin:
            sql += " AND p.date_echeance <= ?"; params.append(date_fin)
        row = conn.execute(sql, params).fetchone()
        total_du, total_paye = row['t'] or 0, row['pay'] or 0
        result.update(taux=round((total_paye / total_du * 100) if total_du else 0, 1),
                       total_du=total_du, total_paye=total_paye,
                       label_du='Total dû', label_paye='Payé')

    conn.close()
    return jsonify(result)


# ─────────────────────────────────────────────
# 🆕 DASHBOARD ENSEIGNANT MOBILE — données (LECTURE SEULE, aucune écriture en base).
# Chaque requête est isolée : si l'une échoue, les autres blocs restent affichés.
# ─────────────────────────────────────────────
def _ens_dashboard_mobile_data(conn, eid):
    today = datetime.date.today()
    jours = ['Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi', 'Dimanche']
    jour_nom = jours[today.weekday()]
    iso = today.isoformat()
    cls_ids = sorted(_ens_classes_ids_assignees(conn, eid))
    ph = ','.join('?' * len(cls_ids)) if cls_ids else ''
    d = {'jour_nom': jour_nom, 'seances': [], 'classes': [], 'absents': [], 'alertes': [], 'devoirs': [],
         'etoiles': [], 'nb_absents': 0, 'nb_retards': 0, 'nb_msgs': 0, 'notes_semaine': 0,
         'nb_classes': len(cls_ids), 'nb_devoirs': 0}

    def _q(sql, params=()):
        try:
            return conn.execute(sql, params).fetchall()
        except Exception as ex:
            print(f"Dashboard enseignant mobile (requête ignorée) : {ex}")
            return []

    # 1) Séances du jour (même logique que l'export « emploi du temps professeur »)
    for r in _q("""SELECT e.heure_debut, e.heure_fin, e.salle, e.libelle, m.nom AS matiere,
                          c.nom AS classe, c.id AS classe_id, c.cycle AS cycle
                   FROM emploi_temps e
                   JOIN matieres m ON e.matiere_id = m.id
                   JOIN classes c ON m.classe_id = c.id
                   WHERE m.enseignant_id = ? AND e.jour = ?
                   ORDER BY e.heure_debut""", (eid, jour_nom)):
        d['seances'].append({'debut': r['heure_debut'], 'fin': r['heure_fin'], 'salle': r['salle'] or '',
                             'matiere': r['matiere'] or r['libelle'] or 'Cours', 'classe': r['classe'],
                             'classe_id': r['classe_id'], 'cycle': r['cycle'] or 'Primaire'})

    if cls_ids:
        # 2) Mes classes : effectif, moyenne de MES notes, élèves pas encore notés
        for c in _q(f"SELECT id, nom, niveau, cycle FROM classes WHERE id IN ({ph}) ORDER BY niveau, nom", cls_ids):
            cycle = c['cycle'] or 'Primaire'
            nb_el = (_q("SELECT COUNT(*) FROM eleves WHERE classe_id=?", (c['id'],)) or [[0]])[0][0]
            r = (_q("""SELECT AVG(n.note), COUNT(*) FROM notes n JOIN eleves e ON n.eleve_id = e.id
                       WHERE e.classe_id=? AND n.enseignant_id=?""", (c['id'], eid)) or [[None, 0]])[0]
            sans = (_q("""SELECT COUNT(*) FROM eleves e WHERE e.classe_id=?
                          AND NOT EXISTS (SELECT 1 FROM notes n WHERE n.eleve_id=e.id AND n.enseignant_id=?)""",
                       (c['id'], eid)) or [[0]])[0][0]
            moy = r[0]
            if moy is None:
                aff, ton, pct = '—', 'none', 0
            elif get_systeme_notes(cycle, conn) == 'lettres':
                aff = _lettre_depuis_note(moy)
                ton = {'A': 'high', 'B': 'mid', 'C': 'low'}.get(aff, 'mid')
                pct = int(max(0, min(100, moy / 20 * 100)))
            else:
                aff = fmt_moy_sys(moy, get_systeme_notes(cycle, conn), 1, False)
                ton = 'high' if moy >= 14 else ('mid' if moy >= 10 else 'low')
                pct = int(max(0, min(100, moy / 20 * 100)))
            d['classes'].append({'id': c['id'], 'nom': c['nom'], 'niveau': c['niveau'] or '', 'cycle': cycle,
                                 'nb_eleves': nb_el, 'nb_notes': r[1] or 0, 'sans_notes': sans,
                                 'moy_aff': aff, 'ton': ton, 'pct': pct,
                                 'notes_pct': int(round((nb_el - sans) / nb_el * 100)) if nb_el else 0})

        # 3) Absents / retards du jour dans mes classes
        rows = _q(f"""SELECT e.id, e.prenom, e.nom, c.nom AS classe, MAX(a.justifiee) AS justifiee
                      FROM absences a JOIN eleves e ON a.eleve_id = e.id JOIN classes c ON e.classe_id = c.id
                      WHERE date(a.date_absence)=? AND e.classe_id IN ({ph})
                      GROUP BY e.id ORDER BY c.nom, e.nom""", [iso] + cls_ids)
        d['nb_absents'] = len(rows)
        d['absents'] = [{'id': r['id'], 'nom': f"{r['prenom']} {r['nom']}", 'classe': r['classe'],
                         'justifiee': bool(r['justifiee'])} for r in rows[:6]]
        d['nb_retards'] = (_q(f"""SELECT COUNT(*) FROM retards r JOIN eleves e ON r.eleve_id = e.id
                                  WHERE date(r.date_retard)=? AND e.classe_id IN ({ph})""",
                              [iso] + cls_ids) or [[0]])[0][0]

        # 4) À surveiller : moyenne faible (mes notes) + absences fréquentes (30 derniers jours)
        for r in _q(f"""SELECT e.id, e.prenom, e.nom, c.nom AS classe, c.cycle AS cycle, AVG(n.note) AS moy, COUNT(*) AS nb
                        FROM notes n JOIN eleves e ON n.eleve_id = e.id JOIN classes c ON e.classe_id = c.id
                        WHERE n.enseignant_id=? AND e.classe_id IN ({ph})
                        GROUP BY e.id HAVING AVG(n.note) < 8 AND COUNT(*) >= 2
                        ORDER BY moy ASC LIMIT 6""", [eid] + cls_ids):
            d['alertes'].append({'type': 'moy', 'id': r['id'], 'nom': f"{r['prenom']} {r['nom']}",
                                 'classe': r['classe'],
                                 'txt': f"Moyenne {fmt_moy_sys(r['moy'], get_systeme_notes(r['cycle'] or 'Primaire', conn), 1)} sur {r['nb']} notes"})
        for r in _q(f"""SELECT e.id, e.prenom, e.nom, c.nom AS classe, COUNT(DISTINCT date(a.date_absence)) AS nb
                        FROM absences a JOIN eleves e ON a.eleve_id = e.id JOIN classes c ON e.classe_id = c.id
                        WHERE date(a.date_absence) >= date(?, '-30 day') AND e.classe_id IN ({ph})
                        GROUP BY e.id HAVING nb >= 3 ORDER BY nb DESC LIMIT 5""", [iso] + cls_ids):
            d['alertes'].append({'type': 'abs', 'id': r['id'], 'nom': f"{r['prenom']} {r['nom']}",
                                 'classe': r['classe'], 'txt': f"{r['nb']} jours d'absence en 30 jours"})

        # 5) À féliciter : meilleures moyennes (au moins 2 notes)
        for r in _q(f"""SELECT e.id, e.prenom, e.nom, c.nom AS classe, c.cycle AS cycle, AVG(n.note) AS moy
                        FROM notes n JOIN eleves e ON n.eleve_id = e.id JOIN classes c ON e.classe_id = c.id
                        WHERE n.enseignant_id=? AND e.classe_id IN ({ph})
                        GROUP BY e.id HAVING AVG(n.note) >= 16 AND COUNT(*) >= 2
                        ORDER BY moy DESC LIMIT 3""", [eid] + cls_ids):
            d['etoiles'].append({'id': r['id'], 'nom': f"{r['prenom']} {r['nom']}", 'classe': r['classe'],
                                 'moy': fmt_moy_sys(r['moy'], get_systeme_notes(r['cycle'] or 'Primaire', conn), 1, False),
                                 'ech': ('' if get_systeme_notes(r['cycle'] or 'Primaire', conn) == 'lettres'
                                         else libelle_echelle_sys(get_systeme_notes(r['cycle'] or 'Primaire', conn)))})

    # 6) Activité : notes saisies sur 7 jours
    d['notes_semaine'] = (_q("""SELECT COUNT(*) FROM notes WHERE enseignant_id=?
                                AND date(date_saisie) >= date('now', '-7 day')""", (eid,)) or [[0]])[0][0]

    # 7) Devoirs que J'AI assignés, à rendre prochainement
    for r in _q("""SELECT d.id, d.titre, d.date_limite, d.priorite, m.nom AS matiere,
                          (SELECT GROUP_CONCAT(c.nom, ', ') FROM devoir_classes dc
                           JOIN classes c ON c.id = dc.classe_id WHERE dc.devoir_id = d.id) AS classes
                   FROM devoirs d LEFT JOIN matieres m ON m.id = d.matiere_id
                   WHERE d.assigne_par=? AND d.date_limite IS NOT NULL AND d.date_limite != ''
                     AND date(d.date_limite) >= date(?) AND COALESCE(d.statut, 'publie') != 'brouillon'
                   ORDER BY d.date_limite ASC LIMIT 5""", (eid, iso)):
        try:
            j = (datetime.date.fromisoformat(str(r['date_limite'])[:10]) - today).days
        except Exception:
            continue
        d['devoirs'].append({'id': r['id'], 'titre': r['titre'], 'matiere': r['matiere'] or '',
                             'classes': r['classes'] or '', 'j': j,
                             'lbl': "Aujourd'hui" if j == 0 else ('Demain' if j == 1 else f"J-{j}"),
                             'urgent': j <= 1})
    d['nb_devoirs'] = len(d['devoirs'])

    # 8) Messages non lus (même règle que la messagerie)
    d['nb_msgs'] = (_q("""SELECT COUNT(*) FROM msg_messages mm
                          JOIN msg_conversations c ON c.id = mm.conversation_id
                          WHERE (c.user_a_id=? OR c.user_b_id=?) AND mm.expediteur_id != ?
                            AND mm.id > COALESCE((SELECT dernier_lu_msg_id FROM msg_participant_etat pe
                                                  WHERE pe.conversation_id=mm.conversation_id AND pe.user_id=?), 0)""",
                      (eid, eid, eid, eid)) or [[0]])[0][0]
    return d


@app.route('/dashboard')
@login_required
def dashboard():
    if session.get('role') in ('chauffeur', 'accompagnatrice'):
        return redirect(url_for('espace_chauffeur'))
    if session.get('role') == 'secretaire':
        return redirect(_accueil_secretaire())
    conn = get_db()
    role = session['role']
    stats = {}
    if role in ('admin', 'agent_admin'):
        stats['nb_eleves'] = conn.execute("SELECT COUNT(*) FROM eleves").fetchone()[0]
        stats['nb_classes'] = conn.execute("SELECT COUNT(*) FROM classes").fetchone()[0]
        stats['nb_enseignants'] = conn.execute("SELECT COUNT(*) FROM users WHERE role='enseignant'").fetchone()[0]
        stats['nb_parents'] = conn.execute("SELECT COUNT(*) FROM users WHERE role='parent'").fetchone()[0]
        # 🩹 CORRECTIF : on aligne ce calcul sur celui de la page /paiements (Hub), qui
        # fait une jointure avec "eleves" et exclut donc les paiements orphelins (rattachés
        # à un élève supprimé depuis). Sans cette jointure, la carte du dashboard comptait
        # ces montants fantômes et affichait un total incohérent avec la page Paiements.
        p = conn.execute("""
            SELECT SUM(p.montant_total - COALESCE(p.montant_regule, 0)) as t, SUM(p.montant_paye) as p
            FROM paiements p
            JOIN eleves e ON p.eleve_id = e.id
        """).fetchone()
        stats['total_du'] = p['t'] or 0
        stats['total_paye'] = p['p'] or 0
        stats['taux_paiement'] = round((stats['total_paye'] / stats['total_du'] * 100) if stats['total_du'] else 0, 1)
        stats['impaye_count'] = conn.execute("""
            SELECT COUNT(*) FROM paiements p JOIN eleves e ON p.eleve_id = e.id WHERE p.statut!='paye'
        """).fetchone()[0]
        notes_avg = conn.execute("SELECT AVG(note) FROM notes").fetchone()[0]
        stats['moyenne_generale'] = round(notes_avg, 2) if notes_avg else 0
        stats['absences_total'] = conn.execute("SELECT COUNT(*) FROM absences").fetchone()[0]
        stats['recent_msgs'] = conn.execute("""
            SELECT mm.*, u.prenom||' '||u.nom as exp_nom, mm.created_at as date_envoi,
                   SUBSTR(mm.contenu, 1, 60) as sujet
            FROM msg_messages mm JOIN users u ON mm.expediteur_id=u.id
            ORDER BY mm.created_at DESC LIMIT 5
        """).fetchall()
        stats['impaye_list'] = conn.execute(
            "SELECT e.prenom||' '||e.nom as eleve, c.nom as classe, p.montant_total-p.montant_paye as reste, p.statut "
            "FROM paiements p JOIN eleves e ON p.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
            "WHERE p.statut!='paye' ORDER BY reste DESC LIMIT 5"
        ).fetchall()

        # 🆕 Répartition élèves/classes par cycle — vue d'ensemble Maternelle/Primaire/Collège
        stats['cycles'] = conn.execute("""
            SELECT COALESCE(NULLIF(c.cycle,''),'Primaire') as cycle,
                   COUNT(DISTINCT c.id) as nb_classes,
                   COUNT(e.id) as nb_eleves
            FROM classes c
            LEFT JOIN eleves e ON e.classe_id = c.id
            GROUP BY COALESCE(NULLIF(c.cycle,''),'Primaire')
        """).fetchall()

        # 🆕 Liste des classes (id/nom/cycle) pour le filtre de la carte "Taux de paiement"
        # du dashboard (sélecteur "Classe" dépendant du "Cycle" choisi, côté JS).
        stats['classes_filtre'] = conn.execute("""
            SELECT id, nom, COALESCE(NULLIF(cycle,''),'Primaire') as cycle
            FROM classes ORDER BY nom
        """).fetchall()

        # 🆕 Effectifs complémentaires pour la vue d'ensemble
        stats['nb_aides_maternelle'] = conn.execute(
            "SELECT COUNT(*) FROM users WHERE role='enseignant' AND fonction='Aide maîtresse'").fetchone()[0]
        stats['nb_personnel_hors_prof'] = conn.execute(
            "SELECT COUNT(*) FROM personnel_hors_prof").fetchone()[0]

        # 🆕 Alertes actionnables : ce qui mérite l'attention de l'admin en un coup d'œil
        stats['classes_sans_prof'] = conn.execute("""
            SELECT c.id, c.nom, c.niveau, COALESCE(NULLIF(c.cycle,''),'Primaire') as cycle
            FROM classes c
            WHERE NOT EXISTS (SELECT 1 FROM classe_profs cp WHERE cp.classe_id = c.id)
            ORDER BY c.nom
        """).fetchall()
        stats['parents_sans_tel'] = conn.execute(
            "SELECT COUNT(*) FROM users WHERE role='parent' AND (telephone IS NULL OR telephone = '')"
        ).fetchone()[0]
        stats['eleves_absences_frequentes'] = conn.execute("""
            SELECT e.id as eleve_id, e.prenom||' '||e.nom as eleve, c.nom as classe, COUNT(a.id) as nb_absences
            FROM absences a
            JOIN eleves e ON a.eleve_id = e.id
            LEFT JOIN classes c ON e.classe_id = c.id
            GROUP BY a.eleve_id
            ORDER BY nb_absences DESC, e.id ASC
            LIMIT 5
        """).fetchall()
        # 🆕 Si cette alerte a déjà été "traitée" (l'admin a cliqué sur "Voir les absences" depuis
        # cette carte) ET que la situation n'a pas changé depuis (mêmes élèves, mêmes compteurs),
        # on la fait disparaître de "Alertes à traiter" — sans effacer les données réelles. Si un
        # nouvel élève dépasse le seuil ou qu'un compteur augmente, la signature change et l'alerte
        # revient automatiquement au prochain chargement du dashboard.
        _sig_absences_freq = ','.join(sorted(
            f"{r['eleve_id']}:{r['nb_absences']}" for r in stats['eleves_absences_frequentes']))
        # 🔧 CORRECTIF (2026-09) : filet de sécurité — si la table n'a pas encore été créée
        # (ex: base toute fraîche où la migration de démarrage n'est pas encore passée), on la
        # crée à la volée ici plutôt que de faire planter tout le dashboard avec un
        # "no such table". CREATE TABLE IF NOT EXISTS est idempotent, donc sans danger même
        # si la table existe déjà.
        try:
            _traitee = conn.execute(
                "SELECT signature FROM alertes_dashboard_traitees WHERE type_alerte='absences_frequentes'"
            ).fetchone()
        except sqlite3.OperationalError:
            conn.execute("""
                         CREATE TABLE IF NOT EXISTS alertes_dashboard_traitees
                         (
                             type_alerte TEXT PRIMARY KEY,
                             signature   TEXT DEFAULT '',
                             traite_le   TEXT
                         )
                         """)
            conn.commit()
            _traitee = None
        if _traitee and _traitee['signature'] == _sig_absences_freq:
            stats['eleves_absences_frequentes'] = []

    elif role == 'enseignant':
        eid = session['user_id']

        # 🔄 MODIFIÉ : On utilise EXISTS avec classe_profs pour mes_classes
        stats['mes_classes'] = conn.execute(
            """SELECT c.*, COUNT(e.id) as nb_eleves 
               FROM classes c 
               LEFT JOIN eleves e ON e.classe_id=c.id 
               WHERE EXISTS (SELECT 1 FROM classe_profs cp WHERE cp.classe_id = c.id AND cp.enseignant_id = ?)
               GROUP BY c.id""",
            (eid,)
        ).fetchall()

        # 🔄 MODIFIÉ : Comptage des élèves basé sur classe_profs
        stats['nb_eleves'] = conn.execute(
            """SELECT COUNT(e.id) 
               FROM eleves e JOIN classes c ON e.classe_id=c.id 
               WHERE EXISTS (SELECT 1 FROM classe_profs cp WHERE cp.classe_id = c.id AND cp.enseignant_id = ?)""",
            (eid,)
        ).fetchone()[0]

        stats['notes_saisies'] = conn.execute("SELECT COUNT(*) FROM notes WHERE enseignant_id=?", (eid,)).fetchone()[0]
        stats['absences_signalees'] = \
            conn.execute("SELECT COUNT(*) FROM absences WHERE signale_par=?", (eid,)).fetchone()[0]

        # 🔄 MODIFIÉ : Récupération des élèves récents basée sur classe_profs
        stats['recent_eleves'] = conn.execute(
            """SELECT e.*, c.nom as classe 
               FROM eleves e JOIN classes c ON e.classe_id=c.id 
               WHERE EXISTS (SELECT 1 FROM classe_profs cp WHERE cp.classe_id = c.id AND cp.enseignant_id = ?) 
               LIMIT 5""",
            (eid,)
        ).fetchall()

        # 🆕 MOBILE ENSEIGNANT : données du nouveau dashboard mobile (ajout pur, lecture seule)
        try:
            stats['ens_m'] = _ens_dashboard_mobile_data(conn, eid)
        except Exception as _e_ens_m:
            print(f"Dashboard enseignant mobile : {_e_ens_m}")
            stats['ens_m'] = None

    elif role == 'parent':
        pid = session['user_id']
        stats['mes_enfants'] = conn.execute(
            "SELECT e.*, c.nom as classe FROM eleves e LEFT JOIN classes c ON e.classe_id=c.id WHERE e.parent_id=?",
            (pid,)
        ).fetchall()
        # 💳 Chèques déposés : une facture couverte par un chèque en attente n'est PAS affichée comme impayée
        # côté parent, mais « Payé par chèque » (même logique que la page /paiements du parent).
        try:
            _assurer_table_cheques(conn)
            _rows_pay_parent = conn.execute(
                f"SELECT p.*, e.prenom||' '||e.nom as eleve, {_SQL_CHEQUES_ATTENTE} AS cheque_attente "
                "FROM paiements p JOIN eleves e ON p.eleve_id=e.id WHERE e.parent_id=?",
                (pid,)
            ).fetchall()
        except Exception as _e_chq_dash:
            print(f"Dashboard parent : lecture des chèques impossible : {_e_chq_dash}")
            _rows_pay_parent = conn.execute(
                "SELECT p.*, e.prenom||' '||e.nom as eleve, 0 AS cheque_attente FROM paiements p JOIN eleves e ON p.eleve_id=e.id WHERE e.parent_id=?",
                (pid,)
            ).fetchall()
        stats['paiements'] = []
        stats['cheque_total_parent'] = 0.0
        for _r_pay in _rows_pay_parent:
            _d_pay = dict(_r_pay)
            _tot = float(_d_pay.get('montant_total') or 0)
            _paye = float(_d_pay.get('montant_paye') or 0)
            _chq = float(_d_pay.get('cheque_attente') or 0)
            _reste_brut = max(_tot - _paye, 0.0)
            if _d_pay.get('statut') == 'paye' or _chq <= 0:
                _chq_ok = 0.0
            else:
                _chq_ok = min(_chq, _reste_brut)
            _d_pay['cheque_ok'] = round(_chq_ok, 2)
            # facture entièrement couverte par un/des chèque(s) → « Payé par chèque »
            _d_pay['cheque_couvre'] = bool(_chq_ok > 0 and (_reste_brut - _chq_ok) <= 0.009)
            # « réglé » affiché = encaissé + chèque déposé ; « reste » = ce qui n'est couvert ni par un paiement ni par un chèque
            _d_pay['paye_aff'] = _paye + _chq_ok
            _d_pay['reste_aff'] = 0.0 if _d_pay.get('statut') == 'paye' else max(_reste_brut - _chq_ok, 0.0)
            stats['cheque_total_parent'] += _chq_ok
            stats['paiements'].append(_d_pay)
        stats['messages_non_lus'] = conn.execute("""
            SELECT COUNT(*) FROM msg_messages mm
            JOIN msg_conversations c ON c.id = mm.conversation_id
            WHERE (c.user_a_id=? OR c.user_b_id=?) AND mm.expediteur_id != ?
              AND mm.id > COALESCE((SELECT dernier_lu_msg_id FROM msg_participant_etat pe
                                     WHERE pe.conversation_id=mm.conversation_id AND pe.user_id=?), 0)
        """, (pid, pid, pid, pid)).fetchone()[0]
        for enf in stats['mes_enfants']:
            avg = conn.execute("SELECT AVG(note) FROM notes WHERE eleve_id=?", (enf['id'],)).fetchone()[0]
            stats[f'avg_{enf["id"]}'] = round(avg, 2) if avg else 'N/A'
            try:
                _cy_enf = conn.execute("SELECT c.cycle FROM eleves e JOIN classes c ON c.id=e.classe_id WHERE e.id=?", (enf['id'],)).fetchone()
                stats[f'systeme_{enf["id"]}'] = get_systeme_notes((_cy_enf['cycle'] if _cy_enf and _cy_enf['cycle'] else 'Primaire'), conn)
            except Exception:
                stats[f'systeme_{enf["id"]}'] = '20'
            # 🆕 Mini-dashboard enfant : nombre d'absences et de retards
            try:
                stats[f'abs_{enf["id"]}'] = conn.execute(
                    "SELECT COUNT(*) FROM absences WHERE eleve_id=?", (enf['id'],)).fetchone()[0]
            except Exception:
                stats[f'abs_{enf["id"]}'] = 0
            try:
                stats[f'ret_{enf["id"]}'] = conn.execute(
                    "SELECT COUNT(*) FROM retards WHERE eleve_id=?", (enf['id'],)).fetchone()[0]
            except Exception:
                stats[f'ret_{enf["id"]}'] = 0
        # 🆕 Situation de paiement globale (tous enfants confondus) pour la carte
        # affichée en haut du tableau de bord parent, avec un émoticône qui reflète
        # le niveau d'impayé : 😊 aucun impayé, 😐 impayé < 1000 DH, 😟 impayé >= 1000 DH
        _sys_enfants = {stats.get(f'systeme_{e["id"]}', '20') for e in stats['mes_enfants']}
        stats['systeme_famille'] = _sys_enfants.pop() if len(_sys_enfants) == 1 else '20'
        stats['solde_impaye_parent'] = sum(
            p['reste_aff'] for p in stats['paiements'] if p['statut'] != 'paye'
        )
        if stats['solde_impaye_parent'] <= 0:
            stats['paiement_emoji'] = '😊'
            stats['paiement_humeur'] = 'ok'
        elif stats['solde_impaye_parent'] < 1000:
            stats['paiement_emoji'] = '😐'
            stats['paiement_humeur'] = 'mid'
        else:
            stats['paiement_emoji'] = '😟'
            stats['paiement_humeur'] = 'bad'

        # 🆕 Slider "À la une" (mêmes actualités publiées que sur /communications, visibles
        # par ce parent) pour le tableau de bord mobile parent.
        communications_publier_programmees(conn)
        classes_acc_dash = _devoir_classes_accessibles(conn, role, pid)
        classe_ids_acc_dash = [c['id'] for c in classes_acc_dash]
        if classe_ids_acc_dash:
            ph_dash = ','.join('?' * len(classe_ids_acc_dash))
            comm_where_dash = (f"(co.toutes_classes=1 OR co.id IN (SELECT communication_id FROM "
                               f"communication_classes WHERE classe_id IN ({ph_dash}))) AND co.statut='publie'")
            comm_params_dash = list(classe_ids_acc_dash)
        else:
            comm_where_dash = "co.toutes_classes=1 AND co.statut='publie'"
            comm_params_dash = []
        lignes_comm_dash = conn.execute(f"""
            SELECT co.* FROM communications co
            WHERE {comm_where_dash}
            GROUP BY co.id
            ORDER BY co.epingle DESC, co.date_publication DESC
        """, comm_params_dash).fetchall()
        comm_ids_dash = [c['id'] for c in lignes_comm_dash]
        fichiers_par_comm_dash = {}
        if comm_ids_dash:
            ph2_dash = ','.join('?' * len(comm_ids_dash))
            for f in conn.execute(
                    f"SELECT * FROM communication_fichiers WHERE communication_id IN ({ph2_dash}) ORDER BY id",
                    comm_ids_dash).fetchall():
                fichiers_par_comm_dash.setdefault(f['communication_id'], []).append(dict(f))
        stats['comms_slider'] = []
        for c in lignes_comm_dash:
            item = dict(c)
            fichiers_c = fichiers_par_comm_dash.get(c['id'], [])
            item['image_apercu'] = next((f for f in fichiers_c if f['type_fichier'] == 'image'), None)
            stats['comms_slider'].append(item)
        # 📅 Carte « Rendez-vous avec l'administration » en haut du tableau de bord parent
        stats['rdv_horaires'] = _rdv_fenetres_txt('paiement')
        stats['rdv_prochain'] = None
        try:
            _rdv_assurer_table(conn)
            _p_rdv = conn.execute(
                """SELECT * FROM rendez_vous WHERE parent_id=? AND type_demande='creneau'
                   AND statut IN ('en_attente','confirme') AND date_rdv>=? ORDER BY date_rdv, heure_rdv LIMIT 1""",
                (pid, datetime.date.today().isoformat())).fetchone()
            if _p_rdv:
                stats['rdv_prochain'] = _rdv_enrichir(_p_rdv, 'parent')
        except Exception:
            stats['rdv_prochain'] = None
    conn.close()
    _fr_days = ['Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi', 'Dimanche']
    _fr_months = ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre']
    _today = datetime.date.today()
    today_str = f"{_fr_days[_today.weekday()]} {_today.day} {_fr_months[_today.month - 1]} {_today.year}"
    first_name = (session.get('nom_complet', 'Utilisateur').split() or ['Utilisateur'])[0]
    # ⏳ Alerte « l'application se termine bientôt » + demande de devis (admin uniquement)
    stats['licence_alerte'] = None
    if role == 'admin' and session.get('role_reel') in (None, 'admin'):
        try:
            stats['licence_alerte'] = _manageapp_alerte_admin()
        except Exception as _e_lic_alerte:
            print(f"Dashboard admin : alerte licence impossible : {_e_lic_alerte}")
    return render_template_string(DASHBOARD_HTML, stats=stats, notif_count=get_notif_count(), today_str=today_str, first_name=first_name,
                                  COULEURS_TYPE_COMMUNICATION=COULEURS_TYPE_COMMUNICATION, LABELS_TYPE_COMMUNICATION=LABELS_TYPE_COMMUNICATION)


