@app.route('/enseignants/<int:enseignant_id>')
@login_required
@role_required('admin')  # Généralement, seul l'admin ou l'enseignant lui-même voit ça
def enseignant_detail(enseignant_id):
    conn = get_db()
    # Récupération de toutes les infos de la table users pour cet enseignant[cite: 1]
    enseignant = conn.execute("SELECT * FROM users WHERE id=? AND role='enseignant'", (enseignant_id,)).fetchone()

    if not enseignant:
        flash('Enseignant introuvable.', 'error')
        return redirect(url_for('dashboard'))

    # Récupération des classes assignées à cet enseignant via classe_profs[cite: 1]
    classes = conn.execute("""
        SELECT c.nom, c.niveau, c.cycle, cp.matiere 
        FROM classe_profs cp
        JOIN classes c ON cp.classe_id = c.id
        WHERE cp.enseignant_id = ?
    """, (enseignant_id,)).fetchall()

    conn.close()
    return render_template_string(ENSEIGNANT_HTML, enseignant=enseignant, classes=classes,
                                  notif_count=get_notif_count())


