@app.route('/eleves/<int:eleve_id>/paiement/add', methods=['POST'])
@login_required
@role_required('admin')
def add_paiement_eleve(eleve_id):
    conn = get_db()
    f = request.form
    # 🩹 FIX : statut recalculé à partir des montants (comme pour la mise à jour d'un paiement),
    # au lieu d'être pris tel quel du formulaire — évite qu'un paiement complet (ex: frais
    # d'inscription) reste affiché "Non payé" (rouge) simplement parce que le champ Statut
    # n'a pas été changé manuellement.
    try:
        montant_total_add = float(str(f['montant_total'] or 0).replace(',', '.'))
        montant_paye_add = float(str(f.get('montant_paye', 0) or 0).replace(',', '.'))
    except ValueError:
        conn.close()
        flash('Montant invalide : entrez un nombre.', 'error')
        return redirect(url_for('eleve_detail', eleve_id=eleve_id))
    if (not _montant_fini(montant_total_add) or not _montant_fini(montant_paye_add)
            or montant_total_add < 0 or montant_paye_add < 0):
        conn.close()
        flash('Montant invalide : un montant ne peut pas être négatif.', 'error')
        return redirect(url_for('eleve_detail', eleve_id=eleve_id))
    # 🔒 Jamais plus que le montant de la facture : l'excédent n'est pas compté comme revenu.
    if montant_paye_add > montant_total_add + 0.005:
        flash(f"Le montant payé ({montant_paye_add:.2f} MAD) dépassait le montant de la facture "
              f"({montant_total_add:.2f} MAD) : il a été ramené à {montant_total_add:.2f} MAD.", 'error')
    montant_paye_add = round(max(min(montant_paye_add, montant_total_add), 0.0), 2)
    statut_add = 'paye' if (montant_total_add <= 0 or montant_paye_add >= montant_total_add) \
        else ('partiel' if montant_paye_add > 0 else 'non_paye')
    # 🆕 Mode d'encaissement (Caisse / Banque) — indispensable pour que ce paiement soit bien
    # compté dans les compteurs de trésorerie de la page /paiements (voir calculer_soldes_caisse_banque),
    # qui ne comptabilisent QUE les paiements dont mode_encaissement est renseigné. Sans ce
    # champ ici, un paiement ajouté depuis la fiche élève restait invisible de la Caisse/Banque.
    mode_encaissement_add = f.get('mode_encaissement') or None
    if montant_paye_add <= 0 or mode_encaissement_add not in ('Caisse', 'Banque'):
        mode_encaissement_add = None
    # 🆕 Si la facture est créée déjà partiellement ou totalement réglée, on renseigne tout
    # de suite la date de paiement (date du jour), sinon le reçu affiche "—" en Date de
    # paiement malgré un statut payé/partiel.
    date_paiement_add = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S') \
        if statut_add in ('partiel', 'paye') else None
    conn.execute(
        "INSERT INTO paiements (eleve_id,montant_total,montant_paye,description,date_echeance,statut,date_paiement,mode_encaissement) VALUES (?,?,?,?,?,?,?,?)",
        (eleve_id, montant_total_add, montant_paye_add, f['description'], f.get('date_echeance'),
         statut_add, date_paiement_add, mode_encaissement_add))
    # 🆕 TRAÇABILITÉ « Saisi par » : cette route (formulaire de la fiche élève) créait des
    # paiements sans laisser de trace dans le journal d'audit, contrairement au tableau
    # principal des paiements — la colonne "Saisi par" restait donc vide pour ces lignes.
    nouveau_pid = conn.execute("SELECT last_insert_rowid()").fetchone()[0]
    eleve_nom_row = conn.execute("SELECT prenom||' '||nom as nom FROM eleves WHERE id=?", (eleve_id,)).fetchone()
    log_action(conn, 'creation', 'paiement', nouveau_pid,
               f"Facturation (fiche élève) {eleve_nom_row['nom'] if eleve_nom_row else eleve_id} — "
               f"{f['description']} — {montant_total_add:.2f} MAD")
    conn.commit();
    conn.close()
    flash('Paiement ajouté!', 'success')
    return redirect(url_for('eleve_detail', eleve_id=eleve_id))


@app.route('/eleves/<int:eleve_id>/paiement/update', methods=['POST'])
@login_required
@role_required('admin')
def update_paiement_eleve(eleve_id):
    conn = get_db()
    f = request.form
    pid = f['paiement_id']
    # 🆕 Le champ du formulaire ne contient plus le total payé mais le montant REÇU
    # AUJOURD'HUI (ex: déjà 200 MAD payés hier + 200 MAD saisis maintenant = 400 MAD au
    # total), pour ne plus obliger à recalculer le cumul à la main à chaque versement.
    try:
        montant_ajoute = float(str(f.get('montant_a_ajouter', f.get('montant_paye', 0)) or 0).replace(',', '.'))
    except ValueError:
        montant_ajoute = float('nan')
    if not _montant_fini(montant_ajoute) or montant_ajoute < 0:
        conn.close()
        flash('Montant invalide : le montant reçu ne peut pas être négatif.', 'error')
        return redirect(url_for('eleve_detail', eleve_id=eleve_id))
    # Plafond = montant de la facture NET de la régule éventuelle (ce qui a été rendu n'est plus dû)
    row_avant = conn.execute("SELECT montant_total - COALESCE(montant_regule, 0) AS montant_total, montant_paye "
                             "FROM paiements WHERE id=?", (pid,)).fetchone()
    mt = max(float(row_avant['montant_total']), 0.0)
    montant_deja_paye = float(row_avant['montant_paye'] or 0)
    if montant_deja_paye + montant_ajoute > mt + 0.005:
        flash(f"Le montant reçu dépassait le reste dû : seuls {max(mt - montant_deja_paye, 0):.2f} MAD ont été comptés.", 'error')
    mp = round(min(montant_deja_paye + montant_ajoute, mt), 2)
    statut = 'paye' if mp >= mt else ('partiel' if mp > 0 else 'non_paye')
    # 🆕 Même correctif que pour l'ajout : on enregistre le mode d'encaissement choisi pour
    # que ce paiement compte dans la Caisse/Banque de la page /paiements.
    mode_encaissement_upd = f.get('mode_encaissement') or None
    if mp <= 0 or mode_encaissement_upd not in ('Caisse', 'Banque'):
        mode_encaissement_upd = None
    synchroniser_versements(conn, pid)  # 🆕 journal : régler d'abord l'existant à son ancienne date
    # COALESCE : si aucun mode n'est transmis, le mode déjà enregistré est conservé (avant, il était effacé
    # et la facture sortait des soldes Caisse/Banque).
    conn.execute("UPDATE paiements SET montant_paye=?,statut=?,date_paiement=CURRENT_TIMESTAMP,"
                 "mode_encaissement=COALESCE(?, mode_encaissement) WHERE id=?",
                 (mp, statut, mode_encaissement_upd, pid))
    synchroniser_versements(conn, pid)  # 🆕 journal : inscrire ce versement (avec SON mode) à la date du jour
    if montant_ajoute <= 0.005 and mode_encaissement_upd:
        corriger_mode_versements(conn, pid, mode_encaissement_upd)   # correction de mode sans nouvel argent
    # 🆕 TRAÇABILITÉ « Saisi par » : idem, cette route modifiait un paiement sans journaliser
    # qui l'avait fait — on aligne son comportement sur celui du tableau principal (AJAX).
    eleve_nom_row = conn.execute(
        "SELECT e.prenom||' '||e.nom as nom FROM paiements p JOIN eleves e ON p.eleve_id=e.id WHERE p.id=?",
        (pid,)).fetchone()
    log_action(conn, 'modification', 'paiement', pid,
               f"Paiement encaissé (fiche élève) : +{montant_ajoute:.2f} MAD "
               f"({montant_deja_paye:.2f} → {mp:.2f} MAD, statut: {statut})"
               f" — {eleve_nom_row['nom'] if eleve_nom_row else ''}")
    conn.commit();
    conn.close()
    flash('Paiement mis à jour!', 'success')
    return redirect(url_for('eleve_detail', eleve_id=eleve_id))


