@app.route('/documents/<int:doc_id>/telecharger')
@login_required
def document_telecharger(doc_id):
    conn = get_db()
    doc = conn.execute("SELECT * FROM documents WHERE id=?", (doc_id,)).fetchone()
    if not doc or not _peut_gerer_documents(doc['proprietaire_type'], doc['proprietaire_id'], conn):
        conn.close()
        flash('Document introuvable ou accès non autorisé.', 'error')
        return redirect(url_for('dashboard'))
    conn.close()
    path = os.path.join(UPLOAD_FOLDER_DOCS, doc['nom_fichier'])
    if not os.path.exists(path):
        flash('Fichier introuvable sur le serveur.', 'error')
        return redirect(url_for('dashboard'))
    return send_file(path, as_attachment=False, download_name=doc['nom_original'])


@app.route('/documents/<int:doc_id>/delete', methods=['POST'])
@login_required
def document_delete(doc_id):
    conn = get_db()
    doc = conn.execute("SELECT * FROM documents WHERE id=?", (doc_id,)).fetchone()
    if not doc or not _peut_gerer_documents(doc['proprietaire_type'], doc['proprietaire_id'], conn):
        conn.close()
        flash('Document introuvable ou accès non autorisé.', 'error')
        return redirect(url_for('dashboard'))

    proprietaire_type, proprietaire_id = doc['proprietaire_type'], doc['proprietaire_id']
    path = os.path.join(UPLOAD_FOLDER_DOCS, doc['nom_fichier'])
    if os.path.exists(path):
        try:
            os.remove(path)
        except OSError:
            pass
    conn.execute("DELETE FROM documents WHERE id=?", (doc_id,))
    conn.commit()
    conn.close()
    flash('Document supprimé.', 'success')

    if proprietaire_type == 'parent':
        return redirect(url_for('parent_detail', parent_id=proprietaire_id))
    return redirect(url_for('eleve_detail', eleve_id=proprietaire_id))


# 🆕 PHOTO DE PROFIL DE L'ÉLÈVE
@app.route('/eleves/<int:eleve_id>/photo', methods=['POST'])
@login_required
@role_required('admin', 'parent')
def eleve_photo_upload(eleve_id):
    conn = get_db()
    try:
        if not _peut_gerer_documents('eleve', eleve_id, conn):
            flash('Accès non autorisé.', 'error')
            return redirect(url_for('eleve_detail', eleve_id=eleve_id))

        photo = request.files.get('photo')
        if not photo or photo.filename == '':
            flash('Veuillez sélectionner une image.', 'error')
            return redirect(url_for('eleve_detail', eleve_id=eleve_id))

        ext = photo.filename.rsplit('.', 1)[-1].lower() if '.' in photo.filename else ''
        if ext not in ALLOWED_PHOTO_EXTENSIONS:
            flash(f"Format d'image non autorisé. Formats acceptés : "
                  f"{', '.join(sorted(ALLOWED_PHOTO_EXTENSIONS))}.", 'error')
            return redirect(url_for('eleve_detail', eleve_id=eleve_id))

        ts = datetime.datetime.now().strftime('%Y%m%d%H%M%S')
        nom_fichier = f"eleve_{eleve_id}_{ts}.{ext}"

        # Supprime l'ancienne photo si elle existe, pour ne pas accumuler de fichiers orphelins
        ancienne = conn.execute("SELECT photo FROM eleves WHERE id=?", (eleve_id,)).fetchone()
        if ancienne and ancienne['photo']:
            ancien_path = os.path.join(UPLOAD_FOLDER_PHOTOS, ancienne['photo'])
            if os.path.exists(ancien_path):
                try:
                    os.remove(ancien_path)
                except OSError:
                    pass

        _sauvegarder_image_compressee(photo, os.path.join(UPLOAD_FOLDER_PHOTOS, nom_fichier), max_dimension=1000, qualite=82)
        conn.execute("UPDATE eleves SET photo=? WHERE id=?", (nom_fichier, eleve_id))
        conn.commit()
        flash('Photo de profil mise à jour !', 'success')
    finally:
        conn.close()
    return redirect(url_for('eleve_detail', eleve_id=eleve_id))


