# 🆕 PHOTOS DE PROFIL — routes d'upload (comptes users) ; helpers définis plus haut
def _retour_photo(defaut):
    """Redirection de retour sûre (chemin interne uniquement)."""
    retour = (request.form.get('retour') or '').strip()
    if retour.startswith('/') and not retour.startswith('//'):
        return redirect(retour)
    return redirect(defaut)


@app.route('/utilisateurs/<int:user_id>/photo', methods=['POST'])
@login_required
def utilisateur_photo(user_id):
    """Photo d'un compte (admin, agent admin, enseignant, secrétaire, parent).
    Autorisé : l'admin / agent admin (jamais un compte admin pour un agent admin) ou le titulaire."""
    role = session.get('role')
    est_soi = (session.get('user_id') == user_id and role not in ('chauffeur', 'accompagnatrice'))
    conn = get_db()
    try:
        cible = conn.execute("SELECT id, role FROM users WHERE id=?", (user_id,)).fetchone()
        if not cible:
            flash('Utilisateur introuvable.', 'error')
            return redirect(url_for('dashboard'))
        autorise = est_soi or role == 'admin' or (role == 'agent_admin' and cible['role'] != 'admin' and cible['role'] not in ROLES_RESPONSABLES)
        if not autorise:
            flash('Accès non autorisé.', 'error')
            return redirect(url_for('dashboard'))
        if request.form.get('supprimer'):
            _supprimer_photo_profil(conn, 'users', user_id)
            flash('Photo retirée.', 'success')
        else:
            ok, msg = _enregistrer_photo_profil(conn, 'users', user_id, request.files.get('photo'), 'user')
            flash(msg, 'success' if ok else 'error')
    finally:
        conn.close()
    return _retour_photo(url_for('profile'))


