# 🩹 CORRECTIF : verrou anti-doublon pour la sauvegarde manuelle en arrière-plan.
# Avant : `sauvegarde_manuelle_complete()` s'exécutait DIRECTEMENT dans la requête HTTP
# (zip de la base + tous les uploads, PUIS envoi réseau vers Cloudflare). Sur Render
# (généralement 1 seul worker Gunicorn), ça bloquait l'unique worker pendant toute la
# durée de l'opération : plus AUCUN utilisateur ne pouvait charger la moindre page tant
# que la sauvegarde manuelle n'était pas terminée ("l'app cesse de fonctionner").
# Maintenant : on lance ce travail dans un thread séparé (même principe que les tâches
# planifiées sauvegarder_2min / sauvegarde_15h, qui elles n'ont jamais bloqué l'app) et on
# répond immédiatement à l'admin — le worker reste donc libre pour tous les autres.
SAUVEGARDE_MANUELLE_EN_COURS = threading.Event()


def _sauvegarde_manuelle_arriere_plan():
    try:
        sauvegarde_manuelle_complete()
    finally:
        SAUVEGARDE_MANUELLE_EN_COURS.clear()


@app.route('/admin/sauvegardes/lancer', methods=['POST'])
@login_required
@role_required('admin')
def admin_sauvegardes_lancer():
    if SAUVEGARDE_MANUELLE_EN_COURS.is_set():
        flash("Une sauvegarde manuelle est déjà en cours, merci de patienter quelques instants.", "error")
        return redirect(url_for('admin_sauvegardes'))
    SAUVEGARDE_MANUELLE_EN_COURS.set()
    threading.Thread(target=_sauvegarde_manuelle_arriere_plan, daemon=True).start()
    flash("Sauvegarde manuelle lancée en arrière-plan. Elle apparaîtra dans l'historique ci-dessous dans "
          "quelques instants — l'application reste utilisable normalement pendant ce temps.", "success")
    return redirect(url_for('admin_sauvegardes'))


# ═══════════════════════════════════════════════════════════════
# 🆕 RESTAURATION D'UNE SAUVEGARDE DEPUIS CLOUDFLARE R2 (page /admin/sauvegardes)
# Le client peut choisir une version précise à restaurer :
#   • "2min"   → temps réel, historique glissant des 24 dernières heures (un nouveau fichier
#                horodaté à chaque changement réel de la base, purgé automatiquement après 24h)
#   • "15h"    → sauvegardes quotidiennes (conservées 90 jours)
#   • "manuel" → sauvegardes manuelles déclenchées depuis cette page
# Ces sauvegardes vivent sur R2 (pas sur le disque local Render), donc restent disponibles
# même après un redéploiement qui efface le disque du conteneur.
# ═══════════════════════════════════════════════════════════════
@app.route('/admin/sauvegardes/liste_r2', methods=['GET'])
@login_required
@role_required('admin')
def admin_sauvegardes_liste_r2():
    type_demande = request.args.get('type', '2min')
    prefixes = {
        # 🆕 (2026-09) : la sauvegarde "2min" (temps réel) garde désormais un historique
        # glissant de 24h (jours_max=1) au lieu d'un unique fichier toujours écrasé — un
        # nouvel objet horodaté est créé à chaque changement réel de la base, et les objets
        # de plus de 24h sont automatiquement supprimés (voir tache_backup_2min).
        '2min': ('sauvegardes/2min', 1),
        '15h': ('sauvegardes/quotidien_15h', None),
        'manuel': ('sauvegardes/manuel', None),
    }
    if type_demande not in prefixes:
        return jsonify({'erreur': "Type de sauvegarde inconnu."})
    prefixe, jours_max = prefixes[type_demande]

    if not cloudflare_est_configure():
        return jsonify({'erreur': "Cloudflare R2 n'est pas configuré (variables d'environnement manquantes)."})
    client = _client_r2()
    bucket = os.environ.get('CLOUDFLARE_R2_BUCKET')
    if not client:
        return jsonify({'erreur': "Impossible de se connecter à Cloudflare R2."})

    limite = None
    if jours_max is not None:
        limite = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(days=jours_max)

    objets = []
    try:
        continuation = None
        while True:
            kwargs = {'Bucket': bucket, 'Prefix': f"{prefixe}/"}
            if continuation:
                kwargs['ContinuationToken'] = continuation
            reponse = client.list_objects_v2(**kwargs)
            for o in reponse.get('Contents', []):
                if limite is None or o['LastModified'] >= limite:
                    objets.append(o)
            if reponse.get('IsTruncated'):
                continuation = reponse.get('NextContinuationToken')
            else:
                break
    except Exception as e:
        return jsonify({'erreur': f"Erreur lors de la lecture de Cloudflare R2 : {e}"})

    # Regroupement par jour pour un affichage plus lisible côté client
    groupes = {}
    for o in sorted(objets, key=lambda x: x['LastModified'], reverse=True):
        jour = o['LastModified'].strftime('%d/%m/%Y')
        heure = o['LastModified'].strftime('%H:%M:%S')
        groupes.setdefault(jour, []).append({
            'cle': o['Key'], 'heure': heure, 'taille': _taille_lisible(o['Size']),
        })
    jours_ordonnes = sorted(groupes.keys(), key=lambda j: datetime.datetime.strptime(j, '%d/%m/%Y'), reverse=True)
    return jsonify({
        'jours': [{'jour': j, 'sauvegardes': groupes[j]} for j in jours_ordonnes],
        'total': len(objets),
    })


def rejouer_toutes_migrations_apres_restauration():
    """🩹 CORRECTIF « internal error après restauration d'une sauvegarde manuelle ».
    Cause : rejouer_migrations_schema_bdd() ne rejoue qu'une PARTIE des migrations (≈45) — pas
    upgrade_db_parametres_ecole, couleurs_personnalisees, logo_ecole, licence, devoirs,
    patrimoine, conges, eleves_sortants, emploi_temps, solde_depart_caisse_banque,
    bulletin_appreciations, absences_hub... qui, elles, ne tournent qu'au démarrage du module.
    Une sauvegarde manuelle étant en général plus ancienne que les sauvegardes automatiques,
    elle n'avait pas ces tables/colonnes : la base restaurée provoquait « no such column / no
    such table » sur la plupart des pages (Internal Server Error) jusqu'au redémarrage du service.
    On rejoue donc ici TOUT ce que fait un démarrage : init_db() + toutes les fonctions
    upgrade_db_* du module (toutes idempotentes), dans leur ordre de définition, index en dernier.
    Retourne la liste des migrations en erreur (non bloquant)."""
    import inspect
    erreurs = []
    try:
        init_db()
    except Exception as ex:
        erreurs.append(f"init_db: {ex}")
    noms = []
    for nom, fn in list(globals().items()):
        if nom.startswith('upgrade_db_') and callable(fn):
            try:
                if any(p.default is inspect.Parameter.empty and p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD)
                       for p in inspect.signature(fn).parameters.values()):
                    continue  # nécessite des arguments : pas une migration autonome
            except (TypeError, ValueError):
                continue
            noms.append(nom)
    noms.sort(key=lambda n: n == 'upgrade_db_indexes')  # tri stable : index en tout dernier
    # DEUX TOURS : certaines migrations en modifient une autre table créée plus loin dans le
    # fichier (ex. suivi_parents ajoute une colonne à parametres_ecole, créée après). Le 2e tour
    # rattrape ces dépendances d'ordre ; seules les erreurs du dernier tour sont conservées.
    for _tour in (1, 2):
        erreurs_tour = []
        try:
            rejouer_migrations_schema_bdd()
        except Exception as ex:
            erreurs_tour.append(f"rejouer_migrations_schema_bdd: {ex}")
        for nom in noms:
            try:
                globals()[nom]()
            except Exception as ex:
                erreurs_tour.append(f"{nom}: {ex}")
    erreurs += erreurs_tour
    if erreurs:
        print("  ⚠️  Migrations en erreur après restauration : " + " | ".join(erreurs))
    return erreurs


def _restauration_arriere_plan(cle):
    """🩹 CORRECTIF : tout le travail de restauration (téléchargement R2 + extraction du zip +
    rejeu des migrations) tournait AVANT directement dans la requête HTTP du clic sur
    "Restaurer". Sur Render (généralement 1 seul worker Gunicorn), ce traitement dépassait
    souvent le délai d'attente du worker (~30s) — Gunicorn tuait alors le worker en plein
    milieu de l'écrasement du fichier school.db, ce qui provoquait à la fois une erreur
    "Internal Server Error" côté navigateur ET, parfois, une base à moitié restaurée.
    Maintenant ce travail tourne dans un thread séparé (même principe que la sauvegarde
    manuelle, voir `_sauvegarde_manuelle_arriere_plan`) : la requête répond IMMÉDIATEMENT
    par une redirection, qui tombe directement sur la page d'attente "Restauration en
    cours…" (voir `bloquer_pendant_restauration`, déclenchée tant que RESTAURATION_EN_COURS
    est actif) — laquelle se rafraîchit seule jusqu'à la fin du traitement."""
    # ⚡ Sécurité : on sauvegarde l'état ACTUEL avant de l'écraser, et on l'envoie aussi sur
    # R2 — si la version choisie pour la restauration s'avère être une erreur, rien n'est
    # perdu : l'état d'avant-restauration reste disponible dans "Sauvegardes manuelles".
    try:
        chemin_avant, _taille = creer_sauvegarde_locale(BACKUP_DIR_MANUEL, 'avant_restauration', inclure_uploads=False)
        if chemin_avant:
            _purger_anciennes_sauvegardes(BACKUP_DIR_MANUEL, BACKUP_RETENTION_MANUEL)
            uploader_vers_cloudflare(chemin_avant, 'sauvegardes/manuel', 'avant_restauration',
                                      garder_n_r2=BACKUP_RETENTION_MANUEL)
    except Exception:
        pass  # la sauvegarde de sécurité ne doit pas bloquer la restauration demandée

    # Le verrou de restauration (RESTAURATION_EN_COURS) est déjà actif à ce stade (posé par
    # la route AVANT de démarrer ce thread). On met aussi en pause le scheduler (sauvegardes
    # automatiques 2min/15h) pour qu'il n'ouvre pas non plus de connexion pendant l'écrasement
    # du fichier. Sans ça, une connexion ouverte entre la suppression des fichiers -wal/-shm et
    # l'extraction du zip pouvait recréer un WAL désynchronisé du nouveau school.db → base
    # corrompue → crash de toutes les requêtes suivantes ("external error" sur Render).
    try:
        scheduler.pause()
    except Exception:
        pass

    client = _client_r2()
    bucket = os.environ.get('CLOUDFLARE_R2_BUCKET')
    tmp_zip = os.path.join(os.path.dirname(__file__), '_restore_manuel_tmp.zip')
    # 🩹 CORRECTIF (2026-09) — BUG CRITIQUE : "restaurer une sauvegarde plante le site". Cette
    # fonction extrayait auparavant `cle` PAR-DESSUS school.db SANS AUCUNE vérification. Si la
    # sauvegarde choisie était elle-même corrompue (ex. une sauvegarde ancienne, faite avant le
    # correctif "copie cohérente via VACUUM INTO" plus haut, ou une sauvegarde dont le zip a été
    # tronqué pendant l'upload), on se retrouvait avec un school.db "database disk image is
    # malformed" appliqué en production, sans le moindre message d'erreur ni recours — d'où le
    # site qui "s'arrête de fonctionner" juste après une restauration. On garde maintenant de
    # côté l'ancien school.db AVANT de l'écraser, on vérifie l'intégrité de celui qu'on vient
    # de restaurer, et si le contrôle échoue on revient automatiquement à l'ancien fichier au
    # lieu de laisser une base corrompue active.
    ancien_chemin_secours = None
    if os.path.exists(DB_PATH):
        ancien_chemin_secours = DB_PATH + '.avant_restauration_manuelle_secours'
        try:
            shutil.copy2(DB_PATH, ancien_chemin_secours)
        except Exception:
            ancien_chemin_secours = None  # tant pis, pas de filet de secours possible

    try:
        client.download_file(bucket, cle, tmp_zip)

        # 🩹 EXTRACTION SÛRE (2026-10) : avant, `zf.extractall(...)` réécrivait school.db EN PLACE
        # (même inode que celui ouvert par d'éventuelles connexions en cours) et pouvait aussi
        # écrire n'importe quel chemin du zip. Maintenant :
        #   1) school.db est extrait dans un fichier TEMPORAIRE voisin, jamais directement ;
        #   2) son intégrité est vérifiée AVANT d'y toucher la base active ;
        #   3) seulement alors, os.replace() le substitue atomiquement à school.db ;
        #   4) seuls school.db et les dossiers d'uploads connus (anciens zips manuels qui en
        #      contenaient) sont extraits — tout autre chemin est ignoré.
        dossier_app = os.path.dirname(os.path.abspath(__file__))
        db_tmp = DB_PATH + '.restore_tmp'
        racines_uploads = {os.path.basename(d) for d in _dossiers_uploads_pour_sauvegarde()}
        with zipfile.ZipFile(tmp_zip, 'r') as zf:
            noms_zip = zf.namelist()
            if 'school.db' not in noms_zip:
                raise RuntimeError(f"La sauvegarde {cle} ne contient pas de fichier school.db.")
            with zf.open('school.db') as src_db, open(db_tmp, 'wb') as dst_db:
                shutil.copyfileobj(src_db, dst_db)
            for nom_membre in noms_zip:
                if nom_membre.endswith('/') or nom_membre == 'school.db':
                    continue
                racine = nom_membre.replace('\\', '/').split('/')[0]
                cible = os.path.abspath(os.path.join(dossier_app, nom_membre))
                if racine not in racines_uploads or not cible.startswith(dossier_app + os.sep):
                    continue  # chemin inconnu ou tentative de sortie du dossier : ignoré
                os.makedirs(os.path.dirname(cible), exist_ok=True)
                with zf.open(nom_membre) as src_f, open(cible, 'wb') as dst_f:
                    shutil.copyfileobj(src_f, dst_f)
        os.remove(tmp_zip)

        _verif = sqlite3.connect(db_tmp)
        try:
            _resultat_integrite = _verif.execute("PRAGMA integrity_check").fetchone()[0]
        finally:
            _verif.close()
        if _resultat_integrite != 'ok':
            try:
                os.remove(db_tmp)
            except Exception:
                pass
            message_erreur = (f"Sauvegarde {cle} corrompue (integrity_check : {_resultat_integrite}) "
                               f"— restauration annulée, la base actuelle n'a PAS été modifiée.")
            _log_sauvegarde('restauration_manuelle', 'erreur', fichier=cle, message=message_erreur)
            print(f"  ❌  {message_erreur}")
            return
        # Base valide : on supprime WAL/SHM puis on substitue atomiquement.
        for suffixe in ('-wal', '-shm'):
            f = DB_PATH + suffixe
            if os.path.exists(f):
                os.remove(f)
        os.replace(db_tmp, DB_PATH)
        _resultat_integrite = 'ok'
        if _resultat_integrite != 'ok':
            if ancien_chemin_secours and os.path.exists(ancien_chemin_secours):
                for suffixe in ('-wal', '-shm'):
                    f = DB_PATH + suffixe
                    if os.path.exists(f):
                        os.remove(f)
                shutil.copy2(ancien_chemin_secours, DB_PATH)
                message_erreur = (f"Sauvegarde {cle} corrompue (integrity_check : {_resultat_integrite}) "
                                   f"— restauration annulée, l'ancienne base a été remise en place.")
            else:
                message_erreur = (f"Sauvegarde {cle} corrompue (integrity_check : {_resultat_integrite}) "
                                   f"— AUCUN filet de secours disponible, school.db reste dans l'état corrompu.")
            _log_sauvegarde('restauration_manuelle', 'erreur', fichier=cle, message=message_erreur)
            print(f"  ❌  {message_erreur}")
            return

        # 🩹 CORRECTIF : on rejoue immédiatement toutes les migrations de schéma sur la base
        # fraîchement restaurée. Si la sauvegarde restaurée est ancienne (schéma incomplet,
        # ex. table sous_matieres sans colonne "coefficient"), le schéma est réparé tout de
        # suite — plus besoin d'attendre un redémarrage manuel du service Render, et la page
        # Analyse (/analyse-notes) ne plante plus juste après une restauration.
        try:
            erreurs_migration = rejouer_toutes_migrations_apres_restauration()
            if erreurs_migration:
                _log_sauvegarde('restauration_manuelle', 'erreur', fichier=cle,
                                message="Migrations en erreur après restauration : " + " | ".join(erreurs_migration)[:900])
        except Exception as ex_migration:
            print(f"  ⚠️  Erreur lors du rejeu des migrations après restauration : {ex_migration}")

        # 🆕 Registre de l'état des notifications : la restauration manuelle est un choix de l'admin,
        # le registre doit donc refléter la base restaurée (sinon il serait ré-appliqué au redémarrage).
        try:
            _notif_etat_synchroniser(force=True)
        except Exception:
            pass

        # 🩹 CORRECTIF (2026-09) — BUG CRITIQUE : "restaurer une sauvegarde annule tout au
        # prochain redémarrage". _restaurer_depuis_r2_si_necessaire() (tout en haut du fichier,
        # exécutée à CHAQUE démarrage/redéploiement) choisit toujours l'objet R2 le PLUS RÉCENT
        # (LastModified) parmi TOUS les préfixes (2min/quotidien_15h/manuel) — y compris le
        # snapshot de sécurité "avant_restauration" qu'on vient d'uploader QUELQUES SECONDES
        # PLUS TÔT dans cette même fonction, juste avant de télécharger `cle`. Comme ce snapshot
        # de sécurité est horodaté "maintenant" (donc plus récent que la sauvegarde `cle` qu'on
        # restaure, qui est forcément plus ancienne), il redevient "le plus récent objet R2" ---
        # et le PROCHAIN redémarrage de l'app sur Render (déploiement, veille/réveil, crash...)
        # écrase silencieusement la restauration qu'on vient de faire pour revenir à l'état
        # d'AVANT la restauration. Résultat côté utilisateur : la restauration semble "ne pas
        # tenir" / l'app "s'arrête de fonctionner" dès que le service redémarre.
        # ✅ Solution : on ré-uploade immédiatement, APRÈS avoir appliqué `cle`, un nouveau
        # snapshot du contenu qu'on vient de restaurer, horodaté à cet instant précis — il
        # devient ainsi le nouvel objet "le plus récent" sur R2, et un redémarrage ultérieur
        # restaurera bien l'état voulu (celui de `cle`) plutôt que l'ancien "avant_restauration".
        try:
            chemin_post, _taille_post = creer_sauvegarde_locale(BACKUP_DIR_MANUEL, 'post_restauration', inclure_uploads=False)
            if chemin_post:
                _purger_anciennes_sauvegardes(BACKUP_DIR_MANUEL, BACKUP_RETENTION_MANUEL)
                uploader_vers_cloudflare(chemin_post, 'sauvegardes/manuel', 'post_restauration',
                                          garder_n_r2=BACKUP_RETENTION_MANUEL)
        except Exception as ex_post:
            print(f"  ⚠️  Échec de l'envoi du snapshot post-restauration (la restauration "
                  f"pourrait être annulée au prochain redémarrage) : {ex_post}")

        _log_sauvegarde('restauration_manuelle', 'succes', fichier=cle, message=f"Restauration depuis {cle}")
    except Exception as e:
        _log_sauvegarde('restauration_manuelle', 'erreur', fichier=cle, message=str(e))
        print(f"  ⚠️  Erreur lors de la restauration manuelle : {e}")
    finally:
        if ancien_chemin_secours and os.path.exists(ancien_chemin_secours):
            try:
                os.remove(ancien_chemin_secours)
            except Exception:
                pass
        # 🩹 On relâche systématiquement le verrou et on relance le scheduler, même en cas
        # d'erreur : sinon l'application resterait bloquée en "restauration en cours" pour
        # toujours (page d'attente sur toutes les routes).
        try:
            scheduler.resume()
        except Exception:
            pass
        RESTAURATION_EN_COURS.clear()


@app.route('/admin/sauvegardes/restaurer', methods=['POST'])
@login_required
@role_required('admin')
def admin_sauvegardes_restaurer():
    cle = (request.form.get('cle') or '').strip()
    confirmation = (request.form.get('confirmation') or '').strip().upper()

    if not cle:
        flash("Aucune sauvegarde sélectionnée.", "error")
        return redirect(url_for('admin_sauvegardes'))
    if confirmation != 'RESTAURER':
        flash("Restauration annulée : le mot de confirmation saisi est incorrect.", "error")
        return redirect(url_for('admin_sauvegardes'))
    if not cloudflare_est_configure():
        flash("Cloudflare R2 n'est pas configuré.", "error")
        return redirect(url_for('admin_sauvegardes'))
    if RESTAURATION_EN_COURS.is_set():
        flash("Une restauration est déjà en cours, merci de patienter quelques instants.", "error")
        return redirect(url_for('admin_sauvegardes'))

    client = _client_r2()
    bucket = os.environ.get('CLOUDFLARE_R2_BUCKET')
    if not client:
        flash("Impossible de se connecter à Cloudflare R2.", "error")
        return redirect(url_for('admin_sauvegardes'))

    # 🩹 CORRECTIF : on active le verrou de restauration ICI, AVANT de démarrer le thread —
    # donc avant même de toucher au fichier school.db. Toute requête HTTP entrante (y compris
    # la redirection ci-dessous, et un éventuel double-clic sur "Restaurer") reçoit
    # immédiatement la page d'attente tant que le verrou est actif (voir
    # `bloquer_pendant_restauration`). Le vrai travail (téléchargement + extraction +
    # migrations) se fait ensuite dans `_restauration_arriere_plan`, dans un thread séparé,
    # pour ne jamais bloquer le worker Gunicorn au point de le faire tuer par timeout.
    RESTAURATION_EN_COURS.set()
    threading.Thread(target=_restauration_arriere_plan, args=(cle,), daemon=True).start()
    return redirect(url_for('admin_sauvegardes'))


# 🆕 Page de diagnostic : montre l'état réel de school.db et des sauvegardes R2, et surtout
# QUEL objet R2 serait choisi par _restaurer_depuis_r2_si_necessaire() au PROCHAIN redémarrage
# de l'app — c'est précisément cette confusion (l'objet le plus récent n'étant pas toujours
# celui qu'on croit) qui causait l'impression que "restaurer casse l'app".
@app.route('/admin/diagnostic-db', methods=['GET'])
@login_required
@role_required('admin')
def admin_diagnostic_db():
    infos = {
        'db_locale': {'existe': os.path.exists(DB_PATH)},
        'restauration_en_cours': RESTAURATION_EN_COURS.is_set(),
        'r2_configure': cloudflare_est_configure(),
    }
    if infos['db_locale']['existe']:
        stat = os.stat(DB_PATH)
        infos['db_locale']['taille'] = _taille_lisible(stat.st_size)
        infos['db_locale']['modifie_le'] = datetime.datetime.fromtimestamp(stat.st_mtime).strftime('%d/%m/%Y %H:%M:%S')
        try:
            conn = sqlite3.connect(DB_PATH)
            infos['db_locale']['integrity_check'] = conn.execute("PRAGMA integrity_check").fetchone()[0]
            conn.close()
        except Exception as e:
            infos['db_locale']['integrity_check'] = f"erreur : {e}"

    infos['candidat_prochain_demarrage'] = None
    infos['objets_r2'] = []
    if infos['r2_configure']:
        try:
            client = _client_r2()
            bucket = os.environ.get('CLOUDFLARE_R2_BUCKET')
            tous_objets = []
            for prefixe in ('sauvegardes/2min/', 'sauvegardes/quotidien_15h/', 'sauvegardes/manuel/'):
                reponse = client.list_objects_v2(Bucket=bucket, Prefix=prefixe)
                tous_objets.extend(reponse.get('Contents', []))
            tous_objets_tries = sorted(tous_objets, key=lambda o: o['LastModified'], reverse=True)
            infos['objets_r2'] = [{
                'cle': o['Key'],
                'modifie_le': o['LastModified'].strftime('%d/%m/%Y %H:%M:%S'),
                'taille': _taille_lisible(o['Size']),
                'serait_ignore_au_demarrage': 'avant_restauration' in o['Key'],
            } for o in tous_objets_tries[:20]]
            candidats_valides = [o for o in tous_objets_tries if 'avant_restauration' not in o['Key']]
            if candidats_valides:
                c = candidats_valides[0]
                infos['candidat_prochain_demarrage'] = f"{c['Key']} (modifié le {c['LastModified'].strftime('%d/%m/%Y %H:%M:%S')})"
        except Exception as e:
            infos['erreur_r2'] = str(e)

    html_lignes = ['<h1>🩺 Diagnostic base de données</h1>',
                   f"<p><b>school.db local</b> : {infos['db_locale']}</p>",
                   f"<p><b>Restauration en cours</b> : {infos['restauration_en_cours']}</p>",
                   f"<p><b>Cloudflare R2 configuré</b> : {infos['r2_configure']}</p>",
                   f"<p><b>Objet qui serait restauré au prochain redémarrage</b> : {infos['candidat_prochain_demarrage']}</p>",
                   '<h2>Sauvegardes R2 (20 plus récentes, tous préfixes)</h2>', '<ul>']
    for o in infos['objets_r2']:
        ignore = ' — <i>ignoré au démarrage auto (snapshot de sécurité)</i>' if o['serait_ignore_au_demarrage'] else ''
        html_lignes.append(f"<li>{html.escape(o['cle'])} — {o['modifie_le']} — {o['taille']}{ignore}</li>")
    html_lignes.append('</ul>')
    if request.args.get('format') == 'json':
        return jsonify(infos)
    return render_template_string(''.join(html_lignes))


