def upgrade_db_communications():
    conn = get_db()
    conn.execute("""
        CREATE TABLE IF NOT EXISTS communications (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            titre TEXT NOT NULL,
            contenu TEXT NOT NULL,
            type TEXT DEFAULT 'info',
            priorite TEXT DEFAULT 'normale',
            statut TEXT DEFAULT 'publie',
            toutes_classes INTEGER DEFAULT 0,
            epingle INTEGER DEFAULT 0,
            date_publication TEXT,
            auteur_id INTEGER REFERENCES users(id),
            notif_envoyee INTEGER DEFAULT 0,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS communication_classes (
            communication_id INTEGER NOT NULL REFERENCES communications(id) ON DELETE CASCADE,
            classe_id INTEGER NOT NULL REFERENCES classes(id) ON DELETE CASCADE,
            PRIMARY KEY (communication_id, classe_id)
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS communication_fichiers (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            communication_id INTEGER NOT NULL REFERENCES communications(id) ON DELETE CASCADE,
            type_fichier TEXT NOT NULL,
            nom_original TEXT,
            nom_fichier TEXT,
            url_externe TEXT,
            libelle TEXT,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS communication_lectures (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            communication_id INTEGER NOT NULL REFERENCES communications(id) ON DELETE CASCADE,
            user_id INTEGER NOT NULL REFERENCES users(id),
            role TEXT,
            lu_at TEXT DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(communication_id, user_id)
        )
    """)
    # 🆕 « J'aime » sur une publication
    conn.execute("""
        CREATE TABLE IF NOT EXISTS communication_likes (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            communication_id INTEGER NOT NULL REFERENCES communications(id) ON DELETE CASCADE,
            user_id INTEGER NOT NULL REFERENCES users(id),
            created_at TEXT DEFAULT CURRENT_TIMESTAMP,
            UNIQUE(communication_id, user_id)
        )
    """)
    # 🆕 Commentaires sur une publication
    conn.execute("""
        CREATE TABLE IF NOT EXISTS communication_commentaires (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            communication_id INTEGER NOT NULL REFERENCES communications(id) ON DELETE CASCADE,
            user_id INTEGER NOT NULL REFERENCES users(id),
            role TEXT,
            contenu TEXT NOT NULL,
            created_at TEXT DEFAULT CURRENT_TIMESTAMP
        )
    """)
    try:
        conn.execute("CREATE INDEX IF NOT EXISTS idx_comm_classes_comm ON communication_classes(communication_id)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_comm_lectures_comm ON communication_lectures(communication_id)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_comm_likes_comm ON communication_likes(communication_id)")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_comm_commentaires_comm ON communication_commentaires(communication_id)")
    except sqlite3.OperationalError:
        pass
    conn.commit()
    conn.close()


upgrade_db_communications()


def upgrade_db_communications_audience():
    """🆕 Audience d'une communication : 'generale' (destinée aux parents) ou 'pro'
    (communication professionnelle, destinée uniquement aux enseignants).
    Les communications existantes restent 'generale'."""
    conn = get_db()
    try:
        conn.execute("ALTER TABLE communications ADD COLUMN audience TEXT DEFAULT 'generale'")
    except Exception:
        pass
    try:
        conn.execute("UPDATE communications SET audience='generale' WHERE audience IS NULL OR audience=''")
    except Exception:
        pass
    conn.commit()
    conn.close()


upgrade_db_communications_audience()


def _comm_audience(comm):
    try:
        return 'pro' if (comm['audience'] or 'generale') == 'pro' else 'generale'
    except Exception:
        return 'generale'


def _comm_parents_cibles(conn, comm):
    """Retourne la liste des ID des parents concernés par une communication
    (tous les parents si diffusion « toute l'école », sinon uniquement les parents
    dont au moins un enfant est dans une des classes ciblées)."""
    if _comm_audience(comm) == 'pro':
        return []  # communication professionnelle : jamais destinée aux parents
    if comm['toutes_classes']:
        rows = conn.execute("SELECT DISTINCT parent_id FROM eleves WHERE parent_id IS NOT NULL").fetchall()
    else:
        rows = conn.execute("""
            SELECT DISTINCT e.parent_id FROM eleves e
            JOIN communication_classes cc ON cc.classe_id = e.classe_id
            WHERE cc.communication_id=? AND e.parent_id IS NOT NULL
        """, (comm['id'],)).fetchall()
    return [r['parent_id'] for r in rows]


def _comm_enseignants_cibles(conn, comm):
    """Retourne la liste des ID des enseignants concernés (professeurs principaux ou
    de matière des classes ciblées, ou tous les enseignants si diffusion école entière).
    Une communication « générale » (destinée aux parents) ne notifie pas les enseignants."""
    if _comm_audience(comm) != 'pro':
        return []
    if comm['toutes_classes']:
        rows = conn.execute("SELECT id FROM users WHERE role='enseignant'").fetchall()
        return [r['id'] for r in rows]
    rows = conn.execute("""
        SELECT enseignant_id as id FROM classe_profs WHERE classe_id IN
            (SELECT classe_id FROM communication_classes WHERE communication_id=?)
        UNION
        SELECT enseignant_id as id FROM matieres WHERE enseignant_id IS NOT NULL AND classe_id IN
            (SELECT classe_id FROM communication_classes WHERE communication_id=?)
    """, (comm['id'], comm['id'])).fetchall()
    return [r['id'] for r in rows if r['id']]


def _comm_enseignants_cibles_pro(conn, comm):
    """Enseignants visés par une communication professionnelle (stats de lecture admin)."""
    if comm['toutes_classes']:
        return [r['id'] for r in conn.execute("SELECT id FROM users WHERE role='enseignant'").fetchall()]
    rows = conn.execute("""
        SELECT enseignant_id as id FROM classe_profs WHERE classe_id IN
            (SELECT classe_id FROM communication_classes WHERE communication_id=?)
        UNION
        SELECT enseignant_id as id FROM matieres WHERE enseignant_id IS NOT NULL AND classe_id IN
            (SELECT classe_id FROM communication_classes WHERE communication_id=?)
    """, (comm['id'], comm['id'])).fetchall()
    return [r['id'] for r in rows if r['id']]


def communication_notifier_publication(conn, comm_id):
    """Envoie une notification in-app à chaque parent et enseignant concerné, une seule fois."""
    comm = conn.execute("SELECT * FROM communications WHERE id=?", (comm_id,)).fetchone()
    if not comm or comm['notif_envoyee']:
        return
    lib = LABELS_TYPE_COMMUNICATION.get(comm['type'], '📢 Communication')
    icone = lib.split(' ')[0]
    lib_txt = lib.split(' ', 1)[1] if ' ' in lib else 'Communication'
    extrait = _notif_extrait(comm['contenu'])
    msg = f"{icone} Nouvelle communication « {comm['titre']} »" + (f" — {extrait}" if extrait else "")
    important = (comm['priorite'] or '') in ('importante', 'urgente') or comm['type'] == 'urgent'
    destinataires = set(_comm_parents_cibles(conn, comm)) | set(_comm_enseignants_cibles(conn, comm))
    for uid in destinataires:
        notif_to_parent(uid, msg, conn, categorie='communication', titre=lib_txt,
                        url=f"/communications/{comm['id']}",
                        meta={'ico': icone, 'couleur': COULEURS_TYPE_COMMUNICATION.get(comm['type'], '#7C3AED'),
                              'cta': 'Lire la communication'},
                        prio='haute' if important else 'normale',
                        push_corps=comm['titre'] + (f"\n{extrait}" if extrait else ""))
    conn.execute("UPDATE communications SET notif_envoyee=1 WHERE id=?", (comm_id,))


def communications_publier_programmees(conn):
    """Publie automatiquement les communications programmées dont l'heure est arrivée
    (appelé à chaque chargement de la page, pas besoin d'un scheduler dédié)."""
    maintenant = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    a_publier = conn.execute(
        "SELECT id FROM communications WHERE statut='programme' AND date_publication <= ?", (maintenant,)
    ).fetchall()
    for c in a_publier:
        conn.execute("UPDATE communications SET statut='publie' WHERE id=?", (c['id'],))
        communication_notifier_publication(conn, c['id'])
    if a_publier:
        conn.commit()


@app.route('/communications', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'agent_admin', 'enseignant', 'parent')
def communications():
    conn = get_db()
    role = session['role']
    peut_editer = role in ('admin', 'agent_admin')

    # 🆕 Parent : « Tout marquer comme lu » (publications publiées visibles par ce parent, pas encore lues)
    if request.method == 'POST' and role in ('parent', 'enseignant') and request.form.get('action') == 'tout_marquer_lu':
        _esp_post = request.form.get('espace', '') if role == 'enseignant' else 'generale'
        try:
            _cls_ids = [c['id'] for c in _devoir_classes_accessibles(conn, role, session['user_id'])]
            _cond = "co.toutes_classes=1"
            if _cls_ids:
                _cond += f" OR co.id IN (SELECT communication_id FROM communication_classes WHERE classe_id IN ({','.join('?' * len(_cls_ids))}))"
            _aud_sql = ("AND COALESCE(co.audience,'generale')='pro'" if _esp_post == 'pro'
                        else "AND COALESCE(co.audience,'generale')!='pro'" if _esp_post == 'generale' else '')
            _ids_nl = [r['id'] for r in conn.execute(
                f"""SELECT co.id FROM communications co
                    WHERE co.statut='publie' AND ({_cond}) {_aud_sql}
                      AND NOT EXISTS (SELECT 1 FROM communication_lectures cl WHERE cl.communication_id=co.id AND cl.user_id=?)""",
                _cls_ids + [session['user_id']]).fetchall()]
            _maintenant = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
            for _cid in _ids_nl:
                conn.execute("INSERT OR IGNORE INTO communication_lectures (communication_id, user_id, role, lu_at) VALUES (?,?,?,?)",
                             (_cid, session['user_id'], role, _maintenant))
            conn.commit()
            flash(f"{len(_ids_nl)} publication{'s' if len(_ids_nl) > 1 else ''} marquée{'s' if len(_ids_nl) > 1 else ''} comme lue{'s' if len(_ids_nl) > 1 else ''}.", "success")
        except Exception:
            flash("Impossible de marquer les publications comme lues.", "error")
        conn.close()
        return redirect(url_for('communications', espace=(_esp_post if role == 'enseignant' and _esp_post in ('pro', 'generale') else None)))

    # ═══ POST : créer / modifier / publier / épingler / archiver / supprimer (admin uniquement) ═══
    if request.method == 'POST':
        if not peut_editer:
            flash("Action non autorisée.", "error")
            conn.close()
            return redirect(url_for('communications'))

        action = request.form.get('action')

        if action in ('add', 'edit'):
            comm_id = request.form.get('comm_id') if action == 'edit' else None
            titre = request.form.get('titre', '').strip()
            contenu = request.form.get('contenu', '').strip()
            type_comm = request.form.get('type') if request.form.get('type') in TYPES_COMMUNICATION else 'info'
            priorite = request.form.get('priorite') if request.form.get('priorite') in PRIORITES_COMMUNICATION else 'normale'
            audience = request.form.get('audience')
            toutes_classes = 1 if request.form.get('toutes_classes') == 'on' else 0
            classes_ids = [c for c in request.form.getlist('classes_ids') if c]
            epingle = 1 if request.form.get('epingle') == 'on' else 0
            date_pub_input = request.form.get('date_publication') or ''
            heure_pub_input = request.form.get('heure_publication') or '08:00'
            mode_publication = request.form.get('publication', 'maintenant')

            if not titre or not contenu:
                flash("Le titre et le contenu sont obligatoires.", "error")
                conn.close()
                return redirect(url_for('communications'))
            if audience not in ('pro', 'generale'):
                flash("Choisissez le type de communication : professionnelle (enseignants) ou générale (parents).", "error")
                conn.close()
                return redirect(url_for('communications'))
            if not toutes_classes and not classes_ids:
                flash("Choisissez « Toute l'école » ou au moins une classe destinataire.", "error")
                conn.close()
                return redirect(url_for('communications'))

            maintenant_dt = datetime.datetime.now()
            if mode_publication == 'brouillon':
                statut = 'brouillon'
                dt_pub = maintenant_dt
            elif mode_publication == 'programmee' and date_pub_input:
                try:
                    dt_pub = datetime.datetime.strptime(f"{date_pub_input} {heure_pub_input}", '%Y-%m-%d %H:%M')
                except ValueError:
                    dt_pub = maintenant_dt
                statut = 'programme' if dt_pub > maintenant_dt else 'publie'
            else:
                statut = 'publie'
                dt_pub = maintenant_dt

            date_publication_str = dt_pub.strftime('%Y-%m-%d %H:%M:%S')
            now_str = maintenant_dt.strftime('%Y-%m-%d %H:%M:%S')

            if action == 'add':
                cur = conn.execute("""
                    INSERT INTO communications (titre, contenu, type, priorite, statut, toutes_classes, epingle,
                                                 date_publication, auteur_id, created_at, updated_at, audience)
                    VALUES (?,?,?,?,?,?,?,?,?,?,?,?)
                """, (titre, contenu, type_comm, priorite, statut, toutes_classes, epingle,
                      date_publication_str, session['user_id'], now_str, now_str, audience))
                comm_id = cur.lastrowid
            else:
                existante = conn.execute("SELECT * FROM communications WHERE id=?", (comm_id,)).fetchone()
                if not existante:
                    flash("Communication introuvable.", "error")
                    conn.close()
                    return redirect(url_for('communications'))
                # Une communication déjà publiée le reste (on ne la repasse pas en brouillon/programmée)
                if existante['statut'] == 'publie':
                    statut = 'publie'
                    date_publication_str = existante['date_publication']
                conn.execute("""
                    UPDATE communications SET titre=?, contenu=?, type=?, priorite=?, statut=?, toutes_classes=?,
                           epingle=?, date_publication=?, updated_at=?, audience=?
                    WHERE id=?
                """, (titre, contenu, type_comm, priorite, statut, toutes_classes, epingle,
                      date_publication_str, now_str, audience, comm_id))
                conn.execute("DELETE FROM communication_classes WHERE communication_id=?", (comm_id,))

            if not toutes_classes:
                for cid in classes_ids:
                    conn.execute("INSERT OR IGNORE INTO communication_classes (communication_id, classe_id) VALUES (?,?)",
                                 (comm_id, cid))

            # Pièces jointes (fichiers)
            for f in request.files.getlist('fichiers'):
                if f and f.filename:
                    ext = f.filename.rsplit('.', 1)[-1].lower() if '.' in f.filename else ''
                    if ext in ALLOWED_COMM_EXTENSIONS:
                        original = secure_filename(f.filename)
                        ts = datetime.datetime.now().strftime('%Y%m%d%H%M%S%f')
                        nom_fichier = f"comm_{ts}_{original}"
                        _sauvegarder_image_compressee(f, os.path.join(UPLOAD_FOLDER_COMMUNICATIONS, nom_fichier), max_dimension=1800, qualite=84)
                        conn.execute("""INSERT INTO communication_fichiers (communication_id, type_fichier, nom_original, nom_fichier)
                                         VALUES (?,?,?,?)""",
                                     (comm_id, type_fichier_depuis_extension(original), original, nom_fichier))
                    else:
                        flash(f"Fichier « {f.filename} » ignoré : extension .{ext} non autorisée.", "error")

            # Liens / ressources externes
            for label, url in zip(request.form.getlist('lien_label[]'), request.form.getlist('lien_url[]')):
                url = url.strip()
                if url:
                    conn.execute("""INSERT INTO communication_fichiers (communication_id, type_fichier, libelle, url_externe)
                                     VALUES (?, 'lien', ?, ?)""", (comm_id, label.strip() or url, url))

            if statut == 'publie':
                communication_notifier_publication(conn, comm_id)

            conn.commit()
            libelle_statut = {'brouillon': 'enregistrée en brouillon', 'programme': 'programmée',
                               'publie': 'publiée'}[statut]
            flash(f'Communication "{titre}" {libelle_statut} avec succès !', 'success')

        elif action == 'publier_maintenant':
            comm_id = request.form.get('comm_id')
            c = conn.execute("SELECT * FROM communications WHERE id=?", (comm_id,)).fetchone()
            if c:
                conn.execute("UPDATE communications SET statut='publie', date_publication=? WHERE id=?",
                             (datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S'), comm_id))
                communication_notifier_publication(conn, comm_id)
                conn.commit()
                flash("Communication publiée immédiatement.", "success")

        elif action == 'toggle_epingle':
            comm_id = request.form.get('comm_id')
            c = conn.execute("SELECT epingle FROM communications WHERE id=?", (comm_id,)).fetchone()
            if c:
                conn.execute("UPDATE communications SET epingle=? WHERE id=?", (0 if c['epingle'] else 1, comm_id))
                conn.commit()

        elif action == 'archiver':
            comm_id = request.form.get('comm_id')
            conn.execute("UPDATE communications SET statut='archive' WHERE id=?", (comm_id,))
            conn.commit()
            flash("Communication archivée.", "success")

        elif action == 'desarchiver':
            comm_id = request.form.get('comm_id')
            conn.execute("UPDATE communications SET statut='publie' WHERE id=?", (comm_id,))
            conn.commit()
            flash("Communication restaurée dans les publiées.", "success")

        elif action == 'delete':
            comm_id = request.form.get('comm_id')
            for fl in conn.execute("SELECT * FROM communication_fichiers WHERE communication_id=?", (comm_id,)).fetchall():
                if fl['nom_fichier']:
                    p = os.path.join(UPLOAD_FOLDER_COMMUNICATIONS, fl['nom_fichier'])
                    if os.path.exists(p):
                        try:
                            os.remove(p)
                        except OSError:
                            pass
            conn.execute("DELETE FROM communication_fichiers WHERE communication_id=?", (comm_id,))
            conn.execute("DELETE FROM communication_classes WHERE communication_id=?", (comm_id,))
            conn.execute("DELETE FROM communication_lectures WHERE communication_id=?", (comm_id,))
            conn.execute("DELETE FROM communication_likes WHERE communication_id=?", (comm_id,))
            conn.execute("DELETE FROM communication_commentaires WHERE communication_id=?", (comm_id,))
            conn.execute("DELETE FROM communications WHERE id=?", (comm_id,))
            conn.commit()
            flash("Communication supprimée.", "success")

        conn.close()
        return redirect(url_for('communications'))

    # ═══ GET : liste + filtres + statistiques ═══
    communications_publier_programmees(conn)

    classes = _devoir_classes_accessibles(conn, role, session['user_id'])
    classe_ids_access = [c['id'] for c in classes]

    # 🆕 Audience : 'pro' = communication professionnelle (enseignants uniquement),
    # 'generale' = communication destinée aux parents. Le parent ne voit jamais les 'pro'.
    espace = request.args.get('espace', '')
    if role == 'enseignant' and espace not in ('pro', 'generale'):
        # Hub d'accueil : l'enseignant choisit d'abord son espace.
        _cond_h = "co.statut='publie' AND (co.toutes_classes=1"
        _prm_h = []
        if classe_ids_access:
            _cond_h += f" OR co.id IN (SELECT communication_id FROM communication_classes WHERE classe_id IN ({','.join('?' * len(classe_ids_access))}))"
            _prm_h += classe_ids_access
        _cond_h += ")"
        hub = {}
        for _aud in ('pro', 'generale'):
            _flt = "COALESCE(co.audience,'generale')='pro'" if _aud == 'pro' else "COALESCE(co.audience,'generale')!='pro'"
            _tot = conn.execute(f"SELECT COUNT(*) FROM communications co WHERE {_cond_h} AND {_flt}", _prm_h).fetchone()[0]
            _nl = conn.execute(
                f"""SELECT COUNT(*) FROM communications co WHERE {_cond_h} AND {_flt}
                    AND NOT EXISTS (SELECT 1 FROM communication_lectures cl WHERE cl.communication_id=co.id AND cl.user_id=?)""",
                _prm_h + [session['user_id']]).fetchone()[0]
            hub[_aud] = {'total': _tot, 'non_lues': _nl}
        conn.close()
        return render_template_string(COMMUNICATIONS_HUB_HTML, hub=hub, notif_count=get_notif_count())
    if role == 'parent':
        espace = 'generale'
    elif espace not in ('pro', 'generale'):
        espace = ''

    q = request.args.get('q', '').strip()
    classe_filter = request.args.get('classe_id', '')
    type_filter = request.args.get('type', '')
    priorite_filter = request.args.get('priorite', '')
    statut_filter = request.args.get('statut', '') if peut_editer else ''
    lecture_filter = request.args.get('lecture', '') if peut_editer else ''
    tri = request.args.get('tri', 'recent')

    where_clauses = []
    params = []

    if not peut_editer:
        if classe_ids_access:
            ph = ','.join('?' * len(classe_ids_access))
            where_clauses.append(
                f"(co.toutes_classes=1 OR co.id IN (SELECT communication_id FROM communication_classes WHERE classe_id IN ({ph})))")
            params += classe_ids_access
        else:
            where_clauses.append("co.toutes_classes=1")
        where_clauses.append("co.statut='publie'")
    elif statut_filter:
        where_clauses.append("co.statut=?")
        params.append(statut_filter)
    else:
        where_clauses.append("co.statut != 'archive'")

    if espace == 'pro':
        where_clauses.append("COALESCE(co.audience,'generale')='pro'")
    elif espace == 'generale':
        where_clauses.append("COALESCE(co.audience,'generale')!='pro'")
    if q:
        where_clauses.append("(co.titre LIKE ? OR co.contenu LIKE ?)")
        params += [f"%{q}%", f"%{q}%"]
    if classe_filter:
        where_clauses.append(
            "(co.toutes_classes=1 OR co.id IN (SELECT communication_id FROM communication_classes WHERE classe_id=?))")
        params.append(classe_filter)
    if type_filter:
        where_clauses.append("co.type=?")
        params.append(type_filter)
    if priorite_filter:
        where_clauses.append("co.priorite=?")
        params.append(priorite_filter)
    if lecture_filter == 'lu':
        where_clauses.append("EXISTS(SELECT 1 FROM communication_lectures cl WHERE cl.communication_id=co.id)")
    elif lecture_filter == 'non_lu':
        where_clauses.append("NOT EXISTS(SELECT 1 FROM communication_lectures cl WHERE cl.communication_id=co.id)")

    where_sql = " AND ".join(where_clauses) if where_clauses else "1=1"

    order_map = {
        'recent': "co.epingle DESC, co.date_publication DESC",
        'ancien': "co.epingle DESC, co.date_publication ASC",
        'titre': "co.epingle DESC, co.titre COLLATE NOCASE ASC",
        'priorite': "co.epingle DESC, CASE co.priorite WHEN 'urgente' THEN 0 WHEN 'importante' THEN 1 ELSE 2 END, co.date_publication DESC",
    }
    order_sql = order_map.get(tri, order_map['recent'])

    lignes = conn.execute(f"""
        SELECT co.*, GROUP_CONCAT(DISTINCT cl.id || '::' || cl.nom || '::' || cl.niveau) as classes_concat,
               u.nom as auteur_nom, u.prenom as auteur_prenom,
               (SELECT COUNT(*) FROM communication_fichiers cf WHERE cf.communication_id=co.id) as nb_fichiers,
               (SELECT COUNT(*) FROM communication_likes cli WHERE cli.communication_id=co.id) as nb_likes,
               (SELECT COUNT(*) FROM communication_commentaires cco WHERE cco.communication_id=co.id) as nb_commentaires
        FROM communications co
        LEFT JOIN communication_classes cc ON cc.communication_id = co.id
        LEFT JOIN classes cl ON cc.classe_id = cl.id
        LEFT JOIN users u ON co.auteur_id = u.id
        WHERE {where_sql}
        GROUP BY co.id
        ORDER BY {order_sql}
    """, params).fetchall()

    # 🆕 Aperçu des pièces jointes (pour le slider : image en avant, sinon nom du fichier)
    comm_ids_all = [c['id'] for c in lignes]
    fichiers_par_comm = {}
    if comm_ids_all:
        ph_ids = ','.join('?' * len(comm_ids_all))
        for f in conn.execute(
                f"SELECT * FROM communication_fichiers WHERE communication_id IN ({ph_ids}) ORDER BY id",
                comm_ids_all).fetchall():
            fichiers_par_comm.setdefault(f['communication_id'], []).append(dict(f))

    comms_data = []
    for c in lignes:
        item = dict(c)
        item['classes_liste'] = _devoir_parse_classes_concat(c['classes_concat'])
        fichiers_c = fichiers_par_comm.get(c['id'], [])
        item['image_apercu'] = next((f for f in fichiers_c if f['type_fichier'] == 'image'), None)
        item['fichier_apercu'] = next((f for f in fichiers_c if f['type_fichier'] != 'image'), None)
        item['user_a_aime'] = conn.execute(
            "SELECT 1 FROM communication_likes WHERE communication_id=? AND user_id=?",
            (c['id'], session['user_id'])).fetchone() is not None
        if peut_editer:
            parents_cibles = _comm_enseignants_cibles_pro(conn, c) if _comm_audience(c) == 'pro' else _comm_parents_cibles(conn, c)
            nb_lu = 0
            lecteurs_noms = []
            if parents_cibles:
                ph = ','.join('?' * len(parents_cibles))
                nb_lu = conn.execute(
                    f"SELECT COUNT(DISTINCT user_id) FROM communication_lectures WHERE communication_id=? AND user_id IN ({ph})",
                    [c['id']] + parents_cibles).fetchone()[0]
                lecteurs_noms = [f"{r['prenom']} {r['nom']}" for r in conn.execute(
                    f"""SELECT u.prenom, u.nom FROM communication_lectures cl JOIN users u ON u.id=cl.user_id
                        WHERE cl.communication_id=? AND cl.user_id IN ({ph}) ORDER BY cl.lu_at DESC LIMIT 6""",
                    [c['id']] + parents_cibles).fetchall()]
            item['nb_destinataires'] = len(parents_cibles)
            item['nb_lu'] = nb_lu
            item['taux_lecture'] = round(100 * nb_lu / len(parents_cibles), 1) if parents_cibles else 0
            item['lecteurs_noms'] = lecteurs_noms
        else:
            item['lu'] = conn.execute(
                "SELECT 1 FROM communication_lectures WHERE communication_id=? AND user_id=?",
                (c['id'], session['user_id'])).fetchone() is not None
        comms_data.append(item)

    # 🆕 Slider « 5 dernières actualités » (aperçu, publications déjà publiées) + grille avec TOUTES les
    # communications (correspondant aux filtres) en dessous, comme demandé.
    # 🆕 Le slider "À la une" affiche désormais TOUTES les actualités publiées (pas juste les 5
    # dernières), pour que le parent/l'enseignant puisse tout parcourir directement depuis le slider.
    # 🆕 Vue PARENT (mobile) : contexte « Communications » V2 — progression de lecture, publications ciblant
    # ses enfants, temps de lecture, ancienneté relative, regroupement par période et sélection « À ne pas manquer ».
    parent_ctx = None
    if role in ('parent', 'enseignant'):
        # 🆕 Le même contexte (périodes, « À la une », types, progression de lecture) sert aussi à la
        # vue mobile enseignant : seuls les enfants sont propres au parent.
        try:
            _kids = [dict(r) for r in conn.execute(
                "SELECT id, prenom, classe_id FROM eleves WHERE parent_id=? ORDER BY prenom", (session['user_id'],)).fetchall()] if role == 'parent' else []
        except Exception:
            _kids = []
        _now = datetime.datetime.now()
        _auj_p = _now.date()
        _mois_courts = ['janv.', 'févr.', 'mars', 'avr.', 'mai', 'juin', 'juil.', 'août', 'sept.', 'oct.', 'nov.', 'déc.']
        _pub = [c for c in comms_data if c['statut'] == 'publie']
        _dts = {}
        for c in _pub:
            _raw = str(c.get('date_publication') or '')
            try:
                _dt = datetime.datetime.strptime(_raw[:19], '%Y-%m-%d %H:%M:%S')
            except Exception:
                try:
                    _dt = datetime.datetime.strptime(_raw[:10], '%Y-%m-%d')
                except Exception:
                    _dt = _now
            _dts[c['id']] = _dt
            _jours = max(0, (_auj_p - _dt.date()).days)
            _sec = max(0, int((_now - _dt).total_seconds()))
            if _jours == 0:
                c['il_y_a'] = "à l'instant" if _sec < 120 else (f"il y a {_sec // 60} min" if _sec < 3600 else f"il y a {_sec // 3600} h")
            elif _jours == 1:
                c['il_y_a'] = 'hier'
            elif _jours < 7:
                c['il_y_a'] = f"il y a {_jours} j"
            else:
                c['il_y_a'] = f"{_dt.day} {_mois_courts[_dt.month - 1]}" + (f" {_dt.year}" if _dt.year != _auj_p.year else '')
            c['cette_semaine'] = _jours < 7
            if _jours == 0:
                c['periode'] = 'aujourdhui'
            elif _jours < 7:
                c['periode'] = 'semaine'
            elif (_dt.year, _dt.month) == (_auj_p.year, _auj_p.month):
                c['periode'] = 'mois'
            else:
                c['periode'] = 'ancien'
            _lab = LABELS_TYPE_COMMUNICATION.get(c.get('type'), c.get('type') or 'Annonce')
            if ' ' in _lab:
                c['type_ico'], c['type_nom'] = _lab.split(' ', 1)
            else:
                c['type_ico'], c['type_nom'] = '📢', _lab
            c['type_color'] = COULEURS_TYPE_COMMUNICATION.get(c.get('type'), '#0A84FF')
            _txt = ' '.join(str(c.get('contenu') or '').split())
            c['extrait'] = _txt[:150] + ('…' if len(_txt) > 150 else '')
            c['temps_lecture'] = max(1, round(len(_txt.split()) / 200 + 0.4))
            _ids_cl = {x['id'] for x in c.get('classes_liste', [])}
            _conc = [k for k in _kids if c.get('toutes_classes') or k['classe_id'] in _ids_cl]
            c['kid_ids'] = [str(k['id']) for k in _conc]
            c['pour_enfants'] = [k['prenom'] for k in _conc] if (not c.get('toutes_classes') and _conc) else []
            c['cible'] = "Toute l'école" if c.get('toutes_classes') else (', '.join(x['nom'] for x in c.get('classes_liste', [])) or "École")
        _pub.sort(key=lambda c: _dts[c['id']], reverse=True)

        _periodes_def = [('aujourdhui', "Aujourd'hui", '🌅'), ('semaine', 'Cette semaine', '🗓️'),
                         ('mois', 'Ce mois-ci', '📆'), ('ancien', 'Plus ancien', '🗄️')]
        _periodes = []
        for _code, _label, _ico in _periodes_def:
            _items = [c for c in _pub if c['periode'] == _code]
            if _items:
                _periodes.append({'label': _label, 'ico': _ico, 'liste': _items})

        _prio = lambda c: (0 if c['priorite'] == 'urgente' else (1 if c['priorite'] == 'importante' else 2), -_dts[c['id']].timestamp())
        _cand = sorted([c for c in _pub if (c['priorite'] in ('urgente', 'importante') or c['epingle']) and not c['lu']], key=_prio)
        _une = _cand[:4]
        if len(_une) < 3:
            for c in sorted(_pub, key=lambda c: (bool(c['lu']), -_dts[c['id']].timestamp())):
                if c not in _une:
                    _une.append(c)
                if len(_une) >= 3:
                    break

        _types_cnt = {}
        for c in _pub:
            _t = _types_cnt.setdefault(c['type'], {'code': c['type'], 'ico': c['type_ico'], 'nom': c['type_nom'], 'color': c['type_color'], 'n': 0})
            _t['n'] += 1
        _nb_total = len(_pub)
        _nb_lus = sum(1 for c in _pub if c['lu'])
        parent_ctx = {
            'kids': _kids, 'periodes': _periodes, 'a_la_une': _une,
            'types': sorted(_types_cnt.values(), key=lambda t: -t['n'])[:6],
            'nb_total': _nb_total, 'nb_lus': _nb_lus, 'nb_non_lus': _nb_total - _nb_lus,
            'pct_lu': round(100 * _nb_lus / _nb_total) if _nb_total else 0,
            'nb_urgents': sum(1 for c in _pub if c['priorite'] in ('urgente', 'importante')),
            'nb_urgents_non_lus': sum(1 for c in _pub if c['priorite'] in ('urgente', 'importante') and not c['lu']),
            'nb_epingles': sum(1 for c in _pub if c['epingle']),
            'nb_semaine': sum(1 for c in _pub if c['cette_semaine']),
        }

    comms_publiees_pour_slider = [c for c in comms_data if c['statut'] == 'publie']
    comms_slider = comms_publiees_pour_slider
    comms_rest = comms_data

    stats = conn.execute(f"""
        SELECT COUNT(DISTINCT co.id) as total,
               COUNT(DISTINCT CASE WHEN co.statut='publie' THEN co.id END) as publiees,
               COUNT(DISTINCT CASE WHEN co.statut='brouillon' THEN co.id END) as brouillons,
               COUNT(DISTINCT CASE WHEN co.statut='programme' THEN co.id END) as programmees,
               COUNT(DISTINCT CASE WHEN co.epingle=1 THEN co.id END) as epinglees,
               COUNT(DISTINCT CASE WHEN co.priorite='urgente' AND co.statut='publie' THEN co.id END) as urgentes
        FROM communications co
        WHERE {where_sql}
    """, params).fetchone()

    # 🆕 Analyses cumulées (tableau de bord admin) : vues/likes/commentaires totaux sur les
    # communications actuellement filtrées, + top 3 des publications les plus engageantes.
    analytics = None
    top_comms = []
    if peut_editer:
        total_vues = sum(c.get('nb_lu', 0) for c in comms_data)
        total_destinataires = sum(c.get('nb_destinataires', 0) for c in comms_data)
        total_likes = sum(c.get('nb_likes', 0) for c in comms_data)
        total_commentaires = sum(c.get('nb_commentaires', 0) for c in comms_data)
        analytics = {
            'total_vues': total_vues,
            'taux_lecture_moyen': round(100 * total_vues / total_destinataires, 1) if total_destinataires else 0,
            'total_likes': total_likes,
            'total_commentaires': total_commentaires,
        }
        top_comms = sorted(
            [c for c in comms_data if c['statut'] == 'publie'],
            key=lambda c: c.get('nb_lu', 0) + c.get('nb_likes', 0) * 2 + c.get('nb_commentaires', 0) * 3,
            reverse=True
        )[:3]

    # 🆕 Prochain événement à venir (pour la carte "Prochain événement" du nouveau design luxe) :
    # on cherche parmi les publications déjà publiées de type "événement"/"sortie"/"sportive" la plus
    # proche dans le temps (aujourd'hui ou dans le futur) ; à défaut, la plus récente déjà publiée.
    prochain_evenement = None
    try:
        aujourdhui_str = datetime.date.today().strftime('%Y-%m-%d')
        prochain_evenement = conn.execute("""
            SELECT * FROM communications
            WHERE statut='publie' AND type IN ('evenement','sportive','pedagogique')
              AND date_publication >= ?
            ORDER BY date_publication ASC LIMIT 1
        """, (aujourdhui_str,)).fetchone()
        if not prochain_evenement:
            prochain_evenement = conn.execute("""
                SELECT * FROM communications WHERE statut='publie' AND type IN ('evenement','sportive','pedagogique')
                ORDER BY date_publication DESC LIMIT 1
            """).fetchone()
    except Exception:
        prochain_evenement = None

    # 🆕 Statistiques globales (vues, j'aime, commentaires) sur TOUTES les publications
    # actuellement publiées et filtrées — visibles par TOUS les rôles (contrairement aux
    # analyses détaillées ci-dessus, réservées à l'admin/enseignant). Utilisées pour la carte
    # "statistiques en cercle" de la colonne latérale.
    comm_ids_publies = [c['id'] for c in comms_data if c['statut'] == 'publie']
    total_vues_globales = 0
    if comm_ids_publies:
        ph_vues = ','.join('?' * len(comm_ids_publies))
        total_vues_globales = conn.execute(
            f"SELECT COUNT(*) FROM communication_lectures WHERE communication_id IN ({ph_vues})",
            comm_ids_publies).fetchone()[0]
    stats_globales = {
        'vues': total_vues_globales,
        'likes': sum(c.get('nb_likes', 0) for c in comms_data if c['statut'] == 'publie'),
        'commentaires': sum(c.get('nb_commentaires', 0) for c in comms_data if c['statut'] == 'publie'),
    }

    conn.close()
    _auj = datetime.date.today()
    annee_scolaire_courante = f"{_auj.year}-{_auj.year+1}" if _auj.month >= 8 else f"{_auj.year-1}-{_auj.year}"
    return render_template_string(
        COMMUNICATIONS_HTML, comms=comms_rest, comms_slider=comms_slider, classes=classes, q=q,
        classe_filter=classe_filter,
        type_filter=type_filter, priorite_filter=priorite_filter, statut_filter=statut_filter,
        lecture_filter=lecture_filter, tri=tri, espace=espace,
        stats=stats, analytics=analytics, top_comms=top_comms, peut_editer=peut_editer, notif_count=get_notif_count(),
        stats_globales=stats_globales,
        prochain_evenement=dict(prochain_evenement) if prochain_evenement else None, role=role,
        annee_scolaire_courante=annee_scolaire_courante, annee_courante=_auj.year,
        parent_ctx=parent_ctx,
        TYPES_COMMUNICATION=TYPES_COMMUNICATION, LABELS_TYPE_COMMUNICATION=LABELS_TYPE_COMMUNICATION,
        COULEURS_TYPE_COMMUNICATION=COULEURS_TYPE_COMMUNICATION,
        PRIORITES_COMMUNICATION=PRIORITES_COMMUNICATION, LABELS_PRIORITE_COMMUNICATION=LABELS_PRIORITE_COMMUNICATION,
        COULEURS_PRIORITE_COMMUNICATION=COULEURS_PRIORITE_COMMUNICATION,
    )


@app.route('/communications/<int:comm_id>', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'agent_admin', 'enseignant', 'parent')
def communication_detail(comm_id):
    conn = get_db()
    role = session['role']
    peut_editer = role in ('admin', 'agent_admin')

    comm = conn.execute("""
        SELECT co.*, u.nom as auteur_nom, u.prenom as auteur_prenom
        FROM communications co LEFT JOIN users u ON co.auteur_id = u.id WHERE co.id=?
    """, (comm_id,)).fetchone()
    if not comm:
        conn.close()
        flash("Communication introuvable.", "error")
        return redirect(url_for('communications'))

    classes_comm = conn.execute("""
        SELECT c.id, c.nom, c.niveau FROM classes c
        JOIN communication_classes cc ON cc.classe_id = c.id WHERE cc.communication_id=?
        ORDER BY c.niveau, c.nom
    """, (comm_id,)).fetchall()
    classe_ids_comm = [c['id'] for c in classes_comm]

    # Contrôle d'accès pour les rôles en lecture seule
    if not peut_editer:
        if role == 'parent' and _comm_audience(comm) == 'pro':
            conn.close()
            flash("Cette communication n'est pas accessible.", "error")
            return redirect(url_for('communications'))
        if comm['statut'] != 'publie':
            conn.close()
            flash("Cette communication n'est pas encore publiée.", "error")
            return redirect(url_for('communications'))
        if not comm['toutes_classes']:
            classes_access = [c['id'] for c in _devoir_classes_accessibles(conn, role, session['user_id'])]
            if not any(cid in classes_access for cid in classe_ids_comm):
                conn.close()
                flash("Cette communication ne concerne pas vos classes.", "error")
                return redirect(url_for('communications'))

    if request.method == 'POST':
        action = request.form.get('action')
        ajax_payload = {'ok': True}
        if action == 'marquer_lu':
            # 🆕 Enregistre automatiquement la lecture : dès qu'un parent (ou enseignant) voit la
            # publication, elle apparaît « vue » côté admin — plus besoin de confirmation manuelle.
            conn.execute("""INSERT OR IGNORE INTO communication_lectures (communication_id, user_id, role, lu_at)
                             VALUES (?,?,?,?)""",
                         (comm_id, session['user_id'], role, datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')))
            conn.commit()
        elif action == 'toggle_like':
            # 🆕 Réponse AJAX enrichie (état du like + nouveau total) pour mise à jour instantanée
            # côté client, sans recharger la page.
            deja = conn.execute("SELECT 1 FROM communication_likes WHERE communication_id=? AND user_id=?",
                                 (comm_id, session['user_id'])).fetchone()
            if deja:
                conn.execute("DELETE FROM communication_likes WHERE communication_id=? AND user_id=?",
                             (comm_id, session['user_id']))
                liked_now = False
            else:
                conn.execute("""INSERT OR IGNORE INTO communication_likes (communication_id, user_id, created_at)
                                 VALUES (?,?,?)""",
                             (comm_id, session['user_id'], datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')))
                liked_now = True
            conn.commit()
            nb_likes_now = conn.execute("SELECT COUNT(*) FROM communication_likes WHERE communication_id=?",
                                         (comm_id,)).fetchone()[0]
            ajax_payload.update({'liked': liked_now, 'nb_likes': nb_likes_now})
        elif action == 'commenter':
            # 🆕 Réponse AJAX enrichie : renvoie le commentaire fraîchement créé (avec auteur et date)
            # pour l'insérer directement dans la liste côté client, sans recharger la page.
            texte = request.form.get('contenu', '').strip()
            if texte:
                cur = conn.execute("""INSERT INTO communication_commentaires (communication_id, user_id, role, contenu, created_at)
                                 VALUES (?,?,?,?,?)""",
                             (comm_id, session['user_id'], role, texte,
                              datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')))
                conn.commit()
                nouveau_id = cur.lastrowid
                cm_row = conn.execute("""
                    SELECT co.*, u.nom as auteur_nom, u.prenom as auteur_prenom
                    FROM communication_commentaires co LEFT JOIN users u ON u.id = co.user_id
                    WHERE co.id=?
                """, (nouveau_id,)).fetchone()
                if cm_row:
                    ajax_payload['commentaire'] = dict(cm_row)
                    ajax_payload['peut_supprimer'] = True
                flash("Commentaire publié.", "success")
            else:
                ajax_payload = {'ok': False, 'erreur': 'Le commentaire ne peut pas être vide.'}
        elif action == 'supprimer_commentaire':
            com_id = request.form.get('commentaire_id')
            com_row = conn.execute("SELECT * FROM communication_commentaires WHERE id=?", (com_id,)).fetchone()
            if com_row and (peut_editer or com_row['user_id'] == session['user_id']):
                conn.execute("DELETE FROM communication_commentaires WHERE id=?", (com_id,))
                conn.commit()
                flash("Commentaire supprimé.", "success")
            else:
                ajax_payload = {'ok': False}
        conn.close()
        # Requête AJAX silencieuse (like, commentaire, ping « vu » depuis le slider) : pas besoin
        # de redirection HTML, on renvoie directement les données utiles au client.
        if request.form.get('ajax') == '1':
            return jsonify(ajax_payload)
        return redirect(url_for('communication_detail', comm_id=comm_id))

    fichiers = conn.execute("SELECT * FROM communication_fichiers WHERE communication_id=? ORDER BY id",
                            (comm_id,)).fetchall()
    # 🆕 On sépare les images (affichées comme une véritable galerie) des autres pièces jointes
    images_comm = [dict(f) for f in fichiers if f['type_fichier'] == 'image']
    autres_fichiers = [dict(f) for f in fichiers if f['type_fichier'] != 'image']

    a_lu = conn.execute("SELECT 1 FROM communication_lectures WHERE communication_id=? AND user_id=?",
                        (comm_id, session['user_id'])).fetchone() is not None

    # 🆕 Un parent/enseignant qui consulte une publication publiée est automatiquement marqué comme
    # l'ayant vue — cela remonte immédiatement côté admin, sans action supplémentaire de sa part.
    if not peut_editer and not a_lu and comm['statut'] == 'publie':
        conn.execute("""INSERT OR IGNORE INTO communication_lectures (communication_id, user_id, role, lu_at)
                         VALUES (?,?,?,?)""",
                     (comm_id, session['user_id'], role, datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')))
        conn.commit()
        a_lu = True

    lecteurs_detail = None
    nb_lu_total = None
    if peut_editer:
        parents_cibles_ids = _comm_parents_cibles(conn, comm)
        if parents_cibles_ids:
            ph = ','.join('?' * len(parents_cibles_ids))
            # 🆕 Tri : ceux qui ont vu en premier (lu_at le plus ancien) apparaissent en tête,
            # dans l'ordre chronologique de consultation ; ceux qui n'ont pas encore vu suivent.
            parents_rows = conn.execute(f"""
                SELECT u.id, u.nom, u.prenom, u.telephone,
                       (SELECT lu_at FROM communication_lectures cl WHERE cl.communication_id=? AND cl.user_id=u.id) as lu_at
                FROM users u WHERE u.id IN ({ph}) ORDER BY (lu_at IS NULL) ASC, lu_at ASC, u.nom
            """, [comm_id] + parents_cibles_ids).fetchall()
            lecteurs_detail = [dict(r) for r in parents_rows]
        nb_lu_total = sum(1 for r in (lecteurs_detail or []) if r['lu_at'])

    nb_likes = conn.execute("SELECT COUNT(*) FROM communication_likes WHERE communication_id=?",
                             (comm_id,)).fetchone()[0]
    user_a_aime = conn.execute("SELECT 1 FROM communication_likes WHERE communication_id=? AND user_id=?",
                                (comm_id, session['user_id'])).fetchone() is not None
    commentaires = conn.execute("""
        SELECT co.*, u.nom as auteur_nom, u.prenom as auteur_prenom
        FROM communication_commentaires co LEFT JOIN users u ON u.id = co.user_id
        WHERE co.communication_id=? ORDER BY co.created_at ASC
    """, (comm_id,)).fetchall()

    # 🆕 Analyses admin : qui a aimé (détail) + taux d'engagement global, pour le tableau de bord
    likers_detail = None
    taux_engagement = 0
    if peut_editer:
        likers_rows = conn.execute("""
            SELECT u.id, u.nom, u.prenom, u.role as user_role, cl.created_at
            FROM communication_likes cl JOIN users u ON u.id = cl.user_id
            WHERE cl.communication_id=? ORDER BY cl.created_at DESC
        """, (comm_id,)).fetchall()
        likers_detail = [dict(r) for r in likers_rows]
        if nb_lu_total:
            taux_engagement = round(100 * (nb_likes + len(commentaires)) / nb_lu_total, 1)

    conn.close()
    return render_template_string(
        COMMUNICATION_DETAIL_HTML, comm=comm, comm_id=comm_id, classes_comm=classes_comm, fichiers=fichiers,
        images_comm=images_comm, autres_fichiers=autres_fichiers, a_lu=a_lu,
        peut_editer=peut_editer, lecteurs_detail=lecteurs_detail,
        nb_lu_total=nb_lu_total, nb_likes=nb_likes, user_a_aime=user_a_aime, commentaires=commentaires,
        likers_detail=likers_detail, taux_engagement=taux_engagement,
        today=datetime.date.today().isoformat(), notif_count=get_notif_count(),
        LABELS_TYPE_COMMUNICATION=LABELS_TYPE_COMMUNICATION, COULEURS_TYPE_COMMUNICATION=COULEURS_TYPE_COMMUNICATION,
        LABELS_PRIORITE_COMMUNICATION=LABELS_PRIORITE_COMMUNICATION,
        COULEURS_PRIORITE_COMMUNICATION=COULEURS_PRIORITE_COMMUNICATION, ICONES_TYPE_FICHIER=ICONES_TYPE_FICHIER,
    )


