# ═══════════════════════════════════════════════════════════════════════════════════════
# 📅 PLAN DE PAIEMENT (paiement échelonné des impayés d'un élève)
# ───────────────────────────────────────────────────────────────────────────────────────
# Un parent qui ne peut pas régler ses impayés d'un coup peut obtenir un plan : le reste dû
# (somme des factures non soldées de l'élève) est découpé en N échéances mensuelles.
# Quand une échéance est payée, le montant est affecté à la facture impayée la PLUS ANCIENNE
# jusqu'à son règlement complet, puis à la suivante (ex : 5 factures = 5000 MAD en 10 fois
# → 500 MAD par mois, les 2 premières échéances soldent la 1re facture de 1000 MAD, etc.).
# Les versements passent par le même circuit que le bouton « ✓ Payé » (journal des versements,
# statut, mode Caisse/Banque, notification parent, historique).
# ═══════════════════════════════════════════════════════════════════════════════════════
def _assurer_tables_plans_paiement(conn):
    conn.execute("""
        CREATE TABLE IF NOT EXISTS plans_paiement (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            eleve_id INTEGER NOT NULL,
            parent_id INTEGER,
            montant_initial REAL NOT NULL,
            nb_echeances INTEGER NOT NULL,
            date_debut TEXT NOT NULL,
            factures_ids TEXT NOT NULL,
            statut TEXT NOT NULL DEFAULT 'actif',
            cree_par INTEGER,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            termine_le DATETIME
        )""")
    conn.execute("""
        CREATE TABLE IF NOT EXISTS plans_paiement_echeances (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            plan_id INTEGER NOT NULL,
            numero INTEGER NOT NULL,
            date_prevue TEXT NOT NULL,
            montant REAL NOT NULL,
            montant_paye REAL NOT NULL DEFAULT 0,
            statut TEXT NOT NULL DEFAULT 'a_payer',
            date_paiement DATETIME,
            mode_encaissement TEXT
        )""")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_plans_paiement_eleve ON plans_paiement(eleve_id, statut)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_plans_echeances_plan ON plans_paiement_echeances(plan_id)")


def _plan_ajouter_mois(d, n):
    """Date + n mois (le jour est conservé, ramené à la fin du mois si besoin : 31 → 28/30)."""
    import calendar
    y = d.year + (d.month - 1 + n) // 12
    m = (d.month - 1 + n) % 12 + 1
    return datetime.date(y, m, min(d.day, calendar.monthrange(y, m)[1]))


def _plan_echeancier(montant_total, nb, date_debut):
    """[(numero, 'AAAA-MM-JJ', montant)] : reste divisé en `nb` échéances mensuelles. Les montants sont
    arrondis au centime et la DERNIÈRE échéance absorbe l'écart d'arrondi (la somme est exacte)."""
    total_cts = int(round(float(montant_total) * 100))
    base = total_cts // nb
    echeances = []
    for i in range(nb):
        cts = base if i < nb - 1 else total_cts - base * (nb - 1)
        echeances.append((i + 1, _plan_ajouter_mois(date_debut, i).strftime('%Y-%m-%d'), cts / 100.0))
    return echeances


def _plan_factures_impayees(conn, eleve_id):
    """Factures non soldées de l'élève, de la plus ancienne à la plus récente (ordre de règlement)."""
    out = []
    for r in conn.execute("""
            SELECT id, description, date_echeance, montant_total, COALESCE(montant_paye, 0) AS montant_paye
            FROM paiements
            WHERE eleve_id = ? AND statut IN ('non_paye', 'partiel')
            ORDER BY COALESCE(date_echeance, '9999-12-31'), id""", (eleve_id,)).fetchall():
        reste = round(float(r['montant_total'] or 0) - float(r['montant_paye'] or 0), 2)
        if reste > 0.004:
            out.append({'id': r['id'], 'description': r['description'] or '', 'echeance': r['date_echeance'] or '',
                        'total': float(r['montant_total'] or 0), 'paye': float(r['montant_paye'] or 0), 'reste': reste})
    return out


def _plan_detail(conn, plan_id):
    """Plan + échéances + factures couvertes (avec ce qu'il reste à régler sur chacune)."""
    plan = conn.execute("SELECT * FROM plans_paiement WHERE id = ?", (plan_id,)).fetchone()
    if not plan:
        return None
    echeances = [dict(r) for r in conn.execute(
        "SELECT * FROM plans_paiement_echeances WHERE plan_id = ? ORDER BY numero", (plan_id,)).fetchall()]
    try:
        ids = json.loads(plan['factures_ids'] or '[]')
    except Exception:
        ids = []
    factures = []
    if ids:
        q = ",".join("?" * len(ids))
        for r in conn.execute(f"""
                SELECT id, description, date_echeance, montant_total, COALESCE(montant_paye, 0) AS montant_paye, statut
                FROM paiements WHERE id IN ({q})
                ORDER BY COALESCE(date_echeance, '9999-12-31'), id""", ids).fetchall():
            total, paye = float(r['montant_total'] or 0), float(r['montant_paye'] or 0)
            factures.append({'id': r['id'], 'description': r['description'] or '', 'echeance': r['date_echeance'] or '',
                             'total': total, 'paye': paye, 'reste': max(round(total - paye, 2), 0.0),
                             'statut': r['statut']})
    eleve = conn.execute("SELECT e.prenom || ' ' || e.nom AS nom, c.nom AS classe FROM eleves e "
                         "LEFT JOIN classes c ON e.classe_id = c.id WHERE e.id = ?", (plan['eleve_id'],)).fetchone()
    payees = [e for e in echeances if e['statut'] == 'paye']
    return {
        'id': plan['id'], 'eleve_id': plan['eleve_id'], 'statut': plan['statut'],
        'eleve': eleve['nom'] if eleve else '', 'classe': (eleve['classe'] if eleve else '') or '',
        'montant_initial': float(plan['montant_initial'] or 0), 'nb_echeances': plan['nb_echeances'],
        'date_debut': plan['date_debut'], 'nb_payees': len(payees),
        'total_regle': round(sum(float(e['montant_paye'] or 0) for e in echeances), 2),
        'reste_factures': round(sum(f['reste'] for f in factures), 2),
        'echeances': echeances, 'factures': factures,
    }


def _plan_repartir_paiement(conn, plan, montant, mode):
    """Affecte `montant` aux factures du plan : la plus ancienne d'abord, jusqu'à ce qu'elle soit
    soldée, puis la suivante. Retourne (factures_touchées, montant_non_affecté)."""
    try:
        ids = json.loads(plan['factures_ids'] or '[]')
    except Exception:
        ids = []
    if not ids:
        return [], round(montant, 2)
    eleve = conn.execute("SELECT e.parent_id, e.prenom || ' ' || e.nom AS nom FROM eleves e WHERE e.id = ?",
                         (plan['eleve_id'],)).fetchone()
    q = ",".join("?" * len(ids))
    rows = conn.execute(f"""
        SELECT id, montant_total - COALESCE(montant_regule, 0) AS montant_total, COALESCE(montant_paye, 0) AS montant_paye
        FROM paiements WHERE id IN ({q}) ORDER BY COALESCE(date_echeance, '9999-12-31'), id""", ids).fetchall()
    restant = round(float(montant), 2)
    touchees = []
    for r in rows:
        if restant <= 0.004:
            break
        mt = float(r['montant_total'] or 0)
        deja = float(r['montant_paye'] or 0)
        reste = round(mt - deja, 2)
        if reste <= 0.004:
            continue
        ajout = round(min(reste, restant), 2)
        mp = mt if (deja + ajout) >= mt - 0.004 else round(deja + ajout, 2)
        statut = 'paye' if mp >= mt else 'partiel'
        synchroniser_versements(conn, r['id'])   # journal : régler d'abord l'existant à son ancienne date
        conn.execute("UPDATE paiements SET montant_paye=?, statut=?, date_paiement=CURRENT_TIMESTAMP, "
                     "mode_encaissement=? WHERE id=?", (mp, statut, mode, r['id']))
        synchroniser_versements(conn, r['id'])   # journal : inscrire ce versement à la date du jour
        log_action(conn, 'modification', 'paiement', r['id'],
                   f"Plan de paiement : +{ajout:.2f} MAD ({deja:.2f} → {mp:.2f} MAD, statut: {statut})"
                   f" — {eleve['nom'] if eleve else ''}", eleve_id=plan['eleve_id'])
        if statut == 'paye' and eleve:
            notifier_paiement_confirme(conn, r['id'], eleve['parent_id'], eleve['nom'])
        touchees.append({'refId': r['id'], 'paye': mp, 'solde': round(mt - mp, 2), 'statut': statut, 'ajout': ajout})
        restant = round(restant - ajout, 2)
    return touchees, max(restant, 0.0)


def _plan_date_valide(txt):
    try:
        return datetime.datetime.strptime((txt or '').strip()[:10], '%Y-%m-%d').date()
    except Exception:
        return None


def _plan_ids_selection(txt):
    """🆕 Liste d'ids de factures reçue du navigateur (« 12,15,18 » ou JSON « [12,15] »).
    None = paramètre absent (→ toutes les factures impayées) ; [] = aucune facture cochée."""
    if txt is None:
        return None
    txt = str(txt).strip()
    if txt == '':
        return []
    try:
        if txt.startswith('['):
            brut = json.loads(txt)
        else:
            brut = [x for x in txt.split(',') if x.strip() != '']
        return sorted({int(x) for x in brut})
    except (TypeError, ValueError):
        return []


@app.route('/paiements/plan/api/simuler/<int:eleve_id>', methods=['GET'])
@login_required
@role_required('admin', 'agent_admin')
def api_plan_paiement_simuler(eleve_id):
    """Calcul à l'ouverture du bouton « Plan de paiement » : reste dû de l'élève + échéancier proposé."""
    conn = get_db()
    try:
        _assurer_tables_plans_paiement(conn)
        eleve = conn.execute("SELECT e.prenom || ' ' || e.nom AS nom, c.nom AS classe FROM eleves e "
                             "LEFT JOIN classes c ON e.classe_id = c.id WHERE e.id = ?", (eleve_id,)).fetchone()
        if not eleve:
            return jsonify({'success': False, 'error': 'Élève introuvable.'}), 404
        factures = _plan_factures_impayees(conn, eleve_id)
        if sum(f['reste'] for f in factures) <= 0:
            return jsonify({'success': False, 'error': "Cet élève n'a aucun impayé : pas de plan de paiement possible."}), 400
        # 🆕 Le plan ne porte que sur les factures COCHÉES (par défaut : toutes les impayées)
        choisies = _plan_ids_selection(request.args.get('factures'))
        ids_dispo = {f['id'] for f in factures}
        selection = ids_dispo if choisies is None else (set(choisies) & ids_dispo)
        for f in factures:
            f['selected'] = f['id'] in selection
        total = round(sum(f['reste'] for f in factures if f['selected']), 2)
        try:
            nb = int(request.args.get('nb', 3))
        except (TypeError, ValueError):
            nb = 3
        nb = max(2, min(nb, 24))
        debut = _plan_date_valide(request.args.get('date_debut')) or datetime.date.today()
        ech = _plan_echeancier(total, nb, debut) if total > 0 else []
        return jsonify({
            'success': True, 'eleve': eleve['nom'], 'classe': eleve['classe'] or '', 'total': total, 'nb': nb,
            'date_debut': debut.strftime('%Y-%m-%d'), 'mensualite': ech[0][2] if ech else 0,
            'echeances': [{'numero': n, 'date': d, 'montant': m} for n, d, m in ech],
            'factures': factures, 'nb_selectionnees': len(selection),
        })
    finally:
        conn.close()


@app.route('/paiements/plan/api/eleve/<int:eleve_id>', methods=['GET'])
@login_required
@role_required('admin', 'agent_admin')
def api_plan_paiement_eleve(eleve_id):
    """Plan de paiement ACTIF d'un élève (détail complet) ou {'plan': None}."""
    conn = get_db()
    try:
        _assurer_tables_plans_paiement(conn)
        r = conn.execute("SELECT id FROM plans_paiement WHERE eleve_id = ? AND statut = 'actif' ORDER BY id DESC LIMIT 1",
                         (eleve_id,)).fetchone()
        return jsonify({'success': True, 'plan': _plan_detail(conn, r['id']) if r else None})
    finally:
        conn.close()


@app.route('/paiements/plan/creer', methods=['POST'])
@login_required
@role_required('admin', 'agent_admin')
def plan_paiement_creer():
    try:
        eleve_id = int(request.form.get('eleve_id'))
        nb = int(request.form.get('nb_echeances'))
    except (TypeError, ValueError):
        return jsonify({'success': False, 'error': 'Paramètres invalides.'}), 400
    if not 2 <= nb <= 24:
        return jsonify({'success': False, 'error': "Le nombre d'échéances doit être compris entre 2 et 24."}), 400
    debut = _plan_date_valide(request.form.get('date_debut'))
    if not debut:
        return jsonify({'success': False, 'error': 'Date de la première échéance invalide.'}), 400
    conn = get_db()
    try:
        _assurer_tables_plans_paiement(conn)
        eleve = conn.execute("SELECT parent_id, prenom || ' ' || nom AS nom FROM eleves WHERE id = ?", (eleve_id,)).fetchone()
        if not eleve:
            return jsonify({'success': False, 'error': 'Élève introuvable.'}), 404
        if conn.execute("SELECT 1 FROM plans_paiement WHERE eleve_id = ? AND statut = 'actif'", (eleve_id,)).fetchone():
            return jsonify({'success': False, 'error': 'Un plan de paiement est déjà en cours pour cet élève.'}), 409
        factures = _plan_factures_impayees(conn, eleve_id)
        if not factures:
            return jsonify({'success': False, 'error': "Cet élève n'a aucun impayé."}), 400
        # 🆕 Seules les factures choisies par l'admin entrent dans le plan (par défaut : toutes)
        choisies = _plan_ids_selection(request.form.get('factures_ids'))
        if choisies is not None:
            factures = [f for f in factures if f['id'] in set(choisies)]
        if not factures:
            return jsonify({'success': False, 'error': "Sélectionnez au moins une facture à inclure dans le plan de paiement."}), 400
        total = round(sum(f['reste'] for f in factures), 2)
        if total <= 0:
            return jsonify({'success': False, 'error': "Les factures sélectionnées n'ont aucun reste à payer."}), 400
        cur = conn.execute(
            "INSERT INTO plans_paiement (eleve_id, parent_id, montant_initial, nb_echeances, date_debut, factures_ids, cree_par) "
            "VALUES (?,?,?,?,?,?,?)",
            (eleve_id, eleve['parent_id'], total, nb, debut.strftime('%Y-%m-%d'),
             json.dumps([f['id'] for f in factures]), session.get('user_id')))
        plan_id = cur.lastrowid
        for numero, date_prevue, montant in _plan_echeancier(total, nb, debut):
            conn.execute("INSERT INTO plans_paiement_echeances (plan_id, numero, date_prevue, montant) VALUES (?,?,?,?)",
                         (plan_id, numero, date_prevue, montant))
        log_action(conn, 'creation', 'plan_paiement', plan_id,
                   f"Plan de paiement créé : {total:.2f} MAD en {nb} échéances mensuelles "
                   f"(à partir du {debut.strftime('%d/%m/%Y')}) sur {len(factures)} facture(s) — {eleve['nom']}", eleve_id=eleve_id)
        conn.commit()
        return jsonify({'success': True, 'plan': _plan_detail(conn, plan_id)})
    except Exception as e:
        conn.rollback()
        return jsonify({'success': False, 'error': f"Erreur serveur : {e}"}), 500
    finally:
        conn.close()


@app.route('/paiements/plan/payer', methods=['POST'])
@login_required
@role_required('admin', 'agent_admin')
def plan_paiement_payer():
    """Paie une échéance du plan : le montant est affecté à la facture impayée la plus ancienne
    jusqu'à son règlement complet, puis à la suivante."""
    try:
        ech_id = int(request.form.get('echeance_id'))
        montant_saisi = request.form.get('montant')
        montant = round(float(montant_saisi), 2) if montant_saisi not in (None, '') else None
    except (TypeError, ValueError):
        return jsonify({'success': False, 'error': 'Paramètres invalides.'}), 400
    mode = request.form.get('mode_encaissement') or None
    if mode not in ('Caisse', 'Banque'):
        return jsonify({'success': False, 'error': "Veuillez choisir le mode d'encaissement (Caisse ou Banque)."}), 400
    conn = get_db()
    try:
        _assurer_tables_plans_paiement(conn)
        ech = conn.execute("SELECT * FROM plans_paiement_echeances WHERE id = ?", (ech_id,)).fetchone()
        if not ech:
            return jsonify({'success': False, 'error': 'Échéance introuvable.'}), 404
        plan = conn.execute("SELECT * FROM plans_paiement WHERE id = ?", (ech['plan_id'],)).fetchone()
        if not plan or plan['statut'] != 'actif':
            return jsonify({'success': False, 'error': "Ce plan de paiement n'est plus actif."}), 409
        if ech['statut'] != 'a_payer':
            return jsonify({'success': False, 'error': 'Cette échéance est déjà réglée.'}), 409
        premiere = conn.execute("SELECT id, numero FROM plans_paiement_echeances WHERE plan_id = ? AND statut = 'a_payer' "
                                "ORDER BY numero LIMIT 1", (plan['id'],)).fetchone()
        if premiere and premiere['id'] != ech_id:
            return jsonify({'success': False, 'error': f"Réglez d'abord l'échéance n°{premiere['numero']}."}), 409
        reste_ech = round(float(ech['montant']) - float(ech['montant_paye'] or 0), 2)
        if montant is None:
            montant = reste_ech
        if not _montant_fini(montant) or montant <= 0:
            return jsonify({'success': False, 'error': 'Le montant doit être supérieur à 0.'}), 400
        if montant > reste_ech + 0.004:
            return jsonify({'success': False,
                            'error': f"Le montant dépasse le reste de cette échéance ({reste_ech:.2f} MAD)."}), 400

        touchees, non_affecte = _plan_repartir_paiement(conn, plan, montant, mode)
        affecte = round(montant - non_affecte, 2)
        nouveau_paye = round(float(ech['montant_paye'] or 0) + affecte, 2)
        solde_ech = nouveau_paye >= float(ech['montant']) - 0.004
        conn.execute("UPDATE plans_paiement_echeances SET montant_paye=?, statut=?, mode_encaissement=?, "
                     "date_paiement=CURRENT_TIMESTAMP WHERE id=?",
                     (float(ech['montant']) if solde_ech else nouveau_paye, 'paye' if solde_ech else 'a_payer', mode, ech_id))

        # Plan terminé : toutes les échéances payées, ou plus rien à régler sur les factures du plan
        # (ex : une partie a été payée directement entre-temps) → les échéances restantes sont soldées.
        detail = _plan_detail(conn, plan['id'])
        if detail['reste_factures'] <= 0.004 or all(e['statut'] == 'paye' for e in detail['echeances']):
            conn.execute("UPDATE plans_paiement_echeances SET statut='solde' WHERE plan_id=? AND statut='a_payer'", (plan['id'],))
            conn.execute("UPDATE plans_paiement SET statut='termine', termine_le=CURRENT_TIMESTAMP WHERE id=?", (plan['id'],))
        log_action(conn, 'modification', 'plan_paiement', plan['id'],
                   f"Échéance n°{ech['numero']} payée : {affecte:.2f} MAD ({mode}) — {detail['eleve']}",
                   eleve_id=plan['eleve_id'])
        conn.commit()
        detail = _plan_detail(conn, plan['id'])
        return jsonify({'success': True, 'plan': detail, 'factures': touchees, 'montant_non_affecte': non_affecte})
    except Exception as e:
        conn.rollback()
        return jsonify({'success': False, 'error': f"Erreur serveur : {e}"}), 500
    finally:
        conn.close()


@app.route('/paiements/plan/annuler', methods=['POST'])
@login_required
@role_required('admin')
def plan_paiement_annuler():
    """Annule un plan en cours (les sommes déjà encaissées restent acquises sur les factures)."""
    try:
        plan_id = int(request.form.get('plan_id'))
    except (TypeError, ValueError):
        return jsonify({'success': False, 'error': 'Paramètres invalides.'}), 400
    conn = get_db()
    try:
        _assurer_tables_plans_paiement(conn)
        plan = conn.execute("SELECT * FROM plans_paiement WHERE id = ? AND statut = 'actif'", (plan_id,)).fetchone()
        if not plan:
            return jsonify({'success': False, 'error': 'Plan introuvable ou déjà clos.'}), 404
        conn.execute("UPDATE plans_paiement SET statut='annule', termine_le=CURRENT_TIMESTAMP WHERE id=?", (plan_id,))
        log_action(conn, 'suppression', 'plan_paiement', plan_id, "Plan de paiement annulé", eleve_id=plan['eleve_id'])
        conn.commit()
        return jsonify({'success': True})
    except Exception as e:
        conn.rollback()
        return jsonify({'success': False, 'error': f"Erreur serveur : {e}"}), 500
    finally:
        conn.close()


@app.route('/paiements/valider_ajax', methods=['POST'])
@login_required
@role_required('admin', 'agent_admin')
def paiement_valider_ajax():
    """🆕 Validation d'un paiement (élève ou enseignant) en AJAX : ne redirige jamais, ne
    recharge jamais la page. Utilisé par le bouton ✓ du tableau des paiements pour que la
    page reste exactement où l'admin se trouvait (scroll, pagination, filtres inchangés)."""
    is_enseignant = request.form.get('is_enseignant') == '1'

    if is_enseignant and session['role'] == 'agent_admin':
        return jsonify({'success': False, 'error': "Accès non autorisé."}), 403

    try:
        pid = int(request.form.get('paiement_id'))
        # 🆕 Le champ envoyé n'est plus le total payé mais le montant REÇU AUJOURD'HUI
        # (ex : 100 MAD encaissés hier + 200 MAD saisis maintenant = 300 MAD au total) —
        # le cumul se calcule désormais automatiquement côté serveur, sans obliger l'admin
        # à refaire le calcul à la main à chaque nouveau versement. On garde 'montant_paye'
        # en repli pour compatibilité si jamais un ancien script appelle encore cette route.
        montant_ajoute = float(request.form.get('montant_ajoute', request.form.get('montant_paye', 0)) or 0)
    except (TypeError, ValueError):
        return jsonify({'success': False, 'error': 'Paramètres invalides.'}), 400

    if not _montant_fini(montant_ajoute) or montant_ajoute < 0:
        return jsonify({'success': False, 'error': 'Le montant reçu ne peut pas être négatif.'}), 400

    mode_encaissement = request.form.get('mode_encaissement') or None

    conn = get_db()
    try:
        table = 'paiements_enseignants' if is_enseignant else 'paiements'
        row = conn.execute(f"SELECT montant_total, montant_paye, mode_encaissement FROM {table} WHERE id=?", (pid,)).fetchone()
        if not row:
            return jsonify({'success': False, 'error': 'Paiement introuvable.'}), 404

        mt = float(row['montant_total'] or 0)
        if not is_enseignant:   # 🆕 facture régularisée : plafond = total − régule (ce qui a déjà été rendu n'est plus dû)
            _rg0 = conn.execute("SELECT COALESCE(montant_regule, 0) FROM paiements WHERE id=?", (pid,)).fetchone()
            if _rg0 and _rg0[0] > 0:
                mt = max(mt - float(_rg0[0]), 0.0)
        montant_deja_paye = float(row['montant_paye'] or 0)
        # 🆕 Cumul automatique : nouveau total payé = ce qui était déjà réglé + ce qui vient
        # d'être saisi, plafonné au montant total de la facture/du bulletin.
        mp = min(montant_deja_paye + montant_ajoute, mt)

        if mp > 0 and mode_encaissement not in ('Caisse', 'Banque'):
            return jsonify({'success': False, 'error': "Veuillez choisir le mode d'encaissement (Caisse ou Banque)."}), 400
        if is_enseignant and _conflit_mode_paie(montant_deja_paye, row['mode_encaissement'], mp, mode_encaissement):
            return jsonify({'success': False, 'error': f"Cette fiche a déjà été réglée en {row['mode_encaissement']} : un seul mode "
                            f"par fiche de paie. Réglez le complément avec le même mode."}), 400

        statut = 'paye' if mp >= mt else ('partiel' if mp > 0 else 'non_paye')
        if not is_enseignant:
            _rg = conn.execute("SELECT COALESCE(montant_regule, 0) FROM paiements WHERE id=?", (pid,)).fetchone()
            if _rg and _rg[0] > 0:
                statut = 'paye'  # 🆕 facture régularisée (élève sortant) : reste « Sortant », jamais impayée
        if not is_enseignant:
            synchroniser_versements(conn, pid)  # 🆕 journal : régler d'abord l'existant à son ancienne date
        conn.execute(f"UPDATE {table} SET montant_paye=?,statut=?,date_paiement=CURRENT_TIMESTAMP,mode_encaissement=? WHERE id=?",
                     (mp, statut, mode_encaissement, pid))
        if not is_enseignant:
            synchroniser_versements(conn, pid)  # 🆕 journal : inscrire ce versement (avec SON mode) à la date du jour
            if montant_ajoute <= 0.005 and mode_encaissement:
                corriger_mode_versements(conn, pid, mode_encaissement)   # simple correction de mode, sans nouvel argent

        badge_emoji, badge_label = None, None

        if is_enseignant:
            nom_row = conn.execute(
                "SELECT prenom||' '||nom as nom FROM users u JOIN paiements_enseignants pe ON pe.enseignant_id=u.id WHERE pe.id=?",
                (pid,)).fetchone()
            log_action(conn, 'modification', 'paiement_enseignant', pid,
                       f"Montant payé mis à jour (AJAX) : +{montant_ajoute:.2f} MAD "
                       f"({montant_deja_paye:.2f} → {mp:.2f} MAD, statut: {statut})"
                       f" — {nom_row['nom'] if nom_row else ''}")
            can_bulletin = (statut == 'paye')
            can_update = (statut != 'paye')  # 🆕 une fois « Payé », le bouton disparaît (comme hors prof) : place au bulletin
        else:
            eleve = conn.execute(
                "SELECT e.parent_id, e.prenom||' '||e.nom as nom FROM paiements p JOIN eleves e ON p.eleve_id=e.id WHERE p.id=?",
                (pid,)).fetchone()
            if statut == 'paye' and eleve:
                notifier_paiement_confirme(conn, pid, eleve['parent_id'], eleve['nom'])
            log_action(conn, 'modification', 'paiement', pid,
                       f"Montant payé mis à jour (AJAX) : +{montant_ajoute:.2f} MAD "
                       f"({montant_deja_paye:.2f} → {mp:.2f} MAD, statut: {statut})"
                       f" — {eleve['nom'] if eleve else ''}")
            can_bulletin = False
            # 🆕 Reste modifiable même une fois payé, pour pouvoir corriger le mode
            # d'encaissement (Caisse/Banque) après coup.
            can_update = True

            # 🆕 Badge du parent recalculé après paiement, pour rafraîchir la colonne "Badge parent"
            if eleve and eleve['parent_id']:
                seuil_bloque = get_seuil_compte_bloque(conn)
                indic_p = _indicateurs_paiement_parent(conn, eleve['parent_id'])
                badge = _badge_paiement_parent(indic_p, seuil_bloque)
                badge_emoji, badge_label = badge['emoji'], badge['label']

        conn.commit()

        return jsonify({
            'success': True,
            'paiement': {
                'paye': mp,
                'solde': round(mt - mp, 2),
                'statut': statut,
                'canUpdate': can_update,
                'canBulletin': can_bulletin,
                'modeEncaissement': mode_encaissement,
                'badgeEmoji': badge_emoji,
                'badgeLabel': badge_label,
            }
        })
    except Exception as e:
        conn.rollback()
        return jsonify({'success': False, 'error': f"Erreur serveur : {e}"}), 500
    finally:
        conn.close()


# ═══ 💳 PAIEMENT PAR CHÈQUE — routes ═══════════════════════════════════════════════════
def _cheque_etat_facture(conn, pid):
    row = conn.execute("SELECT montant_total, montant_paye, statut FROM paiements WHERE id=?", (pid,)).fetchone()
    att = conn.execute("SELECT COALESCE(SUM(montant),0) AS s, COUNT(*) AS n, MIN(date_depot) AS d, "
                       "COALESCE(SUM(CASE WHEN date_depot >= date('now','localtime') THEN montant ELSE 0 END),0) AS sv "
                       "FROM cheques_paiement WHERE paiement_id=? AND statut='en_attente'", (pid,)).fetchone()
    mt = float(row['montant_total'] or 0)
    mp = float(row['montant_paye'] or 0)
    solde = mt - mp
    sv = float(att['sv'] or 0)
    return {'total': mt, 'paye': mp, 'solde': round(solde, 2), 'statut': row['statut'],
            'chequeAttente': round(float(att['s'] or 0), 2), 'chequeNb': att['n'], 'chequeDate': att['d'] or '',
            'chequeValide': round(min(sv, max(solde, 0)), 2),
            'enCours': bool(row['statut'] != 'paye' and sv > 0.009 and solde - sv <= 0.009)}


@app.route('/paiements/cheque/ajouter', methods=['POST'])
@login_required
@role_required('admin', 'agent_admin')
def paiement_cheque_ajouter():
    try:
        pid = int(request.form.get('paiement_id'))
        montant = float(str(request.form.get('montant', '')).replace(',', '.'))
        date_depot = (request.form.get('date_depot') or '').strip()
        datetime.date.fromisoformat(date_depot)
    except (TypeError, ValueError):
        return jsonify({'success': False, 'error': 'Montant ou date de dépôt invalide.'}), 400
    if montant <= 0:
        return jsonify({'success': False, 'error': 'Le montant du chèque doit être supérieur à 0.'}), 400
    numero = (request.form.get('numero') or '').strip()[:120]
    conn = get_db()
    try:
        _assurer_table_cheques(conn)
        row = conn.execute("SELECT p.montant_total, p.montant_paye, p.statut, e.prenom||' '||e.nom AS eleve "
                           "FROM paiements p JOIN eleves e ON p.eleve_id=e.id WHERE p.id=?", (pid,)).fetchone()
        if not row:
            return jsonify({'success': False, 'error': 'Facture introuvable.'}), 404
        etat = _cheque_etat_facture(conn, pid)
        reste_libre = etat['total'] - etat['paye'] - etat['chequeAttente']
        if row['statut'] == 'paye' or reste_libre <= 0.009:
            return jsonify({'success': False, 'error': 'Cette facture est déjà payée ou entièrement couverte par un chèque.'}), 400
        if montant > reste_libre + 0.009:
            return jsonify({'success': False, 'error': f"Le montant du chèque dépasse le reste à payer ({reste_libre:.2f} MAD)."}), 400
        conn.execute("INSERT INTO cheques_paiement (paiement_id, montant, date_depot, numero, created_by) VALUES (?,?,?,?,?)",
                     (pid, montant, date_depot, numero, session.get('nom') or session.get('username') or ''))
        log_action(conn, 'creation', 'paiement', pid,
                   f"Chèque enregistré : {montant:.2f} MAD, dépôt à partir du {date_depot} — {row['eleve']}")
        conn.commit()
        return jsonify({'success': True, 'etat': _cheque_etat_facture(conn, pid)})
    except Exception as e:
        conn.rollback()
        return jsonify({'success': False, 'error': f"Erreur serveur : {e}"}), 500
    finally:
        conn.close()


