@app.route('/paiements/cheque/<int:cheque_id>/encaisser', methods=['POST'])
@login_required
@role_required('admin', 'agent_admin')
def paiement_cheque_encaisser(cheque_id):
    """Chèque déposé et encaissé : le montant entre dans montant_paye (donc dans les revenus)."""
    mode = request.form.get('mode_encaissement')
    if mode not in ('Caisse', 'Banque'):
        return jsonify({'success': False, 'error': "Veuillez choisir le mode d'encaissement (Caisse ou Banque)."}), 400
    conn = get_db()
    try:
        _assurer_table_cheques(conn)
        ch = conn.execute("SELECT * FROM cheques_paiement WHERE id=?", (cheque_id,)).fetchone()
        if not ch or ch['statut'] != 'en_attente':
            return jsonify({'success': False, 'error': "Ce chèque n'est plus en attente."}), 400
        pid = ch['paiement_id']
        row = conn.execute("SELECT montant_total, montant_paye FROM paiements WHERE id=?", (pid,)).fetchone()
        if not row:
            return jsonify({'success': False, 'error': 'Facture introuvable.'}), 404
        mt = float(row['montant_total'] or 0)
        _rg0 = conn.execute("SELECT COALESCE(montant_regule, 0) FROM paiements WHERE id=?", (pid,)).fetchone()
        if _rg0 and _rg0[0] > 0:   # 🆕 facture régularisée : plafond = total − régule
            mt = max(mt - float(_rg0[0]), 0.0)
        deja = float(row['montant_paye'] or 0)
        mp = min(deja + float(ch['montant'] or 0), mt)
        statut = 'paye' if mp >= mt else ('partiel' if mp > 0 else 'non_paye')
        _rg = conn.execute("SELECT COALESCE(montant_regule, 0) FROM paiements WHERE id=?", (pid,)).fetchone()
        if _rg and _rg[0] > 0:
            statut = 'paye'
        synchroniser_versements(conn, pid)
        conn.execute("UPDATE paiements SET montant_paye=?,statut=?,date_paiement=CURRENT_TIMESTAMP,mode_encaissement=? WHERE id=?",
                     (mp, statut, mode, pid))
        synchroniser_versements(conn, pid)
        conn.execute("UPDATE cheques_paiement SET statut='encaisse', mode_encaissement=?, date_statut=CURRENT_TIMESTAMP WHERE id=?",
                     (mode, cheque_id))
        eleve = conn.execute("SELECT e.parent_id, e.prenom||' '||e.nom AS nom FROM paiements p "
                             "JOIN eleves e ON p.eleve_id=e.id WHERE p.id=?", (pid,)).fetchone()
        if statut == 'paye' and eleve:
            notifier_paiement_confirme(conn, pid, eleve['parent_id'], eleve['nom'])
        log_action(conn, 'modification', 'paiement', pid,
                   f"Chèque encaissé : +{float(ch['montant']):.2f} MAD ({deja:.2f} → {mp:.2f} MAD, statut: {statut}) — "
                   f"{eleve['nom'] if eleve else ''}")
        etat = _cheque_etat_facture(conn, pid)
        if eleve and eleve['parent_id']:
            indic_p = _indicateurs_paiement_parent(conn, eleve['parent_id'])
            badge = _badge_paiement_parent(indic_p, get_seuil_compte_bloque(conn))
            etat['badgeEmoji'], etat['badgeLabel'] = badge['emoji'], badge['label']
        conn.commit()
        return jsonify({'success': True, 'etat': etat})
    except Exception as e:
        conn.rollback()
        return jsonify({'success': False, 'error': f"Erreur serveur : {e}"}), 500
    finally:
        conn.close()


