# ─────────────────────────────────────────────
# CLASSES
# ─────────────────────────────────────────────
@app.route('/classes', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'secretaire')
def gestion_classes():
    conn = get_db()
    if request.method == 'POST':
        action = request.form.get('action')
        classe_id = request.form.get('classe_id')
        cycle = request.form.get('cycle', 'Primaire')  # Récupère le cycle actuel
        redirect_classe_id = classe_id  # 🆕 par défaut on revient sur la fiche de la classe concernée

        if action == 'edit':
            nom = request.form.get('nom')
            niveau = request.form.get('niveau')

            # 🔄 MODIFIÉ : Récupération d'une liste de professeurs
            enseignants_ids = request.form.getlist('enseignants_ids')

            # 🔄 MODIFIÉ : On met à jour la classe sans la colonne enseignant_id
            conn.execute("UPDATE classes SET nom=?, niveau=? WHERE id=?",
                         (nom, niveau, classe_id))

            # ✅ NOUVEAU : Nettoyage et insertion des multiples professeurs pour cette classe
            conn.execute("DELETE FROM classe_profs WHERE classe_id=?", (classe_id,))
            for prof_id in enseignants_ids:
                if prof_id:  # Sécurité anti-vide
                    prof_id = int(prof_id)
                    # On récupère la matière spécialité du prof
                    try:
                        prof = conn.execute("SELECT matiere_specialite FROM users WHERE id=?", (prof_id,)).fetchone()
                        mat = prof['matiere_specialite'] if prof and prof['matiere_specialite'] else 'Non défini'
                    except sqlite3.OperationalError:
                        mat = 'Non défini'  # Fallback si la colonne n'existe pas encore

                    conn.execute("INSERT INTO classe_profs (classe_id, enseignant_id, matiere) VALUES (?, ?, ?)",
                                 (classe_id, prof_id, mat))

            conn.commit()
            flash('Classe mise à jour avec succès !', 'success')

        elif action == 'delete':
            conn.execute("UPDATE eleves SET classe_id=NULL WHERE classe_id=?", (classe_id,))
            conn.execute("DELETE FROM matieres WHERE classe_id=?", (classe_id,))
            # ✅ NOUVEAU : Suppression des liaisons profs-classes
            conn.execute("DELETE FROM classe_profs WHERE classe_id=?", (classe_id,))
            conn.execute("DELETE FROM classes WHERE id=?", (classe_id,))
            conn.commit()
            flash('Classe supprimée avec succès !', 'success')
            redirect_classe_id = None  # 🆕 la classe n'existe plus : retour au hub de sélection

        elif action == 'add_matiere':
            nom_mat = request.form.get('nom_matiere')
            coef = request.form.get('coefficient', 1)
            ens_mat_id = request.form.get('enseignant_matiere_id')
            ens_mat_id = int(ens_mat_id) if ens_mat_id else None
            conn.execute("INSERT INTO matieres (nom, coefficient, classe_id, enseignant_id) VALUES (?, ?, ?, ?)",
                         (nom_mat, coef, classe_id, ens_mat_id))
            conn.commit()
            flash('Matière ajoutée avec succès !', 'success')

        elif action == 'delete_matiere':
            mat_id = request.form.get('matiere_id')
            redirect_classe_id = request.form.get('classe_id') or redirect_classe_id  # 🆕
            conn.execute("DELETE FROM notes WHERE matiere_id=?", (mat_id,))
            conn.execute("DELETE FROM sous_matieres WHERE matiere_id=?", (mat_id,))  # 🆕 nettoyage des sous-matières
            conn.execute("DELETE FROM matieres WHERE id=?", (mat_id,))
            conn.commit()
            flash('Matière supprimée avec succès !', 'success')

        # ✅ FIX: Action manquante — modifier le coefficient et/ou l'enseignant d'une matière déjà assignée (CONSERVÉ)
        elif action == 'edit_matiere_assignee':
            mat_id = request.form.get('matiere_id')
            redirect_classe_id = request.form.get('classe_id') or redirect_classe_id  # 🆕
            coef = request.form.get('coefficient', 1)
            ens_mat_id = request.form.get('enseignant_matiere_id')
            ens_mat_id = int(ens_mat_id) if ens_mat_id else None
            if mat_id:
                conn.execute(
                    "UPDATE matieres SET coefficient=?, enseignant_id=? WHERE id=?",
                    (coef, ens_mat_id, mat_id)
                )
                conn.commit()
                flash('Matière mise à jour avec succès !', 'success')
            else:
                flash('Erreur : matière introuvable.', 'error')

        # 🆕 NOUVEAU : Ajouter une sous-matière (ex: pour "Arabe" → Dictée, Participation, Conjugaison...)
        elif action == 'add_sous_matiere':
            mat_id = request.form.get('matiere_id')
            redirect_classe_id = request.form.get('classe_id') or redirect_classe_id
            nom_sm = (request.form.get('nom_sous_matiere') or '').strip()
            coef_sm = request.form.get('coefficient_sous_matiere', 1) or 1
            if mat_id and nom_sm:
                conn.execute(
                    "INSERT INTO sous_matieres (matiere_id, nom, coefficient) VALUES (?, ?, ?)",
                    (mat_id, nom_sm, coef_sm)
                )
                conn.commit()
                flash(f'Sous-matière « {nom_sm} » ajoutée avec succès !', 'success')
            else:
                flash('Erreur : le nom de la sous-matière est obligatoire.', 'error')

        # 🆕 NOUVEAU : Modifier une sous-matière existante (nom + coefficient)
        elif action == 'edit_sous_matiere':
            sm_id = request.form.get('sous_matiere_id')
            redirect_classe_id = request.form.get('classe_id') or redirect_classe_id
            nom_sm = (request.form.get('nom_sous_matiere') or '').strip()
            coef_sm = request.form.get('coefficient_sous_matiere', 1) or 1
            if sm_id and nom_sm:
                conn.execute(
                    "UPDATE sous_matieres SET nom=?, coefficient=? WHERE id=?",
                    (nom_sm, coef_sm, sm_id)
                )
                conn.commit()
                flash('Sous-matière mise à jour avec succès !', 'success')
            else:
                flash('Erreur : sous-matière introuvable ou nom manquant.', 'error')

        # 🆕 NOUVEAU : Supprimer une sous-matière (les notes déjà saisies dessus redeviennent des
        # notes "globales" de la matière plutôt que d'être perdues)
        elif action == 'delete_sous_matiere':
            sm_id = request.form.get('sous_matiere_id')
            redirect_classe_id = request.form.get('classe_id') or redirect_classe_id
            conn.execute("UPDATE notes SET sous_matiere_id=NULL WHERE sous_matiere_id=?", (sm_id,))
            conn.execute("DELETE FROM sous_matieres WHERE id=?", (sm_id,))
            conn.commit()
            flash('Sous-matière supprimée avec succès !', 'success')

        else:
            # Action de création d'une nouvelle classe
            nom = request.form.get('nom')
            niveau = request.form.get('niveau')

            # 🔄 MODIFIÉ : Récupération multiple
            enseignants_ids = request.form.getlist('enseignants_ids')

            if nom and niveau:
                cursor = conn.cursor()  # ✅ Utilisation du cursor pour récupérer l'ID de la nouvelle classe
                try:
                    # 🔄 MODIFIÉ : Insertion sans enseignant_id
                    cursor.execute("INSERT INTO classes (nom, niveau, cycle) VALUES (?, ?, ?)",
                                   (nom, niveau, cycle))
                except sqlite3.OperationalError:
                    # Fallback si la colonne cycle n'existe pas encore (sécurité)
                    cursor.execute("INSERT INTO classes (nom, niveau) VALUES (?, ?)",
                                   (nom, niveau))

                new_classe_id = cursor.lastrowid  # Récupère l'ID nouvellement créé

                # ✅ NOUVEAU : Assignation des multiples profs à la nouvelle classe
                for prof_id in enseignants_ids:
                    if prof_id:
                        prof_id = int(prof_id)
                        try:
                            prof = conn.execute("SELECT matiere_specialite FROM users WHERE id=?",
                                                (prof_id,)).fetchone()
                            mat = prof['matiere_specialite'] if prof and prof['matiere_specialite'] else 'Non défini'
                        except sqlite3.OperationalError:
                            mat = 'Non défini'

                        cursor.execute("INSERT INTO classe_profs (classe_id, enseignant_id, matiere) VALUES (?, ?, ?)",
                                       (new_classe_id, prof_id, mat))

                conn.commit()
                flash('Classe créée avec succès !', 'success')
                redirect_classe_id = new_classe_id  # 🆕 on ouvre directement la fiche de la nouvelle classe

        conn.close()
        # 🆕 Si l'action vient de la page "Toutes les matières", on y retourne directement
        if request.form.get('retour') == 'toutes_matieres':
            return redirect(url_for('toutes_les_matieres'))
        # 🆕 On revient sur la fiche de la classe concernée quand elle existe encore, sinon sur le hub de sélection
        return redirect(url_for('gestion_classes', cycle=cycle, classe_id=redirect_classe_id))

    # --- MÉTHODE GET ---
    cycle_filter = request.args.get('cycle')

    # Étape 1 : Si aucun cycle n'est dans l'URL, on affiche la page d'accueil avec les 3 cases
    if not cycle_filter:
        # 🆕 Petites statistiques rapides par cycle affichées sur chaque tuile
        cycle_stats = {}
        for cyc in get_all_cycle_names(conn):
            try:
                row = conn.execute("""
                    SELECT COUNT(DISTINCT c.id) as nb_classes,
                           (SELECT COUNT(*) FROM eleves e JOIN classes c2 ON e.classe_id=c2.id WHERE c2.cycle=?) as nb_eleves
                    FROM classes c WHERE c.cycle=?
                """, (cyc, cyc)).fetchone()
                cycle_stats[cyc] = {'nb_classes': row['nb_classes'] or 0, 'nb_eleves': row['nb_eleves'] or 0}
            except sqlite3.OperationalError:
                cycle_stats[cyc] = {'nb_classes': 0, 'nb_eleves': 0}
        total_matieres = conn.execute("SELECT COUNT(*) as n FROM matieres").fetchone()['n']
        conn.close()
        return render_template_string(CLASSES_HUB_HTML, notif_count=get_notif_count(), cycle_stats=cycle_stats,
                                       total_matieres=total_matieres)

    # Étape 2 : Si un cycle est sélectionné, on récupère uniquement ses classes
    try:
        # 🔄 MODIFIÉ : Requête SQL adaptée pour concaténer les multiples professeurs de la classe
        classes_raw = conn.execute("""
                                   SELECT c.*,
                                          (SELECT GROUP_CONCAT(u.prenom || ' ' || u.nom || ' (' || cp.matiere || ')', ' • ')
                                           FROM classe_profs cp
                                           JOIN users u ON cp.enseignant_id = u.id
                                           WHERE cp.classe_id = c.id) as profs_assignes,
                                          (SELECT COUNT(*) FROM eleves WHERE classe_id = c.id) as nb_eleves
                                   FROM classes c
                                   WHERE c.cycle = ?
                                   ORDER BY c.niveau, c.nom
                                   """, (cycle_filter,)).fetchall()
    except sqlite3.OperationalError:
        classes_raw = []  # Sécurité si pb BDD

    classes = []
    for c in classes_raw:
        c_dict = dict(c)
        matieres_rows = conn.execute("""
                                          SELECT m.*, u.prenom || ' ' || u.nom as enseignant_nom
                                          FROM matieres m
                                                   LEFT JOIN users u ON m.enseignant_id = u.id
                                          WHERE m.classe_id = ?
                                          ORDER BY m.nom
                                          """, (c['id'],)).fetchall()
        # 🆕 Pour chaque matière, on récupère ses sous-matières (ex: Arabe → Dictée, Participation...)
        matieres_list = []
        for m_row in matieres_rows:
            m_dict = dict(m_row)
            m_dict['sous_matieres'] = conn.execute(
                "SELECT * FROM sous_matieres WHERE matiere_id=? ORDER BY ordre, nom", (m_row['id'],)
            ).fetchall()
            matieres_list.append(m_dict)
        c_dict['matieres'] = matieres_list
        # ✅ NOUVEAU : Liste structurée des professeurs assignés (pour affichage en chips + pré-sélection du formulaire de modification)
        try:
            profs_list = conn.execute("""
                                      SELECT u.id, u.prenom, u.nom, cp.matiere
                                      FROM classe_profs cp
                                      JOIN users u ON cp.enseignant_id = u.id
                                      WHERE cp.classe_id = ?
                                      ORDER BY u.nom, u.prenom
                                      """, (c['id'],)).fetchall()
        except sqlite3.OperationalError:
            profs_list = []
        c_dict['profs_list'] = profs_list
        c_dict['profs_ids_string'] = ','.join(str(p['id']) for p in profs_list)
        classes.append(c_dict)

    enseignants = conn.execute("SELECT * FROM users WHERE role='enseignant' ORDER BY nom").fetchall()

    # ─── ADAPTATION : RÉCUPÉRATION DU CATALOGUE DES MATIÈRES ───
    # ✅ FIX: Sélectionne id ET nom (id est nécessaire pour les actions modifier/supprimer) (CONSERVÉ)
    # ─── CORRECTION 2 : RÉCUPÉRATION DU CATALOGUE DES MATIÈRES PAR CYCLE ───
    catalogue_matieres = conn.execute("""
            SELECT MIN(m.id) as id, m.nom 
            FROM matieres m
            JOIN classes c ON m.classe_id = c.id
            WHERE c.cycle = ? OR (c.cycle IS NULL AND ? = 'Primaire')
            GROUP BY m.nom 
            ORDER BY m.nom
        """, (cycle_filter, cycle_filter)).fetchall()

    conn.close()

    # 🆕 Étape 3 : si aucune classe précise n'est choisie, on affiche le hub de sélection (Hub 2)
    classe_id_filter = request.args.get('classe_id', type=int)
    if not classe_id_filter:
        return render_template_string(CLASSES_PICK_HTML, classes=classes, enseignants=enseignants,
                                       cycle=cycle_filter, notif_count=get_notif_count())

    # 🆕 Étape 4 : une classe précise est choisie → on n'affiche plus qu'elle, avec toutes ses informations
    classe = next((c for c in classes if c['id'] == classe_id_filter), None)
    if not classe:
        flash('Classe introuvable.', 'error')
        return redirect(url_for('gestion_classes', cycle=cycle_filter))

    return render_template_string(CLASSES_DETAIL_HTML, classe=classe, classes=classes, enseignants=enseignants,
                                  cycle=cycle_filter, catalogue_matieres=catalogue_matieres, notif_count=get_notif_count())


# 🆕 Page "Toutes les matières" — accessible depuis le hub /classes, liste TOUTES les
# matières de la base (toutes classes confondues) avec possibilité de modifier
# (coefficient / enseignant) ou de supprimer chaque matière, sans avoir à naviguer
# classe par classe. Réutilise les actions déjà existantes 'edit_matiere_assignee' et
# 'delete_matiere' de la route /classes (POST) — voir le champ caché 'retour' plus bas.
@app.route('/classes/matieres')
@login_required
@role_required('admin', 'secretaire')
def toutes_les_matieres():
    conn = get_db()
    matieres = conn.execute("""
        SELECT m.id, m.nom, m.coefficient, m.classe_id, m.enseignant_id,
               c.nom as classe_nom, c.niveau as classe_niveau, c.cycle as classe_cycle,
               u.nom as prof_nom, u.prenom as prof_prenom
        FROM matieres m
        LEFT JOIN classes c ON m.classe_id = c.id
        LEFT JOIN users u ON m.enseignant_id = u.id
        ORDER BY c.cycle, c.nom COLLATE NOCASE, m.nom COLLATE NOCASE
    """).fetchall()
    classes = conn.execute("SELECT id, nom, niveau, cycle FROM classes ORDER BY cycle, nom COLLATE NOCASE").fetchall()
    enseignants = conn.execute(
        "SELECT id, nom, prenom FROM users WHERE role='enseignant' ORDER BY nom COLLATE NOCASE"
    ).fetchall()
    conn.close()
    return render_template_string(
        TOUTES_MATIERES_HTML, matieres=matieres, classes=classes, enseignants=enseignants,
        notif_count=get_notif_count(),
    )


# ─── GESTION DE L'EMPLOI DU TEMPS ───

JOURS_SEMAINE = ['Lundi', 'Mardi', 'Mercredi', 'Jeudi', 'Vendredi', 'Samedi']
# 🆕 Jours affichés sur les 3 exports PDF de l'emploi du temps (classe / enseignant / élève) :
# le samedi est exclu de l'impression sur demande de l'école. Il reste géré normalement
# partout ailleurs dans l'application (disponibilités des profs, écran emploi du temps...).
JOURS_EMPLOI_TEMPS_PDF = [j for j in JOURS_SEMAINE if j != 'Samedi']
# 🆕 Correspondance jour de la semaine Python (lundi=0) → libellé français utilisé dans
# la table emploi_temps, pour retrouver les créneaux du jour courant depuis les absences.
JOURS_PY_INDEX = {0: 'Lundi', 1: 'Mardi', 2: 'Mercredi', 3: 'Jeudi', 4: 'Vendredi', 5: 'Samedi', 6: 'Dimanche'}


def _seances_jour_classe(conn, classe_id, jour_nom=None):
    """🆕 Construit la liste des séances du jour pour UNE classe, à partir de son emploi du
    temps réel (matière + horaire) — TOUTES les séances réellement prévues ce jour-là, sans
    plafond. Si aucun créneau n'est configuré pour ce jour (classe sans emploi du temps saisi),
    on retombe sur 4 séances génériques (2 matin / 2 après-midi), pour toujours proposer un
    choix cohérent même sans emploi du temps. Retourne (jour_nom, seances_jour)."""
    jour_nom = jour_nom or JOURS_PY_INDEX.get(datetime.date.today().weekday())
    creneaux_jour = []
    if jour_nom in JOURS_SEMAINE:
        creneaux_jour = conn.execute("""
                                      SELECT e.*, m.nom as matiere_nom
                                      FROM emploi_temps e
                                               LEFT JOIN matieres m ON e.matiere_id = m.id
                                      WHERE e.classe_id = ? AND e.jour = ?
                                      ORDER BY e.heure_debut
                                      """, (classe_id, jour_nom)).fetchall()

    seances_jour = []
    if creneaux_jour:
        for i, c in enumerate(creneaux_jour):
            num = i + 1
            titre = c['matiere_nom'] or c['libelle'] or f'Séance {num}'
            debut_min = int(c['heure_debut'].split(':')[0]) * 60 + int(c['heure_debut'].split(':')[1]) if c['heure_debut'] else 0
            periode = 'Matin' if debut_min < 12 * 60 else 'Après-midi'
            icone = '🌅' if periode == 'Matin' else '🌇'
            seances_jour.append({
                'num': num, 'titre': titre,
                'sous': f"{c['heure_debut']}–{c['heure_fin']}", 'periode': periode, 'icone': icone,
            })
    else:
        for num, (label, periode, icone) in {
            1: ('Séance 1', 'Matin', '🌅'), 2: ('Séance 2', 'Matin', '🌅'),
            3: ('Séance 3', 'Après-midi', '🌇'), 4: ('Séance 4', 'Après-midi', '🌇'),
        }.items():
            seances_jour.append({'num': num, 'titre': label, 'sous': periode, 'periode': periode, 'icone': icone})

    return jour_nom, seances_jour


def _noms_seances_classe(conn, classe_id, jour_nom=None):
    """🆕 {numéro de séance: nom de la matière} pour une classe et un jour donnés. Sert à
    figer le vrai nom de la séance dans absences.creneau au moment de la saisie."""
    if not classe_id:
        return {}
    try:
        _, seances = _seances_jour_classe(conn, classe_id, jour_nom)
    except Exception:
        return {}
    return {s['num']: s['titre'] for s in seances}


def _creneaux_jour_enseignant(conn, enseignant_id, jour_nom=None):
    """🆕 Construit la liste des créneaux (matière + classe + horaire) réellement prévus
    AUJOURD'HUI pour UN enseignant, en se basant sur les MATIÈRES qui lui sont directement
    assignées (`matieres.enseignant_id`), croisées avec l'emploi du temps réel.

    🩹 CORRECTIF : l'ancienne version prenait TOUS les créneaux des classes assignées via
    `classe_profs`, sans filtrer sur la matière réellement enseignée — un prof d'Anglais
    voyait alors aussi apparaître les créneaux de Français et d'Arabe de la même classe.
    On filtre désormais directement sur `matieres.enseignant_id` (lien fiable posé lors de
    l'assignation du prof à ses matières), ce qui ne fait remonter QUE les créneaux de la/les
    matière(s) que cet enseignant enseigne réellement.

    Retourne (jour_nom, creneaux) — creneaux est vide si l'enseignant n'a aucune matière
    assignée ou aucun emploi du temps saisi pour ce jour (l'absence sera alors enregistrée
    pour la journée entière, comme avant)."""
    jour_nom = jour_nom or JOURS_PY_INDEX.get(datetime.date.today().weekday())
    creneaux = []
    if jour_nom in JOURS_SEMAINE:
        rows = conn.execute("""
            SELECT DISTINCT et.id as et_id, et.heure_debut, et.heure_fin, et.libelle,
                   m.nom as matiere_nom, c.nom as classe_nom, c.niveau as classe_niveau
            FROM matieres m
            JOIN classes c ON c.id = m.classe_id
            JOIN emploi_temps et ON et.classe_id = c.id AND et.matiere_id = m.id AND et.jour = ?
            WHERE m.enseignant_id = ?
            ORDER BY et.heure_debut
        """, (jour_nom, enseignant_id)).fetchall()
        for r in rows:
            titre = r['matiere_nom'] or r['libelle'] or 'Cours'
            debut_min = int(r['heure_debut'].split(':')[0]) * 60 + int(r['heure_debut'].split(':')[1]) if r['heure_debut'] else 0
            periode = 'Matin' if debut_min < 12 * 60 else 'Après-midi'
            icone = '🌅' if periode == 'Matin' else '🌇'
            creneaux.append({
                'id': r['et_id'], 'titre': titre,
                'classe': f"{r['classe_niveau']} {r['classe_nom']}",
                'sous': f"{r['heure_debut']}–{r['heure_fin']}", 'periode': periode, 'icone': icone,
            })
    return jour_nom, creneaux


# 🆕 APPEL ENSEIGNANT : l'enseignant ne peut faire l'appel QUE pendant une de ses séances.
# Ses séances viennent de l'emploi du temps (créneaux dont la matière lui est assignée via
# `matieres.enseignant_id`). Marge (en minutes) autour du créneau : mettre 0 pour être strict.
SEANCE_TOLERANCE_AVANT_MIN = 5   # l'appel s'ouvre 5 min avant le début de la séance
SEANCE_TOLERANCE_APRES_MIN = 0   # et se ferme exactement à l'heure de fin


def _hhmm_en_minutes(valeur):
    try:
        h, m = str(valeur).split(':')[:2]
        return int(h) * 60 + int(m)
    except Exception:
        return None


def _seances_en_cours_enseignant(conn, enseignant_id, maintenant=None):
    """🆕 Retourne (jour_nom, en_cours, prochaines, refresh_s) pour UN enseignant, à l'instant T.
    - en_cours  : séances actives MAINTENANT (avec classe_id et numéro de séance `num` de la
                  classe, identique à celui de _seances_jour_classe pour rester compatible
                  avec la table `absences`) ;
    - prochaines: séances restantes plus tard aujourd'hui ;
    - refresh_s : secondes avant le prochain changement d'état (ouverture/fermeture), ou None.
    Aucune séance en cours => aucun élève ne doit être affiché."""
    maintenant = maintenant or datetime.datetime.now()
    jour_nom = JOURS_PY_INDEX.get(maintenant.weekday())
    now_min = maintenant.hour * 60 + maintenant.minute
    now_sec = now_min * 60 + maintenant.second
    en_cours, prochaines, bornes = [], [], []
    if jour_nom in JOURS_SEMAINE:
        rows = conn.execute("""
            SELECT DISTINCT et.id AS et_id, et.classe_id, et.heure_debut, et.heure_fin, et.salle, et.libelle,
                   m.nom AS matiere_nom, c.nom AS classe_nom, c.niveau AS classe_niveau
            FROM matieres m
            JOIN classes c ON c.id = m.classe_id
            JOIN emploi_temps et ON et.classe_id = c.id AND et.matiere_id = m.id AND et.jour = ?
            WHERE m.enseignant_id = ?
            ORDER BY et.heure_debut
        """, (jour_nom, enseignant_id)).fetchall()
        numeros = {}
        for r in rows:
            cid = r['classe_id']
            if cid not in numeros:
                ids = [x['id'] for x in conn.execute(
                    "SELECT id FROM emploi_temps WHERE classe_id=? AND jour=? ORDER BY heure_debut", (cid, jour_nom))]
                numeros[cid] = {i: n + 1 for n, i in enumerate(ids)}
            d, f = _hhmm_en_minutes(r['heure_debut']), _hhmm_en_minutes(r['heure_fin'])
            if d is None or f is None or f <= d:
                continue
            ouverture = d - SEANCE_TOLERANCE_AVANT_MIN
            fermeture = f + SEANCE_TOLERANCE_APRES_MIN
            bornes += [ouverture * 60, fermeture * 60]
            item = {
                'et_id': r['et_id'], 'classe_id': cid, 'num': numeros[cid].get(r['et_id'], 1),
                'matiere': r['matiere_nom'] or r['libelle'] or 'Cours',
                'classe': (f"{r['classe_niveau']} {r['classe_nom']}" if r['classe_niveau'] else r['classe_nom']),
                'debut': r['heure_debut'], 'fin': r['heure_fin'], 'salle': r['salle'] or '',
                'pct': max(0, min(100, round((now_min - d) * 100 / (f - d)))),
                'restant_min': max(f - now_min, 0),
            }
            if ouverture <= now_min < fermeture:
                en_cours.append(item)
            elif now_min < ouverture:
                prochaines.append(item)
    futures = [b for b in bornes if b > now_sec]
    refresh_s = (min(futures) - now_sec + 2) if futures else None
    return jour_nom, en_cours, prochaines, refresh_s


@app.route('/emploi-temps', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'agent_admin', 'secretaire')
def emploi_temps():
    conn = get_db()
    role = session.get('role')

    # 🆕 SECRÉTAIRE : accès en lecture/écriture à l'emploi du temps, mais limité aux
    # classes qui lui sont assignées (table classe_secretaires), même principe que pour
    # les absences. On vérifie ici toute tentative d'accès (GET ou POST) à une classe qui
    # ne lui serait pas assignée, pour empêcher un accès/modif via une classe_id trafiquée.
    def _secretaire_autorisee(cid):
        if role != 'secretaire':
            return True
        if not cid:
            return False
        return conn.execute(
            "SELECT 1 FROM classe_secretaires WHERE classe_id=? AND secretaire_id=?",
            (cid, session['user_id'])).fetchone() is not None

    if request.method == 'POST':
        action = request.form.get('action')
        classe_id = request.form.get('classe_id')

        if not _secretaire_autorisee(classe_id):
            conn.close()
            flash("Vous n'êtes pas autorisé(e) à modifier l'emploi du temps de cette classe.", 'error')
            return redirect(url_for('emploi_temps'))

        if action == 'copier_classe' and not _secretaire_autorisee(request.form.get('classe_cible_id')):
            conn.close()
            flash("Vous n'êtes pas autorisé(e) à modifier l'emploi du temps de la classe de destination.", 'error')
            return redirect(url_for('emploi_temps', classe_id=classe_id))

        if action == 'add':
            jour = request.form.get('jour')
            heure_debut = request.form.get('heure_debut')
            heure_fin = request.form.get('heure_fin')
            matiere_id = request.form.get('matiere_id') or None
            # 🆕 Plusieurs sous-matières peuvent désormais être cochées pour un même créneau
            # (ex: Français 8h-10h → Grammaire + Conjugaison). On garde aussi la 1ère comme
            # "sous_matiere_id" sur la colonne historique, pour rester compatible avec tout
            # code qui la lirait encore ailleurs.
            sous_matiere_ids = [s for s in request.form.getlist('sous_matiere_ids') if s]
            sous_matiere_id = sous_matiere_ids[0] if sous_matiere_ids else None
            libelle = request.form.get('libelle', '').strip()
            salle = request.form.get('salle', '').strip()
            if jour and heure_debut and heure_fin:
                cur = conn.execute("""INSERT INTO emploi_temps
                                 (classe_id, jour, heure_debut, heure_fin, matiere_id, sous_matiere_id, libelle, salle)
                                 VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
                             (classe_id, jour, heure_debut, heure_fin, matiere_id, sous_matiere_id, libelle, salle))
                nouveau_creneau_id = cur.lastrowid
                for sm_id in sous_matiere_ids:
                    conn.execute("INSERT INTO emploi_temps_sous_matieres (creneau_id, sous_matiere_id) VALUES (?, ?)",
                                 (nouveau_creneau_id, sm_id))
                conn.commit()
                flash('Créneau ajouté avec succès !', 'success')
            else:
                flash('Veuillez renseigner le jour et les horaires.', 'error')

        elif action == 'edit':
            creneau_id = request.form.get('creneau_id')
            jour = request.form.get('jour')
            heure_debut = request.form.get('heure_debut')
            heure_fin = request.form.get('heure_fin')
            matiere_id = request.form.get('matiere_id') or None
            sous_matiere_ids = [s for s in request.form.getlist('sous_matiere_ids') if s]
            sous_matiere_id = sous_matiere_ids[0] if sous_matiere_ids else None
            libelle = request.form.get('libelle', '').strip()
            salle = request.form.get('salle', '').strip()
            conn.execute("""UPDATE emploi_temps
                             SET jour=?, heure_debut=?, heure_fin=?, matiere_id=?, sous_matiere_id=?, libelle=?, salle=?
                             WHERE id=?""",
                         (jour, heure_debut, heure_fin, matiere_id, sous_matiere_id, libelle, salle, creneau_id))
            # 🆕 On repart de zéro sur la liaison multi sous-matières de ce créneau, puis on
            # réinsère la sélection actuelle (plus simple et plus sûr qu'un diff ligne à ligne).
            conn.execute("DELETE FROM emploi_temps_sous_matieres WHERE creneau_id=?", (creneau_id,))
            for sm_id in sous_matiere_ids:
                conn.execute("INSERT INTO emploi_temps_sous_matieres (creneau_id, sous_matiere_id) VALUES (?, ?)",
                             (creneau_id, sm_id))
            conn.commit()
            flash('Créneau mis à jour avec succès !', 'success')

        elif action == 'delete':
            creneau_id = request.form.get('creneau_id')
            # 🆕 Les clés étrangères ne sont pas appliquées automatiquement sur cette connexion :
            # on nettoie donc explicitement les liaisons multi sous-matières de ce créneau.
            conn.execute("DELETE FROM emploi_temps_sous_matieres WHERE creneau_id=?", (creneau_id,))
            conn.execute("DELETE FROM emploi_temps WHERE id=?", (creneau_id,))
            conn.commit()
            flash('Créneau supprimé avec succès !', 'success')

        elif action == 'dupliquer_semaine':
            # Copie tous les créneaux du Lundi vers Mardi→Samedi (gain de temps pour un emploi du temps régulier)
            base = conn.execute(
                "SELECT * FROM emploi_temps WHERE classe_id=? AND jour='Lundi'", (classe_id,)).fetchall()
            # 🆕 On récupère aussi, pour chaque créneau source, la liste complète de ses
            # sous-matières liées (et non plus une seule), pour les reporter sur les copies.
            sm_par_creneau = {}
            for c in base:
                sm_par_creneau[c['id']] = [r['sous_matiere_id'] for r in conn.execute(
                    "SELECT sous_matiere_id FROM emploi_temps_sous_matieres WHERE creneau_id=?", (c['id'],)).fetchall()]
            for jour in JOURS_SEMAINE[1:]:
                conn.execute("""DELETE FROM emploi_temps_sous_matieres WHERE creneau_id IN
                                 (SELECT id FROM emploi_temps WHERE classe_id=? AND jour=?)""", (classe_id, jour))
                conn.execute("DELETE FROM emploi_temps WHERE classe_id=? AND jour=?", (classe_id, jour))
                for c in base:
                    cur = conn.execute("""INSERT INTO emploi_temps
                                     (classe_id, jour, heure_debut, heure_fin, matiere_id, sous_matiere_id, libelle, salle)
                                     VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
                                 (classe_id, jour, c['heure_debut'], c['heure_fin'], c['matiere_id'], c['sous_matiere_id'], c['libelle'], c['salle']))
                    nouveau_id = cur.lastrowid
                    for sm_id in sm_par_creneau.get(c['id'], []):
                        conn.execute("INSERT INTO emploi_temps_sous_matieres (creneau_id, sous_matiere_id) VALUES (?, ?)",
                                     (nouveau_id, sm_id))
            conn.commit()
            flash('Emploi du temps du Lundi dupliqué sur toute la semaine !', 'success')

        elif action == 'dupliquer_jour':
            # Copie les créneaux d'un jour source vers un ou plusieurs jours cibles choisis librement
            jour_source = request.form.get('jour_source')
            jours_cibles = [j for j in request.form.getlist('jours_cibles') if j != jour_source]
            base = conn.execute(
                "SELECT * FROM emploi_temps WHERE classe_id=? AND jour=?", (classe_id, jour_source)).fetchall()
            # 🆕 Idem : on reporte la liste complète des sous-matières de chaque créneau source.
            sm_par_creneau = {}
            for c in base:
                sm_par_creneau[c['id']] = [r['sous_matiere_id'] for r in conn.execute(
                    "SELECT sous_matiere_id FROM emploi_temps_sous_matieres WHERE creneau_id=?", (c['id'],)).fetchall()]
            if jour_source and jours_cibles:
                for jour in jours_cibles:
                    conn.execute("""DELETE FROM emploi_temps_sous_matieres WHERE creneau_id IN
                                     (SELECT id FROM emploi_temps WHERE classe_id=? AND jour=?)""", (classe_id, jour))
                    conn.execute("DELETE FROM emploi_temps WHERE classe_id=? AND jour=?", (classe_id, jour))
                    for c in base:
                        cur = conn.execute("""INSERT INTO emploi_temps
                                         (classe_id, jour, heure_debut, heure_fin, matiere_id, sous_matiere_id, libelle, salle)
                                         VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
                                     (classe_id, jour, c['heure_debut'], c['heure_fin'], c['matiere_id'], c['sous_matiere_id'], c['libelle'], c['salle']))
                        nouveau_id = cur.lastrowid
                        for sm_id in sm_par_creneau.get(c['id'], []):
                            conn.execute("INSERT INTO emploi_temps_sous_matieres (creneau_id, sous_matiere_id) VALUES (?, ?)",
                                         (nouveau_id, sm_id))
                conn.commit()
                flash(f"Créneaux du {jour_source} dupliqués vers {', '.join(jours_cibles)} !", 'success')
            else:
                flash('Veuillez choisir un jour source et au moins un jour cible.', 'error')

        elif action == 'copier_classe':
            # Copie l'intégralité de l'emploi du temps de la classe actuelle vers une autre classe
            classe_cible_id = request.form.get('classe_cible_id')
            if classe_cible_id and str(classe_cible_id) != str(classe_id):
                source = conn.execute("""
                                       SELECT e.*, m.nom as matiere_nom
                                       FROM emploi_temps e
                                                LEFT JOIN matieres m ON e.matiere_id = m.id
                                       WHERE e.classe_id = ?
                                       """, (classe_id,)).fetchall()
                conn.execute("""DELETE FROM emploi_temps_sous_matieres WHERE creneau_id IN
                                 (SELECT id FROM emploi_temps WHERE classe_id=?)""", (classe_cible_id,))
                conn.execute("DELETE FROM emploi_temps WHERE classe_id=?", (classe_cible_id,))
                for c in source:
                    # La matière est propre à chaque classe : on reporte son nom en libellé libre
                    # plutôt qu'un identifiant de matière potentiellement invalide pour la classe cible.
                    libelle_copie = c['matiere_nom'] or c['libelle']
                    conn.execute("""INSERT INTO emploi_temps
                                     (classe_id, jour, heure_debut, heure_fin, matiere_id, libelle, salle)
                                     VALUES (?, ?, ?, ?, NULL, ?, ?)""",
                                 (classe_cible_id, c['jour'], c['heure_debut'], c['heure_fin'], libelle_copie, c['salle']))
                conn.commit()
                flash("Emploi du temps copié vers la classe sélectionnée !", 'success')
            else:
                flash('Veuillez choisir une classe de destination différente.', 'error')

        elif action == 'vider_classe':
            conn.execute("""DELETE FROM emploi_temps_sous_matieres WHERE creneau_id IN
                             (SELECT id FROM emploi_temps WHERE classe_id=?)""", (classe_id,))
            conn.execute("DELETE FROM emploi_temps WHERE classe_id=?", (classe_id,))
            conn.commit()
            flash("L'emploi du temps de cette classe a été entièrement vidé.", 'success')

        conn.close()
        return redirect(url_for('emploi_temps', classe_id=classe_id))

    # --- MÉTHODE GET ---
    classe_id = request.args.get('classe_id', type=int)
    vue = request.args.get('vue')
    enseignant_id = request.args.get('enseignant_id', type=int)

    # 🆕 HUB : "Emploi du temps" propose d'abord un choix Classe / Enseignant, sauf si on
    # arrive directement avec une classe ou un enseignant déjà précisé (liens existants,
    # ex: fiche élève, portail parent → comportement inchangé, pas de hub affiché).
    if not classe_id and not enseignant_id and vue not in ('classe', 'prof'):
        conn.close()
        return render_template_string(EMPLOI_TEMPS_HUB_HTML, notif_count=get_notif_count(),
                                      banniere_emploi_temps_filename=get_banniere_emploi_temps_filename())

    # 🆕 VUE ENSEIGNANT : réservée à l'admin / agent admin — la secrétaire, dont l'accès est
    # limité à ses classes assignées, n'a pas de vue à l'échelle globale d'un enseignant.
    if vue == 'prof' or enseignant_id:
        if role == 'secretaire':
            conn.close()
            flash("Vous n'êtes pas autorisé(e) à consulter l'emploi du temps par enseignant.", 'error')
            return redirect(url_for('emploi_temps'))

        if enseignant_id:
            prof = conn.execute("SELECT id, prenom, nom FROM users WHERE id=? AND role='enseignant'",
                                (enseignant_id,)).fetchone()
            if not prof:
                conn.close()
                abort(404)

            # 🆕 On vérifie, sur TOUTES les classes, les créneaux liés à une matière enseignée
            # par ce professeur (une matière appartient à une classe et, en option, un enseignant) —
            # puis on génère son emploi du temps complet, avec le nom de la matière et de la classe.
            creneaux = conn.execute("""
                                     SELECT e.*, m.nom as matiere_nom, c.nom as classe_nom, c.niveau as classe_niveau
                                     FROM emploi_temps e
                                              JOIN matieres m ON e.matiere_id = m.id
                                              JOIN classes c ON m.classe_id = c.id
                                     WHERE m.enseignant_id = ?
                                     ORDER BY e.heure_debut
                                     """, (enseignant_id,)).fetchall()

            def _hhmm_vers_min(hhmm):
                try:
                    h, m = hhmm.split(':')
                    return int(h) * 60 + int(m)
                except Exception:
                    return 0

            PX_PER_MIN = 1.3
            grille = {jour: [] for jour in JOURS_SEMAINE}
            if creneaux:
                debuts = [_hhmm_vers_min(c['heure_debut']) for c in creneaux]
                fins = [_hhmm_vers_min(c['heure_fin']) for c in creneaux]
                grid_start_h = min(debuts) // 60
                grid_end_h = -(-max(fins) // 60)
                if grid_end_h <= grid_start_h:
                    grid_end_h = grid_start_h + 1
            else:
                grid_start_h, grid_end_h = 8, 18
            grid_start_min = grid_start_h * 60
            grid_height_px = round((grid_end_h - grid_start_h) * 60 * PX_PER_MIN)

            total_minutes = 0
            jours_count = {j: 0 for j in JOURS_SEMAINE}
            classes_utilisees = set()
            for c in creneaux:
                cd = dict(c)
                debut_min = _hhmm_vers_min(c['heure_debut'])
                fin_min = _hhmm_vers_min(c['heure_fin'])
                cd['top_px'] = round((debut_min - grid_start_min) * PX_PER_MIN)
                cd['height_px'] = max(round((fin_min - debut_min) * PX_PER_MIN) - 3, 22)
                cd['debut_min'] = debut_min
                cd['fin_min'] = fin_min
                cd['classe_label'] = (f"{c['classe_niveau']} {c['classe_nom']}"
                                      if c['classe_niveau'] else c['classe_nom'])
                grille[c['jour']].append(cd)
                total_minutes += max(fin_min - debut_min, 0)
                jours_count[c['jour']] += 1
                classes_utilisees.add(c['classe_nom'])

            stats_et = {'total_creneaux': len(creneaux), 'total_heures': round(total_minutes / 60, 1),
                        'nb_classes': len(classes_utilisees),
                        'jour_charge': max(jours_count, key=jours_count.get) if any(jours_count.values()) else '—'}
            grid_meta = {'start_h': grid_start_h, 'end_h': grid_end_h, 'height_px': grid_height_px,
                        'heures_axe': list(range(grid_start_h, grid_end_h + 1)), 'px_per_min': PX_PER_MIN,
                        'row_height_px': round(60 * PX_PER_MIN)}

            conn.close()
            return render_template_string(EMPLOI_TEMPS_PROF_HTML, prof=prof, grille=grille, jours=JOURS_SEMAINE,
                                          stats_et=stats_et, grid_meta=grid_meta, notif_count=get_notif_count())

        # 🆕 Aucun enseignant choisi pour l'instant → liste des enseignants
        profs = conn.execute("""
                              SELECT u.id, u.prenom, u.nom, u.fonction,
                                     (SELECT COUNT(*) FROM emploi_temps e JOIN matieres m ON e.matiere_id = m.id
                                      WHERE m.enseignant_id = u.id) as nb_creneaux,
                                     (SELECT COUNT(DISTINCT m.classe_id) FROM matieres m WHERE m.enseignant_id = u.id) as nb_classes
                              FROM users u
                              WHERE u.role = 'enseignant'
                              ORDER BY u.nom, u.prenom
                              """).fetchall()
        conn.close()
        return render_template_string(EMPLOI_TEMPS_PROF_LISTE_HTML, profs=profs, notif_count=get_notif_count())

    if role == 'secretaire':
        # 🆕 La secrétaire ne voit que ses classes assignées (classe_secretaires)
        classes = conn.execute("""
                                SELECT c.*, (SELECT COUNT(*) FROM eleves WHERE classe_id = c.id) as nb_eleves,
                                       (SELECT COUNT(*) FROM emploi_temps WHERE classe_id = c.id) as nb_creneaux
                                FROM classes c
                                WHERE EXISTS (SELECT 1 FROM classe_secretaires cs
                                              WHERE cs.classe_id = c.id AND cs.secretaire_id = ?)
                                ORDER BY c.cycle, c.niveau, c.nom
                                """, (session['user_id'],)).fetchall()
        if classe_id and not _secretaire_autorisee(classe_id):
            conn.close()
            flash("Vous n'êtes pas autorisé(e) à consulter l'emploi du temps de cette classe.", 'error')
            return redirect(url_for('emploi_temps'))
    else:
        classes = conn.execute("""
                                SELECT c.*, (SELECT COUNT(*) FROM eleves WHERE classe_id = c.id) as nb_eleves,
                                       (SELECT COUNT(*) FROM emploi_temps WHERE classe_id = c.id) as nb_creneaux
                                FROM classes c
                                ORDER BY c.cycle, c.niveau, c.nom
                                """).fetchall()

    classe_actuelle = None
    matieres = []
    grille = {jour: [] for jour in JOURS_SEMAINE}
    stats_et = {'total_creneaux': 0, 'total_heures': 0, 'nb_matieres': 0, 'jour_charge': '—'}
    grid_meta = {'start_h': 8, 'end_h': 18, 'height_px': 780, 'heures_axe': list(range(8, 19))}

    if classe_id:
        classe_actuelle = conn.execute("SELECT * FROM classes WHERE id=?", (classe_id,)).fetchone()
        matieres = conn.execute("""
                                 SELECT m.*, u.prenom || ' ' || u.nom as enseignant_nom
                                 FROM matieres m
                                          LEFT JOIN users u ON m.enseignant_id = u.id
                                 WHERE m.classe_id = ?
                                 ORDER BY m.nom
                                 """, (classe_id,)).fetchall()
        creneaux = conn.execute("""
                                 SELECT e.*, m.nom as matiere_nom, u.prenom || ' ' || u.nom as enseignant_nom,
                                        (SELECT GROUP_CONCAT(nom, ', ') FROM (
                                             SELECT sm2.nom as nom
                                             FROM emploi_temps_sous_matieres ets2
                                             JOIN sous_matieres sm2 ON sm2.id = ets2.sous_matiere_id
                                             WHERE ets2.creneau_id = e.id
                                             ORDER BY sm2.ordre, sm2.nom
                                         )) as sous_matiere_nom,
                                        (SELECT GROUP_CONCAT(ets3.sous_matiere_id) FROM emploi_temps_sous_matieres ets3
                                         WHERE ets3.creneau_id = e.id) as sous_matiere_ids_str
                                 FROM emploi_temps e
                                          LEFT JOIN matieres m ON e.matiere_id = m.id
                                          LEFT JOIN users u ON m.enseignant_id = u.id
                                 WHERE e.classe_id = ?
                                 ORDER BY e.heure_debut
                                 """, (classe_id,)).fetchall()

        # ── Calcul de la grille horaire (vue "Calendrier") : on positionne chaque
        # créneau verticalement en fonction de son heure, comme un vrai emploi du temps.
        def _hhmm_vers_min(hhmm):
            try:
                h, m = hhmm.split(':')
                return int(h) * 60 + int(m)
            except Exception:
                return 0

        PX_PER_MIN = 1.3
        if creneaux:
            debuts = [_hhmm_vers_min(c['heure_debut']) for c in creneaux]
            fins = [_hhmm_vers_min(c['heure_fin']) for c in creneaux]
            grid_start_h = min(debuts) // 60
            grid_end_h = -(-max(fins) // 60)  # arrondi au supérieur
            if grid_end_h <= grid_start_h:
                grid_end_h = grid_start_h + 1
        else:
            grid_start_h, grid_end_h = 8, 18

        grid_start_min = grid_start_h * 60
        grid_height_px = round((grid_end_h - grid_start_h) * 60 * PX_PER_MIN)

        total_minutes = 0
        jours_count = {j: 0 for j in JOURS_SEMAINE}
        matieres_utilisees = set()

        for c in creneaux:
            cd = dict(c)
            debut_min = _hhmm_vers_min(c['heure_debut'])
            fin_min = _hhmm_vers_min(c['heure_fin'])
            cd['top_px'] = round((debut_min - grid_start_min) * PX_PER_MIN)
            cd['height_px'] = max(round((fin_min - debut_min) * PX_PER_MIN) - 3, 22)
            cd['debut_min'] = debut_min
            cd['fin_min'] = fin_min
            grille[c['jour']].append(cd)
            total_minutes += max(fin_min - debut_min, 0)
            jours_count[c['jour']] += 1
            if c['matiere_nom']:
                matieres_utilisees.add(c['matiere_nom'])

        stats_et['total_creneaux'] = len(creneaux)
        stats_et['total_heures'] = round(total_minutes / 60, 1)
        stats_et['nb_matieres'] = len(matieres_utilisees)
        if any(jours_count.values()):
            stats_et['jour_charge'] = max(jours_count, key=jours_count.get)

        grid_meta = {'start_h': grid_start_h, 'end_h': grid_end_h, 'height_px': grid_height_px,
                     'heures_axe': list(range(grid_start_h, grid_end_h + 1)), 'px_per_min': PX_PER_MIN,
                     'row_height_px': round(60 * PX_PER_MIN)}

    # 🆕 Carte matière → sous-matières (ex: Arabe -> Dictée, Participation...) pour le
    # sélecteur dépendant "Sous-matière" du formulaire d'ajout/modification de créneau,
    # même principe que sur la page Notes.
    sous_matieres_map = {}
    for m in matieres:
        sm_rows = conn.execute(
            "SELECT id, nom FROM sous_matieres WHERE matiere_id=? AND actif=1 ORDER BY ordre, nom",
            (m['id'],)).fetchall()
        if sm_rows:
            sous_matieres_map[m['id']] = [dict(r) for r in sm_rows]

    conn.close()
    return render_template_string(EMPLOI_TEMPS_HTML, classes=classes, classe_actuelle=classe_actuelle,
                                  matieres=matieres, grille=grille, jours=JOURS_SEMAINE, classe_id=classe_id,
                                  stats_et=stats_et, grid_meta=grid_meta, notif_count=get_notif_count(),
                                  sous_matieres_json=json.dumps(sous_matieres_map))


# 🆕 Export PDF de l'emploi du temps d'une classe : jusqu'ici, le bouton "🖨️ Imprimer" ne
# faisait qu'un window.print() du navigateur, ce qui donnait une simple capture visuelle de
# la page (souvent mal coupée / mise en page dégradée). Ici on génère un VRAI PDF côté
# serveur avec reportlab (même moteur que les bulletins/reçus de l'app), en reprenant le
# même découpage par jour et le même code couleur que la vue "Liste" à l'écran (.et-day /
# .et-slot), à partir des créneaux réellement enregistrés dans l'emploi du temps.
@app.route('/export/emploi-temps/<int:classe_id>')
@login_required
@role_required('admin', 'agent_admin', 'secretaire')
def export_emploi_temps_pdf(classe_id):
    try:
        conn = get_db()
        if session.get('role') == 'secretaire':
            autorise = conn.execute(
                "SELECT 1 FROM classe_secretaires WHERE classe_id=? AND secretaire_id=?",
                (classe_id, session['user_id'])).fetchone()
            if not autorise:
                conn.close()
                flash("Vous n'êtes pas autorisé(e) à consulter l'emploi du temps de cette classe.", 'error')
                return redirect(url_for('emploi_temps'))

        classe = conn.execute("SELECT * FROM classes WHERE id=?", (classe_id,)).fetchone()
        if not classe:
            conn.close()
            flash("Classe introuvable.", 'error')
            return redirect(url_for('emploi_temps'))

        creneaux = conn.execute("""
                                 SELECT e.*, m.nom as matiere_nom, u.prenom || ' ' || u.nom as enseignant_nom,
                                        (SELECT GROUP_CONCAT(nom, ', ') FROM (
                                             SELECT sm2.nom as nom
                                             FROM emploi_temps_sous_matieres ets2
                                             JOIN sous_matieres sm2 ON sm2.id = ets2.sous_matiere_id
                                             WHERE ets2.creneau_id = e.id
                                             ORDER BY sm2.ordre, sm2.nom
                                         )) as sous_matiere_nom,
                                        (SELECT GROUP_CONCAT(ets3.sous_matiere_id) FROM emploi_temps_sous_matieres ets3
                                         WHERE ets3.creneau_id = e.id) as sous_matiere_ids_str
                                 FROM emploi_temps e
                                          LEFT JOIN matieres m ON e.matiere_id = m.id
                                          LEFT JOIN users u ON m.enseignant_id = u.id
                                 WHERE e.classe_id = ?
                                 ORDER BY e.heure_debut
                                 """, (classe_id,)).fetchall()
        conn.close()

        grille = {jour: [] for jour in JOURS_SEMAINE}
        for c in creneaux:
            if c['jour'] in grille:
                grille[c['jour']].append(dict(c))

        from reportlab.lib.pagesizes import A4, landscape
        from reportlab.lib import colors
        from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, Image as RLImage
        from reportlab.lib.styles import ParagraphStyle
        from reportlab.lib.units import cm

        buf = io.BytesIO()
        page_w, page_h = landscape(A4)
        doc = SimpleDocTemplate(buf, pagesize=(page_w, page_h), topMargin=0.8 * cm, bottomMargin=1.4 * cm,
                                leftMargin=1 * cm, rightMargin=1 * cm)
        elems = []

        # 🆕 Bannière dédiée aux emplois du temps (uploadée depuis le hub "Emploi du temps"),
        # affichée en entier (jamais recadrée) au-dessus du bandeau de titre. À défaut, on
        # retombe sur le petit logo de l'école (comportement précédent).
        banniere_path = None
        banniere_fn = get_banniere_emploi_temps_filename()
        if banniere_fn:
            candidate = os.path.join(UPLOAD_FOLDER_LOGO, banniere_fn)
            if os.path.exists(candidate):
                banniere_path = candidate
        # 🆕 Bannière pleine largeur (bord à bord, de gauche à droite de la feuille), dessinée
        # directement sur le canevas — voir _pdf_banniere_pleine_largeur_setup.
        banniere_reader, banniere_h = (None, 0)
        if banniere_path:
            banniere_reader, banniere_h = _pdf_banniere_pleine_largeur_setup(banniere_path, page_w)
            if banniere_reader:
                espace_reserve = max(banniere_h - doc.topMargin, 0) + 0.15 * cm
                elems.append(Spacer(1, espace_reserve))
            else:
                banniere_path = None

        logo_path = None
        if not banniere_path:
            logo_fn = get_logo_filename()
            if logo_fn:
                candidate = os.path.join(UPLOAD_FOLDER_LOGO, logo_fn)
                if os.path.exists(candidate):
                    logo_path = candidate
            if logo_path:
                try:
                    logo_buf, iw_l, ih_l = _bulletin_flowable_image(logo_path)
                    MAX_LOGO_H = 1.7 * cm
                    logo_h = MAX_LOGO_H
                    logo_w = logo_h * (iw_l / ih_l)
                    MAX_LOGO_W = 4 * cm
                    if logo_w > MAX_LOGO_W:
                        logo_w = MAX_LOGO_W
                        logo_h = logo_w * (ih_l / iw_l)
                    logo_img = RLImage(logo_buf, width=logo_w, height=logo_h)
                    logo_img.hAlign = 'CENTER'
                    elems.append(logo_img)
                    elems.append(Spacer(1, 0.15 * cm))
                except Exception:
                    pass

        annee_scolaire_aff = _bulletin_annee_scolaire().replace('-', '/')
        sous_titre = f"Emploi du temps {annee_scolaire_aff} - Niveau {classe['niveau'] or classe['nom']}"
        _pdf_emploi_temps_entete(elems, page_w, "Emploi du temps", sous_titre, accent_hex='#0A84FF',
                                 show_school_name=not (banniere_path or logo_path))

        def _et_classe_titre(cr):
            t = cr.get('matiere_nom') or cr.get('libelle') or 'Créneau'
            if cr.get('sous_matiere_nom'):
                t += f" — {cr['sous_matiere_nom']}"
            return t

        def _et_classe_meta(cr):
            bits = []
            if cr.get('enseignant_nom'):
                bits.append(cr['enseignant_nom'])
            if cr.get('salle'):
                bits.append(f"Salle {cr['salle']}")
            return bits

        _pdf_emploi_temps_grille(elems, page_w, grille, _et_classe_titre, _et_classe_meta,
                                 jours=JOURS_EMPLOI_TEMPS_PDF)

        onFirstPage_cb = (_pdf_page_avec_banniere(banniere_reader, banniere_h, page_w, page_h, _pdf_footer)
                          if banniere_reader else _pdf_footer)
        doc.build(elems, onFirstPage=onFirstPage_cb, onLaterPages=_pdf_footer)
        buf.seek(0)
        nom_fichier = f"emploi_du_temps_{classe['nom']}.pdf".replace(' ', '_')
        return send_file(buf, as_attachment=True, download_name=nom_fichier, mimetype='application/pdf')
    except Exception as ex:
        flash(f'Erreur génération PDF: {ex}', 'error')
        return redirect(url_for('emploi_temps', classe_id=classe_id))


# 🆕 Export PDF de l'emploi du temps d'un ENSEIGNANT : jusqu'ici, le bouton "🖨️ Imprimer" de
# la vue enseignant (EMPLOI_TEMPS_PROF_HTML) ne faisait qu'un window.print() du navigateur.
# Ici on génère un VRAI PDF côté serveur avec reportlab, avec la même mise en page que
# l'export "classe" (bannière, bandeau de titre, grille par jour), pour un rendu identique
# au style de l'app — sauf qu'on affiche ici, pour chaque créneau, la classe concernée
# (puisqu'un même enseignant peut intervenir dans plusieurs classes) plutôt que l'enseignant.
@app.route('/export/emploi-temps-prof/<int:enseignant_id>')
@login_required
@role_required('admin', 'agent_admin')
def export_emploi_temps_prof_pdf(enseignant_id):
    try:
        conn = get_db()
        prof = conn.execute("SELECT id, prenom, nom FROM users WHERE id=? AND role='enseignant'",
                            (enseignant_id,)).fetchone()
        if not prof:
            conn.close()
            flash("Enseignant introuvable.", 'error')
            return redirect(url_for('emploi_temps', vue='prof'))

        creneaux = conn.execute("""
                                 SELECT e.*, m.nom as matiere_nom, c.nom as classe_nom, c.niveau as classe_niveau,
                                        (SELECT GROUP_CONCAT(nom, ', ') FROM (
                                             SELECT sm2.nom as nom
                                             FROM emploi_temps_sous_matieres ets2
                                             JOIN sous_matieres sm2 ON sm2.id = ets2.sous_matiere_id
                                             WHERE ets2.creneau_id = e.id
                                             ORDER BY sm2.ordre, sm2.nom
                                         )) as sous_matiere_nom
                                 FROM emploi_temps e
                                          JOIN matieres m ON e.matiere_id = m.id
                                          JOIN classes c ON m.classe_id = c.id
                                 WHERE m.enseignant_id = ?
                                 ORDER BY e.heure_debut
                                 """, (enseignant_id,)).fetchall()
        conn.close()

        grille = {jour: [] for jour in JOURS_SEMAINE}
        for c in creneaux:
            if c['jour'] in grille:
                grille[c['jour']].append(dict(c))

        from reportlab.lib.pagesizes import A4, landscape
        from reportlab.lib import colors
        from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, Image as RLImage
        from reportlab.lib.styles import ParagraphStyle
        from reportlab.lib.units import cm

        buf = io.BytesIO()
        page_w, page_h = landscape(A4)
        doc = SimpleDocTemplate(buf, pagesize=(page_w, page_h), topMargin=0.8 * cm, bottomMargin=1.4 * cm,
                                leftMargin=1 * cm, rightMargin=1 * cm)
        elems = []

        # 🆕 Bannière dédiée aux emplois du temps (uploadée depuis le hub "Emploi du temps") en
        # priorité ; à défaut on retombe sur la bannière générale du bulletin/reçus, pour ne
        # jamais afficher un bandeau vide si seule l'ancienne bannière a été configurée.
        banniere_path = None
        banniere_fn = get_banniere_emploi_temps_filename() or get_banniere_bulletin_filename()
        if banniere_fn:
            candidate = os.path.join(UPLOAD_FOLDER_LOGO, banniere_fn)
            if os.path.exists(candidate):
                banniere_path = candidate
        # 🆕 Bannière pleine largeur (bord à bord, de gauche à droite de la feuille), dessinée
        # directement sur le canevas — voir _pdf_banniere_pleine_largeur_setup.
        banniere_reader, banniere_h = (None, 0)
        if banniere_path:
            banniere_reader, banniere_h = _pdf_banniere_pleine_largeur_setup(banniere_path, page_w)
            if banniere_reader:
                espace_reserve = max(banniere_h - doc.topMargin, 0) + 0.15 * cm
                elems.append(Spacer(1, espace_reserve))
            else:
                banniere_path = None

        nb_creneaux = len(creneaux)
        sous_titre = (f"{prof['prenom']} {prof['nom']} — "
                      f"{nb_creneaux} créneau{'x' if nb_creneaux > 1 else ''} par semaine")
        _pdf_emploi_temps_entete(elems, page_w, "Emploi du temps — Enseignant", sous_titre,
                                 accent_hex='#22C55E', show_school_name=not banniere_path)

        def _et_prof_titre(cr):
            t = cr.get('matiere_nom') or 'Créneau'
            if cr.get('sous_matiere_nom'):
                t += f" — {cr['sous_matiere_nom']}"
            return t

        def _et_prof_meta(cr):
            classe_label = (f"{cr['classe_niveau']} {cr['classe_nom']}"
                            if cr.get('classe_niveau') else cr['classe_nom'])
            bits = [classe_label]
            if cr.get('salle'):
                bits.append(f"Salle {cr['salle']}")
            return bits

        _pdf_emploi_temps_grille(elems, page_w, grille, _et_prof_titre, _et_prof_meta,
                                 jours=JOURS_EMPLOI_TEMPS_PDF)

        onFirstPage_cb = (_pdf_page_avec_banniere(banniere_reader, banniere_h, page_w, page_h, _pdf_footer)
                          if banniere_reader else _pdf_footer)
        doc.build(elems, onFirstPage=onFirstPage_cb, onLaterPages=_pdf_footer)
        buf.seek(0)
        nom_fichier = f"emploi_du_temps_{prof['prenom']}_{prof['nom']}.pdf".replace(' ', '_')
        return send_file(buf, as_attachment=True, download_name=nom_fichier, mimetype='application/pdf')
    except Exception as ex:
        flash(f'Erreur génération PDF: {ex}', 'error')
        return redirect(url_for('emploi_temps', vue='prof', enseignant_id=enseignant_id))


# ─── GESTION DU CATALOGUE DES MATIÈRES ───

@app.route('/matieres/ajouter', methods=['POST'])
@login_required
@role_required('admin', 'secretaire')
def ajouter_matiere():
    nom = request.form.get('nom')
    if nom:
        nom = nom.strip()

    cycle = request.form.get('cycle')
    cycle_en_cours = cycle if cycle else 'Primaire'
    # 🩹 CORRECTIF : une matière ajoutée depuis la fiche d'une classe ne doit être assignée
    # qu'à CETTE classe, jamais à toutes les classes du cycle (ex: ajouter "Arabe" pour
    # Classe 1 Maternelle ne doit plus créer automatiquement "Arabe" pour Classe 2, Classe 3...).
    # Chaque classe doit désormais recevoir la matière explicitement, une par une.
    classe_id = request.form.get('classe_id', type=int)

    if nom and classe_id:
        conn = get_db()
        try:
            classe_cible = conn.execute("SELECT id FROM classes WHERE id=?", (classe_id,)).fetchone()
            if not classe_cible:
                flash("Classe introuvable.", "error")
            else:
                existe = conn.execute("SELECT id FROM matieres WHERE nom = ? AND classe_id = ?",
                                      (nom, classe_id)).fetchone()
                if existe:
                    flash(f"La matière « {nom} » est déjà assignée à cette classe.", "error")
                else:
                    conn.execute("INSERT INTO matieres (nom, coefficient, classe_id) VALUES (?, 1, ?)",
                                 (nom, classe_id))
                    conn.commit()
                    flash(f"Matière « {nom} » ajoutée à cette classe !", "success")
        except sqlite3.IntegrityError:
            flash("Cette matière existe déjà ou une erreur d'intégrité est survenue.", "error")
        except Exception:
            flash("Une erreur est survenue lors de l'ajout.", "error")
        finally:
            conn.close()
    elif nom and not classe_id:
        flash("Impossible d'ajouter une matière sans classe sélectionnée.", "error")

    return redirect(url_for('gestion_classes', cycle=cycle_en_cours, classe_id=classe_id))


@app.route('/matieres/modifier/<int:id>', methods=['POST'])
@login_required
@role_required('admin', 'secretaire')
def modifier_matiere(id):
    nom = request.form.get('nom', '').strip()
    cycle = request.form.get('cycle')
    if not nom:
        flash("Le nom de la matière ne peut pas être vide.", "error")
        return redirect(url_for('gestion_classes', cycle=cycle))
    conn = get_db()
    # ✅ FIX: Vérifie que la matière existe avant de modifier
    existing = conn.execute("SELECT id, nom FROM matieres WHERE id=?", (id,)).fetchone()
    if not existing:
        conn.close()
        flash("Matière introuvable.", "error")
        return redirect(url_for('gestion_classes', cycle=cycle))
    old_nom = existing['nom']
    # ✅ FIX: Renomme TOUTES les matières ayant le même nom (propagation catalogue)
    conn.execute("UPDATE matieres SET nom = ? WHERE nom = ?", (nom, old_nom))
    conn.commit()
    conn.close()
    flash(f"Matière \"{old_nom}\" renommée en \"{nom}\" dans tout le catalogue !", "success")
    return redirect(url_for('gestion_classes', cycle=cycle))


@app.route('/matieres/supprimer/<int:id>', methods=['POST'])
@login_required
@role_required('admin', 'secretaire')
def supprimer_matiere(id):
    cycle = request.form.get('cycle', 'Primaire')
    conn = get_db()

    # ✅ FIX: Vérifie que la matière existe
    existing = conn.execute("SELECT nom FROM matieres WHERE id=?", (id,)).fetchone()
    if not existing:
        conn.close()
        flash("Matière introuvable ou déjà supprimée.", "error")
        return redirect(url_for('gestion_classes', cycle=cycle))

    nom_mat = existing['nom']
    # 1. Nettoyer les dépendances pour éviter l'erreur d'intégrité
    conn.execute("DELETE FROM notes WHERE matiere_id = ?", (id,))
    conn.execute("DELETE FROM classe_matieres WHERE matiere_id = ?", (id,))

    # 2. Supprimer la matière
    conn.execute("DELETE FROM matieres WHERE id = ?", (id,))
    conn.commit()
    conn.close()

    flash(f"Matière \"{nom_mat}\" supprimée du catalogue.", "success")
    return redirect(url_for('gestion_classes', cycle=cycle))


@app.route('/classes/modifier/<int:id>', methods=['GET', 'POST'])
def modifier_classe(id):
    conn = get_db()
    if request.method == 'POST':
        nom_classe = request.form.get('nom')
        matieres_selectionnees = request.form.getlist('matieres')  # Liste des IDs cochés

        # Mettre à jour le nom de la classe
        conn.execute("UPDATE classes SET nom = ? WHERE id = ?", (nom_classe, id))

        # Synchroniser les matières de la classe
        conn.execute("DELETE FROM classe_matieres WHERE classe_id = ?", (id,))
        for mat_id in matieres_selectionnees:
            conn.execute("INSERT INTO classe_matieres (classe_id, matiere_id) VALUES (?, ?)", (id, mat_id))

        conn.commit()
        flash("Classe et matières mises à jour avec succès !", "success")
        return redirect(url_for('classes'))

    # GET : Récupération des données
    classe = conn.execute("SELECT * FROM classes WHERE id = ?", (id,)).fetchone()
    all_matieres = conn.execute("SELECT * FROM matieres").fetchall()

    # Récupérer les IDs des matières déjà associées à cette classe
    matieres_associees = [row['matiere_id'] for row in conn.execute(
        "SELECT matiere_id FROM classe_matieres WHERE classe_id = ?", (id,)
    ).fetchall()]

    return render_template_string(HTML_MODIFIER_CLASSE,
                                  classe=classe,
                                  all_matieres=all_matieres,
                                  matieres_associees=matieres_associees)


