# 🆕 Ordre de ramassage d'un élève assigné au transport — saisi par l'admin depuis la
# fiche du chauffeur (ou celle de l'accompagnatrice liée, même logique). 1 = premier
# récupéré ; les autres élèves gardent leur ordre respectif. Un élève sans numéro reste
# trié comme avant (par classe puis nom), après tous ceux qui ont un numéro.
@app.route('/eleves/<int:eleve_id>/transport/ordre', methods=['POST'])
@login_required
@role_required('admin')
def transport_eleve_ordre_update(eleve_id):
    conn = get_db()
    personnel_id = request.form.get('personnel_id')
    try:
        ordre_raw = (request.form.get('ordre') or '').strip()
        ordre_val = None
        if ordre_raw:
            try:
                ordre_val = max(1, int(float(ordre_raw)))
            except ValueError:
                ordre_val = None

        ligne = conn.execute("SELECT chauffeur_id FROM transport_eleves WHERE eleve_id=?", (eleve_id,)).fetchone()
        if not ligne:
            flash("Cet élève n'est assigné à aucun chauffeur.", 'error')
        else:
            chauffeur_id_ligne = ligne['chauffeur_id']
            if ordre_val is not None:
                # 🆕 Décalage automatique : tout élève du même chauffeur qui avait déjà ce
                # numéro (ou un numéro supérieur) avance d'un cran, pour éviter que deux
                # élèves se retrouvent avec le même numéro de ramassage.
                conn.execute(
                    "UPDATE transport_eleves SET ordre = ordre + 1 "
                    "WHERE chauffeur_id=? AND eleve_id!=? AND ordre >= ?",
                    (chauffeur_id_ligne, eleve_id, ordre_val)
                )
            conn.execute("UPDATE transport_eleves SET ordre=? WHERE eleve_id=?", (ordre_val, eleve_id))
            conn.commit()
            eleve_nom = conn.execute("SELECT prenom||' '||nom as nom FROM eleves WHERE id=?", (eleve_id,)).fetchone()
            log_action(conn, 'modification', 'transport_eleves_ordre', eleve_id,
                       f"Ordre de ramassage de {eleve_nom['nom'] if eleve_nom else eleve_id} mis à "
                       f"{ordre_val if ordre_val is not None else '—'}")
            flash('Ordre de ramassage enregistré !', 'success')
    finally:
        conn.close()
    if personnel_id:
        return redirect(url_for('personnel_hors_prof_detail', personnel_id=personnel_id))
    return redirect(url_for('personnel_hors_prof'))


# 🆕 ─────────────────────────────────────────────
# ABSENCES TRANSPORT — un élève assigné ne sera pas récupéré sur ce trajet aujourd'hui.
# Accessible à l'admin (depuis la fiche de l'accompagnatrice) et à l'accompagnatrice
# elle-même (depuis son espace personnel). Même logique "un clic = marque, un second clic
# = annule" que le module absences de classe (voir /api/absences/toggle).
# ─────────────────────────────────────────────

def _chauffeur_autorise_pour_absence(conn, chauffeur_id):
    """Vérifie qu'une accompagnatrice connectée est bien liée à ce chauffeur avant de la
    laisser marquer/annuler une absence ou consulter l'historique. L'admin a toujours accès."""
    if session.get('role') == 'admin':
        return True
    if session.get('role') == 'accompagnatrice':
        perso = conn.execute(
            "SELECT accompagnatrice_chauffeur_id FROM personnel_hors_prof WHERE id=?",
            (session['user_id'],)
        ).fetchone()
        return bool(perso and perso['accompagnatrice_chauffeur_id'] == chauffeur_id)
    return False


# 🆕 Détermine le trajet en cours : 'matinee' avant midi, 'soiree' à partir de midi. Utilisé
# pour étiqueter chaque absence/présence transport avec le bon trajet, et pour faire en
# sorte que le statut du jour affiché (à renseigner / présent / absent) reparte de zéro à
# midi sans tâche planifiée : à partir de midi, on ne recherche plus que les lignes du
# créneau 'soiree', donc les réponses du matin n'y apparaissent plus.
def _creneau_transport_actuel():
    return 'matinee' if datetime.datetime.now().hour < 12 else 'soiree'


CRENEAU_TRANSPORT_LABELS = {'matinee': 'Matinée', 'soiree': 'Soirée'}


@app.route('/api/transport/absence/toggle', methods=['POST'])
@login_required
@role_required('admin', 'accompagnatrice')
def api_transport_absence_toggle():
    """🆕 Marque/annule l'absence transport du JOUR (et du créneau en cours — matinée ou
    soirée) d'un élève en un clic (AJAX)."""
    data = request.get_json(silent=True) or {}
    try:
        eleve_id = int(data.get('eleve_id'))
    except (TypeError, ValueError):
        return jsonify({'error': "eleve_id manquant ou invalide"}), 400

    conn = get_db()
    ligne = conn.execute("SELECT chauffeur_id FROM transport_eleves WHERE eleve_id=?", (eleve_id,)).fetchone()
    if not ligne:
        conn.close()
        return jsonify({'error': "Cet élève n'est assigné à aucun chauffeur."}), 404
    chauffeur_id = ligne['chauffeur_id']

    if not _chauffeur_autorise_pour_absence(conn, chauffeur_id):
        conn.close()
        return jsonify({'error': "Vous n'avez pas accès à ce trajet."}), 403

    eleve = conn.execute("SELECT prenom, nom, parent_id FROM eleves WHERE id=?", (eleve_id,)).fetchone()
    aujourdhui = datetime.date.today().isoformat()
    creneau = _creneau_transport_actuel()
    creneau_label = CRENEAU_TRANSPORT_LABELS[creneau]
    existante = conn.execute(
        "SELECT id FROM transport_absences WHERE eleve_id=? AND date_absence=? AND creneau=?",
        (eleve_id, aujourdhui, creneau)).fetchone()

    # 🆕 Statut explicite (menu déroulant à 3 choix : à renseigner / présent / absent). Si le
    # client n'envoie pas de statut (ancien bouton "Présent/Absent" de la fiche admin), on
    # garde l'ancien comportement de bascule pour ne rien casser côté admin.
    statut_demande = data.get('statut')
    if statut_demande not in ('present', 'absent', 'a_renseigner', None):
        conn.close()
        return jsonify({'error': "Statut invalide."}), 400

    if statut_demande is None:
        statut_demande = 'present' if existante else 'absent'

    # On repart d'un état propre : on retire toute trace d'absence ou de présence confirmée
    # pour aujourd'hui ET pour ce créneau (matinée ou soirée), puis on ne recrée que ce qui
    # correspond au statut choisi. On ne touche jamais aux lignes de l'autre créneau : une
    # réponse donnée le matin reste intacte dans l'historique et n'interfère pas avec le
    # trajet du soir.
    if existante:
        conn.execute("DELETE FROM transport_absences WHERE id=?", (existante['id'],))
    conn.execute(
        "DELETE FROM transport_presences_confirmees WHERE eleve_id=? AND date_jour=? AND creneau=?",
        (eleve_id, aujourdhui, creneau)
    )

    if statut_demande == 'absent':
        conn.execute(
            "INSERT INTO transport_absences (eleve_id, chauffeur_id, date_absence, creneau, "
            "signale_par_id, signale_par_nom, signale_par_role) VALUES (?,?,?,?,?,?,?)",
            (eleve_id, chauffeur_id, aujourdhui, creneau,
             session.get('user_id'), session.get('nom_complet', ''), session.get('role', ''))
        )
        conn.commit()
        if eleve['parent_id']:
            notif_to_parent(eleve['parent_id'],
                            f"{eleve['prenom']} {eleve['nom']} a été signalé(e) absent(e) du transport "
                            f"de la {creneau_label.lower()} aujourd'hui ({aujourdhui}).", conn,
                            categorie='autre', titre='Absence au transport', prio='haute',
                            meta={'ico': '🚌', 'couleur': '#F59E0B', 'cta': 'Voir le détail'})
            conn.commit()
        log_action(conn, 'modification', 'transport_absences', eleve_id,
                   f"Absence transport ({creneau_label}) signalée pour {eleve['prenom']} {eleve['nom']} le {aujourdhui}.")
    elif statut_demande == 'present':
        conn.execute(
            "INSERT INTO transport_presences_confirmees (eleve_id, chauffeur_id, date_jour, creneau, "
            "confirme_par_id, confirme_par_nom, confirme_par_role) VALUES (?,?,?,?,?,?,?)",
            (eleve_id, chauffeur_id, aujourdhui, creneau,
             session.get('user_id'), session.get('nom_complet', ''), session.get('role', ''))
        )
        conn.commit()
        log_action(conn, 'modification', 'transport_absences', eleve_id,
                   f"Présence transport ({creneau_label}) confirmée pour {eleve['prenom']} {eleve['nom']} le {aujourdhui}.")
    else:
        # a_renseigner → retour à l'état par défaut, rien à insérer.
        conn.commit()
        log_action(conn, 'modification', 'transport_absences', eleve_id,
                   f"Statut transport ({creneau_label}) de {eleve['prenom']} {eleve['nom']} remis à « à renseigner » le {aujourdhui}.")

    conn.close()
    return jsonify({'statut': statut_demande, 'absent': statut_demande == 'absent', 'eleve_id': eleve_id, 'creneau': creneau})


@app.route('/transport/absences/historique/<int:chauffeur_id>')
@login_required
@role_required('admin', 'accompagnatrice')
def transport_absences_historique(chauffeur_id):
    """🆕 Historique des absences transport du trajet, avec filtrage par élève et par
    période, et possibilité d'annuler n'importe quelle absence passée."""
    conn = get_db()
    if not _chauffeur_autorise_pour_absence(conn, chauffeur_id):
        conn.close()
        flash("Vous n'avez pas accès à cet historique.", 'error')
        return redirect(url_for('espace_chauffeur') if session['role'] == 'accompagnatrice'
                         else url_for('personnel_hors_prof'))

    chauffeur = conn.execute(
        "SELECT id, nom, prenom FROM personnel_hors_prof WHERE id=?", (chauffeur_id,)
    ).fetchone()
    if not chauffeur:
        conn.close()
        flash("Ce chauffeur n'existe pas ou a été supprimé.", 'error')
        return redirect(url_for('espace_chauffeur') if session['role'] == 'accompagnatrice'
                         else url_for('personnel_hors_prof'))

    eleve_filtre = (request.args.get('eleve_id') or '').strip()
    date_debut = (request.args.get('date_debut') or '').strip()
    date_fin = (request.args.get('date_fin') or '').strip()
    personnel_id = request.args.get('personnel_id', '').strip()

    # 🆕 Historique "toujours complet" : par défaut (aucun filtre de période), on affiche
    # uniquement AUJOURD'HUI, avec TOUS les élèves du trajet — pas seulement ceux pour qui
    # une absence a été enregistrée. On borne aussi l'intervalle à 31 jours max (au cas où
    # une période très large serait demandée) pour garder une page lisible et rapide.
    aujourdhui_iso = datetime.date.today().isoformat()
    if not date_debut and not date_fin:
        date_debut = date_fin = aujourdhui_iso
    elif not date_debut:
        date_debut = date_fin
    elif not date_fin:
        date_fin = date_debut

    try:
        d_debut = datetime.date.fromisoformat(date_debut)
        d_fin = datetime.date.fromisoformat(date_fin)
    except ValueError:
        d_debut = d_fin = datetime.date.today()
    if d_debut > d_fin:
        d_debut, d_fin = d_fin, d_debut
    if (d_fin - d_debut).days > 30:
        d_debut = d_fin - datetime.timedelta(days=30)
    date_debut, date_fin = d_debut.isoformat(), d_fin.isoformat()

    # Liste des élèves du trajet (roster complet), pour peupler le filtre déroulant ET
    # garantir qu'un élève sans aucun pointage apparaît quand même, en "à renseigner".
    eleves_trajet = conn.execute("""
                                 SELECT e.id, e.prenom, e.nom
                                 FROM transport_eleves t JOIN eleves e ON t.eleve_id = e.id
                                 WHERE t.chauffeur_id = ?
                                   AND COALESCE(e.statut_sortie, '') <> 'sortant_annee'
                                 ORDER BY e.nom, e.prenom
                                 """, (chauffeur_id,)).fetchall()
    eleves_affiches = [e for e in eleves_trajet if not eleve_filtre or str(e['id']) == eleve_filtre]

    # Tous les pointages (absences + présences confirmées) de la période, pour ce trajet.
    pointages = {}  # (eleve_id, date, creneau) -> dict(statut, heure, par_nom, par_role)
    absences_periode = conn.execute("""
                                     SELECT eleve_id, date_absence AS jour, creneau, date_creation,
                                            signale_par_nom, signale_par_role
                                     FROM transport_absences
                                     WHERE chauffeur_id = ? AND date_absence BETWEEN ? AND ?
                                     """, (chauffeur_id, date_debut, date_fin)).fetchall()
    for p in absences_periode:
        pointages[(p['eleve_id'], p['jour'], p['creneau'])] = {
            'statut': 'absent', 'heure': p['date_creation'],
            'par_nom': p['signale_par_nom'], 'par_role': p['signale_par_role'],
        }
    presences_periode = conn.execute("""
                                      SELECT eleve_id, date_jour AS jour, creneau, date_creation,
                                             confirme_par_nom, confirme_par_role
                                      FROM transport_presences_confirmees
                                      WHERE chauffeur_id = ? AND date_jour BETWEEN ? AND ?
                                      """, (chauffeur_id, date_debut, date_fin)).fetchall()
    for p in presences_periode:
        pointages[(p['eleve_id'], p['jour'], p['creneau'])] = {
            'statut': 'present', 'heure': p['date_creation'],
            'par_nom': p['confirme_par_nom'], 'par_role': p['confirme_par_role'],
        }

    # Une date par jour de la période, du plus récent au plus ancien.
    nb_jours = (d_fin - d_debut).days + 1
    dates_periode = [(d_fin - datetime.timedelta(days=i)).isoformat() for i in range(nb_jours)]

    lignes = []
    for jour in dates_periode:
        for e in eleves_affiches:
            info_matin = pointages.get((e['id'], jour, 'matinee'))
            info_soir = pointages.get((e['id'], jour, 'soiree'))
            lignes.append({
                'eleve_id': e['id'], 'prenom': e['prenom'], 'nom': e['nom'], 'jour': jour,
                'matin': info_matin, 'soir': info_soir,
                'heure_matin': info_matin['heure'] if info_matin and info_matin.get('heure') else None,
                'heure_soir': info_soir['heure'] if info_soir and info_soir.get('heure') else None,
            })

    conn.close()
    return render_template_string(
        TRANSPORT_ABSENCES_HISTORIQUE_HTML,
        chauffeur=chauffeur,
        lignes=lignes,
        eleves_trajet=eleves_trajet,
        eleve_filtre=eleve_filtre,
        date_debut=date_debut,
        date_fin=date_fin,
        aujourdhui=aujourdhui_iso,
        personnel_id=personnel_id,
        notif_count=get_notif_count() if session['role'] == 'admin' else 0,
    )


@app.route('/transport/absences/<int:absence_id>/annuler', methods=['POST'])
@login_required
@role_required('admin', 'accompagnatrice')
def transport_absence_annuler(absence_id):
    """🆕 Annule (supprime) une absence transport passée, depuis l'historique."""
    conn = get_db()
    absence = conn.execute("SELECT * FROM transport_absences WHERE id=?", (absence_id,)).fetchone()
    if not absence:
        conn.close()
        flash("Cette absence n'existe plus.", 'error')
        return redirect(url_for('personnel_hors_prof') if session['role'] == 'admin' else url_for('espace_chauffeur'))

    chauffeur_id = absence['chauffeur_id']
    if not _chauffeur_autorise_pour_absence(conn, chauffeur_id):
        conn.close()
        flash("Vous n'avez pas accès à cette absence.", 'error')
        return redirect(url_for('personnel_hors_prof') if session['role'] == 'admin' else url_for('espace_chauffeur'))

    eleve = conn.execute("SELECT prenom, nom FROM eleves WHERE id=?", (absence['eleve_id'],)).fetchone()
    conn.execute("DELETE FROM transport_absences WHERE id=?", (absence_id,))
    conn.commit()
    log_action(conn, 'suppression', 'transport_absences', absence['eleve_id'],
               f"Absence transport annulée pour {eleve['prenom'] if eleve else '—'} "
               f"{eleve['nom'] if eleve else ''} du {absence['date_absence']}.")
    conn.close()
    flash('Absence annulée avec succès.', 'success')

    personnel_id = request.form.get('personnel_id', '').strip()
    return redirect(url_for('transport_absences_historique', chauffeur_id=chauffeur_id,
                             personnel_id=personnel_id) if personnel_id
                     else url_for('transport_absences_historique', chauffeur_id=chauffeur_id))


