@app.route('/personnel-hors-prof/<int:personnel_id>/acces-chauffeur', methods=['POST'])
@login_required
@role_required('admin')
def personnel_acces_chauffeur(personnel_id):
    """Crée ou met à jour l'email/mot de passe permettant à un chauffeur de se connecter à l'app."""
    conn = get_db()
    p = conn.execute("SELECT * FROM personnel_hors_prof WHERE id=?", (personnel_id,)).fetchone()
    if not p or p['mission'] not in ('Chauffeur', 'Accompagnatrice'):
        flash("Cette fiche n'est pas un chauffeur ou une accompagnatrice.", 'error')
        conn.close()
        return redirect(url_for('personnel_hors_prof'))

    email = request.form.get('email', '').strip().lower()
    new_password = request.form.get('new_password', '')

    if not email:
        flash("L'email est obligatoire pour créer un accès à l'application.", 'error')
        conn.close()
        return redirect(url_for('personnel_hors_prof_detail', personnel_id=personnel_id))

    email_deja_pris = conn.execute(
        "SELECT id FROM personnel_hors_prof WHERE email=? AND id!=?", (email, personnel_id)
    ).fetchone() or conn.execute("SELECT id FROM users WHERE email=?", (email,)).fetchone()
    if email_deja_pris:
        flash("Cet email est déjà utilisé par un autre compte.", 'error')
        conn.close()
        return redirect(url_for('personnel_hors_prof_detail', personnel_id=personnel_id))

    if new_password:
        conn.execute("UPDATE personnel_hors_prof SET email=?, password=? WHERE id=?",
                     (email, hash_pw(new_password), personnel_id))
        flash('Accès créé/réinitialisé avec succès. Communiquez-lui son email et son mot de passe.', 'success')
    else:
        conn.execute("UPDATE personnel_hors_prof SET email=? WHERE id=?", (email, personnel_id))
        flash("Email de l'accès mis à jour.", 'success')

    conn.commit()
    log_action(conn, 'modification', 'personnel_hors_prof', personnel_id, "Mise à jour de l'accès à l'app (connexion)")
    conn.close()
    return redirect(url_for('personnel_hors_prof_detail', personnel_id=personnel_id))


