@app.route('/espace-chauffeur')
@login_required
@role_required('chauffeur', 'accompagnatrice')
def espace_chauffeur():
    conn = get_db()
    chauffeur = conn.execute("SELECT * FROM personnel_hors_prof WHERE id=?", (session['user_id'],)).fetchone()
    if not chauffeur or chauffeur['mission'] not in ('Chauffeur', 'Accompagnatrice'):
        conn.close()
        session.clear()
        flash("Cet accès n'est plus valide.", 'error')
        return redirect(url_for('login'))

    # 🆕 Créneau en cours (matinée avant midi / soirée après midi) : sert à adapter les
    # libellés du menu déroulant de statut transport affiché à l'accompagnatrice sur sa
    # page "carte" — le matin on garde "Présent/Absent", l'après-midi on affiche plutôt
    # "Monté au bus / Pas présent au bus" (même valeurs stockées en base, juste le texte
    # affiché qui change selon l'heure).
    creneau_actuel = _creneau_transport_actuel()

    # 🆕 Une accompagnatrice n'a pas d'élèves assignés directement (l'assignation reste
    # rattachée au chauffeur) : elle affiche donc la liste et l'itinéraire du chauffeur
    # auquel elle est liée, tout en gardant son propre partage de position / historique.
    absents_transport_ids = set()
    presents_confirmes_ids = set()  # 🆕 élèves confirmés "Présent" (explicitement) aujourd'hui
    chauffeur_lie_id = None
    if chauffeur['mission'] == 'Accompagnatrice':
        chauffeur_lie_id = chauffeur['accompagnatrice_chauffeur_id']
        if chauffeur_lie_id:
            donnees = construire_donnees_trajet_chauffeur(chauffeur_lie_id, conn)
            creneau_actuel = _creneau_transport_actuel()
            # 🆕 Élèves déjà marqués absents du transport aujourd'hui, pour pré-cocher les
            # boutons "Absent" dans son espace personnel. Filtré sur le créneau en cours
            # (matinée/soirée) : à midi, le trajet du soir repart de "à renseigner" pour
            # tout le monde, même si quelqu'un a été marqué absent le matin.
            absents_transport_ids = {
                r['eleve_id'] for r in conn.execute(
                    "SELECT eleve_id FROM transport_absences WHERE chauffeur_id=? AND date_absence=? AND creneau=?",
                    (chauffeur_lie_id, datetime.date.today().isoformat(), creneau_actuel)
                ).fetchall()
            }
            # 🆕 Élèves déjà confirmés "Présent" pour le créneau en cours (statut par défaut
            # = "à renseigner" tant que l'accompagnatrice n'a pas choisi Présent ou Absent).
            presents_confirmes_ids = {
                r['eleve_id'] for r in conn.execute(
                    "SELECT eleve_id FROM transport_presences_confirmees WHERE chauffeur_id=? AND date_jour=? AND creneau=?",
                    (chauffeur_lie_id, datetime.date.today().isoformat(), creneau_actuel)
                ).fetchall()
            }
        else:
            donnees = {
                'eleves_assignes': [], 'eleves_carte': [],
                'ecole': get_ecole_coords(conn), 'ecole_localisee': False,
                'distance_totale_trajet': None,
            }
            flash("Aucun chauffeur ne vous est encore lié. Contactez l'administration pour voir la liste des élèves.", 'error')
    else:
        donnees = construire_donnees_trajet_chauffeur(session['user_id'], conn)

    conn.close()

    # 🆕 Liste affichée dans la carte "Ordre de ramassage", triée selon le numéro de
    # classement fixé par l'admin (1 en premier), et non selon l'ordre GPS (qui reste
    # utilisé tel quel pour le tracé de l'itinéraire sur la carte).
    eleves_carte_affichage = sorted(
        donnees['eleves_carte'],
        key=lambda e: (e['ordre'] is None, e['ordre'] if e['ordre'] is not None else 0)
    )

    return render_template_string(
        ESPACE_CHAUFFEUR_HTML,
        chauffeur=dict(chauffeur),
        notif_count=0,
        eleves_carte_affichage=eleves_carte_affichage,
        absents_transport_ids=absents_transport_ids,
        presents_confirmes_ids=presents_confirmes_ids,
        chauffeur_lie_id=chauffeur_lie_id,
        creneau_actuel=creneau_actuel,
        **donnees
    )


@app.route('/api/chauffeur/position', methods=['POST'])
@login_required
@role_required('chauffeur', 'accompagnatrice')
def api_chauffeur_position():
    """Reçoit la position GPS envoyée régulièrement par le téléphone du chauffeur (JS geolocation)."""
    data = request.get_json(silent=True) or {}
    lat, lon = data.get('lat'), data.get('lon')
    if lat is None or lon is None:
        return jsonify({'erreur': 'Coordonnées manquantes.'}), 400
    try:
        lat, lon = float(lat), float(lon)
    except (TypeError, ValueError):
        return jsonify({'erreur': 'Coordonnées invalides.'}), 400

    conn = get_db()
    try:
        conn.execute(
            "UPDATE personnel_hors_prof SET position_lat=?, position_lon=?, position_maj_le=CURRENT_TIMESTAMP WHERE id=?",
            (lat, lon, session['user_id'])
        )

        # 🆕 Si un trajet (aller/retour) est en cours pour ce chauffeur, on accumule la distance
        # réellement parcourue depuis la dernière position connue.
        # 🩹 CORRECTIF (2026-09) : l'ancien garde-fou rejetait tout "saut" de plus de 2 km
        # entre deux envois consécutifs, quel que soit le temps écoulé entre les deux. Or,
        # sur mobile, le navigateur suspend souvent l'envoi de position quand l'écran se
        # verrouille ou que l'app passe en arrière-plan (économie de batterie) : plusieurs
        # minutes peuvent s'écouler entre deux points reçus, pendant lesquelles la personne a
        # réellement parcouru plusieurs kilomètres. Avec l'ancien seuil fixe, ce déplacement
        # réel était intégralement ignoré (pas seulement écrêté) — d'où des trajets réels de
        # plusieurs km ramenés à quelques centaines de mètres de kilométrage calculé.
        # On valide désormais le saut à partir de la VITESSE IMPLIQUÉE (distance / temps
        # écoulé depuis le dernier point reçu), et on ne rejette que les sauts qui
        # impliqueraient une vitesse déraisonnable (> 120 km/h), signe d'un vrai problème de
        # précision GPS plutôt que d'un déplacement réel.
        VITESSE_MAX_PLAUSIBLE_KMH = 120
        trajet = conn.execute(
            "SELECT id, distance_km, dernier_lat, dernier_lon, derniere_position_le "
            "FROM chauffeur_trajets WHERE chauffeur_id=? AND actif=1 ORDER BY id DESC LIMIT 1",
            (session['user_id'],)
        ).fetchone()
        if trajet:
            nouvelle_distance = trajet['distance_km']
            if trajet['dernier_lat'] is not None and trajet['dernier_lon'] is not None:
                saut = distance_km(trajet['dernier_lat'], trajet['dernier_lon'], lat, lon)
                saut_plausible = True
                dernier_ts = parser_datetime_sqlite(trajet['derniere_position_le'])
                if dernier_ts:
                    secondes_ecoulees = (datetime.datetime.now() - dernier_ts).total_seconds()
                    if secondes_ecoulees > 0:
                        vitesse_kmh = saut / (secondes_ecoulees / 3600)
                        saut_plausible = vitesse_kmh <= VITESSE_MAX_PLAUSIBLE_KMH
                    # si secondes_ecoulees <= 0 (horloge/serveur), on garde saut_plausible=True
                elif saut > 2.0:
                    # Pas d'horodatage précédent connu (trajet démarré avant cette mise à jour,
                    # ou première position) : on retombe sur l'ancien garde-fou simple par
                    # prudence, le temps qu'un `derniere_position_le` existe pour ce trajet.
                    saut_plausible = False
                if saut_plausible:
                    nouvelle_distance += saut
            # 🩹 CORRECTIF (2026-09) : on n'écrit plus `fin_le` ici — cette colonne doit
            # rester NULL tant que le trajet est réellement actif. On horodate désormais le
            # dernier point GPS dans `derniere_position_le`, pour ne plus faire apparaître le
            # trajet comme "Terminé" côté admin (fiche personnel + timeline du jour) alors
            # que l'accompagnatrice/le chauffeur roule toujours (actif=1).
            conn.execute(
                "UPDATE chauffeur_trajets SET distance_km=?, dernier_lat=?, dernier_lon=?, derniere_position_le=CURRENT_TIMESTAMP WHERE id=?",
                (round(nouvelle_distance, 3), lat, lon, trajet['id'])
            )
            # 🆕 On enregistre également ce point dans l'historique GPS du trajet (déjà limité à
            # 1 envoi/15s côté téléphone du chauffeur, donc pas de risque de saturer la base), afin
            # de pouvoir retracer le chemin exact parcouru sur la carte de suivi admin.
            conn.execute(
                "INSERT INTO transport_positions_trajet (trajet_id, lat, lon) VALUES (?,?,?)",
                (trajet['id'], lat, lon)
            )

        # 🔧 CORRECTIF "database is locked" (2026-09) : commit avec retry automatique
        # (voir db_commit_avec_retry plus haut dans le fichier) au lieu d'un conn.commit()
        # simple, pour absorber un verrou passager sans faire planter la requête.
        db_commit_avec_retry(conn)
    except sqlite3.OperationalError as e:
        conn.rollback()
        if 'locked' in str(e).lower():
            # Réponse douce (503) plutôt qu'un 500 : le téléphone du chauffeur réessaiera
            # tout seul au prochain envoi de position (quelques secondes après).
            return jsonify({'erreur': 'Base de données momentanément occupée, réessai automatique.'}), 503
        raise
    finally:
        conn.close()
    return jsonify({'ok': True})


@app.route('/api/chauffeur/trajet-debut', methods=['POST'])
@login_required
@role_required('chauffeur', 'accompagnatrice')
def api_chauffeur_trajet_debut():
    """Démarre le suivi d'un trajet (aller ou retour) pour le chauffeur connecté, déclenché
    quand il active le partage de position. S'il avait laissé un trajet actif (ex : partage
    coupé sans repasser par le bouton), on le clôture d'abord proprement."""
    data = request.get_json(silent=True) or {}
    type_trajet = data.get('type_trajet') if data.get('type_trajet') in ('aller', 'retour') else 'aller'

    conn = get_db()
    conn.execute(
        "UPDATE chauffeur_trajets SET actif=0, fin_le=CURRENT_TIMESTAMP WHERE chauffeur_id=? AND actif=1",
        (session['user_id'],)
    )
    chauffeur = conn.execute(
        "SELECT position_lat, position_lon FROM personnel_hors_prof WHERE id=?", (session['user_id'],)
    ).fetchone()
    cur = conn.execute(
        "INSERT INTO chauffeur_trajets (chauffeur_id, type_trajet, date_trajet, distance_km, dernier_lat, dernier_lon, actif) "
        "VALUES (?, ?, date('now'), 0, ?, ?, 1)",
        (session['user_id'], type_trajet,
         chauffeur['position_lat'] if chauffeur else None,
         chauffeur['position_lon'] if chauffeur else None)
    )
    conn.commit()
    trajet_id = cur.lastrowid
    conn.close()
    return jsonify({'ok': True, 'trajet_id': trajet_id})


@app.route('/api/chauffeur/trajet-fin', methods=['POST'])
@login_required
@role_required('chauffeur', 'accompagnatrice')
def api_chauffeur_trajet_fin():
    """Clôture le trajet en cours du chauffeur connecté (partage de position désactivé)."""
    conn = get_db()
    conn.execute(
        "UPDATE chauffeur_trajets SET actif=0, fin_le=CURRENT_TIMESTAMP WHERE chauffeur_id=? AND actif=1",
        (session['user_id'],)
    )
    conn.commit()
    conn.close()
    return jsonify({'ok': True})


@app.route('/api/admin/historique-trajets')
@login_required
@role_required('admin')
def api_admin_historique_trajets():
    """Historique des trajets chauffeurs pour l'admin, filtrable par chauffeur, par jour et
    par sens de trajet (aller/retour). Utilisé par le panneau 'Historique trajet' de la page
    de suivi des chauffeurs."""
    chauffeur_id = request.args.get('chauffeur_id', type=int)
    date_filtre = request.args.get('date', '').strip()
    # 🆕 Le filtre "sens" (aller/retour) correspond désormais à la période de la journée
    # (matin = avant midi = "aller", soir = à partir de midi = "retour", voir plus bas) et
    # non plus au choix manuel fait par le chauffeur/l'accompagnatrice au démarrage : le
    # filtrage se fait donc en Python une fois cette période recalculée, pas en SQL.
    type_filtre = request.args.get('type_trajet', '').strip()

    sql = """
        SELECT t.id, t.chauffeur_id, t.type_trajet, t.date_trajet, t.distance_km,
               t.actif, t.debut_le, t.fin_le, t.derniere_position_le,
               p.nom AS chauffeur_nom, p.prenom AS chauffeur_prenom
        FROM chauffeur_trajets t
        JOIN personnel_hors_prof p ON p.id = t.chauffeur_id
        WHERE 1=1
    """
    params = []
    if chauffeur_id:
        sql += " AND t.chauffeur_id=?"
        params.append(chauffeur_id)
    if date_filtre:
        sql += " AND t.date_trajet=?"
        params.append(date_filtre)
    sql += " ORDER BY t.date_trajet DESC, t.debut_le DESC LIMIT 300"

    conn = get_db()
    rows = conn.execute(sql, params).fetchall()
    conn.close()

    # 🩹 CORRECTIF (2026-09) : un trajet peut rester `actif=1` (bouton "Début de travail"
    # pressé côté téléphone) sans qu'AUCUNE position GPS n'ait jamais été reçue derrière
    # (permission refusée sans que l'app le détecte, GPS indisponible en intérieur, page
    # fermée juste après le clic...). Pour que l'admin repère tout de suite ce cas — plutôt
    # que de découvrir "0 km parcourus, rien sur la carte" sans comprendre pourquoi — on
    # calcule ici si la dernière position reçue est récente (< 3 min), et on distingue :
    #   - "en_cours_actif"  : trajet actif ET position récente  -> 🟢 En cours
    #   - "en_cours_fige"   : trajet actif MAIS aucune position récente -> 🟠 En cours (GPS ?)
    #   - "termine"         : trajet clôturé -> Terminé
    maintenant = datetime.datetime.now()
    trajets = []
    for r in rows:
        position_recente = False
        derniere_ts = parser_datetime_sqlite(r['derniere_position_le'])
        if derniere_ts:
            position_recente = (maintenant - derniere_ts).total_seconds() < 180
        if r['actif']:
            statut = 'en_cours_actif' if position_recente else 'en_cours_fige'
        else:
            statut = 'termine'

        # 🆕 Sens du trajet déduit de l'heure de DÉBUT réelle (et non plus du sens choisi
        # manuellement côté téléphone au démarrage) : tout trajet démarré avant midi est
        # affiché comme "Aller" (le matin), tout trajet démarré à partir de midi comme
        # "Retour" (l'après-midi/soir). Sert aussi à répartir les trajets entre les deux
        # onglets "Matin" / "Soir" du panneau historique.
        debut_ts = parser_datetime_sqlite(r['debut_le'])
        if debut_ts and debut_ts.hour >= 12:
            periode = 'soir'
            type_trajet_affiche = 'retour'
        else:
            periode = 'matin'
            type_trajet_affiche = 'aller'

        if type_filtre in ('aller', 'retour') and type_filtre != type_trajet_affiche:
            continue

        trajets.append({
            'id': r['id'],
            'chauffeur_id': r['chauffeur_id'],
            'chauffeur_nom': f"{r['chauffeur_prenom']} {r['chauffeur_nom']}",
            'type_trajet': type_trajet_affiche,
            'periode': periode,
            'date_trajet': r['date_trajet'],
            'distance_km': round(r['distance_km'] or 0, 2),
            'actif': bool(r['actif']),
            'debut_le': r['debut_le'],
            'fin_le': r['fin_le'],
            'derniere_position_le': r['derniere_position_le'],
            'statut': statut,
        })
    return jsonify({'trajets': trajets})


@app.route('/api/admin/trajet-trace/<int:trajet_id>')
@login_required
@role_required('admin')
def api_admin_trajet_trace(trajet_id):
    """🆕 Renvoie la trace GPS (liste de points [lat, lon]) d'un trajet donné, pour l'afficher
    sur la carte de /suivi-chauffeurs. Si le trajet a déjà été archivé (nuit précédente,
    voir tache_archiver_historique_trajets_24h), on lit directement la trace compactée
    (trace_json) ; sinon (trajet du jour, pas encore archivé) on reconstitue le tracé en
    direct à partir des points bruts déjà reçus."""
    conn = get_db()
    trajet = conn.execute("""
        SELECT t.id, t.type_trajet, t.date_trajet, t.distance_km, t.trace_json, t.debut_le,
               p.nom AS chauffeur_nom, p.prenom AS chauffeur_prenom
        FROM chauffeur_trajets t
        JOIN personnel_hors_prof p ON p.id = t.chauffeur_id
        WHERE t.id=?
    """, (trajet_id,)).fetchone()
    if not trajet:
        conn.close()
        return jsonify({'erreur': 'Trajet introuvable.'}), 404

    if trajet['trace_json'] is not None:
        points = json.loads(trajet['trace_json'])
    else:
        rows = conn.execute(
            "SELECT lat, lon FROM transport_positions_trajet WHERE trajet_id=? ORDER BY horodatage ASC",
            (trajet_id,)
        ).fetchall()
        points = [[r['lat'], r['lon']] for r in rows]
    conn.close()

    # 🆕 Même règle que dans /api/admin/historique-trajets : le sens affiché suit l'heure
    # de début (avant midi -> Aller, à partir de midi -> Retour), pour rester cohérent avec
    # le tableau depuis lequel cette trace est ouverte.
    debut_ts = parser_datetime_sqlite(trajet['debut_le'])
    type_trajet_affiche = 'retour' if (debut_ts and debut_ts.hour >= 12) else 'aller'

    return jsonify({
        'trajet_id': trajet['id'],
        'chauffeur_nom': f"{trajet['chauffeur_prenom']} {trajet['chauffeur_nom']}",
        'type_trajet': type_trajet_affiche,
        'date_trajet': trajet['date_trajet'],
        'distance_km': round(trajet['distance_km'] or 0, 2),
        'points': points,
    })


@app.route('/api/admin/chauffeurs-position')
@login_required
@role_required('admin')
def api_admin_chauffeurs_position():
    """Renvoie la dernière position connue de chaque chauffeur, pour la carte de suivi en direct,
    ainsi que les élèves qui lui sont assignés (avec leur emplacement) et une détection en direct
    de l'arrivée du chauffeur chez chaque élève (distance chauffeur ↔ élève < ARRIVEE_ELEVE_SEUIL_KM)."""
    conn = get_db()
    rows = conn.execute("""
                         SELECT id, mission, nom, prenom, email, position_lat, position_lon, position_maj_le,
                                statut_chauffeur, vehicule_immatriculation, vehicule_modele,
                                vehicule_capacite, permis_expiration, photo, accompagnatrice_chauffeur_id
                         FROM personnel_hors_prof
                         WHERE mission IN ('Chauffeur', 'Accompagnatrice')
                         ORDER BY nom, prenom
                         """).fetchall()
    ecole = get_ecole_coords(conn)

    maintenant = datetime.datetime.now()
    aujourdhui_str = maintenant.date().isoformat()
    permis_alerte_str = (maintenant.date() + datetime.timedelta(days=30)).isoformat()
    chauffeurs = []
    evenements_jour = []  # 🆕 timeline du jour, construite à partir de données réelles (chauffeur_trajets)

    for r in rows:
        en_ligne = False
        if r['position_maj_le']:
            try:
                maj = datetime.datetime.strptime(r['position_maj_le'], '%Y-%m-%d %H:%M:%S.%f')
            except ValueError:
                try:
                    maj = datetime.datetime.strptime(r['position_maj_le'], '%Y-%m-%d %H:%M:%S')
                except ValueError:
                    maj = None
            if maj:
                en_ligne = (maintenant - maj).total_seconds() < 180  # "en ligne" si maj il y a < 3 min

        # 🆕 Élèves assignés, avec leur emplacement, pour les afficher sur la carte de suivi
        # admin, et détecter en direct l'arrivée chez l'un d'eux. Pour une accompagnatrice,
        # on affiche les élèves du chauffeur auquel elle est liée (même trajet que lui).
        id_pour_eleves = r['accompagnatrice_chauffeur_id'] if r['mission'] == 'Accompagnatrice' else r['id']
        donnees_trajet = construire_donnees_trajet_chauffeur(id_pour_eleves, conn) if id_pour_eleves else {'eleves_carte': []}
        eleves_suivi = []
        nb_eleves_a_bord = 0
        for e in donnees_trajet['eleves_carte']:
            arrive = False
            distance_actuelle_km = None
            if r['position_lat'] is not None and r['position_lon'] is not None:
                distance_actuelle_km = round(
                    distance_km(r['position_lat'], r['position_lon'], e['lat'], e['lon']), 3)
                arrive = distance_actuelle_km <= ARRIVEE_ELEVE_SEUIL_KM
                if arrive:
                    nb_eleves_a_bord += 1
            eleves_suivi.append({
                'id': e['id'],
                'nom': e['nom'],
                'adresse': e['adresse'],
                'lat': e['lat'],
                'lon': e['lon'],
                'arrive': arrive,
                'distance_actuelle_km': distance_actuelle_km,
            })

        # 🆕 Distance parcourue aujourd'hui par ce chauffeur (somme de ses trajets aller/retour du jour).
        distance_jour = conn.execute(
            "SELECT COALESCE(SUM(distance_km), 0) AS total FROM chauffeur_trajets "
            "WHERE chauffeur_id=? AND date_trajet=date('now')",
            (r['id'],)
        ).fetchone()['total']

        # 🆕 Trajet en cours (aller/retour), s'il y en a un actif — pour le panneau détail
        trajet_actif = conn.execute(
            "SELECT type_trajet, debut_le FROM chauffeur_trajets WHERE chauffeur_id=? AND actif=1 "
            "ORDER BY id DESC LIMIT 1", (r['id'],)
        ).fetchone()

        # 🆕 Alerte permis, calculée uniquement si une date d'expiration a été saisie (donnée réelle)
        alerte_permis = None
        if r['permis_expiration']:
            if r['permis_expiration'] < aujourdhui_str:
                alerte_permis = 'expire'
            elif r['permis_expiration'] <= permis_alerte_str:
                alerte_permis = 'bientot'

        # 🆕 Statut visuel de supervision, dérivé uniquement de faits réels et vérifiables :
        # compte suspendu/indisponible (saisie admin), permis expiré, hors ligne, ou normal.
        if r['statut_chauffeur'] == 'Suspendu':
            statut_visuel = 'suspendu'
        elif alerte_permis == 'expire':
            statut_visuel = 'alerte'
        elif r['statut_chauffeur'] == 'Indisponible':
            statut_visuel = 'indisponible'
        elif not en_ligne:
            statut_visuel = 'hors_ligne'
        else:
            statut_visuel = 'normal'

        chauffeurs.append({
            'id': r['id'],
            'mission': r['mission'],
            'nom': f"{r['prenom']} {r['nom']}" + (' (accompagnatrice)' if r['mission'] == 'Accompagnatrice' else ''),
            'lat': r['position_lat'],
            'lon': r['position_lon'],
            'maj_le': r['position_maj_le'],
            'en_ligne': en_ligne,
            'compte_actif': bool(r['email']),
            'eleves': eleves_suivi,
            'nb_eleves_a_bord': nb_eleves_a_bord,
            'distance_jour_km': round(distance_jour, 2),
            'statut_chauffeur': r['statut_chauffeur'] or 'Actif',
            'statut_visuel': statut_visuel,
            'vehicule_immatriculation': r['vehicule_immatriculation'],
            'vehicule_modele': r['vehicule_modele'],
            'vehicule_capacite': r['vehicule_capacite'],
            'alerte_permis': alerte_permis,
            'permis_expiration': r['permis_expiration'],
            'photo': r['photo'],
            'trajet_en_cours': dict(trajet_actif) if trajet_actif else None,
        })

        # Événements de la timeline du jour, à partir des trajets réellement démarrés/terminés
        trajets_du_jour = conn.execute(
            "SELECT type_trajet, debut_le, fin_le FROM chauffeur_trajets "
            "WHERE chauffeur_id=? AND date_trajet=date('now') ORDER BY id",
            (r['id'],)
        ).fetchall()
        nom_chauffeur = f"{r['prenom']} {r['nom']}"
        for t in trajets_du_jour:
            libelle_sens = 'aller' if t['type_trajet'] == 'aller' else 'retour'
            if t['debut_le']:
                evenements_jour.append({
                    'heure': t['debut_le'][-8:] if len(t['debut_le']) >= 8 else t['debut_le'],
                    'horodatage': t['debut_le'],
                    'texte': f"{nom_chauffeur} a démarré le trajet {libelle_sens}"
                              + (f" ({r['vehicule_immatriculation']})" if r['vehicule_immatriculation'] else ''),
                })
            if t['fin_le']:
                evenements_jour.append({
                    'heure': t['fin_le'][-8:] if len(t['fin_le']) >= 8 else t['fin_le'],
                    'horodatage': t['fin_le'],
                    'texte': f"{nom_chauffeur} a terminé le trajet {libelle_sens}",
                })

    evenements_jour.sort(key=lambda ev: ev['horodatage'] or '', reverse=True)

    # 🆕 Distance totale (tous chauffeurs confondus) effectuée aujourd'hui — affichée dans
    # le carré récapitulatif en haut de la page de suivi.
    distance_totale_jour = conn.execute(
        "SELECT COALESCE(SUM(distance_km), 0) AS total FROM chauffeur_trajets WHERE date_trajet=date('now')"
    ).fetchone()['total']

    conn.close()
    return jsonify({
        'chauffeurs': chauffeurs,
        'ecole': dict(ecole) if ecole else None,
        'distance_totale_jour_km': round(distance_totale_jour, 2),
        'evenements_jour': evenements_jour[:20],
    })


@app.route('/suivi-chauffeurs')
@login_required
@role_required('admin')
def suivi_chauffeurs():
    """Dashboard de suivi en temps réel : localisation de tous les chauffeurs, statistiques
    globales du transport scolaire (élèves abonnés, distances, revenu), vue admin uniquement."""
    conn = get_db()
    chauffeurs = conn.execute(
        "SELECT * FROM personnel_hors_prof WHERE mission IN ('Chauffeur', 'Accompagnatrice') ORDER BY nom, prenom"
    ).fetchall()
    ecole = get_ecole_coords(conn)

    # 🆕 Indicateurs du tableau de bord ────────────────────────────────
    nb_eleves_abonnes = conn.execute(
        "SELECT COUNT(*) FROM eleves WHERE transport_abonne='oui'"
    ).fetchone()[0]
    nb_eleves_assignes = conn.execute(
        "SELECT COUNT(DISTINCT eleve_id) FROM transport_eleves"
    ).fetchone()[0]
    # 🩹 CORRECTIF : on calcule le revenu transport à partir des factures réellement
    # générées (table `paiements`, colonne `montant_transport`) pour le mois en cours,
    # exactement comme sur la page de paiement — et non plus à partir du tarif de base
    # (`eleves.montant_transport`), qui ignore les réductions transport et ne correspond
    # donc pas au montant réellement facturé/affiché sur la page de paiement.
    revenu_transport_mensuel = conn.execute(
        "SELECT COALESCE(SUM(montant_transport),0) FROM paiements "
        "WHERE substr(date_echeance,1,7)=strftime('%Y-%m','now')"
    ).fetchone()[0]
    distance_totale_jour = conn.execute(
        "SELECT COALESCE(SUM(distance_km),0) FROM chauffeur_trajets WHERE date_trajet=date('now')"
    ).fetchone()[0]

    # Distance totale estimée (somme des trajets complets École ↔ élèves, tous chauffeurs)
    # et nombre de chauffeurs actuellement en ligne (position reçue il y a moins de 3 min).
    distance_totale_estimee = 0.0
    nb_chauffeurs_en_ligne = 0
    maintenant = datetime.datetime.now()
    for c in chauffeurs:
        # 🆕 On ne compte la distance estimée que pour les chauffeurs (celle d'une accompagnatrice
        # correspond au même trajet que son chauffeur lié, déjà compté une fois).
        if c['mission'] == 'Chauffeur':
            donnees_trajet = construire_donnees_trajet_chauffeur(c['id'], conn)
            if donnees_trajet['distance_totale_trajet']:
                distance_totale_estimee += donnees_trajet['distance_totale_trajet']
        if c['position_maj_le']:
            try:
                maj = datetime.datetime.strptime(c['position_maj_le'], '%Y-%m-%d %H:%M:%S.%f')
            except ValueError:
                try:
                    maj = datetime.datetime.strptime(c['position_maj_le'], '%Y-%m-%d %H:%M:%S')
                except ValueError:
                    maj = None
            if maj and (maintenant - maj).total_seconds() < 180:
                nb_chauffeurs_en_ligne += 1

    conn.close()
    return render_template_string(
        SUIVI_CHAUFFEURS_HTML,
        chauffeurs=chauffeurs,
        ecole=ecole,
        notif_count=get_notif_count(),
        nb_eleves_abonnes=nb_eleves_abonnes,
        nb_eleves_assignes=nb_eleves_assignes,
        revenu_transport_mensuel=revenu_transport_mensuel,
        distance_totale_jour=round(distance_totale_jour, 2),
        distance_totale_estimee=round(distance_totale_estimee, 1),
        nb_chauffeurs_en_ligne=nb_chauffeurs_en_ligne,
    )


