@app.route('/whatsapp/api/enregistrer_relance', methods=['POST'])
@login_required
@role_required('admin')
def whatsapp_api_enregistrer_relance():
    """🆕 Enregistre qu'une relance de paiement vient d'être ouverte pour un parent et renvoie son
    compteur à jour. Le lot (lot_id) évite de compter plusieurs fois le même envoi."""
    data = request.get_json(silent=True) or {}
    try:
        pid = int(data.get('parent_id'))
    except (TypeError, ValueError):
        return jsonify({'erreur': 'Parent invalide.'}), 400
    lot = str(data.get('lot_id') or '')[:60] or None
    conn = get_db()
    try:
        _assurer_table_relances_wa(conn)
        if not conn.execute("SELECT 1 FROM users WHERE id = ? AND role = 'parent'", (pid,)).fetchone():
            return jsonify({'erreur': 'Parent introuvable.'}), 404
        tf = str(data.get('type_facture') or '').strip()
        if tf not in ('Scolarité', "Frais d'inscription", 'Autre'):
            tf = ''
        deja = lot and conn.execute("SELECT 1 FROM relances_whatsapp WHERE parent_id = ? AND lot_id = ?",
                                    (pid, lot)).fetchone()
        if not deja:
            conn.execute("INSERT INTO relances_whatsapp (parent_id, lot_id, langue, user_id, type_facture) VALUES (?,?,?,?,?)",
                         (pid, lot, _wa_langue(data.get('langue')), session.get('user_id'), tf or None))
            conn.commit()
        r = _relances_wa_resume(conn, pid, tf or None).get(pid, {'n': 0, 'derniere': '', 'depuis': ''})
        return jsonify({'n': r['n'], 'derniere': r['derniere'], 'depuis': r.get('depuis', '')})
    finally:
        conn.close()


@app.route('/whatsapp/api/queue_remerciement/<int:parent_id>', methods=['GET'])
@login_required
@role_required('admin')
def whatsapp_api_queue_remerciement(parent_id):
    """🙏 Prépare le message de remerciement (lien wa.me) pour un parent relancé qui a payé sous 3 jours.
    Le montant et la date sont recalculés ici à partir du journal des versements (jamais fournis par le navigateur)."""
    jour = (request.args.get('relance') or '').strip()
    if not re.fullmatch(r'\d{4}-\d{2}-\d{2}', jour):
        return jsonify({'resultats': [], 'erreur': 'Relance invalide.'}), 400
    conn = get_db()
    try:
        lignes = _relances_payees_vite(conn, parent_id=parent_id, relance_jour=jour)
    finally:
        conn.close()
    if not lignes:
        return jsonify({'resultats': [], 'erreur': 'Aucun paiement rapide trouvé pour cette relance.'}), 404
    l = lignes[0]
    if not (l['telephone'] or '').strip():
        return jsonify({'resultats': [], 'erreur': 'Numéro WhatsApp manquant pour ce parent.'}), 404
    queue = [{
        'parent_id': parent_id,
        'nom': l['nom'],
        'telephone': l['telephone'],
        'message': _wa_msg_remerciement(_wa_langue(request.args.get('lang')), l['nom'], l['enfants'],
                                        l['montant'], l['paiement_txt']),
        'libelle': f"🙏 Remerciement — {_wa_montant(l['montant'])} MAD reçus le {l['paiement_txt']} ({l['delai_txt']} la relance)",
        'relance_jour': jour,
    }]
    return jsonify({'resultats': _preparer_queue_liens(queue)})


