@app.route('/whatsapp/api/queue_message', methods=['POST'])
@login_required
@role_required('admin')
def whatsapp_api_queue_message():
    conn = get_db()
    try:
        data = request.get_json(force=True) or {}
        message_tpl = (data.get('message') or '').strip()
        parent_ids = data.get('parent_ids') or []

        if not message_tpl:
            return jsonify({'erreur': 'Le message ne peut pas être vide.'}), 400
        if not parent_ids:
            return jsonify({'erreur': 'Aucun parent sélectionné.'}), 400

        queue = []
        nb_sans_tel = 0
        for pid in parent_ids:
            info = conn.execute("""
                                SELECT u.nom, u.prenom, u.telephone,
                                       GROUP_CONCAT(DISTINCT e.prenom || ' ' || e.nom) AS enfants,
                                       GROUP_CONCAT(DISTINCT c.nom)                     AS classes_noms
                                FROM users u
                                         LEFT JOIN eleves e ON e.parent_id = u.id
                                         LEFT JOIN classes c ON e.classe_id = c.id
                                WHERE u.id = ?
                                GROUP BY u.id
                                """, (pid,)).fetchone()
            if not info or not info['telephone']:
                nb_sans_tel += 1
                continue
            msg_perso = (message_tpl
                         .replace('{parent}', f"{info['nom']} {info['prenom']}")
                         .replace('{enfant}', info['enfants'] or '')
                         .replace('{classe}', info['classes_noms'] or ''))
            queue.append({
                'nom': f"{info['nom']} {info['prenom']}",
                'telephone': info['telephone'],
                'message': msg_perso
            })
        resultats = _preparer_queue_liens(queue)
        return jsonify({'resultats': resultats, 'nb_sans_telephone': nb_sans_tel})
    finally:
        conn.close()


@app.route('/whatsapp/api/queue_fichier', methods=['POST'])
@login_required
@role_required('admin')
def whatsapp_api_queue_fichier():
    conn = get_db()
    try:
        caption = request.form.get('caption', '').strip()
        parent_ids = request.form.getlist('parent_ids')
        fichier = request.files.get('fichier')

        if not fichier or fichier.filename == '':
            return jsonify({'erreur': 'Aucun fichier sélectionné.'}), 400
        if not parent_ids:
            return jsonify({'erreur': 'Aucun parent sélectionné.'}), 400

        ext = fichier.filename.rsplit('.', 1)[-1].lower() if '.' in fichier.filename else ''
        if ext not in ALLOWED_WA_EXTENSIONS:
            return jsonify({'erreur': f"Type de fichier .{ext} non autorisé. Formats acceptés : "
                                       f"{', '.join(sorted(ALLOWED_WA_EXTENSIONS))}."}), 400

        filename_safe = secure_filename(fichier.filename)
        ts = datetime.datetime.now().strftime('%Y%m%d%H%M%S')
        save_name = f"{ts}_{filename_safe}"
        save_path = os.path.join(UPLOAD_FOLDER_WA, save_name)
        fichier.save(save_path)

        # 🆕 Pas d'envoi automatique : wa.me ne permet pas de joindre un fichier via un
        # lien. On prépare donc, pour chaque parent, le lien de conversation (avec la
        # légende en texte pré-rempli) ; c'est l'administrateur qui télécharge le fichier
        # une fois (bouton ci-dessous) puis le joint manuellement dans chaque conversation
        # WhatsApp Web ouverte, avant de cliquer sur Envoyer.
        resultats = []
        nb_sans_tel = 0
        for pid in parent_ids:
            row = conn.execute("SELECT nom, prenom, telephone FROM users WHERE id=?", (pid,)).fetchone()
            if not row or not row['telephone']:
                nb_sans_tel += 1
                continue
            resultats.append({
                'nom': f"{row['nom']} {row['prenom']}",
                'telephone': row['telephone'],
                'lien': lien_whatsapp(row['telephone'], caption)
            })

        return jsonify({
            'resultats': resultats,
            'nb_sans_telephone': nb_sans_tel,
            'fichier_url': url_for('whatsapp_telecharger_fichier', filename=save_name),
            'fichier_nom': filename_safe
        })
    finally:
        conn.close()


@app.route('/whatsapp/fichier/<path:filename>', methods=['GET'])
@login_required
@role_required('admin')
def whatsapp_telecharger_fichier(filename):
    """Permet à l'admin de retélécharger/ouvrir le fichier pour le joindre
    manuellement dans WhatsApp Web (impossible de le pré-attacher via un lien wa.me)."""
    safe_name = secure_filename(filename)
    path = os.path.join(UPLOAD_FOLDER_WA, safe_name)
    if not os.path.exists(path):
        return "Fichier introuvable", 404
    return send_file(path, as_attachment=False, download_name=safe_name)


