@app.route('/dashboard/traiter-alerte-absences')
@role_required('admin')
def traiter_alerte_absences():
    """🆕 Appelée quand l'admin/agent admin clique sur "Voir les absences" depuis la carte
    "Absences fréquentes" des Actions recommandées du dashboard. On enregistre la signature
    de la situation actuelle comme "traitée" pour que l'alerte disparaisse de "Alertes à
    traiter" — elle ne réapparaîtra que si la situation change (nouvel élève concerné ou
    compteur d'absences en hausse), voir le calcul de stats['eleves_absences_frequentes']."""
    conn = get_db()
    rows = conn.execute("""
        SELECT e.id as eleve_id, COUNT(a.id) as nb_absences
        FROM absences a
        JOIN eleves e ON a.eleve_id = e.id
        GROUP BY a.eleve_id
        ORDER BY nb_absences DESC, e.id ASC
        LIMIT 5
    """).fetchall()
    signature = ','.join(sorted(f"{r['eleve_id']}:{r['nb_absences']}" for r in rows))
    conn.execute("""
        INSERT INTO alertes_dashboard_traitees (type_alerte, signature, traite_le)
        VALUES ('absences_frequentes', ?, ?)
        ON CONFLICT(type_alerte) DO UPDATE SET signature = excluded.signature, traite_le = excluded.traite_le
    """, (signature, datetime.datetime.now().isoformat()))
    conn.commit()
    conn.close()
    return redirect(url_for('absences'))


@app.route('/absences', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'enseignant', 'secretaire')
def absences():
    # 🆕 L'admin, l'agent admin ET la secrétaire passent désormais par le hub (Enseignant /
    # Élève / Salarié hors prof — le type "Enseignant" restant filtré pour la secrétaire, voir
    # absences_hub) plutôt que par l'ancien formulaire à choix de cycle (élèves uniquement),
    # réservé maintenant à l'enseignant uniquement. 🩹 CORRECTIF : avant cette ligne,
    # seul role=='admin' était redirigé — l'agent admin retombait donc sur l'ancien formulaire
    # et n'avait jamais accès à la gestion des absences ENSEIGNANTS malgré les commentaires
    # plus bas indiquant que ce type devait leur être ouvert. 🆕 La secrétaire rejoint désormais
    # ce même groupe : son système d'absences élèves utilise la même logique et le même design
    # que celui de l'agent admin (hub → dashboard → marquer / historique), au lieu de l'ancien
    # parcours "cartes de classes" ci-dessous, qui reste réservé à l'enseignant.
    if session['role'] in ('admin', 'agent_admin', 'secretaire') and request.method == 'GET':
        return redirect(url_for('absences_hub'))

    conn = get_db()

    # 🆕 NOUVEAU PARCOURS ENSEIGNANT : au lieu de l'ancien formulaire manuel
    # (choisir un élève dans une liste déroulante + date + case "justifiée"), on voit
    # uniquement SES classes assignées sous forme de cartes. On clique sur une classe →
    # tableau des élèves → clique sur un élève pour le marquer absent (voir
    # /absences/classe/<id> et /api/absences/toggle ci-dessous, qui gèrent tout
    # automatiquement sans bouton "enregistrer").
    # 🆕 ENSEIGNANT : page d'appel DIRECTE, liée à l'emploi du temps. S'il a une séance en
    # cours → les élèves de cette classe s'affichent (nom + bouton « Pointer absence »).
    # Sinon → aucun élève n'est affiché. (La secrétaire garde son parcours par classes.)
    if session['role'] == 'enseignant' and request.method == 'POST':
        conn.close()
        abort(403)
    if session['role'] == 'enseignant' and request.method == 'GET':
        jour_nom, en_cours, prochaines, refresh_s = _seances_en_cours_enseignant(conn, session['user_id'])
        aujourdhui = datetime.date.today().isoformat()
        sections = []
        for sc in en_cours:
            eleves_rows = conn.execute(
                "SELECT id, nom, prenom, photo FROM eleves WHERE classe_id=? "
                "AND COALESCE(statut_sortie, '') <> 'sortant_annee' ORDER BY nom, prenom",
                (sc['classe_id'],)).fetchall()
            absents = set()
            for r in conn.execute(
                    "SELECT eleve_id, seance FROM absences WHERE date_absence=? AND eleve_id IN "
                    "(SELECT id FROM eleves WHERE classe_id=?)", (aujourdhui, sc['classe_id'])).fetchall():
                # seance 0/NULL = ancienne absence « journée entière » → absent sur toutes les séances
                if r['seance'] in (0, None) or r['seance'] == sc['num']:
                    absents.add(r['eleve_id'])
            eleves_l = [dict(e, absent=(e['id'] in absents)) for e in eleves_rows]
            sections.append(dict(sc, eleves=eleves_l, nb_absents=sum(1 for e in eleves_l if e['absent'])))
        conn.close()
        return render_template_string(ABSENCES_PROF_APPEL_HTML, sections=sections, prochaines=prochaines,
                                      jour_nom=jour_nom, aujourdhui=aujourdhui,
                                      heure=datetime.datetime.now().strftime('%H:%M'),
                                      refresh_s=refresh_s, notif_count=get_notif_count())
    if session['role'] in ('enseignant', 'secretaire') and request.method == 'GET':
        classes_prof = _classes_assignees_role(conn, session['role'], session['user_id'])
        conn.close()
        return render_template_string(ABSENCES_PROF_CLASSES_HTML, classes=classes_prof,
                                      notif_count=get_notif_count())

    # Récupération du cycle actif (par défaut 'Primaire' si aucun n'est spécifié)
    cycle = request.form.get('cycle') or request.args.get('cycle', 'Primaire')

    if request.method == 'POST':
        f = request.form
        conn.execute("INSERT INTO absences (eleve_id,date_absence,justifiee,motif,signale_par) VALUES (?,?,?,?,?)",
                     (f['eleve_id'], f['date_absence'], 1 if f.get('justifiee') else 0, f.get('motif', ''),
                      session['user_id']))
        trace_absence_eleve(conn, 'creation', f['eleve_id'],
                            f"Absence {'justifiée' if f.get('justifiee') else 'non justifiée'} le {f['date_absence']} (journée entière)",
                            f.get('motif', ''))
        eleve = conn.execute("SELECT parent_id, prenom||' '||nom as nom FROM eleves WHERE id=?",
                             (f['eleve_id'],)).fetchone()
        if eleve and eleve['parent_id']:
            just = "justifiée" if f.get('justifiee') else "non justifiée"
            notif_to_parent(eleve['parent_id'], f"🗓️ Absence {just} signalée pour {eleve['nom']} le {_notif_fmt_date(f['date_absence'])}.",
                            conn, **NOTIF_ABSENCE_KW)
        conn.commit()
        flash('Absence enregistrée!', 'success')

    if session['role'] in ('enseignant', 'secretaire'):
        # Filtrage des élèves et absences de l'enseignant/secrétaire selon le cycle actif
        table, col = ('classe_profs', 'enseignant_id') if session['role'] == 'enseignant' else ('classe_secretaires', 'secretaire_id')
        eleves_list = conn.execute(
            f"SELECT e.*, c.nom as classe FROM eleves e JOIN classes c ON e.classe_id=c.id WHERE EXISTS (SELECT 1 FROM {table} t WHERE t.classe_id=c.id AND t.{col}=?) AND (c.cycle=? OR (c.cycle IS NULL AND ?='Primaire')) AND COALESCE(e.statut_sortie, '') <> 'sortant_annee' ORDER BY e.nom",
            (session['user_id'], cycle, cycle)).fetchall()
        absences_list = conn.execute(
            f"SELECT a.*, e.prenom||' '||e.nom as eleve FROM absences a JOIN eleves e ON a.eleve_id=e.id JOIN classes c ON e.classe_id=c.id WHERE EXISTS (SELECT 1 FROM {table} t WHERE t.classe_id=c.id AND t.{col}=?) AND (c.cycle=? OR (c.cycle IS NULL AND ?='Primaire')) ORDER BY a.date_absence DESC",
            (session['user_id'], cycle, cycle)).fetchall()
    else:
        # Filtrage global (Admin) selon le cycle actif
        eleves_list = conn.execute(
            "SELECT e.*, c.nom as classe FROM eleves e JOIN classes c ON e.classe_id=c.id WHERE (c.cycle=? OR (c.cycle IS NULL AND ?='Primaire')) AND COALESCE(e.statut_sortie, '') <> 'sortant_annee' ORDER BY e.nom",
            (cycle, cycle)).fetchall()
        absences_list = conn.execute(
            "SELECT a.*, e.prenom||' '||e.nom as eleve FROM absences a JOIN eleves e ON a.eleve_id=e.id JOIN classes c ON e.classe_id=c.id WHERE c.cycle=? OR (c.cycle IS NULL AND ?='Primaire') ORDER BY a.date_absence DESC",
            (cycle, cycle)).fetchall()

    conn.close()
    return render_template_string(ABSENCES_HTML, eleves=eleves_list, absences=absences_list,
                                  notif_count=get_notif_count(), cycle=cycle)


# 🆕 ─────────────────────────────────────────────
