@app.route('/absences/classe/<int:classe_id>')
@login_required
@role_required('enseignant', 'secretaire')
def absences_classe_prof(classe_id):
    """🆕 Tableau élégant des élèves d'UNE classe assignée à l'enseignant (ou à la secrétaire).
    Cliquer sur une ligne marque/annule l'absence du JOUR pour cet élève, automatiquement
    (AJAX), sans bouton "enregistrer" — voir /api/absences/toggle."""
    # 🆕 L'enseignant passe désormais par la page d'appel liée à son emploi du temps.
    if session['role'] == 'enseignant':
        return redirect(url_for('absences'))
    conn = get_db()
    table, col = ('classe_profs', 'enseignant_id') if session['role'] == 'enseignant' else ('classe_secretaires', 'secretaire_id')
    autorise = conn.execute(
        f"SELECT 1 FROM {table} WHERE classe_id=? AND {col}=?",
        (classe_id, session['user_id'])).fetchone()
    if not autorise:
        conn.close()
        flash("Vous n'êtes pas assigné à cette classe.", 'error')
        return redirect(url_for('absences'))
    classe = conn.execute("SELECT * FROM classes WHERE id=?", (classe_id,)).fetchone()
    if not classe:
        conn.close()
        abort(404)
    aujourdhui = datetime.date.today().isoformat()
    eleves_list = conn.execute(
        "SELECT * FROM eleves WHERE classe_id=? AND COALESCE(statut_sortie, '') <> 'sortant_annee' "
        "ORDER BY nom, prenom", (classe_id,)).fetchall()

    # 🆕 Séances du jour tirées de l'emploi du temps réel de la classe : au lieu de 4
    # colonnes génériques "Séance 1/2/3/4", on propose les créneaux effectivement prévus
    # aujourd'hui pour cette classe (matière + horaire).
    jour_nom, seances_jour = _seances_jour_classe(conn, classe_id)
    nb_seances = len(seances_jour)

    # 🆕 Absences par séance : on construit, pour chaque élève absent aujourd'hui, l'ensemble
    # des séances où il est marqué absent. Les anciennes absences (seance=0, journée entière,
    # créées avant cette mise à jour) comptent comme absentes sur toutes les séances du jour,
    # pour rester cohérentes avec l'affichage précédent.
    absents_par_eleve = {}
    for r in conn.execute(
        "SELECT eleve_id, seance FROM absences WHERE date_absence=? AND eleve_id IN "
        "(SELECT id FROM eleves WHERE classe_id=?)",
        (aujourdhui, classe_id)).fetchall():
        seances = absents_par_eleve.setdefault(r['eleve_id'], set())
        if r['seance'] in (0, None):
            seances.update(range(1, nb_seances + 1))
        else:
            seances.add(r['seance'])
    conn.close()
    return render_template_string(ABSENCES_PROF_TABLE_HTML, classe=classe, eleves=eleves_list,
                                  absents_par_eleve={k: sorted(v) for k, v in absents_par_eleve.items()},
                                  seances_jour=seances_jour, jour_nom=jour_nom,
                                  aujourdhui=aujourdhui, notif_count=get_notif_count())


@app.route('/api/absences/toggle', methods=['POST'])
@login_required
@role_required('enseignant', 'secretaire')
def api_absences_toggle():
    """🆕 Marque/annule automatiquement l'absence d'une SÉANCE précise (1 à 4 : 1-2 = matin,
    3-4 = après-midi) du JOUR pour un élève, en un clic. Vérifie que l'élève appartient bien à
    une classe assignée à l'enseignant (ou à la secrétaire) connecté avant toute écriture
    (sécurité)."""
    data = request.get_json(silent=True) or {}
    try:
        eleve_id = int(data.get('eleve_id'))
    except (TypeError, ValueError):
        return jsonify({'error': "eleve_id manquant ou invalide"}), 400
    est_prof = session['role'] == 'enseignant'
    seance = None
    if not est_prof:
        try:
            seance = int(data.get('seance'))
        except (TypeError, ValueError):
            return jsonify({'error': "seance manquante ou invalide"}), 400
        if seance not in (1, 2, 3, 4):
            return jsonify({'error': "seance invalide (doit être 1, 2, 3 ou 4)"}), 400

    conn = get_db()
    if est_prof:
        # 🆕 ENSEIGNANT : la séance n'est PAS choisie par le client. Elle est déduite côté
        # serveur de l'emploi du temps : l'appel n'est possible que si l'enseignant a une
        # séance EN COURS avec la classe de cet élève (sinon refus).
        eleve = conn.execute(
            "SELECT id, prenom, nom, parent_id, classe_id FROM eleves "
            "WHERE id=? AND COALESCE(statut_sortie, '') <> 'sortant_annee'", (eleve_id,)).fetchone()
        seance_active = None
        if eleve:
            _j, _en_cours, _p, _r = _seances_en_cours_enseignant(conn, session['user_id'])
            seance_active = next((x for x in _en_cours if x['classe_id'] == eleve['classe_id']), None)
        if not eleve or not seance_active:
            conn.close()
            return jsonify({'error': "Aucune séance en cours avec cette classe : l'appel n'est pas disponible."}), 403
        seance = seance_active['num']
    else:
        table, col = ('classe_secretaires', 'secretaire_id')
        eleve = conn.execute(
            f"SELECT e.id, e.prenom, e.nom, e.parent_id, e.classe_id FROM eleves e JOIN classes c ON e.classe_id=c.id "
            f"WHERE e.id=? AND COALESCE(e.statut_sortie, '') <> 'sortant_annee' "
            f"AND EXISTS (SELECT 1 FROM {table} t WHERE t.classe_id=c.id AND t.{col}=?)",
            (eleve_id, session['user_id'])).fetchone()
        if not eleve:
            conn.close()
            return jsonify({'error': "Élève introuvable ou non autorisé pour cet enseignant."}), 403

    aujourdhui = datetime.date.today().isoformat()
    _noms_seances_jour = _noms_seances_classe(conn, eleve['classe_id'])
    # 🆕 Une éventuelle ancienne absence "journée entière" (seance=0, créée avant cette mise à
    # jour) est convertie en absences séance par séance dès qu'on touche à ce jour, pour ne
    # jamais avoir un mélange incohérent des deux systèmes sur une même journée.
    ancienne_journee_entiere = conn.execute(
        "SELECT id, justifiee, motif FROM absences WHERE eleve_id=? AND date_absence=? AND seance=0",
        (eleve_id, aujourdhui)).fetchone()
    if ancienne_journee_entiere:
        conn.execute("DELETE FROM absences WHERE id=?", (ancienne_journee_entiere['id'],))
        for s in (1, 2, 3, 4):
            conn.execute(
                "INSERT INTO absences (eleve_id,date_absence,seance,justifiee,motif,signale_par,creneau) VALUES (?,?,?,?,?,?,?)",
                (eleve_id, aujourdhui, s, ancienne_journee_entiere['justifiee'], ancienne_journee_entiere['motif'], session['user_id'],
                 _noms_seances_jour.get(s)))
        conn.commit()

    existante = conn.execute(
        "SELECT id FROM absences WHERE eleve_id=? AND date_absence=? AND seance=?",
        (eleve_id, aujourdhui, seance)).fetchone()

    if existante:
        # 2e clic → on annule l'absence marquée précédemment sur cette séance aujourd'hui.
        conn.execute("DELETE FROM absences WHERE id=?", (existante['id'],))
        trace_absence_eleve(conn, 'suppression', eleve_id,
                            f"Absence annulée le {aujourdhui} ({SEANCES_LABELS.get(seance, f'séance {seance}')})",
                            '', existante['id'])
        conn.commit()
        conn.close()
        return jsonify({'absent': False, 'eleve_id': eleve_id, 'seance': seance})
    else:
        # 1er clic → on marque l'élève absent sur cette séance aujourd'hui (non justifiée par
        # défaut ; l'admin ou l'enseignant peut la justifier plus tard depuis la fiche élève).
        conn.execute(
            "INSERT INTO absences (eleve_id,date_absence,seance,justifiee,motif,signale_par,creneau) VALUES (?,?,?,0,?,?,?)",
            (eleve_id, aujourdhui, seance, '', session['user_id'], _noms_seances_jour.get(seance)))
        trace_absence_eleve(conn, 'creation', eleve_id,
                            f"Absence non justifiée le {aujourdhui} ({SEANCES_LABELS.get(seance, f'séance {seance}')})")
        conn.commit()
        if eleve['parent_id']:
            # 🆕 On affiche la matière réellement prévue à cette séance (tirée de l'emploi du
            # temps du jour pour la classe de l'élève) plutôt que le générique "Séance N",
            # pour que le parent sache exactement quel cours l'élève a manqué.
            _, _seances_du_jour = _seances_jour_classe(conn, eleve['classe_id'])
            _s_match = next((s for s in _seances_du_jour if s['num'] == seance), None)
            libelle_seance = f"{_s_match['titre']} ({_s_match['sous']})" if _s_match else SEANCES_LABELS.get(seance, f'séance {seance}')
            notif_to_parent(eleve['parent_id'],
                            f"🗓️ Absence signalée pour {eleve['prenom']} {eleve['nom']} le {_notif_fmt_date(aujourdhui)} ({libelle_seance}).",
                            conn, **NOTIF_ABSENCE_KW)
            conn.commit()
        conn.close()
        return jsonify({'absent': True, 'eleve_id': eleve_id, 'seance': seance})


# 🆕 ─────────────────────────────────────────────
# ABSENCES — HUB ADMIN (Enseignant / Élève / Salarié hors prof)
# ─────────────────────────────────────────────
ABSENCES_HUB_TYPES = {
    'eleve':      {'label': 'Élèves',              'icone': '🎒', 'couleur': 'blue-mid'},
    'enseignant': {'label': 'Enseignants',          'icone': '🍎', 'couleur': 'green'},
    'personnel':  {'label': 'Salariés hors prof',   'icone': '🧑\u200d🔧', 'couleur': 'purple'},
}


@app.route('/absences/hub')
@login_required
@role_required('admin', 'secretaire')
def absences_hub():
    """🆕 Page de choix : sur quel type de personne veut-on gérer les absences ?
    🔒 La secrétaire ne gère désormais que les absences des ÉLÈVES : les types 'enseignant' et
    'personnel' (salariés hors prof) sont réservés à admin/agent admin et ne sont donc pas
    proposés ici à la secrétaire."""
    types_visibles = ABSENCES_HUB_TYPES
    if session.get('role') == 'secretaire':
        types_visibles = {cle: infos for cle, infos in ABSENCES_HUB_TYPES.items() if cle == 'eleve'}
    return render_template_string(ABSENCES_HUB_HTML, types=types_visibles, notif_count=get_notif_count())


@app.route('/absences/dashboard/<type_hub>')
@login_required
@role_required('admin', 'secretaire')
def absences_dashboard(type_hub):
    """🆕 Dashboard d'un type d'absence : stats rapides + analyse (courbe d'évolution par
    période + camembert de répartition) + 2 boutons (Marquer un absent / Historique complet)."""
    if type_hub not in ABSENCES_HUB_TYPES:
        abort(404)
    # 🔒 Absences ENSEIGNANT reservees a admin/agent admin : la secretaire n y a pas acces,
    # meme en tapant l URL directement.
    if type_hub in ('enseignant', 'personnel') and session.get('role') == 'secretaire':
        flash('Acces non autorise.', 'error')
        return redirect(url_for('absences_hub'))
    conn = get_db()

    # 🆕 Courbe d'évolution des absences sur les 6 derniers mois (commune aux 3 types).
    table_par_type = {'eleve': 'absences', 'enseignant': 'absences_enseignants', 'personnel': 'absences_personnel'}
    table = table_par_type[type_hub]
    mois_labels, mois_valeurs = [], []
    try:
        for i in range(5, -1, -1):
            d = datetime.date.today().replace(day=1) - datetime.timedelta(days=i * 30)
            cle_mois = d.strftime('%Y-%m')
            nb = conn.execute(
                f"SELECT COUNT(*) FROM {table} WHERE strftime('%Y-%m', date_absence)=?", (cle_mois,)).fetchone()[0]
            mois_labels.append(d.strftime('%b %Y'))
            mois_valeurs.append(nb)
    except sqlite3.OperationalError as ex_evolution:
        print(f"  ⚠️  Erreur lors du calcul de l'évolution des absences ({type_hub}) : {ex_evolution}")
        mois_labels, mois_valeurs = [], []

    # 🩹 Filet de sécurité : si une colonne/table venait à manquer malgré la migration
    # automatique ci-dessus (ex: schéma d'une ancienne version encore présent en prod),
    # on affiche la page avec des statistiques vides plutôt que de crasher avec une
    # "Internal Server Error" — l'utilisateur peut toujours accéder à la page.
    total = justifiees = ce_mois = 0
    top = []
    repartition = []
    erreur_stats = False

    try:
        if type_hub == 'eleve':
            total = conn.execute("SELECT COUNT(*) FROM absences").fetchone()[0]
            justifiees = conn.execute("SELECT COUNT(*) FROM absences WHERE justifiee=1").fetchone()[0]
            top = conn.execute("""
                SELECT e.prenom||' '||e.nom as nom, c.nom as sous_titre, COUNT(a.id) as nb
                FROM absences a JOIN eleves e ON a.eleve_id=e.id
                LEFT JOIN classes c ON e.classe_id=c.id
                GROUP BY a.eleve_id ORDER BY nb DESC LIMIT 5
            """).fetchall()
            ce_mois = conn.execute(
                "SELECT COUNT(*) FROM absences WHERE strftime('%Y-%m', date_absence)=strftime('%Y-%m','now')").fetchone()[0]
            # 🆕 Camembert : répartition des absences PAR CLASSE
            repartition = conn.execute("""
                SELECT COALESCE(c.niveau || ' ' || c.nom, 'Sans classe') as label, COUNT(a.id) as nb
                FROM absences a JOIN eleves e ON a.eleve_id=e.id
                LEFT JOIN classes c ON e.classe_id=c.id
                GROUP BY c.id ORDER BY nb DESC
            """).fetchall()
            repartition_titre = "Répartition des absences par classe"
        elif type_hub == 'enseignant':
            total = conn.execute("SELECT COUNT(*) FROM absences_enseignants").fetchone()[0]
            justifiees = conn.execute("SELECT COUNT(*) FROM absences_enseignants WHERE justifiee=1").fetchone()[0]
            top = conn.execute("""
                SELECT u.prenom||' '||u.nom as nom, 'Enseignant' as sous_titre, COUNT(a.id) as nb
                FROM absences_enseignants a JOIN users u ON a.enseignant_id=u.id
                GROUP BY a.enseignant_id ORDER BY nb DESC LIMIT 5
            """).fetchall()
            ce_mois = conn.execute(
                "SELECT COUNT(*) FROM absences_enseignants WHERE strftime('%Y-%m', date_absence)=strftime('%Y-%m','now')").fetchone()[0]
            # 🆕 Camembert : répartition PAR CLASSE prise en charge par l'enseignant absent
            # (un enseignant peut avoir plusieurs classes → chaque classe qu'il enseigne est comptée).
            repartition = conn.execute("""
                SELECT COALESCE(c.niveau || ' ' || c.nom, 'Classe non assignée') as label, COUNT(*) as nb
                FROM absences_enseignants a
                JOIN classe_profs cp ON cp.enseignant_id = a.enseignant_id
                LEFT JOIN classes c ON cp.classe_id = c.id
                GROUP BY c.id ORDER BY nb DESC
            """).fetchall()
            repartition_titre = "Répartition des absences par classe impactée"
        else:
            total = conn.execute("SELECT COUNT(*) FROM absences_personnel").fetchone()[0]
            justifiees = conn.execute("SELECT COUNT(*) FROM absences_personnel WHERE justifiee=1").fetchone()[0]
            top = conn.execute("""
                SELECT p.prenom||' '||p.nom as nom, p.mission as sous_titre, COUNT(a.id) as nb
                FROM absences_personnel a JOIN personnel_hors_prof p ON a.personnel_id=p.id
                GROUP BY a.personnel_id ORDER BY nb DESC LIMIT 5
            """).fetchall()
            ce_mois = conn.execute(
                "SELECT COUNT(*) FROM absences_personnel WHERE strftime('%Y-%m', date_absence)=strftime('%Y-%m','now')").fetchone()[0]
            # 🆕 Camembert : répartition PAR MISSION (le personnel hors prof n'appartient pas à une classe)
            repartition = conn.execute("""
                SELECT COALESCE(p.mission, 'Non précisé') as label, COUNT(a.id) as nb
                FROM absences_personnel a JOIN personnel_hors_prof p ON a.personnel_id=p.id
                GROUP BY p.mission ORDER BY nb DESC
            """).fetchall()
            repartition_titre = "Répartition des absences par mission"
    except sqlite3.OperationalError as ex_stats:
        print(f"  ⚠️  Erreur lors du calcul des statistiques d'absences ({type_hub}) : {ex_stats}")
        erreur_stats = True
        repartition_titre = "Répartition des absences"
        flash("Certaines statistiques n'ont pas pu être calculées (base de données en cours de mise à jour). "
              "Réessayez dans quelques instants.", 'error')

    conn.close()

    infos = ABSENCES_HUB_TYPES[type_hub]
    evolution_json = json.dumps({'labels': mois_labels, 'valeurs': mois_valeurs})
    repartition_json = json.dumps({
        'labels': [r['label'] for r in repartition],
        'valeurs': [r['nb'] for r in repartition],
    }, ensure_ascii=False)
    return render_template_string(ABSENCES_DASHBOARD_HTML, type_hub=type_hub, infos=infos,
                                  total=total, justifiees=justifiees, non_justifiees=total - justifiees,
                                  ce_mois=ce_mois, top=top, repartition_titre=repartition_titre,
                                  evolution_json=evolution_json, repartition_json=repartition_json,
                                  notif_count=get_notif_count())


@app.route('/absences/marquer/<type_hub>', methods=['GET', 'POST'])
@login_required
@role_required('admin', 'secretaire')
def absences_marquer(type_hub):
    """🆕 Formulaire de saisie d'une absence.
    🆕 CHOIX DE LA DATE : admin, agent admin ET secrétaire peuvent choisir une date d'absence
    différente d'aujourd'hui (ex: saisie a posteriori) — le champ est pré-rempli avec la date
    du jour et reste modifiable par ces trois rôles.
    🆕 ABSENCE SUR PLUSIEURS JOURS : un champ "nombre de jours d'absence" permet de couvrir
    d'un coup plusieurs jours consécutifs. Le 1er jour (celui choisi ci-dessus) utilise les
    séances/créneaux réellement prévus ce jour-là (comme pour une absence d'un seul jour) ;
    les jours suivants sont automatiquement enregistrés en journée complète (les dimanches,
    sans école, ne sont pas comptés)."""
    if type_hub not in ABSENCES_HUB_TYPES:
        abort(404)
    # 🔒 Absences ENSEIGNANT reservees a admin/agent admin : la secretaire n y a pas acces,
    # meme en tapant l URL directement.
    if type_hub in ('enseignant', 'personnel') and session.get('role') == 'secretaire':
        flash('Acces non autorise.', 'error')
        return redirect(url_for('absences_hub'))
    conn = get_db()
    aujourdhui = datetime.date.today().isoformat()
    role = session.get('role')
    # 🆕 Les 3 rôles qui accèdent à cette page (admin, agent admin — ajouté automatiquement par
    # role_required ci-dessus dès que 'admin' y figure —, et secrétaire) peuvent tous choisir
    # la date de l'absence.
    peut_choisir_date = role in ('admin', 'agent_admin', 'secretaire')

    def _date_validee(valeur):
        """Valide une date ISO (YYYY-MM-DD) envoyée par le client ; retourne aujourd'hui si
        absente/invalide, pour ne jamais planter ni accepter un format inattendu."""
        if not valeur:
            return aujourdhui
        try:
            datetime.date.fromisoformat(valeur)
            return valeur
        except ValueError:
            return aujourdhui

    def _dates_absence_multi(date_debut, date_fin_brut):
        """🆕 Construit la liste des dates couvertes par l'absence, à partir d'une date de début
        et d'une date de fin choisies par l'utilisateur : la date de départ (jour J, utilisée
        pour le choix des séances/créneaux) est toujours incluse, suivie de tous les jours
        OUVRABLES jusqu'à la date de fin (le week-end — samedi ET dimanche — est exclu du
        décompte, il ne compte pas comme jour d'absence). Si la date de fin est absente,
        invalide ou antérieure/égale à la date de début, retourne uniquement [date_debut]
        (absence d'un seul jour)."""
        try:
            d_fin = datetime.date.fromisoformat(date_fin_brut)
        except (TypeError, ValueError):
            return [date_debut]
        d_debut = datetime.date.fromisoformat(date_debut)
        if d_fin <= d_debut:
            return [date_debut]
        dates = [date_debut]
        cur = d_debut
        while cur < d_fin:
            cur = cur + datetime.timedelta(days=1)
            if JOURS_PY_INDEX.get(cur.weekday()) in ('Samedi', 'Dimanche'):
                continue
            dates.append(cur.isoformat())
        return dates

    if request.method == 'POST':
        f = request.form
        # 🆕 Seuls admin/agent admin/secrétaire peuvent enregistrer une absence à une date
        # différente d'aujourd'hui ; tout autre rôle (en théorie inaccessible ici) serait forcé
        # sur la date du jour.
        date_absence = _date_validee(f.get('date_absence')) if peut_choisir_date else aujourdhui
        date_fin_brut = f.get('date_fin') if peut_choisir_date else date_absence
        dates_absence = _dates_absence_multi(date_absence, date_fin_brut)
        premier_jour, jours_suivants = dates_absence[0], dates_absence[1:]
        jour_nom_saisie = JOURS_PY_INDEX.get(datetime.date.fromisoformat(premier_jour).weekday())
        entite_id = f.get('entite_id')
        if not entite_id:
            flash("Veuillez sélectionner une personne avant d'enregistrer.", 'error')
            conn.close()
            return redirect(url_for('absences_marquer', type_hub=type_hub, date_absence=date_absence))
        justifiee = 1 if f.get('justifiee') else 0
        motif = f.get('motif', '')
        if type_hub == 'eleve':
            # 🆕 Séance(s) sélectionnée(s) parmi celles proposées (tirées de l'emploi du temps du
            # PREMIER JOUR pour la classe de l'élève) : une ligne d'absence par séance cochée.
            # Si aucune séance n'est cochée, absence "journée entière" (seance=0) pour ce 1er
            # jour. Les jours suivants (si nb_jours > 1) sont TOUJOURS enregistrés en journée
            # complète, quelles que soient les séances cochées pour le 1er jour.
            # 🆕 On revalide côté serveur par rapport au nombre RÉEL de séances de la classe ce
            # jour-là (plus de plafond fixe à 4 : une classe peut avoir plus de séances/jour).
            _eleve_pour_validation = conn.execute("SELECT classe_id FROM eleves WHERE id=?", (entite_id,)).fetchone()
            _nb_seances_reel = 4
            _noms_seances_saisie = {}
            if _eleve_pour_validation and _eleve_pour_validation['classe_id']:
                _, _seances_validation = _seances_jour_classe(conn, _eleve_pour_validation['classe_id'], jour_nom_saisie)
                _nb_seances_reel = len(_seances_validation)
                _noms_seances_saisie = {_sv['num']: _sv['titre'] for _sv in _seances_validation}
            seances_choisies = [s for s in f.getlist('seances') if s.isdigit() and 1 <= int(s) <= _nb_seances_reel]
            if seances_choisies:
                for s in seances_choisies:
                    conn.execute(
                        "INSERT INTO absences (eleve_id,date_absence,seance,justifiee,motif,signale_par,creneau) VALUES (?,?,?,?,?,?,?)",
                        (entite_id, premier_jour, int(s), justifiee, motif, session['user_id'],
                         _noms_seances_saisie.get(int(s))))
            else:
                conn.execute("INSERT INTO absences (eleve_id,date_absence,justifiee,motif,signale_par) VALUES (?,?,?,?,?)",
                             (entite_id, premier_jour, justifiee, motif, session['user_id']))
            for d in jours_suivants:
                conn.execute("INSERT INTO absences (eleve_id,date_absence,justifiee,motif,signale_par) VALUES (?,?,?,?,?)",
                             (entite_id, d, justifiee, motif, session['user_id']))
            _periode_tr = f"du {premier_jour} au {dates_absence[-1]}" if jours_suivants else f"le {premier_jour}"
            _seances_tr = ("séance(s) " + ", ".join(sorted(seances_choisies, key=int))) if seances_choisies else "journée entière"
            trace_absence_eleve(conn, 'creation', entite_id,
                                f"Absence {'justifiée' if justifiee else 'non justifiée'} {_periode_tr} ({_seances_tr})", motif)
            eleve = conn.execute("SELECT parent_id, prenom||' '||nom as nom, classe_id FROM eleves WHERE id=?",
                                 (entite_id,)).fetchone()
            if eleve and eleve['parent_id']:
                just = "justifiée" if justifiee else "non justifiée"
                if seances_choisies:
                    # 🆕 On remplace les numéros de séance par les matières réellement prévues
                    # le 1er jour pour la classe de l'élève (emploi du temps réel), plutôt que
                    # d'afficher "séance 1, 2".
                    _, _seances_du_jour = _seances_jour_classe(conn, eleve['classe_id'], jour_nom_saisie)
                    _titres_par_num = {s['num']: s['titre'] for s in _seances_du_jour}
                    _noms_matieres = [_titres_par_num.get(int(s), f"Séance {s}") for s in sorted(seances_choisies, key=int)]
                    detail = f" ({', '.join(_noms_matieres)})"
                else:
                    detail = ""
                periode = f"du {premier_jour} au {dates_absence[-1]}" if jours_suivants else f"le {premier_jour}"
                notif_to_parent(eleve['parent_id'], f"🗓️ Absence {just} signalée pour {eleve['nom']} {periode}{detail}.", conn,
                                **NOTIF_ABSENCE_KW)
        elif type_hub == 'enseignant':
            # 🆕 Créneau(x) sélectionné(s) parmi ceux réellement prévus, pour le PREMIER JOUR,
            # pour cet enseignant (tirés des matières qui lui sont assignées). On revalide côté
            # serveur les ids reçus par rapport à la liste calculée pour CET enseignant à CETTE
            # date (jamais de confiance aveugle dans les données envoyées par le formulaire).
            # Les jours suivants (si nb_jours > 1) sont TOUJOURS enregistrés en journée complète.
            _, _creneaux_du_jour = _creneaux_jour_enseignant(conn, entite_id, jour_nom_saisie)
            _creneaux_par_id = {str(c['id']): c for c in _creneaux_du_jour}
            creneaux_choisis = [cid for cid in f.getlist('creneaux') if cid in _creneaux_par_id]
            if creneaux_choisis:
                for cid in creneaux_choisis:
                    c = _creneaux_par_id[cid]
                    libelle_creneau = f"{c['sous']} · {c['titre']} ({c['classe']})"
                    conn.execute(
                        "INSERT INTO absences_enseignants (enseignant_id,date_absence,creneau,justifiee,motif,signale_par) VALUES (?,?,?,?,?,?)",
                        (entite_id, premier_jour, libelle_creneau, justifiee, motif, session['user_id']))
            else:
                conn.execute("INSERT INTO absences_enseignants (enseignant_id,date_absence,justifiee,motif,signale_par) VALUES (?,?,?,?,?)",
                             (entite_id, premier_jour, justifiee, motif, session['user_id']))
            for d in jours_suivants:
                conn.execute("INSERT INTO absences_enseignants (enseignant_id,date_absence,justifiee,motif,signale_par) VALUES (?,?,?,?,?)",
                             (entite_id, d, justifiee, motif, session['user_id']))
            _periode_tr = f"du {premier_jour} au {dates_absence[-1]}" if jours_suivants else f"le {premier_jour}"
            try:
                _creneaux_tr = ", ".join(
                    f"{_creneaux_par_id[c]['sous']} · {_creneaux_par_id[c]['titre']} ({_creneaux_par_id[c]['classe']})"
                    for c in creneaux_choisis) if creneaux_choisis else "journée entière"
            except Exception:
                _creneaux_tr = "journée entière"
            trace_absence_prof(conn, 'creation', entite_id,
                               f"Absence {'justifiée' if justifiee else 'non justifiée'} {_periode_tr} ({_creneaux_tr})", motif)
        else:
            for d in dates_absence:
                conn.execute("INSERT INTO absences_personnel (personnel_id,date_absence,justifiee,motif,signale_par) VALUES (?,?,?,?,?)",
                             (entite_id, d, justifiee, motif, session['user_id']))
        conn.commit()
        conn.close()
        if len(dates_absence) > 1:
            flash(f"Absence enregistrée sur {len(dates_absence)} jours ouvrables ({premier_jour} → {dates_absence[-1]}) !", 'success')
        else:
            flash('Absence enregistrée !', 'success')
        return redirect(url_for('absences_marquer', type_hub=type_hub, date_absence=date_absence))

    # 🆕 GET : date sélectionnée (défaut = aujourd'hui, modifiable via le champ du formulaire
    # pour admin/agent admin/secrétaire). Le jour de la semaine correspondant sert à aller
    # chercher les séances/créneaux du BON jour dans l'emploi du temps (et non plus
    # systématiquement celui d'aujourd'hui), pour rester cohérent avec la date choisie.
    date_absence = _date_validee(request.args.get('date_absence')) if peut_choisir_date else aujourdhui
    jour_nom_choisi = JOURS_PY_INDEX.get(datetime.date.fromisoformat(date_absence).weekday())

    classe_id = request.args.get('classe_id', type=int)
    q = (request.args.get('q') or '').strip()
    classes = []
    entites = []
    seances_jour = []
    jour_nom = None
    if type_hub == 'eleve':
        classes = conn.execute("SELECT * FROM classes ORDER BY niveau, nom").fetchall()
        if q:
            entites = conn.execute(
                "SELECT e.id, e.prenom||' '||e.nom as nom, c.nom as sous_titre FROM eleves e "
                "LEFT JOIN classes c ON e.classe_id=c.id "
                "WHERE (e.nom LIKE ? OR e.prenom LIKE ?) AND COALESCE(e.statut_sortie, '') <> 'sortant_annee' ORDER BY e.nom",
                (f'%{q}%', f'%{q}%')).fetchall()
        elif classe_id:
            entites = conn.execute(
                "SELECT e.id, e.prenom||' '||e.nom as nom, c.nom as sous_titre FROM eleves e "
                "LEFT JOIN classes c ON e.classe_id=c.id WHERE e.classe_id=? "
                "AND COALESCE(e.statut_sortie, '') <> 'sortant_annee' ORDER BY e.nom",
                (classe_id,)).fetchall()
            # 🆕 Séances du JOUR CHOISI proposées à partir de l'emploi du temps réel de la
            # classe sélectionnée (matière + horaire), pour marquer l'absence sur une séance
            # précise plutôt que forcément sur la journée entière.
            jour_nom, seances_jour = _seances_jour_classe(conn, classe_id, jour_nom_choisi)
    elif type_hub == 'enseignant':
        entites_rows = conn.execute(
            "SELECT id, prenom||' '||nom as nom, 'Enseignant' as sous_titre FROM users WHERE role='enseignant' ORDER BY nom"
        ).fetchall()
        # 🆕 Pour chaque enseignant, on calcule dès maintenant ses créneaux du JOUR CHOISI
        # (matière + classe + horaire, tirés des matières qui lui sont assignées) et on les
        # embarque en JSON : le formulaire les affiche instantanément au clic sur un enseignant
        # (JS), sans rechargement de page ni appel serveur supplémentaire.
        for e in entites_rows:
            jour_nom, creneaux_ens = _creneaux_jour_enseignant(conn, e['id'], jour_nom_choisi)
            entites.append({
                'id': e['id'], 'nom': e['nom'], 'sous_titre': e['sous_titre'],
                'creneaux_json': json.dumps(creneaux_ens, ensure_ascii=False),
            })
    else:
        entites = conn.execute(
            "SELECT id, prenom||' '||nom as nom, mission as sous_titre FROM personnel_hors_prof ORDER BY nom"
        ).fetchall()
    conn.close()
    infos = ABSENCES_HUB_TYPES[type_hub]
    return render_template_string(ABSENCES_MARQUER_HTML, type_hub=type_hub, infos=infos,
                                  classes=classes, classe_id=classe_id, q=q, entites=entites,
                                  seances_jour=seances_jour, jour_nom=jour_nom,
                                  aujourdhui=aujourdhui, date_absence=date_absence,
                                  peut_choisir_date=peut_choisir_date, notif_count=get_notif_count())


@app.route('/absences/historique/<type_hub>')
@login_required
@role_required('admin', 'secretaire')
def absences_historique(type_hub):
    """🆕 Historique complet (toutes dates confondues) des absences du type choisi.

    🆕 Regroupement : si une même personne a plusieurs absences le même jour (ex. plusieurs
    séances absentées dans la journée pour un élève), on les regroupe en UNE seule ligne
    cliquable dans le tableau plutôt que d'afficher une ligne par séance. Cliquer sur la ligne
    ouvre le détail (chaque séance listée séparément, modifiable/supprimable individuellement).

    🆕 SECRÉTAIRE : accès désormais accordé, avec la même logique que pour le hub/dashboard/
    marquer plus haut — même traitement que admin/agent admin pour les absences ÉLÈVES (et
    salariés hors prof), mais toujours PAS d'accès au type ENSEIGNANT (réservé admin/agent
    admin, cf. blocage identique déjà en place sur absences_hub / absences_dashboard /
    absences_marquer)."""
    if type_hub not in ABSENCES_HUB_TYPES:
        abort(404)
    # 🔒 Absences ENSEIGNANT reservees a admin/agent admin : la secretaire n y a pas acces,
    # meme en tapant l URL directement (même règle que sur absences_dashboard/absences_marquer).
    if type_hub in ('enseignant', 'personnel') and session.get('role') == 'secretaire':
        flash('Acces non autorise.', 'error')
        return redirect(url_for('absences_hub'))
    conn = get_db()
    table, id_col = ABSENCES_TABLE_PAR_TYPE[type_hub]
    if type_hub == 'eleve':
        absences_list = conn.execute("""
            SELECT a.*, e.prenom||' '||e.nom as nom, c.nom as sous_titre, e.classe_id as classe_id
            FROM absences a JOIN eleves e ON a.eleve_id=e.id
            LEFT JOIN classes c ON e.classe_id=c.id
            ORDER BY a.date_absence DESC, a.id DESC
        """).fetchall()
    elif type_hub == 'enseignant':
        absences_list = conn.execute("""
            SELECT a.*, u.prenom||' '||u.nom as nom, 'Enseignant' as sous_titre
            FROM absences_enseignants a JOIN users u ON a.enseignant_id=u.id
            ORDER BY a.date_absence DESC, a.id DESC
        """).fetchall()
    else:
        absences_list = conn.execute("""
            SELECT a.*, p.prenom||' '||p.nom as nom, p.mission as sous_titre
            FROM absences_personnel a JOIN personnel_hors_prof p ON a.personnel_id=p.id
            ORDER BY a.date_absence DESC, a.id DESC
        """).fetchall()
    # 🆕 Retards des enseignants (issus du Pointage des professeurs) — affichés en plus des
    # absences, sans les mélanger (ils ne comptent pas dans la paie ni dans les stats d'absence).
    retards_ens = None
    if type_hub == 'enseignant':
        try:
            retards_ens = conn.execute("""
                SELECT r.*, u.prenom||' '||u.nom as nom
                FROM retards_enseignants r JOIN users u ON r.enseignant_id=u.id
                ORDER BY r.date_retard DESC, r.id DESC
            """).fetchall()
        except sqlite3.OperationalError:
            retards_ens = []
    conn.close()

    # 🆕 Regroupement par (personne, date) — l'ordre SQL (date DESC, id DESC) est conservé
    # puisqu'on ne fait qu'agréger des lignes consécutives dans un dict ordonné.
    # ⚠️ La clé est nommée "lignes" et non "items" : dans Jinja, `g.liste` sur un dict Python
    # tombe sur la MÉTHODE native dict.items() plutôt que sur la clé (l'attribut est cherché
    # avant la subscription), ce qui provoquait un crash ("no len()") sur {{ g.liste|length }}.
    # 🆕 Cache (classe_id, jour_nom) → séances du jour, pour éviter de rejouer la requête sur
    # l'emploi du temps à chaque ligne d'absence (une même classe/jour peut revenir souvent
    # dans l'historique). Ne s'applique qu'aux absences élèves (seules à avoir une "seance").
    _cache_seances_jour = {}
    conn2 = get_db() if type_hub == 'eleve' else None

    def _titre_matiere_seance(classe_id, date_absence, seance_num):
        """Retrouve la matière réellement prévue pour cette séance, ce jour-là, dans la classe
        de l'élève (best-effort : basé sur l'emploi du temps ACTUEL de la classe, faute de
        pouvoir reconstituer un emploi du temps historique)."""
        if not classe_id or not seance_num:
            return None
        try:
            jour_nom = JOURS_PY_INDEX.get(datetime.date.fromisoformat(date_absence).weekday())
        except (ValueError, TypeError):
            return None
        cle_cache = (classe_id, jour_nom)
        if cle_cache not in _cache_seances_jour:
            _, _cache_seances_jour[cle_cache] = _seances_jour_classe(conn2, classe_id, jour_nom)
        s_match = next((s for s in _cache_seances_jour[cle_cache] if s['num'] == seance_num), None)
        return s_match['titre'] if s_match else None

    groupes_par_cle = {}
    ordre_cles = []
    for a in absences_list:
        cle = (a[id_col], a['date_absence'])
        if cle not in groupes_par_cle:
            groupes_par_cle[cle] = {
                'nom': a['nom'], 'sous_titre': a['sous_titre'], 'date_absence': a['date_absence'],
                'lignes': [],
            }
            ordre_cles.append(cle)
        seance_num = a['seance'] if ('seance' in a.keys() and a['seance']) else 0
        creneau_texte = a['creneau'] if ('creneau' in a.keys() and a['creneau']) else None
        if seance_num:
            classe_id = a['classe_id'] if ('classe_id' in a.keys()) else None
            titre_matiere = creneau_texte or _titre_matiere_seance(classe_id, a['date_absence'], seance_num)
            label = titre_matiere if titre_matiere else f"Séance {seance_num}"
        elif creneau_texte:
            # 🆕 Enseignant : le créneau (matière + classe + horaire) a été figé en texte au
            # moment de la saisie (voir absences_marquer), donc affiché tel quel ici.
            label = creneau_texte
        else:
            label = "Journée entière"
        groupes_par_cle[cle]['lignes'].append({
            'id': a['id'],
            'seance': seance_num,
            'label': label,
            'justifiee': bool(a['justifiee']),
            'motif': a['motif'] or '',
        })
    if conn2:
        conn2.close()

    groupes = []
    for cle in ordre_cles:
        g = groupes_par_cle[cle]
        lignes = g['lignes']
        nb_justifiees = sum(1 for it in lignes if it['justifiee'])
        if nb_justifiees == len(lignes):
            statut_justif = 'toutes'
        elif nb_justifiees == 0:
            statut_justif = 'aucune'
        else:
            statut_justif = 'mixte'
        motifs_uniques = list(dict.fromkeys(it['motif'] for it in lignes if it['motif']))
        g['statut_justif'] = statut_justif
        g['motifs_resume'] = ', '.join(motifs_uniques) if motifs_uniques else ''
        g['detail_json'] = json.dumps(lignes, ensure_ascii=False)
        groupes.append(g)

    infos = ABSENCES_HUB_TYPES[type_hub]
    return render_template_string(ABSENCES_HISTORIQUE_HTML, type_hub=type_hub, infos=infos,
                                  groupes=groupes, nb_absences_total=len(absences_list),
                                  retards_ens=retards_ens, notif_count=get_notif_count())


# 🆕 Mapping table + colonne "personne" pour chaque type d'absence, réutilisé par les
# routes de modification/suppression ci-dessous (Élèves / Enseignants / Salariés hors prof).
ABSENCES_TABLE_PAR_TYPE = {
    'eleve':      ('absences',             'eleve_id'),
    'enseignant': ('absences_enseignants', 'enseignant_id'),
    'personnel':  ('absences_personnel',   'personnel_id'),
}


@app.route('/absences/historique/<type_hub>/<int:absence_id>/edit', methods=['POST'])
@login_required
@role_required('admin', 'secretaire')
def absences_historique_edit(type_hub, absence_id):
    """🆕 Modifie une absence déjà enregistrée (date, justifiée, motif) — même logique
    pour les 3 types (élève / enseignant / salarié hors prof).
    🆕 SECRÉTAIRE : mêmes droits que admin/agent admin pour élève et salarié hors prof ;
    toujours pas d'accès au type ENSEIGNANT (même règle que le reste du module absences)."""
    if type_hub not in ABSENCES_HUB_TYPES:
        abort(404)
    if type_hub in ('enseignant', 'personnel') and session.get('role') == 'secretaire':
        flash('Acces non autorise.', 'error')
        return redirect(url_for('absences_hub'))
    table, _ = ABSENCES_TABLE_PAR_TYPE[type_hub]
    f = request.form
    conn = get_db()
    _av = conn.execute(f"SELECT * FROM {table} WHERE id=?", (absence_id,)).fetchone()
    conn.execute(
        f"UPDATE {table} SET date_absence=?, justifiee=?, motif=? WHERE id=?",
        (f.get('date_absence'), 1 if f.get('justifiee') else 0, f.get('motif', ''), absence_id))
    if _av:
        trace_absence_hub(conn, 'modification', type_hub, _av,
                          f"Absence modifiée (date : {_av['date_absence']} → {f.get('date_absence')}, "
                          f"{'justifiée' if f.get('justifiee') else 'non justifiée'})", f.get('motif', ''))
    conn.commit()
    conn.close()
    flash('Absence modifiée !', 'success')
    return redirect(url_for('absences_historique', type_hub=type_hub))


