@app.route('/notifications')
@login_required
def notifications():
    conn = get_db()
    notifs = notifs_avec_categorie(conn.execute("SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC",
                          (session['user_id'],)).fetchall())
    conn.execute("UPDATE notifications SET lu=1 WHERE user_id=?", (session['user_id'],))
    conn.commit();
    conn.close()
    # 🆕 Les alertes (priorité haute) sont affichées en tête, dans leur propre section.
    def _est_alerte(n):
        try:
            return (json.loads(n.get('meta') or '{}') or {}).get('prio') == 'haute'
        except Exception:
            return False
    alertes = [n for n in notifs if _est_alerte(n)]
    groupes = notifs_groupees([n for n in notifs if n not in alertes])
    if alertes:
        groupes.insert(0, {'key': 'alerte', 'label': 'Alertes', 'icone': '🚨', 'color': '#EF4444',
                           'liste': alertes, 'non_lues': sum(1 for n in alertes if not n.get('lu'))})
    return render_template_string(NOTIF_HTML, notifs=notifs, groupes=groupes,
                                  total=len(notifs), total_non_lues=sum(1 for n in notifs if not n['lu']),
                                  notif_count=0)


