def _heat_color(v):
    """Retourne (fond, texte) pour une cellule de heatmap en fonction d'une moyenne /20."""
    if v is None:
        return ('#f1f5f9', '#94a3b8')
    if v >= 16: return ('#15803d', '#ffffff')
    if v >= 14: return ('#4ade80', '#14532d')
    if v >= 12: return ('#fde68a', '#78350f')
    if v >= 10: return ('#fbbf24', '#78350f')
    if v >= 8:  return ('#fb923c', '#7c2d12')
    return ('#dc2626', '#ffffff')


def _pearson(xs, ys):
    """Coefficient de corrélation de Pearson, calcul pur Python (sans numpy)."""
    n = len(xs)
    if n < 3:
        return None
    mx = sum(xs) / n
    my = sum(ys) / n
    sx = sum((x - mx) ** 2 for x in xs) ** 0.5
    sy = sum((y - my) ** 2 for y in ys) ** 0.5
    if sx == 0 or sy == 0:
        return None
    cov = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    return cov / (sx * sy)


def _rows(rows):
    return [dict(r) for r in rows]


# 🆕 BADGE DE PROFIL ÉLÈVE — basé sur la moyenne générale /20 :
#   0–4 🔴 Critique · 4–8 🟠 Fragile · 8–12 🟡 Stable · 12–16 🟢 Leader · 16–20 🏆 Champion
# Sert sur la fiche élève, la page Notes et la page Analyse des Notes.
def _badge_profil(moyenne, matieres=None):
    """Calcule le badge de profil d'un élève à partir de sa moyenne générale /20.

    'matieres' est une liste optionnelle de tuples (nom_matiere, moyenne_matiere),
    utilisée pour déterminer la matière qui justifie le plus ce profil :
    - Stable / Leader / Champion → la matière la plus forte
    - Fragile / Critique → la matière la plus faible

    Retourne None si 'moyenne' est None, sinon un dict :
    {'label', 'emoji', 'css', 'matiere', 'matiere_note'}
    """
    if moyenne is None:
        return None

    if moyenne < 4:
        label, emoji, css = 'Critique', '🔴', 'critique'
    elif moyenne < 8:
        label, emoji, css = 'Fragile', '🟠', 'fragile'
    elif moyenne < 12:
        label, emoji, css = 'Stable', '🟡', 'stable'
    elif moyenne < 16:
        label, emoji, css = 'Leader', '🟢', 'leader'
    else:
        label, emoji, css = 'Champion', '🏆', 'champion'

    matiere_nom, matiere_note = None, None
    if matieres:
        valides = [(nom, val) for nom, val in matieres if val is not None]
        if valides:
            if label in ('Stable', 'Leader', 'Champion'):
                matiere_nom, matiere_note = max(valides, key=lambda x: x[1])
            else:
                matiere_nom, matiere_note = min(valides, key=lambda x: x[1])
            matiere_note = round(matiere_note, 2)

    return {'label': label, 'emoji': emoji, 'css': css,
            'matiere': matiere_nom, 'matiere_note': matiere_note}


FEEDBACK_LABELS = {'Bon': ('👍 Bon', 'bon'), 'Neutre': ('😐 Neutre', 'neutre'), 'Enerve': ('😠 Énervé', 'enerve')}


# ══════════════════════════════════════════════════════════════════
# 🆕 SUIVI DES PAIEMENTS PARENTS — badges de ponctualité + feedback rencontres
# ══════════════════════════════════════════════════════════════════
# Règle de l'école : une échéance doit être réglée le 1er du mois (la date limite exacte de
# chaque facture est stockée dans paiements.date_echeance, fixée au 1er du mois concerné).
# On compare la date de paiement effective (ou la date du jour si toujours impayé) à cette
# échéance pour juger si le règlement est à temps ou en retard.
def _indicateurs_paiement_parent(conn, parent_id):
    """Calcule, pour un parent donné, tous les indicateurs de ponctualité des paiements
    de ses enfants (toutes échéances confondues), à partir de la table 'paiements'."""
    lignes = conn.execute("""
        SELECT p.montant_total, p.montant_paye, p.statut, p.date_echeance, p.date_paiement, COALESCE(p.montant_regule, 0) AS montant_regule
        FROM paiements p
        JOIN eleves e ON p.eleve_id = e.id
        WHERE e.parent_id = ? AND p.date_echeance IS NOT NULL AND p.date_echeance != ''
    """, (parent_id,)).fetchall()

    today = datetime.date.today()
    il_y_a_6_mois = today - datetime.timedelta(days=182)
    il_y_a_12_mois = today - datetime.timedelta(days=365)

    evaluees = []  # échéances échues (payées ou toujours en retard), avec leur résultat
    nb_impayees_en_cours = 0
    solde_impaye_total = 0.0

    for l in lignes:
        montant_total = l['montant_total'] or 0
        montant_paye = l['montant_paye'] or 0
        # 🆕 Facture régularisée (élève sortant) : n'entre plus dans le solde impayé du parent
        if not (l['montant_regule'] or 0) > 0:
            solde_impaye_total += max(montant_total - montant_paye, 0)

        try:
            d_echeance = datetime.datetime.strptime(str(l['date_echeance'])[:10], '%Y-%m-%d').date()
        except (ValueError, TypeError):
            continue

        paye_integralement = (l['statut'] == 'paye') or (montant_total > 0 and montant_paye >= montant_total)

        if paye_integralement and l['date_paiement']:
            try:
                d_paiement = datetime.datetime.strptime(str(l['date_paiement'])[:10], '%Y-%m-%d').date()
            except (ValueError, TypeError):
                continue
            retard = (d_paiement - d_echeance).days
            evaluees.append({'echeance': d_echeance, 'retard': retard, 'a_temps': retard <= 0,
                              'anticipe_3j': retard <= -3})
        elif not paye_integralement and d_echeance < today:
            retard = (today - d_echeance).days
            evaluees.append({'echeance': d_echeance, 'retard': retard, 'a_temps': False, 'anticipe_3j': False})
            nb_impayees_en_cours += 1
        # sinon : échéance future non encore due -> exclue du calcul de ponctualité

    total_eval = len(evaluees)
    nb_a_temps = sum(1 for x in evaluees if x['a_temps'])
    nb_retard = total_eval - nb_a_temps
    retards_jours = [x['retard'] for x in evaluees if not x['a_temps']]
    max_retard = max(retards_jours) if retards_jours else 0
    nb_retard_plus15 = sum(1 for r in retards_jours if r > 15)
    pct_a_temps = round(nb_a_temps / total_eval * 100, 1) if total_eval else None

    # Sous-ensembles temporels (6 / 12 derniers mois) pour les badges Régulier / Exemplaire
    eval_6m = [x for x in evaluees if x['echeance'] >= il_y_a_6_mois]
    eval_12m = [x for x in evaluees if x['echeance'] >= il_y_a_12_mois]
    tout_a_temps_6m = bool(eval_6m) and all(x['a_temps'] for x in eval_6m)
    tout_a_temps_12m = bool(eval_12m) and all(x['a_temps'] for x in eval_12m)

    nb_anticipes_3j = sum(1 for x in evaluees if x.get('anticipe_3j'))

    return {
        'total_eval': total_eval, 'nb_a_temps': nb_a_temps, 'nb_retard': nb_retard,
        'max_retard': max_retard, 'nb_retard_plus15': nb_retard_plus15,
        'nb_impayees_en_cours': nb_impayees_en_cours, 'pct_a_temps': pct_a_temps,
        'tout_a_temps_6m': tout_a_temps_6m, 'tout_a_temps_12m': tout_a_temps_12m,
        'nb_anticipes_3j': nb_anticipes_3j, 'solde_impaye_total': round(solde_impaye_total, 2),
    }


def _badge_paiement_parent(indic, seuil_bloque=3000):
    """Détermine le badge de ponctualité de paiement d'un parent à partir des indicateurs
    de _indicateurs_paiement_parent(). Priorité : signaux négatifs d'abord (plus grave =
    prioritaire sur un bon historique), puis les badges positifs du meilleur au moins bon."""
    if indic['total_eval'] == 0 and indic['solde_impaye_total'] <= 0:
        return {'label': 'Aucune donnée', 'emoji': '⚪', 'css': 'neutre'}

    if indic['solde_impaye_total'] > seuil_bloque:
        return {'label': 'Compte Bloqué', 'emoji': '⚫', 'css': 'bloque'}
    if indic['max_retard'] > 30 or indic['nb_impayees_en_cours'] >= 2:
        return {'label': 'Parent Prioritaire', 'emoji': '🚨', 'css': 'prioritaire'}
    if indic['nb_retard_plus15'] >= 1:
        return {'label': 'Parent en Retard', 'emoji': '🔴', 'css': 'retard'}
    if 1 <= indic['nb_retard'] <= 2:
        return {'label': 'Parent À Régulariser', 'emoji': '🟠', 'css': 'a-regulariser'}
    if indic['nb_retard'] == 0 and indic['total_eval'] and indic['nb_anticipes_3j'] == indic['total_eval']:
        return {'label': 'Parent Premium', 'emoji': '💎', 'css': 'premium'}
    if indic['tout_a_temps_12m']:
        return {'label': 'Parent Exemplaire', 'emoji': '🏆', 'css': 'exemplaire'}
    if indic['tout_a_temps_6m']:
        return {'label': 'Parent Régulier', 'emoji': '🟢', 'css': 'regulier'}
    if indic['max_retard'] <= 7:
        return {'label': 'Parent Fiable', 'emoji': '🔵', 'css': 'fiable'}
    if indic['pct_a_temps'] is not None and indic['pct_a_temps'] >= 90:
        return {'label': 'Parent Ponctuel', 'emoji': '🟡', 'css': 'ponctuel'}

    return {'label': 'Aucune donnée', 'emoji': '⚪', 'css': 'neutre'}


def _indicateurs_feedback_parent(conn, parent_id):
    lignes = conn.execute(
        "SELECT feedback, date_rencontre FROM parent_feedback WHERE parent_id=? ORDER BY date_rencontre DESC",
        (parent_id,)).fetchall()
    nb_total = len(lignes)
    nb_bon = sum(1 for l in lignes if l['feedback'] == 'Bon')
    nb_neutre = sum(1 for l in lignes if l['feedback'] == 'Neutre')
    nb_enerve = sum(1 for l in lignes if l['feedback'] == 'Enerve')
    dernier = lignes[0]['feedback'] if lignes else None

    # Majorité : le type de feedback le plus fréquent (priorité aux signaux négatifs en cas d'égalité)
    counts = {'Bon': nb_bon, 'Neutre': nb_neutre, 'Enerve': nb_enerve}
    majoritaire = None
    if nb_total:
        max_count = max(counts.values())
        for cle in ('Enerve', 'Neutre', 'Bon'):
            if counts[cle] == max_count and max_count > 0:
                majoritaire = cle
                break

    # Répétition d'énervement : les N dernières rencontres consécutives sont "Énervé"
    enerves_consecutifs = 0
    for l in lignes:
        if l['feedback'] == 'Enerve':
            enerves_consecutifs += 1
        else:
            break

    return {
        'nb_total': nb_total, 'nb_bon': nb_bon, 'nb_neutre': nb_neutre, 'nb_enerve': nb_enerve,
        'dernier': dernier, 'majoritaire': majoritaire, 'enerves_consecutifs': enerves_consecutifs,
    }


def _badge_feedback_parent(indic):
    if indic['nb_total'] == 0:
        return {'label': 'Aucune donnée', 'emoji': '⚪', 'css': 'neutre'}

    if indic['nb_enerve'] >= 3 or indic['enerves_consecutifs'] >= 2:
        return {'label': 'Parent Prioritaire', 'emoji': '🚨', 'css': 'prioritaire'}
    if indic['nb_enerve'] >= 2:
        return {'label': 'Parent Difficile', 'emoji': '🔴', 'css': 'difficile'}
    if indic['nb_enerve'] >= 1:
        return {'label': 'Parent Sensible', 'emoji': '🟠', 'css': 'sensible'}
    if indic['nb_total'] >= 3 and indic['majoritaire'] == 'Bon':
        return {'label': 'Parent Partenaire', 'emoji': '🏆', 'css': 'partenaire'}
    if indic['nb_total'] >= 2 and indic['majoritaire'] == 'Bon':
        return {'label': 'Parent Coopératif', 'emoji': '🟢', 'css': 'cooperatif'}
    if indic['nb_total'] >= 3 and indic['majoritaire'] == 'Neutre':
        return {'label': 'Parent À Suivre', 'emoji': '🟡', 'css': 'a-suivre'}
    if indic['nb_total'] >= 1 and indic['majoritaire'] == 'Bon':
        return {'label': 'Parent Positif', 'emoji': '🔵', 'css': 'positif'}
    if indic['dernier'] == 'Neutre':
        return {'label': 'Parent Neutre', 'emoji': '⚪', 'css': 'neutre'}

    return {'label': 'Aucune donnée', 'emoji': '⚪', 'css': 'neutre'}


def get_seuil_compte_bloque(conn):
    try:
        row = conn.execute("SELECT seuil_compte_bloque FROM parametres_ecole WHERE id=1").fetchone()
        return float(row['seuil_compte_bloque']) if row and row['seuil_compte_bloque'] is not None else 3000.0
    except Exception:
        return 3000.0


def _stdev(vals):
    """Écart-type (population), calcul pur Python. Sert à distinguer un problème
    généralisé (toutes les classes/enseignants d'une matière sont homogènes et faibles)
    d'un problème localisé (les résultats varient beaucoup selon la classe/l'enseignant)."""
    n = len(vals)
    if n < 2:
        return None
    m = sum(vals) / n
    return (sum((v - m) ** 2 for v in vals) / n) ** 0.5


def _build_where(cycle, trimestre_f, gf_classe_id, gf_matiere_nom, gf_ens_id, gf_annee, exclude=()):
    parts = ["(c.cycle=? OR (c.cycle IS NULL AND ?='Primaire'))"]
    params = [cycle, cycle]
    if trimestre_f and 'trimestre' not in exclude:
        parts.append("n.trimestre=?");
        params.append(trimestre_f)
    if gf_classe_id and 'classe' not in exclude:
        parts.append("c.id=?");
        params.append(gf_classe_id)
    if gf_matiere_nom and 'matiere' not in exclude:
        parts.append("n.matiere_id IN (SELECT id FROM matieres WHERE nom=?)");
        params.append(gf_matiere_nom)
    if gf_ens_id and 'enseignant' not in exclude:
        parts.append("n.enseignant_id=?");
        params.append(gf_ens_id)
    if gf_annee and 'annee' not in exclude:
        parts.append("strftime('%Y', n.date_saisie)=?");
        params.append(gf_annee)
    return " AND ".join(parts), params


def _dataset_analyse(conn, cycle, trimestre_f='', gf_classe_id='', gf_matiere_nom='', gf_ens_id='', gf_annee=''):
    """Calcule TOUTES les données de la page Analyse des Notes (KPI, classements,
    comparaisons, corrélations, heatmap, alertes...). Utilisé par la page ET par les exports."""

    where_full, p_full = _build_where(cycle, trimestre_f, gf_classe_id, gf_matiere_nom, gf_ens_id, gf_annee)
    where_evol, p_evol = _build_where(cycle, trimestre_f, gf_classe_id, gf_matiere_nom, gf_ens_id, gf_annee,
                                      exclude=('trimestre', 'annee'))
    where_prog, p_prog = _build_where(cycle, trimestre_f, gf_classe_id, gf_matiere_nom, gf_ens_id, gf_annee,
                                      exclude=('trimestre',))

    # ---- KPI globaux ----
    # 🆕 La moyenne générale affichée est la moyenne des moyennes pondérées des élèves
    # (sous-matière puis matière) — cohérente avec tout le reste de l'app. Min/Max/taux de
    # réussite restent calculés sur les notes individuelles (indicateurs de dispersion bruts).
    moy_par_eleve_kpi = _eleves_moyennes_ponderees(conn, where_full, p_full)
    avg_pond = round(sum(moy_par_eleve_kpi.values()) / len(moy_par_eleve_kpi), 2) if moy_par_eleve_kpi else None
    g = conn.execute(
        f"SELECT MIN(n.note) as mn, MAX(n.note) as mx, COUNT(*) as total, "
        f"SUM(CASE WHEN n.note>=10 THEN 1 ELSE 0 END)*100.0/COUNT(*) as taux_reussite "
        f"FROM notes n JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
        f"WHERE {where_full}", p_full
    ).fetchone()
    global_stats = dict(g) if g else {}
    global_stats['avg'] = avg_pond
    taux_reussite = global_stats.get('taux_reussite') or 0
    global_stats['taux_echec'] = 100 - taux_reussite if global_stats.get('total') else 0

    nb_total_eleves = conn.execute(
        f"SELECT COUNT(DISTINCT e.id) FROM eleves e JOIN classes c ON e.classe_id=c.id "
        f"WHERE (c.cycle=? OR (c.cycle IS NULL AND ?='Primaire'))" + (" AND c.id=?" if gf_classe_id else ""),
        [cycle, cycle] + ([gf_classe_id] if gf_classe_id else [])
    ).fetchone()[0]

    nb_classes = conn.execute(
        f"SELECT COUNT(*) FROM classes c WHERE (c.cycle=? OR (c.cycle IS NULL AND ?='Primaire'))" +
        (" AND c.id=?" if gf_classe_id else ""),
        [cycle, cycle] + ([gf_classe_id] if gf_classe_id else [])
    ).fetchone()[0]

    nb_enseignants = conn.execute(
        f"SELECT COUNT(DISTINCT n.enseignant_id) FROM notes n JOIN eleves e ON n.eleve_id=e.id "
        f"JOIN classes c ON e.classe_id=c.id WHERE {where_full}", p_full
    ).fetchone()[0]

    # 🆕 Excellents / en difficulté = comptage sur les moyennes pondérées déjà calculées ci-dessus
    nb_excellents = sum(1 for m in moy_par_eleve_kpi.values() if m >= 16)
    nb_difficulte = sum(1 for m in moy_par_eleve_kpi.values() if m < 10)

    kpi = {
        'moyenne_generale': global_stats.get('avg') or 0,
        'taux_reussite': taux_reussite,
        'taux_echec': global_stats.get('taux_echec') or 0,
        'total_notes': global_stats.get('total') or 0,
        'note_min': global_stats.get('mn') or 0,
        'note_max': global_stats.get('mx') or 0,
        'nb_eleves': nb_total_eleves or 0,
        'nb_classes': nb_classes or 0,
        'nb_enseignants': nb_enseignants or 0,
        'nb_excellents': nb_excellents or 0,
        'nb_difficulte': nb_difficulte or 0,
    }

    # ---- Classement classes / matières / enseignants ----
    # 🆕 La moyenne d'une classe est la moyenne des moyennes pondérées de ses élèves (sous-matière
    # puis matière) — cohérent avec la fiche élève / bulletin, plutôt qu'une moyenne brute de
    # toutes les notes individuelles qui surpondérait les matières les plus "notées".
    moy_classes = conn.execute(
        f"SELECT z.classe as nom, z.niveau as niveau, AVG(z.moyenne) as avg, "
        f"COUNT(DISTINCT z.eleve_id) as nb_eleves "
        f"FROM ( "
        f"    SELECT y.eleve_id, c.nom as classe, c.niveau as niveau, "
        f"           SUM(y.matiere_moy*y.coef_matiere)*1.0/NULLIF(SUM(y.coef_matiere),0) as moyenne "
        f"    FROM ( "
        f"        SELECT eleve_id, matiere_id, coef_matiere, "
        f"               SUM(note*coef_sm)*1.0/NULLIF(SUM(coef_sm),0) as matiere_moy "
        f"        FROM ( "
        f"            SELECT n.eleve_id, n.matiere_id, m.coefficient as coef_matiere, n.note, "
        f"                   COALESCE(sm.coefficient,1) as coef_sm "
        f"            FROM notes n JOIN matieres m ON m.id=n.matiere_id "
        f"            JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
        f"            LEFT JOIN sous_matieres sm ON sm.id=n.sous_matiere_id "
        f"            WHERE {where_full} "
        f"        ) raw GROUP BY eleve_id, matiere_id, coef_matiere "
        f"    ) y "
        f"    JOIN eleves e ON e.id = y.eleve_id "
        f"    JOIN classes c ON c.id = e.classe_id "
        f"    GROUP BY y.eleve_id "
        f") z GROUP BY z.classe ORDER BY avg DESC", p_full
    ).fetchall()
    moy_classes = _rows(moy_classes)
    # Taux de réussite = % de notes individuelles >=10 dans la classe (indicateur brut, distinct de la moyenne)
    taux_classes_rows = conn.execute(
        f"SELECT c.nom as nom, "
        f"SUM(CASE WHEN n.note>=10 THEN 1 ELSE 0 END)*100.0/COUNT(n.id) as taux_reussite "
        f"FROM notes n JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
        f"WHERE {where_full} GROUP BY c.id", p_full
    ).fetchall()
    taux_classes_map = {r['nom']: r['taux_reussite'] for r in taux_classes_rows}
    for r in moy_classes:
        r['taux_reussite'] = taux_classes_map.get(r['nom'])
        r['taux_echec'] = 100 - (r['taux_reussite'] or 0)

    # 🆕 Moyenne par matière pondérée par le coefficient des sous-matières (ex: la moyenne
    # "Arabe" tient compte du poids de Dictée/Participation/Conjugaison), filtres actifs respectés.
    moy_matieres = conn.execute(
        f"SELECT y.matiere as nom, "
        f"SUM(y.note*y.coef_sm)*1.0/NULLIF(SUM(y.coef_sm),0) as avg, "
        f"MIN(y.note) as mn, MAX(y.note) as mx, COUNT(*) as cnt, "
        f"SUM(CASE WHEN y.note>=10 THEN 1 ELSE 0 END)*100.0/COUNT(*) as taux_reussite "
        f"FROM ( "
        f"    SELECT m.nom as matiere, n.note, COALESCE(sm.coefficient,1) as coef_sm "
        f"    FROM notes n JOIN matieres m ON n.matiere_id=m.id "
        f"    JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
        f"    LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id "
        f"    WHERE {where_full} "
        f") y GROUP BY y.matiere ORDER BY avg DESC", p_full
    ).fetchall()
    moy_matieres = _rows(moy_matieres)
    for r in moy_matieres:
        r['taux_echec'] = 100 - (r['taux_reussite'] or 0)

    # 🆕 Moyenne par enseignant pondérée par le coefficient des sous-matières (chaque note pèse
    # selon son propre poids, ex: une Dictée coef 2 compte double dans la moyenne du prof).
    stats_enseignants = conn.execute(
        f"SELECT y.id as id, y.nom as nom, "
        f"SUM(y.note*y.coef_sm)*1.0/NULLIF(SUM(y.coef_sm),0) as avg, MIN(y.note) as mn, MAX(y.note) as mx, "
        f"COUNT(*) as total_notes, SUM(CASE WHEN y.note>=10 THEN 1 ELSE 0 END)*100.0/COUNT(*) as taux_reussite "
        f"FROM ( "
        f"    SELECT u.id as id, u.prenom||' '||u.nom as nom, n.note, COALESCE(sm.coefficient,1) as coef_sm "
        f"    FROM notes n JOIN users u ON n.enseignant_id=u.id "
        f"    JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
        f"    LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id "
        f"    WHERE {where_full} "
        f") y GROUP BY y.id ORDER BY avg DESC", p_full
    ).fetchall()
    stats_enseignants = _rows(stats_enseignants)
    for r in stats_enseignants:
        r['taux_echec'] = 100 - (r['taux_reussite'] or 0)

    classes_top3 = moy_classes[:3]
    classes_bottom3 = list(reversed(moy_classes[-3:])) if len(moy_classes) > 3 else list(reversed(moy_classes))
    # 🆕 Matières les plus performantes = moyenne > 12 ; les plus difficiles = moyenne < 12
    matieres_top3 = sorted([m for m in moy_matieres if (m['avg'] or 0) > 12], key=lambda r: r['avg'] or 0, reverse=True)
    matieres_bottom3 = sorted([m for m in moy_matieres if (m['avg'] or 0) < 12], key=lambda r: r['avg'] or 0)
    # 🆕 Enseignants les plus performants = moyenne >= 14 ; à accompagner = taux de réussite < 70%
    enseignants_top3 = sorted([t for t in stats_enseignants if (t['avg'] or 0) >= 14], key=lambda r: r['avg'] or 0, reverse=True)
    enseignants_accompagnement = sorted([t for t in stats_enseignants if (t['taux_reussite'] or 0) < 70], key=lambda r: r['taux_reussite'] or 0)

    # ---- 🧠 ANALYSE AVANCÉE : croisement Prof × Classe × Matière ----
    # ✅ FIX LOGIQUE IMPORTANT : on ne compare plus un enseignant à la moyenne générale
    # tous matières confondues (ce qui pénalisait injustement les matières réputées plus
    # exigeantes comme les Maths face à des matières plus généreuses comme le Sport ou les
    # Arts). Chaque combinaison Prof+Classe+Matière est comparée à la moyenne établissement
    # DE CETTE MATIÈRE précise : une comparaison équitable, à périmètre égal.
    croisement_rows = conn.execute(
        f"SELECT y.classe as classe, y.matiere as matiere, y.enseignant_id as enseignant_id, "
        f"y.enseignant as enseignant, "
        f"SUM(y.note*y.coef_sm)*1.0/NULLIF(SUM(y.coef_sm),0) as avg, COUNT(*) as nb_notes, "
        f"COUNT(DISTINCT y.eleve_id) as nb_eleves, "
        f"SUM(CASE WHEN y.note>=10 THEN 1 ELSE 0 END)*100.0/COUNT(*) as taux_reussite "
        f"FROM ( "
        f"    SELECT c.id as classe_id, c.nom as classe, m.id as matiere_id, m.nom as matiere, "
        f"           u.id as enseignant_id, u.prenom||' '||u.nom as enseignant, "
        f"           n.eleve_id, n.note, COALESCE(sm.coefficient,1) as coef_sm "
        f"    FROM notes n JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
        f"    JOIN matieres m ON n.matiere_id=m.id JOIN users u ON n.enseignant_id=u.id "
        f"    LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id "
        f"    WHERE {where_full} "
        f") y GROUP BY y.classe_id, y.matiere_id, y.enseignant_id ORDER BY y.matiere, y.classe", p_full
    ).fetchall()
    croisement_rows = _rows(croisement_rows)
    _matiere_ref = {r['nom']: (r['avg'] or 0) for r in moy_matieres}
    for r in croisement_rows:
        ref = _matiere_ref.get(r['matiere'])
        r['matiere_ref'] = round(ref, 2) if ref is not None else None
        r['ecart'] = round((r['avg'] or 0) - ref, 2) if ref is not None else None
        r['taux_echec'] = 100 - (r['taux_reussite'] or 0)
        if r['ecart'] is None:
            r['niveau'] = 'neutral'
        elif r['ecart'] <= -2.5:
            r['niveau'] = 'danger'
        elif r['ecart'] <= -1:
            r['niveau'] = 'warning'
        elif r['ecart'] >= 2.5:
            r['niveau'] = 'excellent'
        else:
            r['niveau'] = 'normal'
    # Trié du plus préoccupant (écart le plus négatif) au plus favorable
    croisement = sorted(croisement_rows, key=lambda r: (r['ecart'] if r['ecart'] is not None else 0))

    # ---- Diagnostic par matière : problème généralisé (programme/matière) vs localisé (classe/prof précis) ----
    matiere_diagnostic = {}
    for m_ in moy_matieres:
        rows_m = [r for r in croisement_rows if r['matiere'] == m_['nom'] and r['nb_notes'] >= 3]
        vals = [r['avg'] or 0 for r in rows_m]
        ecart_type = round(_stdev(vals), 2) if len(vals) >= 2 else None
        diag_texte, diag_type = None, None
        if (m_['avg'] or 0) < 10 and ecart_type is not None:
            if ecart_type <= 1.5:
                diag_type = 'generalise'
                diag_texte = "Difficulté homogène sur toutes les classes/enseignants — probablement liée au programme ou au niveau d'exigence de la matière elle-même."
            else:
                diag_type = 'localise'
                diag_texte = "Résultats très hétérogènes selon la classe ou l'enseignant — le problème semble localisé plutôt que généralisé à toute la matière."
        matiere_diagnostic[m_['nom']] = {'ecart_type': ecart_type, 'diagnostic': diag_texte, 'type': diag_type}

    # ---- Classement complet des élèves ----
    # 🆕 La moyenne de chaque élève est calculée avec la même pondération à deux niveaux que
    # partout ailleurs dans l'app (sous-matière puis matière), tout en respectant les filtres
    # actifs de la page (cycle, trimestre, classe, matière, enseignant, année) appliqués au
    # niveau de chaque note. Le taux de réussite reste basé sur les notes individuelles (>=10).
    classement_eleves = conn.execute(
        f"SELECT y.eleve_id as id, e.prenom||' '||e.nom as nom, c.nom as classe, c.niveau as niveau, "
        f"SUM(y.matiere_moy * y.coef_matiere)*1.0/NULLIF(SUM(y.coef_matiere),0) as moyenne, "
        f"SUM(y.nb_notes) as nb_notes, "
        f"SUM(y.nb_reussite)*100.0/NULLIF(SUM(y.nb_notes),0) as taux_reussite, "
        f"(SELECT COUNT(*) FROM absences WHERE eleve_id=e.id) as nb_abs "
        f"FROM ( "
        f"    SELECT eleve_id, matiere_id, coef_matiere, "
        f"           SUM(note*coef_sm)*1.0/NULLIF(SUM(coef_sm),0) as matiere_moy, "
        f"           COUNT(*) as nb_notes, "
        f"           SUM(CASE WHEN note>=10 THEN 1 ELSE 0 END) as nb_reussite "
        f"    FROM ( "
        f"        SELECT n.eleve_id, n.matiere_id, m.coefficient as coef_matiere, n.note, "
        f"               COALESCE(sm.coefficient,1) as coef_sm "
        f"        FROM notes n "
        f"        JOIN matieres m ON m.id = n.matiere_id "
        f"        JOIN eleves e ON n.eleve_id = e.id "
        f"        JOIN classes c ON e.classe_id = c.id "
        f"        LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id "
        f"        WHERE {where_full} "
        f"    ) raw GROUP BY eleve_id, matiere_id, coef_matiere "
        f") y "
        f"JOIN eleves e ON e.id = y.eleve_id "
        f"JOIN classes c ON c.id = e.classe_id "
        f"GROUP BY y.eleve_id ORDER BY moyenne DESC", p_full
    ).fetchall()
    classement_eleves = _rows(classement_eleves)
    for i, r in enumerate(classement_eleves, 1):
        r['rang'] = i

    # 🆕 Badge de profil (Critique/Fragile/Stable/Leader/Champion) par élève, avec la matière
    # qui le justifie le plus — moyenne par matière calculée avec les mêmes filtres actifs,
    # pondérée par coefficient de sous-matière.
    mat_par_eleve_rows = conn.execute(
        f"SELECT y.eleve_id, y.matiere, SUM(y.note*y.coef_sm)*1.0/NULLIF(SUM(y.coef_sm),0) as avg "
        f"FROM ( "
        f"    SELECT n.eleve_id, m.nom as matiere, n.note, COALESCE(sm.coefficient,1) as coef_sm "
        f"    FROM notes n JOIN matieres m ON n.matiere_id=m.id JOIN eleves e ON n.eleve_id=e.id "
        f"    JOIN classes c ON e.classe_id=c.id "
        f"    LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id "
        f"    WHERE {where_full} "
        f") y GROUP BY y.eleve_id, y.matiere", p_full
    ).fetchall()
    mat_par_eleve = {}
    for row in mat_par_eleve_rows:
        mat_par_eleve.setdefault(row['eleve_id'], []).append((row['matiere'], row['avg']))
    for r in classement_eleves:
        r['profil_badge'] = _badge_profil(r['moyenne'], mat_par_eleve.get(r['id'], []))

    # 🔧 FIX : le Top 10 ne doit contenir que des élèves avec une moyenne >= 10 —
    # avant, un élève sous la moyenne pouvait apparaître s'il n'y avait pas assez
    # d'élèves au-dessus pour remplir les 10 places.
    top_eleves10 = [r for r in classement_eleves if (r['moyenne'] or 0) >= 10][:10]
    # 🔧 FIX SEUILS : "en difficulté" = entre 8 et 10 (zone tampon) ; "à risque d'échec" = sous 8 (le plus critique)
    diff_eleves10 = sorted([r for r in classement_eleves if 8 <= (r['moyenne'] or 0) < 10],
                           key=lambda r: r['moyenne'])[:10]
    risque_eleves10 = sorted([r for r in classement_eleves if (r['moyenne'] or 0) < 8],
                             key=lambda r: r['moyenne'])[:10]

    # ---- Progression / régression (2 derniers trimestres avec données) ----
    # 🆕 Moyenne par élève/trimestre pondérée (sous-matière puis matière), filtres actifs respectés.
    prog_rows = conn.execute(
        f"SELECT y.eleve_id as id, e.prenom||' '||e.nom as nom, c.nom as classe, y.trimestre, "
        f"SUM(y.matiere_moy * y.coef_matiere)*1.0/NULLIF(SUM(y.coef_matiere),0) as m "
        f"FROM ( "
        f"    SELECT eleve_id, trimestre, matiere_id, coef_matiere, "
        f"           SUM(note*coef_sm)*1.0/NULLIF(SUM(coef_sm),0) as matiere_moy "
        f"    FROM ( "
        f"        SELECT n.eleve_id, n.trimestre, n.matiere_id, m.coefficient as coef_matiere, n.note, "
        f"               COALESCE(sm.coefficient,1) as coef_sm "
        f"        FROM notes n "
        f"        JOIN matieres m ON m.id = n.matiere_id "
        f"        JOIN eleves e ON n.eleve_id = e.id "
        f"        JOIN classes c ON e.classe_id = c.id "
        f"        LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id "
        f"        WHERE {where_prog} "
        f"    ) raw GROUP BY eleve_id, trimestre, matiere_id, coef_matiere "
        f") y "
        f"JOIN eleves e ON e.id = y.eleve_id "
        f"JOIN classes c ON c.id = e.classe_id "
        f"GROUP BY y.eleve_id, y.trimestre", p_prog
    ).fetchall()
    by_student = {}
    for r in prog_rows:
        by_student.setdefault(r['id'], {'nom': r['nom'], 'classe': r['classe'], 'tri': {}})
        by_student[r['id']]['tri'][r['trimestre']] = r['m']
    deltas = []
    for sid, info in by_student.items():
        trims = sorted(info['tri'].keys())
        if len(trims) >= 2:
            last, prev = trims[-1], trims[-2]
            deltas.append({
                'nom': info['nom'], 'classe': info['classe'],
                'avant': info['tri'][prev], 'apres': info['tri'][last],
                'delta': info['tri'][last] - info['tri'][prev]
            })
    progression10 = sorted(deltas, key=lambda d: d['delta'], reverse=True)[:10]
    progression10 = [d for d in progression10 if d['delta'] > 0]
    regression10 = sorted(deltas, key=lambda d: d['delta'])[:10]
    regression10 = [d for d in regression10 if d['delta'] < 0]

    # ---- 🔍 Classements spécialisés par élève (nouveau tableau interactif à filtres) ----
    # Réutilise 'deltas' (déjà calculé ci-dessus) et 'classement_eleves' (déjà calculé plus haut),
    # sans requête supplémentaire pour la progression/amélioration.
    filtre_progression = sorted([d_ for d_ in deltas if d_['delta'] > 0], key=lambda d_: d_['delta'], reverse=True)[:15]
    filtre_amelioration = sorted(
        [d_ for d_ in deltas if d_['delta'] > 0 and (d_.get('avant') or 0) >= 1],
        key=lambda d_: d_['delta'] / d_['avant'], reverse=True
    )[:15]

    filtre_participation = sorted(
        [r for r in classement_eleves if (r.get('nb_notes') or 0) > 0],
        key=lambda r: r['nb_notes'], reverse=True
    )[:15]

    filtre_assiduite = sorted(classement_eleves, key=lambda r: r.get('nb_abs') or 0)[:15]

    # Régularité = élèves dont les notes varient le moins (écart-type le plus faible),
    # à effectif minimal de 3 notes pour que l'indicateur soit significatif.
    reg_rows = conn.execute(
        f"SELECT e.id, e.prenom||' '||e.nom as nom, c.nom as classe, AVG(n.note) as moyenne, "
        f"COUNT(n.id) as nb_notes, AVG(n.note*n.note) as avg_sq "
        f"FROM notes n JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
        f"WHERE {where_full} GROUP BY e.id HAVING COUNT(n.id)>=3", p_full
    ).fetchall()
    filtre_regularite = []
    for r in _rows(reg_rows):
        moy_r = r.get('moyenne') or 0
        variance = (r.get('avg_sq') or 0) - moy_r * moy_r
        r['ecart_type'] = round(variance ** 0.5, 2) if variance > 0 else 0.0
        filtre_regularite.append(r)
    filtre_regularite = sorted(filtre_regularite, key=lambda r: r['ecart_type'])[:15]

    filtres_eleves = {
        'progression': {
            'titre': '📈 Plus forte progression', 'colonne': 'Progression',
            'items': [{'nom': d_['nom'], 'classe': d_['classe'], 'valeur': f"+{d_['delta']:.1f} pt",
                       'detail': f"{_sn(d_['avant'],1)} → {_sn(d_['apres'],1)}{_se()}"} for d_ in filtre_progression],
        },
        'amelioration': {
            'titre': '🚀 Plus forte amélioration (relative)', 'colonne': 'Amélioration',
            'items': [{'nom': d_['nom'], 'classe': d_['classe'], 'valeur': f"+{(d_['delta']/d_['avant']*100):.0f}%",
                       'detail': f"{_sn(d_['avant'],1)} → {_sn(d_['apres'],1)}{_se()}"} for d_ in filtre_amelioration],
        },
        'regularite': {
            'titre': '🎯 Élève le plus régulier', 'colonne': 'Écart-type',
            'items': [{'nom': r['nom'], 'classe': r['classe'], 'valeur': f"±{r['ecart_type']:.2f} pt",
                       'detail': f"Moyenne {_sn(r['moyenne'],1)}{_se()} sur {r['nb_notes']} note{'s' if r['nb_notes']>1 else ''}"} for r in filtre_regularite],
        },
        'participation': {
            'titre': '🙋 Meilleure participation', 'colonne': 'Notes saisies',
            'items': [{'nom': r['nom'], 'classe': r['classe'], 'valeur': f"{r['nb_notes']} note{'s' if r['nb_notes']>1 else ''}",
                       'detail': f"Moyenne {_sn((r['moyenne'] or 0),1)}{_se()}"} for r in filtre_participation],
        },
        'assiduite': {
            'titre': '🗓️ Meilleure assiduité', 'colonne': 'Absences',
            'items': [{'nom': r['nom'], 'classe': r['classe'], 'valeur': f"{r.get('nb_abs') or 0} absence{'s' if (r.get('nb_abs') or 0)>1 else ''}",
                       'detail': f"Moyenne {_sn((r['moyenne'] or 0),1)}{_se()}"} for r in filtre_assiduite],
        },
    }

    # ---- Distribution / histogramme ----
    d = conn.execute(
        f"SELECT SUM(CASE WHEN n.note>=18 THEN 1 ELSE 0 END) as tres_bien,"
        f"SUM(CASE WHEN n.note>=14 AND n.note<18 THEN 1 ELSE 0 END) as bien,"
        f"SUM(CASE WHEN n.note>=10 AND n.note<14 THEN 1 ELSE 0 END) as assez_bien,"
        f"SUM(CASE WHEN n.note>=8 AND n.note<10 THEN 1 ELSE 0 END) as passable,"
        f"SUM(CASE WHEN n.note<8 THEN 1 ELSE 0 END) as insuffisant "
        f"FROM notes n JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
        f"WHERE {where_full}", p_full
    ).fetchone()
    distribution = dict(d) if d else {}

    hist_bins = [0] * 10  # 0-2,2-4,...,18-20
    notes_bruts = conn.execute(
        f"SELECT n.note FROM notes n JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
        f"WHERE {where_full}", p_full
    ).fetchall()
    for row in notes_bruts:
        v = row['note'] or 0
        idx = min(int(v // 2), 9)
        hist_bins[idx] += 1
    histogram = [{'label': f'{i * 2}-{i * 2 + 2}', 'count': hist_bins[i]} for i in range(10)]

    # ---- Évolutions (trimestre / année) ----
    # 🆕 La moyenne affichée par trimestre/année est la moyenne des moyennes pondérées des
    # élèves (sous-matière puis matière) ; le nombre de notes (cnt) reste le compte brut de
    # notes saisies, à titre indicatif.
    moy_trimestres_avg = conn.execute(f"""
        SELECT z.trimestre as trimestre, AVG(z.moyenne) as avg, MIN(z.moyenne) as mn, MAX(z.moyenne) as mx
        FROM (
            SELECT y.eleve_id, y.trimestre,
                   SUM(y.matiere_moy * y.coef_matiere) * 1.0 / NULLIF(SUM(y.coef_matiere), 0) as moyenne
            FROM (
                SELECT eleve_id, trimestre, matiere_id, coef_matiere,
                       SUM(note * coef_sm) * 1.0 / NULLIF(SUM(coef_sm), 0) as matiere_moy
                FROM (
                    SELECT n.eleve_id, n.trimestre, n.matiere_id, m.coefficient as coef_matiere, n.note,
                           COALESCE(sm.coefficient, 1) as coef_sm
                    FROM notes n JOIN matieres m ON m.id = n.matiere_id
                    JOIN eleves e ON n.eleve_id = e.id JOIN classes c ON e.classe_id = c.id
                    LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id
                    WHERE {where_evol}
                ) raw GROUP BY eleve_id, trimestre, matiere_id, coef_matiere
            ) y GROUP BY y.eleve_id, y.trimestre
        ) z GROUP BY z.trimestre ORDER BY z.trimestre
    """, p_evol).fetchall()
    moy_trimestres_cnt = conn.execute(
        f"SELECT n.trimestre, COUNT(n.id) as cnt "
        f"FROM notes n JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
        f"WHERE {where_evol} GROUP BY n.trimestre", p_evol
    ).fetchall()
    cnt_par_trim = {r['trimestre']: r['cnt'] for r in moy_trimestres_cnt}
    moy_trimestres = _rows(moy_trimestres_avg)
    for r in moy_trimestres:
        r['cnt'] = cnt_par_trim.get(r['trimestre'], 0)

    moy_annees_avg = conn.execute(f"""
        SELECT z.annee as annee, AVG(z.moyenne) as avg
        FROM (
            SELECT y.eleve_id, y.annee,
                   SUM(y.matiere_moy * y.coef_matiere) * 1.0 / NULLIF(SUM(y.coef_matiere), 0) as moyenne
            FROM (
                SELECT eleve_id, annee, matiere_id, coef_matiere,
                       SUM(note * coef_sm) * 1.0 / NULLIF(SUM(coef_sm), 0) as matiere_moy
                FROM (
                    SELECT n.eleve_id, strftime('%Y', n.date_saisie) as annee, n.matiere_id,
                           m.coefficient as coef_matiere, n.note, COALESCE(sm.coefficient, 1) as coef_sm
                    FROM notes n JOIN matieres m ON m.id = n.matiere_id
                    JOIN eleves e ON n.eleve_id = e.id JOIN classes c ON e.classe_id = c.id
                    LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id
                    WHERE {where_evol} AND n.date_saisie IS NOT NULL
                ) raw GROUP BY eleve_id, annee, matiere_id, coef_matiere
            ) y GROUP BY y.eleve_id, y.annee
        ) z GROUP BY z.annee ORDER BY z.annee
    """, p_evol).fetchall()
    moy_annees_cnt = conn.execute(
        f"SELECT strftime('%Y', n.date_saisie) as annee, COUNT(n.id) as cnt "
        f"FROM notes n JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
        f"WHERE {where_evol} AND n.date_saisie IS NOT NULL GROUP BY annee", p_evol
    ).fetchall()
    cnt_par_annee = {r['annee']: r['cnt'] for r in moy_annees_cnt}
    moy_annees = _rows(moy_annees_avg)
    for r in moy_annees:
        r['cnt'] = cnt_par_annee.get(r['annee'], 0)

    # ---- Absences par classe (existant) ----
    abs_classes = conn.execute(
        "SELECT c.nom, COUNT(a.id) as total, "
        "SUM(a.justifiee) as justifiees, SUM(1-a.justifiee) as non_justifiees "
        "FROM absences a JOIN eleves e ON a.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
        "WHERE c.cycle=? OR (c.cycle IS NULL AND ?='Primaire') "
        "GROUP BY c.id ORDER BY total DESC", (cycle, cycle)
    ).fetchall()
    abs_classes = _rows(abs_classes)

    # ---- Comparaison garçons / filles ----
    # 🆕 Réutilise les moyennes pondérées par élève déjà calculées (moy_par_eleve_kpi) pour
    # rester cohérent avec le reste du tableau de bord.
    eleves_sexe_rows = conn.execute(
        f"SELECT DISTINCT e.id, COALESCE(NULLIF(TRIM(e.sexe),''),'Non défini') as sexe "
        f"FROM notes n JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
        f"WHERE {where_full}", p_full
    ).fetchall()
    sexe_of_eleve = {r['id']: r['sexe'] for r in eleves_sexe_rows}
    genre_taux_rows = conn.execute(
        f"SELECT COALESCE(NULLIF(TRIM(e.sexe),''),'Non défini') as sexe, "
        f"SUM(CASE WHEN n.note>=10 THEN 1 ELSE 0 END)*100.0/COUNT(n.id) as taux_reussite "
        f"FROM notes n JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
        f"WHERE {where_full} GROUP BY sexe", p_full
    ).fetchall()
    taux_par_sexe = {r['sexe']: r['taux_reussite'] for r in genre_taux_rows}
    genre_groupes = {}
    for eid, moy in moy_par_eleve_kpi.items():
        sx = sexe_of_eleve.get(eid)
        if sx:
            genre_groupes.setdefault(sx, []).append(moy)
    genre_stats = [
        {'sexe': sx, 'avg': round(sum(vals) / len(vals), 2), 'nb_eleves': len(vals),
         'taux_reussite': taux_par_sexe.get(sx)}
        for sx, vals in genre_groupes.items()
    ]
    genre_dispo = any(g['sexe'] != 'Non défini' for g in genre_stats) and len(genre_stats) > 1

    # ---- Corrélation absences / résultats ----
    # 🆕 Utilise la moyenne pondérée par élève (moy_par_eleve_kpi) au lieu d'une AVG(note) brute.
    eleves_noms_rows = conn.execute(
        f"SELECT DISTINCT e.id, e.prenom||' '||e.nom as nom "
        f"FROM notes n JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
        f"WHERE {where_full}", p_full
    ).fetchall()
    correlation_abs = []
    for r in eleves_noms_rows:
        moy = moy_par_eleve_kpi.get(r['id'])
        if moy is None:
            continue
        nb_abs = conn.execute("SELECT COUNT(*) FROM absences WHERE eleve_id=?", (r['id'],)).fetchone()[0]
        correlation_abs.append({'nom': r['nom'], 'moyenne': moy, 'nb_abs': nb_abs})
    coef = _pearson([r['nb_abs'] or 0 for r in correlation_abs], [r['moyenne'] or 0 for r in correlation_abs])
    if coef is None:
        correlation_interpretation = "Pas assez de données pour calculer une corrélation fiable."
    elif coef <= -0.5:
        correlation_interpretation = "Corrélation négative marquée : plus l'absentéisme augmente, plus les résultats baissent."
    elif coef <= -0.2:
        correlation_interpretation = "Légère tendance : les élèves les plus absents ont en moyenne des résultats un peu plus faibles."
    elif coef >= 0.2:
        correlation_interpretation = "Aucune tendance négative détectée entre absences et résultats sur cette période."
    else:
        correlation_interpretation = "Pas de lien clair entre absences et résultats sur cette période."

    # ---- Heatmap classes x matières ----
    # 🆕 Moyenne par cellule pondérée par le coefficient des sous-matières
    heat_rows = conn.execute(
        f"SELECT y.classe as classe, y.matiere as matiere, "
        f"SUM(y.note*y.coef_sm)*1.0/NULLIF(SUM(y.coef_sm),0) as avg "
        f"FROM ( "
        f"    SELECT c.nom as classe, m.nom as matiere, n.note, COALESCE(sm.coefficient,1) as coef_sm "
        f"    FROM notes n JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
        f"    JOIN matieres m ON n.matiere_id=m.id "
        f"    LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id "
        f"    WHERE {where_full} "
        f") y GROUP BY y.classe, y.matiere", p_full
    ).fetchall()
    heat_classes = sorted({r['classe'] for r in heat_rows})
    heat_matieres = sorted({r['matiere'] for r in heat_rows})
    heat_lookup = {(r['classe'], r['matiere']): r['avg'] for r in heat_rows}
    heatmap_matrix = []
    for cl in heat_classes:
        cells = []
        for mt in heat_matieres:
            v = heat_lookup.get((cl, mt))
            bg, fg = _heat_color(v)
            cells.append({'matiere': mt, 'avg': v, 'bg': bg, 'fg': fg})
        heatmap_matrix.append({'classe': cl, 'cells': cells})

    # ---- Radar : profil matières (classe sélectionnée vs établissement) ----
    radar_classe_id = gf_classe_id or (moy_classes and None)
    radar_labels, radar_classe_values, radar_global_values, radar_classe_nom = [], [], [], None
    ref_classe_id = gf_classe_id
    if not ref_classe_id:
        first_classe = conn.execute(
            "SELECT id, nom FROM classes WHERE cycle=? OR (cycle IS NULL AND ?='Primaire') ORDER BY nom LIMIT 1",
            (cycle, cycle)).fetchone()
        if first_classe:
            ref_classe_id = first_classe['id']
    if ref_classe_id:
        rc = conn.execute("SELECT nom FROM classes WHERE id=?", (ref_classe_id,)).fetchone()
        radar_classe_nom = rc['nom'] if rc else None
        radar_rows = conn.execute(
            "SELECT y.nom as nom, SUM(y.note*y.coef_sm)*1.0/NULLIF(SUM(y.coef_sm),0) as avg "
            "FROM ( "
            "    SELECT m.nom as nom, n.note, COALESCE(sm.coefficient,1) as coef_sm "
            "    FROM notes n JOIN matieres m ON n.matiere_id=m.id "
            "    JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
            "    LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id "
            "    WHERE c.id=? "
            ") y GROUP BY y.nom ORDER BY y.nom", (ref_classe_id,)
        ).fetchall()
        global_par_matiere = conn.execute(
            "SELECT y.nom as nom, SUM(y.note*y.coef_sm)*1.0/NULLIF(SUM(y.coef_sm),0) as avg "
            "FROM ( "
            "    SELECT m.nom as nom, n.note, COALESCE(sm.coefficient,1) as coef_sm "
            "    FROM notes n JOIN matieres m ON n.matiere_id=m.id "
            "    JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
            "    LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id "
            "    WHERE (c.cycle=? OR (c.cycle IS NULL AND ?='Primaire')) "
            ") y GROUP BY y.nom ORDER BY y.nom",
            (cycle, cycle)
        ).fetchall()
        global_map = {r['nom']: r['avg'] for r in global_par_matiere}
        for r in radar_rows:
            radar_labels.append(r['nom'])
            radar_classe_values.append(round(r['avg'] or 0, 2))
            radar_global_values.append(round(global_map.get(r['nom']) or 0, 2))

    # ---- Régression ciblée PAR MATIÈRE (avec le prof concerné) — plus précis qu'une
    # simple baisse de moyenne générale, ça permet d'identifier QUELLE matière et QUEL
    # enseignant sont concernés par la baisse d'un élève donné.
    prog_mat_rows = conn.execute(
        f"SELECT y.eleve_id as id, y.nom as nom, y.classe as classe, y.matiere_id as matiere_id, "
        f"y.matiere as matiere, y.enseignant as enseignant, y.trimestre as trimestre, "
        f"SUM(y.note*y.coef_sm)*1.0/NULLIF(SUM(y.coef_sm),0) as m "
        f"FROM ( "
        f"    SELECT e.id as eleve_id, e.prenom||' '||e.nom as nom, c.nom as classe, "
        f"           m.id as matiere_id, m.nom as matiere, u.prenom||' '||u.nom as enseignant, "
        f"           n.trimestre, n.note, COALESCE(sm.coefficient,1) as coef_sm "
        f"    FROM notes n JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
        f"    JOIN matieres m ON n.matiere_id=m.id JOIN users u ON n.enseignant_id=u.id "
        f"    LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id "
        f"    WHERE {where_prog} "
        f") y GROUP BY y.eleve_id, y.matiere_id, y.trimestre", p_prog
    ).fetchall()
    by_student_matiere = {}
    for r in prog_mat_rows:
        key = (r['id'], r['matiere'])
        by_student_matiere.setdefault(
            key, {'nom': r['nom'], 'classe': r['classe'], 'matiere': r['matiere'],
                  'enseignant': r['enseignant'], 'tri': {}})
        by_student_matiere[key]['tri'][r['trimestre']] = r['m']
    regressions_matiere = []
    for key, info in by_student_matiere.items():
        trims = sorted(info['tri'].keys())
        if len(trims) >= 2:
            last, prev = trims[-1], trims[-2]
            delta = info['tri'][last] - info['tri'][prev]
            if delta <= -3:
                regressions_matiere.append({**info, 'avant': info['tri'][prev],
                                            'apres': info['tri'][last], 'delta': delta})
    regressions_matiere = sorted(regressions_matiere, key=lambda d_: d_['delta'])[:10]

    # ---- Alertes automatiques ----
    alertes = []
    for c_ in moy_classes:
        if (c_['taux_reussite'] or 0) < 50:
            alertes.append({'niveau': 'danger', 'icone': '🏫',
                            'texte': f"Classe {c_['nom']} : taux de réussite critique ({c_['taux_reussite']:.1f}%)"})
    for m_ in moy_matieres:
        if (m_['avg'] or 0) < 8:
            diag = matiere_diagnostic.get(m_['nom'], {})
            suffixe = f" — {diag['diagnostic']}" if diag.get('diagnostic') else ""
            alertes.append({'niveau': 'danger', 'icone': '📚',
                            'texte': f"Matière {m_['nom']} : moyenne générale très faible ({_sn(m_['avg'],2)}{_se()}){suffixe}"})
    # ✅ FIX LOGIQUE : comparaison équitable par matière (voir croisement_rows plus haut)
    # au lieu de comparer chaque prof à la moyenne générale tous matières confondues.
    for r in croisement_rows:
        if r['nb_notes'] >= 5 and r['ecart'] is not None and r['ecart'] <= -2.5:
            alertes.append({'niveau': 'warning', 'icone': '🔎',
                            'texte': f"{r['enseignant']} — {r['matiere']} ({r['classe']}) : moyenne "
                                     f"{r['ecart']:+.1f} pt(s) sous la moyenne établissement de cette matière "
                                     f"({_sn(r['avg'],1)} vs {_sn(r['matiere_ref'],1)}{_se()}) — à examiner (méthode "
                                     f"d'évaluation, profil de la classe, contenu du programme...)"})
    for d_ in regression10:
        if d_['delta'] <= -3:
            alertes.append({'niveau': 'danger', 'icone': '📉',
                            'texte': f"{d_['nom']} ({d_['classe']}) : forte baisse de moyenne générale ({d_['delta']:+.1f} pts) entre les 2 derniers trimestres"})
    for d_ in regressions_matiere[:5]:
        alertes.append({'niveau': 'danger', 'icone': '📉',
                        'texte': f"{d_['nom']} ({d_['classe']}) : forte baisse en {d_['matiere']} avec "
                                 f"{d_['enseignant']} ({_sn(d_['avant'],1)} → {_sn(d_['apres'],1)}, {_sn(d_['delta'],1) if d_['delta'] < 0 else '+' + _sn(d_['delta'],1)} pts)"})
    for e_ in classement_eleves:
        if (e_['nb_abs'] or 0) > 8 and (e_['moyenne'] or 0) < 10:
            alertes.append({'niveau': 'warning', 'icone': '⚠️',
                            'texte': f"{e_['nom']} : absentéisme élevé ({e_['nb_abs']} abs.) combiné à des résultats faibles ({_sn(e_['moyenne'],1)}{_se()})"})
    ordre = {'danger': 0, 'warning': 1}
    alertes = sorted(alertes, key=lambda a: ordre.get(a['niveau'], 2))[:14]

    return {
        'kpi': kpi, 'global_stats': global_stats,
        'moy_classes': moy_classes, 'moy_matieres': moy_matieres, 'stats_enseignants': stats_enseignants,
        'classes_top3': classes_top3, 'classes_bottom3': classes_bottom3,
        'matieres_top3': matieres_top3, 'matieres_bottom3': matieres_bottom3,
        'enseignants_top3': enseignants_top3, 'enseignants_accompagnement': enseignants_accompagnement,
        'classement_eleves': classement_eleves,
        'top_eleves10': top_eleves10, 'diff_eleves10': diff_eleves10, 'risque_eleves10': risque_eleves10,
        'progression10': progression10, 'regression10': regression10,
        'distribution': distribution, 'histogram': histogram,
        'moy_trimestres': moy_trimestres, 'moy_annees': moy_annees,
        'abs_classes': abs_classes,
        'genre_stats': genre_stats, 'genre_dispo': genre_dispo,
        'correlation_abs': correlation_abs, 'correlation_coef': coef,
        'correlation_interpretation': correlation_interpretation,
        'heat_matieres': heat_matieres, 'heatmap_matrix': heatmap_matrix,
        'radar_labels': radar_labels, 'radar_classe_values': radar_classe_values,
        'radar_global_values': radar_global_values, 'radar_classe_nom': radar_classe_nom,
        'alertes': alertes,
        'filtres_eleves': filtres_eleves,
        # 🧠 Analyse avancée : croisement Prof × Classe × Matière + diagnostics intelligents
        'croisement': croisement, 'matiere_diagnostic': matiere_diagnostic,
        'regressions_matiere': regressions_matiere,
        'croisement_preoccupants': [r for r in croisement if r['niveau'] in ('danger', 'warning') and r['nb_notes'] >= 3][:12],
        'croisement_excellents': [r for r in reversed(croisement) if r['niveau'] == 'excellent' and r['nb_notes'] >= 3][:8],
        'matiere_diagnostics_actifs': [
            {'matiere': nom, **d} for nom, d in matiere_diagnostic.items() if d.get('diagnostic')
        ],
    }


# ═══════════════════════════════════════════════════════════════════════════
# 🏅 MODULE QUALITÉ ISO — pilotage de la démarche d'amélioration continue :
# objectifs mesurables, historique du score dans le temps (preuve de suivi) et
# plan d'actions qualité tracé (responsable, échéance, statut, clôture).
# Aligné sur la logique PDCA (Plan-Do-Check-Act) attendue par un référentiel
# type ISO 9001 pour un établissement scolaire.
# ═══════════════════════════════════════════════════════════════════════════
def _get_objectifs_qualite(conn, cycle):
    """Objectifs qualité du cycle (créés avec des valeurs par défaut raisonnables
    au premier accès). Servent de cibles de référence pour mesurer l'écart entre
    la performance réelle et l'objectif fixé par l'établissement."""
    row = conn.execute("SELECT * FROM qualite_objectifs WHERE cycle=?", (cycle,)).fetchone()
    if not row:
        try:
            conn.execute(
                "INSERT INTO qualite_objectifs (cycle, objectif_moyenne, objectif_taux_reussite, objectif_score) "
                "VALUES (?, 12, 80, 70)", (cycle,))
            conn.commit()
        except sqlite3.OperationalError:
            pass
        row = conn.execute("SELECT * FROM qualite_objectifs WHERE cycle=?", (cycle,)).fetchone()
    return dict(row) if row else {'objectif_moyenne': 12, 'objectif_taux_reussite': 80, 'objectif_score': 70}


def _save_score_snapshot(conn, cycle, robot, kpi):
    """Enregistre (au plus 1 fois par jour et par cycle) un point d'historique du
    score qualité — condition centrale d'un système de management de la qualité :
    mesurer, enregistrer, tracer dans le temps pour prouver le pilotage."""
    today = datetime.date.today().isoformat()
    try:
        conn.execute(
            "INSERT OR REPLACE INTO qualite_historique "
            "(cycle, date_snapshot, score, moyenne, taux_reussite, nb_alertes_danger, nb_alertes_warning, nb_eleves) "
            "VALUES (?,?,?,?,?,?,?,?)",
            (cycle, today, robot.get('score'), kpi.get('moyenne_generale'), kpi.get('taux_reussite'),
             robot.get('nb_alertes_danger') or 0, robot.get('nb_alertes_warning') or 0, kpi.get('nb_eleves') or 0)
        )
        conn.commit()
    except sqlite3.OperationalError:
        pass


def _get_score_historique(conn, cycle, limite=24):
    rows = conn.execute(
        "SELECT * FROM qualite_historique WHERE cycle=? ORDER BY date_snapshot ASC", (cycle,)
    ).fetchall()
    return _rows(rows)[-limite:]


def _get_actions_qualite(conn, cycle):
    rows = conn.execute(
        "SELECT * FROM qualite_actions WHERE cycle=? ORDER BY "
        "CASE statut WHEN 'a_faire' THEN 0 WHEN 'en_cours' THEN 1 ELSE 2 END, "
        "CASE priorite WHEN 'haute' THEN 0 WHEN 'moyenne' THEN 1 ELSE 2 END, "
        "cree_le DESC", (cycle,)
    ).fetchall()
    return _rows(rows)


def _linregress_pente(points):
    """Régression linéaire simple (moindres carrés) sur une liste de (x, y).
    Retourne (pente, ordonnée_origine) ou (None, None) si non calculable —
    utilisé pour projeter une tendance (moyenne générale) sur la période suivante."""
    n = len(points)
    if n < 2:
        return None, None
    xs = [p[0] for p in points]
    ys = [p[1] for p in points]
    mx = sum(xs) / n
    my = sum(ys) / n
    num = sum((x - mx) * (y - my) for x, y in points)
    den = sum((x - mx) ** 2 for x in xs)
    if den == 0:
        return None, None
    pente = num / den
    origine = my - pente * mx
    return pente, origine


def _robot_analyse(data, cycle, objectifs=None):
    """🤖 Robot d'analyse intelligent — lit TOUTES les données déjà calculées par
    _dataset_analyse() (KPI, alertes, croisements, diagnostics, régressions...) et en
    tire un compte rendu en langage clair + des solutions concrètes et priorisées.
    Aucune donnée supplémentaire n'est interrogée : le robot "interprète" ce qui existe déjà,
    donc son avis reste toujours cohérent avec les chiffres affichés sur la page."""

    kpi = data.get('kpi', {})
    moyenne = kpi.get('moyenne_generale') or 0
    taux_reussite = kpi.get('taux_reussite') or 0
    nb_eleves = kpi.get('nb_eleves') or 0
    nb_difficulte = kpi.get('nb_difficulte') or 0
    nb_excellents = kpi.get('nb_excellents') or 0
    pct_difficulte = round((nb_difficulte / nb_eleves * 100), 1) if nb_eleves else 0
    pct_excellents = round((nb_excellents / nb_eleves * 100), 1) if nb_eleves else 0

    alertes = data.get('alertes') or []
    nb_alertes_danger = len([a for a in alertes if a.get('niveau') == 'danger'])
    nb_alertes_warning = len([a for a in alertes if a.get('niveau') == 'warning'])

    # ---- Score de santé pédagogique /100 (réussite + niveau moyen + proportion en difficulté,
    # pénalisé par les alertes critiques détectées ailleurs sur la page) ----
    score = 0.55 * taux_reussite + 0.25 * (moyenne / 20 * 100) + 0.20 * max(0, 100 - pct_difficulte * 2)
    score -= nb_alertes_danger * 3 + nb_alertes_warning * 1
    score = max(0, min(100, round(score)))

    if score >= 80:
        niveau, label, couleur, couleur_light, couleur_txt = 'excellent', 'Excellent', 'var(--ins-green)', 'var(--ins-green-light)', '#1E8A47'
    elif score >= 65:
        niveau, label, couleur, couleur_light, couleur_txt = 'bon', 'Bon', 'var(--ins-green)', 'var(--ins-green-light)', '#1E8A47'
    elif score >= 50:
        niveau, label, couleur, couleur_light, couleur_txt = 'moyen', 'Moyen', 'var(--ins-amber)', 'var(--ins-amber-light)', '#8A6100'
    elif score >= 35:
        niveau, label, couleur, couleur_light, couleur_txt = 'preoccupant', 'Préoccupant', 'var(--ins-red)', 'var(--ins-red-light)', '#B71C2B'
    else:
        niveau, label, couleur, couleur_light, couleur_txt = 'critique', 'Critique', 'var(--ins-red)', 'var(--ins-red-light)', '#B71C2B'

    # ---- Compte rendu (synthèse en langage clair) ----
    phrases = [
        f"Sur le cycle {cycle}, {nb_eleves} élève(s) répartis en {kpi.get('nb_classes') or 0} classe(s) "
        f"affichent une moyenne générale de {_sn(moyenne,2)}{_se()} pour un taux de réussite de {taux_reussite:.1f}%."
    ]
    if nb_excellents:
        phrases.append(f"{nb_excellents} élève(s) ({pct_excellents}%) se distinguent avec une moyenne ≥ {_sth(16)}{_se()}.")
    if nb_difficulte:
        phrases.append(f"{nb_difficulte} élève(s) ({pct_difficulte}%) sont en situation d'échec (moyenne < {_sth(10)}{_se()}) "
                        f"et nécessitent une attention particulière.")
    if nb_alertes_danger:
        phrases.append(f"Le système a détecté {nb_alertes_danger} alerte(s) critique(s) et "
                        f"{nb_alertes_warning} point(s) de vigilance à traiter en priorité.")
    elif nb_alertes_warning:
        phrases.append(f"{nb_alertes_warning} point(s) de vigilance ont été identifiés, sans situation critique "
                        f"à ce stade.")
    else:
        phrases.append("Aucune alerte critique n'a été détectée sur la période et le périmètre analysés.")
    synthese = " ".join(phrases)

    # ---- Points forts ----
    points_forts = []
    for c in (data.get('classes_top3') or [])[:2]:
        if (c.get('avg') or 0) > 0:
            points_forts.append(f"Classe {c['nom']} : moyenne de {_sn(c['avg'],2)}{_se()} "
                                f"({(c.get('taux_reussite') or 0):.1f}% de réussite).")
    for m in (data.get('matieres_top3') or [])[:2]:
        points_forts.append(f"Matière {m['nom']} : moyenne de {_sn(m['avg'],2)}{_se()} sur l'ensemble du périmètre.")
    for t in (data.get('enseignants_top3') or [])[:2]:
        points_forts.append(f"{t['nom']} obtient d'excellents résultats (moyenne accordée {_sn(t['avg'],2)}{_se()}).")
    if data.get('croisement_excellents'):
        r = data['croisement_excellents'][0]
        points_forts.append(f"{r['enseignant']} en {r['matiere']} ({r['classe']}) dépasse la moyenne "
                            f"établissement de la matière de {r['ecart']:+.1f} pt(s).")
    if not points_forts:
        points_forts.append("Pas encore assez de données pour dégager des points forts significatifs.")

    # ---- Points faibles ----
    points_faibles = []
    for c in (data.get('classes_bottom3') or []):
        if (c.get('taux_reussite') or 0) < 60:
            points_faibles.append(f"Classe {c['nom']} : {(c.get('taux_reussite') or 0):.1f}% de réussite "
                                  f"seulement (moyenne {_sn(c['avg'],2)}{_se()}).")
    for m in (data.get('matieres_bottom3') or [])[:2]:
        points_faibles.append(f"Matière {m['nom']} : moyenne de {_sn(m['avg'],2)}{_se()} — "
                              f"{(m.get('taux_reussite') or 0):.1f}% de réussite.")
    for t in (data.get('enseignants_accompagnement') or [])[:2]:
        points_faibles.append(f"{t['nom']} : taux de réussite de {(t.get('taux_reussite') or 0):.1f}% dans "
                              f"ses classes — un accompagnement pourrait aider.")
    for r in (data.get('croisement_preoccupants') or [])[:2]:
        points_faibles.append(f"{r['enseignant']} — {r['matiere']} ({r['classe']}) : {r['ecart']:+.1f} pt(s) "
                              f"sous la moyenne établissement de la matière.")
    for d_ in (data.get('regressions_matiere') or [])[:2]:
        points_faibles.append(f"{d_['nom']} ({d_['classe']}) : forte baisse en {d_['matiere']} "
                              f"({_sn(d_['avant'],1)} → {_sn(d_['apres'],1)}).")
    if data.get('correlation_coef') is not None and data['correlation_coef'] <= -0.2:
        points_faibles.append(data.get('correlation_interpretation') or '')
    points_faibles = [p for p in points_faibles if p]
    if not points_faibles:
        points_faibles.append("Aucun point faible majeur détecté — poursuivez le suivi régulier.")

    # ---- Solutions / recommandations, priorisées ----
    recommandations = []

    def _add(icone, titre, texte, priorite):
        recommandations.append({'icone': icone, 'titre': titre, 'texte': texte, 'priorite': priorite})

    for d_ in (data.get('matiere_diagnostics_actifs') or []):
        if d_.get('type') == 'generalise':
            _add('📖', f"Revoir le programme de {d_['matiere']}",
                f"La difficulté est homogène sur toutes les classes et enseignants — organiser une réunion "
                f"pédagogique pour ajuster le contenu, le rythme ou le barème de {d_['matiere']}, et envisager "
                f"une formation continue si besoin.", 'haute')
        elif d_.get('type') == 'localise':
            _add('🔀', f"Harmoniser les pratiques en {d_['matiere']}",
                f"Les résultats varient fortement selon la classe ou l'enseignant en {d_['matiere']} — organiser "
                f"une co-observation entre enseignants et harmoniser les méthodes d'évaluation.", 'moyenne')

    if data.get('croisement_preoccupants'):
        _add('🔎', "Accompagner les combinaisons prof × classe × matière en difficulté",
            f"{len(data['croisement_preoccupants'])} combinaison(s) sont nettement sous la moyenne de leur "
            f"matière — proposer un entretien individuel, un partage de bonnes pratiques avec les enseignants "
            f"performants sur la même matière, et un suivi rapproché la période prochaine.", 'haute')

    if data.get('enseignants_accompagnement'):
        _add('🧑‍🏫', "Mettre en place un accompagnement pédagogique ciblé",
            f"{len(data['enseignants_accompagnement'])} enseignant(s) ont un taux de réussite sous 70% — "
            f"visites de classe, mentorat par un pair, ou formation continue ciblée.", 'moyenne')

    if data.get('regressions_matiere') or data.get('regression10'):
        _add('📉', "Traiter les baisses de niveau individuelles",
            "Contacter les familles concernées et organiser un soutien scolaire ciblé pour les élèves ayant "
            "connu une forte baisse entre les deux derniers trimestres, avant que la baisse ne s'installe.",
            'haute')

    if data.get('risque_eleves10'):
        _add('🚨', "Plan de soutien pour les élèves à risque d'échec",
            f"{len(data['risque_eleves10'])} élève(s) ont une moyenne inférieure à {_sth(8)}{_se()} — mettre en place un "
            f"plan de remédiation individualisé (tutorat, devoirs accompagnés, suivi rapproché parents/"
            f"enseignants).", 'haute')
    elif data.get('diff_eleves10'):
        _add('⚠️', f"Surveiller les élèves en zone tampon ({_sth(8)}-{_sth(10)}{_se()})",
            f"{len(data['diff_eleves10'])} élève(s) sont entre {_sth(8)} et {_sth(10)}{_se()} — un soutien léger et rapide peut "
            f"éviter le décrochage.", 'moyenne')

    if data.get('correlation_coef') is not None and data['correlation_coef'] <= -0.2:
        _add('📅', "Agir sur l'assiduité",
            "Une corrélation entre absentéisme et résultats a été détectée — renforcer le suivi des absences "
            "et alerter les familles rapidement en cas d'absences répétées.",
            'haute' if data['correlation_coef'] <= -0.5 else 'moyenne')

    # ---- 🎯 Indice de risque par classe (2026) ----
    # Combine le taux d'échec (poids 60%) et l'écart à une moyenne "de sécurité" de 12/20
    # (poids 40%) en un score 0-100 unique, pour classer instantanément les classes qui ont
    # le plus besoin d'attention — sans requête supplémentaire, à partir de moy_classes déjà
    # calculé par _dataset_analyse().
    classes_a_risque = []
    for c in (data.get('moy_classes') or []):
        avg_c = c.get('avg') or 0
        echec_c = c.get('taux_echec') or 0
        nb_e = c.get('nb_eleves') or 0
        if not nb_e:
            continue
        deficit = max(0, (12 - avg_c) / 12 * 100)
        indice = round(min(100, 0.6 * echec_c + 0.4 * deficit), 1)
        if indice <= 0:
            continue
        if indice >= 60:
            niveau_r, couleur_r = 'Critique', '#FF3B30'
        elif indice >= 40:
            niveau_r, couleur_r = 'Élevé', '#FF9500'
        elif indice >= 20:
            niveau_r, couleur_r = 'Modéré', '#FBBF24'
        else:
            niveau_r, couleur_r = 'Faible', '#34C759'
        raisons = []
        if echec_c >= 30:
            raisons.append(f"{echec_c:.0f}% d'échec")
        if avg_c < 12:
            raisons.append(f"moyenne {_sn(avg_c,2)}{_se()}")
        classes_a_risque.append({
            'nom': c.get('nom'), 'indice': indice, 'niveau': niveau_r, 'couleur': couleur_r,
            'avg': avg_c, 'taux_echec': echec_c, 'nb_eleves': nb_e,
            'raison': " · ".join(raisons) if raisons else "à surveiller",
        })
    classes_a_risque = sorted(classes_a_risque, key=lambda r: r['indice'], reverse=True)[:5]

    if classes_a_risque and classes_a_risque[0]['indice'] >= 50:
        _add('🎯', f"Prioriser la classe {classes_a_risque[0]['nom']} (indice de risque {classes_a_risque[0]['indice']:.0f}/100)",
            f"Cette classe cumule le plus fort indice de risque du périmètre ({classes_a_risque[0]['raison']}) — "
            f"planifier un conseil de classe ciblé et un plan d'action à court terme.", 'haute')

    # ---- 🎯 Le même indice de risque, appliqué aux matières (même formule, même échelle) ----
    matieres_a_risque = []
    for m in (data.get('moy_matieres') or []):
        avg_m = m.get('avg') or 0
        echec_m = m.get('taux_echec') or 0
        cnt_m = m.get('cnt') or 0
        if not cnt_m:
            continue
        deficit_m = max(0, (12 - avg_m) / 12 * 100)
        indice_m = round(min(100, 0.6 * echec_m + 0.4 * deficit_m), 1)
        if indice_m <= 0:
            continue
        if indice_m >= 60:
            niveau_m, couleur_m = 'Critique', '#FF3B30'
        elif indice_m >= 40:
            niveau_m, couleur_m = 'Élevé', '#FF9500'
        elif indice_m >= 20:
            niveau_m, couleur_m = 'Modéré', '#FBBF24'
        else:
            niveau_m, couleur_m = 'Faible', '#34C759'
        matieres_a_risque.append({
            'nom': m.get('nom'), 'indice': indice_m, 'niveau': niveau_m, 'couleur': couleur_m,
            'avg': avg_m, 'taux_echec': echec_m,
        })
    matieres_a_risque = sorted(matieres_a_risque, key=lambda r: r['indice'], reverse=True)[:5]

    # ---- 📈 Tendance établissement (comparaison des deux derniers trimestres disponibles) ----
    tendance = None
    trims = data.get('moy_trimestres') or []
    if len(trims) >= 2:
        t_prev, t_last = trims[-2], trims[-1]
        ecart_t = round((t_last.get('avg') or 0) - (t_prev.get('avg') or 0), 2)
        if ecart_t > 0.2:
            sens, icone_t, couleur_t = 'hausse', '↗', '#34C759'
        elif ecart_t < -0.2:
            sens, icone_t, couleur_t = 'baisse', '↘', '#FF3B30'
        else:
            sens, icone_t, couleur_t = 'stable', '→', '#8E8E93'
        tendance = {
            'ecart': ecart_t, 'sens': sens, 'icone': icone_t, 'couleur': couleur_t,
            'trimestre_prev': t_prev.get('trimestre'), 'trimestre_last': t_last.get('trimestre'),
            'avg_prev': t_prev.get('avg') or 0, 'avg_last': t_last.get('avg') or 0,
        }
        if sens == 'baisse':
            _add('📉', f"Enrayer la baisse de tendance ({ecart_t:+.2f} pt entre S{t_prev.get('trimestre')} et S{t_last.get('trimestre')})",
                "La moyenne générale de l'établissement recule d'un trimestre à l'autre — organiser un point "
                "d'étape avec les équipes pédagogiques pour identifier les causes avant le prochain trimestre.",
                'haute' if ecart_t <= -1 else 'moyenne')

    # ---- 🚨 Baisses individuelles nominatives (au lieu d'un simple compteur) ----
    baisses_individuelles = [
        {'nom': d_.get('nom'), 'classe': d_.get('classe'), 'avant': d_.get('avant') or 0,
         'apres': d_.get('apres') or 0, 'delta': d_.get('delta') or 0}
        for d_ in (data.get('regression10') or [])[:5]
    ]

    # ---- 🌱 Élèves en nette progression — à consolider avant qu'ils ne retombent ----
    progres_a_consolider = [
        {'nom': d_.get('nom'), 'classe': d_.get('classe'), 'avant': d_.get('avant') or 0,
         'apres': d_.get('apres') or 0, 'delta': d_.get('delta') or 0}
        for d_ in (data.get('progression10') or [])[:5]
    ]
    if progres_a_consolider:
        _add('🌱', "Consolider les progrès récents",
            f"{len(progres_a_consolider)} élève(s) viennent de progresser nettement d'un trimestre à l'autre — "
            f"un mot d'encouragement et un suivi de courte durée peuvent transformer cet essai en tendance durable.",
            'basse')

    # ---- 🔮 Projection intelligente : extrapolation de la moyenne générale au prochain
    # trimestre par régression linéaire sur les trimestres déjà connus. Permet d'anticiper
    # un décrochage AVANT qu'il ne soit constaté, dans l'esprit "prévention" d'un SMQ ISO. ----
    projection = None
    if len(trims) >= 2:
        pts = [(t.get('trimestre') or 0, t.get('avg') or 0) for t in trims if t.get('trimestre') is not None]
        pente, origine = _linregress_pente(pts)
        if pente is not None:
            prochain_t = max(p[0] for p in pts) + 1
            valeur_projetee = round(max(0, min(20, origine + pente * prochain_t)), 2)
            projection = {
                'trimestre_cible': prochain_t, 'valeur': valeur_projetee,
                'pente': round(pente, 3),
                'fiable': len(pts) >= 3,
            }
            if valeur_projetee < 10:
                _add('🔮', f"Anticiper un risque de passage sous la moyenne au S{prochain_t}",
                    f"La tendance actuelle projette une moyenne générale d'environ {_sn(valeur_projetee,2)}{_se()} au "
                    f"prochain trimestre si rien ne change — agir maintenant (soutien, révision du rythme "
                    f"pédagogique) permet d'infléchir la courbe avant qu'elle ne se confirme.", 'haute')

    # ---- ⚖️ Indice d'équité inter-classes (0-100) : mesure si le niveau est homogène
    # entre les classes du périmètre ou si de fortes disparités existent — un indicateur
    # attendu dans une logique qualité (égalité de traitement pédagogique). ----
    equite = None
    classes_vals = [c.get('avg') or 0 for c in (data.get('moy_classes') or []) if (c.get('nb_eleves') or 0) > 0]
    if len(classes_vals) >= 2:
        ecart_type_classes = _stdev(classes_vals) or 0
        ecart_max = max(classes_vals) - min(classes_vals)
        # Écart-type ramené à une échelle 0-100 (un écart-type de 4pts/20 = équité nulle)
        indice_equite = round(max(0, 100 - (ecart_type_classes / 4) * 100), 1)
        if indice_equite >= 80:
            equite_label, equite_couleur = 'Homogène', '#34C759'
        elif indice_equite >= 60:
            equite_label, equite_couleur = 'Correcte', '#8BC34A'
        elif indice_equite >= 40:
            equite_label, equite_couleur = 'À surveiller', '#FBBF24'
        else:
            equite_label, equite_couleur = 'Disparités marquées', '#FF3B30'
        equite = {
            'indice': indice_equite, 'label': equite_label, 'couleur': equite_couleur,
            'ecart_type': round(ecart_type_classes, 2), 'ecart_max': round(ecart_max, 2),
        }
        if indice_equite < 50:
            _add('⚖️', "Réduire les disparités entre classes",
                f"L'écart entre la classe la plus forte et la plus faible atteint {ecart_max:.1f} points sur 20 "
                f"— envisager une répartition plus équilibrée des effectifs, une harmonisation des méthodes "
                f"pédagogiques entre classes, ou un renfort ciblé sur les classes en retrait.", 'moyenne')

    # ---- 🎯 Écart aux objectifs qualité fixés par l'établissement (moyenne, taux de
    # réussite, score) — cœur d'une démarche ISO : comparer le réel à un objectif défini
    # et déclencher une action corrective en cas d'écart significatif. ----
    objectifs = objectifs or {}
    obj_moyenne = objectifs.get('objectif_moyenne')
    obj_taux = objectifs.get('objectif_taux_reussite')
    obj_score = objectifs.get('objectif_score')
    objectifs_ecarts = None
    if obj_moyenne is not None or obj_taux is not None or obj_score is not None:
        ecart_moy = round(moyenne - obj_moyenne, 2) if obj_moyenne is not None else None
        ecart_taux = round(taux_reussite - obj_taux, 1) if obj_taux is not None else None
        ecart_score = round(score - obj_score, 1) if obj_score is not None else None
        objectifs_ecarts = {
            'objectif_moyenne': obj_moyenne, 'ecart_moyenne': ecart_moy,
            'objectif_taux_reussite': obj_taux, 'ecart_taux_reussite': ecart_taux,
            'objectif_score': obj_score, 'ecart_score': ecart_score,
            'atteint_moyenne': ecart_moy is not None and ecart_moy >= 0,
            'atteint_taux': ecart_taux is not None and ecart_taux >= 0,
            'atteint_score': ecart_score is not None and ecart_score >= 0,
        }
        if ecart_score is not None and ecart_score < -5:
            _add('🎯', f"Combler l'écart à l'objectif qualité ({score}/100 vs objectif {obj_score:.0f}/100)",
                f"Le score de santé pédagogique est {abs(ecart_score):.0f} point(s) sous l'objectif fixé pour ce "
                f"cycle — formaliser un plan d'action qualité (voir onglet Qualité ISO) avec échéance et "
                f"responsable pour combler l'écart avant la prochaine évaluation.", 'haute')

    if not recommandations:
        _add('✅', "Maintenir le cap",
            "Aucune anomalie majeure détectée sur ce périmètre. Poursuivez le suivi régulier via ce tableau "
            "de bord pour anticiper toute évolution.", 'basse')

    ordre_prio = {'haute': 0, 'moyenne': 1, 'basse': 2}
    recommandations = sorted(recommandations, key=lambda r: ordre_prio.get(r['priorite'], 3))[:8]

    return {
        'score': score, 'niveau': niveau, 'label': label, 'couleur': couleur,
        'couleur_light': couleur_light, 'couleur_txt': couleur_txt,
        'synthese': synthese,
        'classes_a_risque': classes_a_risque,
        'matieres_a_risque': matieres_a_risque,
        'tendance': tendance,
        'projection': projection,
        'equite': equite,
        'objectifs_ecarts': objectifs_ecarts,
        'baisses_individuelles': baisses_individuelles,
        'progres_a_consolider': progres_a_consolider,
        'points_forts': points_forts[:6],
        'points_faibles': points_faibles[:6],
        'recommandations': recommandations,
        'nb_alertes_danger': nb_alertes_danger, 'nb_alertes_warning': nb_alertes_warning,
        'genere_le': datetime.datetime.now().strftime('%d/%m/%Y à %H:%M'),
    }



def _analyse_notes_maternelle(conn, toutes_les_classes, gf_classe_id, trimestre_f, cycle='Maternelle'):
    """Analyse dédiée au cycle Maternelle, noté en A (Bon) / B (Moyen) / C (Bas) au lieu de /20."""
    where = ["(c.cycle = ?)"]
    params = [cycle]
    if gf_classe_id:
        where.append("c.id = ?")
        params.append(gf_classe_id)
    if trimestre_f:
        where.append("n.trimestre = ?")
        params.append(trimestre_f)
    where_sql = " AND ".join(where)

    rows = conn.execute(f"""
        SELECT n.note, n.trimestre, n.eleve_id, e.nom as el_nom, e.prenom as el_prenom,
               c.id as classe_id, c.nom as classe_nom, m.nom as mat_nom
        FROM notes n
        JOIN eleves e ON n.eleve_id = e.id
        JOIN classes c ON e.classe_id = c.id
        JOIN matieres m ON n.matiere_id = m.id
        WHERE {where_sql}
    """, params).fetchall()

    def rep(liste_lettres):
        total = len(liste_lettres)
        c = {'A': 0, 'B': 0, 'C': 0}
        for l in liste_lettres:
            c[l] = c.get(l, 0) + 1
        return {
            'total': total,
            'A': c['A'], 'B': c['B'], 'C': c['C'],
            'pA': round(c['A'] * 100 / total) if total else 0,
            'pB': round(c['B'] * 100 / total) if total else 0,
            'pC': round(c['C'] * 100 / total) if total else 0,
        }

    toutes_lettres = [_lettre_depuis_note(r['note']) for r in rows]
    kpi = rep(toutes_lettres)

    # Répartition par matière
    par_matiere = {}
    for r in rows:
        par_matiere.setdefault(r['mat_nom'], []).append(_lettre_depuis_note(r['note']))
    matieres_stats = sorted(
        [{'nom': nom, **rep(lettres)} for nom, lettres in par_matiere.items()],
        key=lambda x: x['nom']
    )

    # Répartition par classe (utile quand aucune classe précise n'est filtrée)
    par_classe = {}
    for r in rows:
        par_classe.setdefault((r['classe_id'], r['classe_nom']), []).append(_lettre_depuis_note(r['note']))
    classes_stats = sorted(
        [{'id': cid, 'nom': nom, **rep(lettres)} for (cid, nom), lettres in par_classe.items()],
        key=lambda x: x['nom']
    )

    # Par élève : tendance dominante + évolution T1 -> T2
    par_eleve = {}
    for r in rows:
        d = par_eleve.setdefault(r['eleve_id'], {
            'nom': r['el_nom'], 'prenom': r['el_prenom'], 'classe': r['classe_nom'],
            'lettres': [], 't1': [], 't2': [],
        })
        l = _lettre_depuis_note(r['note'])
        d['lettres'].append(l)
        if str(r['trimestre']) == '1':
            d['t1'].append(l)
        elif str(r['trimestre']) == '2':
            d['t2'].append(l)

    def dominante(lettres):
        if not lettres:
            return None
        from collections import Counter
        return Counter(lettres).most_common(1)[0][0]

    eleves_stats = []
    for eid, d in par_eleve.items():
        dom = dominante(d['lettres'])
        dom_t1 = dominante(d['t1'])
        dom_t2 = dominante(d['t2'])
        eleves_stats.append({
            'id': eid, 'nom': d['nom'], 'prenom': d['prenom'], 'classe': d['classe'],
            'nb': len(d['lettres']), 'dominante': dom,
            'dom_t1': dom_t1, 'dom_t2': dom_t2,
            'evolution': (
                'up' if dom_t1 and dom_t2 and (
                    (dom_t1 == 'C' and dom_t2 in ('A', 'B')) or (dom_t1 == 'B' and dom_t2 == 'A')
                ) else
                'down' if dom_t1 and dom_t2 and (
                    (dom_t1 == 'A' and dom_t2 in ('B', 'C')) or (dom_t1 == 'B' and dom_t2 == 'C')
                ) else 'flat'
            ) if dom_t1 and dom_t2 else None,
        })
    eleves_stats.sort(key=lambda x: (x['nom'], x['prenom']))

    conn.close()
    return render_template_string(
        ANALYSE_MATERNELLE_HTML,
        toutes_les_classes=toutes_les_classes, gf_classe_id=gf_classe_id, trimestre_f=trimestre_f,
        kpi=kpi, matieres_stats=matieres_stats, classes_stats=classes_stats, eleves_stats=eleves_stats,
        notif_count=get_notif_count(),
    )


@app.route('/analyse-notes')
@login_required
@role_required('admin')
def analyse_notes():
    conn = get_db()

    cycle = request.args.get('cycle', 'Primaire')
    _set_sys_analyse(cycle, conn)
    trimestre_f = request.args.get('trimestre', '')
    gf_classe_id = request.args.get('gf_classe_id', '')
    gf_matiere_nom = request.args.get('gf_matiere_nom', '')
    gf_ens_id = request.args.get('gf_ens_id', '')
    gf_annee = request.args.get('gf_annee', '')
    active_tab = request.args.get('tab', 'dashboard')
    eleve_sel_id = request.args.get('eleve_sel_id', '')

    toutes_les_classes = conn.execute(
        "SELECT id, nom FROM classes WHERE cycle=? OR (cycle IS NULL AND ?='Primaire') ORDER BY nom",
        (cycle, cycle)
    ).fetchall()

    # 🆕 Le cycle Maternelle est noté par lettres (A/B/C) et non sur 20 : l'analyse générale
    # (moyennes pondérées, coefficients, classement /20...) n'a pas de sens ici, donc on bascule
    # sur une analyse dédiée, indépendante du moteur numérique utilisé pour Primaire/Collège.
    if _sa() == 'lettres':
        return _analyse_notes_maternelle(conn, toutes_les_classes, gf_classe_id, trimestre_f, cycle)

    toutes_les_matieres_noms = conn.execute("SELECT DISTINCT nom FROM matieres ORDER BY nom").fetchall()
    tous_les_enseignants = conn.execute(
        "SELECT id, prenom||' '||nom as nom FROM users WHERE role='enseignant' ORDER BY nom"
    ).fetchall()
    annees_dispo = conn.execute(
        "SELECT DISTINCT strftime('%Y', date_saisie) as a FROM notes WHERE date_saisie IS NOT NULL ORDER BY a"
    ).fetchall()
    tous_les_eleves = conn.execute(
        "SELECT e.id, e.prenom||' '||e.nom as nom, c.nom as classe FROM eleves e JOIN classes c ON e.classe_id=c.id "
        "WHERE (c.cycle=? OR (c.cycle IS NULL AND ?='Primaire')) ORDER BY e.nom", (cycle, cycle)
    ).fetchall()

    data = _dataset_analyse(conn, cycle, trimestre_f, gf_classe_id, gf_matiere_nom, gf_ens_id, gf_annee)
    # 🏅 Module Qualité ISO : objectifs du cycle, puis robot enrichi de l'analyse d'écart
    objectifs_qualite = _get_objectifs_qualite(conn, cycle)
    # 🤖 Robot d'analyse : compte rendu + solutions générés à partir du dataset ci-dessus
    robot = _robot_analyse(data, cycle, objectifs=objectifs_qualite)
    # 📈 Historisation du score (1 point/jour/cycle) — preuve de suivi dans le temps
    _save_score_snapshot(conn, cycle, robot, data.get('kpi') or {})
    historique_qualite = _get_score_historique(conn, cycle)
    actions_qualite = _get_actions_qualite(conn, cycle)

    # ---- Détail des notes élève par élève pour la matière filtrée (onglet Par matière) ----
    detail_matiere = None
    if gf_matiere_nom:
        detail_matiere = conn.execute(
            "SELECT e.prenom||' '||e.nom as eleve, c.nom as classe, n.note, n.trimestre "
            "FROM notes n JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
            "JOIN matieres m ON n.matiere_id=m.id "
            "WHERE m.nom=? AND (c.cycle=? OR (c.cycle IS NULL AND ?='Primaire')) "
            "ORDER BY n.note DESC", (gf_matiere_nom, cycle, cycle)).fetchall()
        detail_matiere = _rows(detail_matiere)

    # ---- Détail élève sélectionné (fiche 360° — analyse individuelle intelligente) ----
    eleve_detail = None
    if eleve_sel_id:
        einfo = conn.execute(
            "SELECT e.*, c.nom as classe, c.niveau as niveau FROM eleves e JOIN classes c ON e.classe_id=c.id WHERE e.id=?",
            (eleve_sel_id,)).fetchone()
        if einfo:
            # Moyenne par matière + enseignant(s) associé(s), pondérée par sous-matière, pour
            # savoir QUI enseigne QUOI à cet élève.
            par_matiere = conn.execute(
                "SELECT y.nom as nom, SUM(y.note*y.coef_sm)*1.0/NULLIF(SUM(y.coef_sm),0) as avg, "
                "COUNT(*) as nb_notes, GROUP_CONCAT(DISTINCT y.prof) as profs "
                "FROM ( "
                "    SELECT m.nom as nom, n.note, COALESCE(sm.coefficient,1) as coef_sm, "
                "           COALESCE(u.prenom||' '||u.nom, 'Enseignant non défini') as prof "
                "    FROM notes n JOIN matieres m ON n.matiere_id=m.id LEFT JOIN users u ON n.enseignant_id=u.id "
                "    LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id "
                "    WHERE n.eleve_id=? "
                ") y GROUP BY y.nom ORDER BY y.nom", (eleve_sel_id,)).fetchall()
            par_matiere = _rows(par_matiere)

            # 🆕 Ref matière = moyenne GÉNÉRALE pondérée (sous-matière puis matière) des élèves
            # du même NIVEAU (ex: CP) — une seule valeur de référence, utilisée pour chaque
            # ligne de la table "Détail par matière".
            eleve_niveau = einfo['niveau'] if 'niveau' in einfo.keys() else None
            if eleve_niveau:
                moy_par_eleve_niveau = _eleves_moyennes_ponderees(conn, "c.niveau=?", (eleve_niveau,))
            else:
                moy_par_eleve_niveau = _eleves_moyennes_ponderees(
                    conn, "(c.cycle=? OR (c.cycle IS NULL AND ?='Primaire'))", (cycle, cycle))
            ref_niveau = (round(sum(moy_par_eleve_niveau.values()) / len(moy_par_eleve_niveau), 2)
                          if moy_par_eleve_niveau else None)
            for pm in par_matiere:
                pm['ref_etablissement'] = round(ref_niveau, 2) if ref_niveau is not None else None
                pm['ecart_etablissement'] = round((pm['avg'] or 0) - ref_niveau, 2) if ref_niveau is not None else None

            point_fort = max(par_matiere, key=lambda r: r['avg'] or 0) if par_matiere else None
            point_faible = min(par_matiere, key=lambda r: r['avg'] or 0) if par_matiere else None

            # 🆕 Moyenne par trimestre pondérée (sous-matière puis matière) pour cet élève
            par_trimestre = conn.execute("""
                SELECT y.trimestre as trimestre,
                       SUM(y.matiere_moy * y.coef_matiere) * 1.0 / NULLIF(SUM(y.coef_matiere), 0) as avg
                FROM (
                    SELECT trimestre, matiere_id, coef_matiere,
                           SUM(note * coef_sm) * 1.0 / NULLIF(SUM(coef_sm), 0) as matiere_moy
                    FROM (
                        SELECT n.trimestre, n.matiere_id, m.coefficient as coef_matiere, n.note,
                               COALESCE(sm.coefficient, 1) as coef_sm
                        FROM notes n JOIN matieres m ON m.id = n.matiere_id
                        LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id
                        WHERE n.eleve_id=?
                    ) raw GROUP BY trimestre, matiere_id, coef_matiere
                ) y GROUP BY y.trimestre ORDER BY y.trimestre
            """, (eleve_sel_id,)).fetchall()

            # Historique détaillé : matière × trimestre × enseignant (pour voir l'évolution
            # précise avec chaque professeur, pas juste une moyenne générale par trimestre)
            # 🆕 Pondéré par le coefficient des sous-matières.
            historique = conn.execute(
                "SELECT y.matiere as matiere, y.enseignant as enseignant, y.trimestre as trimestre, "
                "SUM(y.note*y.coef_sm)*1.0/NULLIF(SUM(y.coef_sm),0) as avg, COUNT(*) as nb_notes "
                "FROM ( "
                "    SELECT m.nom as matiere, COALESCE(u.prenom||' '||u.nom, 'Enseignant non défini') as enseignant, n.trimestre, n.note, "
                "           COALESCE(sm.coefficient,1) as coef_sm "
                "    FROM notes n JOIN matieres m ON n.matiere_id=m.id LEFT JOIN users u ON n.enseignant_id=u.id "
                "    LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id "
                "    WHERE n.eleve_id=? "
                ") y GROUP BY y.matiere, y.enseignant, y.trimestre ORDER BY y.matiere, y.trimestre",
                (eleve_sel_id,)).fetchall()
            historique = _rows(historique)
            # Alerte de tendance : matière en baisse entre les 2 derniers trimestres connus
            hist_par_matiere = {}
            for h in historique:
                hist_par_matiere.setdefault(h['matiere'], {})[h['trimestre']] = h['avg']
            tendances = []
            for mat, tri in hist_par_matiere.items():
                trims = sorted(tri.keys())
                if len(trims) >= 2:
                    delta = tri[trims[-1]] - tri[trims[-2]]
                    tendances.append({'matiere': mat, 'delta': round(delta, 2),
                                      'sens': 'hausse' if delta > 0.3 else 'baisse' if delta < -0.3 else 'stable'})

            nb_abs_row = conn.execute(
                "SELECT COUNT(*) as total, COALESCE(SUM(justifiee),0) as justif FROM absences WHERE eleve_id=?",
                (eleve_sel_id,)).fetchone()
            # 🔧 FIX SYNCHRO : la moyenne générale doit utiliser les coefficients des matières
            # (ceux définis sur la page Classe), pas une simple AVG(note) qui les ignorait —
            # sinon elle ne bougeait jamais quand on changeait un coefficient sur la classe.
            # 🆕 Elle tient aussi compte du coefficient des sous-matières (si définies) au sein
            # de chaque matière, avant de pondérer par le coefficient de la matière elle-même.
            # Même formule que sur la fiche élève / bulletin : moyenne pondérée par trimestre,
            # puis moyenne des trimestres réellement notés.
            notes_pond_rows = conn.execute(
                "SELECT n.trimestre, n.note, n.matiere_id, m.nom as matiere, m.coefficient, "
                "n.sous_matiere_id, sm.coefficient as sm_coefficient "
                "FROM notes n JOIN matieres m ON n.matiere_id=m.id "
                "LEFT JOIN sous_matieres sm ON n.sous_matiere_id = sm.id "
                "WHERE n.eleve_id=?", (eleve_sel_id,)).fetchall()
            notes_par_tri = {}
            for r in notes_pond_rows:
                notes_par_tri.setdefault(r['trimestre'], []).append(r)
            moyennes_tri_valides = []
            for rows in notes_par_tri.values():
                moy_tri, _ = _moyenne_ponderee_matieres(rows)
                moyennes_tri_valides.append(moy_tri)
            moyenne_generale_pond = (
                round(sum(moyennes_tri_valides) / len(moyennes_tri_valides), 2)
                if moyennes_tri_valides else None
            )
            # 🆕 STYLE POWERSCHOOL : rang et percentile de l'élève dans sa classe et son niveau,
            # calculés à partir du même classement_eleves déjà utilisé pour le tableau général
            # (donc toujours cohérent avec les filtres actifs — trimestre, année, cycle...).
            classe_nom_sel = einfo['classe']
            niveau_sel = einfo['niveau'] if 'niveau' in einfo.keys() else None
            classe_group = [r for r in data['classement_eleves'] if r['classe'] == classe_nom_sel]
            niveau_group = ([r for r in data['classement_eleves'] if r['niveau'] == niveau_sel]
                             if niveau_sel else classe_group)
            rang_classe = next((i for i, r in enumerate(classe_group, 1) if str(r['id']) == str(eleve_sel_id)), None)
            rang_niveau = next((i for i, r in enumerate(niveau_group, 1) if str(r['id']) == str(eleve_sel_id)), None)
            effectif_classe = len(classe_group)
            effectif_niveau = len(niveau_group)
            percentile_niveau = (
                round((1 - (rang_niveau - 1) / effectif_niveau) * 100)
                if rang_niveau and effectif_niveau > 1 else (100 if rang_niveau else None)
            )
            # Valeur directement affichable "fait partie du Top X% du niveau"
            top_pct_niveau = (
                max(1, round(rang_niveau / effectif_niveau * 100))
                if rang_niveau and effectif_niveau else None
            )
            # 🆕 Badge de profil (Critique/Fragile/Stable/Leader/Champion) + matière qui le justifie
            matieres_badge = [(pm['nom'], pm['avg']) for pm in par_matiere]
            profil_badge = _badge_profil(moyenne_generale_pond, matieres_badge)

            eleve_detail = {
                'info': dict(einfo),
                'par_matiere': par_matiere,
                'par_trimestre': _rows(par_trimestre),
                'historique': historique,
                'tendances': tendances,
                'point_fort': point_fort,
                'point_faible': point_faible,
                'nb_abs': nb_abs_row['total'] if nb_abs_row else 0,
                'nb_abs_justif': nb_abs_row['justif'] if nb_abs_row else 0,
                'moyenne_generale': moyenne_generale_pond,
                'rang_classe': rang_classe, 'effectif_classe': effectif_classe,
                'rang_niveau': rang_niveau, 'effectif_niveau': effectif_niveau,
                'percentile_niveau': percentile_niveau, 'top_pct_niveau': top_pct_niveau,
                'profil_badge': profil_badge,
            }

    conn.close()

    return render_template_string(
        ANALYSE_HTML,
        cycle=cycle, trimestre_f=trimestre_f, gf_classe_id=gf_classe_id, gf_matiere_nom=gf_matiere_nom,
        gf_ens_id=gf_ens_id, gf_annee=gf_annee, active_tab=active_tab, eleve_sel_id=eleve_sel_id,
        toutes_les_classes=toutes_les_classes, toutes_les_matieres_noms=toutes_les_matieres_noms,
        tous_les_enseignants=tous_les_enseignants, annees_dispo=annees_dispo, tous_les_eleves=tous_les_eleves,
        eleve_detail=eleve_detail, detail_matiere=detail_matiere,
        notif_count=get_notif_count(), robot=robot,
        objectifs_qualite=objectifs_qualite, historique_qualite=historique_qualite, actions_qualite=actions_qualite,
        **data
    )


