def _redirect_qualite(cycle):
    return redirect(url_for('analyse_notes', cycle=cycle, tab='qualite'))


@app.route('/analyse-notes/qualite/objectifs', methods=['POST'])
@login_required
@role_required('admin')
def qualite_objectifs_save():
    conn = get_db()
    cycle = request.form.get('cycle', 'Primaire')
    try:
        obj_moyenne = float(request.form.get('objectif_moyenne') or (6 if get_systeme_notes(cycle, conn) == '10' else 12))
        if get_systeme_notes(cycle, conn) == '10':
            obj_moyenne = obj_moyenne * 2  # stocké en interne sur 20
        obj_taux = float(request.form.get('objectif_taux_reussite') or 80)
        obj_score = float(request.form.get('objectif_score') or 70)
    except ValueError:
        flash("Merci de saisir des valeurs numériques valides pour les objectifs.", 'error')
        conn.close()
        return _redirect_qualite(cycle)
    conn.execute(
        "INSERT INTO qualite_objectifs (cycle, objectif_moyenne, objectif_taux_reussite, objectif_score, maj_le) "
        "VALUES (?,?,?,?,CURRENT_TIMESTAMP) "
        "ON CONFLICT(cycle) DO UPDATE SET objectif_moyenne=excluded.objectif_moyenne, "
        "objectif_taux_reussite=excluded.objectif_taux_reussite, objectif_score=excluded.objectif_score, "
        "maj_le=CURRENT_TIMESTAMP",
        (cycle, obj_moyenne, obj_taux, obj_score)
    )
    conn.commit()
    log_action(conn, 'modification', 'qualite_objectifs', None, f'Objectifs qualité {cycle} mis à jour')
    conn.close()
    flash('Objectifs qualité mis à jour avec succès.', 'success')
    return _redirect_qualite(cycle)


