@app.route('/export/analyse/excel')
@login_required
@role_required('admin')
def export_analyse_excel():
    try:
        import openpyxl
        from openpyxl.styles import Font, PatternFill
        conn = get_db()
        cycle, trimestre_f, gf_classe_id, gf_matiere_nom, gf_ens_id, gf_annee = _analyse_filters_from_request()
        d = _dataset_analyse(conn, cycle, trimestre_f, gf_classe_id, gf_matiere_nom, gf_ens_id, gf_annee)
        conn.close()

        wb = openpyxl.Workbook()
        header_fill = PatternFill(start_color='1a3a5c', end_color='1a3a5c', fill_type='solid')
        header_font = Font(color='FFFFFF', bold=True)

        def write_sheet(ws, headers, rows):
            for col, h in enumerate(headers, 1):
                cell = ws.cell(1, col, h)
                cell.fill = header_fill;
                cell.font = header_font
            for r_i, row in enumerate(rows, 2):
                for c_i, val in enumerate(row, 1):
                    ws.cell(r_i, c_i, val if val is not None else '')

        ws1 = wb.active;
        ws1.title = 'KPI'
        write_sheet(ws1, ['Indicateur', 'Valeur'], [
            ['Cycle', cycle], ['Moyenne générale ' + _se(), round(_cv(d['kpi']['moyenne_generale']), 2)],
            ['Taux de réussite (%)', round(d['kpi']['taux_reussite'], 1)],
            ['Taux d\'échec (%)', round(d['kpi']['taux_echec'], 1)],
            ['Total élèves', d['kpi']['nb_eleves']], ['Total classes', d['kpi']['nb_classes']],
            ['Total enseignants', d['kpi']['nb_enseignants']],
            ['Élèves excellents (>=16)', d['kpi']['nb_excellents']],
            ['Élèves en difficulté (<10)', d['kpi']['nb_difficulte']],
            ['Total notes saisies', d['kpi']['total_notes']],
        ])

        ws2 = wb.create_sheet('Classes')
        write_sheet(ws2, ['Classe', 'Niveau', 'Moyenne ' + _se(), 'Effectif', 'Taux réussite %', 'Taux échec %'],
                    [[c['nom'], c['niveau'], round(_cv(c['avg'] or 0), 2), c['nb_eleves'],
                      round(c['taux_reussite'] or 0, 1), round(c['taux_echec'] or 0, 1)] for c in d['moy_classes']])

        ws3 = wb.create_sheet('Matières')
        write_sheet(ws3, ['Matière', 'Moyenne ' + _se(), 'Min', 'Max', 'Notes', 'Taux réussite %'],
                    [[m['nom'], round(_cv(m['avg'] or 0), 2), round(_cv(m['mn'] or 0), 2), round(_cv(m['mx'] or 0), 2),
                      m['cnt'], round(m['taux_reussite'] or 0, 1)] for m in d['moy_matieres']])

        ws4 = wb.create_sheet('Enseignants')
        write_sheet(ws4, ['Enseignant', 'Moyenne accordée ' + _se(), 'Notes saisies', 'Taux réussite %'],
                    [[t['nom'], round(_cv(t['avg'] or 0), 2), t['total_notes'], round(t['taux_reussite'] or 0, 1)]
                     for t in d['stats_enseignants']])

        ws5 = wb.create_sheet('Classement élèves')
        write_sheet(ws5, ['Rang', 'Élève', 'Classe', 'Moyenne ' + _se(), 'Taux réussite %', 'Absences'],
                    [[e['rang'], e['nom'], e['classe'], round(_cv(e['moyenne'] or 0), 2),
                      round(e['taux_reussite'] or 0, 1), e['nb_abs']] for e in d['classement_eleves']])

        buf = io.BytesIO();
        wb.save(buf);
        buf.seek(0)
        return send_file(buf, as_attachment=True, download_name=f'analyse_notes_{cycle}.xlsx',
                         mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
    except Exception as ex:
        flash(f'Erreur export Excel: {ex}', 'error')
        return redirect(url_for('analyse_notes'))


