def _pdf_letterhead(elems, doc_type, subtitle=None, accent_hex='#2563EB'):
    """🆕 En-tête premium partagé par TOUS les documents PDF de l'application (bulletins de notes,
    reçus, fiches de paie, rapports...) : bandeau coloré avec le nom de l'école + le type de
    document, aligné sur la couleur --primary du design system du site (au lieu de l'ancien
    bleu marine codé en dur). `accent_hex` permet de nuancer par type de document tout en
    gardant une identité visuelle cohérente à l'échelle de l'app."""
    from reportlab.lib import colors
    from reportlab.platypus import Paragraph, Spacer, Table, TableStyle
    from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
    from reportlab.lib.units import cm
    styles = getSampleStyleSheet()
    header_table = Table([[
        Paragraph("🏫 <b>" + _nom_ecole_html() + "</b>", ParagraphStyle(
            'SchoolName', fontSize=15, textColor=colors.white, fontName='Helvetica-Bold', leading=18)),
        Paragraph(doc_type.upper(), ParagraphStyle(
            'DocType', fontSize=10.5, textColor=colors.white, alignment=2, fontName='Helvetica-Bold', leading=13)),
    ]], colWidths=[11 * cm, 6 * cm])
    header_table.setStyle(TableStyle([
        ('BACKGROUND', (0, 0), (-1, -1), colors.HexColor(accent_hex)),
        ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
        ('LEFTPADDING', (0, 0), (0, 0), 16), ('RIGHTPADDING', (-1, 0), (-1, 0), 16),
        ('TOPPADDING', (0, 0), (-1, -1), 14), ('BOTTOMPADDING', (0, 0), (-1, -1), 14),
    ]))
    elems.append(header_table)
    elems.append(Spacer(1, 0.45 * cm))
    if subtitle:
        elems.append(Paragraph(subtitle, ParagraphStyle(
            'Sub', parent=styles['Normal'], fontSize=10.5, textColor=colors.HexColor('#475569'))))
        elems.append(Spacer(1, 0.35 * cm))


# 🆕 Variante COMPACTE de l'en-tête ci-dessus, réservée aux PDF d'emploi du temps (classe /
# enseignant / élève, tous en paysage). Auparavant elle affichait un bandeau bleu ("petite
# sous-bannière") avec le nom de l'école et le type de document en blanc sur fond de couleur.
# À la demande, ce bandeau coloré a été supprimé : on ne garde que le nom de l'école (en
# texte simple, uniquement si aucune bannière-image n'est déjà affichée juste au-dessus) et
# le sous-titre (classe / enseignant / élève + nombre de créneaux), sans fond coloré.
def _pdf_letterhead_compact(elems, doc_type, subtitle=None, accent_hex='#2563EB', show_school_name=True):
    from reportlab.lib import colors
    from reportlab.platypus import Paragraph, Spacer
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib.units import cm
    if show_school_name:
        elems.append(Paragraph("🏫 <b>" + _nom_ecole_html() + "</b>", ParagraphStyle(
            'SchoolNameC', fontSize=11, textColor=colors.HexColor('#0F172A'), fontName='Helvetica-Bold', leading=13)))
        elems.append(Spacer(1, 0.1 * cm))
    if subtitle:
        elems.append(Paragraph(subtitle, ParagraphStyle(
            'SubC', fontSize=9, textColor=colors.HexColor('#475569'), fontName='Helvetica-Bold')))
        elems.append(Spacer(1, 0.22 * cm))


# 🆕 ─────────────────────────────────────────────
# SUPPORT DE L'ARABE DANS LES PDF (reportlab)
# ─────────────────────────────────────────────
# Les polices intégrées de reportlab (Helvetica, Helvetica-Bold...) ne contiennent AUCUN
# glyphe arabe : tout texte arabe (matières, sous-matières, noms saisis en arabe...) était
# donc affiché sous forme de petits carrés noirs ("tofu") à l'impression/export PDF. En plus
# de ça, même avec une police qui supporte l'arabe, il faut "reshaper" le texte (relier les
# lettres entre elles selon leur position dans le mot, comme le fait un traitement de texte)
# et le réordonner pour un affichage de droite à gauche : reportlab n'a aucun moteur RTL
# intégré, il affiche les caractères Unicode tels quels, dans l'ordre du texte source.
_ARABIC_FONTS_READY = {'done': False, 'ok': False}
_ARABIC_CHAR_RE = re.compile(
    r'[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF]+')
# Séparateurs "neutres" (espace, virgule, tiret...) : quand l'un d'eux se trouve ENTRE deux
# portions arabes (ex: la virgule dans "منظمة, مطالعة", ou l'espace dans "بشرى سماحي"), on
# l'absorbe dans le bloc arabe avant reshape/bidi, sinon l'algorithme RTL ne verrait que des
# mots isolés et ne pourrait pas remettre les mots dans le bon ordre de lecture (droite à
# gauche). Un séparateur entre du FRANÇAIS et de l'arabe (ex: " — " dans "ARABE — ...") n'est
# lui jamais absorbé, il reste toujours hors du bloc arabe.
_ARABIC_NEUTRAL_SEP_RE = re.compile(r'^[\s,،\-–—:/]+$')


def _ensure_arabic_pdf_fonts():
    """Enregistre une bonne fois pour toutes (au premier appel) les polices Regular/Bold
    "Noto Naskh Arabic" auprès de reportlab, si les fichiers .ttf sont présents dans le
    dossier fonts/ à côté de app.py. Renvoie True si les polices sont disponibles."""
    if _ARABIC_FONTS_READY['done']:
        return _ARABIC_FONTS_READY['ok']
    _ARABIC_FONTS_READY['done'] = True
    try:
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.ttfonts import TTFont
        regular_path = os.path.join(PDF_FONTS_FOLDER, 'NotoNaskhArabic-Regular.ttf')
        bold_path = os.path.join(PDF_FONTS_FOLDER, 'NotoNaskhArabic-Bold.ttf')
        if not (os.path.exists(regular_path) and os.path.exists(bold_path)):
            return False
        pdfmetrics.registerFont(TTFont('ArabicPDF', regular_path))
        pdfmetrics.registerFont(TTFont('ArabicPDF-Bold', bold_path))
        _ARABIC_FONTS_READY['ok'] = True
        return True
    except Exception:
        return False


def _pdf_arabic_safe(text, bold=False):
    """Prépare une chaîne (pouvant mélanger français/arabe, ex: 'ARABE — مطالعة, منظمة')
    pour un affichage correct dans un reportlab Paragraph : chaque portion arabe est
    reformée (lettres reliées) et réordonnée de droite à gauche via arabic_reshaper +
    python-bidi, puis encadrée d'une balise <font name="..."> pointant vers la police
    Noto Naskh Arabic enregistrée. Les portions non-arabes (français, chiffres, ponctuation)
    sont laissées telles quelles, dans l'ordre d'origine. Si les portions arabe ne sont pas
    trouvées, ou si les librairies de reshaping / la police ne sont pas disponibles, renvoie
    le texte échappé tel quel (comportement inchangé, pas pire qu'avant)."""
    if not text:
        return ''
    text = str(text)
    if not _ARABIC_CHAR_RE.search(text):
        return html.escape(text)

    fonts_ok = _ensure_arabic_pdf_fonts()
    arabic_font = 'ArabicPDF-Bold' if bold else 'ArabicPDF'

    try:
        import arabic_reshaper
        from bidi.algorithm import get_display
        can_shape = True
    except Exception:
        can_shape = False

    # 1) Découpage en blocs "ar" (arabe) / "autre" (français, chiffres, ponctuation...).
    runs = []
    last = 0
    for m in _ARABIC_CHAR_RE.finditer(text):
        if m.start() > last:
            runs.append(('autre', text[last:m.start()]))
        runs.append(('ar', m.group(0)))
        last = m.end()
    if last < len(text):
        runs.append(('autre', text[last:]))

    # 2) Fusion : un séparateur neutre coincé entre deux blocs arabes rejoint le bloc arabe
    # (nécessaire pour que le reshape/bidi réordonne correctement plusieurs mots arabes,
    # ex: un nom complet ou une liste de sous-matières séparées par des virgules).
    changed = True
    while changed:
        changed = False
        for i in range(1, len(runs) - 1):
            typ, val = runs[i]
            if typ == 'autre' and _ARABIC_NEUTRAL_SEP_RE.match(val) \
                    and runs[i - 1][0] == 'ar' and runs[i + 1][0] == 'ar':
                fusion = runs[i - 1][1] + val + runs[i + 1][1]
                runs = runs[:i - 1] + [('ar', fusion)] + runs[i + 2:]
                changed = True
                break

    # 3) Reshape + bidi sur chaque bloc arabe (mot ou groupe de mots), le reste échappé tel quel.
    out = []
    for typ, val in runs:
        if typ == 'ar':
            if can_shape:
                try:
                    val = get_display(arabic_reshaper.reshape(val))
                except Exception:
                    pass
            val = html.escape(val)
            if fonts_ok:
                val = f'<font name="{arabic_font}">{val}</font>'
            out.append(val)
        else:
            out.append(html.escape(val))
    return ''.join(out)


def _pdf_footer(canvas, doc):
    """🆕 Pied de page premium, appliqué automatiquement sur chaque page de chaque document
    (via onFirstPage/onLaterPages) : fine ligne de séparation, date/heure de génération à
    gauche, numéro de page à droite — évite de répéter ce code dans chaque route d'export."""
    from reportlab.lib import colors
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.units import cm
    canvas.saveState()
    canvas.setStrokeColor(colors.HexColor('#E5E7EB'))
    canvas.setLineWidth(0.6)
    canvas.line(1.5 * cm, 1.35 * cm, A4[0] - 1.5 * cm, 1.35 * cm)
    canvas.setFont('Helvetica', 8)
    canvas.setFillColor(colors.HexColor('#94A3B8'))
    canvas.drawString(1.5 * cm, 0.95 * cm, f"Généré le {datetime.datetime.now().strftime('%d/%m/%Y à %H:%M')}")
    canvas.drawRightString(A4[0] - 1.5 * cm, 0.95 * cm, f"Page {canvas.getPageNumber()}")
    canvas.restoreState()


def _pdf_status_pill(text, ok=True):
    """🆕 Petit badge coloré façon "pilule" (vert/rouge) pour mettre en valeur un statut
    (PAYÉ / NON PAYÉ...) dans les tableaux PDF — équivalent des badges .badge-green/.badge-red
    du site, pour garder la même grammaire visuelle entre l'app et les documents téléchargés."""
    from reportlab.platypus import Paragraph
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib import colors
    bg = '#DCFCE7' if ok else '#FEE2E2'
    fg = '#15803D' if ok else '#B91C1C'
    return Paragraph(
        f'<para alignment="center"><font color="{fg}"><b>{text}</b></font></para>',
        ParagraphStyle('Pill', backColor=colors.HexColor(bg), borderPadding=(4, 8, 4, 8)))


def _pdf_table_report(title, subtitle, headers, rows, col_widths, filename):
    from reportlab.lib.pagesizes import A4
    from reportlab.lib import colors
    from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer
    from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
    from reportlab.lib.units import cm
    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4, topMargin=1.5 * cm, bottomMargin=2 * cm)
    styles = getSampleStyleSheet()
    # 🔄 En-tête premium partagé (au lieu du simple Paragraph bleu marine précédent)
    elems = []
    _pdf_letterhead(elems, title, subtitle, accent_hex='#2563EB')
    table_data = [headers] + rows
    t = Table(table_data, colWidths=col_widths, repeatRows=1)
    t.setStyle(TableStyle([
        ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#2563EB')),
        ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
        ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
        ('ROWBACKGROUNDS', (0, 1), (-1, -1), [colors.HexColor('#F8FAFC'), colors.white]),
        ('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#E5E7EB')),
        ('FONTSIZE', (0, 0), (-1, -1), 9),
        ('TOPPADDING', (0, 0), (-1, -1), 6), ('BOTTOMPADDING', (0, 0), (-1, -1), 6),
    ]))
    elems.append(t)
    # 🔄 Le "Généré le..." est désormais dans le pied de page (_pdf_footer), plus besoin ici
    doc.build(elems, onFirstPage=_pdf_footer, onLaterPages=_pdf_footer)
    buf.seek(0)
    return send_file(buf, as_attachment=True, download_name=filename, mimetype='application/pdf')


