@app.route('/export/analyse/rapport-classe/<int:classe_id>/pdf')
@login_required
@role_required('admin')
def export_rapport_classe_pdf(classe_id):
    try:
        conn = get_db()
        classe = conn.execute("SELECT * FROM classes WHERE id=?", (classe_id,)).fetchone()
        if not classe:
            flash('Classe introuvable.', 'error');
            return redirect(url_for('analyse_notes'))
        # 🆕 Moyenne pondérée (sous-matière puis matière) par élève, cohérente avec le reste de l'app
        eleves = conn.execute("""
            SELECT e.prenom||' '||e.nom as nom, y.moyenne as moyenne, y.taux as taux
            FROM eleves e
            LEFT JOIN (
                SELECT eleve_id,
                       SUM(matiere_moy * coef_matiere) * 1.0 / NULLIF(SUM(coef_matiere), 0) as moyenne,
                       SUM(nb_reussite) * 100.0 / NULLIF(SUM(nb_notes), 0) as taux
                FROM (
                    SELECT eleve_id, matiere_id, coef_matiere,
                           SUM(note * coef_sm) * 1.0 / NULLIF(SUM(coef_sm), 0) as matiere_moy,
                           COUNT(*) as nb_notes,
                           SUM(CASE WHEN note>=10 THEN 1 ELSE 0 END) as nb_reussite
                    FROM (
                        SELECT n.eleve_id, n.matiere_id, m.coefficient as coef_matiere, n.note,
                               COALESCE(sm.coefficient, 1) as coef_sm
                        FROM notes n JOIN matieres m ON m.id = n.matiere_id
                        LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id
                        WHERE n.eleve_id IN (SELECT id FROM eleves WHERE classe_id=?)
                    ) raw GROUP BY eleve_id, matiere_id, coef_matiere
                ) y2 GROUP BY eleve_id
            ) y ON y.eleve_id = e.id
            WHERE e.classe_id=?
            ORDER BY moyenne DESC
        """, (classe_id, classe_id)).fetchall()
        eleves = [dict(r) for r in eleves if r['moyenne'] is not None]
        _set_sys_analyse(classe['cycle'] or 'Primaire', conn)
        conn.close()
        moy_classe = (sum(e['moyenne'] or 0 for e in eleves) / len(eleves)) if eleves else 0
        subtitle = f"Classe {classe['nom']} ({classe['niveau']}) — Moyenne de classe: {_sn(moy_classe, 2)}{_se()} — {len(eleves)} élèves"
        headers = ['Rang', 'Élève', 'Moyenne ' + _se(), 'Taux de réussite']
        rows = [[str(i), e['nom'], _sn(e['moyenne'] or 0, 2), f"{e['taux'] or 0:.1f}%"]
                for i, e in enumerate(eleves, 1)]
        from reportlab.lib.units import cm
        return _pdf_table_report(f"Rapport de Classe — {classe['nom']}", subtitle, headers, rows,
                                 [2 * cm, 7 * cm, 3 * cm, 4 * cm], f'rapport_classe_{classe["nom"]}.pdf')
    except Exception as ex:
        flash(f'Erreur génération PDF: {ex}', 'error')
        return redirect(url_for('analyse_notes'))


@app.route('/export/analyse/rapport-matiere/<path:matiere_nom>/pdf')
@login_required
@role_required('admin')
def export_rapport_matiere_pdf(matiere_nom):
    try:
        conn = get_db()
        # 🆕 Moyenne par classe pour cette matière, pondérée par le coefficient des sous-matières
        rows = conn.execute(
            "SELECT y.classe as classe, "
            "SUM(y.note*y.coef_sm)*1.0/NULLIF(SUM(y.coef_sm),0) as avg, COUNT(*) as cnt, "
            "SUM(CASE WHEN y.note>=10 THEN 1 ELSE 0 END)*100.0/COUNT(*) as taux "
            "FROM ( "
            "    SELECT c.nom as classe, n.note, COALESCE(sm.coefficient,1) as coef_sm "
            "    FROM notes n JOIN matieres m ON n.matiere_id=m.id "
            "    JOIN eleves e ON n.eleve_id=e.id JOIN classes c ON e.classe_id=c.id "
            "    LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id "
            "    WHERE m.nom=? "
            ") y GROUP BY y.classe ORDER BY avg DESC", (matiere_nom,)).fetchall()
        conn.close()
        if not rows:
            flash('Aucune donnée pour cette matière.', 'error');
            return redirect(url_for('analyse_notes'))
        moy_gen = sum((r['avg'] or 0) * r['cnt'] for r in rows) / sum(r['cnt'] for r in rows) if rows else 0
        subtitle = f"Matière {matiere_nom} — Moyenne générale: {moy_gen:.2f}/20"
        headers = ['Classe', 'Moyenne /20', 'Notes saisies', 'Taux de réussite']
        table_rows = [[r['classe'], f"{r['avg'] or 0:.2f}", str(r['cnt']), f"{r['taux'] or 0:.1f}%"] for r in rows]
        from reportlab.lib.units import cm
        return _pdf_table_report(f"Rapport de Matière — {matiere_nom}", subtitle, headers, table_rows,
                                 [4 * cm, 3.5 * cm, 3.5 * cm, 4 * cm], f'rapport_matiere_{matiere_nom}.pdf')
    except Exception as ex:
        flash(f'Erreur génération PDF: {ex}', 'error')
        return redirect(url_for('analyse_notes'))


