@app.route('/export/paiements/excel')
@login_required
@role_required('admin')
def export_paiements_excel():
    try:
        import openpyxl
        conn = get_db()

        # --- Reprise des mêmes filtres avancés que la page /paiements ---
        # pour exporter exactement ce que l'admin est en train de consulter.
        cycle_filter = request.args.get('cycle', 'Global')

        # 🔒 AGENT ADMIN : ne doit pas pouvoir contourner l'interface (qui bloque déjà l'onglet
        # "Enseignants") en forgeant directement l'URL d'export Excel.
        if session.get('role') == 'agent_admin' and cycle_filter == 'Enseignants' and not peut_voir('paiements_enseignants'):
            flash('Accès non autorisé.', 'error')
            return redirect(url_for('paiements'))

        status_filter = request.args.get('statut', '')
        mois_filter = request.args.get('mois', '')
        search_filter = request.args.get('q', '').strip()
        classe_filter = request.args.get('classe_id', '')
        categorie_filter = request.args.get('categorie_filter', '')
        transport_filter = request.args.get('transport_filter', '')
        date_debut = request.args.get('date_debut', '')
        date_fin = request.args.get('date_fin', '')
        # 🆕 Mêmes filtres "date de paiement reçu" que sur la page /paiements (voir plus haut).
        recu_debut = request.args.get('recu_debut', '').strip()
        recu_fin = request.args.get('recu_fin', '').strip()

        def _parse_montant(val):
            try:
                return float(val) if val not in (None, '') else None
            except ValueError:
                return None

        montant_min = _parse_montant(request.args.get('montant_min', ''))
        montant_max = _parse_montant(request.args.get('montant_max', ''))

        wb = openpyxl.Workbook()
        ws = wb.active

        if cycle_filter == 'Enseignants':
            ws.title = "Paiements Enseignants"
            where_clauses = []
            params = []
            if status_filter:
                where_clauses.append("p.statut=?")
                params.append(status_filter)
            if mois_filter:
                where_clauses.append("p.mois=?")
                params.append(mois_filter)
            if search_filter:
                like_term = f"%{search_filter}%"
                where_clauses.append("(u.nom LIKE ? OR u.prenom LIKE ?)")
                params.extend([like_term, like_term])
            if montant_min is not None:
                where_clauses.append("p.montant_total >= ?")
                params.append(montant_min)
            if montant_max is not None:
                where_clauses.append("p.montant_total <= ?")
                params.append(montant_max)
            if date_debut:
                where_clauses.append("p.date_paiement >= ?")
                params.append(date_debut)
            if date_fin:
                where_clauses.append("p.date_paiement <= ?")
                params.append(date_fin)
            where_sql = "WHERE " + " AND ".join(where_clauses) if where_clauses else ""

            data = conn.execute(f"""
                SELECT u.prenom||' '||u.nom, p.mois, p.type_paiement, p.montant_total,
                       p.montant_paye, p.montant_total-p.montant_paye, p.statut, p.date_paiement
                FROM paiements_enseignants p
                JOIN users u ON p.enseignant_id = u.id
                {where_sql}
                ORDER BY p.statut, u.nom
            """, params).fetchall()

            headers = ['Enseignant', 'Mois', 'Type de paiement', 'Montant Total', 'Montant Payé', 'Reste', 'Statut',
                       'Date paiement']
        else:
            ws.title = "Paiements"
            where_clauses = []
            params = []
            if cycle_filter not in ('Global', ''):
                where_clauses.append("(c.cycle = ? OR (c.cycle IS NULL AND ? = 'Primaire'))")
                params.extend([cycle_filter, cycle_filter])
            if status_filter == 'en_cours':
                _assurer_table_cheques(conn)
                where_clauses.append(_SQL_EN_COURS)
            elif status_filter:
                where_clauses.append("p.statut=?")
                params.append(status_filter)
                if status_filter in ('non_paye', 'partiel'):
                    _assurer_table_cheques(conn)
                    where_clauses.append("NOT " + _SQL_EN_COURS)
            if mois_filter:
                where_clauses.append("strftime('%Y-%m', p.date_echeance) = ?")
                params.append(mois_filter)
            if search_filter:
                like_term = f"%{search_filter}%"
                where_clauses.append("(e.nom LIKE ? OR e.prenom LIKE ?)")
                params.extend([like_term, like_term])
            if classe_filter:
                where_clauses.append("c.id=?")
                params.append(classe_filter)
            if categorie_filter:
                # 🩹 Même correctif que sur la page /paiements : "Scolarité" doit aussi
                # inclure les factures "[Scolarité + Transport]".
                if categorie_filter == 'Scolarité':
                    where_clauses.append("p.description LIKE '[Scolarité%'")
                else:
                    where_clauses.append("p.description LIKE ?")
                    params.append(f"[{categorie_filter}]%")
            if categorie_filter == 'Scolarité' and transport_filter == 'avec':
                where_clauses.append("p.description LIKE '[Scolarité + Transport]%'")
            elif categorie_filter == 'Scolarité' and transport_filter == 'sans':
                where_clauses.append("p.description LIKE '[Scolarité]%'")
            if montant_min is not None:
                where_clauses.append("p.montant_total >= ?")
                params.append(montant_min)
            if montant_max is not None:
                where_clauses.append("p.montant_total <= ?")
                params.append(montant_max)
            if date_debut:
                where_clauses.append("p.date_echeance >= ?")
                params.append(date_debut)
            if date_fin:
                where_clauses.append("p.date_echeance <= ?")
                params.append(date_fin)
            if recu_debut:
                where_clauses.append("date(p.date_paiement) >= ?")
                params.append(recu_debut)
            if recu_fin:
                where_clauses.append("date(p.date_paiement) <= ?")
                params.append(recu_fin)
            where_sql = "WHERE " + " AND ".join(where_clauses) if where_clauses else ""

            data = conn.execute(f"""
                SELECT e.prenom||' '||e.nom, c.nom, p.description, p.montant_total,
                       p.montant_paye, p.montant_total-COALESCE(p.montant_regule,0)-p.montant_paye, p.statut, p.date_echeance
                FROM paiements p
                JOIN eleves e ON p.eleve_id=e.id
                LEFT JOIN classes c ON e.classe_id=c.id
                {where_sql}
                ORDER BY p.statut, e.nom
            """, params).fetchall()

            headers = ['Élève', 'Classe', 'Description', 'Montant Total', 'Montant Payé', 'Reste', 'Statut', 'Échéance']

        conn.close()
        for col, h in enumerate(headers, 1): ws.cell(1, col, h)
        for row, d in enumerate(data, 2):
            d = list(d)
            # 🆕 Dernière colonne = date (Échéance élèves / Date paiement enseignants) :
            # mois + année uniquement, sauf saison scolaire pour les frais d'inscription.
            if cycle_filter == 'Enseignants':
                d[-1] = _formater_mois_annee(d[-1]) or ''
            else:
                d[-1] = _formater_date_paiement(d[-1], d[2]) or ''
            for col, val in enumerate(d, 1): ws.cell(row, col, val or '')
        buf = io.BytesIO();
        wb.save(buf);
        buf.seek(0)
        return send_file(buf, as_attachment=True, download_name='paiements.xlsx',
                         mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')
    except Exception as ex:
        flash(f'Erreur export: {ex}', 'error');
        return redirect(url_for('paiements'))


# ═══════════════════════════════════════════════════════════════
# 🆕 BULLETIN SCOLAIRE — design "école de luxe" (bandeau bleu marine, sceau doré,
# photo de l'élève, tableau des moyennes, mini-graphique d'évolution, observations
# des enseignants). Dessiné entièrement avec reportlab (canvas), sans dépendance
# externe supplémentaire (aucun ajout à requirements.txt).
# ═══════════════════════════════════════════════════════════════
# 🩹 CORRECTIF : `cm` doit être importé au niveau du MODULE (pas seulement à l'intérieur de
# export_bulletin_pdf) car les fonctions _bulletin_* ci-dessous sont définies au niveau module
# et le résolvent donc dans les globals du module, pas dans les locals de la route appelante.
from reportlab.lib.units import cm

_BULLETIN_NAVY = '#152341'
_BULLETIN_NAVY_LIGHT = '#1F3358'
_BULLETIN_GOLD = '#C9A24B'
_BULLETIN_GOLD_LIGHT = '#E4C878'
_BULLETIN_CREAM = '#FBF8F1'
_BULLETIN_BORDER = '#E7DFC9'
_BULLETIN_TEXT_DARK = '#1E2430'
_BULLETIN_TEXT_MUTED = '#6B7280'
_BULLETIN_GREEN = '#1F9254'
_BULLETIN_AMBER = '#C08A1E'
_BULLETIN_RED = '#C0392B'

_MOIS_FR = ['', 'janvier', 'février', 'mars', 'avril', 'mai', 'juin',
            'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre']


def _bulletin_date_fr(date_str):
    """Formate une date ISO ('2015-03-12') en 'Mars 2015' à la française, sans dépendance
    à la locale du serveur (souvent absente sur Render)."""
    if not date_str:
        return None
    try:
        d = datetime.datetime.strptime(date_str[:10], '%Y-%m-%d').date()
        return f"{d.day} {_MOIS_FR[d.month].capitalize()} {d.year}"
    except (ValueError, TypeError, IndexError):
        return None


def _formater_mois_annee(date_str):
    """Formate une date ISO ('2026-01-12') en 'Janvier 2026' (mois + année, sans le jour),
    sans dépendance à la locale du serveur."""
    if not date_str:
        return None
    try:
        d = datetime.datetime.strptime(str(date_str)[:10], '%Y-%m-%d').date()
        return f"{_MOIS_FR[d.month].capitalize()} {d.year}"
    except (ValueError, TypeError, IndexError):
        return None


def _formater_date_paiement(date_str, description=None):
    """🆕 Formatage des dates sur la page Paiements et les factures :
    - Frais d'inscription -> saison scolaire (ex: '2026-2027'), année en cours + année suivante
    - Toutes les autres dates -> mois + année uniquement, sans le jour (ex: 'Janvier 2026')."""
    if not date_str:
        return None
    categorie = ''
    if description and ']' in str(description):
        categorie = str(description).split(']')[0].lstrip('[').strip()
    if categorie.lower() == "frais d'inscription":
        try:
            d = datetime.datetime.strptime(str(date_str)[:10], '%Y-%m-%d').date()
            return f"{d.year}-{d.year + 1}"
        except (ValueError, TypeError, IndexError):
            return None
    return _formater_mois_annee(date_str)


def _label_mois_paye(p):
    """🆕 Libellé "Mois payé" / "Saison payée" pour le reçu PDF : pour un "Frais
    d'inscription", on affiche toujours la saison scolaire (ex: '2026-2027') calculée à
    partir de la date d'échéance — quel que soit le contenu de la colonne `mois` (celle-ci
    est renseignée automatiquement par un trigger SQLite dès qu'une échéance existe, y
    compris pour les frais d'inscription, ce qui donnerait sinon un mois au lieu d'une saison).
    Pour tous les autres types de paiement (mensualités, Voyage, Achat...), on se base en
    priorité sur la colonne `mois` (fiable pour les mensualités générées automatiquement),
    et on retombe sur la date d'échéance formatée (mois/année) si `mois` est vide (cas des
    paiements ajoutés manuellement)."""
    categorie = ''
    if p['description'] and ']' in str(p['description']):
        categorie = str(p['description']).split(']')[0].lstrip('[').strip()

    if categorie.lower() == "frais d'inscription":
        return _formater_date_paiement(p['date_echeance'], p['description'])

    mois_col = None
    try:
        mois_col = p['mois']
    except (IndexError, KeyError):
        mois_col = None
    if mois_col:
        label = _formater_mois_annee(f"{mois_col}-01")
        if label:
            return label
    return _formater_date_paiement(p['date_echeance'], p['description'])


# 🆕 Filtres Jinja utilisables dans les templates : {{ p.date_echeance | date_paiement(p.description) }}
app.jinja_env.filters['date_paiement'] = lambda v, desc=None: _formater_date_paiement(v, desc) or '—'
app.jinja_env.filters['mois_annee'] = lambda v: _formater_mois_annee(v) or '—'


def _bulletin_annee_scolaire():
    """Année scolaire en cours ('2025-2026'), calculée à partir de la date du jour :
    à partir de septembre on est déjà dans la nouvelle année scolaire."""
    aujourdhui = datetime.date.today()
    if aujourdhui.month >= 9:
        return f"{aujourdhui.year}-{aujourdhui.year + 1}"
    return f"{aujourdhui.year - 1}-{aujourdhui.year}"


def _bulletin_appreciation(note):
    if note is None:
        return '—'
    if note >= 16: return 'Excellent'
    if note >= 14: return 'Très bien'
    if note >= 12: return 'Bien'
    if note >= 10: return 'Passable'
    return 'Insuffisant'


def _bulletin_note_color(v):
    from reportlab.lib import colors
    if v is None: return colors.HexColor(_BULLETIN_TEXT_MUTED)
    if v < 8: return colors.HexColor(_BULLETIN_RED)
    if v < 12: return colors.HexColor(_BULLETIN_AMBER)
    return colors.HexColor(_BULLETIN_GREEN)


def _bulletin_rounded_rect(c, x, y, w, h, r, fill=None, stroke=None, lw=1):
    c.saveState()
    if fill is not None:
        c.setFillColor(fill)
    if stroke is not None:
        c.setStrokeColor(stroke)
        c.setLineWidth(lw)
    c.roundRect(x, y, w, h, r, stroke=1 if stroke is not None else 0, fill=1 if fill is not None else 0)
    c.restoreState()


def _bulletin_star(c, cx, cy, r_out, r_in, color, points=5, rotation=-90):
    import math
    c.saveState()
    c.setFillColor(color)
    path = c.beginPath()
    ang_step = math.pi / points
    start = math.radians(rotation)
    for i in range(points * 2):
        r = r_out if i % 2 == 0 else r_in
        ang = start + i * ang_step
        x = cx + r * math.cos(ang)
        y = cy + r * math.sin(ang)
        if i == 0:
            path.moveTo(x, y)
        else:
            path.lineTo(x, y)
    path.close()
    c.drawPath(path, fill=1, stroke=0)
    c.restoreState()


def _bulletin_diamond(c, cx, cy, r, color):
    c.saveState()
    c.setFillColor(color)
    p = c.beginPath()
    p.moveTo(cx, cy + r); p.lineTo(cx + r, cy); p.lineTo(cx, cy - r); p.lineTo(cx - r, cy)
    p.close()
    c.drawPath(p, fill=1, stroke=0)
    c.restoreState()


def _bulletin_safe_image(path, max_px=900):
    """🩹 Charge une image pour le PDF en la redimensionnant/compressant si besoin.
    Évite les timeouts Gunicorn et les pics mémoire causés par des photos très
    lourdes (ex: photo de smartphone non compressée, plusieurs Mo / haute résolution)
    et convertit au passage les modes problématiques (CMYK, palette...) en RGB."""
    from reportlab.lib.utils import ImageReader
    try:
        from PIL import Image
        img = Image.open(path)
        img.load()
        if img.mode not in ('RGB', 'L'):
            img = img.convert('RGB')
        w, h = img.size
        if max(w, h) > max_px:
            scale = max_px / max(w, h)
            img = img.resize((max(1, int(w * scale)), max(1, int(h * scale))), Image.LANCZOS)
        out = io.BytesIO()
        img.save(out, format='JPEG', quality=85)
        out.seek(0)
        return ImageReader(out)
    except Exception:
        # Dernier recours : laisser reportlab tenter de lire le fichier tel quel
        return ImageReader(path)


# 🩹 CORRECTIF : contrairement à `_bulletin_safe_image` (qui renvoie un ImageReader, utilisé
# avec les dessins au `canvas` bas niveau — reçus, bulletins...), les documents construits
# avec des flowables platypus (`reportlab.platypus.Image`, utilisé par les PDF d'emploi du
# temps) N'ACCEPTENT PAS un ImageReader en entrée : cela lève un TypeError silencieusement
# avalé par le `except Exception: pass` appelant, si bien que la bannière de l'école
# n'apparaissait jamais sur ces PDF alors qu'elle s'affichait très bien sur les reçus.
# Cette variante renvoie directement un buffer BytesIO (image déjà redimensionnée/compressée),
# ce que `reportlab.platypus.Image` sait consommer nativement, ainsi que ses dimensions.
def _bulletin_flowable_image(path, max_px=1600):
    from PIL import Image
    img = Image.open(path)
    img.load()
    if img.mode not in ('RGB', 'L'):
        img = img.convert('RGB')
    w, h = img.size
    if max(w, h) > max_px:
        scale = max_px / max(w, h)
        img = img.resize((max(1, int(w * scale)), max(1, int(h * scale))), Image.LANCZOS)
        w, h = img.size
    out = io.BytesIO()
    img.save(out, format='JPEG', quality=88)
    out.seek(0)
    return out, w, h


# 🆕 BANNIÈRE PLEINE LARGEUR DES EXPORTS PDF D'EMPLOI DU TEMPS — sur demande de l'école, la
# bannière doit couvrir TOUTE la largeur de la feuille (bord à bord, de gauche à droite),
# collée en haut. Une image insérée comme flowable classique reste toujours cantonnée à
# l'intérieur des marges du document ; on la dessine donc directement sur le canevas
# (avant que reportlab ne dessine le contenu de la page), en dehors du cadre à marges.
def _pdf_banniere_pleine_largeur_setup(banniere_path, page_w, max_h_cm=2.2):
    """Prépare la bannière pour un affichage pleine largeur : renvoie (image_reader,
    hauteur_finale) à partir du chemin du fichier, ou (None, 0) en cas d'erreur. La
    hauteur est plafonnée pour éviter qu'une bannière trop haute ne pousse la grille des
    créneaux sur une 2e page (la largeur, elle, reste toujours celle de la feuille)."""
    from reportlab.lib.utils import ImageReader
    from reportlab.lib.units import cm
    try:
        banniere_buf, iw_b, ih_b = _bulletin_flowable_image(banniere_path)
        banner_h = page_w * (ih_b / iw_b)
        max_h = max_h_cm * cm
        if banner_h > max_h:
            banner_h = max_h
        return ImageReader(banniere_buf), banner_h
    except Exception:
        return None, 0


def _pdf_page_avec_banniere(image_reader, banner_h, page_w, page_h, callback_suivant=None):
    """Renvoie une fonction de callback (utilisable en onFirstPage) qui dessine la
    bannière bord à bord (x=0 → page_w) tout en haut de la feuille (y=page_h-banner_h →
    page_h), puis enchaîne avec callback_suivant (ex. _pdf_footer) si fourni."""
    def _dessiner(canvas, doc):
        canvas.saveState()
        try:
            canvas.drawImage(image_reader, 0, page_h - banner_h, width=page_w, height=banner_h,
                              preserveAspectRatio=False, mask='auto')
        except Exception:
            pass
        canvas.restoreState()
        if callback_suivant:
            callback_suivant(canvas, doc)
    return _dessiner


# 🆕 Palette de couleurs pastel attribuées de façon STABLE à chaque matière (même matière =
# toujours la même couleur, sur tous les jours et sur les trois exports PDF d'emploi du temps
# — classe / enseignant / élève), pour repérer chaque matière d'un coup d'œil comme sur un
# vrai planning scolaire imprimé, plutôt qu'un unique bloc bleu indifférencié pour toutes.
_PALETTE_MATIERES_PDF = [
    '#E3F2FD', '#E8F5E9', '#FFF3E0', '#F3E5F5', '#FCE4EC', '#E0F7FA',
    '#FFFDE7', '#EDE7F6', '#E8EAF6', '#F1F8E9', '#FBE9E7', '#E0F2F1',
]


def _couleur_matiere_pdf(nom):
    """Retourne une couleur de fond hex stable pour une matière donnée (même nom → toujours
    la même couleur), utilisée sur les créneaux des PDF d'emploi du temps. Un créneau sans
    matière (libellé libre) reçoit une couleur ambre neutre distincte de la palette."""
    if not nom:
        return '#FFF3E5'
    h = 0
    for ch in str(nom).strip().lower():
        h = (h * 31 + ord(ch)) & 0xFFFFFFFF
    return _PALETTE_MATIERES_PDF[h % len(_PALETTE_MATIERES_PDF)]


# 🆕 ─────────────────────────────────────────────
# DESIGN "LUXE" DES EXPORTS PDF DE L'EMPLOI DU TEMPS (classe / enseignant / élève)
# ─────────────────────────────────────────────
# Sur demande de l'école : le PDF imprimé de l'emploi du temps doit reprendre un style
# "premium" façon planning imprimé (bandeau titre en pilule bleu marine + sous-titre en
# pilule colorée, et un code couleur DISTINCT par jour sur les en-têtes et la barre
# d'accent de chaque créneau), au lieu du bandeau gris uniforme précédent. Ne concerne QUE
# ces 3 exports emploi du temps — le reste des PDF de l'app (reçus, bulletins...) est
# inchangé.
_ETP_DAY_COLORS = {
    'Lundi':    ('#2F6FED', '#EAF1FE'),
    'Mardi':    ('#22A559', '#E7F7EC'),
    'Mercredi': ('#E23B7A', '#FDEAF2'),
    'Jeudi':    ('#F08A24', '#FEF1E1'),
    'Vendredi': ('#8B5CF6', '#F2EBFE'),
    'Samedi':   ('#17A6A6', '#E4F7F7'),
}


def _pdf_emploi_temps_entete(elems, page_w, titre, sous_titre, accent_hex='#0A84FF', show_school_name=True):
    """Bandeau titre 'luxe' des 3 exports PDF d'emploi du temps : titre dans une pilule
    bleu marine arrondie, sous-titre (classe / enseignant / élève + nb de créneaux) dans
    une pilule colorée juste en dessous. Remplace, pour ces 3 exports seulement, l'ancien
    bandeau texte simple de _pdf_letterhead_compact."""
    from reportlab.lib import colors
    from reportlab.platypus import Table, TableStyle, Paragraph, Spacer
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib.units import cm

    if show_school_name:
        elems.append(Paragraph("🏫 <b>" + _nom_ecole_html() + "</b>", ParagraphStyle(
            'SchoolNameC', fontSize=10.5, textColor=colors.HexColor('#0F172A'),
            fontName='Helvetica-Bold', leading=13)))
        elems.append(Spacer(1, 0.18 * cm))

    titre_style = ParagraphStyle('EtTitreLuxe', fontSize=15.5, textColor=colors.white,
                                 fontName='Helvetica-Bold', alignment=1, leading=18)
    title_tbl = Table([[Paragraph(f"✦ &nbsp; {html.escape(titre.upper())} &nbsp; ✦", titre_style)]],
                      colWidths=[page_w - 2 * cm])
    title_tbl.setStyle(TableStyle([
        ('BACKGROUND', (0, 0), (-1, -1), colors.HexColor('#0F1E3D')),
        ('TOPPADDING', (0, 0), (-1, -1), 8), ('BOTTOMPADDING', (0, 0), (-1, -1), 8),
        ('ROUNDEDCORNERS', [14, 14, 14, 14]),
    ]))
    elems.append(title_tbl)
    elems.append(Spacer(1, 0.22 * cm))

    if sous_titre:
        sous_style = ParagraphStyle('EtSousLuxe', fontSize=9, textColor=colors.white,
                                    fontName='Helvetica-Bold', alignment=1)
        sous_tbl = Table([[Paragraph(html.escape(sous_titre), sous_style)]])
        sous_tbl.setStyle(TableStyle([
            ('BACKGROUND', (0, 0), (-1, -1), colors.HexColor(accent_hex)),
            ('LEFTPADDING', (0, 0), (-1, -1), 14), ('RIGHTPADDING', (0, 0), (-1, -1), 14),
            ('TOPPADDING', (0, 0), (-1, -1), 5), ('BOTTOMPADDING', (0, 0), (-1, -1), 5),
            ('ROUNDEDCORNERS', [10, 10, 10, 10]),
        ]))
        sous_tbl.hAlign = 'CENTER'
        elems.append(sous_tbl)
        elems.append(Spacer(1, 0.32 * cm))
    else:
        elems.append(Spacer(1, 0.15 * cm))


def _pdf_emploi_temps_grille(elems, page_w, grille, get_titre, get_meta, jours=None):
    """Construit la grille par jour (en-têtes en pilule colorée + cartes de créneaux
    arrondies avec barre d'accent assortie à la couleur du jour), commune aux 3 exports
    PDF d'emploi du temps (classe / enseignant / élève). get_titre(cr) renvoie le titre du
    créneau (matière [+ sous-matière]) ; get_meta(cr) renvoie la liste des infos
    secondaires (enseignant/classe + salle) affichées dessous. 🆕 `jours` permet de
    restreindre les colonnes affichées (ex. JOURS_EMPLOI_TEMPS_PDF pour masquer le samedi
    à l'impression) ; par défaut, tous les jours de JOURS_SEMAINE sont affichés."""
    from reportlab.lib import colors
    from reportlab.platypus import Table, TableStyle, Paragraph, Spacer
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.lib.units import cm

    if jours is None:
        jours = JOURS_SEMAINE

    heure_style = ParagraphStyle('EtHeure', fontSize=6.8, textColor=colors.HexColor('#64748B'),
                                 fontName='Helvetica-Bold', leading=8)
    mat_style = ParagraphStyle('EtMat', fontSize=7.8, textColor=colors.HexColor('#0F172A'),
                               fontName='Helvetica-Bold', leading=9.4)
    meta_style = ParagraphStyle('EtMeta', fontSize=6.3, textColor=colors.HexColor('#64748B'), leading=7.4)
    vide_style = ParagraphStyle('EtVide', fontSize=6.8, textColor=colors.HexColor('#94A3B8'), alignment=1)
    jour_style = ParagraphStyle('EtJour', fontSize=8, textColor=colors.white, alignment=1,
                                fontName='Helvetica-Bold')
    jour_sub_style = ParagraphStyle('EtJourSub', fontSize=6, textColor=colors.white, alignment=1)

    nb_jours = len(jours)
    col_w = (page_w - 2 * cm) / nb_jours
    cell_w = col_w - 0.3 * cm
    accent_w = 0.22 * cm
    content_w = cell_w - accent_w

    header_row = []
    for jour in jours:
        day_accent, _day_light = _ETP_DAY_COLORS.get(jour, ('#334155', '#E2E8F0'))
        nb = len(grille[jour])
        h_tbl = Table([[Paragraph(jour, jour_style)],
                      [Paragraph(f"{nb} créneau{'x' if nb > 1 else ''}", jour_sub_style)]],
                     colWidths=[cell_w])
        h_tbl.setStyle(TableStyle([
            ('BACKGROUND', (0, 0), (-1, -1), colors.HexColor(day_accent)),
            ('TOPPADDING', (0, 0), (-1, 0), 5), ('BOTTOMPADDING', (0, 0), (-1, 0), 1),
            ('TOPPADDING', (0, 1), (-1, 1), 0), ('BOTTOMPADDING', (0, 1), (-1, 1), 5),
            ('ROUNDEDCORNERS', [8, 8, 0, 0]),
        ]))
        header_row.append(h_tbl)

    body_row = []
    for jour in jours:
        day_accent, day_light = _ETP_DAY_COLORS.get(jour, ('#334155', '#E2E8F0'))
        if not grille[jour]:
            empty_tbl = Table([[Paragraph("Aucun créneau", vide_style)]], colWidths=[cell_w])
            empty_tbl.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (-1, -1), colors.HexColor(day_light)),
                ('TOPPADDING', (0, 0), (-1, -1), 14), ('BOTTOMPADDING', (0, 0), (-1, -1), 14),
                ('ROUNDEDCORNERS', [0, 0, 8, 8]),
            ]))
            body_row.append(empty_tbl)
            continue
        bloc_rows = []
        for cr in sorted(grille[jour], key=lambda x: x['heure_debut']):
            bg = _couleur_matiere_pdf(cr.get('matiere_nom') or cr.get('libelle'))
            titre_c = get_titre(cr)
            meta_bits = get_meta(cr)
            contenu = [[Paragraph(f"{cr['heure_debut']} – {cr['heure_fin']}", heure_style)],
                      [Paragraph(_pdf_arabic_safe(titre_c, bold=True), mat_style)]]
            if meta_bits:
                contenu.append([Paragraph(_pdf_arabic_safe(' · '.join(meta_bits)), meta_style)])
            inner_tbl = Table(contenu, colWidths=[content_w])
            inner_tbl.setStyle(TableStyle([
                ('LEFTPADDING', (0, 0), (-1, -1), 5), ('RIGHTPADDING', (0, 0), (-1, -1), 4),
                ('TOPPADDING', (0, 0), (-1, 0), 3), ('BOTTOMPADDING', (0, -1), (-1, -1), 3),
                ('TOPPADDING', (0, 1), (-1, -1), 0.5), ('BOTTOMPADDING', (0, 0), (-1, -2), 0.5),
                ('BACKGROUND', (0, 0), (-1, -1), colors.HexColor(bg)),
            ]))
            card = Table([['', inner_tbl]], colWidths=[accent_w, content_w])
            card.setStyle(TableStyle([
                ('BACKGROUND', (0, 0), (0, -1), colors.HexColor(day_accent)),
                ('BACKGROUND', (1, 0), (1, -1), colors.HexColor(bg)),
                ('LEFTPADDING', (0, 0), (-1, -1), 0), ('RIGHTPADDING', (0, 0), (-1, -1), 0),
                ('TOPPADDING', (0, 0), (-1, -1), 0), ('BOTTOMPADDING', (0, 0), (-1, -1), 0),
                ('ROUNDEDCORNERS', [6, 6, 6, 6]),
            ]))
            bloc_rows.append([card])
            bloc_rows.append([Spacer(1, 0.09 * cm)])
        day_tbl = Table(bloc_rows, colWidths=[cell_w])
        day_tbl.setStyle(TableStyle([
            ('LEFTPADDING', (0, 0), (-1, -1), 0), ('RIGHTPADDING', (0, 0), (-1, -1), 0),
            ('TOPPADDING', (0, 0), (-1, -1), 0), ('BOTTOMPADDING', (0, 0), (-1, -1), 0),
        ]))
        wrapper = Table([[day_tbl]], colWidths=[cell_w])
        wrapper.setStyle(TableStyle([
            ('LEFTPADDING', (0, 0), (-1, -1), 3), ('RIGHTPADDING', (0, 0), (-1, -1), 3),
            ('TOPPADDING', (0, 0), (-1, -1), 4), ('BOTTOMPADDING', (0, 0), (-1, -1), 4),
            ('BACKGROUND', (0, 0), (-1, -1), colors.HexColor(day_light)),
            ('ROUNDEDCORNERS', [0, 0, 8, 8]),
        ]))
        body_row.append(wrapper)

    planning = Table([header_row, body_row], colWidths=[col_w] * nb_jours)
    planning.setStyle(TableStyle([
        ('VALIGN', (0, 0), (-1, -1), 'TOP'),
        ('TOPPADDING', (0, 0), (-1, -1), 0), ('BOTTOMPADDING', (0, 0), (-1, -1), 0),
        ('LEFTPADDING', (0, 0), (-1, -1), 2), ('RIGHTPADDING', (0, 0), (-1, -1), 2),
    ]))
    elems.append(planning)


def _bulletin_fit_right_text(text, font_name, max_width, max_size=6.9, min_size=5.2, step=0.3):
    """🩹 Réduit progressivement la taille de police pour qu'un texte tienne dans
    max_width (ex: nom de matière à côté de son libellé 'Meilleure matière' /
    'Matière la plus faible', qui peuvent être longs). Si même à la taille
    minimale ça ne rentre toujours pas, tronque proprement avec des points de
    suspension au lieu de laisser le texte chevaucher le libellé."""
    from reportlab.pdfbase.pdfmetrics import stringWidth
    text = str(text)
    size = max_size
    while size >= min_size:
        if stringWidth(text, font_name, size) <= max_width:
            return text, size
        size = round(size - step, 2)
    size = min_size
    truncated = text
    while truncated and stringWidth(truncated + '…', font_name, size) > max_width:
        truncated = truncated[:-1]
    return (truncated + '…' if truncated != text else text), size


def _bulletin_draw_crest(c, cx, cy, size, logo_path=None):
    """Emblème gauche du bandeau : logo réel de l'école si disponible (uploadé depuis
    /parametres), sinon un blason dessiné (livre + étoile) dans le même esprit visuel."""
    from reportlab.lib import colors
    NAVY = colors.HexColor(_BULLETIN_NAVY)
    GOLD = colors.HexColor(_BULLETIN_GOLD)
    if logo_path and os.path.exists(logo_path):
        try:
            img = _bulletin_safe_image(logo_path)
            iw, ih = img.getSize()
            ratio = min(size / iw, size / ih)
            w, h = iw * ratio, ih * ratio
            c.drawImage(img, cx - w / 2, cy - h / 2, width=w, height=h,
                        preserveAspectRatio=True, mask='auto')
            return
        except Exception:
            pass
    r = size / 2
    c.saveState()
    c.setStrokeColor(GOLD)
    c.setLineWidth(1.4)
    c.circle(cx, cy, r, stroke=1, fill=0)
    c.circle(cx, cy, r - 0.09 * cm, stroke=1, fill=0)
    bw, bh = r * 0.95, r * 0.62
    c.setFillColor(GOLD)
    c.roundRect(cx - bw / 2, cy - bh / 2, bw, bh, 2, stroke=0, fill=1)
    c.setStrokeColor(NAVY)
    c.setLineWidth(1.1)
    c.line(cx, cy - bh / 2 + 1, cx, cy + bh / 2 - 1)
    for dx in (-bw * 0.28, bw * 0.28):
        c.setLineWidth(0.6)
        c.line(cx + dx - bw * 0.14, cy - bh * 0.12, cx + dx + bw * 0.14, cy - bh * 0.12)
        c.line(cx + dx - bw * 0.14, cy + bh * 0.02, cx + dx + bw * 0.14, cy + bh * 0.02)
    _bulletin_star(c, cx, cy + r * 0.72, r * 0.16, r * 0.07, GOLD)
    c.restoreState()


def _bulletin_draw_medallion(c, cx, cy, r, lines, tail_bottom_y):
    """Sceau doré à droite du bandeau, avec deux rubans qui retombent sous l'en-tête."""
    import math
    from reportlab.lib import colors
    NAVY = colors.HexColor(_BULLETIN_NAVY)
    GOLD = colors.HexColor(_BULLETIN_GOLD)
    GOLD_LIGHT = colors.HexColor(_BULLETIN_GOLD_LIGHT)
    c.saveState()
    tail_w = r * 0.62
    for dx in (-r * 0.55, r * 0.55):
        x0 = cx + dx - tail_w / 2
        c.setFillColor(GOLD)
        p = c.beginPath()
        p.moveTo(x0, cy)
        p.lineTo(x0 + tail_w, cy)
        p.lineTo(x0 + tail_w, tail_bottom_y + 0.35 * cm)
        p.lineTo(x0 + tail_w / 2, tail_bottom_y)
        p.lineTo(x0, tail_bottom_y + 0.35 * cm)
        p.close()
        c.drawPath(p, fill=1, stroke=0)
    c.setFillColor(GOLD_LIGHT)
    c.circle(cx, cy, r, stroke=0, fill=1)
    c.setStrokeColor(colors.white)
    c.setLineWidth(1.3)
    c.circle(cx, cy, r - 0.14 * cm, stroke=1, fill=0)
    c.setStrokeColor(GOLD)
    c.setLineWidth(0.8)
    c.circle(cx, cy, r - 0.28 * cm, stroke=1, fill=0)
    for i in range(8):
        ang = math.radians(i * 45 + 10)
        _bulletin_star(c, cx + (r - 0.05 * cm) * math.cos(ang), cy + (r - 0.05 * cm) * math.sin(ang),
                       0.045 * cm, 0.02 * cm, colors.white)
    c.setFillColor(NAVY)
    n = len(lines)
    fsz = 6.6
    total_h = n * (fsz + 1.4)
    ystart = cy + total_h / 2 - fsz
    for i, (txt, bold) in enumerate(lines):
        c.setFont('Helvetica-Bold' if bold else 'Helvetica', fsz if not bold else fsz + 0.6)
        c.drawCentredString(cx, ystart - i * (fsz + 1.4), txt)
    c.restoreState()


def _bulletin_draw_avatar(c, cx, cy, r, image_path=None, initials=''):
    from reportlab.lib import colors
    GOLD = colors.HexColor(_BULLETIN_GOLD)
    NAVY = colors.HexColor(_BULLETIN_NAVY)
    c.saveState()
    c.setStrokeColor(GOLD)
    c.setLineWidth(2.2)
    c.setFillColor(colors.HexColor('#EDE6D3'))
    c.circle(cx, cy, r, stroke=1, fill=1)
    drew_image = False
    if image_path and os.path.exists(image_path):
        try:
            img = _bulletin_safe_image(image_path)
            c.saveState()
            p = c.beginPath()
            p.circle(cx, cy, r - 1.1)
            c.clipPath(p, stroke=0, fill=0)
            # 🩹 Mode "cover" (comme object-fit:cover en CSS) : la photo est agrandie pour
            # remplir tout le cercle sans bande vide, quel que soit son ratio d'origine —
            # avant, l'option preserveAspectRatio "contain" laissait parfois la photo plus
            # petite que le cercle, avec le fond crème visible autour ("photo coupée/petite").
            iw, ih = img.getSize()
            scale = max((2 * r) / iw, (2 * r) / ih)
            dw, dh = iw * scale, ih * scale
            c.drawImage(img, cx - dw / 2, cy - dh / 2, width=dw, height=dh,
                        preserveAspectRatio=True, mask='auto', anchor='c')
            c.restoreState()
            drew_image = True
        except Exception:
            drew_image = False
    if not drew_image:
        c.setFillColor(NAVY)
        c.setFont('Helvetica-Bold', r * 0.9)
        c.drawCentredString(cx, cy - r * 0.32, initials.upper())
    c.restoreState()


def _bulletin_mini_line_chart(c, x, y, w, h, labels, values, line_color, area_color, systeme='20'):
    """Petit graphique d'évolution dessiné à la main (aucune dépendance externe type matplotlib)."""
    from reportlab.lib import colors
    c.saveState()
    pad_l, pad_b, pad_t = 0.75 * cm, 0.55 * cm, 0.15 * cm
    plot_x, plot_y = x + pad_l, y + pad_b
    plot_w, plot_h = w - pad_l - 0.25 * cm, h - pad_b - pad_t
    vmax = 20.0
    c.setFont('Helvetica', 6.2)
    c.setFillColor(colors.HexColor(_BULLETIN_TEXT_MUTED))
    if systeme == 'lettres':
        _grille = [(0, ''), (4, 'C'), (10, 'B'), (16, 'A'), (20, '')]
    elif systeme == '10':
        _grille = [(0, '0'), (5, '2.5'), (10, '5'), (15, '7.5'), (20, '10')]
    else:
        _grille = [(0, '0'), (5, '5'), (10, '10'), (15, '15'), (20, '20')]
    for gv, glab in _grille:
        gy = plot_y + (gv / vmax) * plot_h
        c.setStrokeColor(colors.HexColor('#EDEBE3'))
        c.setLineWidth(0.5)
        c.line(plot_x, gy, plot_x + plot_w, gy)
        c.drawRightString(plot_x - 0.12 * cm, gy - 2, glab)
    pts_valid = [(i, v) for i, v in enumerate(values) if v is not None]
    n = len(values)
    if n >= 1:
        step = plot_w / max(1, n - 1)
        coords = [(plot_x + i * step, plot_y + (v / vmax) * plot_h) for i, v in pts_valid]
        if len(coords) >= 2:
            p = c.beginPath()
            p.moveTo(coords[0][0], plot_y)
            for cxp, cyp in coords:
                p.lineTo(cxp, cyp)
            p.lineTo(coords[-1][0], plot_y)
            p.close()
            c.setFillColor(area_color)
            c.drawPath(p, fill=1, stroke=0)
            c.setStrokeColor(line_color)
            c.setLineWidth(2.2)
            c.setLineJoin(1)
            p2 = c.beginPath()
            p2.moveTo(*coords[0])
            for pt in coords[1:]:
                p2.lineTo(*pt)
            c.drawPath(p2, fill=0, stroke=1)
        for (cxp, cyp), (_, v) in zip(coords, pts_valid):
            c.setFillColor(line_color)
            c.circle(cxp, cyp, 2.6, stroke=0, fill=1)
            c.setFillColor(colors.HexColor(_BULLETIN_TEXT_DARK))
            c.setFont('Helvetica-Bold', 7)
            c.drawCentredString(cxp, cyp + 6, fmt_moy_sys(v, systeme, 2, False))
    c.setFont('Helvetica', 6.4)
    c.setFillColor(colors.HexColor(_BULLETIN_TEXT_MUTED))
    step = plot_w / max(1, n - 1) if n > 1 else 0
    for i, lab in enumerate(labels):
        lx = plot_x + i * step if n > 1 else plot_x + plot_w / 2
        c.drawCentredString(lx, y + 0.12 * cm, lab)
    c.restoreState()


# 🆕 Anneau/cercle de progression (« donut ») — utilisé pour l'analyse par matière du bulletin
# (page 2) : affiche la moyenne d'une matière sous forme de cercle rempli proportionnellement
# à la note/20, coloré selon le niveau (vert/orange/rouge), sans dépendance externe.
def _bulletin_donut_gauge(c, cx, cy, r, pct, color, track_hex='#EDE8D8'):
    """Dessine un cercle de progression centré en (cx, cy) de rayon r. `pct` est une fraction
    0..1 (ex: moyenne/20). Le remplissage part du haut (12h) et tourne dans le sens horaire."""
    from reportlab.lib import colors
    c.saveState()
    pct = max(0.0, min(1.0, pct or 0.0))
    c.setFillColor(colors.HexColor(track_hex))
    c.circle(cx, cy, r, stroke=0, fill=1)
    if pct > 0:
        c.setFillColor(color)
        extent = -360.0 * pct
        if pct >= 0.999:
            c.circle(cx, cy, r, stroke=0, fill=1)
        else:
            c.wedge(cx - r, cy - r, cx + r, cy + r, 90, extent, stroke=0, fill=1)
    c.setFillColor(colors.white)
    c.circle(cx, cy, r * 0.60, stroke=0, fill=1)
    c.restoreState()


# ═══════════════════════════════════════════════════════════════════════════
# 🆕 DESIGN SYSTEM PDF UNIFIÉ — les mêmes fonctions ci-dessous dessinent le
# bandeau navy/or, la carte d'identité, le tableau et le pied de page utilisés
# par le bulletin scolaire, et sont désormais réutilisées par TOUS les autres
# documents PDF officiels (reçus/factures de paiement, bulletins de paie du
# personnel enseignant et non-enseignant) afin qu'ils partagent exactement la
# même identité visuelle premium (même couleurs, même blason, même typographie).
# ═══════════════════════════════════════════════════════════════════════════

def _doc_premium_header(c, ML, CW, H, title_main, subtitle_label, badge_text, medallion_lines,
                         logo_path=None, banniere_path=None, header_h=3.9 * cm):
    """Bandeau d'en-tête premium générique — EXACTEMENT le même dessin que le bandeau du
    bulletin scolaire (blason/logo à gauche, titre + sous-titre + pastille dorée au centre,
    médaillon à droite ; ou bannière personnalisée de l'école si elle a été uploadée).
    Retourne header_bot (bas du bandeau) pour enchaîner avec la suite du document."""
    from reportlab.lib import colors
    NAVY = colors.HexColor(_BULLETIN_NAVY)
    NAVY_LIGHT = colors.HexColor(_BULLETIN_NAVY_LIGHT)
    GOLD = colors.HexColor(_BULLETIN_GOLD)
    GOLD_LIGHT = colors.HexColor(_BULLETIN_GOLD_LIGHT)

    header_top = H - ML
    header_bot = header_top - header_h
    if banniere_path:
        c.saveState()
        p = c.beginPath()
        p.roundRect(ML, header_bot, CW, header_h, 0.35 * cm)
        c.clipPath(p, stroke=0, fill=0)
        try:
            img = _bulletin_safe_image(banniere_path)
            iw, ih = img.getSize()
            scale = max(CW / iw, header_h / ih)
            dw, dh = iw * scale, ih * scale
            dx = ML + (CW - dw) / 2
            dy = header_bot + (header_h - dh) / 2
            c.drawImage(img, dx, dy, width=dw, height=dh, preserveAspectRatio=True, mask='auto')
        except Exception:
            c.setFillColor(NAVY)
            c.rect(ML, header_bot, CW, header_h, stroke=0, fill=1)
        c.restoreState()
    else:
        _bulletin_rounded_rect(c, ML, header_bot, CW, header_h, 0.35 * cm, fill=NAVY)
        c.saveState()
        p = c.beginPath()
        p.roundRect(ML, header_bot, CW, header_h, 0.35 * cm)
        c.clipPath(p, stroke=0, fill=0)
        c.setFillColor(NAVY_LIGHT)
        c.rect(ML, header_top - 0.06 * cm, CW, 0.06 * cm, stroke=0, fill=1)
        c.restoreState()

        crest_cx = ML + 2.0 * cm
        crest_cy = header_bot + header_h / 2 + 0.15 * cm
        _bulletin_draw_crest(c, crest_cx, crest_cy, 2.6 * cm, logo_path=logo_path)
        if not logo_path:
            c.setFillColor(colors.white)
            c.setFont('Helvetica-Bold', 8.4)
            c.drawCentredString(crest_cx, crest_cy - 1.55 * cm, 'ÉCOLE')

        center_x = ML + CW / 2 + 0.3 * cm
        c.setFillColor(colors.white)
        c.setFont('Helvetica-Bold', 22)
        c.drawCentredString(center_x, header_top - 1.35 * cm, title_main)
        c.setFillColor(GOLD_LIGHT)
        c.setFont('Helvetica-Bold', 11)
        c.drawCentredString(center_x, header_top - 1.95 * cm, subtitle_label.upper())
        sep_y = header_top - 2.35 * cm
        c.setStrokeColor(GOLD)
        c.setLineWidth(0.7)
        c.line(center_x - 2.9 * cm, sep_y, center_x - 0.35 * cm, sep_y)
        c.line(center_x + 0.35 * cm, sep_y, center_x + 2.9 * cm, sep_y)
        _bulletin_diamond(c, center_x, sep_y, 0.09 * cm, GOLD)
        pill_w, pill_h = 7.2 * cm, 0.68 * cm
        badge_txt, badge_size = _bulletin_fit_right_text(badge_text, 'Helvetica-Bold', pill_w - 0.6 * cm,
                                                          max_size=9.2, min_size=6.8)
        _bulletin_rounded_rect(c, center_x - pill_w / 2, sep_y - 0.35 * cm - pill_h, pill_w, pill_h,
                               pill_h / 2, fill=GOLD)
        c.setFillColor(NAVY)
        c.setFont('Helvetica-Bold', badge_size)
        c.drawCentredString(center_x, sep_y - 0.35 * cm - pill_h / 2 - 3, badge_txt)

        medal_cx = ML + CW - 2.05 * cm
        medal_cy = header_bot + header_h / 2 + 0.25 * cm
        _bulletin_draw_medallion(c, medal_cx, medal_cy, 1.55 * cm, medallion_lines,
                                 tail_bottom_y=header_bot - 1.0 * cm)
    return header_bot


def _doc_identity_card(c, ML, CW, card_top, card_h, initials, photo_path, nom_complet, info_lines,
                        stat_labels, note_title, note_body, note_footer=None):
    """Carte d'identité premium générique — même dessin que la carte d'identité élève du bulletin
    scolaire (avatar rond cerclé d'or, informations, indicateurs chiffrés, encart texte à droite).
    Retourne card_bot (bas de la carte)."""
    from reportlab.lib import colors
    from reportlab.platypus import Paragraph
    from reportlab.lib.styles import ParagraphStyle
    GOLD = colors.HexColor(_BULLETIN_GOLD)
    CREAM = colors.HexColor(_BULLETIN_CREAM)
    BORDER = colors.HexColor(_BULLETIN_BORDER)
    TEXT_DARK = colors.HexColor(_BULLETIN_TEXT_DARK)
    TEXT_MUTED = colors.HexColor(_BULLETIN_TEXT_MUTED)

    card_bot = card_top - card_h
    _bulletin_rounded_rect(c, ML, card_bot, CW, card_h, 0.3 * cm, fill=CREAM, stroke=BORDER, lw=0.8)

    photo_r = 1.6 * cm
    photo_cx = ML + 0.5 * cm + photo_r
    photo_cy = card_bot + card_h / 2
    _bulletin_draw_avatar(c, photo_cx, photo_cy, photo_r, image_path=photo_path, initials=initials)

    info_x = photo_cx + photo_r + 0.5 * cm
    c.setFillColor(TEXT_DARK)
    c.setFont('Helvetica-Bold', 9.5)
    # 🔄 Nom en plus petit sur la facture/reçu et les bulletins de paie (demande explicite :
    # le nom ne doit pas dominer visuellement la carte d'identité sur ces documents).
    nom_txt, nom_size = _bulletin_fit_right_text(nom_complet.upper(), 'Helvetica-Bold',
                                                 10.0 * cm, max_size=9.5, min_size=7.0)
    c.setFont('Helvetica-Bold', nom_size)
    c.drawString(info_x, card_top - 0.8 * cm, nom_txt)
    # 🩹 FIX chevauchement (« nom du parent / montant croisés ») : la largeur disponible pour
    # la valeur (ex: nom du parent, description) était fixée à 7.3cm, ce qui débordait très
    # largement sur la colonne des montants (qui commence à ML+10.55cm) et sur l'encart de
    # droite. On borne désormais la largeur au véritable espace disponible avant cette colonne.
    stat_x = ML + 10.55 * cm
    val_max_w = (stat_x - 0.35 * cm) - (info_x + 2.55 * cm)
    ly = card_top - 1.5 * cm
    for label, val in info_lines:
        c.setFillColor(TEXT_MUTED)
        c.setFont('Helvetica', 7.9)
        c.drawString(info_x, ly, f'{label} :')
        c.setFillColor(TEXT_DARK)
        val_txt, val_size = _bulletin_fit_right_text(str(val), 'Helvetica-Bold', val_max_w,
                                                      max_size=8.1, min_size=6.0)
        c.setFont('Helvetica-Bold', val_size)
        c.drawString(info_x + 2.55 * cm, ly, val_txt)
        ly -= 0.48 * cm

    sy = card_top - 0.55 * cm
    for label, val, col in stat_labels:
        c.setFillColor(TEXT_MUTED)
        c.setFont('Helvetica', 7.6)
        c.drawString(stat_x, sy, label)
        c.setFillColor(col)
        c.setFont('Helvetica-Bold', 13.5)
        c.drawString(stat_x, sy - 0.6 * cm, val)
        sy -= 1.35 * cm

    app_x = ML + 13.85 * cm
    app_w = CW - 13.85 * cm - 0.3 * cm
    _bulletin_rounded_rect(c, app_x, card_bot + 0.3 * cm, app_w, card_h - 0.6 * cm, 0.22 * cm,
                           fill=colors.white, stroke=BORDER, lw=0.7)
    c.setFillColor(GOLD)
    c.setFont('Helvetica-Bold', 8.3)
    c.drawString(app_x + 0.3 * cm, card_top - 0.65 * cm, note_title)
    style_app = ParagraphStyle('appDoc', fontName='Helvetica', fontSize=8.0, leading=11.2, textColor=TEXT_DARK)
    para = Paragraph(note_body, style_app)
    pw, ph = para.wrap(app_w - 0.6 * cm, card_h)
    para.drawOn(c, app_x + 0.3 * cm, card_top - 0.95 * cm - ph)
    # 🩹 FIX « Cachet & signature de l'établissement » qui débordait de son cadre : ce libellé
    # est désormais centré, sur une police réduite et automatiquement réparti sur deux lignes
    # si besoin (au lieu d'une seule ligne qui dépassait la largeur de l'encart), tout en
    # restant entièrement contenu dans le cadre blanc.
    from xml.sax.saxutils import escape as _xml_escape_footer
    from reportlab.lib.enums import TA_CENTER
    footer_line_y = card_bot + 0.85 * cm
    c.setStrokeColor(colors.HexColor('#D8D2BE'))
    c.setLineWidth(0.6)
    c.line(app_x + 0.3 * cm, footer_line_y, app_x + app_w - 0.3 * cm, footer_line_y)
    footer_txt = _xml_escape_footer(note_footer or 'La Direction')
    style_footer = ParagraphStyle('footerDoc', fontName='Helvetica', fontSize=6.6, leading=7.6,
                                  textColor=TEXT_MUTED, alignment=TA_CENTER)
    para_footer = Paragraph(footer_txt, style_footer)
    footer_w = app_w - 0.6 * cm
    fw, fh = para_footer.wrap(footer_w, card_h)
    # Sécurité supplémentaire : si le texte est encore trop long pour tenir sur 2 lignes dans
    # l'espace restant (cas extrême), on réduit encore la police jusqu'à ce qu'il rentre.
    min_footer_size = 6.6
    while fh > (footer_line_y - (card_bot + 0.22 * cm)) and min_footer_size > 5.0:
        min_footer_size -= 0.3
        style_footer = ParagraphStyle('footerDoc', fontName='Helvetica', fontSize=min_footer_size,
                                      leading=min_footer_size + 1.0, textColor=TEXT_MUTED,
                                      alignment=TA_CENTER)
        para_footer = Paragraph(footer_txt, style_footer)
        fw, fh = para_footer.wrap(footer_w, card_h)
    para_footer.drawOn(c, app_x + 0.3 * cm, footer_line_y - 0.15 * cm - fh)
    return card_bot


def _doc_finance_table(c, ML, CW, table_top, headers, rows, col_w, total_row=None, row_styles=None, boxes=None):
    """Tableau financier premium — même style visuel que le tableau des évaluations du bulletin
    scolaire (en-tête bleu marine, lignes zébrées crème, ligne TOTAL en marine).

    🆕 row_styles (optionnel) : dict {index_ligne (0-based dans `rows`, hors en-tête/total): style}
    permettant d'habiller une ligne précise — utilisé pour teinter en fond très pâle les blocs
    "Scolarité" / "Transport" (les séparer visuellement) et pour afficher les lignes de
    réduction en gris discret/italique ("presque invisible") plutôt qu'en texte normal.
    Clés de style supportées : 'bg' (fond, hex), 'text_color' (texte, hex), 'italic' (bool),
    'bold' (bool), 'font_size' (float).

    🆕 boxes (optionnel) : liste de tuples (idx_debut, idx_fin) — 0-based dans `rows` — pour
    encadrer d'un contour noir gras un petit groupe de lignes (ex : le bloc "Frais de
    scolarité / Réduction / Total après réduction"), afin de bien le distinguer visuellement
    comme un mini-tableau à part entière.

    Retourne la hauteur totale dessinée (th)."""
    from reportlab.lib import colors
    from reportlab.platypus import Table, TableStyle
    NAVY = colors.HexColor(_BULLETIN_NAVY)
    data = [headers] + rows + ([total_row] if total_row else [])
    t = Table(data, colWidths=col_w, repeatRows=1)
    last_body_row = len(data) - (2 if total_row else 1)
    style_cmds = [
        ('BACKGROUND', (0, 0), (-1, 0), NAVY),
        ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
        ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
        ('FONTSIZE', (0, 0), (-1, 0), 8.8),
        ('ROWBACKGROUNDS', (0, 1), (-1, last_body_row), [colors.white, colors.HexColor('#F6F2E7')]),
        ('GRID', (0, 0), (-1, -1), 0.4, colors.HexColor('#E7E2D3')),
        ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
        ('FONTSIZE', (0, 1), (-1, -1), 8.6),
        ('TOPPADDING', (0, 0), (-1, -1), 7.5), ('BOTTOMPADDING', (0, 0), (-1, -1), 7.5),
        ('ALIGN', (-1, 0), (-1, -1), 'RIGHT'),
    ]
    if row_styles:
        for _idx, _st in row_styles.items():
            _r = _idx + 1  # +1 car la ligne d'en-tête occupe l'index 0 du tableau
            if _r < 1 or _r > last_body_row:
                continue
            if 'bg' in _st:
                style_cmds.append(('BACKGROUND', (0, _r), (-1, _r), colors.HexColor(_st['bg'])))
            if 'text_color' in _st:
                style_cmds.append(('TEXTCOLOR', (0, _r), (-1, _r), colors.HexColor(_st['text_color'])))
            if _st.get('italic'):
                _fontname = 'Helvetica-Oblique'
            elif _st.get('bold'):
                _fontname = 'Helvetica-Bold'
            else:
                _fontname = 'Helvetica'
            style_cmds.append(('FONTNAME', (0, _r), (-1, _r), _fontname))
            if 'font_size' in _st:
                style_cmds.append(('FONTSIZE', (0, _r), (-1, _r), _st['font_size']))
    if boxes:
        for _b_start, _b_end in boxes:
            _r0 = _b_start + 1
            _r1 = _b_end + 1
            if _r0 < 1 or _r1 > last_body_row or _r0 > _r1:
                continue
            style_cmds.append(('BOX', (0, _r0), (-1, _r1), 1.3, colors.black))
    if total_row:
        style_cmds += [
            ('BACKGROUND', (0, -1), (-1, -1), NAVY),
            ('TEXTCOLOR', (0, -1), (-1, -1), colors.white),
            ('FONTNAME', (0, -1), (-1, -1), 'Helvetica-Bold'),
            ('FONTSIZE', (0, -1), (-1, -1), 9.4),
        ]
    t.setStyle(TableStyle(style_cmds))
    tw, th = t.wrap(CW, 0)
    t.drawOn(c, ML, table_top - th)
    return th


def _doc_info_panel(c, ML, CW, panel_top, panel_h, title, lines):
    """Encart d'informations complémentaires premium — même style que le bloc "Observations des
    enseignants" du bulletin scolaire (carte blanche, titre marine centré, contenu en colonnes)."""
    from reportlab.lib import colors
    NAVY = colors.HexColor(_BULLETIN_NAVY)
    BORDER = colors.HexColor(_BULLETIN_BORDER)
    TEXT_DARK = colors.HexColor(_BULLETIN_TEXT_DARK)
    TEXT_MUTED = colors.HexColor(_BULLETIN_TEXT_MUTED)
    _bulletin_rounded_rect(c, ML, panel_top - panel_h, CW, panel_h, 0.25 * cm,
                           fill=colors.white, stroke=BORDER, lw=0.7)
    c.setFillColor(NAVY)
    c.setFont('Helvetica-Bold', 9.4)
    c.drawCentredString(ML + CW / 2, panel_top - 0.5 * cm, title)
    col_w = CW / max(1, len(lines))
    for idx, (label, val) in enumerate(lines):
        cx = ML + idx * col_w + 0.35 * cm
        c.setFillColor(TEXT_MUTED)
        c.setFont('Helvetica', 7.6)
        c.drawString(cx, panel_top - 1.05 * cm, label)
        c.setFillColor(TEXT_DARK)
        c.setFont('Helvetica-Bold', 8.6)
        c.drawString(cx, panel_top - 1.45 * cm, str(val)[:32])


def _doc_signature_block(c, ML, CW, y_top, labels):
    """Bloc(s) de signature premium — même présentation discrète que le bulletin scolaire
    (ligne fine + libellé), avec 1 à 3 signatures côte à côte selon le document."""
    from reportlab.lib import colors
    TEXT_MUTED = colors.HexColor(_BULLETIN_TEXT_MUTED)
    BORDER = colors.HexColor(_BULLETIN_BORDER)
    n = len(labels)
    col_w = CW / n
    c.setStrokeColor(BORDER)
    c.setLineWidth(0.6)
    for i, label in enumerate(labels):
        x0 = ML + i * col_w + 0.4 * cm
        x1 = ML + (i + 1) * col_w - 0.4 * cm
        c.line(x0, y_top, x1, y_top)
        c.setFillColor(TEXT_MUTED)
        c.setFont('Helvetica', 8)
        c.drawCentredString((x0 + x1) / 2, y_top - 0.4 * cm, label)


def _doc_quote_bandeau(c, ML, CW, quote_text, quote_y=1.15 * cm):
    """Bandeau de citation + pied de page — EXACTEMENT le même bandeau marine/or que celui du
    bas du bulletin scolaire, réutilisé pour garder la cohérence visuelle jusqu'au bas de page.
    `quote_y` (bas du bandeau) est ajustable pour les documents plus courts que le bulletin, afin
    de ne pas laisser un grand vide entre le contenu et la citation — jamais en dessous de 1.15cm
    du bas de page, pour ne jamais chevaucher le pied de page."""
    from reportlab.lib import colors
    NAVY = colors.HexColor(_BULLETIN_NAVY)
    GOLD_LIGHT = colors.HexColor(_BULLETIN_GOLD_LIGHT)
    TEXT_MUTED = colors.HexColor(_BULLETIN_TEXT_MUTED)
    quote_h = 1.05 * cm
    quote_y = max(quote_y, 1.15 * cm)
    _bulletin_rounded_rect(c, ML, quote_y, CW, quote_h, 0.2 * cm, fill=NAVY)
    c.setFillColor(GOLD_LIGHT)
    c.setFont('Helvetica-Oblique', 8.6)
    c.drawCentredString(ML + CW / 2, quote_y + quote_h / 2 - 3, quote_text)
    c.setFillColor(TEXT_MUTED)
    c.setFont('Helvetica', 7)
    c.drawString(ML, 0.55 * cm, f"Généré le {datetime.datetime.now().strftime('%d/%m/%Y à %H:%M')}")
    c.drawRightString(ML + CW, 0.55 * cm, "Page 1")


@app.route('/export/bulletin/<int:eleve_id>')
@login_required
def export_bulletin_pdf(eleve_id):
    # 🔒 Un enseignant ne doit voir que les notes de sa propre matière : le bulletin complet
    # contient TOUTES les matières (donc celles des autres enseignants), il lui est donc fermé.
    if session.get('role') == 'enseignant':
        flash("Accès non autorisé : le bulletin complet n'est pas accessible aux enseignants.", 'error')
        return redirect(url_for('gestion_notes'))
    try:
        from reportlab.lib.pagesizes import A4
        from reportlab.lib import colors
        from reportlab.platypus import Table, TableStyle, Paragraph
        from reportlab.lib.styles import ParagraphStyle
        from reportlab.lib.units import cm
        from reportlab.pdfgen import canvas as pdfcanvas

        NAVY = colors.HexColor(_BULLETIN_NAVY)
        NAVY_LIGHT = colors.HexColor(_BULLETIN_NAVY_LIGHT)
        GOLD = colors.HexColor(_BULLETIN_GOLD)
        GOLD_LIGHT = colors.HexColor(_BULLETIN_GOLD_LIGHT)
        CREAM = colors.HexColor(_BULLETIN_CREAM)
        BORDER = colors.HexColor(_BULLETIN_BORDER)
        TEXT_DARK = colors.HexColor(_BULLETIN_TEXT_DARK)
        TEXT_MUTED = colors.HexColor(_BULLETIN_TEXT_MUTED)
        GREEN = colors.HexColor(_BULLETIN_GREEN)

        conn = get_db()
        eleve = conn.execute(
            "SELECT e.*, c.nom as classe, c.niveau as niveau, c.cycle as cycle, c.id as classe_id "
            "FROM eleves e LEFT JOIN classes c ON e.classe_id=c.id WHERE e.id=?",
            (eleve_id,)).fetchone()
        if not eleve:
            conn.close()
            return "Élève non trouvé", 404
        if session['role'] == 'parent' and eleve['parent_id'] != session['user_id']:
            conn.close()
            return "Accès refusé", 403

        # 🆕 Système de notation du cycle de l'élève (lettres A/B/C, /10 ou /20)
        sys_b = get_systeme_notes(eleve['cycle'] or 'Primaire', conn)
        ech_b = libelle_echelle_sys(sys_b)

        trimestre = request.args.get('t', '1')
        notes = conn.execute(
            "SELECT n.note, n.commentaire, m.id as matiere_id, m.nom as matiere, m.coefficient, "
            "sm.nom as sous_matiere, sm.coefficient as sm_coefficient "
            "FROM notes n JOIN matieres m ON n.matiere_id=m.id "
            "LEFT JOIN sous_matieres sm ON n.sous_matiere_id = sm.id "
            "WHERE n.eleve_id=? AND n.trimestre=? ORDER BY m.nom, sm.ordre, sm.nom",
            (eleve_id, trimestre)).fetchall()

        # 🆕 Classement dans la classe pour CE trimestre (cohérent avec les données affichées
        # sur le bulletin, plutôt que le classement cumulé toute l'année utilisé sur la fiche élève)
        rang, total_classe = None, None
        if eleve['classe_id']:
            classement = conn.execute("""
                SELECT e.id,
                       SUM(y.matiere_moy * y.coef_matiere) * 1.0 / NULLIF(SUM(y.coef_matiere), 0) AS moyenne
                FROM eleves e
                LEFT JOIN (
                    SELECT eleve_id, matiere_id, coef_matiere,
                           SUM(note * coef_sm) * 1.0 / NULLIF(SUM(coef_sm), 0) AS matiere_moy
                    FROM (
                        SELECT n.eleve_id, n.matiere_id, m.coefficient AS coef_matiere, n.note,
                               COALESCE(sm.coefficient, 1) AS coef_sm
                        FROM notes n
                        JOIN matieres m ON m.id = n.matiere_id
                        LEFT JOIN sous_matieres sm ON sm.id = n.sous_matiere_id
                        WHERE n.trimestre = ?
                    ) raw
                    GROUP BY eleve_id, matiere_id, coef_matiere
                ) y ON y.eleve_id = e.id
                WHERE e.classe_id = ?
                GROUP BY e.id
                HAVING moyenne IS NOT NULL
                ORDER BY moyenne DESC
            """, (trimestre, eleve['classe_id'])).fetchall()
            total_classe = conn.execute("SELECT COUNT(*) as n FROM eleves WHERE classe_id=?",
                                        (eleve['classe_id'],)).fetchone()['n']
            for i, row in enumerate(classement, start=1):
                if row['id'] == eleve_id:
                    rang = i
                    break

        # 🆕 Évolution T1 → T2 (mêmes formules que la fiche élève / le tableau de bord)
        evol_valeurs = []
        for t in (1, 2):
            notes_t = conn.execute(
                "SELECT n.*, m.nom as matiere, m.coefficient, sm.coefficient as sm_coefficient "
                "FROM notes n JOIN matieres m ON n.matiere_id=m.id "
                "LEFT JOIN sous_matieres sm ON n.sous_matiere_id = sm.id "
                "WHERE n.eleve_id=? AND n.trimestre=?", (eleve_id, t)).fetchall()
            if notes_t:
                moy_t, _ = _moyenne_ponderee_matieres(notes_t)
                evol_valeurs.append(round(moy_t, 2))
            else:
                evol_valeurs.append(None)

        # 🆕 Absences / retards (comptage factuel — aucun pourcentage inventé faute de nombre
        # de jours de classe suivi précisément dans l'app)
        nb_absences = conn.execute("SELECT COUNT(*) as n FROM absences WHERE eleve_id=?",
                                   (eleve_id,)).fetchone()['n']
        nb_retards = conn.execute("SELECT COUNT(*) as n FROM retards WHERE eleve_id=?",
                                  (eleve_id,)).fetchone()['n']

        photo_path = None
        if eleve['photo']:
            candidate = os.path.join(UPLOAD_FOLDER_PHOTOS, eleve['photo'])
            if os.path.exists(candidate):
                photo_path = candidate
        logo_path = None
        logo_fn = get_logo_filename()
        if logo_fn:
            candidate = os.path.join(UPLOAD_FOLDER_LOGO, logo_fn)
            if os.path.exists(candidate):
                logo_path = candidate

        # 🆕 Bannière personnalisée de l'école (remplace le bandeau bleu marine si uploadée)
        banniere_path = None
        banniere_fn = get_banniere_bulletin_filename()
        if banniere_fn:
            candidate = os.path.join(UPLOAD_FOLDER_LOGO, banniere_fn)
            if os.path.exists(candidate):
                banniere_path = candidate

        # 🆕 Appréciation générale (admin/agent-admin) & observations des enseignants (enseignant)
        # saisies manuellement pour ce trimestre — utilisées à la place du texte auto-généré.
        appr_row = conn.execute(
            "SELECT appreciation_generale, observation_enseignant FROM bulletin_appreciations WHERE eleve_id=? AND trimestre=?",
            (eleve_id, trimestre)).fetchone()
        appreciation_manuelle = (appr_row['appreciation_generale'] or '').strip() if appr_row else ''
        observation_manuelle = (appr_row['observation_enseignant'] or '').strip() if appr_row else ''

        conn.close()

        buf = io.BytesIO()
        c = pdfcanvas.Canvas(buf, pagesize=A4)
        W, H = A4
        ML = 1.2 * cm
        CW = W - 2 * ML

        # ═══ 1) BANDEAU D'EN-TÊTE ═══
        header_h = 3.9 * cm
        header_top = H - ML
        header_bot = header_top - header_h
        if banniere_path:
            # 🆕 Bannière personnalisée de l'école : remplace entièrement le bandeau bleu marine
            # par la photo/bannière uploadée depuis "Mon profil", en mode "cover" (remplit tout
            # le bandeau, sans bande vide, recadrée si nécessaire) et respecte les coins arrondis.
            c.saveState()
            p = c.beginPath()
            p.roundRect(ML, header_bot, CW, header_h, 0.35 * cm)
            c.clipPath(p, stroke=0, fill=0)
            try:
                img = _bulletin_safe_image(banniere_path)
                iw, ih = img.getSize()
                scale = max(CW / iw, header_h / ih)
                dw, dh = iw * scale, ih * scale
                dx = ML + (CW - dw) / 2
                dy = header_bot + (header_h - dh) / 2
                c.drawImage(img, dx, dy, width=dw, height=dh, preserveAspectRatio=True, mask='auto')
            except Exception:
                c.setFillColor(NAVY)
                c.rect(ML, header_bot, CW, header_h, stroke=0, fill=1)
            c.restoreState()
        else:
            _bulletin_rounded_rect(c, ML, header_bot, CW, header_h, 0.35 * cm, fill=NAVY)
            c.saveState()
            p = c.beginPath()
            p.roundRect(ML, header_bot, CW, header_h, 0.35 * cm)
            c.clipPath(p, stroke=0, fill=0)
            c.setFillColor(NAVY_LIGHT)
            c.rect(ML, header_top - 0.06 * cm, CW, 0.06 * cm, stroke=0, fill=1)
            c.restoreState()

            crest_cx = ML + 2.0 * cm
            crest_cy = header_bot + header_h / 2 + 0.15 * cm
            _bulletin_draw_crest(c, crest_cx, crest_cy, 2.6 * cm, logo_path=logo_path)
            if not logo_path:
                c.setFillColor(colors.white)
                c.setFont('Helvetica-Bold', 8.4)
                c.drawCentredString(crest_cx, crest_cy - 1.55 * cm, 'ÉCOLE')

            center_x = ML + CW / 2 + 0.3 * cm
            c.setFillColor(colors.white)
            c.setFont('Helvetica-Bold', 25)
            c.drawCentredString(center_x, header_top - 1.35 * cm, 'BULLETIN SCOLAIRE')
            c.setFillColor(GOLD_LIGHT)
            c.setFont('Helvetica-Bold', 11.5)
            cycle_label = f"ENSEIGNEMENT {(eleve['cycle'] or 'SCOLAIRE').upper()}"
            c.drawCentredString(center_x, header_top - 1.95 * cm, cycle_label)
            sep_y = header_top - 2.35 * cm
            c.setStrokeColor(GOLD)
            c.setLineWidth(0.7)
            c.line(center_x - 2.6 * cm, sep_y, center_x - 0.35 * cm, sep_y)
            c.line(center_x + 0.35 * cm, sep_y, center_x + 2.6 * cm, sep_y)
            _bulletin_diamond(c, center_x, sep_y, 0.09 * cm, GOLD)
            pill_w, pill_h = 5.4 * cm, 0.68 * cm
            _bulletin_rounded_rect(c, center_x - pill_w / 2, sep_y - 0.35 * cm - pill_h, pill_w, pill_h,
                                   pill_h / 2, fill=GOLD)
            c.setFillColor(NAVY)
            c.setFont('Helvetica-Bold', 9.2)
            c.drawCentredString(center_x, sep_y - 0.35 * cm - pill_h / 2 - 3,
                                f'ANNÉE SCOLAIRE {_bulletin_annee_scolaire()}')

            medal_cx = ML + CW - 2.05 * cm
            medal_cy = header_bot + header_h / 2 + 0.25 * cm
            _bulletin_draw_medallion(c, medal_cx, medal_cy, 1.55 * cm,
                                     [('EXCELLENCE', True), ('&', False), ('BIENVEILLANCE', True)],
                                     tail_bottom_y=header_bot - 1.0 * cm)

        # ═══ 2) CARTE D'IDENTITÉ ═══
        card_top = header_bot - 0.35 * cm
        card_h = 5.0 * cm
        card_bot = card_top - card_h
        _bulletin_rounded_rect(c, ML, card_bot, CW, card_h, 0.3 * cm, fill=CREAM, stroke=BORDER, lw=0.8)

        photo_r = 1.6 * cm
        photo_cx = ML + 0.5 * cm + photo_r
        photo_cy = card_bot + card_h / 2
        initials = (eleve['prenom'][:1] + eleve['nom'][:1]) if eleve['prenom'] else '?'
        _bulletin_draw_avatar(c, photo_cx, photo_cy, photo_r, image_path=photo_path, initials=initials)

        info_x = photo_cx + photo_r + 0.5 * cm
        c.setFillColor(TEXT_DARK)
        # 🩹 Nom/prénom de l'élève réduit (était 14.5 — trop grand, débordait sur certains
        # noms longs à côté de la photo)
        c.setFont('Helvetica-Bold', 11.5)
        c.drawString(info_x, card_top - 0.8 * cm, f"{eleve['prenom']} {eleve['nom']}".upper())
        info_lines = [
            ('Né(e) le', _bulletin_date_fr(eleve['date_naissance']) or '—'),
            ('Niveau', eleve['niveau'] or '—'),
            ('Classe', eleve['classe'] or '—'),
            ('Effectif classe', f"{total_classe} élèves" if total_classe else '—'),
        ]
        ly = card_top - 1.5 * cm
        for label, val in info_lines:
            c.setFillColor(TEXT_MUTED)
            c.setFont('Helvetica', 7.9)
            c.drawString(info_x, ly, f'{label} :')
            c.setFillColor(TEXT_DARK)
            c.setFont('Helvetica-Bold', 8.1)
            c.drawString(info_x + 2.55 * cm, ly, str(val))
            ly -= 0.48 * cm

        moyenne_generale = evol_valeurs[int(trimestre) - 1] if trimestre in ('1', '2') else None
        assiduite_label = f"{nb_absences} absence{'s' if nb_absences > 1 else ''}"
        assiduite_color = GREEN if nb_absences == 0 else (colors.HexColor(_BULLETIN_AMBER) if nb_absences <= 5 else colors.HexColor(_BULLETIN_RED))

        stat_x = ML + 10.55 * cm
        stat_labels = [
            ('Moyenne générale', fmt_moy_sys(moyenne_generale, sys_b),
             _bulletin_note_color(moyenne_generale)),
            ('Rang', f"{rang}e/{total_classe}" if rang else '—', NAVY),
            ('Assiduité', assiduite_label, assiduite_color),
        ]
        sy = card_top - 0.55 * cm
        for label, val, col in stat_labels:
            c.setFillColor(TEXT_MUTED)
            c.setFont('Helvetica', 7.6)
            c.drawString(stat_x, sy, label)
            c.setFillColor(col)
            c.setFont('Helvetica-Bold', 14)
            c.drawString(stat_x, sy - 0.6 * cm, val)
            sy -= 1.35 * cm

        app_x = ML + 13.85 * cm
        app_w = CW - 13.85 * cm - 0.3 * cm
        _bulletin_rounded_rect(c, app_x, card_bot + 0.3 * cm, app_w, card_h - 0.6 * cm, 0.22 * cm,
                               fill=colors.white, stroke=BORDER, lw=0.7)
        c.setFillColor(GOLD)
        c.setFont('Helvetica-Bold', 8.3)
        c.drawString(app_x + 0.3 * cm, card_top - 0.65 * cm, 'APPRÉCIATION GÉNÉRALE')
        appr_generale = _bulletin_appreciation(moyenne_generale)
        if appreciation_manuelle:
            # 🆕 Priorité au texte saisi manuellement par l'admin/agent-admin (page Notes de la
            # fiche élève) sur le texte auto-généré à partir de la moyenne.
            from xml.sax.saxutils import escape as _xml_escape
            txt_appr = _xml_escape(appreciation_manuelle).replace('\n', '<br/>')
        elif moyenne_generale is None:
            txt_appr = "Aucune note enregistrée pour ce trimestre."
        elif moyenne_generale >= 14:
            txt_appr = f"{eleve['prenom']} obtient d'excellents résultats ce trimestre ({appr_generale.lower()}), avec sérieux et régularité. Continuez ainsi !"
        elif moyenne_generale >= 10:
            txt_appr = f"{eleve['prenom']} obtient des résultats {appr_generale.lower()} ce trimestre. Des efforts réguliers permettront de progresser encore."
        else:
            txt_appr = f"Ce trimestre reste difficile pour {eleve['prenom']}. Un accompagnement rapproché est recommandé pour consolider les bases."
        style_app = ParagraphStyle('app', fontName='Helvetica', fontSize=8.0, leading=10.8, textColor=TEXT_DARK)
        para = Paragraph(txt_appr, style_app)
        pw, ph = para.wrap(app_w - 0.6 * cm, card_h)
        para.drawOn(c, app_x + 0.3 * cm, card_top - 0.95 * cm - ph)
        c.setStrokeColor(colors.HexColor('#D8D2BE'))
        c.setLineWidth(0.6)
        c.line(app_x + 0.3 * cm, card_bot + 0.75 * cm, app_x + app_w - 0.3 * cm, card_bot + 0.75 * cm)
        c.setFillColor(TEXT_MUTED)
        c.setFont('Helvetica', 7.6)
        c.drawString(app_x + 0.3 * cm, card_bot + 0.55 * cm, 'La Direction')

        # ═══ 3) TABLEAU DES ÉVALUATIONS ═══
        table_top = card_bot - 0.4 * cm
        headers = ['Matière', 'Moyenne ' + ech_b, 'Coeff.', 'Moyenne pondérée', 'Appréciation']
        data = [headers]
        row_is_detail = []
        observations = []
        if observation_manuelle:
            # 🆕 Observation générale saisie manuellement (admin ou enseignant, page Notes de la
            # fiche élève) — affichée en premier dans le bloc "Observations des enseignants".
            from xml.sax.saxutils import escape as _xml_escape_obs
            observations.append({'matiere': 'Observation générale',
                                 'texte': _xml_escape_obs(observation_manuelle)})
        if notes:
            par_matiere = {}
            for n in notes:
                d = par_matiere.setdefault(n['matiere_id'], {
                    'nom': n['matiere'], 'coefficient': n['coefficient'] or 1, 'pts': 0.0,
                    'coef_sum': 0.0, 'details': [], 'commentaires': []
                })
                coef_sm = n['sm_coefficient'] if (n['sous_matiere'] and n['sm_coefficient']) else 1
                d['pts'] += n['note'] * coef_sm
                d['coef_sum'] += coef_sm
                d['details'].append(n)
                if n['commentaire']:
                    d['commentaires'].append(n['commentaire'])

            total_pts = total_coef = 0.0
            for mat_id, d in sorted(par_matiere.items(), key=lambda kv: kv[1]['nom']):
                moy_matiere = d['pts'] / d['coef_sum'] if d['coef_sum'] else 0
                data.append([d['nom'], fmt_moy_sys(moy_matiere, sys_b, 2, False), str(d['coefficient']),
                            ('' if sys_b == 'lettres' else f"{conv_note_sys(moy_matiere, sys_b) * d['coefficient']:.2f}"),
                            _bulletin_appreciation(moy_matiere)])
                if any(n['sous_matiere'] for n in d['details']):
                    for n in d['details']:
                        if n['sous_matiere']:
                            data.append([f"   · {n['sous_matiere']}", fmt_moy_sys(n['note'], sys_b, 2, False),
                                        f"(coef {n['sm_coefficient'] or 1:g})", '', n['commentaire'] or ''])
                            row_is_detail.append(len(data) - 1)
                total_pts += moy_matiere * d['coefficient']
                total_coef += d['coefficient']
                if d['commentaires']:
                    observations.append({'matiere': d['nom'], 'texte': '; '.join(d['commentaires'])})
            data.append(['TOTAL', '', f"{total_coef:g}",
                         ('' if sys_b == 'lettres' else f"{conv_note_sys(total_pts, sys_b):.2f}"), ''])

            col_w = [5.5 * cm, 3.0 * cm, 2.3 * cm, 3.8 * cm, 4.0 * cm]
            t = Table(data, colWidths=col_w, repeatRows=1)
            style_cmds = [
                ('BACKGROUND', (0, 0), (-1, 0), NAVY),
                ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
                ('FONTNAME', (0, 0), (-1, 0), 'Helvetica-Bold'),
                ('FONTSIZE', (0, 0), (-1, 0), 8.6),
                ('BACKGROUND', (0, -1), (-1, -1), NAVY),
                ('TEXTCOLOR', (0, -1), (-1, -1), colors.white),
                ('FONTNAME', (0, -1), (-1, -1), 'Helvetica-Bold'),
                ('ROWBACKGROUNDS', (0, 1), (-1, -2), [colors.white, colors.HexColor('#F6F2E7')]),
                ('GRID', (0, 0), (-1, -1), 0.4, colors.HexColor('#E7E2D3')),
                ('ALIGN', (1, 0), (3, -1), 'CENTER'),
                ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
                ('FONTSIZE', (0, 1), (-1, -1), 8.2),
                ('TOPPADDING', (0, 0), (-1, -1), 5.5), ('BOTTOMPADDING', (0, 0), (-1, -1), 5.5),
            ]
            for ridx in row_is_detail:
                style_cmds.append(('FONTSIZE', (0, ridx), (-1, ridx), 7.3))
                style_cmds.append(('TEXTCOLOR', (0, ridx), (-1, ridx), TEXT_MUTED))
            t.setStyle(TableStyle(style_cmds))
            tw, th = t.wrap(CW, 0)
            t.drawOn(c, ML, table_top - th)
        else:
            th = 1.2 * cm
            c.setFillColor(TEXT_MUTED)
            c.setFont('Helvetica-Oblique', 9)
            c.drawString(ML, table_top - 0.7 * cm, "Aucune note disponible pour ce trimestre.")

        # ═══ 4) TROIS CARTES (résumé / évolution / appréciations) ═══
        row2_top = table_top - th - 0.4 * cm
        row2_h = 4.7 * cm
        gap = 0.35 * cm
        card_w3 = (CW - 2 * gap) / 3

        moys_matieres = {d_['nom']: (d_['pts'] / d_['coef_sum'] if d_['coef_sum'] else 0) for d_ in par_matiere.values()} if notes else {}
        # (recalcul propre à partir de par_matiere pour éviter tout risque de parsing)
        meilleure_txt = plus_basse_txt = '—'
        if notes and par_matiere:
            moy_par_nom = {}
            for mat_id, d in par_matiere.items():
                moy_par_nom[d['nom']] = d['pts'] / d['coef_sum'] if d['coef_sum'] else 0
            if moy_par_nom:
                nom_max = max(moy_par_nom, key=lambda k: moy_par_nom[k])
                nom_min = min(moy_par_nom, key=lambda k: moy_par_nom[k])
                meilleure_txt = f"{nom_max} ({fmt_moy_sys(moy_par_nom[nom_max], sys_b, 2, False)})"
                plus_basse_txt = f"{nom_min} ({fmt_moy_sys(moy_par_nom[nom_min], sys_b, 2, False)})"

        x1 = ML
        _bulletin_rounded_rect(c, x1, row2_top - row2_h, card_w3, row2_h, 0.25 * cm,
                               fill=colors.white, stroke=BORDER, lw=0.7)
        c.setFillColor(NAVY)
        c.setFont('Helvetica-Bold', 9)
        c.drawString(x1 + 0.35 * cm, row2_top - 0.55 * cm, 'RÉSUMÉ DES RÉSULTATS')
        resume_rows = [
            ('Moyenne générale', fmt_moy_sys(moyenne_generale, sys_b), False),
            ('Rang', f"{rang}/{total_classe}" if rang else '—', False),
            ('Meilleure matière', meilleure_txt, True),
            ('Matière la plus faible', plus_basse_txt, True),
            ('Absences / Retards', f"{nb_absences} / {nb_retards}", False),
        ]
        ry = row2_top - 1.15 * cm
        for label, val, matiere_petite in resume_rows:
            c.setFillColor(TEXT_MUTED)
            c.setFont('Helvetica', 7.6)
            c.drawString(x1 + 0.35 * cm, ry, label)
            c.setFillColor(TEXT_DARK)
            if matiere_petite:
                # 🩹 Nom de matière : taille de police ajustée dynamiquement (et tronquée en
                # dernier recours avec "…") pour ne jamais chevaucher le libellé à gauche,
                # quelle que soit la longueur du nom de la matière.
                from reportlab.pdfbase.pdfmetrics import stringWidth
                label_w = stringWidth(label, 'Helvetica', 7.6)
                avail_w = (card_w3 - 0.7 * cm) - label_w - 0.15 * cm
                fitted_txt, fitted_size = _bulletin_fit_right_text(val, 'Helvetica-Bold', avail_w)
                c.setFont('Helvetica-Bold', fitted_size)
                c.drawRightString(x1 + card_w3 - 0.35 * cm, ry, fitted_txt)
            else:
                c.setFont('Helvetica-Bold', 8.4)
                c.drawRightString(x1 + card_w3 - 0.35 * cm, ry, str(val)[:26])
            ry -= 0.68 * cm

        x2 = x1 + card_w3 + gap
        _bulletin_rounded_rect(c, x2, row2_top - row2_h, card_w3, row2_h, 0.25 * cm,
                               fill=colors.white, stroke=BORDER, lw=0.7)
        c.setFillColor(NAVY)
        c.setFont('Helvetica-Bold', 9)
        c.drawString(x2 + 0.35 * cm, row2_top - 0.55 * cm, 'ÉVOLUTION DE LA MOYENNE')
        _bulletin_mini_line_chart(c, x2 + 0.15 * cm, row2_top - row2_h + 0.15 * cm,
                                  card_w3 - 0.3 * cm, row2_h - 0.8 * cm,
                                  ['Trimestre 1', 'Trimestre 2'], evol_valeurs,
                                  line_color=GOLD, area_color=colors.HexColor('#F3E6C4'), systeme=sys_b)

        x3 = x2 + card_w3 + gap
        _bulletin_rounded_rect(c, x3, row2_top - row2_h, card_w3, row2_h, 0.25 * cm,
                               fill=colors.white, stroke=BORDER, lw=0.7)
        c.setFillColor(NAVY)
        c.setFont('Helvetica-Bold', 9)
        c.drawString(x3 + 0.35 * cm, row2_top - 0.55 * cm, 'APPRÉCIATION PAR TRIMESTRE')
        ay = row2_top - 1.25 * cm
        for i, val in enumerate(evol_valeurs, start=1):
            appr = _bulletin_appreciation(val) if val is not None else 'En attente'
            col = _bulletin_note_color(val) if val is not None else TEXT_MUTED
            c.setFillColor(TEXT_DARK)
            c.setFont('Helvetica', 8.4)
            c.drawString(x3 + 0.35 * cm, ay, f'Trimestre {i}')
            c.setFillColor(col)
            c.setFont('Helvetica-Bold', 8.4)
            c.drawRightString(x3 + card_w3 - 0.35 * cm, ay, appr)
            ay -= 0.85 * cm

        # ═══ 5) OBSERVATIONS DES ENSEIGNANTS ═══
        import math as _math
        obs_top = row2_top - row2_h - 0.4 * cm
        n_obs = len(observations)
        obs_rows_count = _math.ceil(n_obs / 3) if n_obs else 1
        obs_h = 0.55 * cm + obs_rows_count * 1.05 * cm + 0.3 * cm
        _bulletin_rounded_rect(c, ML, obs_top - obs_h, CW, obs_h, 0.25 * cm,
                               fill=colors.white, stroke=BORDER, lw=0.7)
        c.setFillColor(NAVY)
        c.setFont('Helvetica-Bold', 9.4)
        c.drawCentredString(ML + CW / 2, obs_top - 0.5 * cm, 'OBSERVATIONS DES ENSEIGNANTS')
        if observations:
            col_w_obs = CW / 3
            for idx, obs in enumerate(observations):
                col_i = idx % 3
                row_i = idx // 3
                ox = ML + col_i * col_w_obs + 0.3 * cm
                oy = obs_top - 0.95 * cm - row_i * 1.05 * cm
                c.setFillColor(NAVY)
                c.setFont('Helvetica-Bold', 8.2)
                c.drawString(ox, oy, obs['matiere'])
                style_obs = ParagraphStyle('obs', fontName='Helvetica', fontSize=7.4, leading=9.4,
                                           textColor=TEXT_MUTED)
                p2 = Paragraph(obs['texte'], style_obs)
                pw2, ph2 = p2.wrap(col_w_obs - 0.6 * cm, 1 * cm)
                p2.drawOn(c, ox, oy - 0.15 * cm - ph2)
        else:
            c.setFillColor(TEXT_MUTED)
            c.setFont('Helvetica-Oblique', 8.2)
            c.drawCentredString(ML + CW / 2, obs_top - 1.0 * cm,
                                "Aucune observation enregistrée pour ce trimestre.")

        # ═══ 6) BANDEAU DE CITATION ═══
        quote_h = 1.05 * cm
        quote_y = 1.15 * cm
        _bulletin_rounded_rect(c, ML, quote_y, CW, quote_h, 0.2 * cm, fill=NAVY)
        c.setFillColor(GOLD_LIGHT)
        c.setFont('Helvetica-Oblique', 8.6)
        c.drawCentredString(ML + CW / 2, quote_y + quote_h / 2 - 3,
                            "« L'éducation est l'arme la plus puissante pour changer le monde. » — Nelson Mandela")

        c.setFillColor(TEXT_MUTED)
        c.setFont('Helvetica', 7)
        c.drawString(ML, 0.55 * cm, f"Généré le {datetime.datetime.now().strftime('%d/%m/%Y à %H:%M')}")
        c.drawRightString(ML + CW, 0.55 * cm, "Page 1")

        # ═══ 7) 🆕 PAGE 2 — ANALYSE GRAPHIQUE DES MATIÈRES (courbe + cercles) ═══
        # Uniquement si des notes existent pour ce trimestre (sinon rien à analyser).
        if notes and par_matiere:
            c.showPage()
            import math as _math2

            # -- 7a) Bandeau d'en-tête (même identité visuelle, format réduit) --
            head2_h = 2.3 * cm
            head2_top = H - ML
            head2_bot = head2_top - head2_h
            _bulletin_rounded_rect(c, ML, head2_bot, CW, head2_h, 0.3 * cm, fill=NAVY)
            c.setFillColor(colors.white)
            c.setFont('Helvetica-Bold', 16.5)
            c.drawString(ML + 0.6 * cm, head2_top - 1.05 * cm, 'ANALYSE DES MATIÈRES')
            c.setFillColor(GOLD_LIGHT)
            c.setFont('Helvetica-Bold', 9.5)
            c.drawString(ML + 0.6 * cm, head2_top - 1.65 * cm,
                        f"{eleve['prenom']} {eleve['nom']}".upper() +
                        f"  ·  Trimestre {trimestre}  ·  {_bulletin_annee_scolaire()}")
            c.setFillColor(colors.white)
            c.setFont('Helvetica', 7.6)
            c.drawRightString(ML + CW - 0.6 * cm, head2_top - 1.65 * cm,
                              'Courbe des moyennes et vue circulaire par matière')

            # -- 7b) Courbe des moyennes par matière --
            labels_mat = list(moy_par_nom.keys())
            values_mat = [round(v, 2) for v in moy_par_nom.values()]
            courbe_top = head2_bot - 0.4 * cm
            courbe_h = 7.2 * cm
            _bulletin_rounded_rect(c, ML, courbe_top - courbe_h, CW, courbe_h, 0.3 * cm,
                                   fill=colors.white, stroke=BORDER, lw=0.7)
            c.setFillColor(NAVY)
            c.setFont('Helvetica-Bold', 9.6)
            c.drawString(ML + 0.4 * cm, courbe_top - 0.55 * cm, 'COURBE DES MOYENNES PAR MATIÈRE')
            _bulletin_mini_line_chart(c, ML + 0.25 * cm, courbe_top - courbe_h + 0.25 * cm,
                                      CW - 0.5 * cm, courbe_h - 1.1 * cm,
                                      labels_mat, values_mat,
                                      line_color=GOLD, area_color=colors.HexColor('#F3E6C4'), systeme=sys_b)

            # -- 7c) Cercles (donuts) par matière --
            cercles_top = courbe_top - courbe_h - 0.4 * cm
            n_mat = len(labels_mat)
            n_cols = 5 if n_mat > 4 else max(1, n_mat)
            n_rows = _math2.ceil(n_mat / n_cols) if n_mat else 1
            row_h = 3.55 * cm
            cercles_h = 0.7 * cm + n_rows * row_h + 0.25 * cm
            _bulletin_rounded_rect(c, ML, cercles_top - cercles_h, CW, cercles_h, 0.3 * cm,
                                   fill=colors.white, stroke=BORDER, lw=0.7)
            c.setFillColor(NAVY)
            c.setFont('Helvetica-Bold', 9.6)
            c.drawCentredString(ML + CW / 2, cercles_top - 0.55 * cm,
                                'VUE CIRCULAIRE DES RÉSULTATS PAR MATIÈRE')
            col_w_cerc = CW / n_cols
            r_donut = 1.05 * cm
            for idx, nom_mat in enumerate(labels_mat):
                col_i = idx % n_cols
                row_i = idx // n_cols
                moy_mat = moy_par_nom[nom_mat]
                cx_d = ML + col_i * col_w_cerc + col_w_cerc / 2
                cy_d = cercles_top - 1.05 * cm - row_i * row_h - r_donut
                col_note = _bulletin_note_color(moy_mat)
                _bulletin_donut_gauge(c, cx_d, cy_d, r_donut, moy_mat / 20.0, col_note)
                c.setFillColor(TEXT_DARK)
                c.setFont('Helvetica-Bold', 10.5)
                c.drawCentredString(cx_d, cy_d - 3, fmt_moy_sys(moy_mat, sys_b, 1, False))
                c.setFillColor(TEXT_MUTED)
                c.setFont('Helvetica', 6.6)
                c.drawCentredString(cx_d, cy_d - r_donut - 0.32 * cm, '' if sys_b == 'lettres' else ech_b)
                nom_txt2, nom_size2 = _bulletin_fit_right_text(nom_mat, 'Helvetica-Bold',
                                                                col_w_cerc - 0.3 * cm,
                                                                max_size=7.6, min_size=5.6)
                c.setFillColor(NAVY)
                c.setFont('Helvetica-Bold', nom_size2)
                c.drawCentredString(cx_d, cy_d - r_donut - 0.72 * cm, nom_txt2)

            # -- 7d) Légende couleurs --
            leg_y = cercles_top - cercles_h - 0.55 * cm
            if sys_b == 'lettres':
                leg_items = [(GREEN, 'A : Bon'),
                            (colors.HexColor(_BULLETIN_AMBER), 'B : Moyen'),
                            (colors.HexColor(_BULLETIN_RED), 'C : Bas')]
            elif sys_b == '10':
                leg_items = [(GREEN, '≥ 6 : Bien / Excellent'),
                            (colors.HexColor(_BULLETIN_AMBER), '4 à 6 : Passable'),
                            (colors.HexColor(_BULLETIN_RED), '< 4 : Insuffisant')]
            else:
                leg_items = [(GREEN, '≥ 12 : Bien / Excellent'),
                            (colors.HexColor(_BULLETIN_AMBER), '8 à 12 : Passable'),
                            (colors.HexColor(_BULLETIN_RED), '< 8 : Insuffisant')]
            lx0 = ML + CW / 2 - 6.6 * cm
            for col_leg, txt_leg in leg_items:
                c.setFillColor(col_leg)
                c.circle(lx0 + 0.15 * cm, leg_y + 0.1 * cm, 0.15 * cm, stroke=0, fill=1)
                c.setFillColor(TEXT_MUTED)
                c.setFont('Helvetica', 7.4)
                c.drawString(lx0 + 0.4 * cm, leg_y, txt_leg)
                lx0 += 4.4 * cm

            c.setFillColor(TEXT_MUTED)
            c.setFont('Helvetica', 7)
            c.drawString(ML, 0.55 * cm, f"Généré le {datetime.datetime.now().strftime('%d/%m/%Y à %H:%M')}")
            c.drawRightString(ML + CW, 0.55 * cm, "Page 2")

        c.save()
        buf.seek(0)
        return send_file(buf, as_attachment=True,
                         download_name=f'bulletin_{eleve["nom"]}_{trimestre}.pdf',
                         mimetype='application/pdf')
    except Exception as ex:
        flash(f'Erreur génération PDF: {ex}', 'error')
        return redirect(url_for('eleve_detail', eleve_id=eleve_id))




# 🆕 Affichage UNIQUEMENT (reçu PDF) : un pourcentage de réduction s'affiche en nombre entier
# (ex : 33,33 % -> 33 %). Les calculs et les montants ne sont pas modifiés.
def _pct_aff(valeur):
    try:
        return str(int(float(valeur) + 0.5))
    except (TypeError, ValueError):
        return str(valeur)


def _desc_pdf_pct(description):
    """Arrondit à l'entier les pourcentages cités dans un libellé de facture (affichage seulement)."""
    import re as _re_pct
    if not description:
        return description
    return _re_pct.sub(r'(\d+(?:[.,]\d+)?)\s*%',
                       lambda m: _pct_aff(float(m.group(1).replace(',', '.'))) + '%',
                       str(description))

# ═══════════════════════════════════════════════════════════════════════════
# 📑 COMPTE RENDU FINANCIER (PDF « dashboard ») — bouton sur la page Paiements
# ───────────────────────────────────────────────────────────────────────────
# • Encaissements (sommes réellement reçues = journal `versements_paiements`, par date de
#   versement) : Scolarité (hors transport), Transport seul, Frais d'inscription, Autres
#   factures — chacun en Caisse / Banque / Total et par cycle (Scolarité, Inscription, Autres).
# • Réductions accordées (champ `reduction_appliquee` des factures de la période) : total et
#   par cycle, ventilées Scolarité / Transport / Inscription / Autres.
# • Charges payées par catégorie (Gasoil, Fournitures…), salaires enseignants, salaires du
#   personnel hors enseignants.
# • Courbes d'analyse mensuelles + graphiques, dessinés avec reportlab (aucune dépendance en plus).
# La période (date_debut / date_fin, facultatives) filtre toutes les sections.
# ═══════════════════════════════════════════════════════════════════════════
_CR_LABELS_CYCLE = {'College': 'Collège', 'Maternelle': 'Maternelle', 'Primaire': 'Primaire'}


def _cr_label_cycle(nom):
    return _CR_LABELS_CYCLE.get(nom, nom or '')


def _cr_mois_liste(m1, m2):
    """['2026-09', ..., '2027-02'] (bornes incluses)."""
    try:
        y, m = int(m1[:4]), int(m1[5:7])
        y2, m2_ = int(m2[:4]), int(m2[5:7])
    except (TypeError, ValueError):
        return []
    out = []
    while (y, m) <= (y2, m2_) and len(out) < 60:
        out.append(f"{y:04d}-{m:02d}")
        m += 1
        if m > 12:
            y, m = y + 1, 1
    return out


def _cr_collecter_donnees(conn, d1, d2, avec_charges=True, avec_salaires=True, base='encaissements'):
    import re as _re
    from collections import defaultdict
    try:
        synchroniser_versements(conn, commit=True)   # journal à jour (comme le hub financier)
    except Exception:
        pass

    cycles = list(get_all_cycle_names(conn) or []) or ['Maternelle', 'Primaire', 'College']

    # ── 1) Encaissements ────────────────────────────────────────────────────
    # 🆕 Base de calcul (choisie à la validation du compte rendu) :
    #  - 'encaissements' (défaut, comportement historique) : TOUS les encaissements reçus pendant la période,
    #    y compris ceux de factures des mois précédents payées durant cette période ;
    #  - 'factures' : seulement les encaissements reçus pendant la période sur les factures dont
    #    l'échéance tombe dans le(s) mois de la période.
    import calendar as _cal
    base = 'factures' if base == 'factures' else 'encaissements'
    _d1m = (d1[:7] + '-01') if d1 else ''
    _d2m = ''
    if d2:
        try:
            _d2m = f"{int(d2[:4]):04d}-{int(d2[5:7]):02d}-{_cal.monthrange(int(d2[:4]), int(d2[5:7]))[1]:02d}"
        except (ValueError, IndexError):
            _d2m = d2
    cl_f, pr_f = _clauses_dates('p.date_echeance', _d1m, _d2m)
    cl, pr = _clauses_dates('v.date_versement', d1, d2)
    # Encaissements de la période portant sur des factures d'AUTRES mois (utile pour l'information)
    enc_anterieures = 0.0
    if cl_f and (d1 or d2):
        _r_ant = conn.execute(
            "SELECT SUM(v.montant) AS t FROM versements_paiements v JOIN paiements p ON v.paiement_id = p.id "
            "WHERE COALESCE(v.montant,0) > 0 AND " + " AND ".join(cl) +
            " AND NOT (" + " AND ".join(cl_f) + ")", list(pr) + list(pr_f)).fetchone()
        enc_anterieures = float(_r_ant['t'] or 0) if _r_ant else 0.0
    if base == 'factures':
        cl = cl + cl_f
        pr = list(pr) + list(pr_f)
    where = " AND ".join(["COALESCE(v.montant,0) > 0"] + cl)
    rows = conn.execute(f"""
        SELECT COALESCE(c.cycle,'Primaire') AS cycle,
               COALESCE(NULLIF(v.mode_encaissement,''),'Autre') AS mode,
               CASE WHEN p.description LIKE '[Scolarité%' THEN 'scol'
                    WHEN p.description LIKE '[Frais d''inscription]%' THEN 'insc'
                    ELSE 'autre' END AS typ,
               strftime('%Y-%m', v.date_versement) AS mois,
               SUM(v.montant) AS total,
               SUM(CASE WHEN p.description LIKE '[Scolarité%' AND COALESCE(p.montant_total,0) > 0
                        THEN v.montant * MIN(COALESCE(p.montant_transport,0), p.montant_total) / p.montant_total
                        ELSE 0 END) AS transport
        FROM versements_paiements v
        JOIN paiements p ON v.paiement_id = p.id
        JOIN eleves e ON p.eleve_id = e.id
        LEFT JOIN classes c ON e.classe_id = c.id
        WHERE {where}
        GROUP BY cycle, mode, typ, mois""", pr).fetchall()

    enc = defaultdict(float)          # (type, mode, cycle) -> montant
    mois_enc = defaultdict(float)     # mois -> total encaissé
    for r in rows:
        mode = r['mode'] if r['mode'] in ('Caisse', 'Banque') else 'Autre'
        cyc = r['cycle'] or 'Primaire'
        if cyc not in cycles:
            cycles.append(cyc)
        total = float(r['total'] or 0)
        trans = float(r['transport'] or 0) if r['typ'] == 'scol' else 0.0
        if r['typ'] == 'scol':
            enc[('scol', mode, cyc)] += total - trans
            enc[('transport', mode, cyc)] += trans
        else:
            enc[(r['typ'], mode, cyc)] += total
        if r['mois']:
            mois_enc[r['mois']] += total

    # ── 2) Réductions accordées (factures dont l'échéance tombe dans la période) ──
    # Factures générées : on prend TOUT le mois (ou les mois) couvert(s) par la période choisie.
    import calendar
    d1m = (d1[:7] + '-01') if d1 else ''
    d2m = ''
    if d2:
        try:
            _y, _mo = int(d2[:4]), int(d2[5:7])
            d2m = f"{_y:04d}-{_mo:02d}-{calendar.monthrange(_y, _mo)[1]:02d}"
        except (ValueError, IndexError):
            d2m = d2
    cl, pr = _clauses_dates('p.date_echeance', d1m, d2m)
    w_fact = (" AND " + " AND ".join(cl)) if cl else ""
    red = defaultdict(float)          # (type, cycle) -> réduction
    nb_red = defaultdict(int)         # type -> nb de factures concernées
    mois_red = defaultdict(float)
    for r in conn.execute(f"""
            SELECT p.description, p.montant_total, p.montant_transport, p.reduction_appliquee,
                   substr(p.date_echeance,1,7) AS mois, COALESCE(c.cycle,'Primaire') AS cycle
            FROM paiements p JOIN eleves e ON p.eleve_id = e.id LEFT JOIN classes c ON e.classe_id = c.id
            WHERE COALESCE(p.reduction_appliquee,0) > 0{w_fact}""", pr).fetchall():
        cyc = r['cycle'] or 'Primaire'
        if cyc not in cycles:
            cycles.append(cyc)
        desc = str(r['description'] or '')
        total_red = float(r['reduction_appliquee'] or 0)
        if desc.startswith('[Scolarité'):
            red_trans = 0.0
            tn = float(r['montant_transport'] or 0)
            if tn > 0:
                m_t = _re.search(r'([\d.,]+)\s*%\s*sur le transport', desc)
                pt = float(m_t.group(1).replace(',', '.')) if m_t else 0.0
                if 0 < pt < 100:
                    red_trans = min(total_red, round(tn / (1 - pt / 100) - tn, 2))
            red_scol = round(total_red - red_trans, 2)
            if red_scol > 0.004:
                red[('scol', cyc)] += red_scol
                nb_red['scol'] += 1
            if red_trans > 0.004:
                red[('transport', cyc)] += red_trans
                nb_red['transport'] += 1
        elif desc.startswith("[Frais d'inscription]"):
            red[('insc', cyc)] += total_red
            nb_red['insc'] += 1
        else:
            red[('autre', cyc)] += total_red
            nb_red['autre'] += 1
        if r['mois']:
            mois_red[r['mois']] += total_red

    # Facturé généré (MOIS ENTIER) et reste à encaisser du mois ; l'encaissé, lui, ne compte que
    # les versements de la période choisie (voir plus bas).
    brut_cycle = defaultdict(float)
    fact = defaultdict(lambda: [0.0, 0.0, 0, 0.0])   # (type, cycle) -> [facturé, encaissé période, nb, reste du mois]
    mois_fact, mois_paye_fact = defaultdict(float), defaultdict(float)
    typ_sql = """CASE WHEN p.description LIKE '[Scolarité%' THEN 'scol'
                      WHEN p.description LIKE '[Frais d''inscription]%' THEN 'insc' ELSE 'autre' END"""
    for r in conn.execute(f"""
            SELECT COALESCE(c.cycle,'Primaire') AS cycle, {typ_sql} AS typ,
                   substr(p.date_echeance,1,7) AS mois,
                   SUM(COALESCE(p.montant_total,0)) AS total,
                   SUM(MAX(COALESCE(p.montant_total,0) - COALESCE(p.montant_regule,0) - COALESCE(p.montant_paye,0), 0)) AS reste,
                   SUM(COALESCE(p.reduction_appliquee,0)) AS red, COUNT(*) AS n
            FROM paiements p JOIN eleves e ON p.eleve_id = e.id LEFT JOIN classes c ON e.classe_id = c.id
            WHERE 1=1{w_fact} GROUP BY cycle, typ, mois""", pr).fetchall():
        cyc = r['cycle'] or 'Primaire'
        if cyc not in cycles:
            cycles.append(cyc)
        tot = float(r['total'] or 0)
        brut_cycle[cyc] += tot + float(r['red'] or 0)
        f = fact[(r['typ'], cyc)]
        f[0] += tot
        f[2] += int(r['n'] or 0)
        f[3] += float(r['reste'] or 0)
        if r['mois']:
            mois_fact[r['mois']] += tot
    cl_v, pr_v = _clauses_dates('v.date_versement', d1, d2)
    for r in conn.execute(f"""
            SELECT COALESCE(c.cycle,'Primaire') AS cycle, {typ_sql} AS typ,
                   substr(p.date_echeance,1,7) AS mois, SUM(v.montant) AS paye
            FROM versements_paiements v
            JOIN paiements p ON v.paiement_id = p.id
            JOIN eleves e ON p.eleve_id = e.id LEFT JOIN classes c ON e.classe_id = c.id
            WHERE 1=1{w_fact}{(" AND " + " AND ".join(cl_v)) if cl_v else ""}
            GROUP BY cycle, typ, mois""", list(pr) + list(pr_v)).fetchall():
        cyc = r['cycle'] or 'Primaire'
        pay = float(r['paye'] or 0)
        fact[(r['typ'], cyc)][1] += pay
        if r['mois']:
            mois_paye_fact[r['mois']] += pay

    # ── 3) Charges par catégorie ────────────────────────────────────────────
    charges_cat, charges_mois, charges_np = [], defaultdict(float), []
    if avec_charges:
        cl, pr = _clauses_dates('date_facture', d1, d2)
        w = " AND ".join(["statut='paye'"] + cl)
        charges_cat = [(r['cat'], float(r['m'] or 0), int(r['n'] or 0)) for r in conn.execute(
            f"SELECT COALESCE(NULLIF(TRIM(categorie),''),'Non classée') AS cat, SUM(montant) AS m, COUNT(*) AS n "
            f"FROM charges WHERE {w} GROUP BY cat ORDER BY m DESC", pr).fetchall()]
        for r in conn.execute(
                f"SELECT strftime('%Y-%m', date_facture) AS mois, SUM(montant) AS m FROM charges "
                f"WHERE {w} GROUP BY mois", pr).fetchall():
            if r['mois']:
                charges_mois[r['mois']] += float(r['m'] or 0)
        # Charges NON payées (tout statut autre que « paye ») de la même période, par catégorie
        w_np = " AND ".join(["COALESCE(statut,'') <> 'paye'"] + cl)
        charges_np = [(r['cat'], float(r['m'] or 0), int(r['n'] or 0)) for r in conn.execute(
            f"SELECT COALESCE(NULLIF(TRIM(categorie),''),'Non classée') AS cat, SUM(montant) AS m, COUNT(*) AS n "
            f"FROM charges WHERE {w_np} GROUP BY cat ORDER BY m DESC", pr).fetchall()]

    # ── 4) Salaires ─────────────────────────────────────────────────────────
    sal_ens = {'total': 0.0, 'n': 0, 'mois': defaultdict(float)}
    sal_pers = {'total': 0.0, 'n': 0, 'mois': defaultdict(float)}
    if avec_salaires:
        for table, cible in (('paiements_enseignants', sal_ens), ('paiements_personnel_hors_prof', sal_pers)):
            cl, pr = _clauses_dates('date_paiement', d1, d2)
            w = " AND ".join(["COALESCE(montant_paye,0) > 0"] + cl)
            try:
                r0 = conn.execute(f"SELECT SUM(montant_paye) AS m, COUNT(*) AS n FROM {table} WHERE {w}", pr).fetchone()
                cible['total'] = float(r0['m'] or 0)
                cible['n'] = int(r0['n'] or 0)
                for r in conn.execute(
                        f"SELECT strftime('%Y-%m', date_paiement) AS mois, SUM(montant_paye) AS m FROM {table} "
                        f"WHERE {w} GROUP BY mois", pr).fetchall():
                    if r['mois']:
                        cible['mois'][r['mois']] += float(r['m'] or 0)
            except sqlite3.OperationalError:
                pass

    # ── Axe des mois ────────────────────────────────────────────────────────
    tous_mois = set(mois_enc) | set(mois_red) | set(mois_fact) | set(charges_mois) | set(sal_ens['mois']) | set(sal_pers['mois'])
    m_min = d1[:7] if d1 else (min(tous_mois) if tous_mois else None)
    m_max = d2[:7] if d2 else (max(tous_mois) if tous_mois else None)
    mois = _cr_mois_liste(m_min, m_max) if (m_min and m_max) else []

    return {'cycles': cycles, 'enc': enc, 'mois_enc': mois_enc, 'red': red, 'nb_red': nb_red,
            'mois_red': mois_red, 'brut_cycle': brut_cycle, 'fact': fact, 'mois_fact': mois_fact,
            'mois_paye_fact': mois_paye_fact, 'charges_cat': charges_cat, 'charges_np': charges_np,
            'charges_mois': charges_mois, 'sal_ens': sal_ens, 'sal_pers': sal_pers, 'mois': mois,
            'avec_charges': avec_charges, 'avec_salaires': avec_salaires,
            'base': base, 'enc_anterieures': enc_anterieures}


def _cr_construire_pdf(D, titre_periode, logo_path=None, nom_ecole=None):
    nom_ecole = nom_ecole or get_nom_ecole()
    """Dessine le compte rendu (4 pages A4 paysage) et renvoie un BytesIO."""
    import io as _io
    from reportlab.lib.pagesizes import A4, landscape
    from reportlab.lib import colors
    from reportlab.pdfgen import canvas as pdfcanvas
    from reportlab.platypus import Table, TableStyle
    from reportlab.graphics.shapes import Drawing, String, Circle
    from reportlab.graphics.charts.linecharts import HorizontalLineChart
    from reportlab.graphics.charts.barcharts import VerticalBarChart, HorizontalBarChart
    from reportlab.graphics.charts.piecharts import Pie
    from reportlab.graphics.widgets.markers import makeMarker
    from reportlab.graphics import renderPDF

    NAVY = colors.HexColor(_BULLETIN_NAVY)
    GOLD = colors.HexColor(_BULLETIN_GOLD)
    CREAM = colors.HexColor(_BULLETIN_CREAM)
    BORDER = colors.HexColor(_BULLETIN_BORDER)
    DARK = colors.HexColor(_BULLETIN_TEXT_DARK)
    MUTED = colors.HexColor(_BULLETIN_TEXT_MUTED)
    GREEN = colors.HexColor(_BULLETIN_GREEN)
    RED = colors.HexColor(_BULLETIN_RED)
    BLUE = colors.HexColor('#2F6FED')
    TEAL = colors.HexColor('#17A398')
    CORAL = colors.HexColor('#E07A5F')
    PURPLE = colors.HexColor('#8E6BBF')
    GRIDC = colors.HexColor('#E5E7EB')
    TYPE_COL = {'scol': BLUE, 'transport': TEAL, 'insc': GOLD, 'autre': PURPLE}
    TYPE_LAB = {'scol': 'Scolarité', 'transport': 'Transport', 'insc': "Frais d'inscription", 'autre': 'Autres factures'}

    W, H = landscape(A4)
    ML = 34
    CW = W - 2 * ML
    TOP = H - 76          # haut de la zone de contenu
    BOT = 36              # bas de la zone de contenu
    NB_PAGES = 5
    cycles = D['cycles']
    mois = D['mois']
    enc, red, fact = D['enc'], D['red'], D['fact']

    def m_(x):
        return f"{x:,.2f}".replace(',', ' ')

    def court(v):
        a = abs(v)
        if a >= 1_000_000:
            return f"{v / 1_000_000:.1f}M"
        if a >= 1000:
            return f"{v / 1000:.0f}k" if a >= 10000 else f"{v / 1000:.1f}k"
        return f"{v:.0f}"

    def lab_mois(k):
        return f"{k[5:7]}/{k[2:4]}"

    # ── agrégats ──
    def e_(typ, mode=None, cyc=None):
        return sum(v for (t, mo, cy), v in enc.items()
                   if t == typ and (mode is None or mo == mode) and (cyc is None or cy == cyc))

    def r_(typ=None, cyc=None):
        return sum(v for (t, cy), v in red.items() if (typ is None or t == typ) and (cyc is None or cy == cyc))

    types = ['scol', 'transport', 'insc', 'autre']
    total_enc = sum(enc.values())
    enc_caisse = sum(v for (t, mo, cy), v in enc.items() if mo == 'Caisse')
    enc_banque = sum(v for (t, mo, cy), v in enc.items() if mo == 'Banque')
    enc_autre = total_enc - enc_caisse - enc_banque
    total_red = r_()
    total_brut = sum(D['brut_cycle'].values())
    taux_red = (total_red / total_brut * 100) if total_brut > 0 else 0.0
    total_charges = sum(m for _, m, _ in D['charges_cat']) if D['avec_charges'] else None
    total_np = sum(m for _, m, _ in D['charges_np']) if D['avec_charges'] else None
    total_sal_ens = D['sal_ens']['total'] if D['avec_salaires'] else None
    total_sal_pers = D['sal_pers']['total'] if D['avec_salaires'] else None
    depenses = None
    if total_charges is not None and total_sal_ens is not None:
        depenses = total_charges + total_sal_ens + total_sal_pers
    resultat = (total_enc - depenses) if depenses is not None else None
    fact_total = sum(v[0] for v in fact.values())
    fact_paye = sum(v[1] for v in fact.values())
    fact_reste = sum(v[3] for v in fact.values())
    taux_enc = (fact_paye / fact_total * 100) if fact_total > 0 else 0.0

    buf = _io.BytesIO()
    c = pdfcanvas.Canvas(buf, pagesize=(W, H))
    c.setTitle('Compte rendu financier')
    c.setAuthor(nom_ecole)
    maintenant = datetime.datetime.now().strftime('%d/%m/%Y à %H:%M')

    # ── primitives ──
    def entete(num, titre, sous_titre=''):
        c.setFillColor(CREAM)
        c.rect(0, 0, W, H, stroke=0, fill=1)
        c.setFillColor(NAVY)
        c.rect(0, H - 62, W, 62, stroke=0, fill=1)
        c.setFillColor(GOLD)
        c.rect(0, H - 65, W, 3, stroke=0, fill=1)
        x_txt = ML
        if logo_path:
            try:
                c.drawImage(logo_path, ML, H - 56, width=44, height=44, preserveAspectRatio=True, mask='auto')
                x_txt = ML + 56
            except Exception:
                pass
        c.setFillColor(colors.white)
        c.setFont('Helvetica-Bold', 17)
        c.drawString(x_txt, H - 33, titre)
        c.setFillColor(GOLD)
        c.setFont('Helvetica', 9)
        c.drawString(x_txt, H - 49, sous_titre or nom_ecole)
        c.setFillColor(colors.white)
        c.setFont('Helvetica-Bold', 9)
        c.drawRightString(W - ML, H - 30, 'Période : ' + titre_periode)
        c.setFont('Helvetica', 8)
        c.setFillColor(colors.HexColor('#C7CEDC'))
        c.drawRightString(W - ML, H - 45, 'Généré le ' + maintenant)
        c.setFillColor(MUTED)
        c.setFont('Helvetica', 7.5)
        c.drawString(ML, 20, f"{nom_ecole} — Compte rendu financier")
        c.drawRightString(W - ML, 20, f"Page {num} / {NB_PAGES}")
        c.setStrokeColor(BORDER)
        c.line(ML, 30, W - ML, 30)

    def panel(x, y, w, h, titre, accent=NAVY):
        c.setFillColor(colors.white)
        c.setStrokeColor(BORDER)
        c.setLineWidth(0.8)
        c.roundRect(x, y, w, h, 7, stroke=1, fill=1)
        c.setFillColor(accent)
        c.rect(x, y + h - 20, 4, 14, stroke=0, fill=1)
        c.setFillColor(NAVY)
        c.setFont('Helvetica-Bold', 9.5)
        c.drawString(x + 11, y + h - 16, titre)
        return x + 8, y + 6, w - 16, h - 28

    def kpi(x, y, w, h, label, valeur, sous, couleur):
        c.setFillColor(colors.white)
        c.setStrokeColor(BORDER)
        c.roundRect(x, y, w, h, 7, stroke=1, fill=1)
        c.setFillColor(couleur)
        c.roundRect(x, y, 5, h, 2, stroke=0, fill=1)
        c.setFillColor(MUTED)
        c.setFont('Helvetica-Bold', 7.5)
        c.drawString(x + 12, y + h - 15, label.upper())
        c.setFillColor(couleur)
        c.setFont('Helvetica-Bold', 14.5)
        c.drawString(x + 12, y + h - 35, valeur)
        c.setFillColor(MUTED)
        c.setFont('Helvetica', 7.5)
        c.drawString(x + 12, y + 8, sous)

    def table(data, x, y_top, colw, align_right_from=1, total_rows=(), head_bg=NAVY, font=8, row_h=17, header=True):
        t = Table(data, colWidths=colw, rowHeights=[row_h] * len(data))
        st = [('FONT', (0, 0), (-1, -1), 'Helvetica', font),
              ('TEXTCOLOR', (0, 0), (-1, -1), DARK),
              ('ALIGN', (align_right_from, 0), (-1, -1), 'RIGHT'),
              ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'),
              ('LINEBELOW', (0, 0), (-1, -1), 0.4, GRIDC),
              ('ROWBACKGROUNDS', (0, 1 if header else 0), (-1, -1), [colors.white, colors.HexColor('#F7F8FB')]),
              ('LEFTPADDING', (0, 0), (-1, -1), 6), ('RIGHTPADDING', (0, 0), (-1, -1), 6)]
        if header:
            st += [('BACKGROUND', (0, 0), (-1, 0), head_bg), ('TEXTCOLOR', (0, 0), (-1, 0), colors.white),
                   ('FONT', (0, 0), (-1, 0), 'Helvetica-Bold', font)]
        for i in total_rows:
            st += [('FONT', (0, i), (-1, i), 'Helvetica-Bold', font),
                   ('BACKGROUND', (0, i), (-1, i), colors.HexColor('#EAF0FB'))]
        t.setStyle(TableStyle(st))
        tw, th = t.wrapOn(c, sum(colw), 400)
        t.drawOn(c, x, y_top - th)
        return th

    def legende(x, y, items):
        cx = x
        for nom, col in items:
            c.setFillColor(col)
            c.rect(cx, y, 8, 8, stroke=0, fill=1)
            c.setFillColor(DARK)
            c.setFont('Helvetica', 7.5)
            c.drawString(cx + 11, y + 1, nom)
            cx += 11 + c.stringWidth(nom, 'Helvetica', 7.5) + 14

    def aucune_donnee(x, y, w, h):
        c.setFillColor(MUTED)
        c.setFont('Helvetica-Oblique', 8.5)
        c.drawCentredString(x + w / 2, y + h / 2, 'Aucune donnée sur la période')

    def courbes(x, y, w, h, series, labels=None):
        """series = [(nom, couleur, [valeurs par mois])]"""
        labels = labels or [lab_mois(k) for k in mois]
        if not labels or not any(any(abs(v) > 0.004 for v in s[2]) for s in series):
            aucune_donnee(x, y, w, h)
            return
        legende(x + 4, y + h - 10, [(s[0], s[1]) for s in series])
        d = Drawing(w, h - 16)
        ch = HorizontalLineChart()
        ch.x, ch.y, ch.width, ch.height = 40, 24, w - 52, h - 16 - 34
        ch.data = [list(s[2]) for s in series]
        ch.categoryAxis.categoryNames = labels
        ch.categoryAxis.labels.fontSize = 7
        ch.categoryAxis.labels.fontName = 'Helvetica'
        ch.categoryAxis.labels.fillColor = MUTED
        ch.categoryAxis.joinAxisMode = 'bottom'
        if len(labels) > 9:
            ch.categoryAxis.labels.angle = 35
            ch.categoryAxis.labels.boxAnchor = 'ne'
            ch.categoryAxis.labels.dy = -2
        ch.categoryAxis.strokeColor = GRIDC
        vmin = min(0, min(min(s[2]) for s in series))
        vmax = max(max(s[2]) for s in series)
        ch.valueAxis.valueMin = vmin
        if vmax <= 0:
            ch.valueAxis.valueMax = 1
        ch.valueAxis.labels.fontSize = 7
        ch.valueAxis.labels.fontName = 'Helvetica'
        ch.valueAxis.labels.fillColor = MUTED
        ch.valueAxis.labelTextFormat = lambda v: court(v)
        ch.valueAxis.visibleGrid = 1
        ch.valueAxis.gridStrokeColor = GRIDC
        ch.valueAxis.strokeColor = GRIDC
        ch.joinedLines = 1
        for i, s in enumerate(series):
            ch.lines[i].strokeColor = s[1]
            ch.lines[i].strokeWidth = 2
            mk = makeMarker('FilledCircle')
            mk.size = 4
            mk.fillColor = s[1]
            mk.strokeColor = colors.white
            ch.lines[i].symbol = mk
        d.add(ch)
        renderPDF.draw(d, c, x, y)

    def barres(x, y, w, h, cats, series, horizontal=False, marge_gauche=None, fmt=None):
        """series = [(nom, couleur, [valeurs par catégorie])]"""
        if not cats or not any(any(abs(v) > 0.004 for v in s[2]) for s in series):
            aucune_donnee(x, y, w, h)
            return
        multi = len(series) > 1
        if multi:
            legende(x + 4, y + h - 10, [(s[0], s[1]) for s in series])
        top_pad = 16 if multi else 4
        d = Drawing(w, h - top_pad)
        ch = HorizontalBarChart() if horizontal else VerticalBarChart()
        gauche = marge_gauche if (horizontal and marge_gauche) else 40
        ch.x, ch.y, ch.width, ch.height = gauche, 22 if not horizontal else 8, w - gauche - 14, h - top_pad - (34 if not horizontal else 20)
        if horizontal:
            ch.data = [list(reversed(s[2])) for s in series]
            ch.categoryAxis.categoryNames = [(n if len(n) <= 26 else n[:25] + '…') for n in reversed(cats)]
            ch.categoryAxis.labels.boxAnchor = 'e'
            ch.categoryAxis.labels.dx = -4
        else:
            ch.data = [list(s[2]) for s in series]
            ch.categoryAxis.categoryNames = cats
        ch.categoryAxis.labels.fontSize = 7.5
        ch.categoryAxis.labels.fontName = 'Helvetica'
        ch.categoryAxis.labels.fillColor = DARK
        ch.categoryAxis.strokeColor = GRIDC
        ch.valueAxis.valueMin = 0
        vmax = max(max(s[2]) for s in series)
        if vmax <= 0:
            ch.valueAxis.valueMax = 1
        ch.valueAxis.labels.fontSize = 7
        ch.valueAxis.labels.fontName = 'Helvetica'
        ch.valueAxis.labels.fillColor = MUTED
        ch.valueAxis.labelTextFormat = lambda v: (fmt(v) if fmt else court(v))
        ch.valueAxis.visibleGrid = 1
        ch.valueAxis.gridStrokeColor = GRIDC
        ch.valueAxis.strokeColor = GRIDC
        ch.groupSpacing = 8
        ch.barSpacing = 1.5
        ch.barLabelFormat = lambda v: ('' if abs(v) < 0.005 else (fmt(v) if fmt else court(v)))
        ch.barLabels.fontSize = 6.5
        ch.barLabels.fontName = 'Helvetica'
        ch.barLabels.fillColor = DARK
        if horizontal:
            ch.barLabels.nudge = 14
        else:
            ch.barLabels.nudge = 6
        for i, s in enumerate(series):
            ch.bars[i].fillColor = s[1]
            ch.bars[i].strokeColor = None
        d.add(ch)
        renderPDF.draw(d, c, x, y)

    def anneau(x, y, w, h, parts):
        """parts = [(nom, couleur, valeur)] — anneau + légende avec pourcentages."""
        tot = sum(p[2] for p in parts)
        taille = min(h - 8, w * 0.5)
        if tot <= 0:
            aucune_donnee(x, y, w, h)
            return
        d = Drawing(taille, taille)
        pie = Pie()
        pie.x, pie.y, pie.width, pie.height = 4, 4, taille - 8, taille - 8
        pie.data = [max(p[2], 0.0001) for p in parts]
        pie.labels = None
        pie.sideLabels = 0
        pie.slices.strokeColor = colors.white
        pie.slices.strokeWidth = 1.5
        for i, p in enumerate(parts):
            pie.slices[i].fillColor = p[1]
        try:
            pie.innerRadiusFraction = 0.58
        except Exception:
            pass
        d.add(pie)
        renderPDF.draw(d, c, x, y + (h - taille) / 2)
        lx = x + taille + 14
        pas = min(27, max(17, (h - 6) / max(len(parts), 1)))
        ly = y + h / 2 + (len(parts) - 1) * pas / 2 + 4
        for nom, col, val in parts:
            c.setFillColor(col)
            c.rect(lx, ly - 2, 9, 9, stroke=0, fill=1)
            c.setFillColor(DARK)
            c.setFont('Helvetica-Bold', 8)
            c.drawString(lx + 14, ly, f"{nom}")
            c.setFont('Helvetica', 7.5)
            c.setFillColor(MUTED)
            c.drawString(lx + 14, ly - 10, f"{m_(val)} MAD  ({val / tot * 100:.1f}%)")
            ly -= pas

    def serie_mois(dic):
        return [round(float(dic.get(k, 0.0)), 2) for k in mois]

    # ═══════════════ PAGE 1 : SYNTHÈSE ═══════════════
    entete(1, 'COMPTE RENDU FINANCIER', 'Tableau de bord — synthèse de la situation financière (tous cycles)')
    gap = 10
    # ── Bandeau « solde final » : la société est-elle gagnante ou perdante sur la période ? ──
    bh = 54
    by = TOP - bh
    if resultat is None:
        col_b, verdict, verdict_txt = MUTED, 'NON CALCULABLE', ''
    elif resultat > 0.004:
        col_b, verdict, verdict_txt = GREEN, 'GAGNANTE', 'EXCÉDENT'
    elif resultat < -0.004:
        col_b, verdict, verdict_txt = RED, 'PERDANTE', 'DÉFICIT'
    else:
        col_b, verdict, verdict_txt = colors.HexColor(_BULLETIN_AMBER), 'ÉQUILIBRE', ''
    c.setFillColor(col_b)
    c.roundRect(ML, by, CW, bh, 8, stroke=0, fill=1)
    c.setFillColor(colors.white)
    c.setFont('Helvetica-Bold', 7.5)
    c.drawString(ML + 14, by + bh - 14, 'SOLDE FINAL DE LA PÉRIODE' + (' — ' + verdict_txt if verdict_txt else ''))
    c.setFont('Helvetica-Bold', 21)
    c.drawString(ML + 14, by + 10, ((('+' if resultat > 0.004 else '') + m_(resultat) + ' MAD') if resultat is not None else '—'))
    c.setFont('Helvetica-Bold', 21)
    vx = ML + 14 + c.stringWidth(((('+' if (resultat or 0) > 0.004 else '') + m_(resultat) + ' MAD') if resultat is not None else '—'), 'Helvetica-Bold', 21) + 16
    c.setFont('Helvetica-Bold', 9.5)
    pill_w = c.stringWidth('SOCIÉTÉ ' + verdict, 'Helvetica-Bold', 9.5) + 18
    c.setFillColor(colors.white)
    c.roundRect(vx, by + 12, pill_w, 20, 10, stroke=0, fill=1)
    c.setFillColor(col_b)
    c.drawString(vx + 9, by + 18, 'SOCIÉTÉ ' + verdict)
    c.setFillColor(colors.white)
    mx = ML + CW * 0.55
    c.setFont('Helvetica', 8)
    c.drawString(mx, by + bh - 17, f"Encaissé {m_(total_enc)}")
    if depenses is not None:
        c.drawString(mx, by + bh - 29, f"− Charges {m_(total_charges)}   − Salaires {m_(total_sal_ens + total_sal_pers)}")
    c.setFont('Helvetica-Oblique', 7)
    if D.get('base') == 'factures' and D.get('enc_anterieures') is not None:
        c.drawString(mx, by + 8, f"Base : factures de la période seulement (hors {m_(D.get('enc_anterieures') or 0)} sur factures antérieures)")
    else:
        c.drawString(mx, by + 8, 'Trésorerie : encaissé − charges − salaires')
    tx = ML + CW * 0.79
    c.setFont('Helvetica-Bold', 7.5)
    c.drawString(tx, by + bh - 14, "TAUX D'ENCAISSEMENT")
    c.setFont('Helvetica-Bold', 17)
    c.drawString(tx, by + bh - 34, f"{taux_enc:.1f}%")
    bw = CW * 0.19
    c.setFillColor(colors.Color(1, 1, 1, alpha=0.35))
    c.roundRect(tx, by + 9, bw, 7, 3, stroke=0, fill=1)
    c.setFillColor(GOLD)
    c.roundRect(tx, by + 9, max(bw * min(taux_enc, 100) / 100, 1), 7, 3, stroke=0, fill=1)

    # ── 🆕 Projection de la vraie situation : solde final − charges NON payées de la période ──
    # (le solde final ci-dessus reste calculé uniquement sur le payé ; la projection est indicative)
    bas_bandeau = by
    if resultat is not None and total_np is not None:
        nb_np = sum(k for _, _, k in D['charges_np'])
        projection = resultat - total_np
        if projection > 0.004:
            col_p, verdict_p = GREEN, 'EXCÉDENT PROJETÉ'
        elif projection < -0.004:
            col_p, verdict_p = RED, 'DÉFICIT PROJETÉ'
        else:
            col_p, verdict_p = colors.HexColor(_BULLETIN_AMBER), 'ÉQUILIBRE PROJETÉ'
        ph_ = 40
        py_ = by - 5 - ph_
        c.setFillColor(col_p)
        c.roundRect(ML, py_, CW, ph_, 8, stroke=0, fill=1)
        c.setFillColor(colors.white)
        c.setFont('Helvetica-Bold', 7.5)
        c.drawString(ML + 14, py_ + ph_ - 13, 'PROJECTION DE LA VRAIE SITUATION — ' + verdict_p)
        txt_proj = ('+' if projection > 0.004 else '') + m_(projection) + ' MAD'
        c.setFont('Helvetica-Bold', 17)
        c.drawString(ML + 14, py_ + 8, txt_proj)
        c.setFont('Helvetica', 8)
        c.drawString(mx, py_ + ph_ - 15, f"Solde final {('+' if resultat > 0.004 else '') + m_(resultat)}   − Charges non payées {m_(total_np)}")
        c.setFont('Helvetica-Oblique', 7)
        c.drawString(mx, py_ + 8, f"{nb_np} charge(s) non payée(s) sur la période · indicatif, hors solde final")
        bas_bandeau = py_

    kw = (CW - 4 * gap) / 5
    kh = 52
    ky = bas_bandeau - 10 - kh
    kpi(ML, ky, kw, kh, 'Facturé généré (mois entier)', m_(fact_total) + ' MAD', f"après {m_(total_red)} de réductions", NAVY)
    kpi(ML + (kw + gap), ky, kw, kh, 'Encaissé (période choisie)', m_(fact_paye) + ' MAD', f"Caisse {court(enc_caisse)} · Banque {court(enc_banque)}", BLUE)
    kpi(ML + 2 * (kw + gap), ky, kw, kh, 'Reste à encaisser (mois)', m_(fact_reste) + ' MAD', "sur le mois entier facturé", RED if fact_reste > 0.004 else GREEN)
    kpi(ML + 3 * (kw + gap), ky, kw, kh, 'Dépenses (charges + salaires)',
        (m_(depenses) + ' MAD') if depenses is not None else '—',
        (f"Charges {court(total_charges)} · Salaires {court(total_sal_ens + total_sal_pers)}") if depenses is not None else 'Accès charges / paie requis', CORAL)
    kpi(ML + 4 * (kw + gap), ky, kw, kh, 'Réductions accordées', m_(total_red) + ' MAD',
        f"{taux_red:.1f}% du montant initial facturé", GOLD)

    r1_top = ky - 10
    r1_h = 168
    pw1 = CW * 0.62
    x, y, w, h = panel(ML, r1_top - r1_h, pw1, r1_h, 'Évolution mensuelle : encaissements, dépenses et résultat')
    dep_m = [(D['charges_mois'].get(k, 0.0) + D['sal_ens']['mois'].get(k, 0.0) + D['sal_pers']['mois'].get(k, 0.0)) for k in mois]
    enc_m = serie_mois(D['mois_enc'])
    if depenses is not None:
        net_m = [round(a_ - b_, 2) for a_, b_ in zip(enc_m, dep_m)]
        courbes(x, y, w, h, [('Encaissé', BLUE, enc_m), ('Dépenses (charges + salaires)', CORAL, [round(v, 2) for v in dep_m]),
                             ('Résultat du mois', GREEN, net_m)])
    else:
        courbes(x, y, w, h, [('Encaissé', BLUE, enc_m)])
    x, y, w, h = panel(ML + pw1 + gap, r1_top - r1_h, CW - pw1 - gap, r1_h, 'Répartition des encaissements', GOLD)
    anneau(x, y, w, h, [(TYPE_LAB[t], TYPE_COL[t], e_(t)) for t in types])

    r2_top = r1_top - r1_h - 10
    r2_h = r2_top - BOT
    pw2 = CW * 0.58
    x, y, w, h = panel(ML, BOT, pw2, r2_h, 'Encaissé par cycle et par type', TEAL)
    barres(x, y, w, h, [_cr_label_cycle(cy) for cy in cycles],
           [(TYPE_LAB[t], TYPE_COL[t], [round(e_(t, None, cy), 2) for cy in cycles]) for t in types])
    x, y, w, h = panel(ML + pw2 + gap, BOT, CW - pw2 - gap, r2_h, 'Caisse / Banque', NAVY)
    data = [['Mode', 'Encaissé', '%']]
    for nom, val in (('Caisse', enc_caisse), ('Banque', enc_banque)) + ((('Non précisé', enc_autre),) if enc_autre > 0.004 else ()):
        data.append([nom, m_(val), f"{(val / total_enc * 100) if total_enc else 0:.1f}%"])
    data.append(['TOTAL', m_(total_enc), '100%' if total_enc else '0%'])
    table(data, x, y + h, [w * 0.38, w * 0.38, w * 0.24], total_rows=(len(data) - 1,))
    c.setFillColor(MUTED)
    c.setFont('Helvetica', 7)
    c.drawString(x + 2, y + 4, "Montants réellement reçus (journal des versements) sur la période.")

    c.showPage()

    # ═══════════════ PAGE 2 : ENCAISSEMENTS ═══════════════
    entete(2, 'ENCAISSEMENTS', 'Scolarité · Transport · Frais d\'inscription · Autres factures')
    gap = 14
    pw = (CW - gap) / 2
    ph = (TOP - BOT - gap) / 2
    avec_autre = enc_autre > 0.004
    cols_modes = ['Caisse', 'Banque'] + (['Autre'] if avec_autre else [])

    def tab_encaissement(typ, px, py, titre, par_cycle=True, accent=BLUE):
        x, y, w, h = panel(px, py, pw, ph, titre, accent)
        head = [''] + ['Caisse', 'Banque'] + (['Non précisé'] if avec_autre else []) + ['Total']
        data = [head]
        data.append(['TOTAL'] + [m_(e_(typ, mo)) for mo in cols_modes] + [m_(e_(typ))])
        if par_cycle:
            for cy in cycles:
                data.append([_cr_label_cycle(cy)] + [m_(e_(typ, mo, cy)) for mo in cols_modes] + [m_(e_(typ, None, cy))])
        nc = len(head)
        first = w * 0.24
        rest = (w - first) / (nc - 1)
        th = table(data, x, y + h, [first] + [rest] * (nc - 1), total_rows=(1,), head_bg=accent)
        if par_cycle and h - th - 30 > 70:
            barres(x, y + 12, w, h - th - 20,
                   [_cr_label_cycle(cy) for cy in cycles],
                   [(mo if mo != 'Autre' else 'Non précisé', {'Caisse': accent, 'Banque': NAVY, 'Autre': MUTED}[mo],
                     [round(e_(typ, mo, cy), 2) for cy in cycles]) for mo in cols_modes])
        return x, y, w, h, th

    x, y, w, h, th = tab_encaissement('scol', ML, BOT + ph + gap, 'Scolarité encaissée (hors transport)', True, BLUE)
    c.setFillColor(MUTED); c.setFont('Helvetica', 7)
    c.drawString(x + 2, y + 2, 'Mensualités de scolarité, part transport exclue.')
    x, y, w, h, th = tab_encaissement('transport', ML + pw + gap, BOT + ph + gap, 'Frais de transport encaissés (seulement)', False, TEAL)
    barres(x, y + 8, w, h - th - 14, ['Caisse', 'Banque'] + (['Non précisé'] if avec_autre else []),
           [('Transport', TEAL, [round(e_('transport', mo), 2) for mo in cols_modes])], horizontal=True, marge_gauche=70)
    x, y, w, h, th = tab_encaissement('insc', ML, BOT, "Frais d'inscription encaissés", True, GOLD)
    x, y, w, h, th = tab_encaissement('autre', ML + pw + gap, BOT, 'Autres factures encaissées', True, PURPLE)
    c.showPage()

    # ═══════════════ PAGE 3 : TAUX D'ENCAISSEMENT ═══════════════
    entete(3, "TAUX D'ENCAISSEMENT", 'Facturé = factures générées sur le(s) mois entier(s) · Encaissé = période choisie · Reste = mois entier')

    def fsum(idx, typ=None, cyc=None):
        return sum(v[idx] for (t, cy), v in fact.items() if (typ is None or t == typ) and (cyc is None or cy == cyc))

    def ligne(nom, typ=None, cyc=None):
        ft, fp = fsum(0, typ, cyc), fsum(1, typ, cyc)
        return [nom, m_(ft), m_(fp), m_(fsum(3, typ, cyc)), f"{(fp / ft * 100) if ft > 0 else 0:.1f}%"]

    lw = CW * 0.56
    hA = 128
    x, y, w, h = panel(ML, TOP - hA, lw, hA, 'Par type de facture (facturé du mois · encaissé de la période)', BLUE)
    data = [['Type', 'Facturé (mois)', 'Encaissé (période)', 'Reste (mois)', 'Taux'], ligne('Scolarité + Transport', 'scol'),
            ligne("Frais d'inscription", 'insc'), ligne('Autres factures', 'autre'), ligne('TOTAL')]
    table(data, x, y + h, [w * 0.30, w * 0.21, w * 0.21, w * 0.17, w * 0.11], total_rows=(4,), head_bg=BLUE, font=7.5)
    x, y, w, h = panel(ML, BOT, lw, TOP - hA - 12 - BOT, 'Par cycle', TEAL)
    data = [['Cycle', 'Facturé (mois)', 'Encaissé (période)', 'Reste (mois)', 'Taux']] + [ligne(_cr_label_cycle(cy), None, cy) for cy in cycles] + [ligne('TOTAL')]
    th = table(data, x, y + h, [w * 0.30, w * 0.21, w * 0.21, w * 0.17, w * 0.11], total_rows=(len(data) - 1,), head_bg=TEAL, font=7.5)
    if h - th > 100:
        barres(x, y + 4, w, h - th - 10, [_cr_label_cycle(cy) for cy in cycles],
               [('Facturé', NAVY, [round(fsum(0, None, cy), 2) for cy in cycles]),
                ('Encaissé', GREEN, [round(fsum(1, None, cy), 2) for cy in cycles])])
    rx = ML + lw + 12
    rw = CW - lw - 12
    hh = (TOP - BOT - 12) / 2
    x, y, w, h = panel(rx, BOT + hh + 12, rw, hh, "Taux d'encaissement par cycle (%)", GREEN)
    barres(x, y, w, h, [_cr_label_cycle(cy) for cy in cycles] + ['Global'],
           [("Taux (%)", GREEN, [round((fsum(1, None, cy) / fsum(0, None, cy) * 100) if fsum(0, None, cy) > 0 else 0.0, 1) for cy in cycles]
             + [round(taux_enc, 1)])], fmt=lambda v: f"{v:.1f}%")
    x, y, w, h = panel(rx, BOT, rw, hh, 'Facturé vs encaissé par mois (selon l\'échéance)', BLUE)
    courbes(x, y, w, h, [('Facturé', NAVY, serie_mois(D['mois_fact'])), ('Encaissé', GREEN, serie_mois(D['mois_paye_fact']))])
    c.showPage()

    # ═══════════════ PAGE 3 : RÉDUCTIONS ═══════════════
    entete(4, 'RÉDUCTIONS ACCORDÉES', 'Différence entre le montant initial et le montant convenu, factures avec réduction')
    pw = CW * 0.54
    ph_t = 250
    x, y, w, h = panel(ML, TOP - ph_t, pw, ph_t, 'Total des réductions par type et par cycle', GOLD)
    head = ['Type'] + [_cr_label_cycle(cy) for cy in cycles] + ['Total', 'Nb fact.']
    data = [head]
    for t in types:
        data.append([TYPE_LAB[t]] + [m_(r_(t, cy)) for cy in cycles] + [m_(r_(t)), str(D['nb_red'].get(t, 0))])
    data.append(['TOTAL'] + [m_(r_(None, cy)) for cy in cycles] + [m_(total_red), str(sum(D['nb_red'].values()))])
    nc = len(head)
    first = w * 0.22
    last = w * 0.09
    mid = (w - first - last) / (nc - 2)
    table(data, x, y + h, [first] + [mid] * (nc - 2) + [last], total_rows=(len(data) - 1,), head_bg=GOLD, font=7.5)
    # synthèse initial → convenu
    net_fact = total_brut - total_red
    sy = y + h - 17 * len(data) - 16
    c.setFillColor(NAVY)
    c.setFont('Helvetica-Bold', 8.5)
    c.drawString(x + 2, sy, 'Synthèse (toutes factures de la période)')
    sdata = [['Montant initial facturé', m_(total_brut) + ' MAD'],
             ['Total des réductions', '- ' + m_(total_red) + ' MAD'],
             ['Montant convenu (net facturé)', m_(net_fact) + ' MAD'],
             ['Taux moyen de réduction', f"{taux_red:.2f}%"]]
    table(sdata, x, sy - 8, [w * 0.62, w * 0.38], align_right_from=1, total_rows=(2,), head_bg=colors.white, font=8, row_h=16, header=False)
    # taux par cycle
    ty = BOT + 8
    x2, y2, w2, h2 = panel(ML, BOT, pw, TOP - ph_t - BOT - 12, 'Taux de réduction par cycle', TEAL)
    barres(x2, y2, w2, h2, [_cr_label_cycle(cy) for cy in cycles],
           [('Taux (%)', TEAL, [round((r_(None, cy) / D['brut_cycle'][cy] * 100) if D['brut_cycle'].get(cy) else 0.0, 2) for cy in cycles])],
           fmt=lambda v: f"{v:.1f}%")
    px2 = ML + pw + 12
    pw2 = CW - pw - 12
    hh = (TOP - BOT - 12) / 2
    x, y, w, h = panel(px2, BOT + hh + 12, pw2, hh, 'Réductions par cycle et par type', GOLD)
    barres(x, y, w, h, [_cr_label_cycle(cy) for cy in cycles],
           [(TYPE_LAB[t], TYPE_COL[t], [round(r_(t, cy), 2) for cy in cycles]) for t in types])
    x, y, w, h = panel(px2, BOT, pw2, hh, 'Courbe mensuelle des réductions', CORAL)
    courbes(x, y, w, h, [('Réductions', GOLD, serie_mois(D['mois_red']))])
    c.showPage()

    # ═══════════════ PAGE 4 : CHARGES & SALAIRES ═══════════════
    entete(5, 'CHARGES ET SALAIRES', 'Charges payées par catégorie · salaires enseignants · salaires du personnel')
    lw = CW * 0.42
    x, y, w, h = panel(ML, BOT, lw, TOP - BOT, 'Charges par catégorie : payées et non payées', CORAL)
    if not D['avec_charges']:
        c.setFillColor(MUTED); c.setFont('Helvetica-Oblique', 9)
        c.drawCentredString(x + w / 2, y + h / 2, "Section réservée (accès « Charges » requis)")
    elif not D['charges_cat'] and not D['charges_np']:
        aucune_donnee(x, y, w, h)
    else:
        pd_ = {n: (m, k) for n, m, k in D['charges_cat']}
        nd_ = {n: (m, k) for n, m, k in D['charges_np']}
        rows_c = [(n, pd_.get(n, (0.0, 0))[0], nd_.get(n, (0.0, 0))[0], pd_.get(n, (0.0, 0))[1] + nd_.get(n, (0.0, 0))[1])
                  for n in set(pd_) | set(nd_)]
        rows_c.sort(key=lambda r_: -(r_[1] + r_[2]))
        MAXL = 16
        lignes, reste = rows_c[:MAXL], rows_c[MAXL:]
        data = [['Catégorie', 'Nb', 'Payé', 'Non payé', 'Total']]
        for nom, mp, mn, nb in lignes:
            data.append([nom if len(nom) <= 22 else nom[:21] + '…', str(nb), m_(mp), m_(mn), m_(mp + mn)])
        if reste:
            data.append([f"Autres catégories ({len(reste)})", str(sum(r_[3] for r_ in reste)),
                         m_(sum(r_[1] for r_ in reste)), m_(sum(r_[2] for r_ in reste)),
                         m_(sum(r_[1] + r_[2] for r_ in reste))])
        tp, tn = sum(r_[1] for r_ in rows_c), sum(r_[2] for r_ in rows_c)
        data.append(['TOTAL', str(sum(r_[3] for r_ in rows_c)), m_(tp), m_(tn), m_(tp + tn)])
        th_cat = table(data, x, y + h, [w * 0.31, w * 0.07, w * 0.21, w * 0.21, w * 0.20], total_rows=(len(data) - 1,),
                       head_bg=CORAL, font=7, row_h=min(17, (h - 4) / len(data)))
        if h - th_cat > 120:
            c.setFillColor(NAVY); c.setFont('Helvetica-Bold', 8.5)
            c.drawString(x + 2, y + h - th_cat - 16, 'Répartition des charges (payées + non payées)')
            pal = [CORAL, BLUE, TEAL, GOLD, PURPLE, GREEN, MUTED]
            top6 = rows_c[:6]
            parts = [(n if len(n) <= 22 else n[:21] + '…', pal[i], mp + mn) for i, (n, mp, mn, _) in enumerate(top6)]
            if len(rows_c) > 6:
                parts.append(('Autres', pal[6], sum(r_[1] + r_[2] for r_ in rows_c[6:])))
            anneau(x, y + 4, w, h - th_cat - 26, parts)
    rx = ML + lw + 12
    rw = CW - lw - 12
    sw = (rw - 24) / 3
    sy = TOP - 56
    kpi(rx, sy, sw, 56, 'Salaires enseignants',
        (m_(total_sal_ens) + ' MAD') if total_sal_ens is not None else '—',
        f"{D['sal_ens']['n']} paiement(s) sur la période" if total_sal_ens is not None else 'Accès « Paie » requis', PURPLE)
    kpi(rx + sw + 12, sy, sw, 56, 'Salaires personnel (hors ens.)',
        (m_(total_sal_pers) + ' MAD') if total_sal_pers is not None else '—',
        f"{D['sal_pers']['n']} paiement(s) sur la période" if total_sal_pers is not None else 'Accès « Paie » requis', TEAL)
    kpi(rx + 2 * (sw + 12), sy, sw, 56, 'Charges non payées',
        (m_(total_np) + ' MAD') if total_np is not None else '—',
        (f"{sum(k for _, _, k in D['charges_np'])} charge(s) en attente · hors solde") if total_np is not None else 'Accès « Charges » requis',
        colors.HexColor(_BULLETIN_AMBER))
    avail = sy - 12 - BOT
    ch_h = (avail - 12) / 2
    x, y, w, h = panel(rx, BOT + ch_h + 12, rw, ch_h, 'Principales catégories de charges (payé / non payé)', CORAL)
    if D['avec_charges'] and (D['charges_cat'] or D['charges_np']):
        _p = {n: m for n, m, _ in D['charges_cat']}
        _n = {n: m for n, m, _ in D['charges_np']}
        top = sorted(set(_p) | set(_n), key=lambda n_: -(_p.get(n_, 0) + _n.get(n_, 0)))[:7]
        barres(x, y, w, h, top,
               [('Payé', CORAL, [round(_p.get(n_, 0.0), 2) for n_ in top]),
                ('Non payé', colors.HexColor(_BULLETIN_AMBER), [round(_n.get(n_, 0.0), 2) for n_ in top])],
               horizontal=True, marge_gauche=120)
    else:
        aucune_donnee(x, y, w, h)
    x, y, w, h = panel(rx, BOT, rw, ch_h, 'Courbes mensuelles : charges et salaires', PURPLE)
    series = []
    if D['avec_charges']:
        series.append(('Charges', CORAL, serie_mois(D['charges_mois'])))
    if D['avec_salaires']:
        series.append(('Salaires enseignants', PURPLE, serie_mois(D['sal_ens']['mois'])))
        series.append(('Salaires personnel', TEAL, serie_mois(D['sal_pers']['mois'])))
    if series:
        courbes(x, y, w, h, series)
    else:
        aucune_donnee(x, y, w, h)
    c.showPage()

    c.save()
    buf.seek(0)
    return buf


@app.route('/export/compte-rendu-financier/pdf')
@login_required
@role_required('admin')
def export_compte_rendu_financier_pdf():
    """📑 Compte rendu financier de l'école (PDF « dashboard »). Filtres facultatifs :
    date_debut / date_fin (YYYY-MM-DD). Sans filtre : toute la période enregistrée."""
    try:
        d1, d2 = normaliser_periode_hub(request.args.get('date_debut', ''), request.args.get('date_fin', ''))
        base_calcul = 'factures' if request.args.get('base') == 'factures' else 'encaissements'
        conn = get_db()
        try:
            D = _cr_collecter_donnees(conn, d1, d2,
                                      avec_charges=peut_voir('charges'),
                                      avec_salaires=peut_voir('paiements_enseignants'),
                                      base=base_calcul)
        finally:
            conn.close()
        logo_path = None
        logo_fn = get_logo_filename()
        if logo_fn:
            candidate = os.path.join(UPLOAD_FOLDER_LOGO, logo_fn)
            if os.path.exists(candidate):
                logo_path = candidate
        titre_periode = _libelle_periode_fr(d1, d2) or 'toutes périodes'
        buf = _cr_construire_pdf(D, titre_periode, logo_path)
        nom = 'compte_rendu_financier_' + datetime.datetime.now().strftime('%Y%m%d') + '.pdf'
        return send_file(buf, as_attachment=True, download_name=nom, mimetype='application/pdf')
    except Exception as ex:
        flash(f'Erreur lors de la génération du compte rendu : {ex}', 'error')
        return redirect(url_for('paiements'))


@app.route('/export/recu/<int:paiement_id>')
@login_required
def export_recu_pdf(paiement_id):
    # 🆕 Les parents ne doivent plus pouvoir consulter ni télécharger les reçus de paiement
    # (masqué du côté interface, mais on bloque aussi l'accès direct à cette route par URL).
    if session.get('role') == 'parent':
        flash("Accès non autorisé.", 'error')
        return redirect(url_for('dashboard'))
    try:
        from reportlab.lib.pagesizes import A4
        from reportlab.lib import colors
        from reportlab.pdfgen import canvas as pdfcanvas
        from reportlab.lib.units import cm
        from xml.sax.saxutils import escape as _xml_escape

        NAVY = colors.HexColor(_BULLETIN_NAVY)
        GREEN = colors.HexColor(_BULLETIN_GREEN)
        RED = colors.HexColor(_BULLETIN_RED)
        AMBER = colors.HexColor(_BULLETIN_AMBER)

        conn = get_db()
        p = conn.execute(
            "SELECT p.*, e.prenom||' '||e.nom as eleve, e.prenom as eleve_prenom, e.nom as eleve_nom, "
            "e.photo as eleve_photo, c.nom as classe, u.prenom||' '||u.nom as parent, "
            "u.telephone as parent_telephone, "
            "e.reduction_pourcentage as eleve_reduction_pourcentage, "
            "e.reduction_transport_pourcentage as eleve_reduction_transport_pourcentage "
            "FROM paiements p JOIN eleves e ON p.eleve_id=e.id LEFT JOIN classes c ON e.classe_id=c.id "
            "LEFT JOIN users u ON e.parent_id=u.id WHERE p.id=?",
            (paiement_id,)).fetchone()
        conn.close()
        if not p:
            return "Non trouvé", 404

        # 🔄 Mêmes ressources (logo / bannière de l'école) que le bulletin scolaire, pour un
        # en-tête strictement identique sur les deux documents.
        photo_path = None
        if p['eleve_photo']:
            candidate = os.path.join(UPLOAD_FOLDER_PHOTOS, p['eleve_photo'])
            if os.path.exists(candidate):
                photo_path = candidate
        logo_path = None
        logo_fn = get_logo_filename()
        if logo_fn:
            candidate = os.path.join(UPLOAD_FOLDER_LOGO, logo_fn)
            if os.path.exists(candidate):
                logo_path = candidate
        banniere_path = None
        banniere_fn = get_banniere_bulletin_filename()
        if banniere_fn:
            candidate = os.path.join(UPLOAD_FOLDER_LOGO, banniere_fn)
            if os.path.exists(candidate):
                banniere_path = candidate

        reste = p['montant_total'] - p['montant_paye']
        statut = (p['statut'] or '').lower()
        if statut == 'paye':
            statut_label, statut_hex = 'PAYÉ INTÉGRALEMENT', _BULLETIN_GREEN
        elif p['montant_paye'] and p['montant_paye'] > 0:
            statut_label, statut_hex = 'PARTIELLEMENT PAYÉ', _BULLETIN_AMBER
        else:
            statut_label, statut_hex = 'NON PAYÉ', _BULLETIN_RED

        buf = io.BytesIO()
        c = pdfcanvas.Canvas(buf, pagesize=A4)
        W, H = A4
        ML = 1.2 * cm
        CW = W - 2 * ML

        # 🆕 Hauteur du bandeau calculée à partir du ratio réel de la bannière uploadée : la
        # largeur du bandeau reste celle de la page (CW), la hauteur suit proportionnellement
        # pour afficher la bannière EN ENTIER sans la recadrer (auparavant, une hauteur fixe de
        # 3.9cm forçait un "zoom" façon cover qui coupait le haut/le bas de l'image quand son
        # ratio ne correspondait pas exactement au bandeau). L'image elle-même n'est jamais
        # modifiée, seule la taille d'affichage du bandeau s'adapte à sa proportion réelle.
        header_h_recu = 3.9 * cm
        if banniere_path:
            try:
                img_banniere = _bulletin_safe_image(banniere_path)
                iw_b, ih_b = img_banniere.getSize()
                header_h_recu = CW * (ih_b / iw_b)
            except Exception:
                header_h_recu = 3.9 * cm

        # ═══ 1) BANDEAU D'EN-TÊTE (identique au bulletin scolaire) ═══
        header_bot = _doc_premium_header(
            c, ML, CW, H,
            title_main='REÇU DE PAIEMENT',
            subtitle_label='FACTURE — ÉTABLISSEMENT SCOLAIRE',
            badge_text=f"REÇU N° {paiement_id:04d} — {datetime.datetime.now().strftime('%d/%m/%Y')}",
            medallion_lines=[('PAIEMENT', True), ('&', False), ('CONFIANCE', True)],
            logo_path=logo_path, banniere_path=banniere_path, header_h=header_h_recu)

        # ═══ 2) CARTE D'IDENTITÉ (identique au bulletin scolaire) ═══
        initials = (p['eleve_prenom'][:1] + p['eleve_nom'][:1]) if p['eleve_prenom'] else '?'
        info_lines = [
            ('Classe', p['classe'] or '—'),
            ('Parent', p['parent'] or '—'),
            ('Téléphone', p['parent_telephone'] or '—'),
            ('Description', _desc_pdf_pct(p['description']) or '—'),
        ]
        stat_labels = [
            ('Montant total', f"{p['montant_total']:,.2f} MAD".replace(',', ' '), NAVY),
            ('Montant payé', f"{p['montant_paye']:,.2f} MAD".replace(',', ' '), GREEN),
            ('Reste à payer', f"{reste:,.2f} MAD".replace(',', ' '), RED if reste > 0 else GREEN),
        ]
        note_body = (f'<font color="{statut_hex}"><b>{_xml_escape(statut_label)}</b></font><br/>'
                     f'<font color="{_BULLETIN_TEXT_MUTED}" size="7.4">Merci pour votre confiance '
                     f'et la régularité de vos règlements.</font>')
        card_top = header_bot - 0.35 * cm
        card_h = 5.0 * cm
        card_bot = _doc_identity_card(
            c, ML, CW, card_top, card_h, initials, photo_path, p['eleve'],
            info_lines, stat_labels, 'STATUT DU PAIEMENT', note_body,
            note_footer="")

        # ═══ 3) TABLEAU FINANCIER (même style que le tableau des évaluations) ═══
        table_top = card_bot - 0.4 * cm
        headers = ['Désignation', 'Montant']
        # 🆕 Si une réduction a été appliquée sur ce paiement, on l'affiche en détail :
        # montant brut (avant réduction) -> ligne réduction -> net à payer (après réduction),
        # puis le montant déjà réglé comme avant. Sans réduction, on garde l'affichage d'origine.
        reduction_appliquee = 0.0
        try:
            reduction_appliquee = float(p['reduction_appliquee'] or 0)
        except (IndexError, KeyError, TypeError, ValueError):
            reduction_appliquee = 0.0
        montant_brut = round((p['montant_total'] or 0) + reduction_appliquee, 2)

        # 🆕 Montant transport déjà facturé sur cette ligne (net, après sa propre réduction
        # éventuelle) — permet de repérer une facture combinée « Scolarité + Transport »
        # (générée par la mensualisation automatique) et de détailler séparément les deux
        # postes sur le reçu, au lieu d'un seul bloc fusionné.
        montant_transport_p = 0.0
        try:
            montant_transport_p = float(p['montant_transport'] or 0)
        except (IndexError, KeyError, TypeError, ValueError):
            montant_transport_p = 0.0

        if montant_transport_p > 0:
            # Facture combinée Scolarité + Transport : on sépare les deux postes, chacun avec
            # son montant initial et sa propre réduction (les pourcentages de réduction sont
            # récupérés dans le libellé de la facture, où ils sont enregistrés indépendamment
            # l'un de l'autre lors de la génération — ex : "10% sur la mensualité + 5% sur le
            # transport").
            import re as _re_recu
            desc_txt = str(p['description'] or '')
            m_scol = _re_recu.search(r'([\d.,]+)\s*%\s*sur la mensualit', desc_txt)
            m_trans = _re_recu.search(r'([\d.,]+)\s*%\s*sur le transport', desc_txt)
            pct_scol = float(m_scol.group(1).replace(',', '.')) if m_scol else 0.0
            pct_trans = float(m_trans.group(1).replace(',', '.')) if m_trans else 0.0

            # 🩹 CORRECTIF : si le libellé de la facture ne contient pas (ou plus) le
            # pourcentage exploitable — anciennes factures, wording différent, etc. — on se
            # rabat sur le pourcentage de réduction actuellement configuré sur la fiche élève,
            # pour que le sous-total après réduction s'affiche toujours quand une réduction a
            # bien été appliquée (au lieu de la faire disparaître silencieusement).
            if pct_scol <= 0:
                try:
                    pct_scol = float(p['eleve_reduction_pourcentage'] or 0)
                except (IndexError, KeyError, TypeError, ValueError):
                    pct_scol = 0.0
            if pct_trans <= 0:
                try:
                    pct_trans = float(p['eleve_reduction_transport_pourcentage'] or 0)
                except (IndexError, KeyError, TypeError, ValueError):
                    pct_trans = 0.0

            scolarite_net = round((p['montant_total'] or 0) - montant_transport_p, 2)
            transport_net = montant_transport_p

            scolarite_brut = round(scolarite_net / (1 - pct_scol / 100), 2) if pct_scol > 0 else scolarite_net
            reduction_scol_montant = round(scolarite_brut - scolarite_net, 2) if pct_scol > 0 else 0.0

            transport_brut = round(transport_net / (1 - pct_trans / 100), 2) if pct_trans > 0 else transport_net
            reduction_trans_montant = round(transport_brut - transport_net, 2) if pct_trans > 0 else 0.0

            # 🆕 Détail complet ligne par ligne (montant initial → réduction → montant après
            # réduction) pour la scolarité PUIS pour le transport, chaque bloc teinté d'un fond
            # très pâle qui lui est propre (vert d'eau pour la scolarité, bleu glacé pour le
            # transport) afin de bien séparer visuellement les deux postes. Les lignes de
            # réduction sont en gris discret/italique, presque invisibles, pour ne pas
            # accrocher l'œil autant que les montants principaux.
            BG_SCOL = '#EDF7F1'
            BG_TRANS = '#EEF3FB'
            BG_REDUCTION = '#D9C57A'   # 🎨 or lux froid — lignes de réduction
            BG_SOUS_TOTAL = '#A9C6EA'  # 🎨 bleu froid — lignes "Total ... après réduction"
            BG_NET_A_PAYER = '#A9DDBB' # 🎨 vert — ligne "Net à payer"
            NOIR = '#000000'
            rows = []
            row_styles = {}
            boxes = []

            _scol_start = len(rows)
            rows.append(['Frais de scolarité', f"{scolarite_brut:,.2f} MAD".replace(',', ' ')])
            row_styles[len(rows) - 1] = {'bg': BG_SCOL}
            if reduction_scol_montant > 0:
                rows.append([f'Réduction scolarité ({_pct_aff(pct_scol)}%)', f"- {reduction_scol_montant:,.2f} MAD".replace(',', ' ')])
                row_styles[len(rows) - 1] = {'bg': BG_REDUCTION, 'text_color': NOIR}
                rows.append(['Total scolarité après réduction', f"{scolarite_net:,.2f} MAD".replace(',', ' ')])
                row_styles[len(rows) - 1] = {'bg': BG_SOUS_TOTAL, 'text_color': NOIR, 'bold': True}
            boxes.append((_scol_start, len(rows) - 1))

            _trans_start = len(rows)
            rows.append(['Frais de transport', f"{transport_brut:,.2f} MAD".replace(',', ' ')])
            row_styles[len(rows) - 1] = {'bg': BG_TRANS}
            if reduction_trans_montant > 0:
                rows.append([f'Réduction transport ({_pct_aff(pct_trans)}%)', f"- {reduction_trans_montant:,.2f} MAD".replace(',', ' ')])
                row_styles[len(rows) - 1] = {'bg': BG_REDUCTION, 'text_color': NOIR}
                rows.append(['Total transport après réduction', f"{transport_net:,.2f} MAD".replace(',', ' ')])
                row_styles[len(rows) - 1] = {'bg': BG_SOUS_TOTAL, 'text_color': NOIR, 'bold': True}
            boxes.append((_trans_start, len(rows) - 1))

            rows.append(['Net à payer', f"{p['montant_total']:,.2f} MAD".replace(',', ' ')])
            row_styles[len(rows) - 1] = {'bg': BG_NET_A_PAYER, 'text_color': NOIR, 'bold': True}
            rows.append(['Montant déjà réglé', f"- {p['montant_paye']:,.2f} MAD".replace(',', ' ')])
        elif reduction_appliquee > 0:
            # 🆕 Taux de réduction toujours affiché à côté de la ligne "Réduction appliquée" :
            # on le récupère depuis le libellé de la facture (déjà enregistré lors de sa
            # création — ex : "10% sur la mensualité" ou "(Réduction 10% appliquée)" pour un
            # Frais d'inscription), avec un repli sur un calcul à partir des montants si le
            # libellé ne contient pas de pourcentage exploitable.
            import re as _re_recu2
            desc_txt2 = str(p['description'] or '')
            m_pct = (_re_recu2.search(r'([\d.,]+)\s*%\s*sur la mensualit', desc_txt2)
                     or _re_recu2.search(r'Réduction\s*([\d.,]+)\s*%\s*appliquée', desc_txt2)
                     or _re_recu2.search(r'([\d.,]+)\s*%', desc_txt2))
            if m_pct:
                pct_reduc = float(m_pct.group(1).replace(',', '.'))
            elif montant_brut > 0:
                pct_reduc = round(reduction_appliquee / montant_brut * 100, 2)
            else:
                pct_reduc = 0.0
            # 🆕 Même logique détaillée (montant initial → réduction grisée/discrète → montant
            # après réduction) que pour le cas combiné scolarité + transport ci-dessus.
            rows = [[_desc_pdf_pct(p['description']) or 'Montant scolarité', f"{montant_brut:,.2f} MAD".replace(',', ' ')]]
            row_styles = {}
            rows.append([f'Réduction ({_pct_aff(pct_reduc)}%)', f"- {reduction_appliquee:,.2f} MAD".replace(',', ' ')])
            row_styles[len(rows) - 1] = {'bg': '#D9C57A', 'text_color': '#000000'}
            rows.append(['Net à payer', f"{p['montant_total']:,.2f} MAD".replace(',', ' ')])
            row_styles[len(rows) - 1] = {'bg': '#A9DDBB', 'text_color': '#000000', 'bold': True}
            boxes = [(0, len(rows) - 1)]
            rows.append(['Montant déjà réglé', f"- {p['montant_paye']:,.2f} MAD".replace(',', ' ')])
        else:
            rows = [
                [_desc_pdf_pct(p['description']) or 'Frais de scolarité', f"{p['montant_total']:,.2f} MAD".replace(',', ' ')],
                ['Montant déjà réglé', f"- {p['montant_paye']:,.2f} MAD".replace(',', ' ')],
            ]
            row_styles = {}
            boxes = []
        total_row = ['SOLDE RESTANT DÛ', f"{reste:,.2f} MAD".replace(',', ' ')]
        col_w = [12.6 * cm, 6.0 * cm]
        th = _doc_finance_table(c, ML, CW, table_top, headers, rows, col_w, total_row=total_row,
                                 row_styles=row_styles, boxes=boxes)

        # ═══ 4) ENCART INFORMATIONS COMPLÉMENTAIRES ═══
        panel_top = table_top - th - 0.4 * cm
        panel_h = 1.9 * cm
        # 🆕 "Mois payé" (ou "Saison payée" pour un Frais d'inscription) remplace "Date
        # d'échéance" (peu utile sur un reçu déjà réglé), et "Date de paiement" affiche
        # désormais le jour complet (uniquement sur ce document).
        categorie_recu = ''
        if p['description'] and ']' in str(p['description']):
            categorie_recu = str(p['description']).split(']')[0].lstrip('[').strip()
        label_periode = 'Saison payée' if categorie_recu.lower() == "frais d'inscription" else 'Mois payé'
        mois_paye = _label_mois_paye(p) or '—'
        date_paie = _bulletin_date_fr(p['date_paiement']) or '—'
        _doc_info_panel(c, ML, CW, panel_top, panel_h, 'INFORMATIONS COMPLÉMENTAIRES', [
            (label_periode, mois_paye),
            ('Date de paiement', date_paie),
            ('Année scolaire', _bulletin_annee_scolaire()),
        ])

        # ═══ 5) SIGNATURE ═══
        sig_y = panel_top - panel_h - 1.6 * cm

        # 🆕 Mention "Fait à FES, le [date complète]" (convention factures), juste au-dessus de
        # la signature — seule date à apparaître en entier (jour + mois + année) sur le document.
        c.setFillColor(colors.HexColor(_BULLETIN_TEXT_MUTED))
        c.setFont('Helvetica', 8)
        c.drawRightString(ML + CW, sig_y + 0.5 * cm,
                          f"Fait à FES, le {_bulletin_date_fr(datetime.datetime.now().strftime('%Y-%m-%d'))}")

        _doc_signature_block(c, ML, CW, sig_y,
                             ["Cachet & signature de l'établissement"])

        # ═══ 6) BANDEAU DE CITATION + PIED DE PAGE (identique au bulletin scolaire) ═══
        _doc_quote_bandeau(c, ML, CW,
                           "« La confiance est la monnaie la plus précieuse d'un partenariat durable. »",
                           quote_y=sig_y - 1.9 * cm)

        c.save()
        buf.seek(0)
        return send_file(buf, as_attachment=True, download_name=f'recu_{paiement_id:04d}.pdf',
                         mimetype='application/pdf')
    except Exception as ex:
        flash(f'Erreur: {ex}', 'error');
        return redirect(url_for('paiements'))


@app.route('/export/bulletin-paie/enseignant/<int:paiement_id>')
@login_required
@role_required('admin')
def export_bulletin_paie_enseignant(paiement_id):
    # 🆕 AGENT ADMIN : pas d'accès aux fiches de paie des enseignants (sauf autorisation de l'admin)
    if session.get('role') == 'agent_admin' and not peut_voir('paiements_enseignants'):
        flash('Accès non autorisé.', 'error')
        return redirect(url_for('paiements_enseignants'))
    try:
        from reportlab.lib.pagesizes import A4
        from reportlab.lib import colors
        from reportlab.pdfgen import canvas as pdfcanvas
        from reportlab.lib.units import cm
        from xml.sax.saxutils import escape as _xml_escape

        NAVY = colors.HexColor(_BULLETIN_NAVY)
        GREEN = colors.HexColor(_BULLETIN_GREEN)

        conn = get_db()
        p = conn.execute("""
                         SELECT pe.*, u.nom, u.prenom, u.cin, u.cnss, u.adresse,
                                u.matiere_specialite, u.date_embauche, u.telephone
                         FROM paiements_enseignants pe
                                  JOIN users u ON pe.enseignant_id = u.id
                         WHERE pe.id = ?
                         """, (paiement_id,)).fetchone()
        conn.close()

        if not p:
            flash('Fiche de paie introuvable.', 'error')
            return redirect(url_for('paiements_enseignants'))
        if p['statut'] != 'paye':
            flash("Le bulletin de paie n'est disponible qu'après validation du paiement.", 'error')
            return redirect(url_for('paiements_enseignants'))

        # 🔄 Mêmes ressources (logo / bannière de l'école) que le bulletin scolaire.
        logo_path = None
        logo_fn = get_logo_filename()
        if logo_fn:
            candidate = os.path.join(UPLOAD_FOLDER_LOGO, logo_fn)
            if os.path.exists(candidate):
                logo_path = candidate
        banniere_path = None
        banniere_fn = get_banniere_bulletin_filename()
        if banniere_fn:
            candidate = os.path.join(UPLOAD_FOLDER_LOGO, banniere_fn)
            if os.path.exists(candidate):
                banniere_path = candidate

        type_p = (p['type_paiement'] or 'Mensuel')
        if type_p.lower() == 'mensuel':
            libelle_type = 'Salaire mensuel forfaitaire'
        else:
            libelle_type = f"{type_p} — {p['unites_validees'] or 0} unité(s) validée(s)"
        reste = (p['montant_total'] or 0) - (p['montant_paye'] or 0)

        buf = io.BytesIO()
        c = pdfcanvas.Canvas(buf, pagesize=A4)
        W, H = A4
        ML = 1.2 * cm
        CW = W - 2 * ML

        # ═══ 1) BANDEAU D'EN-TÊTE (identique au bulletin scolaire) ═══
        header_bot = _doc_premium_header(
            c, ML, CW, H,
            title_main='BULLETIN DE PAIE',
            subtitle_label='PERSONNEL ENSEIGNANT',
            badge_text=f"PÉRIODE : {str(p['mois']).upper()}",
            medallion_lines=[('RIGUEUR', True), ('&', False), ('RECONNAISSANCE', True)],
            logo_path=logo_path, banniere_path=banniere_path)

        # ═══ 2) CARTE D'IDENTITÉ (identique au bulletin scolaire) ═══
        initials = (p['prenom'][:1] + p['nom'][:1]) if p['prenom'] else '?'
        info_lines = [
            ('Fonction', f"Enseignant — {p['matiere_specialite'] or 'Non spécifiée'}"),
            ('CIN', p['cin'] or 'N/A'),
            ('N° CNSS', p['cnss'] or 'N/A'),
            ('Téléphone', p['telephone'] or 'N/A'),
            ("Date d'embauche", p['date_embauche'] or 'N/A'),
        ]
        stat_labels = [
            ('Montant net à payer', f"{p['montant_total']:,.2f} MAD".replace(',', ' '), NAVY),
            ('Montant versé', f"{p['montant_paye']:,.2f} MAD".replace(',', ' '), GREEN),
        ]
        note_body = (f'<font color="{_BULLETIN_GREEN}"><b>PAYÉ ✓</b></font><br/>'
                     f'<font color="{_BULLETIN_TEXT_MUTED}" size="7.4">Bulletin n° {paiement_id:04d} — '
                     f'{_xml_escape(libelle_type)}.</font>')
        card_top = header_bot - 0.35 * cm
        card_h = 5.0 * cm
        card_bot = _doc_identity_card(
            c, ML, CW, card_top, card_h, initials, None, f"{p['prenom']} {p['nom']}",
            info_lines, stat_labels, 'STATUT DU PAIEMENT', note_body,
            note_footer='La Direction')

        # ═══ 3) TABLEAU FINANCIER (même style que le tableau des évaluations) ═══
        table_top = card_bot - 0.4 * cm
        headers = ['Désignation', 'Montant']
        rows = [
            ['Type de rémunération', libelle_type],
            ['Montant brut / net à payer', f"{p['montant_total']:,.2f} MAD".replace(',', ' ')],
        ]
        # 🎓 Avantage de scolarité des enfants (en nature, non versé en espèces) affiché à part
        try:
            _av = float(p['avantage_scolarite'] or 0)
        except (IndexError, KeyError, TypeError, ValueError):
            _av = 0.0
        if abs(_av) > 0.009:
            rows.append(['Avantage de scolarité des enfants (en nature)', f"{_av:,.2f} MAD".replace(',', ' ')])
            rows.append(['Rémunération totale calculée (paie + avantage)', f"{(p['montant_total'] or 0) + _av:,.2f} MAD".replace(',', ' ')])
        total_row = ['MONTANT RÉELLEMENT VERSÉ', f"{p['montant_paye']:,.2f} MAD".replace(',', ' ')]
        col_w = [12.6 * cm, 6.0 * cm]
        th = _doc_finance_table(c, ML, CW, table_top, headers, rows, col_w, total_row=total_row)

        # ═══ 4) ENCART INFORMATIONS COMPLÉMENTAIRES ═══
        panel_top = table_top - th - 0.4 * cm
        panel_h = 1.9 * cm
        date_p = _bulletin_date_fr(p['date_paiement']) or (p['date_paiement'] or '—')
        _doc_info_panel(c, ML, CW, panel_top, panel_h, 'INFORMATIONS COMPLÉMENTAIRES', [
            ('Adresse', p['adresse'] or '—'),
            ('Date de paiement', date_p),
            ('Année scolaire', _bulletin_annee_scolaire()),
        ])

        # ═══ 5) SIGNATURES ═══
        sig_y = panel_top - panel_h - 1.6 * cm
        _doc_signature_block(c, ML, CW, sig_y,
                             ['Signature Direction', 'Signature Employé'])

        # ═══ 6) BANDEAU DE CITATION + PIED DE PAGE (identique au bulletin scolaire) ═══
        _doc_quote_bandeau(c, ML, CW,
                           "« Le travail accompli avec cœur mérite une reconnaissance à sa mesure. »",
                           quote_y=sig_y - 1.9 * cm)

        c.save()
        buf.seek(0)
        nom_fichier = f'bulletin_paie_{p["nom"]}_{p["prenom"]}_{p["mois"]}.pdf'.replace(' ', '_')
        return send_file(buf, as_attachment=True, download_name=nom_fichier, mimetype='application/pdf')
    except Exception as ex:
        flash(f'Erreur génération du bulletin de paie: {ex}', 'error')
        return redirect(url_for('paiements_enseignants'))


