@app.route('/api/stats/paiements')
@login_required
@role_required('admin')
def api_stats_paiements():
    conn = get_db()
    data = conn.execute("SELECT statut, COUNT(*) as n FROM paiements GROUP BY statut").fetchall()
    conn.close()
    return jsonify([{'statut': r['statut'], 'count': r['n']} for r in data])


@app.route('/api/stats/notes')
@login_required
@role_required('admin')
def api_stats_notes():
    conn = get_db()
    data = _matieres_moyennes_ponderees(conn)[:8]
    conn.close()
    return jsonify([{'matiere': r['matiere'], 'moyenne': round(r['moyenne'], 2)} for r in data])


# ─────────────────────────────────────────────
# PROFILE
# ─────────────────────────────────────────────
@app.route('/parametres/nom-ecole', methods=['POST'])
@login_required
@role_required('admin')
def parametres_nom_ecole():
    # Enregistre le nom de l'école (affiché partout) et sa version arabe facultative
    import re as _re
    def _propre(v):
        v = _re.sub(r'[<>\x00-\x1f]', '', v or '')          # pas de balises ni de caractères de contrôle
        return _re.sub(r'\s+', ' ', v).strip()[:80]
    nom = _propre(request.form.get('nom_ecole'))
    nom_ar = _propre(request.form.get('nom_ecole_ar'))
    if not nom:
        flash("Le nom de l'école ne peut pas être vide.", 'error')
        return redirect(url_for('profile'))
    upgrade_db_nom_ecole()
    conn = get_db()
    try:
        ancien = get_nom_ecole()
        if not conn.execute("SELECT 1 FROM parametres_ecole WHERE id=1").fetchone():
            conn.execute("INSERT INTO parametres_ecole (id, adresse) VALUES (1, '')")
        conn.execute("UPDATE parametres_ecole SET nom_ecole=?, nom_ecole_ar=? WHERE id=1", (nom, nom_ar))
        log_action(conn, 'modification', 'parametres', 1, f"Nom de l'école : « {ancien} » → « {nom} »")
        conn.commit()
        flash(f"Nom de l'école enregistré : {nom} ✓", 'success')
    except Exception as e:
        conn.rollback()
        flash(f"Erreur lors de l'enregistrement du nom : {e}", 'error')
    finally:
        conn.close()
    return redirect(url_for('profile'))


@app.route('/profile', methods=['GET', 'POST'])
@login_required
def profile():
    conn = get_db()
    if request.method == 'POST':
        f = request.form
        # 🆕 Admin : choix du système de notation de chaque cycle (lettres / sur 10 / sur 20)
        if f.get('action') == 'systemes_notes':
            if session.get('role') != 'admin':
                flash('Action non autorisée.', 'error')
                conn.close()
                return redirect(url_for('profile'))
            nb = 0
            for c in get_all_cycles(conn):
                choix = f.get('systeme_' + str(c['id']))
                if choix in SYSTEMES_NOTES:
                    conn.execute("UPDATE cycles SET systeme_notes=? WHERE id=?", (choix, c['id']))
                    nb += 1
            conn.commit()
            conn.close()
            flash('Systèmes de notation enregistrés.' if nb else 'Aucun changement.', 'success')
            return redirect(url_for('profile'))
        if f.get('new_password'):
            old = hash_pw(f.get('old_password', ''))
            user = conn.execute("SELECT password FROM users WHERE id=?", (session['user_id'],)).fetchone()
            if user['password'] != old:
                flash('Ancien mot de passe incorrect!', 'error')
                conn.close();
                return redirect(url_for('profile'))
            conn.execute("UPDATE users SET password=? WHERE id=?", (hash_pw(f['new_password']), session['user_id']))
        conn.execute("UPDATE users SET nom=?,prenom=?,email=? WHERE id=?",
                     (f['nom'], f['prenom'], f['email'], session['user_id']))
        session['nom_complet'] = f"{f['prenom']} {f['nom']}"
        conn.commit()
        flash('Profil mis à jour!', 'success')
    user = conn.execute("SELECT * FROM users WHERE id=?", (session['user_id'],)).fetchone()
    cycles_systemes = []
    if session.get('role') == 'admin':
        for c in get_all_cycles(conn):
            cycles_systemes.append({'id': c['id'], 'nom': c['nom'], 'icone': c.get('icone') or '🏫',
                                    'systeme': get_systeme_notes(c['nom'], conn)})
    conn.close()
    _nom_brut, _nom_ar_brut = _lire_nom_ecole_brut()
    return render_template_string(PROFILE_HTML, user=user, notif_count=get_notif_count(),
                                  cycles_systemes=cycles_systemes, systemes_notes=SYSTEMES_NOTES,
                                  nom_ecole_val=_nom_brut or NOM_ECOLE_DEFAUT, nom_ecole_ar_val=_nom_ar_brut,
                                  nom_ecole_ar_defaut=get_nom_ecole_ar(),
                                  logo_filename=get_logo_filename(),
                                  banniere_bulletin_filename=get_banniere_bulletin_filename(),
                                  couleurs=get_couleurs_personnalisees())


