# ── Moteur de traduction (voir docstring de translate_html) ──
import html as _html_i18n

# Mots ambigus / très courts : traduits UNIQUEMENT quand ils forment à eux seuls le texte
# d'un élément (ex. un en-tête de colonne, un bouton) — jamais au milieu d'une phrase française.
_TR_EXACT_ONLY = {
    "Lun", "Mar", "Mer", "Jeu", "Ven", "Sam", "Dim", "Oui", "Non", "Bon", "Fin", "Début", "Soir", "Matin",
    "Sens", "Liste", "Cartes", "Tableau", "Autre", "Divers", "Achat", "Service", "Voyage", "Facile",
    "Difficile", "Neutre", "Passable", "Ordre", "Suivi", "Vues", "Stable", "Progrès", "Compte", "Excel",
    "Tout", "Moyen", "Haute", "Basse", "Normale", "Excellent", "Sécurité", "Gérer", "Voir", "Ouvrir",
    "Détail", "Fait", "Actif", "Actifs", "Actives", "Bon suivi", "Tâche", "Période", "Distance",
}

_TR_WORD = _re_i18n.compile(r"\w+", _re_i18n.UNICODE)
_TR_WS = _re_i18n.compile(r"\s+")
_TR_LEAD = _re_i18n.compile(r"^[^\w]*", _re_i18n.UNICODE)
_TR_TRAIL = _re_i18n.compile(r"[^\w]*$", _re_i18n.UNICODE)


def _tr_norm(s):
    return _TR_WS.sub(" ", _html_i18n.unescape(s)).strip().lower()


def _tr_build(glossary):
    """Prépare : table exacte (insensible à la casse) + phrases « en ligne » indexées par premier mot.
    Les clés explicites passent avant les variantes automatiques (« milieu de phrase »)."""
    exact, entries, seen = {}, [], set()

    def _add(v, ar, fr):
        exact.setdefault(_tr_norm(v), ar)
        if fr in _TR_EXACT_ONLY or v in seen:
            return
        seen.add(v)
        pat = _re_i18n.compile(r"(?<!\w)" + r"\s+".join(_re_i18n.escape(p) for p in v.split(" ")) + r"(?!\w)")
        entries.append((v, ar, pat))

    for fr, ar in glossary.items():
        _add(fr, ar, fr)
        if "&" in fr:
            _add(fr.replace("&", "&amp;"), ar, fr)
    for fr, ar in glossary.items():
        if fr[:1].isupper() and (" " in fr or len(fr) >= 7):
            v = fr[0].lower() + fr[1:]
            if v not in glossary:
                _add(v, ar, fr)
    entries.sort(key=lambda e: -len(e[0]))  # tri stable : à longueur égale, l'ordre d'insertion est conservé
    index = {}
    for i, (v, _ar, _p) in enumerate(entries):
        m = _TR_WORD.search(v)
        if m:
            index.setdefault(m.group(0).lower(), []).append(i)
    return exact, entries, index


