# Les entités HTML (&larr; &rarr; &nbsp; &lsaquo;…) en début/fin de texte comptent comme de la ponctuation
# (sinon « &larr; Retour » ou « Ouvrir &rarr; » n'étaient jamais reconnus).
_TR_LEAD = _re_i18n.compile(r"^(?:&#?\w+;|[^\w])*", _re_i18n.UNICODE)
_TR_TRAIL = _re_i18n.compile(r"(?:&#?\w+;|[^\w])*$", _re_i18n.UNICODE)

_TR_EXACT, _TR_ENTRIES, _TR_INDEX = _tr_build(TRANSLATIONS_AR)
_TR_CACHE = {}


def _tr_text(text):
    """Traduit un texte visible (nœud de texte, valeur d'attribut, littéral JS)."""
    if not text or not _TR_WORD.search(text):
        return text
    hit = _TR_CACHE.get(text)
    if hit is not None:
        return hit
    lead = _TR_WS.match(text).group(0) if text[:1].isspace() else ""
    core = text.strip()
    out = None
    # 1) correspondance exacte du texte entier (casse ignorée, entités décodées)
    ar = _TR_EXACT.get(_tr_norm(core))
    if ar is not None:
        out = ar
    else:
        # 2) idem en ignorant emoji / ponctuation en début et fin (« 🌅 Matin », « Fin : »)
        pre = _TR_LEAD.match(core).group(0)
        suf = _TR_TRAIL.search(core).group(0) if len(pre) < len(core) else ""
        mid = core[len(pre):len(core) - len(suf)] if suf else core[len(pre):]
        ar = _TR_EXACT.get(_tr_norm(mid)) if mid else None
        if ar is not None:
            out = pre + ar + suf
    if out is None:
        # 3) remplacement de phrases à l'intérieur du texte (mots entiers, plus long d'abord)
        cand = set()
        for w in _TR_WORD.findall(core):
            cand.update(_TR_INDEX.get(w.lower(), ()))
        out = core
        for i in sorted(cand):
            _v, ar, pat = _TR_ENTRIES[i]
            out = pat.sub(ar, out)
    trail = text[len(text.rstrip()):]
    res = lead + out + trail
    if len(_TR_CACHE) < 20000:
        _TR_CACHE[text] = res
    return res



# ═══ 🆕 PHRASES DYNAMIQUES (avec nombres / pluriels) — traduites par motifs ═══
# Les phrases du type « 3 professeurs déjà pointés sur 8 cours. » changent à chaque affichage (nombres, « s » du
# pluriel) : le dictionnaire ne peut pas les reconnaître. Chaque motif ci-dessous les traduit en gardant les nombres.

def _tr_cnt(sing, dual, plur, acc=None, fem=False):
    """Accord nombre/nom en arabe : 1 → « تلميذ واحد », 2 → duel, 3-10 → pluriel, 11+ → singulier à l'accusatif."""
    def _f(m):
        n = int(m.group(1))
        if n == 1:
            return sing + (" واحدة" if fem else " واحد")
        if n == 2:
            return dual
        if 3 <= n <= 10:
            return "%d %s" % (n, plur)
        return "%d %s" % (n, acc or sing)
    return _f


