    (r"séances?", "حصة", "حصتان", "حصص", "حصة", True),
    (r"cours", "درس", "درسان", "دروس", "درسًا", False),
    (r"rendez-vous", "موعد", "موعدان", "مواعيد", "موعدًا", False),
    (r"notifications?", "إشعار", "إشعاران", "إشعارات", "إشعارًا", False),
