@app.route('/hub/<nom>')
@login_required
@role_required('admin')
def hub_gestion(nom):
    hub = HUB_PAGES.get(nom)
    if not hub:
        flash('Page introuvable.', 'error')
        return redirect(url_for('dashboard'))
    if session.get('role') != 'admin':  # 🔐 la page Autorisation est réservée à l'admin
        hub = dict(hub, liens=[l for l in hub['liens'] if l[2] != '/admin/autorisations'])
    if nom == 'pedagogique':  # 📅 nombre de demandes de rendez-vous en attente sur la carte « Rendez-vous »
        try:
            _c_rdv = get_db()
            try:
                _rdv_assurer_table(_c_rdv)
                _n_rdv = _c_rdv.execute("SELECT COUNT(*) FROM rendez_vous WHERE statut='en_attente'").fetchone()[0]
            finally:
                _c_rdv.close()
            if _n_rdv:
                hub = dict(hub, liens=[(l[0], l[1], l[2], f"{l[3]} — {_n_rdv} en attente" if l[2] == '/rendez-vous' else l[3])
                                       for l in hub['liens']])
        except Exception:
            pass
    return render_template_string(HUB_HTML, hub=hub, nom=nom, notif_count=get_notif_count())


# ─────────────────────────────────────────────
# 📅 RENDEZ-VOUS PARENT ↔ ADMINISTRATION
# Le parent réserve un créneau depuis son tableau de bord ; les agents admin (et l'admin) sont
# notifiés et traitent les demandes sur la page « Rendez-vous » (Gestion pédagogique).
# Si aucun créneau ne convient, le parent écrit directement à l'agent admin.
# ─────────────────────────────────────────────
RDV_DUREE_MIN = 15              # durée d'un créneau (minutes)
RDV_HORIZON_JOURS = 21          # on peut réserver jusqu'à 3 semaines à l'avance
RDV_JOURS_OUVRES = (0, 1, 2, 3, 4)   # lundi → vendredi
RDV_MAX_ACTIFS = 3              # rendez-vous à venir simultanés par parent
# Paiement et réclamation : 08h30 → 10h00, puis l'après-midi de 13h00 → 14h00.
RDV_FENETRES_PAIEMENT = (('08:30', '10:00'), ('13:00', '14:00'))
# Autres motifs (à ajuster ici si besoin) : tranches distinctes, plus tard dans la journée.
RDV_FENETRES_AUTRES = (('10:00', '12:00'), ('14:00', '16:00'))
RDV_MOTIFS = {
    'paiement':    {'label': 'Paiement', 'ico': '💳', 'couleur': '#059669', 'fenetres': RDV_FENETRES_PAIEMENT,
                    'desc': 'Régler une facture, un échéancier ou demander un reçu'},
    'reclamation': {'label': 'Réclamation', 'ico': '⚠️', 'couleur': '#DC2626', 'fenetres': RDV_FENETRES_PAIEMENT,
                    'desc': 'Signaler un problème ou déposer une réclamation'},
    'scolarite':   {'label': 'Suivi scolaire', 'ico': '🎓', 'couleur': '#2563EB', 'fenetres': RDV_FENETRES_AUTRES,
                    'desc': 'Résultats, comportement, orientation de votre enfant'},
    'transport':   {'label': 'Transport', 'ico': '🚌', 'couleur': '#F59E0B', 'fenetres': RDV_FENETRES_AUTRES,
                    'desc': 'Abonnement, trajet, horaires de ramassage'},
    'autre':       {'label': 'Autre demande', 'ico': '💬', 'couleur': '#7C3AED', 'fenetres': RDV_FENETRES_AUTRES,
                    'desc': 'Toute autre question à voir avec l\'administration'},
}
RDV_MODES = {'presentiel': '🏫 Sur place', 'telephone': '📞 Appel téléphonique'}
RDV_STATUTS = {
    'en_attente': ('⏳ En attente', '#B45309', '#FEF3C7'),
    'confirme':   ('✅ Confirmé', '#047857', '#D1FAE5'),
    'refuse':     ('❌ Refusé', '#B91C1C', '#FEE2E2'),
    'annule':     ('🚫 Annulé', '#475569', '#E2E8F0'),
    'termine':    ('🏁 Terminé', '#1D4ED8', '#DBEAFE'),
}
_RDV_JOURS = ['lundi', 'mardi', 'mercredi', 'jeudi', 'vendredi', 'samedi', 'dimanche']
_RDV_MOIS = ['janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre',
             'octobre', 'novembre', 'décembre']


def _rdv_fmt_date(d):
    """'2026-10-20' → 'mardi 20 octobre'."""
    try:
        dt = datetime.date.fromisoformat(str(d)[:10])
        return f"{_RDV_JOURS[dt.weekday()]} {dt.day} {_RDV_MOIS[dt.month - 1]}"
    except Exception:
        return str(d or '')


def _rdv_fmt_heure(h):
    """'08:30' → '08h30'."""
    return str(h or '').replace(':', 'h')


def _rdv_fenetres_txt(motif):
    cfg = RDV_MOTIFS.get(motif) or RDV_MOTIFS['autre']
    return ' · '.join(f"{_rdv_fmt_heure(a)} – {_rdv_fmt_heure(b)}" for a, b in cfg['fenetres'])


def _rdv_assurer_table(conn):
    """Crée la table des rendez-vous si besoin (sans toucher aux autres tables). Idempotent."""
    existe = conn.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='rendez_vous'").fetchone()
    if existe:
        return
    conn.execute("""
        CREATE TABLE IF NOT EXISTS rendez_vous (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            parent_id INTEGER NOT NULL,
            eleve_id INTEGER,
            motif TEXT NOT NULL,
            mode TEXT DEFAULT 'presentiel',
            priorite TEXT DEFAULT 'normale',
            note TEXT,
            date_rdv DATE,
            heure_rdv TEXT,
            duree_min INTEGER DEFAULT 15,
            type_demande TEXT DEFAULT 'creneau',
            statut TEXT DEFAULT 'en_attente',
            reponse_admin TEXT,
            traite_par INTEGER,
            date_traitement DATETIME,
            date_creation DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    """)
    try:
        # Un seul rendez-vous actif par créneau (protège aussi contre deux réservations simultanées).
        conn.execute("""CREATE UNIQUE INDEX IF NOT EXISTS idx_rdv_creneau_unique ON rendez_vous(date_rdv, heure_rdv)
                        WHERE statut IN ('en_attente','confirme') AND date_rdv IS NOT NULL AND heure_rdv IS NOT NULL""")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_rdv_parent ON rendez_vous(parent_id)")
    except sqlite3.OperationalError:
        pass
    conn.commit()


def upgrade_db_rendez_vous():
    """Migration idempotente (rejouée au démarrage et après restauration)."""
    if not os.path.exists(DB_PATH):
        return
    try:
        conn = get_db()
        try:
            _rdv_assurer_table(conn)
        finally:
            conn.close()
    except Exception as e:
        print(f"  ⚠️  Migration rendez_vous a échoué : {e}")


def _rdv_heures_motif(motif):
    """Liste des heures de début de créneau ('08:30', '08:45', ...) autorisées pour un motif."""
    cfg = RDV_MOTIFS.get(motif)
    if not cfg:
        return []
    heures = []
    for debut, fin in cfg['fenetres']:
        h1, m1 = (int(x) for x in debut.split(':'))
        h2, m2 = (int(x) for x in fin.split(':'))
        t, t_fin = h1 * 60 + m1, h2 * 60 + m2
        while t + RDV_DUREE_MIN <= t_fin:
            heures.append('%02d:%02d' % (t // 60, t % 60))
            t += RDV_DUREE_MIN
    return heures


def _rdv_creneau_valide(motif, date_iso, heure, maintenant=None):
    """Vérifie qu'un (jour, heure) respecte les horaires du motif. Retourne (ok, message d'erreur)."""
    if motif not in RDV_MOTIFS:
        return False, "Motif de rendez-vous invalide."
    try:
        d = datetime.date.fromisoformat(str(date_iso))
    except ValueError:
        return False, "Date invalide."
    now = maintenant or datetime.datetime.now()
    today = now.date()
    if d < today or d > today + datetime.timedelta(days=RDV_HORIZON_JOURS):
        return False, "Cette date n'est pas ouverte à la réservation."
    if d.weekday() not in RDV_JOURS_OUVRES:
        return False, "Les rendez-vous ont lieu du lundi au vendredi."
    if heure not in _rdv_heures_motif(motif):
        return False, (f"Pour un rendez-vous « {RDV_MOTIFS[motif]['label']} », "
                       f"les horaires sont : {_rdv_fenetres_txt(motif)}.")
    if d == today:
        hh, mm = (int(x) for x in heure.split(':'))
        if datetime.datetime.combine(d, datetime.time(hh, mm)) < now + datetime.timedelta(minutes=30):
            return False, "Ce créneau est trop proche ou déjà passé."
    return True, ''


def _rdv_ids_admins(conn):
    return [r['id'] for r in conn.execute("SELECT id FROM users WHERE role IN ('agent_admin','admin')").fetchall()]


def _rdv_notifier_admins(conn, msg, titre, prio='normale'):
    """Notification (in-app + push) envoyée à tous les agents admin et à l'admin → page Rendez-vous."""
    for aid in _rdv_ids_admins(conn):
        notif_to_parent(aid, msg, conn, categorie='autre', titre=titre, url='/rendez-vous',
                        meta={'ico': '📅', 'couleur': '#7C3AED', 'cta': 'Voir la demande'}, prio=prio)


def _rdv_notifier_parent(conn, parent_id, msg, titre, couleur='#7C3AED'):
    notif_to_parent(parent_id, msg, conn, categorie='autre', titre=titre, url='/rendez-vous',
                    meta={'ico': '📅', 'couleur': couleur, 'cta': 'Voir mon rendez-vous'}, prio='haute')


def _rdv_enrichir(r, role='parent'):
    """Ajoute les libellés d'affichage à une ligne de la table rendez_vous."""
    d = dict(r)
    motif = RDV_MOTIFS.get(d.get('motif')) or RDV_MOTIFS['autre']
    d['motif_label'], d['motif_ico'], d['motif_couleur'] = motif['label'], motif['ico'], motif['couleur']
    d['mode_label'] = RDV_MODES.get(d.get('mode'), '')
    d['est_message'] = (d.get('type_demande') == 'message')
    d['date_txt'] = _rdv_fmt_date(d['date_rdv']) if d.get('date_rdv') else ''
    d['heure_txt'] = _rdv_fmt_heure(d.get('heure_rdv'))
    lab, col, bg = RDV_STATUTS.get(d.get('statut'), RDV_STATUTS['en_attente'])
    if d['est_message'] and d.get('statut') == 'en_attente':
        lab, col, bg = ('✉️ Message envoyé', '#6D28D9', '#EDE9FE') if role == 'parent' else ('✉️ À traiter', '#6D28D9', '#EDE9FE')
    d['statut_label'], d['statut_color'], d['statut_bg'] = lab, col, bg
    return d


# ── API agenda (parent + admin) ──────────────────────────────────────────────
@app.route('/rendez-vous/agenda')
@login_required
def rdv_agenda():
    """Jours ouvrés des prochaines semaines avec, pour chacun, les créneaux libres/occupés du motif."""
    if session.get('role') not in ('parent', 'admin', 'agent_admin'):
        return jsonify({'ok': False, 'erreur': 'Accès non autorisé.'}), 403
    motif = request.args.get('motif', '')
    if motif not in RDV_MOTIFS:
        return jsonify({'ok': False, 'erreur': 'Motif invalide.'}), 400
    exclure = request.args.get('exclure', type=int) if session.get('role') != 'parent' else None
    conn = get_db()
    try:
        _rdv_assurer_table(conn)
        now = datetime.datetime.now()
        today = now.date()
        fin = today + datetime.timedelta(days=RDV_HORIZON_JOURS)
        prises = {}
        for r in conn.execute("""SELECT id, date_rdv, heure_rdv FROM rendez_vous
                                 WHERE statut IN ('en_attente','confirme') AND date_rdv BETWEEN ? AND ?""",
                              (today.isoformat(), fin.isoformat())).fetchall():
            if exclure and r['id'] == exclure:
                continue
            prises.setdefault(r['date_rdv'], set()).add(r['heure_rdv'])
        heures = _rdv_heures_motif(motif)
        jours = []
        d = today
        while d <= fin:
            if d.weekday() in RDV_JOURS_OUVRES:
                iso = d.isoformat()
                creneaux = []
                for h in heures:
                    ok, _ = _rdv_creneau_valide(motif, iso, h, now)
                    creneaux.append({'h': h, 'libre': bool(ok and h not in prises.get(iso, set()))})
                jours.append({'date': iso, 'jour': _RDV_JOURS[d.weekday()], 'num': d.day,
                              'mois': _RDV_MOIS[d.month - 1],
                              'libres': sum(1 for c in creneaux if c['libre']), 'creneaux': creneaux})
            d += datetime.timedelta(days=1)
        return jsonify({'ok': True, 'motif': motif, 'horaires': _rdv_fenetres_txt(motif),
                        'duree': RDV_DUREE_MIN, 'jours': jours})
    finally:
        conn.close()


@app.route('/rendez-vous', methods=['GET', 'POST'])
@login_required
def rendez_vous():
    role = session.get('role')
    if role == 'parent':
        return _rdv_vue_parent()
    if role in ('admin', 'agent_admin'):
        return _rdv_vue_admin()
    flash('Accès non autorisé.', 'error')
    return redirect(url_for('dashboard'))


# ── Vue PARENT ───────────────────────────────────────────────────────────────
def _rdv_vue_parent():
    uid = session['user_id']
    nom_parent = session.get('nom_complet', 'Un parent')
    conn = get_db()
    try:
        _rdv_assurer_table(conn)
        enfants = [dict(e) for e in conn.execute(
            "SELECT id, prenom, nom FROM eleves WHERE parent_id=? ORDER BY prenom", (uid,)).fetchall()]
        ids_enfants = {e['id'] for e in enfants}

        def _eleve_valide(valeur):
            try:
                v = int(valeur)
            except (TypeError, ValueError):
                return None
            return v if v in ids_enfants else None

        if request.method == 'POST':
            action = request.form.get('action', '')
            eleve_id = _eleve_valide(request.form.get('eleve_id'))
            enfant_txt = ''
            if eleve_id:
                e = next(x for x in enfants if x['id'] == eleve_id)
                enfant_txt = f" — enfant : {e['prenom']} {e['nom']}"

            if action == 'reserver':
                motif = request.form.get('motif', '')
                date_iso = (request.form.get('date') or '').strip()
                heure = (request.form.get('heure') or '').strip()
                mode = request.form.get('mode', 'presentiel')
                mode = mode if mode in RDV_MODES else 'presentiel'
                priorite = 'urgente' if request.form.get('priorite') == 'urgente' else 'normale'
                note = (request.form.get('note') or '').strip()[:1000]
                ok, err = _rdv_creneau_valide(motif, date_iso, heure)
                if not ok:
                    flash(err, 'error')
                    return redirect(url_for('rendez_vous'))
                actifs = conn.execute(
                    """SELECT COUNT(*) FROM rendez_vous WHERE parent_id=? AND type_demande='creneau'
                       AND statut IN ('en_attente','confirme') AND date_rdv>=?""",
                    (uid, datetime.date.today().isoformat())).fetchone()[0]
                if actifs >= RDV_MAX_ACTIFS:
                    flash(f"Vous avez déjà {RDV_MAX_ACTIFS} rendez-vous à venir. Annulez-en un ou attendez qu'il ait eu lieu.", 'error')
                    return redirect(url_for('rendez_vous'))
                try:
                    conn.execute(
                        """INSERT INTO rendez_vous (parent_id, eleve_id, motif, mode, priorite, note, date_rdv,
                                                    heure_rdv, duree_min, type_demande, statut)
                           VALUES (?,?,?,?,?,?,?,?,?,'creneau','en_attente')""",
                        (uid, eleve_id, motif, mode, priorite, note, date_iso, heure, RDV_DUREE_MIN))
                except sqlite3.IntegrityError:
                    conn.rollback()
                    flash("Ce créneau vient d'être réservé par un autre parent. Choisissez-en un autre.", 'error')
                    return redirect(url_for('rendez_vous'))
                label = RDV_MOTIFS[motif]['label']
                _rdv_notifier_admins(
                    conn,
                    f"📅 {nom_parent} demande un rendez-vous « {label} » le {_rdv_fmt_date(date_iso)} à "
                    f"{_rdv_fmt_heure(heure)}{enfant_txt}{' (URGENT)' if priorite == 'urgente' else ''}",
                    'Nouvelle demande de rendez-vous', prio='haute' if priorite == 'urgente' else 'normale')
                conn.commit()
                flash("Demande envoyée ✅ — l'administration va la confirmer. Vous serez notifié(e) de la réponse.", 'success')
                return redirect(url_for('rendez_vous'))

            if action == 'annuler':
                rdv_id = request.form.get('rdv_id', type=int)
                r = conn.execute("SELECT * FROM rendez_vous WHERE id=? AND parent_id=?", (rdv_id, uid)).fetchone()
                if not r or r['statut'] not in ('en_attente', 'confirme'):
                    flash("Rendez-vous introuvable ou déjà clôturé.", 'error')
                    return redirect(url_for('rendez_vous'))
                conn.execute("UPDATE rendez_vous SET statut='annule', date_traitement=CURRENT_TIMESTAMP WHERE id=?", (rdv_id,))
                if r['type_demande'] == 'creneau':
                    _rdv_notifier_admins(
                        conn, f"🚫 {nom_parent} a annulé son rendez-vous « {RDV_MOTIFS.get(r['motif'], RDV_MOTIFS['autre'])['label']} » "
                              f"du {_rdv_fmt_date(r['date_rdv'])} à {_rdv_fmt_heure(r['heure_rdv'])}",
                        'Rendez-vous annulé')
                conn.commit()
                flash("Rendez-vous annulé.", 'success')
                return redirect(url_for('rendez_vous'))

            if action == 'message':
                contenu = (request.form.get('contenu') or '').strip()[:2000]
                motif = request.form.get('motif', '')
                motif = motif if motif in RDV_MOTIFS else 'autre'
                dispo = (request.form.get('dispo') or '').strip()[:200]
                if not contenu:
                    flash("Écrivez votre message à l'agent admin.", 'error')
                    return redirect(url_for('rendez_vous'))
                destinataires = [r['id'] for r in conn.execute("SELECT id FROM users WHERE role='agent_admin'").fetchall()]
                if not destinataires:  # aucun agent admin créé : on écrit à l'admin plutôt que de perdre le message
                    destinataires = [r['id'] for r in conn.execute("SELECT id FROM users WHERE role='admin'").fetchall()]
                if not destinataires:
                    flash("Aucun agent admin n'est disponible pour le moment.", 'error')
                    return redirect(url_for('rendez_vous'))
                texte = "📅 Demande de rendez-vous — les créneaux proposés ne me conviennent pas\n"
                texte += f"Motif : {RDV_MOTIFS[motif]['label']}\n"
                if dispo:
                    texte += f"Mes disponibilités : {dispo}\n"
                texte += "\n" + contenu
                for did in destinataires:
                    conv_id = _msg_get_or_create_conversation(conn, uid, did, eleve_id)
                    cur = conn.execute(
                        "INSERT INTO msg_messages (conversation_id, expediteur_id, contenu, priorite) VALUES (?,?,?,?)",
                        (conv_id, uid, texte, 'normal'))
                    _msg_marque_camera(conn, conv_id, uid, cur.lastrowid)
                conn.execute(
                    """INSERT INTO rendez_vous (parent_id, eleve_id, motif, note, type_demande, statut)
                       VALUES (?,?,?,?,'message','en_attente')""",
                    (uid, eleve_id, motif, (f"[{dispo}] " if dispo else '') + contenu))
                extrait = contenu if len(contenu) <= 90 else contenu[:87] + '…'
                _rdv_notifier_admins(
                    conn, f"✉️ {nom_parent} n'a pas trouvé de créneau convenable ({RDV_MOTIFS[motif]['label']}){enfant_txt} : « {extrait} »",
                    'Rendez-vous : message d\'un parent')
                conn.commit()
                flash("Message envoyé à l'agent admin ✅ — il vous répondra par la messagerie.", 'success')
                return redirect(url_for('rendez_vous'))

            return redirect(url_for('rendez_vous'))

        today = datetime.date.today().isoformat()
        lignes = [_rdv_enrichir(r, 'parent') for r in conn.execute(
            """SELECT r.*, e.prenom AS e_prenom, e.nom AS e_nom FROM rendez_vous r
               LEFT JOIN eleves e ON e.id = r.eleve_id WHERE r.parent_id=? ORDER BY r.id DESC LIMIT 60""", (uid,)).fetchall()]
        for d in lignes:
            d['enfant'] = f"{d.get('e_prenom') or ''} {d.get('e_nom') or ''}".strip()
            d['peut_annuler'] = d['statut'] in ('en_attente', 'confirme') and (d['est_message'] or (d['date_rdv'] or '') >= today)
        a_venir = [d for d in lignes if d['statut'] in ('en_attente', 'confirme') and (d['est_message'] or (d['date_rdv'] or '') >= today)]
        a_venir.sort(key=lambda d: (d['est_message'], d['date_rdv'] or '', d['heure_rdv'] or ''))
        ids_a_venir = {d['id'] for d in a_venir}
        historique = [d for d in lignes if d['id'] not in ids_a_venir]
        motifs_js = {k: {'label': v['label'], 'ico': v['ico'], 'horaires': _rdv_fenetres_txt(k)} for k, v in RDV_MOTIFS.items()}
        return render_template_string(
            RDV_PARENT_HTML, notif_count=get_notif_count(), motifs=RDV_MOTIFS, motifs_js=motifs_js, modes=RDV_MODES,
            enfants=enfants, a_venir=a_venir, historique=historique, duree=RDV_DUREE_MIN,
            horaires_paiement=_rdv_fenetres_txt('paiement'), max_actifs=RDV_MAX_ACTIFS)
    finally:
        conn.close()


# ── Vue ADMIN / AGENT ADMIN ──────────────────────────────────────────────────
def _rdv_vue_admin():
    uid = session['user_id']
    conn = get_db()
    try:
        _rdv_assurer_table(conn)
        if request.method == 'POST':
            action = request.form.get('action', '')
            rdv_id = request.form.get('rdv_id', type=int)
            r = conn.execute("SELECT * FROM rendez_vous WHERE id=?", (rdv_id,)).fetchone()
            if not r:
                flash("Demande introuvable.", 'error')
                return redirect(url_for('rendez_vous'))
            reponse = (request.form.get('reponse') or '').strip()[:500]
            label = RDV_MOTIFS.get(r['motif'], RDV_MOTIFS['autre'])['label']
            quand = f"{_rdv_fmt_date(r['date_rdv'])} à {_rdv_fmt_heure(r['heure_rdv'])}" if r['date_rdv'] else ''
            suffixe = f" Message de l'administration : {reponse}" if reponse else ''

            if action == 'confirmer':
                if r['statut'] != 'en_attente' or r['type_demande'] != 'creneau':
                    flash("Cette demande ne peut plus être confirmée.", 'error')
                    return redirect(url_for('rendez_vous'))
                conn.execute("""UPDATE rendez_vous SET statut='confirme', reponse_admin=?, traite_par=?,
                                date_traitement=CURRENT_TIMESTAMP WHERE id=?""", (reponse, uid, rdv_id))
                _rdv_notifier_parent(conn, r['parent_id'], f"✅ Votre rendez-vous « {label} » du {quand} est confirmé.{suffixe}",
                                     'Rendez-vous confirmé', '#059669')
                flash("Rendez-vous confirmé — le parent a été notifié.", 'success')

            elif action == 'refuser':
                if r['statut'] not in ('en_attente', 'confirme'):
                    flash("Cette demande est déjà clôturée.", 'error')
                    return redirect(url_for('rendez_vous'))
                conn.execute("""UPDATE rendez_vous SET statut='refuse', reponse_admin=?, traite_par=?,
                                date_traitement=CURRENT_TIMESTAMP WHERE id=?""", (reponse, uid, rdv_id))
                if r['type_demande'] == 'creneau':
                    _rdv_notifier_parent(conn, r['parent_id'],
                                         f"❌ Votre rendez-vous « {label} » du {quand} n'a pas pu être retenu.{suffixe} "
                                         f"Vous pouvez choisir un autre créneau ou nous écrire.",
                                         'Rendez-vous refusé', '#DC2626')
                flash("Demande refusée — le parent a été notifié.", 'success')

            elif action == 'reprogrammer':
                date_iso = (request.form.get('date') or '').strip()
                heure = (request.form.get('heure') or '').strip()
                if r['statut'] not in ('en_attente', 'confirme'):
                    flash("Cette demande est déjà clôturée.", 'error')
                    return redirect(url_for('rendez_vous'))
                ok, err = _rdv_creneau_valide(r['motif'], date_iso, heure)
                if not ok:
                    flash(err, 'error')
                    return redirect(url_for('rendez_vous'))
                try:
                    conn.execute("""UPDATE rendez_vous SET date_rdv=?, heure_rdv=?, duree_min=?, statut='confirme',
                                    reponse_admin=?, traite_par=?, date_traitement=CURRENT_TIMESTAMP WHERE id=?""",
                                 (date_iso, heure, RDV_DUREE_MIN, reponse, uid, rdv_id))
                except sqlite3.IntegrityError:
                    conn.rollback()
                    flash("Ce créneau est déjà pris. Choisissez-en un autre.", 'error')
                    return redirect(url_for('rendez_vous'))
                nouveau = f"{_rdv_fmt_date(date_iso)} à {_rdv_fmt_heure(heure)}"
                _rdv_notifier_parent(conn, r['parent_id'],
                                     f"📅 Rendez-vous « {label} » fixé au {nouveau}.{suffixe}",
                                     'Rendez-vous programmé', '#2563EB')
                flash("Rendez-vous programmé — le parent a été notifié.", 'success')

            elif action == 'terminer':
                conn.execute("""UPDATE rendez_vous SET statut='termine', traite_par=?, date_traitement=CURRENT_TIMESTAMP
                                WHERE id=? AND statut IN ('en_attente','confirme')""", (uid, rdv_id))
                flash("Marqué comme terminé.", 'success')
            conn.commit()
            return redirect(url_for('rendez_vous'))

        today = datetime.date.today().isoformat()
        lignes = []
        for r in conn.execute(
                """SELECT r.*, u.prenom AS p_prenom, u.nom AS p_nom, u.telephone AS p_tel,
                          e.prenom AS e_prenom, e.nom AS e_nom, c.nom AS classe_nom
                   FROM rendez_vous r JOIN users u ON u.id = r.parent_id
                   LEFT JOIN eleves e ON e.id = r.eleve_id LEFT JOIN classes c ON c.id = e.classe_id
                   ORDER BY r.id DESC LIMIT 300""").fetchall():
            d = _rdv_enrichir(r, 'admin')
            d['parent_nom'] = f"{d['p_prenom']} {d['p_nom']}".strip()
            d['enfant'] = (f"{d.get('e_prenom') or ''} {d.get('e_nom') or ''}".strip()
                           + (f" ({d['classe_nom']})" if d.get('classe_nom') else '')) if d.get('e_prenom') else ''
            if d['statut'] == 'en_attente':
                d['groupe'] = 'messages' if d['est_message'] else 'attente'
            elif d['statut'] == 'confirme':
                d['groupe'] = 'confirme'
            else:
                d['groupe'] = 'historique'
            d['conv_url'] = ''
            if d['est_message']:
                conv = conn.execute(
                    """SELECT id FROM msg_conversations WHERE (user_a_id=? AND user_b_id=?) OR (user_a_id=? AND user_b_id=?)
                       ORDER BY id DESC LIMIT 1""", (uid, d['parent_id'], d['parent_id'], uid)).fetchone()
                d['conv_url'] = f"/messages?conv={conv['id']}" if conv else f"/messages?vers={d['parent_id']}"
            lignes.append(d)

        ordre = {'attente': 0, 'messages': 1, 'confirme': 2, 'historique': 3}
        # Tri stable : la requête renvoie déjà les plus récents d'abord (historique) ; les demandes à traiter
        # et les confirmés sont triés par date/heure croissantes.
        lignes.sort(key=lambda d: (ordre[d['groupe']],
                                   '' if d['groupe'] == 'historique' else (d['date_rdv'] or '9999-12-31'),
                                   '' if d['groupe'] == 'historique' else (d['heure_rdv'] or '')))
        kpi = {
            'attente': sum(1 for d in lignes if d['groupe'] == 'attente'),
            'messages': sum(1 for d in lignes if d['groupe'] == 'messages'),
            'aujourdhui': sum(1 for d in lignes if d['groupe'] == 'confirme' and d['date_rdv'] == today),
            'confirmes': sum(1 for d in lignes if d['groupe'] == 'confirme' and (d['date_rdv'] or '') >= today),
        }
        motifs_js = {k: {'label': v['label'], 'horaires': _rdv_fenetres_txt(k)} for k, v in RDV_MOTIFS.items()}
        return render_template_string(RDV_ADMIN_HTML, notif_count=get_notif_count(), rdvs=lignes, kpi=kpi,
                                      today=today, motifs_js=motifs_js,
                                      horaires_paiement=_rdv_fenetres_txt('paiement'))
    finally:
        conn.close()


# ── Gabarit PARENT : prise de rendez-vous ────────────────────────────────────
RDV_PARENT_HTML = """<!DOCTYPE html><html>
<head><title>Rendez-vous — {{ ECOLE_NOM }}</title>""" + BASE_CSS + MACOS_CSS + """
<style>
.rdv-hero{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;padding:24px 28px;border-radius:24px;color:#fff;
  background:linear-gradient(135deg,#1D4ED8 0%,#7C3AED 55%,#DB2777 100%);box-shadow:0 16px 34px -16px rgba(76,29,149,.6);margin-bottom:16px;}
.rdv-hero h2{margin:0;font-size:1.5rem;font-weight:800;letter-spacing:-.02em;color:#fff;}
.rdv-hero p{margin:6px 0 0;font-size:.88rem;opacity:.92;color:#fff;}
.rdv-hero-ico{font-size:2.8rem;line-height:1;}
.rdv-notice{display:flex;gap:12px;align-items:flex-start;padding:14px 18px;border-radius:16px;margin-bottom:16px;
  background:linear-gradient(135deg,#FFFBEB,#FEF3C7);border:1px solid #FCD34D;color:#78350F;font-size:.88rem;line-height:1.5;}
.rdv-notice .ni{font-size:1.5rem;line-height:1;}
.rdv-notice b{color:#92400E;}
.rdv-grid{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:18px;align-items:start;}
.rdv-card{background:var(--card-bg,#fff);border:1px solid var(--gray-200,#e2e8f0);border-radius:20px;padding:18px 20px;margin-bottom:16px;box-shadow:var(--shadow);}
.rdv-step{display:flex;align-items:center;gap:10px;font-weight:800;font-size:1rem;margin-bottom:12px;}
.rdv-step b{width:26px;height:26px;border-radius:50%;background:linear-gradient(135deg,#2563EB,#7C3AED);color:#fff;display:inline-flex;align-items:center;justify-content:center;font-size:.8rem;flex-shrink:0;}
.rdv-motifs{display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:10px;}
.rdv-motif{position:relative;display:flex;flex-direction:column;gap:4px;padding:14px;border-radius:16px;cursor:pointer;border:2px solid var(--gray-200,#e2e8f0);
  background:var(--card-bg,#fff);transition:transform .15s,box-shadow .15s,border-color .15s;}
.rdv-motif:hover{transform:translateY(-2px);box-shadow:0 10px 22px -12px rgba(0,0,0,.25);}
.rdv-motif input{position:absolute;opacity:0;pointer-events:none;}
.rdv-motif.is-on{border-color:var(--mc,#2563EB);box-shadow:0 0 0 3px color-mix(in srgb,var(--mc,#2563EB) 18%,transparent);}
.rdv-motif-ico{font-size:1.6rem;line-height:1;}
.rdv-motif-name{font-weight:800;font-size:.95rem;}
.rdv-motif-desc{font-size:.74rem;opacity:.7;line-height:1.35;}
.rdv-motif-hours{font-size:.7rem;font-weight:700;color:var(--mc,#2563EB);margin-top:2px;}
.rdv-row{display:grid;grid-template-columns:1fr 1fr;gap:14px;}
.rdv-lbl{display:block;font-size:.74rem;font-weight:800;letter-spacing:.04em;text-transform:uppercase;opacity:.65;margin-bottom:6px;}
.rdv-select,.rdv-input,.rdv-area{width:100%;box-sizing:border-box;padding:11px 13px;border-radius:12px;border:1px solid var(--gray-200,#e2e8f0);background:var(--card-bg,#fff);color:inherit;font:inherit;}
.rdv-area{min-height:84px;resize:vertical;}
.rdv-pills{display:flex;gap:8px;flex-wrap:wrap;}
.rdv-pill{display:inline-flex;align-items:center;gap:6px;padding:9px 14px;border-radius:999px;border:1px solid var(--gray-200,#e2e8f0);cursor:pointer;font-weight:700;font-size:.84rem;background:var(--card-bg,#fff);}
.rdv-pill input{position:absolute;opacity:0;pointer-events:none;}
.rdv-pill.is-on{background:linear-gradient(135deg,#2563EB,#7C3AED);color:#fff;border-color:transparent;}
.rdv-hours-info{font-size:.8rem;font-weight:700;color:#7C3AED;background:rgba(124,58,237,.1);border-radius:12px;padding:9px 12px;margin-bottom:12px;}
.rdv-days{display:flex;gap:8px;overflow-x:auto;padding:4px 2px 10px;scroll-snap-type:x proximity;}
.rdv-day{flex:0 0 auto;scroll-snap-align:start;display:flex;flex-direction:column;align-items:center;gap:1px;min-width:66px;padding:10px 8px;border-radius:16px;cursor:pointer;
  border:2px solid var(--gray-200,#e2e8f0);background:var(--card-bg,#fff);color:inherit;font:inherit;transition:transform .12s,border-color .12s;}
.rdv-day:hover:not(:disabled){transform:translateY(-2px);}
.rdv-day-j{font-size:.68rem;font-weight:800;text-transform:uppercase;opacity:.65;}
.rdv-day-n{font-size:1.3rem;font-weight:800;line-height:1.1;}
.rdv-day-m{font-size:.68rem;opacity:.65;}
.rdv-day-c{font-size:.64rem;font-weight:800;margin-top:3px;padding:2px 7px;border-radius:99px;background:#D1FAE5;color:#047857;}
.rdv-day.is-full{opacity:.45;cursor:not-allowed;}
.rdv-day.is-full .rdv-day-c{background:#E2E8F0;color:#475569;}
.rdv-day.is-on{border-color:#7C3AED;background:linear-gradient(160deg,rgba(37,99,235,.14),rgba(124,58,237,.14));}
.rdv-slot-title{font-size:.78rem;font-weight:800;opacity:.7;margin:10px 0 6px;}
.rdv-slot-wrap{display:flex;flex-wrap:wrap;gap:8px;}
.rdv-slot{padding:9px 15px;border-radius:12px;border:1px solid #6EE7B7;background:#ECFDF5;color:#047857;font-weight:800;font-size:.86rem;cursor:pointer;font-family:inherit;}
.rdv-slot:hover:not(:disabled){background:#D1FAE5;}
.rdv-slot.is-on{background:linear-gradient(135deg,#2563EB,#7C3AED);color:#fff;border-color:transparent;}
.rdv-slot.is-taken{background:#F1F5F9;border-color:#E2E8F0;color:#94A3B8;text-decoration:line-through;cursor:not-allowed;}
.rdv-empty{font-size:.84rem;opacity:.7;padding:10px 4px;}
.rdv-side{position:sticky;top:12px;}
.rdv-rc-row{display:flex;justify-content:space-between;gap:10px;padding:8px 0;border-bottom:1px dashed var(--gray-200,#e2e8f0);font-size:.86rem;}
.rdv-rc-row span{opacity:.65;}
.rdv-rc-row b{text-align:right;}
.rdv-btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;width:100%;margin-top:14px;padding:13px 16px;border:none;border-radius:14px;cursor:pointer;
  font-weight:800;font-size:.92rem;font-family:inherit;color:#fff;background:linear-gradient(135deg,#2563EB,#7C3AED 60%,#DB2777);box-shadow:0 10px 22px -10px rgba(76,29,149,.7);}
.rdv-btn:disabled{opacity:.45;cursor:not-allowed;box-shadow:none;}
.rdv-btn.alt{background:#0F172A;}
.rdv-mine{border:1px solid var(--gray-200,#e2e8f0);border-left:5px solid var(--mc,#7C3AED);border-radius:14px;padding:12px 14px;margin-bottom:10px;background:var(--card-bg,#fff);}
.rdv-mine-top{display:flex;justify-content:space-between;align-items:center;gap:8px;}
.rdv-mine-top b{font-size:.92rem;}
.rdv-badge{font-size:.68rem;font-weight:800;padding:3px 9px;border-radius:99px;white-space:nowrap;}
.rdv-mine-meta{font-size:.78rem;opacity:.8;margin-top:6px;line-height:1.5;}
.rdv-mine-resp{font-size:.78rem;margin-top:6px;padding:7px 10px;border-radius:10px;background:rgba(37,99,235,.08);}
.rdv-cancel{margin-top:8px;background:none;border:1px solid #FCA5A5;color:#B91C1C;border-radius:10px;padding:5px 12px;font-size:.76rem;font-weight:700;cursor:pointer;font-family:inherit;}
.rdv-msg summary{cursor:pointer;font-weight:800;font-size:.98rem;list-style:none;display:flex;align-items:center;gap:10px;}
.rdv-msg summary::-webkit-details-marker{display:none;}
.rdv-msg[open] summary{margin-bottom:12px;}
@media(max-width:960px){
  .rdv-grid{grid-template-columns:minmax(0,1fr);}
  .rdv-main,.rdv-side,.rdv-card,.rdv-grid form{min-width:0;max-width:100%;}
  .rdv-side{position:static;}
  .rdv-row{grid-template-columns:minmax(0,1fr);}
  .rdv-hero{padding:18px;border-radius:20px;}
  .rdv-hero h2{font-size:1.2rem;}
  .rdv-hours-info,.rdv-notice,.rdv-mine-meta{overflow-wrap:anywhere;}
  /* Motifs : slider horizontal (glisser vers la gauche/droite) */
  .rdv-motifs{display:flex;gap:10px;overflow-x:auto;overflow-y:hidden;scroll-snap-type:x mandatory;-webkit-overflow-scrolling:touch;
    padding:4px 2px 12px;margin:0 -2px;scrollbar-width:thin;overscroll-behavior-x:contain;}
  .rdv-motif{flex:0 0 72%;max-width:250px;scroll-snap-align:start;}
  .rdv-swipe-hint{display:inline-block !important;}
}
.rdv-swipe-hint{display:none;margin-left:auto;font-size:.68rem;font-weight:700;opacity:.55;white-space:nowrap;}
</style>
</head><body class="page-rdv"><div class="layout">
{{ nav_html|safe }}
<script>document.getElementById('page-title').textContent='Rendez-vous';</script>
{% for cat,msg in get_flashed_messages(with_categories=true) %}<div class="alert {{'alert-success' if cat=='success' else 'alert-error'}}">{{ msg }}</div>{% endfor %}

<div class="rdv-hero">
  <div>
    <h2>Prendre rendez-vous avec l'administration</h2>
    <p>Choisissez un motif, un jour et un créneau de {{ duree }} minutes : l'administration confirme et vous recevez une notification.</p>
  </div>
  <div class="rdv-hero-ico">📅</div>
</div>

<div class="rdv-notice">
  <div class="ni">🕒</div>
  <div><b>Paiement et réclamation :</b> les rendez-vous ont lieu uniquement de <b>{{ horaires_paiement }}</b> (le matin, puis l'après-midi).
  Les autres motifs disposent d'horaires distincts, affichés lorsque vous les sélectionnez.</div>
</div>

<div class="rdv-grid">
  <div class="rdv-main">
    <form method="post" id="rdv-form" autocomplete="off">
      <input type="hidden" name="action" value="reserver">
      <input type="hidden" name="date" id="rdv-date" value="">
      <input type="hidden" name="heure" id="rdv-heure" value="">

      <div class="rdv-card">
        <div class="rdv-step"><b>1</b> Motif du rendez-vous <span class="rdv-swipe-hint">Glissez ⇆</span></div>
        <div class="rdv-motifs">
          {% for k, m in motifs.items() %}
          <label class="rdv-motif" style="--mc:{{ m.couleur }}">
            <input type="radio" name="motif" value="{{ k }}" required>
            <span class="rdv-motif-ico">{{ m.ico }}</span>
            <span class="rdv-motif-name">{{ m.label }}</span>
            <span class="rdv-motif-desc">{{ m.desc }}</span>
            <span class="rdv-motif-hours">🕒 {{ motifs_js[k].horaires }}</span>
          </label>
          {% endfor %}
        </div>
      </div>

      <div class="rdv-card">
        <div class="rdv-step"><b>2</b> Options</div>
        <div class="rdv-row">
          <div>
            <label class="rdv-lbl" for="rdv-enfant">Enfant concerné</label>
            <select name="eleve_id" id="rdv-enfant" class="rdv-select">
              <option value="">Non précisé</option>
              {% for e in enfants %}<option value="{{ e.id }}">{{ e.prenom }} {{ e.nom }}</option>{% endfor %}
            </select>
          </div>
          <div>
            <span class="rdv-lbl">Mode du rendez-vous</span>
            <div class="rdv-pills">
              {% for k, lab in modes.items() %}
              <label class="rdv-pill{% if loop.first %} is-on{% endif %}"><input type="radio" name="mode" value="{{ k }}"{% if loop.first %} checked{% endif %}>{{ lab }}</label>
              {% endfor %}
            </div>
          </div>
        </div>
        <div style="margin-top:14px;">
          <span class="rdv-lbl">Priorité</span>
          <div class="rdv-pills">
            <label class="rdv-pill is-on"><input type="radio" name="priorite" value="normale" checked>Normale</label>
            <label class="rdv-pill"><input type="radio" name="priorite" value="urgente">🔥 Urgente</label>
          </div>
        </div>
      </div>

      <div class="rdv-card">
        <div class="rdv-step"><b>3</b> Agenda — jour et créneau</div>
        <div class="rdv-hours-info" id="rdv-hours-info" style="display:none;"></div>
        <div class="rdv-days" id="rdv-days"><div class="rdv-empty">Choisissez d'abord un motif pour voir les créneaux disponibles.</div></div>
        <div id="rdv-slots"></div>
      </div>

      <div class="rdv-card">
        <div class="rdv-step"><b>4</b> Précisions (facultatif)</div>
        <textarea name="note" class="rdv-area" maxlength="1000" placeholder="Ex. : facture de novembre, point sur les résultats du 1er trimestre…"></textarea>
      </div>
    </form>

    <details class="rdv-card rdv-msg" id="rdv-msg-box">
      <summary><span style="font-size:1.4rem;">✉️</span> Aucun créneau ne vous convient ? Écrivez à l'agent admin</summary>
      <form method="post">
        <input type="hidden" name="action" value="message">
        <div class="rdv-row">
          <div>
            <label class="rdv-lbl" for="msg-motif">Motif</label>
            <select name="motif" id="msg-motif" class="rdv-select">
              {% for k, m in motifs.items() %}<option value="{{ k }}"{% if k == 'autre' %} selected{% endif %}>{{ m.ico }} {{ m.label }}</option>{% endfor %}
            </select>
          </div>
          <div>
            <label class="rdv-lbl" for="msg-enfant">Enfant concerné</label>
            <select name="eleve_id" id="msg-enfant" class="rdv-select">
              <option value="">Non précisé</option>
              {% for e in enfants %}<option value="{{ e.id }}">{{ e.prenom }} {{ e.nom }}</option>{% endfor %}
            </select>
          </div>
        </div>
        <div style="margin-top:12px;">
          <label class="rdv-lbl" for="msg-dispo">Vos disponibilités (facultatif)</label>
          <input type="text" name="dispo" id="msg-dispo" class="rdv-input" maxlength="200" placeholder="Ex. : mardi ou jeudi après 16h">
        </div>
        <div style="margin-top:12px;">
          <label class="rdv-lbl" for="msg-contenu">Votre message</label>
          <textarea name="contenu" id="msg-contenu" class="rdv-area" maxlength="2000" required placeholder="Expliquez pourquoi les créneaux ne vous conviennent pas et ce qui vous arrangerait."></textarea>
        </div>
        <button type="submit" class="rdv-btn alt">✉️ Envoyer le message à l'agent admin</button>
      </form>
    </details>
  </div>

  <aside class="rdv-side">
    <div class="rdv-card">
      <div class="rdv-step" style="margin-bottom:6px;">📋 Récapitulatif</div>
      <div class="rdv-rc-row"><span>Motif</span><b id="rc-motif">—</b></div>
      <div class="rdv-rc-row"><span>Date</span><b id="rc-date">—</b></div>
      <div class="rdv-rc-row"><span>Heure</span><b id="rc-heure">—</b></div>
      <div class="rdv-rc-row"><span>Durée</span><b>{{ duree }} min</b></div>
      <div class="rdv-rc-row"><span>Mode</span><b id="rc-mode">—</b></div>
      <div class="rdv-rc-row"><span>Priorité</span><b id="rc-prio">—</b></div>
      <div class="rdv-rc-row"><span>Enfant</span><b id="rc-enfant">Non précisé</b></div>
      <button type="submit" form="rdv-form" id="rdv-submit" class="rdv-btn" disabled>📅 Envoyer ma demande</button>
      <div style="font-size:.72rem;opacity:.65;margin-top:8px;">Maximum {{ max_actifs }} rendez-vous à venir en même temps.</div>
    </div>

    <div class="rdv-card">
      <div class="rdv-step" style="margin-bottom:10px;">🗓️ Mes rendez-vous</div>
      {% if not a_venir %}<div class="rdv-empty">Aucun rendez-vous à venir.</div>{% endif %}
      {% for r in a_venir %}
      <div class="rdv-mine" style="--mc:{{ r.motif_couleur }}">
        <div class="rdv-mine-top"><b>{{ r.motif_ico }} {{ r.motif_label }}</b>
          <span class="rdv-badge" style="color:{{ r.statut_color }};background:{{ r.statut_bg }}">{{ r.statut_label }}</span></div>
        <div class="rdv-mine-meta">
          {% if r.est_message %}Message envoyé à l'agent admin — vous recevrez une réponse par la messagerie.
          {% else %}📅 {{ r.date_txt }} à {{ r.heure_txt }} · {{ r.mode_label }}{% if r.priorite == 'urgente' %} · 🔥 Urgent{% endif %}{% endif %}
          {% if r.enfant %}<br>👧 {{ r.enfant }}{% endif %}
        </div>
        {% if r.reponse_admin %}<div class="rdv-mine-resp">↪ {{ r.reponse_admin }}</div>{% endif %}
        {% if r.peut_annuler %}
        <form method="post" onsubmit="return confirm('Annuler cette demande de rendez-vous ?');">
          <input type="hidden" name="action" value="annuler"><input type="hidden" name="rdv_id" value="{{ r.id }}">
          <button type="submit" class="rdv-cancel">Annuler</button>
        </form>
        {% endif %}
      </div>
      {% endfor %}
      {% if historique %}
      <details style="margin-top:10px;">
        <summary style="cursor:pointer;font-weight:700;font-size:.84rem;">Historique ({{ historique|length }})</summary>
        <div style="margin-top:10px;">
          {% for r in historique %}
          <div class="rdv-mine" style="--mc:{{ r.motif_couleur }};opacity:.85;">
            <div class="rdv-mine-top"><b>{{ r.motif_ico }} {{ r.motif_label }}</b>
              <span class="rdv-badge" style="color:{{ r.statut_color }};background:{{ r.statut_bg }}">{{ r.statut_label }}</span></div>
            <div class="rdv-mine-meta">{% if r.est_message %}✉️ Message à l'agent admin{% else %}📅 {{ r.date_txt }} à {{ r.heure_txt }}{% endif %}</div>
            {% if r.reponse_admin %}<div class="rdv-mine-resp">↪ {{ r.reponse_admin }}</div>{% endif %}
          </div>
          {% endfor %}
        </div>
      </details>
      {% endif %}
    </div>
  </aside>
</div>

<script>
(function(){
  var MOTIFS = {{ motifs_js|tojson }};
  var st = {motif:'', date:'', heure:'', days:[]};
  var $ = function(id){ return document.getElementById(id); };
  var form = $('rdv-form'), elDays = $('rdv-days'), elSlots = $('rdv-slots'), elInfo = $('rdv-hours-info'), btn = $('rdv-submit');

  function fmtH(h){ return String(h).replace(':', 'h'); }
  function setText(id, t){ var e = $(id); if (e) e.textContent = t; }
  function note(t){ var d = document.createElement('div'); d.className = 'rdv-empty'; d.textContent = t; return d; }

  function recap(){
    var m = st.motif ? MOTIFS[st.motif] : null;
    setText('rc-motif', m ? (m.ico + ' ' + m.label) : '—');
    var d = st.days.filter(function(x){ return x.date === st.date; })[0];
    setText('rc-date', d ? (d.jour + ' ' + d.num + ' ' + d.mois) : '—');
    setText('rc-heure', st.heure ? fmtH(st.heure) : '—');
    var mode = form.querySelector('input[name=mode]:checked');
    setText('rc-mode', mode ? mode.parentNode.textContent.trim() : '—');
    var pr = form.querySelector('input[name=priorite]:checked');
    setText('rc-prio', pr ? pr.parentNode.textContent.trim() : '—');
    var sel = $('rdv-enfant');
    setText('rc-enfant', (sel && sel.value) ? sel.options[sel.selectedIndex].text : 'Non précisé');
    btn.disabled = !(st.motif && st.date && st.heure);
  }

  function pickSlot(h){
    st.heure = h; $('rdv-heure').value = h;
    var bs = elSlots.querySelectorAll('.rdv-slot');
    for (var i = 0; i < bs.length; i++) bs[i].classList.toggle('is-on', bs[i].textContent === fmtH(h));
    recap();
  }

  function renderSlots(day){
    elSlots.innerHTML = '';
    var groupes = [['☀️ Matin', function(h){ return h < '12:00'; }], ['🌤️ Après-midi', function(h){ return h >= '12:00'; }]];
    groupes.forEach(function(g){
      var items = day.creneaux.filter(function(c){ return g[1](c.h); });
      if (!items.length) return;
      var t = document.createElement('div'); t.className = 'rdv-slot-title'; t.textContent = g[0]; elSlots.appendChild(t);
      var w = document.createElement('div'); w.className = 'rdv-slot-wrap';
      items.forEach(function(c){
        var b = document.createElement('button');
        b.type = 'button'; b.className = 'rdv-slot' + (c.libre ? '' : ' is-taken');
        b.textContent = fmtH(c.h); b.disabled = !c.libre;
        if (!c.libre) b.title = 'Indisponible';
        b.addEventListener('click', function(){ pickSlot(c.h); });
        w.appendChild(b);
      });
      elSlots.appendChild(w);
    });
  }

  function pickDay(date){
    st.date = date; st.heure = ''; $('rdv-date').value = date; $('rdv-heure').value = '';
    var bs = elDays.querySelectorAll('.rdv-day');
    for (var i = 0; i < bs.length; i++) bs[i].classList.toggle('is-on', bs[i].dataset.date === date);
    var day = st.days.filter(function(x){ return x.date === date; })[0];
    if (day) renderSlots(day);
    recap();
  }

  function renderDays(){
    elDays.innerHTML = '';
    st.days.forEach(function(d){
      var b = document.createElement('button');
      b.type = 'button'; b.className = 'rdv-day' + (d.libres ? '' : ' is-full'); b.disabled = !d.libres; b.dataset.date = d.date;
      var j = document.createElement('span'); j.className = 'rdv-day-j'; j.textContent = d.jour.slice(0, 3);
      var n = document.createElement('span'); n.className = 'rdv-day-n'; n.textContent = d.num;
      var m = document.createElement('span'); m.className = 'rdv-day-m'; m.textContent = d.mois.slice(0, 4);
      var c = document.createElement('span'); c.className = 'rdv-day-c'; c.textContent = d.libres ? (d.libres + ' libre' + (d.libres > 1 ? 's' : '')) : 'Complet';
      b.appendChild(j); b.appendChild(n); b.appendChild(m); b.appendChild(c);
      b.addEventListener('click', function(){ pickDay(d.date); });
      elDays.appendChild(b);
    });
  }

  function loadAgenda(){
    st.date = ''; st.heure = ''; st.days = [];
    $('rdv-date').value = ''; $('rdv-heure').value = '';
    elSlots.innerHTML = '';
    elDays.innerHTML = '';
    if (!st.motif){ elInfo.style.display = 'none'; elDays.appendChild(note("Choisissez d'abord un motif pour voir les créneaux disponibles.")); recap(); return; }
    var m = MOTIFS[st.motif];
    elInfo.style.display = 'block';
    elInfo.textContent = '🕒 Horaires « ' + m.label + ' » : ' + m.horaires + ' — créneaux de {{ duree }} min';
    elDays.appendChild(note('Chargement des créneaux…'));
    fetch('/rendez-vous/agenda?motif=' + encodeURIComponent(st.motif), {credentials: 'same-origin'})
      .then(function(r){ return r.json(); })
      .then(function(j){
        elDays.innerHTML = '';
        if (!j.ok){ elDays.appendChild(note(j.erreur || 'Impossible de charger les créneaux.')); recap(); return; }
        st.days = j.jours; renderDays();
        var first = j.jours.filter(function(d){ return d.libres > 0; })[0];
        if (first) pickDay(first.date);
        else elSlots.appendChild(note("Aucun créneau libre pour l'instant : écrivez à l'agent admin avec le formulaire ci-dessous."));
        recap();
      })
      .catch(function(){ elDays.innerHTML = ''; elDays.appendChild(note('Impossible de charger les créneaux. Réessayez.')); });
  }

  function syncPills(name){
    var inputs = form.querySelectorAll('input[name=' + name + ']');
    for (var i = 0; i < inputs.length; i++) inputs[i].parentNode.classList.toggle('is-on', inputs[i].checked);
  }

  var motifInputs = form.querySelectorAll('input[name=motif]');
  for (var i = 0; i < motifInputs.length; i++){
    motifInputs[i].addEventListener('change', function(){
      for (var k = 0; k < motifInputs.length; k++) motifInputs[k].parentNode.classList.toggle('is-on', motifInputs[k].checked);
      st.motif = this.value;
      var mm = $('msg-motif'); if (mm) mm.value = st.motif;
      loadAgenda();
    });
  }
  ['mode', 'priorite'].forEach(function(name){
    var inputs = form.querySelectorAll('input[name=' + name + ']');
    for (var i = 0; i < inputs.length; i++) inputs[i].addEventListener('change', function(){ syncPills(name); recap(); });
  });
  $('rdv-enfant').addEventListener('change', function(){
    recap();
    var me = $('msg-enfant'); if (me) me.value = this.value;
  });
  form.addEventListener('submit', function(e){
    if (!(st.motif && st.date && st.heure)){ e.preventDefault(); }
  });
  recap();
})();
</script>
</div></div></div></body></html>
"""


# ── Gabarit ADMIN / AGENT ADMIN : page « Rendez-vous » ───────────────────────
RDV_ADMIN_HTML = """<!DOCTYPE html><html>
<head><title>Rendez-vous — {{ ECOLE_NOM }}</title>""" + BASE_CSS + MACOS_CSS + """
<style>
.rdva-hero{display:flex;align-items:center;justify-content:space-between;gap:14px;flex-wrap:wrap;padding:22px 26px;border-radius:22px;color:#fff;margin-bottom:16px;
  background:linear-gradient(135deg,#1D4ED8 0%,#7C3AED 55%,#DB2777 100%);box-shadow:0 14px 30px -14px rgba(76,29,149,.55);}
.rdva-hero h2{margin:0;font-size:1.45rem;font-weight:800;color:#fff;letter-spacing:-.02em;}
.rdva-hero p{margin:5px 0 0;font-size:.85rem;opacity:.92;color:#fff;}
.rdva-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:16px;}
.rdva-kpi{border-radius:18px;padding:16px;color:#fff;box-shadow:0 12px 24px -14px rgba(0,0,0,.5);}
.rdva-kpi b{display:block;font-size:1.8rem;line-height:1.1;font-weight:800;}
.rdva-kpi span{font-size:.76rem;font-weight:700;opacity:.92;}
.rdva-kpi.k1{background:linear-gradient(135deg,#F59E0B,#EA580C);}
.rdva-kpi.k2{background:linear-gradient(135deg,#7C3AED,#DB2777);}
.rdva-kpi.k3{background:linear-gradient(135deg,#2563EB,#06B6D4);}
.rdva-kpi.k4{background:linear-gradient(135deg,#059669,#84CC16);}
.rdva-tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;}
.rdva-tab{border:1px solid var(--gray-200,#e2e8f0);background:var(--card-bg,#fff);color:inherit;border-radius:999px;padding:8px 16px;font-weight:700;font-size:.84rem;cursor:pointer;font-family:inherit;}
.rdva-tab.is-on{background:linear-gradient(135deg,#2563EB,#7C3AED);color:#fff;border-color:transparent;}
.rdva-card{background:var(--card-bg,#fff);border:1px solid var(--gray-200,#e2e8f0);border-left:5px solid var(--mc,#7C3AED);border-radius:18px;padding:16px 18px;margin-bottom:12px;box-shadow:var(--shadow);}
.rdva-head{display:flex;align-items:center;gap:12px;}
.rdva-ico{width:44px;height:44px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.4rem;background:color-mix(in srgb,var(--mc,#7C3AED) 16%,transparent);flex-shrink:0;}
.rdva-who{flex:1;min-width:0;}
.rdva-who b{display:block;font-size:.98rem;}
.rdva-who span{font-size:.78rem;opacity:.7;}
.rdva-badge{font-size:.72rem;font-weight:800;padding:4px 11px;border-radius:99px;white-space:nowrap;}
.rdva-meta{display:flex;flex-wrap:wrap;gap:8px 14px;align-items:center;margin-top:10px;font-size:.84rem;font-weight:600;}
.rdva-chip{padding:3px 10px;border-radius:99px;font-size:.74rem;font-weight:800;color:#fff;background:var(--mc,#7C3AED);}
.rdva-urgent{color:#B91C1C;background:#FEE2E2;padding:3px 10px;border-radius:99px;font-size:.74rem;font-weight:800;}
.rdva-note{margin-top:10px;padding:10px 12px;border-radius:12px;background:rgba(120,120,128,.09);font-size:.84rem;line-height:1.5;white-space:pre-wrap;}
.rdva-resp{margin-top:8px;font-size:.8rem;padding:8px 11px;border-radius:10px;background:rgba(37,99,235,.08);}
.rdva-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px;align-items:flex-start;}
.rdva-inline{display:flex;gap:8px;flex-wrap:wrap;align-items:center;}
.rdva-inp{padding:8px 11px;border-radius:10px;border:1px solid var(--gray-200,#e2e8f0);background:var(--card-bg,#fff);color:inherit;font:inherit;font-size:.82rem;min-width:180px;}
.rdva-btn{display:inline-flex;align-items:center;gap:6px;padding:8px 14px;border-radius:10px;border:1px solid var(--gray-200,#e2e8f0);background:var(--card-bg,#fff);color:inherit;
  font-weight:700;font-size:.82rem;cursor:pointer;text-decoration:none;font-family:inherit;}
.rdva-btn.ok{background:#059669;color:#fff;border-color:transparent;}
.rdva-btn.no{background:#fff;color:#B91C1C;border-color:#FCA5A5;}
.rdva-btn.pri{background:linear-gradient(135deg,#2563EB,#7C3AED);color:#fff;border-color:transparent;}
.rdva-det{border:1px dashed var(--gray-200,#cbd5e1);border-radius:12px;padding:8px 12px;}
.rdva-det summary{cursor:pointer;font-weight:700;font-size:.82rem;}
.rdva-det form{margin-top:10px;display:flex;gap:8px;flex-wrap:wrap;align-items:center;}
.rdva-empty{text-align:center;padding:40px 10px;opacity:.65;}
@media(max-width:900px){.rdva-kpis{grid-template-columns:repeat(2,minmax(0,1fr));}.rdva-hero{padding:18px;}}
</style>
</head><body class="page-rdv-admin"><div class="layout">
{{ nav_html|safe }}
<script>document.getElementById('page-title').textContent='Rendez-vous';</script>
{% for cat,msg in get_flashed_messages(with_categories=true) %}<div class="alert {{'alert-success' if cat=='success' else 'alert-error'}}">{{ msg }}</div>{% endfor %}

<div class="rdva-hero">
  <div>
    <h2>📅 Rendez-vous des parents</h2>
    <p>Paiement et réclamation : {{ horaires_paiement }}. Un rendez-vous par créneau ; les parents sont notifiés de chaque décision.</p>
  </div>
</div>

<div class="rdva-kpis">
  <div class="rdva-kpi k1"><b>{{ kpi.attente }}</b><span>⏳ Demandes à confirmer</span></div>
  <div class="rdva-kpi k2"><b>{{ kpi.messages }}</b><span>✉️ Messages (hors créneaux)</span></div>
  <div class="rdva-kpi k3"><b>{{ kpi.aujourdhui }}</b><span>📍 Aujourd'hui</span></div>
  <div class="rdva-kpi k4"><b>{{ kpi.confirmes }}</b><span>✅ Confirmés à venir</span></div>
</div>

<div class="rdva-tabs">
  <button type="button" class="rdva-tab is-on" data-f="all">Toutes</button>
  <button type="button" class="rdva-tab" data-f="todo">À traiter ({{ kpi.attente + kpi.messages }})</button>
  <button type="button" class="rdva-tab" data-f="confirme">Confirmés</button>
  <button type="button" class="rdva-tab" data-f="historique">Historique</button>
</div>

{% if not rdvs %}<div class="rdva-empty">Aucune demande de rendez-vous pour le moment.</div>{% endif %}
{% for r in rdvs %}
<div class="rdva-card" data-g="{{ r.groupe }}" style="--mc:{{ r.motif_couleur }}">
  <div class="rdva-head">
    <div class="rdva-ico">{{ r.motif_ico }}</div>
    <div class="rdva-who"><b>{{ r.parent_nom }}</b><span>{% if r.p_tel %}📞 {{ r.p_tel }}{% endif %}{% if r.enfant %}{% if r.p_tel %} · {% endif %}👧 {{ r.enfant }}{% endif %}</span></div>
    <span class="rdva-badge" style="color:{{ r.statut_color }};background:{{ r.statut_bg }}">{{ r.statut_label }}</span>
  </div>
  <div class="rdva-meta">
    <span class="rdva-chip">{{ r.motif_label }}</span>
    {% if r.est_message %}
      <span>✉️ Les créneaux proposés ne conviennent pas au parent</span>
    {% else %}
      <span>📅 {{ r.date_txt }} · 🕒 {{ r.heure_txt }}</span>
      <span>{{ r.mode_label }}</span>
      {% if r.priorite == 'urgente' %}<span class="rdva-urgent">🔥 Urgent</span>{% endif %}
    {% endif %}
  </div>
  {% if r.note %}<div class="rdva-note">{{ r.note }}</div>{% endif %}
  {% if r.reponse_admin %}<div class="rdva-resp">↪ Réponse envoyée : {{ r.reponse_admin }}</div>{% endif %}

  {% if r.statut in ('en_attente', 'confirme') %}
  <div class="rdva-actions">
    {% if r.statut == 'en_attente' and not r.est_message %}
    <form method="post" class="rdva-inline">
      <input type="hidden" name="action" value="confirmer"><input type="hidden" name="rdv_id" value="{{ r.id }}">
      <input type="text" name="reponse" class="rdva-inp" maxlength="500" placeholder="Message au parent (facultatif)">
      <button type="submit" class="rdva-btn ok">✅ Confirmer</button>
    </form>
    {% endif %}
    {% if r.est_message %}<a href="{{ r.conv_url }}" class="rdva-btn pri">💬 Répondre par message</a>{% endif %}
    {% if r.statut == 'confirme' or r.est_message %}
    <form method="post" class="rdva-inline">
      <input type="hidden" name="action" value="terminer"><input type="hidden" name="rdv_id" value="{{ r.id }}">
      <button type="submit" class="rdva-btn">🏁 Marquer comme {{ 'traité' if r.est_message else 'terminé' }}</button>
    </form>
    {% endif %}
    <details class="rdva-det">
      <summary>🔄 {{ 'Programmer un rendez-vous' if r.est_message else 'Proposer un autre horaire' }}</summary>
      <form method="post">
        <input type="hidden" name="action" value="reprogrammer"><input type="hidden" name="rdv_id" value="{{ r.id }}">
        <input type="date" name="date" class="rdva-inp rdva-date" min="{{ today }}" data-rdv="{{ r.id }}" data-motif="{{ r.motif }}" required style="min-width:150px;">
        <select name="heure" class="rdva-inp" required style="min-width:150px;"><option value="">Choisir l'heure</option></select>
        <input type="text" name="reponse" class="rdva-inp" maxlength="500" placeholder="Message au parent (facultatif)">
        <button type="submit" class="rdva-btn pri">Programmer</button>
      </form>
    </details>
    <details class="rdva-det">
      <summary>❌ {{ 'Clôturer sans suite' if r.est_message else 'Refuser / annuler' }}</summary>
      <form method="post" onsubmit="return confirm('Confirmer ?');">
        <input type="hidden" name="action" value="refuser"><input type="hidden" name="rdv_id" value="{{ r.id }}">
        <input type="text" name="reponse" class="rdva-inp" maxlength="500" placeholder="Motif (visible par le parent)">
        <button type="submit" class="rdva-btn no">Valider</button>
      </form>
    </details>
  </div>
  {% endif %}
</div>
{% endfor %}

<script>
(function(){
  var cache = {};
  function charger(motif, exclure, cb){
    var k = motif + '|' + exclure;
    if (cache[k]) return cb(cache[k]);
    fetch('/rendez-vous/agenda?motif=' + encodeURIComponent(motif) + '&exclure=' + encodeURIComponent(exclure), {credentials: 'same-origin'})
      .then(function(r){ return r.json(); })
      .then(function(j){ cache[k] = j; cb(j); })
      .catch(function(){ cb({ok: false, jours: []}); });
  }
  var dates = document.querySelectorAll('.rdva-date');
  for (var i = 0; i < dates.length; i++){
    dates[i].addEventListener('change', function(){
      var inp = this, sel = inp.parentNode.querySelector('select[name=heure]');
      sel.innerHTML = '';
      var o = document.createElement('option'); o.value = ''; o.textContent = 'Chargement…'; sel.appendChild(o);
      charger(inp.dataset.motif, inp.dataset.rdv, function(j){
        var day = (j.jours || []).filter(function(d){ return d.date === inp.value; })[0];
        if (!day){ o.textContent = 'Jour indisponible (lundi–vendredi, 3 semaines max)'; return; }
        o.textContent = "Choisir l'heure";
        day.creneaux.forEach(function(c){
          if (!c.libre) return;
          var op = document.createElement('option'); op.value = c.h; op.textContent = c.h.replace(':', 'h'); sel.appendChild(op);
        });
        if (sel.options.length === 1) o.textContent = 'Aucun créneau libre ce jour';
      });
    });
  }
  var tabs = document.querySelectorAll('.rdva-tab'), cards = document.querySelectorAll('.rdva-card');
  function filtrer(f){
    for (var t = 0; t < tabs.length; t++) tabs[t].classList.toggle('is-on', tabs[t].dataset.f === f);
    for (var c = 0; c < cards.length; c++){
      var g = cards[c].dataset.g;
      var ok = f === 'all' || (f === 'todo' && (g === 'attente' || g === 'messages')) || g === f;
      cards[c].style.display = ok ? '' : 'none';
    }
  }
  for (var t = 0; t < tabs.length; t++) tabs[t].addEventListener('click', function(){ filtrer(this.dataset.f); });
})();
</script>
</div></div></div></body></html>
"""


