# 🔐 PAGE « AUTORISATION » (Gestion admin) — réservée au compte admin
# ─────────────────────────────────────────────
AUTORISATION_HTML = """<!DOCTYPE html><html>
<head><title>Autorisation — {{ ECOLE_NOM }}</title>""" + BASE_CSS + MACOS_CSS + """
<style>
.aut-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0 14px;}
.aut-tab{border:1px solid rgba(0,0,0,.1);background:var(--card-bg,#fff);color:inherit;border-radius:999px;
  padding:9px 18px;font-weight:700;font-size:.9rem;cursor:pointer;}
.aut-tab.active{background:var(--primary,#2563EB);color:#fff;border-color:transparent;}
.aut-bar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-bottom:12px;}
.aut-bar .aut-lbl{font-size:.8rem;opacity:.7;margin-right:4px;}
.aut-mini{border:1px solid rgba(0,0,0,.12);background:transparent;color:inherit;border-radius:8px;
  padding:6px 12px;font-size:.8rem;font-weight:600;cursor:pointer;}
.aut-mini:hover{background:rgba(120,120,128,.12);}
.aut-wrap{overflow-x:auto;border:1px solid rgba(0,0,0,.08);border-radius:14px;background:var(--card-bg,#fff);}
.aut-table{width:100%;border-collapse:collapse;min-width:560px;}
.aut-table th{font-size:.78rem;text-transform:uppercase;letter-spacing:.04em;opacity:.65;padding:12px 10px;text-align:center;}
.aut-table th:first-child{text-align:left;padding-left:16px;}
.aut-table td{padding:11px 10px;border-top:1px solid rgba(0,0,0,.06);vertical-align:middle;}
.aut-group td{background:rgba(120,120,128,.1);font-weight:800;font-size:.82rem;padding:8px 16px;}
.aut-name{font-weight:700;font-size:.95rem;}
.aut-desc{font-size:.76rem;opacity:.65;margin-top:2px;max-width:480px;}
.aut-cell{text-align:center;}
.aut-cell label{display:inline-flex;flex-direction:column;align-items:center;gap:3px;cursor:pointer;padding:4px 14px;}
.aut-cell input{width:18px;height:18px;cursor:pointer;}
.aut-cell small{font-size:.65rem;opacity:.55;}
tr.aut-changed td:first-child{box-shadow:inset 3px 0 0 #f59e0b;}
.aut-save{position:sticky;bottom:0;display:flex;gap:10px;align-items:center;flex-wrap:wrap;justify-content:space-between;
  margin-top:16px;padding:12px 16px;background:var(--card-bg,#fff);border:1px solid rgba(0,0,0,.1);border-radius:14px;
  box-shadow:0 -4px 16px rgba(0,0,0,.06);}
.aut-note{font-size:.8rem;opacity:.75;line-height:1.5;margin-top:14px;}
.aut-pill{display:inline-block;font-size:.72rem;font-weight:700;padding:2px 9px;border-radius:999px;background:rgba(245,158,11,.18);color:#b45309;}
</style>
</head><body class="page-hub"><div class="layout">
{{ nav_html|safe }}
<script>document.getElementById('page-title').textContent='Autorisation';</script>
{% for cat,msg in get_flashed_messages(with_categories=true) %}<div class="alert {{'alert-success' if cat=='success' else 'alert-error'}}">{{ msg }}</div>{% endfor %}

<div class="lux-hero"><div class="lux-hero-top"><div class="lux-hero-title">
  <div class="lux-hero-icon">🔐</div>
  <div><h2>Autorisation</h2>
  <p>Choisissez, pour chaque profil, les pages accessibles : aucun accès, lecture seule ou modification</p></div>
</div></div></div>

<form method="post" id="aut-form">
<input type="hidden" name="tab" id="aut-tab-field" value="{{ tab }}">
<div class="aut-tabs">
  {% for role, rlabel, ricon in roles %}
  <button type="button" class="aut-tab {{ 'active' if role == tab else '' }}" data-tab="{{ role }}">{{ ricon }} {{ rlabel }}</button>
  {% endfor %}
</div>

{% for role, rlabel, ricon in roles %}
<div class="aut-panel" id="panel-{{ role }}" style="{{ '' if role == tab else 'display:none;' }}">
  <div class="aut-bar">
    <span class="aut-lbl">Pour tout le profil « {{ rlabel }} » :</span>
    <button type="button" class="aut-mini" data-all="aucun">Tout : aucun</button>
    <button type="button" class="aut-mini" data-all="lecture">Tout : lecture</button>
    <button type="button" class="aut-mini" data-all="modification">Tout : modification</button>
    <button type="submit" class="aut-mini" name="action" value="reset:{{ role }}"
      onclick="return confirm('Remettre les droits PAR DÉFAUT du profil « {{ rlabel }} » ?');">↺ Valeurs par défaut</button>
    <span class="aut-pill" data-count style="display:none;"></span>
  </div>
  <div class="aut-wrap"><table class="aut-table">
    <thead><tr><th>Page</th>{% for n in niveaux %}<th>{{ libelles[n] }}</th>{% endfor %}</tr></thead>
    <tbody>
    {% for groupe, mods in groupes %}
      <tr class="aut-group"><td colspan="{{ 1 + niveaux|length }}">{{ groupe }}</td></tr>
      {% for m in mods %}
      <tr data-def="{{ defauts[role][m.key] }}">
        <td><div class="aut-name">{{ m.icone }} {{ m.label }}</div><div class="aut-desc">{{ m.desc }}</div></td>
        {% for n in niveaux %}
        <td class="aut-cell"><label>
          <input type="radio" name="niv__{{ role }}__{{ m.key }}" value="{{ n }}" {{ 'checked' if niveaux_actuels[role][m.key] == n else '' }}>
          {% if defauts[role][m.key] == n %}<small>par défaut</small>{% endif %}
        </label></td>
        {% endfor %}
      </tr>
      {% endfor %}
    {% endfor %}
    </tbody>
  </table></div>
</div>
{% endfor %}

<div class="aut-save">
  <span style="font-size:.82rem;opacity:.75;">Les changements s'appliquent immédiatement après l'enregistrement.</span>
  <button type="submit" class="btn btn-primary" name="action" value="save">💾 Enregistrer les autorisations</button>
</div>
</form>

<div class="aut-note">
  <b>À savoir :</b> le compte <b>admin</b> garde toujours l'accès complet. Les réglages de départ reproduisent ce que
  chaque profil peut faire aujourd'hui — vous retirez ou laissez. <b>Lecture</b> = le profil peut consulter la page mais
  tout enregistrement, ajout, modification ou suppression est refusé. Une page accordée à un professeur ou à une
  secrétaire s'ouvre avec les écrans de l'agent admin (jamais ceux de l'admin) ; les informations sensibles réservées
  à l'admin restent masquées. Les pages Utilisateurs, Sauvegardes et Autorisation ne sont pas concernées.
</div>

<script>
(function(){
  var form = document.getElementById('aut-form');
  var tabField = document.getElementById('aut-tab-field');
  function refresh(panel){
    var n = 0;
    panel.querySelectorAll('tbody tr[data-def]').forEach(function(tr){
      var chk = tr.querySelector('input[type=radio]:checked');
      var diff = chk && chk.value !== tr.getAttribute('data-def');
      tr.classList.toggle('aut-changed', !!diff);
      if (diff) n++;
    });
    var pill = panel.querySelector('[data-count]');
    if (pill){ pill.style.display = n ? 'inline-block' : 'none'; pill.textContent = n + ' page(s) différente(s) du réglage par défaut'; }
  }
  document.querySelectorAll('.aut-tab').forEach(function(b){
    b.addEventListener('click', function(){
      var t = b.getAttribute('data-tab'); tabField.value = t;
      document.querySelectorAll('.aut-tab').forEach(function(x){ x.classList.toggle('active', x === b); });
      document.querySelectorAll('.aut-panel').forEach(function(p){ p.style.display = (p.id === 'panel-' + t) ? '' : 'none'; });
    });
  });
  document.querySelectorAll('.aut-panel').forEach(function(panel){
    panel.querySelectorAll('[data-all]').forEach(function(btn){
      btn.addEventListener('click', function(){
        var v = btn.getAttribute('data-all');
        panel.querySelectorAll('input[type=radio][value="' + v + '"]').forEach(function(r){ r.checked = true; });
        refresh(panel);
      });
    });
    panel.addEventListener('change', function(){ refresh(panel); });
    refresh(panel);
  });
})();
</script>
</div></body></html>
"""


@app.route('/admin/autorisations', methods=['GET', 'POST'])
@login_required
@role_required('admin')
def admin_autorisations():
    # role_required('admin') laisse passer l'agent admin : cette page lui est interdite.
    if session.get('role') != 'admin':
        flash('Accès non autorisé.', 'error')
        return redirect(url_for('dashboard'))

    upgrade_db_autorisations()  # garantit la table (base neuve ou restaurée)

    if request.method == 'POST':
        action = request.form.get('action', 'save')
        tab = request.form.get('tab', '')
        if tab not in AUTORISATION_ROLES_KEYS:
            tab = AUTORISATION_ROLES_KEYS[0]
        actuels = _autorisations_courantes(force=True)
        nouveaux = {}
        if action.startswith('reset:'):
            role_cible = action.split(':', 1)[1]
            if role_cible in AUTORISATION_ROLES_KEYS:
                tab = role_cible
                for m in AUTORISATION_MODULES:
                    nouveaux[(role_cible, m['key'])] = _defaut_niveau(role_cible, m['key'])
        else:
            for role in AUTORISATION_ROLES_KEYS:
                for m in AUTORISATION_MODULES:
                    val = request.form.get(f"niv__{role}__{m['key']}")
                    if val in AUTORISATION_NIVEAUX:
                        nouveaux[(role, m['key'])] = val
        changements = [(cle, actuels.get(cle), val) for cle, val in nouveaux.items() if actuels.get(cle) != val]
        conn = get_db()
        try:
            for (role, module_key), ancien, val in changements:
                conn.execute(
                    "INSERT OR REPLACE INTO autorisations_roles (role, module, niveau, modifie_par, date_modif) "
                    "VALUES (?,?,?,?,CURRENT_TIMESTAMP)", (role, module_key, val, session.get('user_id')))
            if changements:
                libelle_role = {r[0]: r[1] for r in AUTORISATION_ROLES}
                detail = "; ".join(
                    f"{libelle_role[r]} · {_MODULES_PAR_CLE[mk]['label']} : {_LIBELLE_NIVEAU[a]} → {_LIBELLE_NIVEAU[v]}"
                    for (r, mk), a, v in changements)
                log_action(conn, 'modification', 'autorisations', None, detail[:1500])
            conn.commit()
        finally:
            conn.close()
        _AUTORISATIONS_CACHE['data'] = None
        if changements:
            flash(f"Autorisations enregistrées ({len(changements)} changement(s)).", 'success')
        else:
            flash("Aucun changement à enregistrer.", 'success')
        return redirect(url_for('admin_autorisations', tab=tab))

    tab = request.args.get('tab', '')
    if tab not in AUTORISATION_ROLES_KEYS:
        tab = AUTORISATION_ROLES_KEYS[0]
    courants = _autorisations_courantes(force=True)
    groupes, vus = [], {}
    for m in AUTORISATION_MODULES:
        if m['groupe'] not in vus:
            vus[m['groupe']] = []
            groupes.append((m['groupe'], vus[m['groupe']]))
        vus[m['groupe']].append(m)
    niveaux_actuels = {r: {m['key']: courants[(r, m['key'])] for m in AUTORISATION_MODULES}
                       for r in AUTORISATION_ROLES_KEYS}
    defauts = {r: {m['key']: _defaut_niveau(r, m['key']) for m in AUTORISATION_MODULES}
               for r in AUTORISATION_ROLES_KEYS}
    return render_template_string(
        AUTORISATION_HTML, roles=AUTORISATION_ROLES, groupes=groupes, niveaux=AUTORISATION_NIVEAUX,
        libelles=_LIBELLE_NIVEAU, niveaux_actuels=niveaux_actuels, defauts=defauts, tab=tab,
        notif_count=get_notif_count())


