@app.route('/avantages-scolarite')
@login_required
@role_required('admin')
def avantages_scolarite_liste():
    if not _bons_autorise():
        flash('Accès non autorisé.', 'error')
        return redirect(url_for('dashboard'))
    conn = get_db()
    try:
        _assurer_tables_bons_reduction(conn)
        f_ens = request.args.get('ens', type=int)
        f_statut, f_annee, f_mois = (request.args.get(k, '').strip() for k in ('statut', 'annee', 'mois'))
        cl, pr = [], []
        if f_ens: cl.append("b.enseignant_id=?"); pr.append(f_ens)
        if f_statut in ('en_attente', 'valide', 'annule'): cl.append("b.statut=?"); pr.append(f_statut)
        if f_annee: cl.append("b.annee_scolaire=?"); pr.append(f_annee)
        if f_mois: cl.append("b.mois_paie=?"); pr.append(f_mois)
        bons = [dict(r) for r in conn.execute(
            "SELECT b.*, u.prenom||' '||u.nom AS ens, e.prenom||' '||e.nom AS enfant FROM bons_reduction b "
            "JOIN users u ON b.enseignant_id=u.id JOIN eleves e ON b.eleve_id=e.id "
            + ("WHERE " + " AND ".join(cl) if cl else "") + " ORDER BY b.id DESC", pr).fetchall()]
        enseignants = [dict(r) for r in conn.execute("SELECT id, prenom, nom FROM users WHERE role='enseignant' ORDER BY prenom, nom").fetchall()]
        total = round(sum(b['montant_reduction'] for b in bons if b['statut'] == 'valide'), 2)
        return render_template_string(AV_LISTE_HTML, bons=bons, enseignants=enseignants, total=total, f_ens=f_ens,
                                      f_statut=f_statut, f_annee=f_annee, f_mois=f_mois, notif_count=get_notif_count())
    finally:
        conn.close()



_assurer_tables_bons_reduction()

