# pour page utilusateur :
UTILISATEURS_HTML = """<!DOCTYPE html><html><head><title>Gestion des Utilisateurs</title>""" + BASE_CSS + MACOS_CSS + """
</head><body><div class="layout">
{{ nav_html|safe }}
<script>document.getElementById('page-title').textContent='Gestion des Utilisateurs';</script>

<div class="container" style="padding-top: 20px;">

  {% for cat,msg in get_flashed_messages(with_categories=true) %}
  <div class="alert {{'alert-success' if cat=='success' else 'alert-error'}}" style="margin-bottom:20px; padding:12px; border-radius:6px; background: {{'#d4edda' if cat=='success' else '#f8d7da'}}; color: {{'#155724' if cat=='success' else '#721c24'}}; border: 1px solid {{'#c3e6cb' if cat=='success' else '#f5c6cb'}};">
    {{ msg }}
  </div>
  {% endfor %}

  <div class="card mb-20" style="padding: 15px 20px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 15px;">
    <div>
      <h2 style="font-size:1.4rem; font-weight:700;">👥 Annuaire des utilisateurs</h2>
      <p class="text-muted text-sm">Gérez les accès et les profils de l'application</p>
    </div>

    <form method="GET" action="/utilisateurs" style="display:flex; gap:10px; flex-grow:1; max-width: 400px;">
      <input type="text" name="q" value="{{ search_query }}" placeholder="Rechercher par nom, prénom ou email..." style="width:100%; padding:10px 15px; border:1px solid var(--gray-300); border-radius:8px; outline:none;">
      <button type="submit" class="btn btn-primary" style="padding:10px 20px;">🔍</button>
      {% if search_query %}
        <a href="/utilisateurs" class="btn btn-outline" style="padding:10px 15px; text-decoration:none;">✖</a>
      {% endif %}
    </form>

    {% if session.role == 'admin' %}
    <button type="button" onclick="document.getElementById('reset-financier-modal').style.display='flex'" class="btn btn-outline" style="color:var(--red); border-color:var(--red); white-space:nowrap;">
      ⚠️ Réinitialiser paiements/salaires/charges
    </button>
    {% endif %}
  </div>

  {% if session.role == 'admin' %}
  <div id="reset-financier-modal" style="display:none; position:fixed; top:0; left:0; width:100%; height:100%; background:rgba(0,0,0,0.5); z-index:1000; align-items:center; justify-content:center;">
    <div class="card" style="width:100%; max-width:480px; margin:10vh auto; padding:25px; box-shadow:var(--shadow-lg);">
      <h3 style="font-size:1.2rem; font-weight:700; margin-bottom:10px; color:var(--gray-900);">⚠️ Réinitialiser toutes les données financières</h3>
      <p class="text-muted text-sm" style="margin-bottom:15px;">
        Cette action supprime <strong>définitivement et irréversiblement</strong> :
      </p>
      <ul class="text-sm text-muted" style="margin:0 0 15px 20px; line-height:1.8;">
        <li>Tous les <strong>paiements de scolarité</strong> des élèves</li>
        <li>Tous les <strong>salaires versés aux enseignants</strong></li>
        <li>Tous les <strong>salaires versés au personnel</strong> (hors prof)</li>
        <li>Toutes les <strong>charges / dépenses</strong> de l'établissement</li>
      </ul>
      <p class="text-sm" style="margin-bottom:15px;">Les élèves, employés et classes eux-mêmes ne sont pas supprimés — seul l'historique financier est effacé.</p>
      <form method="POST" action="/admin/reset-financier" onsubmit="return confirm('Dernière confirmation : voulez-vous vraiment tout effacer ? Cette action est irréversible.');">
        <label style="font-weight:600; font-size:0.9rem; display:block; margin-bottom:6px;">
          Tapez <code>RESET</code> pour confirmer :
        </label>
        <input type="text" name="confirmation" required placeholder="RESET" style="width:100%; padding:10px; border:1px solid var(--gray-300); border-radius:6px; margin-bottom:20px; text-transform:uppercase;">
        <div style="display:flex; justify-content:flex-end; gap:10px;">
          <button type="button" onclick="document.getElementById('reset-financier-modal').style.display='none'" class="btn btn-outline">Annuler</button>
          <button type="submit" class="btn" style="background:var(--red); color:#fff;">🗑️ Tout réinitialiser</button>
        </div>
      </form>
    </div>
  </div>
  {% endif %}

  <div class="card">
    <table>
      <thead>
        <tr>
          <th>Utilisateur</th>
          <th>Email</th>
          <th>Rôle</th>
          <th style="text-align:right;">Actions</th>
        </tr>
      </thead>
      <tbody>
        {% for u in users %}
        <tr>
          <td>
            <div style="display:flex; align-items:center; gap:10px;">
              <div style="width:35px; height:35px; border-radius:50%; background:var(--gray-200); display:flex; align-items:center; justify-content:center; font-size:1.1rem;">
                {{ '🧑‍🏫' if u.role == 'enseignant' else '👨‍👩‍👧' if u.role == 'parent' else '🎓' if u.role == 'eleve' else '🛡️' }}
              </div>
              <strong>{{ u.prenom }} {{ u.nom }}</strong>
            </div>
          </td>
          <td style="color:var(--gray-600);">{{ u.email }}</td>
          <td>
            <span class="badge {{ 'badge-blue' if u.role == 'enseignant' else 'badge-green' if u.role == 'parent' else 'badge-amber' if (u.role == 'admin' or u.role.startswith('responsable_')) else 'badge-gray' }}">
              {{ u.role | capitalize }}
            </span>
          </td>
          <td style="text-align:right; display:flex; justify-content:flex-end; gap:8px;">
            <button onclick="openEditModal({{ u.id }}, '{{ u.prenom|replace(\"'\", \"\\\\'\") }}', '{{ u.nom|replace(\"'\", \"\\\\'\") }}', '{{ u.email|replace(\"'\", \"\\\\'\") }}', '{{ u.role }}')" class="btn btn-outline btn-sm" style="color:var(--amber); border-color:var(--amber);">✏️</button>

            {% if u.id|string != session.user_id|string %}
            <form action="/utilisateurs" method="POST" onsubmit="return confirm('Êtes-vous sûr de vouloir supprimer {{ u.prenom }} {{ u.nom }} définitivement ?');" style="display:inline;">
              <input type="hidden" name="action" value="delete">
              <input type="hidden" name="user_id" value="{{ u.id }}">
              <button type="submit" class="btn btn-outline btn-sm" style="color:var(--red); border-color:var(--red);">🗑️</button>
            </form>
            {% endif %}
          </td>
        </tr>
        {% else %}
        <tr>
          <td colspan="4" style="text-align:center; padding:30px; color:var(--gray-500);">
            Aucun utilisateur trouvé pour "<strong>{{ search_query }}</strong>".
          </td>
        </tr>
        {% endfor %}
      </tbody>
    </table>
  </div>

</div>

<div id="edit-modal" style="display:none; position:fixed; top:0; left:0; width:100%; height:100%; background:rgba(0,0,0,0.5); z-index:1000; align-items:center; justify-content:center;">
  <div class="card" style="width:100%; max-width:500px; margin: 10vh auto; padding:25px; box-shadow:var(--shadow-lg);">
    <h3 style="font-size:1.2rem; font-weight:700; margin-bottom:20px;">✏️ Modifier l'utilisateur</h3>

    <form action="/utilisateurs" method="POST">
      <input type="hidden" name="action" value="edit">
      <input type="hidden" name="user_id" id="edit-user-id">

      <div style="display:grid; grid-template-columns:1fr 1fr; gap:15px; margin-bottom:15px;">
        <div class="form-group">
          <label style="font-weight:600; font-size:0.9rem; display:block; margin-bottom:5px;">Prénom</label>
          <input type="text" name="prenom" id="edit-prenom" required style="width:100%; padding:10px; border:1px solid var(--gray-300); border-radius:6px;">
        </div>
        <div class="form-group">
          <label style="font-weight:600; font-size:0.9rem; display:block; margin-bottom:5px;">Nom</label>
          <input type="text" name="nom" id="edit-nom" required style="width:100%; padding:10px; border:1px solid var(--gray-300); border-radius:6px;">
        </div>
      </div>

      <div class="form-group" style="margin-bottom:15px;">
        <label style="font-weight:600; font-size:0.9rem; display:block; margin-bottom:5px;">Email</label>
        <input type="email" name="email" id="edit-email" required style="width:100%; padding:10px; border:1px solid var(--gray-300); border-radius:6px;">
      </div>

      <div class="form-group" style="margin-bottom:25px;">
        <label style="font-weight:600; font-size:0.9rem; display:block; margin-bottom:5px;">Rôle</label>
        <select name="role" id="edit-role" required style="width:100%; padding:10px; border:1px solid var(--gray-300); border-radius:6px; background:white;">
          <option value="admin">Admin</option>
          <option value="enseignant">Enseignant</option>
          <option value="parent">Parent</option>
          <option value="eleve">Élève</option>
        </select>
      </div>

      <div style="display:flex; justify-content:flex-end; gap:10px;">
        <button type="button" onclick="document.getElementById('edit-modal').style.display='none'" class="btn btn-outline">Annuler</button>
        <button type="submit" class="btn btn-primary">💾 Enregistrer</button>
      </div>
    </form>
  </div>
</div>

<script>
// Fonction JS pour pré-remplir et afficher le modal de modification
function openEditModal(id, prenom, nom, email, role) {
    document.getElementById('edit-user-id').value = id;
    document.getElementById('edit-prenom').value = prenom;
    document.getElementById('edit-nom').value = nom;
    document.getElementById('edit-email').value = email;
    document.getElementById('edit-role').value = role;

    document.getElementById('edit-modal').style.display = 'flex';
}
</script>

</div></body></html>"""
# ensignant hub
# eleve hub
ELEVES_HUB_HTML = """<!DOCTYPE html><html><head><title>Choix du Cycle - Élèves</title>""" + BASE_CSS + MACOS_CSS + ENS_PAGES_CSS + """</head><body class="page-cyclehub{% if session.role == 'enseignant' %} em-t{% endif %}"><div class="layout">
{{ nav_html|safe }}
<script>document.getElementById('page-title').textContent='Gestion des Élèves';</script>
{% if session.role == 'enseignant' %}
<!-- 🆕 ENSEIGNANT (mobile) — choix du cycle : même design que le dashboard mobile. Masqué sur ordinateur. -->
<div class="em-root">
  {% set _tc = namespace(c=0, e=0) %}
  {% for c in cycles %}{% set _s = (em_stats or {}).get(c.nom, {}) %}{% set _tc.c = _tc.c + _s.get('classes', 0) %}{% set _tc.e = _tc.e + _s.get('eleves', 0) %}{% endfor %}
  <div class="em-hero">
    <div class="em-top">
      <div>
        <div class="em-greet">Mes élèves</div>
        <div class="em-name">Choisissez un cycle</div>
        <div class="em-date">Vos classes assignées, par cycle</div>
      </div>
      <div class="em-avatar">👥</div>
    </div>
    <div class="em-pills">
      <span class="em-pill">🏫 {{ _tc.c }} classe{{ 's' if _tc.c > 1 else '' }}</span>
      <span class="em-pill">🧒 {{ _tc.e }} élève{{ 's' if _tc.e > 1 else '' }}</span>
    </div>
  </div>
  <div class="em-sec">
    <div class="em-sec-h"><h3>Cycles</h3></div>
    <div class="em-tiles">
      {% for c in cycles %}
      {% set _s = (em_stats or {}).get(c.nom, {}) %}
      <a class="em-tile" href="?cycle={{ c.nom|urlencode }}" style="--i:{{ loop.index0 }}">
        <span class="em-tile-ic">{{ cycle_icon_html(c, '54px', '3px') }}</span>
        <span class="em-tile-b"><b>{{ c.nom }}</b><small>{{ _s.get('classes', 0) }} classe{{ 's' if _s.get('classes', 0) > 1 else '' }} · {{ _s.get('eleves', 0) }} élève{{ 's' if _s.get('eleves', 0) > 1 else '' }}</small></span>
        <span class="em-go">›</span>
      </a>
      {% else %}
      <div class="em-box"><div class="em-empty">Vous n'êtes assigné à aucune classe pour le moment. Rapprochez-vous de l'administration.</div></div>
      {% endfor %}
      {% if cycles %}
      <a class="em-tile" href="?tous=1" style="--i:{{ cycles|length }}">
        <span class="em-tile-ic"><span class="em-act-i" style="width:54px;height:54px;border-radius:50%;background:linear-gradient(135deg,#7c3aed,#db2777);font-size:1.6rem;">👥</span></span>
        <span class="em-tile-b"><b>Tous mes élèves</b><small>Tous cycles et classes confondus</small></span>
        <span class="em-go">›</span>
      </a>
      {% endif %}
    </div>
  </div>
</div>
{% endif %}
<div class="container{% if session.role == 'enseignant' %} em-old{% endif %}" style="padding-top: 20px;">
  <div style="display:flex; align-items:center; justify-content:space-between; flex-wrap:wrap; gap:10px; margin-bottom:10px;">
    <div>
      <h2 style="font-size:1.6rem; font-weight:700; margin-bottom:6px; color:#000;">👥 Sélectionner un cycle pour les Éléves</h2>
      <p class="text-muted" style="margin:0;">Choisissez un cycle d'enseignement pour accéder aux listes d'élèves.</p>
    </div>
    {% if session.role in ('admin', 'agent_admin') %}
    <div style="display:flex; gap:10px; flex-wrap:wrap;">
      <a href="/eleves/add" class="btn btn-primary" style="text-decoration:none;">➕ Nouvel élève</a>
      <a href="/eleves/importer" class="btn btn-outline" style="text-decoration:none;">📥 Importer Excel</a>
      <button type="button" class="btn btn-primary" onclick="document.getElementById('modal-add-cycle').style.display='flex'">➕ Ajouter un cycle</button>
    </div>
    {% endif %}
  </div>

  <div class="grid-3" style="gap: 30px; margin-top: 30px;">

    {% for c in cycles %}
    <div style="position:relative; display:flex; flex-direction:column; align-items:center; justify-content:center; padding:20px; background:transparent; transition:all 0.2s;">
      {% if session.role in ('admin', 'agent_admin') %}
      <button type="button" onclick="event.stopPropagation(); confirmDeleteCycle({{ c.id }}, '{{ c.nom|replace("'", "\\\\'") }}')" title="Supprimer ce cycle" style="position:absolute; top:10px; right:10px; width:28px; height:28px; border-radius:50%; border:none; background:var(--red-light); color:var(--red); cursor:pointer; font-size:0.9rem; line-height:1; z-index:2;">✕</button>
      <button type="button" onclick="event.stopPropagation(); openPhotoCycle({{ c.id }}, '{{ c.nom|replace("'", "\\\\'") }}', {{ 'true' if c.photo else 'false' }})" title="Changer la photo de ce cycle" style="position:absolute; top:10px; left:10px; width:28px; height:28px; border-radius:50%; border:none; background:var(--blue-light,#e8f1ff); color:var(--blue); cursor:pointer; font-size:0.9rem; line-height:1; z-index:2;">📷</button>
      {% endif %}
      <a href="?cycle={{ c.nom }}" class="zoom-card" style="display:flex; flex-direction:column; align-items:center; text-decoration:none; width:100%;">
        <div style="display:flex; justify-content:center; margin-bottom:15px;">{{ cycle_icon_html(c, '180px', '6px') }}</div>
        <h3 style="color:var(--gray-900); font-size:1.4rem;">{{ c.nom }}</h3>
        <span class="badge" style="margin-top:10px; background:var(--{{ c.couleur }}-light, var(--gray-100)); color:var(--{{ c.couleur }});">Élèves {{ c.nom }}</span>
      </a>
    </div>
    {% else %}
    {% if session.role == 'enseignant' %}<div class="card" style="grid-column:1/-1; text-align:center; padding:30px;"><p class="text-muted">Vous n'êtes assigné à aucune classe pour le moment. Rapprochez-vous de l'administration.</p></div>{% endif %}
    {% endfor %}

    {% if not (session.role == 'enseignant' and not cycles) %}
    <div style="position:relative; display:flex; flex-direction:column; align-items:center; justify-content:center; padding:20px; background:transparent; transition:all 0.2s;">
      <a href="?tous=1" class="zoom-card" style="display:flex; flex-direction:column; align-items:center; text-decoration:none; width:100%;">
        <div style="display:flex; justify-content:center; margin-bottom:15px;">
          <div style="width:180px;height:180px;border-radius:50%;overflow:hidden;display:inline-flex;align-items:center;justify-content:center;background:#fff;border:6px solid var(--purple, #FFD60A);box-shadow:0 4px 14px rgba(0,0,0,.18), inset 0 0 0 3px rgba(255,255,255,.75);flex-shrink:0;">
            <span style="font-size:90px; line-height:1;">👥</span>
          </div>
        </div>
        <h3 style="color:var(--gray-900); font-size:1.4rem;">Tous les élèves</h3>
        <span class="badge badge-purple" style="margin-top:10px;">Tous cycles et classes confondus</span>
      </a>
    </div>
    {% endif %}

    {% if session.role in ('admin', 'agent_admin') %}
    <!-- 🆕 ÉLÈVE SORTANT : hub à 2 choix (durant l'année / fin d'année) -->
    <div style="position:relative; display:flex; flex-direction:column; align-items:center; justify-content:center; padding:20px; background:transparent; transition:all 0.2s;">
      <a href="?sortants=1" class="zoom-card" style="display:flex; flex-direction:column; align-items:center; text-decoration:none; width:100%;">
        <div style="display:flex; justify-content:center; margin-bottom:15px;">
          <div style="width:180px;height:180px;border-radius:50%;overflow:hidden;display:inline-flex;align-items:center;justify-content:center;background:#fff;border:6px solid #E08A00;box-shadow:0 4px 14px rgba(0,0,0,.18), inset 0 0 0 3px rgba(255,255,255,.75);flex-shrink:0;">
            <span style="font-size:90px; line-height:1;">🚪</span>
          </div>
        </div>
        <h3 style="color:var(--gray-900); font-size:1.4rem;">ÉLÈVE SORTANT</h3>
        <span class="badge badge-amber" style="margin-top:10px;">Départs durant l'année ou en fin d'année</span>
      </a>
    </div>
    {% endif %}

  </div>
</div>

{% if session.role in ('admin', 'agent_admin') %}
<!-- 🆕 Modal Ajout d'un cycle -->
<div id="modal-add-cycle" style="display:none; position:fixed; inset:0; background:rgba(0,0,0,.5); align-items:center; justify-content:center; z-index:1000;">
  <div class="card" style="width:95%; max-width:420px; padding:25px;">
    <h3 style="margin-top:0; margin-bottom:20px; color:var(--gray-900); font-weight:700;">➕ Ajouter un cycle</h3>
    <form method="POST" action="{{ url_for('cycles_action') }}" enctype="multipart/form-data">
      <input type="hidden" name="action" value="add">
      <div class="form-group" style="margin-bottom:15px;">
        <label style="font-weight:600; font-size:0.9rem; display:block; margin-bottom:5px;">Nom du cycle</label>
        <input type="text" name="nom" required placeholder="ex: Lycée" style="width:100%; padding:10px; border:1px solid var(--gray-300); border-radius:6px;">
      </div>
      <div class="form-group" style="margin-bottom:15px;">
        <label style="font-weight:600; font-size:0.9rem; display:block; margin-bottom:5px;">Icône (emoji)</label>
        <input type="text" name="icone" value="🏫" maxlength="4" style="width:100%; padding:10px; border:1px solid var(--gray-300); border-radius:6px;">
      </div>
      <div class="form-group" style="margin-bottom:15px;">
        <label style="font-weight:600; font-size:0.9rem; display:block; margin-bottom:5px;">Photo (optionnel — remplace l'icône)</label>
        <input type="file" name="photo" accept="image/*" style="width:100%; padding:8px; border:1px solid var(--gray-300); border-radius:6px; background:white;">
      </div>
      <div class="form-group" style="margin-bottom:20px;">
        <label style="font-weight:600; font-size:0.9rem; display:block; margin-bottom:5px;">Couleur</label>
        <select name="couleur" style="width:100%; padding:10px; border:1px solid var(--gray-300); border-radius:6px; background:white;">
          <option value="blue-mid">Bleu</option>
          <option value="green">Vert</option>
          <option value="amber">Ambre</option>
          <option value="purple">Violet</option>
          <option value="red">Rouge</option>
        </select>
      </div>
      <div style="display:flex; justify-content:flex-end; gap:10px;">
        <button type="button" onclick="document.getElementById('modal-add-cycle').style.display='none'" class="btn btn-outline">Annuler</button>
        <button type="submit" class="btn btn-primary">💾 Ajouter</button>
      </div>
    </form>
  </div>
</div>

<!-- 🆕 Modal Changer la photo d'un cycle existant -->
<div id="modal-photo-cycle" style="display:none; position:fixed; inset:0; background:rgba(0,0,0,.5); align-items:center; justify-content:center; z-index:1000;">
  <div class="card" style="width:95%; max-width:420px; padding:25px;">
    <h3 style="margin-top:0; margin-bottom:5px; color:var(--gray-900); font-weight:700;">📷 Photo du cycle</h3>
    <p class="text-muted" id="photo-cycle-nom" style="margin-top:0; margin-bottom:20px;"></p>
    <form method="POST" action="{{ url_for('cycles_action') }}" enctype="multipart/form-data">
      <input type="hidden" name="action" value="photo">
      <input type="hidden" name="cycle_id" id="photo-cycle-id" value="">
      <div class="form-group" style="margin-bottom:20px;">
        <label style="font-weight:600; font-size:0.9rem; display:block; margin-bottom:5px;">Choisir une image</label>
        <input type="file" name="photo" accept="image/*" required style="width:100%; padding:8px; border:1px solid var(--gray-300); border-radius:6px; background:white;">
      </div>
      <div style="display:flex; justify-content:space-between; align-items:center; gap:10px;">
        <button type="button" id="photo-cycle-remove-btn" onclick="removePhotoCycle()" class="btn btn-outline" style="display:none;">🗑️ Retirer la photo</button>
        <div style="display:flex; gap:10px; margin-left:auto;">
          <button type="button" onclick="document.getElementById('modal-photo-cycle').style.display='none'" class="btn btn-outline">Annuler</button>
          <button type="submit" class="btn btn-primary">💾 Enregistrer</button>
        </div>
      </div>
    </form>
  </div>
</div>

<!-- 🆕 Formulaire caché de suppression de photo, soumis via removePhotoCycle() -->
<form id="form-remove-photo-cycle" method="POST" action="{{ url_for('cycles_action') }}" style="display:none;">
  <input type="hidden" name="action" value="remove_photo">
  <input type="hidden" name="cycle_id" id="remove-photo-cycle-id" value="">
</form>

<!-- 🆕 Formulaire caché de suppression, soumis via confirmDeleteCycle() -->
<form id="form-delete-cycle" method="POST" action="{{ url_for('cycles_action') }}" style="display:none;">
  <input type="hidden" name="action" value="delete">
  <input type="hidden" name="cycle_id" id="delete-cycle-id" value="">
</form>
<script>
function confirmDeleteCycle(id, nom) {
    if (confirm('Supprimer le cycle « ' + nom + ' » ?\\n\\n(Impossible si des classes y sont encore rattachées.)')) {
        document.getElementById('delete-cycle-id').value = id;
        document.getElementById('form-delete-cycle').submit();
    }
}
function openPhotoCycle(id, nom, aUnePhoto) {
    document.getElementById('photo-cycle-id').value = id;
    document.getElementById('photo-cycle-nom').textContent = nom;
    document.getElementById('photo-cycle-remove-btn').style.display = aUnePhoto ? 'inline-flex' : 'none';
    document.getElementById('modal-photo-cycle').style.display = 'flex';
}
function removePhotoCycle() {
    if (confirm('Retirer la photo de ce cycle et revenir à l\\'emoji ?')) {
        document.getElementById('remove-photo-cycle-id').value = document.getElementById('photo-cycle-id').value;
        document.getElementById('form-remove-photo-cycle').submit();
    }
}
</script>
{% endif %}

</div></div></body></html>"""
