ADD_ELEVE_HTML = """<!DOCTYPE html><html><head><title>Ajouter élève</title>""" + BASE_CSS + MACOS_CSS + """</head><body><div class="layout">
{{ nav_html|safe }}
<script>document.getElementById('page-title').textContent='Ajouter un élève';</script>
<div class="card" style="max-width:700px">
  <div class="card-header"><span class="card-title">+ Nouvel élève</span><a href="/eleves" class="btn btn-outline btn-sm">← Retour</a></div>
  <div class="card-body">
    <form method="post">
      <div class="form-grid">
        <div class="form-group"><label>Nom *</label><input name="nom" required placeholder="Alami"></div>
        <div class="form-group"><label>Prénom *</label><input name="prenom" required placeholder="Karim"></div>
        <div class="form-group"><label>Nom Arabe</label><input name="nom_arabe" placeholder="الاسم العائلي"></div>
        <div class="form-group"><label>Prénom Arabe</label><input name="prenom_arabe" placeholder="الاسم الشخصي"></div>
        <div class="form-group"><label>Sexe *</label>
          <select name="sexe" required>
            <option value="M">👦 Garçon</option>
            <option value="F">👧 Fille</option>
          </select>
        </div>

        <div class="form-group"><label>Date de naissance</label><input type="date" name="date_naissance"></div>
        <div class="form-group"><label>Lieu de naissance</label><input type="text" name="lieu_naissance"></div>
        <div class="form-group"><label>Adresse</label><input type="text" name="adresse" placeholder="Adresse du domicile, ou GPS / lien OSM">
          <small class="text-muted" style="font-size:.7rem;">Ex : 34,0066014 ; -5,0066006 (ou un lien openstreetmap.org)</small>
        </div>
        <div class="form-group"><label>Adresse 2</label><input type="text" name="adresse2" placeholder="Adresse en toutes lettres (ex : 12 rue des Fleurs, Quartier X, Fès)"></div>
        <div class="form-group"><label>Date d'inscription</label><input type="date" name="date_inscription"></div>
        <div class="form-group"><label>Matricule</label><input type="text" name="numero_matricule" placeholder="Ex: EL0012"></div>

        <div class="form-group"><label>Classe</label><select name="classe_id" onchange="appliquerReferenceParClasse(this)"><option value="">Sélectionner...</option>{% for c in classes %}<option value="{{ c.id }}" data-ref="{{ 1500 if c.cycle == 'College' else (1000 if (c.cycle == 'Primaire' or not c.cycle) else 800) }}">{{ c.nom }} ({{ c.niveau }})</option>{% endfor %}</select></div>

      </div>

      <div class="mt-20" style="margin-top:20px;">
        <div style="display:flex; gap:10px; align-items:center; margin-bottom:10px;">
          <strong>👨‍👩‍👧 Parent de l'élève</strong>
        </div>
        <input type="hidden" name="parent_mode" id="parent_mode" value="nouveau">
        <div id="parent-mode-segment" style="display:flex; gap:8px; margin-bottom:14px;">
          <div class="lux-role-option" data-mode="nouveau" onclick="setParentMode('nouveau')" style="cursor:pointer; padding:8px 14px; border-radius:8px; border:1px solid var(--gray-200);">🆕 Nouveau parent</div>
          <div class="lux-role-option" data-mode="existant" onclick="setParentMode('existant')" style="cursor:pointer; padding:8px 14px; border-radius:8px; border:1px solid var(--gray-200);">👪 Parent déjà existant (fratrie)</div>
        </div>

        <div id="parent-existant-fields" style="display:none;">
          <div class="form-grid">
            <div class="form-group">
              <label>Parent</label>
              <input type="text" id="addEleveParentSearch" placeholder="🔍 Rechercher un parent..." oninput="addEleveFilterParents()" style="width:100%;margin-bottom:6px;padding:6px 10px;border:1px solid var(--gray-300);border-radius:8px;font-size:.85rem;" autocomplete="off">
              <select name="parent_id" id="addEleveParentSelect"><option value="">Sélectionner...</option>{% for p in parents %}<option value="{{ p.id }}">{{ p.nom_complet }}</option>{% endfor %}</select>
            </div>
          </div>
        </div>

        <div id="parent-nouveau-fields">
          <div class="form-grid">
            <div class="form-group"><label>Nom du parent *</label><input type="text" name="nouveau_parent_nom" placeholder="Alami"></div>
            <div class="form-group"><label>Prénom du parent *</label><input type="text" name="nouveau_parent_prenom" placeholder="Mohammed"></div>
          </div>
          <div class="form-grid" style="margin-top:10px;">
            <div class="form-group"><label>Email (login) *</label><input type="email" name="nouveau_parent_email" placeholder="parent@email.com"></div>
            <div class="form-group"><label>Mot de passe *</label><input type="password" name="nouveau_parent_password" minlength="6" placeholder="6 caractères min."></div>
          </div>
          <div class="form-grid" style="margin-top:10px;">
            <div class="form-group"><label>Téléphone</label><input type="tel" name="nouveau_parent_telephone" placeholder="06XXXXXXXX"></div>
            <div class="form-group"><label>CIN</label><input type="text" name="nouveau_parent_cin"></div>
          </div>
          <small class="text-muted" style="font-size:.75rem;">Un compte parent (accès Espace Parent) sera créé automatiquement avec ces informations et assigné à cet élève. Les champs Nom du père / Métier / Nom de la mère / Métier ci-dessus seront aussi enregistrés sur ce compte.</small>
        </div>
      </div>

      <div class="mt-20" style="margin-top:20px;">
        <div style="margin-bottom:10px;"><strong>💰 Frais d'inscription</strong></div>
        <div class="form-grid">
          <div class="form-group"><label>Montant référence frais d'inscription (MAD) <a href="#" onclick="return deverrouillerMontantRef(this,'add_page_inscription')" style="font-size:.7rem;font-weight:400;">🔓 modifier</a></label><input type="number" step="0.01" name="montant_inscription" id="add_page_inscription" value="800" readonly style="background:#f3f4f6;cursor:not-allowed;" oninput="calculerReductionAuto('add_page_inscription','add_page_inscription_convenu','add_page_inscription_reduction')"></div>
          <div class="form-group"><label>💰 Montant convenu (MAD)</label><input type="number" id="add_page_inscription_convenu" step="0.01" min="0" placeholder="Ex: 900" oninput="calculerReductionAuto('add_page_inscription','add_page_inscription_convenu','add_page_inscription_reduction')"></div>
          <div class="form-group"><label>🏷️ Réduction (%) — calculée automatiquement</label><input type="number" name="reduction_inscription_pourcentage" id="add_page_inscription_reduction" step="any" min="0" max="100" value="0" readonly style="background:#f3f4f6;cursor:not-allowed;"></div>
          <div class="form-group"><label>Montant déjà payé (MAD)</label><input type="number" step="0.01" name="montant_paye_inscription" id="add_page_inscription_paye" value="0" oninput="toggleModeEncaissementAdd()"></div>
          <div class="form-group" id="add_page_inscription_mode_wrap" style="display:none;"><label>💰 Mode d'encaissement</label>
            <select name="mode_encaissement_inscription" id="add_page_inscription_mode">
              <option value="Caisse">💵 Caisse</option>
              <option value="Banque">🏦 Banque</option>
            </select>
          </div>
        </div>
        <small class="text-muted" style="font-size:.75rem;">Ces frais seront ajoutés sur la page Paiements de l'élève (catégorie « Frais d'inscription »). Laisser 0 si aucun frais d'inscription n'est à facturer. Laissez « Montant convenu » vide si aucune réduction n'est accordée.</small>
      </div>

      <div class="form-grid" style="margin-top:20px;">
        <div class="form-group"><label>Mensualité Scolarité — référence (MAD) <a href="#" onclick="return deverrouillerMontantRef(this,'add_page_mensualite')" style="font-size:.7rem;font-weight:400;">🔓 modifier</a></label><input type="number" name="montant_mensualite" id="add_page_mensualite" value="800" required readonly style="background:#f3f4f6;cursor:not-allowed;" oninput="calculerReductionAuto('add_page_mensualite','add_page_convenu','add_page_reduction')"></div>
        <div class="form-group"><label>💰 Montant convenu / mois (MAD)</label><input type="number" id="add_page_convenu" name="montant_convenu" step="0.01" min="0" placeholder="Ex: 700" oninput="calculerReductionAuto('add_page_mensualite','add_page_convenu','add_page_reduction')"></div>
        <div class="form-group"><label>🏷️ Réduction (%) — calculée automatiquement</label><input type="number" name="reduction_pourcentage" id="add_page_reduction" step="any" min="0" max="100" value="0" placeholder="Ex: 10" readonly style="background:#f3f4f6;cursor:not-allowed;"></div>

        <div class="form-group">
          <label>Abonné au transport ?</label>
          <select name="transport_abonne" id="page_add_transport" onchange="toggleTransportPageAdd()">
            <option value="non">Non</option>
            <option value="oui">Oui</option>
          </select>
        </div>
        <div class="form-group" id="add_page_div_montant" style="display:none;grid-column:1/-1;">
          <label>🚌 Transport</label>
          <div style="padding:8px 10px;background:#f3f4f6;border-radius:8px;font-size:.85rem;">Montant fixe : <b>300 MAD / mois</b>. Le « montant convenu » ci-dessus inclut le transport (100 MAD net + 200 MAD de réduction).</div>
          <input type="hidden" name="transport_tarif" id="add_page_tarif" value="inclus">
          <div id="add_page_apercu" style="display:none;margin-top:8px;padding:8px 10px;background:#ecfdf5;border-radius:8px;font-size:.82rem;font-weight:600;"></div>
        </div>
        <div class="form-group"><label>Groupe sanguin</label>
          <select name="groupe_sanguin">
            <option value="">Inconnu</option>
            {% for gs in ['A+','A-','B+','B-','AB+','AB-','O+','O-'] %}<option value="{{ gs }}">{{ gs }}</option>{% endfor %}
          </select>
        </div>
        <div class="form-group"><label>Allergies / besoins particuliers</label><input type="text" name="allergies" placeholder="Ex: Allergie aux arachides"></div>
        <div class="form-group"><label>Contact d'urgence — Nom</label><input type="text" name="contact_urgence_nom" placeholder="Nom du contact"></div>
        <div class="form-group"><label>Contact d'urgence — Téléphone</label><input type="tel" name="contact_urgence_tel" placeholder="06XXXXXXXX"></div>

      </div>
      <div class="mt-20"><button type="submit" class="btn btn-primary">💾 Enregistrer</button></div>
    </form>
  </div>
</div>
</div>
<script>
// 🆕 Calcule automatiquement le taux de réduction (%) à partir de la mensualité pleine
// et du "montant convenu" saisi par l'utilisateur (ex: mensualité 800, convenu 700 -> 12,5%).
function calculerReductionAuto(idMensualite, idConvenu, idReduction) {
    var mensualite = parseFloat(document.getElementById(idMensualite).value) || 0;
    var convenuRaw = document.getElementById(idConvenu).value;
    var reductionInput = document.getElementById(idReduction);
    if (convenuRaw === '' || mensualite <= 0) { reductionInput.value = 0; return; }
    var convenu = parseFloat(convenuRaw);
    if (isNaN(convenu)) { reductionInput.value = 0; return; }
    var pct = ((mensualite - convenu) / mensualite) * 100;
    if (pct < 0) pct = 0;
    if (pct > 100) pct = 100;
    reductionInput.value = Math.round(pct * 100000000) / 100000000;
}
// 🆕 Montant de référence de la scolarité selon le cycle de la classe choisie
// (Primaire = 1000 MAD, Collège = 1500 MAD, autres = 800 MAD).
function appliquerReferenceParClasse(select) {
    var opt = select.options[select.selectedIndex];
    var ref = opt ? parseFloat(opt.getAttribute('data-ref')) : NaN;
    var champ = document.getElementById('add_page_mensualite');
    if (!champ || isNaN(ref) || !champ.readOnly) return; // ne pas écraser une saisie manuelle
    champ.value = ref;
    calculerReductionAuto('add_page_mensualite', 'add_page_convenu', 'add_page_reduction');
}
// 🆕 Déverrouille exceptionnellement un montant de référence (normalement grisé/readonly).
function deverrouillerMontantRef(lien, idChamp) {
    var champ = document.getElementById(idChamp);
    if (champ) {
        champ.readOnly = false;
        champ.style.background = '#fff';
        champ.style.cursor = 'text';
        champ.focus();
    }
    if (lien) { lien.style.display = 'none'; }
    return false;
}
// 🆕 Affiche le choix Caisse/Banque uniquement si un montant de frais d'inscription
// a déjà été réglé dès la fiche d'inscription.
function toggleModeEncaissementAdd() {
    var champPaye = document.getElementById('add_page_inscription_paye');
    var wrap = document.getElementById('add_page_inscription_mode_wrap');
    if (!champPaye || !wrap) return;
    var montant = parseFloat(champPaye.value) || 0;
    wrap.style.display = montant > 0 ? 'block' : 'none';
}
document.addEventListener('DOMContentLoaded', function () {
    if (document.getElementById('add_page_inscription_paye')) { toggleModeEncaissementAdd(); }
});
function toggleTransportPageAdd() {
    transportRegleMaj('page_add_transport', 'add_page_div_montant', 'add_page_tarif', 'add_page_choix', 'add_page_apercu', 'add_page_mensualite', 'add_page_convenu');
}

// 🚌 Transport fixe 300 DH : seule la case Abonné oui/non est saisie. Aperçu de la répartition.
function transportApercu(selId, tarifId, apercuId, mId, cId) {
    var el = document.getElementById(apercuId); if (!el) return;
    var sel = document.getElementById(selId), tarif = document.getElementById(tarifId);
    if (!sel || sel.value !== 'oui' || !tarif || tarif.value === 'legacy') { el.style.display = 'none'; return; }
    var M = parseFloat(document.getElementById(mId).value) || 0, T = 300;
    var cRaw = document.getElementById(cId).value, c = parseFloat(cRaw), txt;
    var fmt = function (x) { return (Math.round(x * 100) / 100).toLocaleString('fr-FR'); };
    if (tarif.value === 'supplement') {
        if (cRaw === '' || isNaN(c) || c >= M) { txt = 'Scolarité ' + fmt(M) + ' + Transport ' + fmt(T) + ' = ' + fmt(M + T) + ' MAD (sans réduction)'; }
        else { txt = 'Scolarité ' + fmt(c) + ' + Transport ' + fmt(T - 100) + ' (300 − 100 de réduction) = ' + fmt(c + T - 100) + ' MAD'; }
    } else {
        if (cRaw === '' || isNaN(c) || c >= M + T) { txt = 'Scolarité ' + fmt(M) + ' + Transport ' + fmt(T) + ' = ' + fmt(M + T) + ' MAD (sans réduction)'; }
        else {
            var D = M + T - c, tr = Math.min(D, 200), sr = Math.min(D - tr, M);
            txt = 'Scolarité ' + fmt(M - sr) + ' (−' + fmt(sr) + ') + Transport ' + fmt(T - tr) + ' (−' + fmt(tr) + ') = ' + fmt(M + T - D) + ' MAD';
        }
    }
    el.textContent = '🧾 ' + txt; el.style.display = 'block';
}
function transportRegleMaj(selId, divId, tarifId, choixId, apercuId, mId, cId) {
    var sel = document.getElementById(selId); if (!sel) return;
    var oui = (sel.value === 'oui');
    var div = document.getElementById(divId), tarif = document.getElementById(tarifId), choix = document.getElementById(choixId);
    var origOui = (sel.getAttribute('data-orig') === 'oui');
    if (div) div.style.display = oui ? 'block' : 'none';
    if (tarif) {
        if (!oui) { tarif.value = 'inclus'; }
        else if (!origOui) { var r = choix ? choix.querySelector('input[type=radio]:checked') : null; tarif.value = r ? r.value : 'inclus'; }
        else { tarif.value = sel.getAttribute('data-tarif') || 'legacy'; }
    }
    if (choix) choix.style.display = (oui && !origOui) ? 'block' : 'none';
    transportApercu(selId, tarifId, apercuId, mId, cId);
}
document.addEventListener('input', function () { transportApercu('page_add_transport', 'add_page_tarif', 'add_page_apercu', 'add_page_mensualite', 'add_page_convenu'); });

// 🆕 Recherche dans la liste des parents (choix d'un parent déjà existant)
function addEleveFilterParents(){
    var input = document.getElementById('addEleveParentSearch');
    var select = document.getElementById('addEleveParentSelect');
    if (!input || !select) return;
    var q = input.value.toLowerCase();
    Array.prototype.forEach.call(select.options, function(opt){
        if (!opt.value) { opt.hidden = false; return; } // garde toujours "Sélectionner..."
        opt.hidden = opt.textContent.toLowerCase().indexOf(q) === -1;
    });
    if (select.selectedOptions.length && select.selectedOptions[0].hidden) select.value = '';
}

// 🆕 Bascule entre "Nouveau parent" (crée un compte parent + assigne l'élève) et
// "Parent déjà existant" (fratrie : on choisit un parent déjà créé dans la liste).
function setParentMode(mode) {
    document.getElementById('parent_mode').value = mode;

    document.querySelectorAll('#parent-mode-segment .lux-role-option').forEach(function(opt) {
        var isActive = opt.getAttribute('data-mode') === mode;
        opt.classList.toggle('active', isActive);
        opt.style.background = isActive ? 'var(--blue)' : 'transparent';
        opt.style.color = isActive ? '#fff' : 'inherit';
        opt.style.borderColor = isActive ? 'var(--blue)' : 'var(--gray-200)';
    });

    var divNouveau = document.getElementById('parent-nouveau-fields');
    var divExistant = document.getElementById('parent-existant-fields');
    var champsNouveau = divNouveau.querySelectorAll('input[name^="nouveau_parent_"]');

    if (mode === 'nouveau') {
        divNouveau.style.display = 'block';
        divExistant.style.display = 'none';
        champsNouveau.forEach(function(inp) {
            if (inp.name === 'nouveau_parent_nom' || inp.name === 'nouveau_parent_prenom' ||
                inp.name === 'nouveau_parent_email' || inp.name === 'nouveau_parent_password') {
                inp.required = true;
            }
        });
    } else {
        divNouveau.style.display = 'none';
        divExistant.style.display = 'block';
        champsNouveau.forEach(function(inp) { inp.required = false; });
    }
}
document.addEventListener('DOMContentLoaded', function() { setParentMode('nouveau'); });
</script>
</body></html>"""
NOTES_HUB_HTML = """<!DOCTYPE html><html><head><title>Choix du Cycle - Notes</title>""" + BASE_CSS + MACOS_CSS + """</head><body class="page-cyclehub"><div class="layout">
{{ nav_html|safe }}
<script>document.getElementById('page-title').textContent='Gestion des Notes';</script>
<div class="container" style="padding-top: 20px;">
  <h2 style="font-size:1.6rem; font-weight:700; margin-bottom:10px; color:var(--gray-900);">📝 Saisie & Analyse des Notes</h2>
  <p class="text-muted mb-20">Sélectionnez le cycle d'enseignement pour gérer les évaluations et les bulletins.</p>

  <div class="grid-3" style="gap: 30px; margin-top: 30px;">
    {% for c in nav_cycles %}
    <a href="?cycle={{ c.nom }}" class="zoom-card" style="display:flex; flex-direction:column; align-items:center; justify-content:center; text-decoration:none; padding:20px; background:transparent; cursor:pointer;">
      <div style="display:flex; justify-content:center; margin-bottom:15px;">{{ cycle_icon_html(c, '180px', '6px') }}</div>
      <h3 style="color:var(--gray-900); font-size:1.4rem;">{{ c.nom }}</h3>
      <span class="badge" style="margin-top:10px; background:var(--{{ c.couleur }}-light, var(--gray-100)); color:var(--{{ c.couleur }});">Notes {{ c.nom }}</span>
    </a>
    {% else %}
    {% if session.role == 'enseignant' %}<div class="card" style="grid-column:1/-1; text-align:center; padding:30px;"><p class="text-muted">Vous n'êtes assigné à aucune classe pour le moment. Rapprochez-vous de l'administration.</p></div>{% endif %}
    {% endfor %}
  </div>
</div>
</div></div></body></html>"""

NOTES_HTML = """<!DOCTYPE html><html><head><title>Gestion des Notes</title>""" + BASE_CSS + MACOS_CSS + BADGE_PROFIL_CSS + """
<style>
/* ═══════════════ Grille "une carte carrée par élève" — page Notes ═══════════════ */
.notes-eleve-grid{ display:grid; grid-template-columns:repeat(auto-fill,minmax(280px,1fr)); gap:18px; margin-top:4px; }
/* 🆕 Barre de recherche d'élève — au-dessus des cartes de notes */
.notes-search-bar{
  display:flex; align-items:center; gap:10px; background:var(--surface); border:1px solid var(--lux-line);
  border-radius:14px; padding:12px 16px; box-shadow:var(--shadow);
}
.notes-search-icon{ font-size:1rem; opacity:.6; flex-shrink:0; }
.notes-search-bar input{
  flex:1; border:none; outline:none; background:transparent; font-size:.92rem; color:var(--gray-900);
  min-width:0;
}
.notes-search-bar input::placeholder{ color:var(--gray-500); }
.notes-search-bar:focus-within{ border-color:var(--blue-mid); box-shadow:0 0 0 3px rgba(10,132,255,.12); }
.notes-eleve-card{
  background:rgba(255,255,255,.9); border:1px solid var(--lux-line); border-radius:18px; box-shadow:var(--shadow);
  display:flex; flex-direction:column; overflow:hidden; transition:box-shadow .2s ease, transform .2s ease;
  animation:clsRiseNotes .4s cubic-bezier(.2,.8,.2,1) both;
}
@keyframes clsRiseNotes{ from{ opacity:0; transform:translateY(10px); } to{ opacity:1; transform:none; } }
.notes-eleve-card:hover{ box-shadow:var(--shadow-lg); transform:translateY(-2px); }
.notes-eleve-head{ display:flex; align-items:center; gap:12px; padding:14px 16px; border-bottom:1px solid rgba(0,0,0,.06); background:rgba(120,120,128,.03); }
.notes-eleve-avatar{ width:42px;height:42px;border-radius:50%;flex-shrink:0;display:flex;align-items:center;justify-content:center;font-size:.95rem;font-weight:700;color:#fff;background:linear-gradient(160deg,var(--blue-mid),var(--blue));box-shadow:inset 0 1px 0 rgba(255,255,255,.3),0 3px 8px rgba(0,0,0,.15); }
.notes-eleve-titlewrap{ min-width:0; }
.notes-eleve-name{ font-weight:700; font-size:.92rem; color:var(--gray-900); letter-spacing:-.01em; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.notes-eleve-sub{ font-size:.71rem; color:var(--gray-500); margin-top:1px; }
.notes-eleve-avg{ margin-left:auto; text-align:right; flex-shrink:0; }
.notes-eleve-avg .v{ font-weight:800; font-size:1.05rem; letter-spacing:-.02em; }
.notes-eleve-avg .v.high{ color:#15803d; } .notes-eleve-avg .v.mid{ color:#92400e; } .notes-eleve-avg .v.low{ color:#991b1b; }
.notes-eleve-avg .l{ font-size:.58rem; color:var(--gray-500); text-transform:uppercase; letter-spacing:.04em; }
.notes-eleve-body{ padding:12px 14px; flex:1; display:flex; flex-direction:column; gap:7px; }
.notes-row{ display:flex; align-items:center; justify-content:space-between; gap:8px; background:rgba(120,120,128,.05); border:1px solid rgba(0,0,0,.05); border-radius:11px; padding:8px 10px; font-size:.79rem; }
.notes-row-info{ min-width:0; overflow:hidden; }
.notes-row-info strong{ color:var(--gray-900); }
.notes-row-info .t{ color:var(--gray-500); font-size:.68rem; margin-left:4px; white-space:nowrap; }
.notes-row-info .modif{ display:block; font-size:.65rem; color:var(--amber); margin-top:1px; }
.notes-row-right{ display:flex; align-items:center; gap:6px; flex-shrink:0; }
.notes-row-actions{ display:flex; gap:2px; }
.notes-row-actions button{ background:none; border:none; cursor:pointer; font-size:.78rem; padding:2px; line-height:1; color:var(--gray-500); }
.notes-row-actions button.ed:hover{ color:var(--amber); }
.notes-row-actions button.de:hover{ color:var(--red); }
.notes-empty-card{ padding:22px 14px; text-align:center; color:var(--gray-400); font-size:.8rem; flex:1; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:4px; }
.notes-empty-card .big{ font-size:1.5rem; opacity:.55; }
/* 🆕 Filtre Trimestre 1 / Trimestre 2 par carte élève */
.notes-tri-toggle{ display:flex; gap:4px; padding:0 14px 10px; }
.notes-tri-toggle button{
  flex:1; border:1px solid rgba(0,0,0,.08); background:rgba(120,120,128,.06); color:var(--gray-600);
  font-size:.68rem; font-weight:700; padding:5px 0; border-radius:8px; cursor:pointer; transition:all .15s ease;
}
.notes-tri-toggle button.active{ background:var(--blue-mid); border-color:var(--blue-mid); color:#fff; }
.notes-row.tri-hidden{ display:none !important; }
/* 🆕 Mini-graphiques dans le hero (répartition des profils + évolution moyenne classe) */
.lux-charts-row{ display:grid; grid-template-columns:1fr 1fr; gap:16px; margin-top:18px; position:relative; z-index:1; }
@media(max-width:720px){ .lux-charts-row{ grid-template-columns:1fr; } }
.lux-chart-card{ background:rgba(255,255,255,.06); border:1px solid rgba(255,255,255,.1); border-radius:14px; padding:14px 16px; }
.lux-chart-card .lux-chart-title{ font-size:.72rem; font-weight:700; text-transform:uppercase; letter-spacing:.05em; color:rgba(255,255,255,.6); margin-bottom:8px; display:flex; align-items:center; justify-content:space-between; gap:8px; }
.lux-chart-card .lux-chart-canvas-wrap{ position:relative; height:130px; }
.lux-trend-tag{ font-size:.72rem; font-weight:700; padding:2px 9px; border-radius:999px; }
.lux-trend-tag.up{ background:rgba(48,209,88,.18); color:#30D158; }
.lux-trend-tag.down{ background:rgba(255,69,58,.18); color:#FF6961; }
.lux-trend-tag.flat{ background:rgba(255,255,255,.1); color:rgba(255,255,255,.7); }

/* 🆕 Mobile uniquement (page Notes) : les 3 pastilles stats (Notes saisies / Moyenne
   générale / Notes modifiées) deviennent des cartes carrées, toutes les 3 sur la même
   ligne. Les 2 cartes graphiques (Répartition des profils / Moyenne de classe) passent
   en slider — on glisse pour voir l'autre. */
.lux-charts-mobile-wrap{ position:relative; }
.lux-charts-arrow-hint{ display:none; }
@media(max-width:900px){
  /* Spécificité renforcée (.lux-hero.page-notes-hero .lux-stats) pour l'emporter sur la
     règle générique [class*="-stats"] du CSS de base qui forçait un retour à la ligne
     flex-wrap et empêchait les 3 cartes de tenir sur la même ligne. */
  .lux-hero.page-notes-hero .lux-stats{
    display:grid !important; grid-template-columns:repeat(3,1fr) !important; gap:8px !important;
    flex-wrap:nowrap !important;
  }
  .lux-hero.page-notes-hero .lux-stat-pill{
    flex:none !important; width:auto !important; min-width:0 !important; aspect-ratio:1/1;
    display:flex !important; flex-direction:column !important; align-items:center !important; justify-content:center !important;
    text-align:center; gap:4px !important; padding:10px 6px !important;
  }
  .lux-hero.page-notes-hero .lux-stat-pill .dot{ display:none; }
  .lux-hero.page-notes-hero .lux-stat-pill .num{ font-size:1.15rem !important; line-height:1.1; }
  .lux-hero.page-notes-hero .lux-stat-pill .lbl{ font-size:.66rem !important; line-height:1.2; }

  .lux-charts-row{
    display:flex !important; flex-wrap:nowrap !important; overflow-x:auto; scroll-snap-type:x mandatory;
    -webkit-overflow-scrolling:touch; scrollbar-width:none; gap:0 !important; margin-top:16px;
  }
  .lux-charts-row::-webkit-scrollbar{ display:none; }
  .lux-charts-row .lux-chart-card{
    flex:0 0 90%; scroll-snap-align:center; margin-right:12px;
  }
  .lux-charts-arrow-hint{
    display:flex; align-items:center; justify-content:center;
    position:absolute; right:2px; top:50%; transform:translateY(-50%);
    width:30px; height:30px; border-radius:50%;
    background:linear-gradient(135deg,var(--blue-mid,#0A84FF),#0060DF);
    color:#fff; font-size:1.1rem; font-weight:800; line-height:1;
    box-shadow:0 3px 10px rgba(10,132,255,.4);
    pointer-events:none; z-index:5;
    animation: luxChartsArrowPulse 1.6s ease-in-out infinite;
  }
  @keyframes luxChartsArrowPulse{
    0%,100%{ transform:translateY(-50%) translateX(0); opacity:.85; }
    50%{ transform:translateY(-50%) translateX(5px); opacity:1; }
  }
}

/* 🆕 Lien cliquable sur l'en-tête de la carte élève (avatar + nom) → ouvre le dossier élève */
.notes-eleve-link{ display:flex; align-items:center; gap:12px; min-width:0; flex:1; text-decoration:none; color:inherit; cursor:pointer; }
.notes-eleve-link:hover .notes-eleve-name{ color:var(--blue-mid); text-decoration:underline; }
.notes-eleve-trend{ font-size:.63rem; font-weight:700; margin-top:2px; display:inline-flex; align-items:center; gap:2px; }
.notes-eleve-trend.up{ color:#15803d; } .notes-eleve-trend.down{ color:#991b1b; } .notes-eleve-trend.flat{ color:var(--gray-500); }
</style>
</head><body{% if session.role == 'enseignant' %} class="nm-teacher"{% endif %}><div class="layout">
{{ nav_html|safe }}
<script>document.getElementById('page-title').textContent="Gestion des Notes";</script>

<div class="container">

{% if session.role == 'enseignant' and notes_mobile_json %}
<style>
/* ═══ 🆕 GESTION DES NOTES — version MOBILE ENSEIGNANT uniquement (≤900px). Le bureau reste inchangé. ═══ */
.nm-only{ display:none; }
@media(max-width:900px){
  body.nm-teacher .nm-desk{ display:none !important; }
  body.nm-teacher .nm-only{ display:block; }
}
.nm-root{ --nm-s:var(--surface,#fff); --nm-t:var(--gray-900,#0f172a); --nm-soft:var(--gray-500,#64748b); --nm-line:rgba(15,23,42,.08); --nm-chip:rgba(100,116,139,.12); color:var(--nm-t); padding-bottom:120px; }
html.theme-neon .nm-root{ --nm-s:rgba(20,20,36,.92); --nm-t:#ECECF6; --nm-soft:#9A9AB5; --nm-line:rgba(255,255,255,.1); --nm-chip:rgba(255,255,255,.08); }
.nm-root, .nm-root *{ -webkit-tap-highlight-color:transparent; }
.nm-root a{ color:inherit; text-decoration:none; }
.nm-root button{ font-family:inherit; }

.nm-head{ border-radius:26px; padding:16px; color:#fff; position:relative; overflow:hidden;
  background:radial-gradient(110% 90% at 100% 0%,rgba(168,85,247,.8) 0%,transparent 55%),linear-gradient(135deg,#0b1f4d 0%,#1d4ed8 65%,#0ea5e9 130%); box-shadow:0 22px 38px -24px rgba(29,78,216,.8); }
.nm-head-r{ display:flex; align-items:center; gap:12px; }
.nm-ib{ width:40px; height:40px; border-radius:14px; background:rgba(255,255,255,.18); border:1px solid rgba(255,255,255,.28); color:#fff; display:flex; align-items:center; justify-content:center; font-size:1.2rem; font-weight:800; cursor:pointer; flex-shrink:0; }
.nm-head-t{ flex:1; min-width:0; }
.nm-title{ font-size:1.25rem; font-weight:800; letter-spacing:-.03em; line-height:1.15; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.nm-sub{ font-size:.74rem; font-weight:600; opacity:.85; margin-top:2px; }
.nm-kp{ display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:8px; margin-top:14px; }
.nm-kpi{ background:rgba(255,255,255,.14); border:1px solid rgba(255,255,255,.2); border-radius:16px; padding:10px 6px; text-align:center; backdrop-filter:blur(8px); }
.nm-kpi b{ display:block; font-size:1.12rem; font-weight:800; letter-spacing:-.03em; line-height:1.1; }
.nm-kpi span{ display:block; font-size:.6rem; font-weight:700; opacity:.85; margin-top:3px; text-transform:uppercase; letter-spacing:.04em; }
.nm-dist{ display:flex; height:9px; border-radius:99px; overflow:hidden; margin-top:14px; background:rgba(255,255,255,.2); }
.nm-dist i{ display:block; height:100%; cursor:pointer; transition:flex .4s ease; }
.nm-dist-l{ display:flex; flex-wrap:wrap; gap:5px; margin-top:9px; }
.nm-dl{ font-size:.62rem; font-weight:800; padding:3px 8px; border-radius:99px; background:rgba(255,255,255,.16); border:1px solid transparent; color:#fff; cursor:pointer; }
.nm-dl.on{ background:#fff; color:#0b1f4d; }

.nm-flash{ margin:12px 0 0; padding:11px 14px; border-radius:16px; font-size:.82rem; font-weight:700; display:flex; align-items:center; gap:8px; transition:opacity .4s ease; }
.nm-flash.ok{ background:rgba(34,197,94,.15); color:#15803d; border:1px solid rgba(34,197,94,.35); }
.nm-flash.err{ background:rgba(239,68,68,.13); color:#b91c1c; border:1px solid rgba(239,68,68,.35); }

.nm-tools{ position:sticky; top:60px; z-index:30; margin:12px -6px 0; padding:10px 6px 8px; background:rgba(248,250,252,.84); -webkit-backdrop-filter:blur(14px); backdrop-filter:blur(14px); border-radius:0 0 20px 20px; }
html.theme-neon .nm-tools{ background:rgba(10,10,20,.82); }
.nm-search{ display:flex; align-items:center; gap:8px; background:var(--nm-s); border:1px solid var(--nm-line); border-radius:16px; padding:0 12px; height:46px; box-shadow:0 8px 18px -14px rgba(15,23,42,.4); }
.nm-search:focus-within{ border-color:#2563eb; box-shadow:0 0 0 3px rgba(37,99,235,.15); }
.nm-search input{ flex:1; min-width:0; border:none !important; outline:none; box-shadow:none !important; background:transparent !important; padding:0 !important; height:auto !important; color:var(--nm-t); font-size:16px; font-family:inherit; }
.nm-search button{ border:none; background:var(--nm-chip); color:var(--nm-soft); width:24px; height:24px; border-radius:50%; font-size:.8rem; cursor:pointer; display:none; }
.nm-chips{ display:flex; gap:7px; overflow-x:auto; padding:8px 2px 2px; scrollbar-width:none; -webkit-overflow-scrolling:touch; }
.nm-chips::-webkit-scrollbar{ display:none; }
.nm-c{ flex:0 0 auto; border:1px solid var(--nm-line); background:var(--nm-s); color:var(--nm-t); font-size:.76rem; font-weight:700; padding:8px 13px; border-radius:99px; cursor:pointer; white-space:nowrap; }
.nm-c.on{ background:linear-gradient(135deg,#2563eb,#4f46e5); color:#fff; border-color:transparent; box-shadow:0 8px 16px -8px rgba(37,99,235,.7); }
.nm-seg{ display:grid; grid-template-columns:1fr 1fr; gap:4px; padding:4px; border-radius:16px; background:var(--nm-chip); margin-top:10px; }
.nm-seg button{ border:none; background:transparent; color:var(--nm-soft); font-weight:800; font-size:.8rem; padding:9px 0; border-radius:12px; cursor:pointer; }
.nm-seg button.on{ background:var(--nm-s); color:var(--nm-t); box-shadow:0 4px 10px -4px rgba(0,0,0,.25); }
.nm-count{ font-size:.74rem; font-weight:700; color:var(--nm-soft); margin:12px 6px 8px; }

/* Cartes élèves */
.nm-it{ background:var(--nm-s); border:1px solid var(--nm-line); border-radius:22px; margin-bottom:10px; overflow:hidden; box-shadow:0 10px 22px -18px rgba(15,23,42,.45); }
.nm-it-h{ display:flex; align-items:center; gap:12px; padding:13px 14px; width:100%; border:none; background:transparent; text-align:left; color:inherit; cursor:pointer; }
.nm-av{ width:44px; height:44px; border-radius:15px; flex-shrink:0; display:flex; align-items:center; justify-content:center; color:#fff; font-weight:800; font-size:.92rem; }
.nm-it-b{ flex:1; min-width:0; }
.nm-nm{ font-weight:800; font-size:.92rem; letter-spacing:-.01em; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.nm-meta{ font-size:.72rem; color:var(--nm-soft); margin-top:2px; font-weight:600; }
.nm-tr{ font-weight:800; }
.nm-tr.up{ color:#15803d; } .nm-tr.down{ color:#b91c1c; }
.nm-pf{ display:inline-block; margin-top:5px; font-size:.64rem; font-weight:800; padding:3px 9px; border-radius:99px; }
.nm-pf.p-critique{ background:rgba(239,68,68,.15); color:#b91c1c; } .nm-pf.p-fragile{ background:rgba(249,115,22,.17); color:#c2410c; }
.nm-pf.p-stable{ background:rgba(234,179,8,.2); color:#a16207; } .nm-pf.p-leader{ background:rgba(34,197,94,.17); color:#15803d; }
.nm-pf.p-champion{ background:rgba(59,130,246,.17); color:#1d4ed8; } .nm-pf.p-none{ background:var(--nm-chip); color:var(--nm-soft); }
.nm-avg{ min-width:54px; text-align:center; padding:8px 6px; border-radius:15px; font-weight:800; font-size:1.02rem; letter-spacing:-.02em; flex-shrink:0; line-height:1.1; }
.nm-avg small{ display:block; font-size:.54rem; font-weight:700; opacity:.7; margin-top:1px; }
.nm-avg.high{ background:rgba(34,197,94,.16); color:#15803d; } .nm-avg.mid{ background:rgba(245,158,11,.18); color:#b45309; }
.nm-avg.low{ background:rgba(239,68,68,.15); color:#b91c1c; } .nm-avg.none{ background:var(--nm-chip); color:var(--nm-soft); }
.nm-chev{ color:var(--nm-soft); font-size:.9rem; transition:transform .25s ease; flex-shrink:0; }
.nm-it.open .nm-chev{ transform:rotate(180deg); }
.nm-it-x{ display:none; padding:2px 12px 12px; }
.nm-it.open .nm-it-x{ display:block; }
.nm-n{ display:flex; align-items:center; gap:10px; padding:10px 10px; border-radius:15px; background:var(--nm-chip); margin-top:6px; }
.nm-n-b{ flex:1; min-width:0; }
.nm-n-t{ font-weight:700; font-size:.82rem; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.nm-n-s{ font-size:.68rem; color:var(--nm-soft); margin-top:2px; font-weight:600; }
.nm-v{ font-weight:800; font-size:.86rem; padding:6px 10px; border-radius:11px; flex-shrink:0; }
.nm-v.high{ background:rgba(34,197,94,.18); color:#15803d; } .nm-v.mid{ background:rgba(245,158,11,.2); color:#b45309; } .nm-v.low{ background:rgba(239,68,68,.17); color:#b91c1c; }
.nm-ib2{ width:34px; height:34px; border-radius:12px; border:none; background:var(--nm-s); color:var(--nm-t); cursor:pointer; font-size:.9rem; flex-shrink:0; box-shadow:0 2px 6px rgba(0,0,0,.12); }
.nm-add{ width:100%; margin-top:10px; padding:12px; border-radius:15px; border:1.5px dashed rgba(37,99,235,.5); background:rgba(37,99,235,.07); color:#2563eb; font-weight:800; font-size:.82rem; cursor:pointer; }
.nm-none{ text-align:center; padding:14px 8px 4px; color:var(--nm-soft); font-size:.78rem; font-weight:600; }
.nm-empty{ text-align:center; padding:40px 16px; color:var(--nm-soft); font-weight:600; font-size:.88rem; }

/* Vue matières */
.nm-mat{ background:var(--nm-s); border:1px solid var(--nm-line); border-radius:22px; padding:14px; margin-bottom:10px; width:100%; text-align:left; cursor:pointer; color:inherit; display:block; }
.nm-mat-h{ display:flex; align-items:center; justify-content:space-between; gap:8px; }
.nm-mat-n{ font-weight:800; font-size:.95rem; letter-spacing:-.01em; }
.nm-bar{ height:8px; border-radius:99px; background:var(--nm-chip); overflow:hidden; margin-top:11px; }
.nm-bar span{ display:block; height:100%; border-radius:99px; }
.nm-mat-s{ display:flex; justify-content:space-between; gap:6px; flex-wrap:wrap; font-size:.7rem; color:var(--nm-soft); font-weight:700; margin-top:8px; }

/* FAB */
.nm-fab{ position:fixed; right:72px; bottom:calc(18px + env(safe-area-inset-bottom,0px)); z-index:900; display:flex; align-items:center; gap:8px; padding:0 18px; height:54px; border-radius:20px; border:none; cursor:pointer;
  background:linear-gradient(135deg,#2563eb,#7c3aed); color:#fff; font-weight:800; font-size:.86rem; box-shadow:0 16px 30px -10px rgba(79,70,229,.8); }
.nm-fab:active{ transform:scale(.95); }
@media(min-width:641px){ .nm-fab{ right:90px; } }
body:has(.nm-sheet.on) #theme-toggle-fab{ display:none !important; }

/* Bottom sheet */
.nm-ov{ position:fixed; inset:0; z-index:1190; background:rgba(2,6,23,.55); backdrop-filter:blur(3px); opacity:0; pointer-events:none; transition:opacity .25s ease; }
.nm-ov.on{ opacity:1; pointer-events:auto; }
.nm-sheet{ position:fixed; left:0; right:0; bottom:0; z-index:1200; background:var(--nm-s); color:var(--nm-t); border-radius:28px 28px 0 0; padding:10px 16px calc(20px + env(safe-area-inset-bottom,0px)); max-height:92vh; overflow:auto; transform:translateY(105%); transition:transform .32s cubic-bezier(.2,.9,.25,1); box-shadow:0 -20px 50px -20px rgba(0,0,0,.55); overscroll-behavior:contain; }
.nm-sheet.on{ transform:none; }
.nm-grip{ width:42px; height:5px; border-radius:99px; background:var(--nm-chip); margin:0 auto 12px; }
.nm-sh-t{ font-size:1.08rem; font-weight:800; letter-spacing:-.02em; }
.nm-sh-s{ font-size:.78rem; color:var(--nm-soft); font-weight:600; margin:2px 0 12px; }
.nm-lb{ display:block; font-size:.66rem; font-weight:800; text-transform:uppercase; letter-spacing:.06em; color:var(--nm-soft); margin:14px 2px 6px; }
.nm-sheet .nm-chips{ flex-wrap:wrap; overflow:visible; padding:0; }
.nm-tri{ display:grid; grid-template-columns:1fr 1fr; gap:6px; }
.nm-tri button{ padding:11px 0; border-radius:14px; border:1px solid var(--nm-line); background:var(--nm-chip); color:var(--nm-t); font-weight:800; cursor:pointer; }
.nm-tri button.on{ background:linear-gradient(135deg,#2563eb,#4f46e5); color:#fff; border-color:transparent; }
.nm-score{ display:flex; align-items:center; gap:10px; }
.nm-score input{ flex:1; min-width:0; text-align:center; font-size:2.1rem; font-weight:800; letter-spacing:-.03em; border:2px solid var(--nm-line); background:var(--nm-chip); color:var(--nm-t); border-radius:20px; height:68px; outline:none; font-family:inherit; }
.nm-score input:focus{ border-color:#2563eb; box-shadow:0 0 0 4px rgba(37,99,235,.15); }
.nm-step{ width:52px; height:52px; border-radius:17px; border:none; background:var(--nm-chip); color:var(--nm-t); font-size:1.5rem; font-weight:800; cursor:pointer; flex-shrink:0; }
.nm-step:active{ transform:scale(.92); }
.nm-quick{ display:grid; grid-template-columns:repeat(5,1fr); gap:6px; margin-top:10px; }
.nm-quick button{ padding:10px 0; border-radius:13px; border:1px solid var(--nm-line); background:var(--nm-s); color:var(--nm-t); font-weight:800; font-size:.84rem; cursor:pointer; }
.nm-quick button:active{ background:rgba(37,99,235,.15); }
.nm-abc{ display:grid; grid-template-columns:repeat(3,1fr); gap:8px; }
.nm-abc button{ padding:16px 0; border-radius:18px; border:2px solid var(--nm-line); background:var(--nm-chip); color:var(--nm-t); font-weight:800; font-size:1.5rem; cursor:pointer; line-height:1; }
.nm-abc button small{ display:block; font-size:.66rem; font-weight:700; margin-top:5px; opacity:.8; }
.nm-abc button.on.A{ background:rgba(34,197,94,.2); border-color:#22c55e; color:#15803d; }
.nm-abc button.on.B{ background:rgba(245,158,11,.22); border-color:#f59e0b; color:#b45309; }
.nm-abc button.on.C{ background:rgba(239,68,68,.18); border-color:#ef4444; color:#b91c1c; }
.nm-txt{ width:100%; border:2px solid var(--nm-line); background:var(--nm-chip); color:var(--nm-t); border-radius:16px; padding:13px 14px; font-size:16px; font-family:inherit; outline:none; }
.nm-txt:focus{ border-color:#2563eb; }
.nm-warn{ margin-top:12px; padding:11px 13px; border-radius:15px; background:rgba(245,158,11,.15); color:#b45309; font-size:.76rem; font-weight:700; line-height:1.4; }
.nm-acts{ display:grid; gap:8px; margin-top:16px; }
.nm-bt{ width:100%; padding:15px; border-radius:17px; border:none; font-weight:800; font-size:.92rem; cursor:pointer; }
.nm-bt.pri{ background:linear-gradient(135deg,#2563eb,#4f46e5); color:#fff; box-shadow:0 12px 22px -12px rgba(37,99,235,.8); }
.nm-bt.sec{ background:var(--nm-chip); color:var(--nm-t); }
.nm-bt[disabled]{ opacity:.6; }
.nm-bl{ display:flex; align-items:center; gap:10px; padding:9px 10px; border-radius:15px; background:var(--nm-chip); margin-top:6px; }
.nm-bl-n{ flex:1; min-width:0; font-weight:700; font-size:.84rem; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.nm-bl-n small{ display:block; font-size:.66rem; color:var(--nm-soft); font-weight:600; }
.nm-bl input{ width:84px; text-align:center; font-size:1.05rem; font-weight:800; border:2px solid var(--nm-line); background:var(--nm-s); color:var(--nm-t); border-radius:13px; height:44px; outline:none; font-family:inherit; }
.nm-bl input:focus{ border-color:#2563eb; }
.nm-bl select{ width:84px; height:44px; border-radius:13px; border:2px solid var(--nm-line); background:var(--nm-s); color:var(--nm-t); font-weight:800; font-size:1rem; text-align:center; font-family:inherit; }
.nm-prog{ margin-top:12px; height:8px; border-radius:99px; background:var(--nm-chip); overflow:hidden; display:none; }
.nm-prog span{ display:block; height:100%; width:0; background:linear-gradient(90deg,#2563eb,#22d3ee); transition:width .2s ease; }
.nm-link{ display:flex; align-items:center; gap:12px; padding:14px; border-radius:17px; background:var(--nm-chip); margin-top:8px; font-weight:700; font-size:.88rem; }
.nm-toast{ position:fixed; left:50%; bottom:calc(86px + env(safe-area-inset-bottom,0px)); transform:translate(-50%,20px); z-index:1300; background:#0f172a; color:#fff; font-weight:700; font-size:.8rem; padding:11px 16px; border-radius:99px; opacity:0; pointer-events:none; transition:all .3s ease; max-width:88vw; text-align:center; }
.nm-toast.on{ opacity:1; transform:translate(-50%,0); }
@media(prefers-reduced-motion:reduce){ .nm-sheet,.nm-ov,.nm-dist i,.nm-chev{ transition:none; } }
</style>

<div class="nm-only nm-root" id="nmRoot">
  {% set _fl = get_flashed_messages(with_categories=true) %}
  {% for cat,msg in _fl|unique %}
  <div class="nm-flash {{ 'ok' if cat == 'success' else 'err' }}" data-nm-flash>{{ '✅' if cat == 'success' else '⚠️' }} <span>{{ msg }}{% set _k = _fl|select('equalto', (cat,msg))|list|length %}{% if _k > 1 %} (×{{ _k }}){% endif %}</span></div>
  {% endfor %}

  <div class="nm-head">
    <div class="nm-head-r">
      <a class="nm-ib" href="/notes?cycle={{ cycle|urlencode }}" aria-label="Changer de classe">‹</a>
      <div class="nm-head-t">
        <div class="nm-title" id="nmTitle">Notes</div>
        <div class="nm-sub">Section {{ cycle }} · Gestion des notes</div>
      </div>
      <button type="button" class="nm-ib" id="nmMenuBtn" aria-label="Plus d'options">⋯</button>
    </div>
    <div class="nm-kp" id="nmStats"></div>
    <div class="nm-dist" id="nmDist"></div>
    <div class="nm-dist-l" id="nmDistL"></div>
  </div>

  <div class="nm-tools">
    <div class="nm-search"><span>🔎</span><input type="text" id="nmSearch" placeholder="Rechercher un élève…" autocomplete="off" enterkeyhint="search"><button type="button" id="nmClear" aria-label="Effacer">✕</button></div>
    <div class="nm-chips" id="nmTri"></div>
    <div class="nm-chips" id="nmMat"></div>
    <div class="nm-chips" id="nmSort"></div>
    <div class="nm-seg"><button type="button" id="nmVE" class="on">👥 Élèves</button><button type="button" id="nmVM">📚 Matières</button></div>
  </div>

  <div class="nm-count" id="nmCount"></div>
  <div id="nmList"></div>

  <button type="button" class="nm-fab" id="nmFab"><span>⚡</span> Saisie en série</button>
  <div class="nm-ov" id="nmOv"></div>
  <div class="nm-sheet" id="nmSheet" role="dialog" aria-modal="true"><div class="nm-grip"></div><div id="nmSheetBody"></div></div>
  <div class="nm-toast" id="nmToast"></div>
</div>

<script>
(function(){
  var NM = {{ notes_mobile_json|safe }};
  var SYS = NM.systeme || (NM.cycle === 'Maternelle' ? 'lettres' : '20'); var MAT = SYS === 'lettres'; var DIV = SYS === '10' ? 2 : 1; var MX = 20 / DIV;
  var st = { q: '', tri: 'tous', mat: '', sort: 'az', view: 'eleves', profil: '', open: {} };
  var order = [];
  var $ = function(id){ return document.getElementById(id); };

  function esc(s){ return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;'); }
  function norm(s){ return String(s || '').toLowerCase().normalize('NFD').split('').filter(function(ch){ var c = ch.charCodeAt(0); return c < 768 || c > 879; }).join(''); }
  function r2(x){ return Math.round(x * 100) / 100; }
  function lettre(v){ return v >= 13 ? 'A' : (v >= 7 ? 'B' : 'C'); }
  function lib(l){ return l === 'A' ? 'Bon' : (l === 'B' ? 'Moyen' : 'Bas'); }
  function tone(v){ if (v == null) return 'none'; if (MAT) { var l = lettre(v); return l === 'A' ? 'high' : (l === 'B' ? 'mid' : 'low'); } return v >= 14 ? 'high' : (v >= 10 ? 'mid' : 'low'); }
  function fmt(v){ return v == null ? '—' : (MAT ? lettre(v) : String(r2(v / DIV))); }
  function avg(list){ if (!list.length) return null; var s = 0; list.forEach(function(n){ s += n.v; }); return s / list.length; }
  function profil(v){
    if (v == null) return { k: 'none', l: 'Pas de notes', e: '' };
    if (MAT){ var l = lettre(v); return l === 'A' ? { k: 'leader', l: 'Bon', e: '🟢' } : (l === 'B' ? { k: 'stable', l: 'Moyen', e: '🟡' } : { k: 'critique', l: 'Bas', e: '🔴' }); }
    if (v < 4) return { k: 'critique', l: 'Critique', e: '🔴' };
    if (v < 8) return { k: 'fragile', l: 'Fragile', e: '🟠' };
    if (v < 12) return { k: 'stable', l: 'Stable', e: '🟡' };
    if (v < 16) return { k: 'leader', l: 'Leader', e: '🟢' };
    return { k: 'champion', l: 'Champion', e: '🏆' };
  }
  var PCOL = { critique: '#FF453A', fragile: '#FF9F0A', stable: '#FFD60A', leader: '#30D158', champion: '#0A84FF' };
  var PLAB = { critique: 'Critique', fragile: 'Fragile', stable: 'Stable', leader: 'Leader', champion: 'Champion' };
  var GRAD = ['#2563eb,#06b6d4', '#7c3aed,#db2777', '#059669,#84cc16', '#f59e0b,#ea580c', '#0ea5e9,#6366f1', '#e11d48,#f97316'];
  function grad(id){ return 'linear-gradient(135deg,' + GRAD[Math.abs(parseInt(id, 10) || 0) % GRAD.length] + ')'; }
  function matName(id){ for (var i = 0; i < NM.mat.length; i++) if (String(NM.mat[i].id) === String(id)) return NM.mat[i].nom; return ''; }
  function eleveById(id){ for (var i = 0; i < NM.eleves.length; i++) if (String(NM.eleves[i].id) === String(id)) return NM.eleves[i]; return null; }
  function notesF(e){ return e.notes.filter(function(n){ return (st.tri === 'tous' || String(n.t) === st.tri) && (!st.mat || String(n.mid) === st.mat); }); }

  function toast(t){ var el = $('nmToast'); el.textContent = t; el.classList.add('on'); clearTimeout(toast._t); toast._t = setTimeout(function(){ el.classList.remove('on'); }, 2600); }

  /* ── En-tête : stats + répartition ── */
  function renderHead(){
    $('nmTitle').textContent = NM.classe || 'Notes';
    var all = []; var nbMod = 0; var notes = 0; var notes_eleves = 0;
    NM.eleves.forEach(function(e){ if (e.notes.length) notes_eleves++; e.notes.forEach(function(n){ all.push(n); notes++; if (n.mod) nbMod++; }); });
    var m = avg(all);
    $('nmStats').innerHTML =
      '<div class="nm-kpi"><b>' + NM.eleves.length + '</b><span>Élèves</span></div>' +
      '<div class="nm-kpi"><b>' + notes + '</b><span>Notes</span></div>' +
      '<div class="nm-kpi"><b>' + (m == null ? '—' : (MAT ? lettre(m) : r2(m))) + '</b><span>Moyenne</span></div>' +
      '<div class="nm-kpi"><b>' + (NM.eleves.length - notes_eleves) + '</b><span>Sans note</span></div>';
    var counts = { critique: 0, fragile: 0, stable: 0, leader: 0, champion: 0 }; var tot = 0;
    NM.eleves.forEach(function(e){ var mm = avg(e.notes); if (mm != null){ var p = profil(mm).k; counts[p]++; tot++; } });
    var d = '', l = '';
    Object.keys(counts).forEach(function(k){
      if (!counts[k]) return;
      d += '<i data-p="' + k + '" style="flex:' + counts[k] + ';background:' + PCOL[k] + '"></i>';
      l += '<button type="button" class="nm-dl' + (st.profil === k ? ' on' : '') + '" data-p="' + k + '">' + PLAB[k] + ' · ' + counts[k] + '</button>';
    });
    $('nmDist').innerHTML = d; $('nmDist').style.display = tot ? 'flex' : 'none';
    $('nmDistL').innerHTML = l;
  }

  /* ── Filtres ── */
  function chip(label, on, attr){ return '<button type="button" class="nm-c' + (on ? ' on' : '') + '" ' + attr + '>' + esc(label) + '</button>'; }
  function renderTools(){
    $('nmTri').innerHTML = chip('Toute l\u2019année', st.tri === 'tous', 'data-tri="tous"') + chip('Trimestre 1', st.tri === '1', 'data-tri="1"') + chip('Trimestre 2', st.tri === '2', 'data-tri="2"');
    var h = chip('Toutes matières', !st.mat, 'data-mat=""');
    NM.mat.forEach(function(m){ h += chip(m.nom, String(st.mat) === String(m.id), 'data-mat="' + m.id + '"'); });
    $('nmMat').innerHTML = h;
    $('nmSort').innerHTML = chip('A → Z', st.sort === 'az', 'data-sort="az"') + chip('Meilleurs d\u2019abord', st.sort === 'hi', 'data-sort="hi"') + chip('Plus fragiles d\u2019abord', st.sort === 'lo', 'data-sort="lo"') + chip('Sans note d\u2019abord', st.sort === 'new', 'data-sort="new"');
    $('nmVE').classList.toggle('on', st.view === 'eleves'); $('nmVM').classList.toggle('on', st.view === 'matieres');
    var dis = st.view === 'matieres'; $('nmMat').style.display = dis ? 'none' : 'flex'; $('nmSort').style.display = dis ? 'none' : 'flex';
  }

  /* ── Liste des élèves ── */
  function renderList(){
    if (st.view === 'matieres') return renderMatieres();
    var q = norm(st.q); var rows = [];
    NM.eleves.forEach(function(e){
      if (q && norm(e.p + ' ' + e.n).indexOf(q) === -1 && norm(e.n + ' ' + e.p).indexOf(q) === -1) return;
      var nf = notesF(e); var m = avg(nf);
      if (st.profil && profil(avg(e.notes)).k !== st.profil) return;
      rows.push({ e: e, nf: nf, m: m });
    });
    rows.sort(function(a, b){
      if (st.sort === 'hi') return (b.m == null ? -1 : b.m) - (a.m == null ? -1 : a.m);
      if (st.sort === 'lo') return (a.m == null ? 99 : a.m) - (b.m == null ? 99 : b.m);
      if (st.sort === 'new') { var x = a.nf.length ? 1 : 0, y = b.nf.length ? 1 : 0; if (x !== y) return x - y; }
      return (a.e.n + ' ' + a.e.p).localeCompare(b.e.n + ' ' + b.e.p, 'fr');
    });
    order = rows.map(function(r){ return r.e.id; });
    $('nmCount').textContent = rows.length + ' élève' + (rows.length > 1 ? 's' : '') + (st.profil ? ' · profil ' + PLAB[st.profil] : '') + (st.mat ? ' · ' + matName(st.mat) : '');
    if (!rows.length){ $('nmList').innerHTML = '<div class="nm-empty">🔎 Aucun élève ne correspond.</div>'; return; }
    var out = '';
    rows.forEach(function(r){
      var e = r.e, nf = r.nf, m = r.m, p = profil(m);
      var t1 = avg(e.notes.filter(function(n){ return String(n.t) === '1'; })), t2 = avg(e.notes.filter(function(n){ return String(n.t) === '2'; }));
      var trend = '';
      if (t1 != null && t2 != null && !MAT){ var dd = r2((t2 - t1) / DIV); trend = ' · <span class="nm-tr ' + (dd > 0.05 ? 'up' : (dd < -0.05 ? 'down' : '')) + '">' + (dd > 0.05 ? '↗' : (dd < -0.05 ? '↘' : '→')) + ' ' + (dd > 0 ? '+' : '') + dd + '</span>'; }
      var init = ((e.p || ' ').charAt(0) + (e.n || ' ').charAt(0)).toUpperCase();
      var isOpen = !!st.open[e.id];
      out += '<div class="nm-it' + (isOpen ? ' open' : '') + '" data-id="' + e.id + '">' +
        '<button type="button" class="nm-it-h" data-act="toggle">' +
          '<span class="nm-av" style="background:' + grad(e.id) + '">' + esc(init) + '</span>' +
          '<span class="nm-it-b"><div class="nm-nm">' + esc(e.p) + ' ' + esc(e.n) + '</div>' +
          '<div class="nm-meta">' + nf.length + ' note' + (nf.length > 1 ? 's' : '') + trend + '</div>' +
          (m != null ? '<span class="nm-pf p-' + p.k + '">' + p.e + ' ' + p.l + '</span>' : '<span class="nm-pf p-none">📭 Aucune note</span>') + '</span>' +
          '<span class="nm-avg ' + tone(m) + '">' + fmt(m) + (m != null && !MAT ? '<small>/' + MX + '</small>' : (MAT && m != null ? '<small>' + lib(lettre(m)) + '</small>' : '')) + '</span>' +
          '<span class="nm-chev">▾</span></button>' +
        '<div class="nm-it-x">';
      if (!nf.length) out += '<div class="nm-none">Aucune note pour cette sélection.</div>';
      nf.slice().sort(function(a, b){ return String(b.d).localeCompare(String(a.d)); }).forEach(function(n){
        out += '<div class="nm-n"><div class="nm-n-b"><div class="nm-n-t">' + esc(n.mat) + (n.sm ? ' · ' + esc(n.sm) + (n.ex ? ' (Examen ' + n.ex + ')' : '') : (n.ex ? ' · Examen ' + n.ex : '')) + '</div>' +
          '<div class="nm-n-s">S' + esc(n.t) + (n.d ? ' · ' + esc(n.d.split('-').reverse().join('/')) : '') + (n.mod ? ' · ✏️ modifiée' : '') + '</div></div>' +
          '<span class="nm-v ' + tone(n.v) + '">' + (MAT ? lettre(n.v) : r2(n.v / DIV) + '/' + MX) + '</span>' +
          (n.mod ? '<button type="button" class="nm-ib2" data-act="locked" data-nid="' + n.id + '" aria-label="Verrouillée">🔒</button>'
                 : '<button type="button" class="nm-ib2" data-act="edit" data-nid="' + n.id + '" aria-label="Modifier">✏️</button>') + '</div>';
      });
      out += '<button type="button" class="nm-add" data-act="add">➕ Ajouter une note pour ' + esc(e.p) + '</button></div></div>';
    });
    $('nmList').innerHTML = out;
  }

  /* ── Vue par matière ── */
  function renderMatieres(){
    $('nmCount').textContent = NM.mat.length + ' matière' + (NM.mat.length > 1 ? 's' : '') + ' · touchez pour filtrer les élèves';
    if (!NM.mat.length){ $('nmList').innerHTML = '<div class="nm-empty">📚 Aucune matière ne vous est assignée dans cette classe.</div>'; return; }
    var out = '';
    NM.mat.forEach(function(mt){
      var list = [];
      NM.eleves.forEach(function(e){ e.notes.forEach(function(n){ if (String(n.mid) === String(mt.id) && (st.tri === 'tous' || String(n.t) === st.tri)) list.push(n); }); });
      var m = avg(list); var t = tone(m);
      var ok = list.filter(function(n){ return n.v >= 10; }).length;
      var min = list.length ? Math.min.apply(null, list.map(function(n){ return n.v; })) : null;
      var max = list.length ? Math.max.apply(null, list.map(function(n){ return n.v; })) : null;
      var col = t === 'high' ? '#22c55e' : (t === 'mid' ? '#f59e0b' : (t === 'low' ? '#ef4444' : '#94a3b8'));
      out += '<button type="button" class="nm-mat" data-mid="' + mt.id + '"><div class="nm-mat-h"><div class="nm-mat-n">' + esc(mt.nom) + '</div><span class="nm-avg ' + t + '">' + fmt(m) + (m != null && !MAT ? '<small>/' + MX + '</small>' : '') + '</span></div>' +
        '<div class="nm-bar"><span style="width:' + (m == null ? 0 : Math.max(4, Math.min(100, m / 20 * 100))) + '%;background:' + col + '"></span></div>' +
        '<div class="nm-mat-s"><span>' + list.length + ' note' + (list.length > 1 ? 's' : '') + '</span>' +
        (list.length ? (MAT ? '<span>A: ' + list.filter(function(n){ return lettre(n.v) === 'A'; }).length + ' · B: ' + list.filter(function(n){ return lettre(n.v) === 'B'; }).length + ' · C: ' + list.filter(function(n){ return lettre(n.v) === 'C'; }).length + '</span>'
                              : '<span>Réussite ' + Math.round(ok / list.length * 100) + '%</span><span>Min ' + r2(min / DIV) + ' · Max ' + r2(max / DIV) + '</span>') : '<span>Aucune note saisie</span>') + '</div></button>';
    });
    $('nmList').innerHTML = out;
  }

  function renderAll(){ renderHead(); renderTools(); renderList(); }

  /* ── Bottom sheet ── */
  function openSheet(html){ $('nmSheetBody').innerHTML = html; $('nmOv').classList.add('on'); $('nmSheet').classList.add('on'); $('nmSheet').scrollTop = 0; }
  function closeSheet(){ $('nmOv').classList.remove('on'); $('nmSheet').classList.remove('on'); }
  function hid(n, v){ return '<input type="hidden" name="' + n + '" value="' + esc(v) + '">'; }
  function base(){ return hid('cycle', NM.cycle) + hid('classe_id', NM.classe_id); }
  function getPref(){ try { return JSON.parse(sessionStorage.getItem('nm_pref') || '{}'); } catch (e) { return {}; } }
  function setPref(o){ try { sessionStorage.setItem('nm_pref', JSON.stringify(o)); } catch (e) {} }

  function matChips(sel, grp){
    var h = '<div class="nm-chips" id="' + grp + '">';
    NM.mat.forEach(function(m){ h += '<button type="button" class="nm-c' + (String(sel) === String(m.id) ? ' on' : '') + '" data-pick="mat" data-v="' + m.id + '">' + esc(m.nom) + '</button>'; });
    return h + '</div>';
  }
  function smBlock(mid, sel, wrapId){
    var l = NM.sm[mid] || [];
    if (!l.length) return '<div id="' + wrapId + '" style="display:none"></div>';
    var h = '<div id="' + wrapId + '"><span class="nm-lb">Sous-matière</span><div class="nm-chips">';
    l.forEach(function(s){ h += '<button type="button" class="nm-c' + (String(sel) === String(s.id) ? ' on' : '') + '" data-pick="sm" data-v="' + s.id + '">' + esc(s.nom) + ' · coef ' + esc(s.coefficient) + '</button>'; });
    return h + '</div></div>';
  }
  function triBlock(sel){ return '<span class="nm-lb">Trimestre</span><div class="nm-tri"><button type="button" data-pick="tri" data-v="1" class="' + (String(sel) === '1' ? 'on' : '') + '">Trimestre 1</button><button type="button" data-pick="tri" data-v="2" class="' + (String(sel) === '2' ? 'on' : '') + '">Trimestre 2</button></div>'; }
  function scoreBlock(cur){
    if (MAT){
      var h = '<span class="nm-lb">Évaluation</span><div class="nm-abc">';
      ['A', 'B', 'C'].forEach(function(l){ h += '<button type="button" class="' + l + (cur === l ? ' on' : '') + '" data-pick="abc" data-v="' + l + '">' + l + '<small>' + lib(l) + '</small></button>'; });
      return h + '</div>';
    }
    return '<span class="nm-lb">Note (sur ' + MX + ')</span><div class="nm-score"><button type="button" class="nm-step" data-step="-0.25" aria-label="Moins">−</button>' +
      '<input type="text" id="nmVal" inputmode="decimal" placeholder="0 – ' + MX + '" autocomplete="off" value="' + esc(cur == null ? '' : cur) + '"><button type="button" class="nm-step" data-step="0.25" aria-label="Plus">+</button></div>' +
      '<div class="nm-quick">' + (SYS === '10' ? [0, 2, 4, 5, 6, 7, 8, 9, 10] : [0, 5, 8, 10, 12, 14, 15, 16, 18, 20]).map(function(v){ return '<button type="button" data-q="' + v + '">' + v + '</button>'; }).join('') + '</div>';
  }
  function readScore(){
    if (MAT){ var a = document.querySelector('#nmSheetBody .nm-abc button.on'); return a ? { lettre: a.getAttribute('data-v') } : null; }
    var raw = String(($('nmVal') || {}).value || '').replace(',', '.').trim();
    var v = parseFloat(raw);
    if (raw === '' || isNaN(v) || v < 0 || v > MX) return null;
    return { note: String(r2(v)) };
  }

  function openAdd(eid, pre){
    var e = eleveById(eid); if (!e) return;
    var pref = getPref(); pre = pre || {};
    var mat = pre.mat || st.mat || pref.mat || (NM.mat.length === 1 ? NM.mat[0].id : '');
    var sm = pre.sm || '';
    var tri = pre.t || (st.tri !== 'tous' ? st.tri : (pref.t || '1'));
    var html = '<form method="POST" action="/notes" id="nmAddForm">' + base() + hid('eleve_id', e.id) +
      '<input type="hidden" name="matiere_id" id="nmFMat" value="' + esc(mat) + '"><input type="hidden" name="sous_matiere_id" id="nmFSm" value="' + esc(sm) + '"><input type="hidden" name="trimestre" id="nmFTri" value="' + esc(tri) + '">' +
      (MAT ? '<input type="hidden" name="note_lettre" id="nmFLet" value="">' : '<input type="hidden" name="note" id="nmFNote" value="">') +
      '<div class="nm-sh-t">➕ Nouvelle note</div><div class="nm-sh-s">' + esc(e.p) + ' ' + esc(e.n) + '</div>' +
      '<span class="nm-lb">Matière</span>' + matChips(mat, 'nmMatC') + smBlock(mat, sm, 'nmSmW') + triBlock(tri) + scoreBlock(null) +
      '<div class="nm-acts"><button type="submit" class="nm-bt pri" data-go="save">💾 Enregistrer</button>' +
      '<button type="submit" class="nm-bt sec" data-go="next">Enregistrer et élève suivant ➜</button></div></form>';
    openSheet(html);
  }
  function openEdit(nid){
    var note = null, el = null;
    NM.eleves.forEach(function(e){ e.notes.forEach(function(n){ if (String(n.id) === String(nid)){ note = n; el = e; } }); });
    if (!note) return;
    var cur = MAT ? lettre(note.v) : String(r2(note.v / DIV));
    var html = '<form method="POST" action="/notes" id="nmEditForm">' + base() + hid('action', 'edit') + hid('note_id', note.id) +
      (MAT ? '<input type="hidden" name="note_lettre" id="nmFLet" value="' + cur + '">' : '<input type="hidden" name="note" id="nmFNote" value="">') +
      '<div class="nm-sh-t">✏️ Modifier la note</div><div class="nm-sh-s">' + esc(el.p) + ' ' + esc(el.n) + ' · ' + esc(note.mat) + (note.sm ? ' · ' + esc(note.sm) + (note.ex ? ' (Examen ' + note.ex + ')' : '') : (note.ex ? ' · Examen ' + note.ex : '')) + ' · S' + esc(note.t) + '</div>' +
      '<div class="nm-warn">⚠️ Vous ne disposez que d\u2019<b>une seule modification</b> par note. Après enregistrement, elle sera verrouillée.</div>' +
      scoreBlock(cur) +
      '<span class="nm-lb">Justification (obligatoire)</span><input type="text" class="nm-txt" name="commentaire" id="nmComm" placeholder="Ex : erreur lors de la correction…" value="' + esc(note.c) + '" autocomplete="off">' +
      '<div class="nm-acts"><button type="submit" class="nm-bt pri">💾 Enregistrer la modification</button><button type="button" class="nm-bt sec" data-close="1">Annuler</button></div></form>';
    openSheet(html);
  }
  function openMenu(){
    var q = 'cycle=' + encodeURIComponent(NM.cycle) + '&classe_id=' + encodeURIComponent(NM.classe_id);
    openSheet('<div class="nm-sh-t">Options</div><div class="nm-sh-s">' + esc(NM.classe || '') + '</div>' +
      '<a class="nm-link" href="/export/notes/excel?' + q + '">📥 Exporter en Excel</a>' +
      '<a class="nm-link" href="/export/notes/pdf?' + q + '">📄 Exporter en PDF</a>' +
      '<a class="nm-link" href="/notes?cycle=' + encodeURIComponent(NM.cycle) + '">🏫 Changer de classe</a>' +
      '<a class="nm-link" href="/notes">🗂️ Changer de cycle</a>' +
      '<a class="nm-link" href="/analyse-notes">📊 Analyse des notes</a>');
  }

  /* ── Saisie en série : une matière + un trimestre, puis une note par élève ── */
  function openBatch(){
    var pref = getPref();
    var mat = st.mat || pref.mat || (NM.mat.length === 1 ? NM.mat[0].id : '');
    var tri = st.tri !== 'tous' ? st.tri : (pref.t || '1');
    var html = '<div class="nm-sh-t">⚡ Saisie en série</div><div class="nm-sh-s">Une même évaluation pour toute la classe. Laissez vide les élèves absents.</div>' +
      '<input type="hidden" id="nmBMat" value="' + esc(mat) + '"><input type="hidden" id="nmBSm" value=""><input type="hidden" id="nmBTri" value="' + esc(tri) + '">' +
      '<span class="nm-lb">Matière</span>' + matChips(mat, 'nmBMatC') + smBlock(mat, '', 'nmBSmW') + triBlock(tri) +
      '<span class="nm-lb">Élèves</span><div id="nmBList"></div>' +
      '<div class="nm-prog" id="nmBProg"><span id="nmBBar"></span></div>' +
      '<div class="nm-acts"><button type="button" class="nm-bt pri" id="nmBGo">💾 Enregistrer toutes les notes</button><button type="button" class="nm-bt sec" data-close="1">Annuler</button></div>';
    openSheet(html); batchList();
  }
  function batchList(){
    var mat = ($('nmBMat') || {}).value, tri = ($('nmBTri') || {}).value; var h = '';
    var sorted = NM.eleves.slice().sort(function(a, b){ return (a.n + ' ' + a.p).localeCompare(b.n + ' ' + b.p, 'fr'); });
    sorted.forEach(function(e){
      var ex = e.notes.filter(function(n){ return String(n.mid) === String(mat) && String(n.t) === String(tri); });
      var hint = ex.length ? 'déjà noté : ' + ex.map(function(n){ return fmt(n.v); }).join(', ') : 'pas encore noté';
      h += '<div class="nm-bl"><div class="nm-bl-n">' + esc(e.p) + ' ' + esc(e.n) + '<small>' + esc(hint) + '</small></div>' +
        (MAT ? '<select data-b="' + e.id + '"><option value="">—</option><option>A</option><option>B</option><option>C</option></select>'
             : '<input type="text" inputmode="decimal" placeholder="/' + MX + '" data-b="' + e.id + '" autocomplete="off">') + '</div>';
    });
    $('nmBList').innerHTML = h || '<div class="nm-none">Aucun élève.</div>';
  }
  function runBatch(){
    var mat = $('nmBMat').value, sm = $('nmBSm').value, tri = $('nmBTri').value;
    if (!mat){ toast('Choisissez une matière'); return; }
    if ((NM.sm[mat] || []).length && !sm){ toast('Choisissez une sous-matière'); return; }
    var jobs = [], bad = 0;
    document.querySelectorAll('#nmBList [data-b]').forEach(function(f){
      var raw = String(f.value || '').replace(',', '.').trim(); if (!raw) return;
      if (MAT){ jobs.push({ eid: f.getAttribute('data-b'), lettre: raw }); return; }
      var v = parseFloat(raw);
      if (isNaN(v) || v < 0 || v > MX){ bad++; f.style.borderColor = '#ef4444'; return; }
      jobs.push({ eid: f.getAttribute('data-b'), note: String(r2(v)) });
    });
    if (bad){ toast(bad + ' note(s) invalide(s) (0 à ' + MX + ')'); return; }
    if (!jobs.length){ toast('Saisissez au moins une note'); return; }
    if (!confirm('Enregistrer ' + jobs.length + ' note' + (jobs.length > 1 ? 's' : '') + ' ?')) return;
    var btn = $('nmBGo'); btn.disabled = true; btn.textContent = 'Enregistrement…';
    $('nmBProg').style.display = 'block'; setPref({ mat: mat, t: tri });
    var done = 0, fail = 0;
    function next(){
      if (done + fail >= jobs.length){
        if (fail){ toast(done + ' enregistrée(s), ' + fail + ' en échec'); setTimeout(function(){ location.reload(); }, 1400); } else { location.reload(); }
        return;
      }
      var j = jobs[done + fail]; var fd = new URLSearchParams();
      fd.append('cycle', NM.cycle); fd.append('classe_id', NM.classe_id); fd.append('eleve_id', j.eid); fd.append('matiere_id', mat);
      if (sm) fd.append('sous_matiere_id', sm); fd.append('trimestre', tri);
      if (MAT) fd.append('note_lettre', j.lettre); else fd.append('note', j.note);
      fetch('/notes', { method: 'POST', body: fd, credentials: 'same-origin', redirect: 'manual', headers: { 'Content-Type': 'application/x-www-form-urlencoded' } })
        .then(function(r){ if (r.type === 'opaqueredirect' || r.ok) done++; else fail++; })
        .catch(function(){ fail++; })
        .then(function(){ $('nmBBar').style.width = Math.round((done + fail) / jobs.length * 100) + '%'; next(); });
    }
    next();
  }

  /* ── Événements (délégation) ── */
  document.addEventListener('click', function(ev){
    var t = ev.target; if (!t || !t.closest) return;
    if (!t.closest('#nmRoot')) return;
    var b;
    if ((b = t.closest('[data-tri]'))){ st.tri = b.getAttribute('data-tri'); renderAll(); return; }
    if ((b = t.closest('#nmMat [data-mat]'))){ st.mat = b.getAttribute('data-mat'); renderAll(); return; }
    if ((b = t.closest('[data-sort]'))){ st.sort = b.getAttribute('data-sort'); renderAll(); return; }
    if ((b = t.closest('.nm-dl, #nmDist i'))){ var p = b.getAttribute('data-p'); st.profil = st.profil === p ? '' : p; st.view = 'eleves'; renderAll(); return; }
    if (t.closest('#nmVE')){ st.view = 'eleves'; renderAll(); return; }
    if (t.closest('#nmVM')){ st.view = 'matieres'; renderAll(); return; }
    if ((b = t.closest('.nm-mat'))){ st.mat = b.getAttribute('data-mid'); st.view = 'eleves'; renderAll(); window.scrollTo({ top: 0, behavior: 'smooth' }); return; }
    if (t.closest('#nmMenuBtn')){ openMenu(); return; }
    if (t.closest('#nmFab')){ openBatch(); return; }
    if (t.closest('#nmOv') || t.closest('[data-close]')){ closeSheet(); return; }
    if (t.closest('#nmClear')){ $('nmSearch').value = ''; st.q = ''; $('nmClear').style.display = 'none'; renderList(); return; }
    if ((b = t.closest('[data-act]'))){
      var act = b.getAttribute('data-act'); var card = b.closest('.nm-it'); var id = card ? card.getAttribute('data-id') : null;
      if (act === 'toggle'){ st.open[id] = !st.open[id]; card.classList.toggle('open', !!st.open[id]); return; }
      if (act === 'add'){ openAdd(id); return; }
      if (act === 'edit'){ openEdit(b.getAttribute('data-nid')); return; }
      if (act === 'locked'){
        var nn = null; NM.eleves.forEach(function(e){ e.notes.forEach(function(n){ if (String(n.id) === b.getAttribute('data-nid')) nn = n; }); });
        toast('🔒 Déjà modifiée' + (nn && nn.c ? ' — ' + nn.c : '')); return;
      }
    }
    /* Dans la feuille */
    if ((b = t.closest('[data-pick]'))){
      var k = b.getAttribute('data-pick'), v = b.getAttribute('data-v');
      var grp = b.parentNode; Array.prototype.forEach.call(grp.querySelectorAll('button'), function(x){ x.classList.remove('on'); }); b.classList.add('on');
      if (k === 'mat'){
        if ($('nmFMat')){ $('nmFMat').value = v; $('nmFSm').value = ''; var w = $('nmSmW'); if (w) w.outerHTML = smBlock(v, '', 'nmSmW'); }
        if ($('nmBMat')){ $('nmBMat').value = v; $('nmBSm').value = ''; var w2 = $('nmBSmW'); if (w2) w2.outerHTML = smBlock(v, '', 'nmBSmW'); batchList(); }
      } else if (k === 'sm'){ if ($('nmFSm')) $('nmFSm').value = v; if ($('nmBSm')) $('nmBSm').value = v; }
      else if (k === 'tri'){ if ($('nmFTri')) $('nmFTri').value = v; if ($('nmBTri')){ $('nmBTri').value = v; batchList(); } }
      else if (k === 'abc'){ if ($('nmFLet')) $('nmFLet').value = v; }
      return;
    }
    if ((b = t.closest('[data-q]'))){ var inp = $('nmVal'); if (inp){ inp.value = b.getAttribute('data-q'); } return; }
    if ((b = t.closest('[data-step]'))){ var i2 = $('nmVal'); if (i2){ var c = parseFloat(String(i2.value).replace(',', '.')); if (isNaN(c)) c = 0; c = Math.max(0, Math.min(20, c + parseFloat(b.getAttribute('data-step')))); i2.value = String(r2(c)); } return; }
    if (t.closest('#nmBGo')){ runBatch(); return; }
    if ((b = t.closest('[data-go]'))){ b.form && (b.form._go = b.getAttribute('data-go')); }
  });

  $('nmSearch').addEventListener('input', function(){ st.q = this.value; $('nmClear').style.display = this.value ? 'block' : 'none'; renderList(); });
  document.addEventListener('keydown', function(e){ if (e.key === 'Escape') closeSheet(); });

  /* Validation + envoi des formulaires de la feuille */
  document.addEventListener('submit', function(ev){
    var f = ev.target; if (!f || (f.id !== 'nmAddForm' && f.id !== 'nmEditForm')) return;
    var sc = readScore();
    if (!sc){ ev.preventDefault(); toast(MAT ? 'Choisissez une évaluation (A, B ou C)' : 'Entrez une note valide entre 0 et ' + MX); return; }
    if (f.id === 'nmAddForm'){
      var mat = $('nmFMat').value;
      if (!mat){ ev.preventDefault(); toast('Choisissez une matière'); return; }
      if ((NM.sm[mat] || []).length && !$('nmFSm').value){ ev.preventDefault(); toast('Choisissez une sous-matière'); return; }
      setPref({ mat: mat, t: $('nmFTri').value });
      if (f._go === 'next'){
        var idx = order.indexOf(parseInt(f.querySelector('[name=eleve_id]').value, 10));
        if (idx === -1) idx = order.map(String).indexOf(f.querySelector('[name=eleve_id]').value);
        var nx = order[idx + 1];
        try { if (nx != null) sessionStorage.setItem('nm_next', JSON.stringify({ eid: nx, mat: mat, sm: $('nmFSm').value, t: $('nmFTri').value, cls: NM.classe_id })); } catch (e) {}
      }
    } else if (!$('nmComm').value.trim()){ ev.preventDefault(); toast('La justification est obligatoire'); return; }
    if (MAT){ $('nmFLet').value = sc.lettre; } else { $('nmFNote').value = sc.note; }
    var sb = f.querySelectorAll('button[type=submit]'); Array.prototype.forEach.call(sb, function(x){ x.disabled = true; });
  });

  /* Les messages flash disparaissent seuls */
  setTimeout(function(){ Array.prototype.forEach.call(document.querySelectorAll('[data-nm-flash]'), function(x){ x.style.opacity = '0'; setTimeout(function(){ x.style.display = 'none'; }, 450); }); }, 5000);

  renderAll();
  /* « Enregistrer et élève suivant » : réouvre directement la saisie du prochain élève */
  try {
    var nx = JSON.parse(sessionStorage.getItem('nm_next') || 'null'); sessionStorage.removeItem('nm_next');
    if (nx && String(nx.cls) === String(NM.classe_id) && window.matchMedia('(max-width:900px)').matches){
      st.open[nx.eid] = true; renderList(); openAdd(nx.eid, { mat: nx.mat, sm: nx.sm, t: nx.t });
      setTimeout(function(){ var c = document.querySelector('.nm-it[data-id="' + nx.eid + '"]'); if (c) c.scrollIntoView({ block: 'center' }); }, 60);
    }
  } catch (e) {}
})();
</script>
{% endif %}

{% if session.role in ['admin','agent_admin','enseignant'] %}
{% if notes_pro_json %}
<style>
.np{--np-s:#fff;--np-s2:#f8fafc;--np-t:#0f172a;--np-soft:#64748b;--np-line:rgba(15,23,42,.08);--np-track:rgba(100,116,139,.18);--np-p:#4f46e5;--np-p2:#0ea5e9;--np-ok:#16a34a;--np-warn:#f59e0b;--np-bad:#ef4444;--np-sh:0 1px 2px rgba(15,23,42,.05),0 10px 28px -14px rgba(15,23,42,.18);color:var(--np-t);font-family:inherit;padding-bottom:60px;position:relative}
html.theme-neon .np{--np-s:rgba(22,22,40,.9);--np-s2:rgba(255,255,255,.05);--np-t:#ececf6;--np-soft:#9a9ab5;--np-line:rgba(255,255,255,.1);--np-track:rgba(255,255,255,.12);--np-sh:0 12px 32px -16px rgba(0,0,0,.65)}
.np *{box-sizing:border-box}
.np button{font-family:inherit;cursor:pointer}
.np-hero{position:relative;overflow:hidden;border-radius:26px;padding:26px 28px 24px;color:#fff;background:linear-gradient(135deg,#312e81 0%,#4f46e5 48%,#0ea5e9 100%);box-shadow:0 20px 50px -22px rgba(79,70,229,.7);margin-bottom:18px}
.np-hero:before,.np-hero:after{content:"";position:absolute;border-radius:50%;filter:blur(2px);pointer-events:none}
.np-hero:before{width:340px;height:340px;right:-90px;top:-150px;background:radial-gradient(circle,rgba(255,255,255,.28),transparent 68%)}
.np-hero:after{width:260px;height:260px;left:30%;bottom:-170px;background:radial-gradient(circle,rgba(56,189,248,.45),transparent 70%)}
.np-hero-top{position:relative;z-index:1;display:flex;flex-wrap:wrap;gap:16px;align-items:center;justify-content:space-between}
.np-id{display:flex;gap:14px;align-items:center;min-width:0}
.np-back{width:42px;height:42px;border-radius:14px;display:flex;align-items:center;justify-content:center;background:rgba(255,255,255,.16);color:#fff;text-decoration:none;font-size:1.5rem;line-height:1;transition:.2s;backdrop-filter:blur(8px)}
.np-back:hover{background:rgba(255,255,255,.28);transform:translateX(-2px)}
.np-eyebrow{font-size:.72rem;letter-spacing:.14em;text-transform:uppercase;opacity:.8;font-weight:700}
.np-h1{margin:2px 0 0;font-size:1.65rem;font-weight:800;letter-spacing:-.02em;color:#fff}
.np-sub{font-size:.85rem;opacity:.85;margin-top:2px}
.np-actions{display:flex;flex-wrap:wrap;gap:10px;align-items:center}
.np-btn{border:0;border-radius:14px;padding:10px 16px;font-weight:700;font-size:.86rem;display:inline-flex;gap:7px;align-items:center;transition:.18s;text-decoration:none;white-space:nowrap}
.np-btn:active{transform:scale(.97)}
.np-btn-glass{background:rgba(255,255,255,.16);color:#fff;backdrop-filter:blur(10px);border:1px solid rgba(255,255,255,.22)}
.np-btn-glass:hover{background:rgba(255,255,255,.28)}
.np-btn-white{background:#fff;color:#3730a3;box-shadow:0 8px 20px -8px rgba(0,0,0,.35)}
.np-btn-white:hover{transform:translateY(-1px)}
.np-btn-p{background:linear-gradient(135deg,var(--np-p),var(--np-p2));color:#fff;box-shadow:0 10px 22px -10px rgba(79,70,229,.8)}
.np-btn-p:hover{filter:brightness(1.07);transform:translateY(-1px)}
.np-btn-p:disabled{opacity:.5;cursor:not-allowed;transform:none}
.np-btn-o{background:var(--np-s);color:var(--np-t);border:1px solid var(--np-line)}
.np-btn-o:hover{border-color:var(--np-p);color:var(--np-p)}
.np-btn-d{background:rgba(239,68,68,.1);color:#dc2626}
.np-btn-sm{padding:7px 12px;font-size:.78rem;border-radius:11px}
.np-menu{position:relative}
.np-menu-pop{position:absolute;right:0;top:calc(100% + 8px);min-width:210px;background:var(--np-s);color:var(--np-t);border:1px solid var(--np-line);border-radius:16px;box-shadow:0 24px 50px -16px rgba(15,23,42,.4);padding:6px;display:none;z-index:30}
.np-menu.open .np-menu-pop{display:block;animation:npin .16s ease-out}
.np-menu-pop a,.np-menu-pop button{display:flex;gap:10px;align-items:center;width:100%;text-align:left;border:0;background:none;color:inherit;text-decoration:none;padding:10px 12px;border-radius:11px;font-size:.84rem;font-weight:600}
.np-menu-pop a:hover,.np-menu-pop button:hover{background:var(--np-s2)}
.np-kpis{position:relative;z-index:1;display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px;margin-top:22px}
.np-kpi{background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.2);border-radius:18px;padding:14px 16px;backdrop-filter:blur(10px);animation:npup .5s both;animation-delay:calc(var(--i,0)*60ms)}
.np-kpi-l{font-size:.7rem;text-transform:uppercase;letter-spacing:.1em;opacity:.8;font-weight:700;display:flex;gap:6px;align-items:center}
.np-kpi-v{font-size:1.75rem;font-weight:800;letter-spacing:-.02em;margin-top:4px;line-height:1.1}
.np-kpi-v small{font-size:.8rem;font-weight:600;opacity:.75;margin-left:3px}
.np-kpi-s{font-size:.74rem;opacity:.85;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.np-tabs{display:inline-flex;gap:4px;padding:5px;background:var(--np-s);border:1px solid var(--np-line);border-radius:18px;box-shadow:var(--np-sh);max-width:100%;overflow-x:auto}
.np-tab{border:0;background:none;color:var(--np-soft);font-weight:700;font-size:.84rem;padding:9px 16px;border-radius:13px;white-space:nowrap;transition:.18s}
.np-tab:hover{color:var(--np-t)}
.np-tab.on{background:linear-gradient(135deg,var(--np-p),var(--np-p2));color:#fff;box-shadow:0 8px 18px -8px rgba(79,70,229,.8)}
.np-tools{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:16px 0 8px}
.np-search{flex:1 1 260px;display:flex;align-items:center;gap:8px;background:var(--np-s);border:1px solid var(--np-line);border-radius:15px;padding:0 14px;box-shadow:var(--np-sh);transition:.18s}
.np-search:focus-within{border-color:var(--np-p);box-shadow:0 0 0 4px rgba(79,70,229,.14)}
.np-search input{flex:1;border:0;outline:0;background:none;color:var(--np-t);padding:12px 0;font-size:.9rem;font-family:inherit;min-width:0}
.np-search kbd{font-size:.68rem;border:1px solid var(--np-line);border-radius:6px;padding:2px 6px;color:var(--np-soft)}
.np-chips{display:inline-flex;background:var(--np-s);border:1px solid var(--np-line);border-radius:14px;padding:3px;box-shadow:var(--np-sh)}
.np-chip{border:0;background:none;color:var(--np-soft);padding:8px 13px;border-radius:11px;font-weight:700;font-size:.8rem}
.np-chip.on{background:var(--np-t);color:var(--np-s)}
.np-sel{background:var(--np-s);color:var(--np-t);border:1px solid var(--np-line);border-radius:14px;padding:10px 12px;font-size:.84rem;font-weight:600;font-family:inherit;box-shadow:var(--np-sh);max-width:100%}
.np-sel:focus{outline:0;border-color:var(--np-p)}
.np-count{font-size:.8rem;color:var(--np-soft);margin:6px 4px 14px;display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.np-pill{display:inline-flex;gap:6px;align-items:center;background:rgba(79,70,229,.1);color:var(--np-p);border-radius:999px;padding:3px 10px;font-weight:700;font-size:.72rem}
.np-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(310px,1fr));gap:16px}
.np-card{background:var(--np-s);border:1px solid var(--np-line);border-radius:22px;padding:18px;box-shadow:var(--np-sh);transition:.22s;animation:npup .45s both;animation-delay:calc(var(--i,0)*28ms);cursor:pointer;position:relative;overflow:hidden}
.np-card:hover{transform:translateY(-3px);border-color:rgba(79,70,229,.35);box-shadow:0 22px 40px -22px rgba(79,70,229,.45)}
.np-card-h{display:flex;gap:12px;align-items:center}
.np-av{width:46px;height:46px;border-radius:15px;display:flex;align-items:center;justify-content:center;color:#fff;font-weight:800;font-size:.95rem;flex:none;box-shadow:0 8px 16px -8px rgba(0,0,0,.4)}
.np-nm{font-weight:800;font-size:.98rem;line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.np-meta{font-size:.76rem;color:var(--np-soft);margin-top:2px}
.np-rank{margin-left:auto;font-size:.72rem;font-weight:800;border-radius:10px;padding:5px 9px;background:var(--np-s2);border:1px solid var(--np-line);white-space:nowrap}
.np-rank.r1{background:linear-gradient(135deg,#fde68a,#f59e0b);color:#78350f;border-color:transparent}
.np-rank.r2{background:linear-gradient(135deg,#e2e8f0,#94a3b8);color:#1e293b;border-color:transparent}
.np-rank.r3{background:linear-gradient(135deg,#fed7aa,#ea580c);color:#7c2d12;border-color:transparent}
.np-mid{display:flex;gap:16px;align-items:center;margin:16px 0 12px}
.np-ringbox{position:relative;width:76px;height:76px;flex:none}
.np-ringbox .np-ringv{position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;font-weight:800;font-size:1.12rem;line-height:1}
.np-ringbox small{font-size:.62rem;color:var(--np-soft);font-weight:700;margin-top:2px}
.np-ring-v{animation:npring .9s ease-out both}
.np-badges{display:flex;flex-wrap:wrap;gap:6px}
.np-badge{display:inline-flex;gap:5px;align-items:center;border-radius:999px;padding:4px 10px;font-size:.72rem;font-weight:800;background:var(--np-s2);border:1px solid var(--np-line)}
.np-badge i{width:8px;height:8px;border-radius:50%;display:inline-block}
.np-up{color:#16a34a;background:rgba(34,197,94,.12);border-color:transparent}
.np-down{color:#dc2626;background:rgba(239,68,68,.12);border-color:transparent}
.np-flat{color:var(--np-soft)}
.np-bars{display:grid;gap:7px;margin-top:6px}
.np-bar{display:grid;grid-template-columns:92px 1fr 38px;gap:8px;align-items:center;font-size:.74rem}
.np-bar span:first-child{color:var(--np-soft);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.np-track{height:7px;border-radius:99px;background:var(--np-track);overflow:hidden}
.np-fill{height:100%;border-radius:99px;transform-origin:left;animation:npgrow .8s ease-out both}
.np-fill.hi{background:linear-gradient(90deg,#22c55e,#4ade80)}
.np-fill.md{background:linear-gradient(90deg,#f59e0b,#fbbf24)}
.np-fill.lo{background:linear-gradient(90deg,#ef4444,#f87171)}
.np-fill.na{background:#94a3b8}
.np-bar b{text-align:right;font-weight:800}
.np-card-f{display:flex;gap:8px;align-items:center;margin-top:14px;padding-top:12px;border-top:1px dashed var(--np-line)}
.np-card-f .np-meta{margin:0;flex:1}
.np-ic{width:34px;height:34px;border-radius:11px;border:1px solid var(--np-line);background:var(--np-s2);color:var(--np-t);display:inline-flex;align-items:center;justify-content:center;font-size:.95rem;transition:.15s}
.np-ic:hover{background:var(--np-p);color:#fff;border-color:transparent}
.np-ic.add{background:linear-gradient(135deg,var(--np-p),var(--np-p2));color:#fff;border-color:transparent;font-weight:800}
.np-ic.del:hover{background:#ef4444}
.np-panel{background:var(--np-s);border:1px solid var(--np-line);border-radius:22px;box-shadow:var(--np-sh);overflow:hidden;margin-bottom:16px}
.np-panel-h{padding:16px 20px;border-bottom:1px solid var(--np-line);display:flex;gap:10px;align-items:center;flex-wrap:wrap}
.np-panel-h h3{margin:0;font-size:1rem;font-weight:800;flex:1}
.np-panel-b{padding:18px 20px}
.np-tw{overflow:auto;max-height:70vh}
.np-table{width:100%;border-collapse:separate;border-spacing:0;font-size:.84rem}
.np-table th{position:sticky;top:0;z-index:2;background:var(--np-s2);text-align:center;padding:12px 10px;font-size:.7rem;text-transform:uppercase;letter-spacing:.08em;color:var(--np-soft);border-bottom:1px solid var(--np-line);white-space:nowrap;cursor:pointer;user-select:none}
.np-table th:hover{color:var(--np-p)}
.np-table td{padding:10px;border-bottom:1px solid var(--np-line);text-align:center;white-space:nowrap}
.np-table tr:hover td{background:rgba(79,70,229,.05)}
.np-table td.l,.np-table th.l{text-align:left}
.np-table .stk{position:sticky;left:0;z-index:1;background:var(--np-s)}
.np-table th.stk{z-index:3;background:var(--np-s2)}
.np-cell{display:inline-block;min-width:46px;padding:4px 9px;border-radius:10px;font-weight:800}
.np-cell.hi{background:rgba(34,197,94,.14);color:#15803d}
.np-cell.md{background:rgba(245,158,11,.16);color:#b45309}
.np-cell.lo{background:rgba(239,68,68,.14);color:#b91c1c}
.np-cell.na{color:var(--np-soft)}
html.theme-neon .np-cell.hi{color:#4ade80}html.theme-neon .np-cell.md{color:#fbbf24}html.theme-neon .np-cell.lo{color:#f87171}
.np-qe-top{display:flex;flex-wrap:wrap;gap:12px;align-items:flex-end}
.np-fld{display:grid;gap:5px;font-size:.7rem;font-weight:800;text-transform:uppercase;letter-spacing:.08em;color:var(--np-soft)}
.np-fld .np-sel{text-transform:none;letter-spacing:0;min-width:170px}
.np-hint{background:rgba(79,70,229,.08);border:1px dashed rgba(79,70,229,.35);color:var(--np-p);border-radius:14px;padding:12px 14px;font-size:.82rem;font-weight:600;margin-top:14px}
.np-inp{width:110px;border:1.5px solid var(--np-line);background:var(--np-s2);color:var(--np-t);border-radius:12px;padding:9px 12px;font-weight:800;font-size:.95rem;text-align:center;font-family:inherit;transition:.15s}
.np-inp:focus{outline:0;border-color:var(--np-p);box-shadow:0 0 0 4px rgba(79,70,229,.15);background:var(--np-s)}
.np-inp.ok{border-color:#22c55e;background:rgba(34,197,94,.08)}
.np-inp.bad{border-color:#ef4444;background:rgba(239,68,68,.08)}
.np-chipx{display:inline-block;font-size:.72rem;font-weight:700;padding:3px 8px;border-radius:9px;background:var(--np-s2);border:1px solid var(--np-line);margin:2px 3px 2px 0}
.np-sticky-f{position:sticky;bottom:12px;z-index:5;margin-top:16px;display:flex;flex-wrap:wrap;gap:12px;align-items:center;justify-content:space-between;background:var(--np-s);border:1px solid var(--np-line);border-radius:18px;padding:12px 16px;box-shadow:0 18px 40px -18px rgba(15,23,42,.5)}
.np-prog{height:8px;width:180px;border-radius:99px;background:var(--np-track);overflow:hidden}
.np-prog i{display:block;height:100%;background:linear-gradient(90deg,var(--np-p),var(--np-p2));transition:width .3s}
.np-2c{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:16px}
.np-dist{display:flex;align-items:flex-end;gap:12px;height:190px;padding-top:10px}
.np-dcol{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;gap:6px}
.np-dbar{width:100%;border-radius:12px 12px 4px 4px;min-height:4px;transform-origin:bottom;animation:npgrowy .8s ease-out both}
.np-dcol b{font-size:.95rem}
.np-dcol span{font-size:.7rem;color:var(--np-soft);font-weight:700;text-align:center}
.np-mrow{display:grid;grid-template-columns:130px 1fr 62px;gap:12px;align-items:center;padding:9px 0;border-bottom:1px solid var(--np-line);font-size:.84rem}
.np-mrow:last-child{border:0}
.np-mrow .np-track{height:10px;position:relative;overflow:visible}
.np-mrow .np-fill{position:absolute;inset:0 auto 0 0}
.np-rl{display:flex;gap:12px;align-items:center;padding:9px 0;border-bottom:1px solid var(--np-line);cursor:pointer}
.np-rl:last-child{border:0}
.np-rl:hover .np-nm{color:var(--np-p)}
.np-log{display:flex;gap:14px;padding:13px 0;border-bottom:1px solid var(--np-line);align-items:flex-start}
.np-log:last-child{border:0}
.np-dot{width:36px;height:36px;border-radius:12px;display:flex;align-items:center;justify-content:center;flex:none;font-weight:800;font-size:.8rem}
.np-empty{text-align:center;padding:60px 20px;color:var(--np-soft)}
.np-empty b{display:block;font-size:2.4rem;margin-bottom:8px}
.np-ov{position:fixed;inset:0;background:rgba(15,23,42,.5);backdrop-filter:blur(4px);opacity:0;pointer-events:none;transition:.22s;z-index:900}
.np-ov.on{opacity:1;pointer-events:auto}
.np-drawer{position:fixed;top:0;right:0;bottom:0;width:min(520px,100vw);background:var(--np-s);color:var(--np-t);z-index:910;transform:translateX(105%);transition:transform .3s cubic-bezier(.2,.8,.2,1);display:flex;flex-direction:column;box-shadow:-30px 0 60px -30px rgba(0,0,0,.5)}
html.theme-neon .np-drawer{background:#14142a}
.np-drawer.on{transform:none}
.np-dr-h{padding:20px 22px;color:#fff;background:linear-gradient(135deg,#312e81,#4f46e5 55%,#0ea5e9);position:relative}
.np-x{position:absolute;right:16px;top:16px;width:36px;height:36px;border-radius:12px;border:0;background:rgba(255,255,255,.18);color:#fff;font-size:1.1rem}
.np-dr-b{flex:1;overflow:auto;padding:18px 22px}
.np-dr-f{padding:14px 22px;border-top:1px solid var(--np-line);display:flex;gap:10px;flex-wrap:wrap}
.np-mblk{border:1px solid var(--np-line);border-radius:18px;margin-bottom:12px;overflow:hidden;background:var(--np-s)}
.np-mblk-h{display:flex;gap:10px;align-items:center;padding:12px 14px;background:var(--np-s2);font-weight:800;font-size:.88rem}
.np-nrow{display:flex;gap:10px;align-items:center;padding:10px 14px;border-top:1px solid var(--np-line);font-size:.82rem}
.np-nrow .grow{flex:1;min-width:0}
.np-nrow small{display:block;color:var(--np-soft);font-size:.7rem;margin-top:1px}
.np-modal{position:fixed;inset:0;z-index:950;display:none;align-items:center;justify-content:center;padding:16px;background:rgba(15,23,42,.55);backdrop-filter:blur(5px)}
.np-modal.on{display:flex;animation:npin .18s ease-out}
.np-mbox{width:min(560px,100%);max-height:92vh;overflow:auto;background:var(--np-s);color:var(--np-t);border-radius:26px;padding:24px;box-shadow:0 40px 80px -30px rgba(0,0,0,.6)}
.np-mbox h3{margin:0 0 4px;font-size:1.2rem;font-weight:800}
.np-mbox p.sub{margin:0 0 16px;color:var(--np-soft);font-size:.84rem}
.np-fg{display:grid;gap:14px;grid-template-columns:1fr 1fr}
.np-fg .full{grid-column:1/-1}
.np-fg label{display:grid;gap:6px;font-size:.72rem;font-weight:800;color:var(--np-soft);text-transform:uppercase;letter-spacing:.07em}
.np-fg .np-sel,.np-fg .np-inp{width:100%;text-align:left;box-shadow:none}
.np-seg{display:flex;gap:6px}
.np-seg label{flex:1;margin:0;cursor:pointer}
.np-seg input{display:none}
.np-seg span{display:block;text-align:center;padding:11px;border-radius:12px;border:1.5px solid var(--np-line);font-weight:800;font-size:.9rem;color:var(--np-t);text-transform:none;letter-spacing:0;transition:.15s}
.np-seg input:checked+span{background:linear-gradient(135deg,var(--np-p),var(--np-p2));color:#fff;border-color:transparent}
.np-prev{background:rgba(79,70,229,.08);border-radius:12px;padding:10px 12px;font-size:.8rem;font-weight:700;color:var(--np-p);text-transform:none;letter-spacing:0}
.np-warn{background:rgba(245,158,11,.12);border:1px solid rgba(245,158,11,.4);color:#b45309;border-radius:12px;padding:10px 12px;font-size:.8rem;font-weight:600;text-transform:none;letter-spacing:0}
.np-mf{display:flex;gap:10px;justify-content:flex-end;margin-top:20px}
.np-toasts{position:fixed;right:20px;bottom:20px;z-index:1000;display:grid;gap:10px}
.np-toast{background:#0f172a;color:#fff;border-radius:16px;padding:13px 18px;font-weight:600;font-size:.86rem;box-shadow:0 20px 40px -16px rgba(0,0,0,.6);display:flex;gap:10px;align-items:center;max-width:380px;animation:npin .25s ease-out;border-left:5px solid #22c55e}
.np-toast.err{border-left-color:#ef4444}
@keyframes npup{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}
@keyframes npin{from{opacity:0;transform:scale(.97)}to{opacity:1;transform:none}}
@keyframes npring{from{stroke-dashoffset:var(--c)}}
@keyframes npgrow{from{transform:scaleX(0)}}
@keyframes npgrowy{from{transform:scaleY(0)}}
@media(max-width:760px){
.np-hero{padding:20px 16px;border-radius:20px}.np-h1{font-size:1.3rem}.np-actions{width:100%}.np-actions .np-btn{flex:1;justify-content:center}
.np-grid{grid-template-columns:1fr}.np-2c{grid-template-columns:1fr}.np-fg{grid-template-columns:1fr}.np-mrow{grid-template-columns:96px 1fr 54px}
.np-toasts{left:14px;right:14px}.np-sel{flex:1 1 140px}.np-tabs{width:100%}
}
@media(prefers-reduced-motion:reduce){.np *{animation:none!important;transition:none!important}}
@media print{.np-tools,.np-tabs,.np-actions,.np-ic,.np-sticky-f,.np-toasts{display:none!important}.np-hero{box-shadow:none}}
</style>
<div class="np nm-desk" id="np">
  <section class="np-hero">
    <div class="np-hero-top">
      <div class="np-id">
        <a class="np-back" id="npBack" href="/notes" title="Changer de classe">‹</a>
        <div><div class="np-eyebrow" id="npEyebrow"></div><h1 class="np-h1" id="npTitle">Notes</h1><div class="np-sub" id="npSub"></div></div>
      </div>
      <div class="np-actions">
        <button type="button" class="np-btn np-btn-glass" data-act="go-grid">⚡ Saisie rapide</button>
        <button type="button" class="np-btn np-btn-white" data-act="add">＋ Nouvelle note</button>
        <div class="np-menu">
          <button type="button" class="np-btn np-btn-glass" data-act="menu">⤓ Exporter ▾</button>
          <div class="np-menu-pop" id="npMenu">
            <button type="button" data-act="export-csv">📄 CSV (notes affichées)</button>
            <a id="npXls" href="#">📥 Excel (classe complète)</a>
            <a id="npPdf" href="#">📕 PDF (classe complète)</a>
            <button type="button" data-act="print">🖨️ Imprimer la page</button>
          </div>
        </div>
      </div>
    </div>
    <div class="np-kpis" id="npKpis"></div>
  </section>
  <div class="np-tabs" id="npTabs"></div>
  <div class="np-tools" id="npTools"></div>
  <div class="np-count" id="npCount"></div>
  <div id="npView"></div>
  <div class="np-ov" id="npOv"></div>
  <aside class="np-drawer" id="npDrawer"></aside>
  <div class="np-modal" id="npModal"></div>
  <div class="np-toasts" id="npToasts"></div>
</div>

<script>
window.NP_DATA = {{ notes_pro_json|safe }};
window.NP_FLASH = [{% for _c, _m in get_flashed_messages(with_categories=true)|unique %}{{ [_c, _m]|tojson }}{% if not loop.last %},{% endif %}{% endfor %}];
</script>
<script>
(function(){
'use strict';
var NP = window.NP_DATA || {eleves:[], mat:[], sm:{}};
var D = document;
function $(id){ return D.getElementById(id); }
var SYS = NP.systeme, LET = SYS === 'lettres', MX = SYS === '10' ? 10 : 20, DIV = SYS === '10' ? 2 : 1;
var ROLE = NP.role, UID = NP.uid, ADMIN = (ROLE === 'admin' || ROLE === 'agent_admin'), ISADMIN = (ROLE === 'admin');
var MATS = {}, EL = {}, SMC = {};
NP.mat.forEach(function(m){ MATS[m.id] = m; });
NP.eleves.forEach(function(e){ EL[e.id] = e; });
Object.keys(NP.sm || {}).forEach(function(k){ NP.sm[k].forEach(function(s){ SMC[s.id] = s; }); });

/* ───────── état + persistance ───────── */
var SKEY = 'np_state_v1_' + (NP.classe_id || 'x') + '_' + ROLE;
var ST = {view:'cards', q:'', tri:'all', mat:'', sm:'', statut:'all', sort:'name'};
try { var sv = JSON.parse(localStorage.getItem(SKEY) || 'null'); if (sv) { for (var k in ST) { if (sv[k] != null) ST[k] = sv[k]; } } } catch (e) {}
ST.q = '';
if (ST.mat && !MATS[ST.mat]) { ST.mat = ''; ST.sm = ''; }
if (['cards','table','grid','stats','log'].indexOf(ST.view) < 0) ST.view = 'cards';
function save(){ try { localStorage.setItem(SKEY, JSON.stringify(ST)); } catch (e) {} }
var QE = {mat:'', sm:'', tri:'1', ens:'', vals:{}};
var DR = {eid:null, tri:'all'};
var RALL = [], RVIS = [];

/* ───────── helpers ───────── */
function esc(s){ return String(s == null ? '' : s).replace(/[&<>"']/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]; }); }
function r2(x){ return Math.round(x * 100) / 100; }
function letter(v){ return v >= 13 ? 'A' : (v >= 7 ? 'B' : 'C'); }
function fmt(v){
  if (v == null || isNaN(v)) return '—';
  if (LET) return letter(v);
  var x = r2(v / DIV);
  return String(x % 1 === 0 ? x : x.toFixed(2).replace(/0+$/, '').replace(/\\.$/, ''));
}
function tone(v){ if (v == null) return 'na'; if (LET) return v >= 13 ? 'hi' : (v >= 7 ? 'md' : 'lo'); return v >= 14 ? 'hi' : (v >= 10 ? 'md' : 'lo'); }
var PROF = [['Critique','#ef4444',4],['Fragile','#f97316',8],['Stable','#eab308',12],['Leader','#22c55e',16],['Champion','#3b82f6',21]];
function profil(v){
  if (v == null) return null;
  if (LET) { var l = letter(v); return l === 'A' ? {l:'Bon', c:'#22c55e'} : (l === 'B' ? {l:'Moyen', c:'#eab308'} : {l:'Bas', c:'#ef4444'}); }
  for (var i = 0; i < PROF.length; i++) { if (v < PROF[i][2]) return {l:PROF[i][0], c:PROF[i][1]}; }
  return {l:'Champion', c:'#3b82f6'};
}
function norm(s){ return String(s || '').toLowerCase().normalize('NFD').replace(/[\\u0300-\\u036f]/g, ''); }
function initials(e){ return ((e.p || '').charAt(0) + (e.n || '').charAt(0)).toUpperCase() || '?'; }
function grad(id){ var g = [['#6366f1','#8b5cf6'],['#0ea5e9','#6366f1'],['#10b981','#0ea5e9'],['#f59e0b','#ef4444'],['#ec4899','#8b5cf6'],['#14b8a6','#22c55e'],['#f97316','#ec4899']]; var p = g[Math.abs(parseInt(id, 10) || 0) % g.length]; return 'linear-gradient(135deg,' + p[0] + ',' + p[1] + ')'; }
function fdate(d){ if (!d) return ''; var p = String(d).slice(0, 10).split('-'); return p.length === 3 ? p[2] + '/' + p[1] + '/' + p[0] : d; }
function trendChip(d){
  if (d == null) return '';
  if (d > 0.05) return '<span class="np-badge np-up">↗ ' + (LET ? '' : '+' + r2(d / DIV)) + ' vs S1</span>';
  if (d < -0.05) return '<span class="np-badge np-down">↘ ' + (LET ? '' : r2(d / DIV)) + ' vs S1</span>';
  return '<span class="np-badge np-flat">→ stable vs S1</span>';
}
function ring(v, size, sw){
  size = size || 76; sw = sw || 8;
  var r = (size - sw) / 2, c = 2 * Math.PI * r, p = v == null ? 0 : Math.max(0, Math.min(1, v / 20));
  var col = {hi:'#22c55e', md:'#f59e0b', lo:'#ef4444', na:'#94a3b8'}[tone(v)];
  var h = size / 2;
  return '<svg width="' + size + '" height="' + size + '" viewBox="0 0 ' + size + ' ' + size + '"><circle cx="' + h + '" cy="' + h + '" r="' + r + '" fill="none" stroke="var(--np-track)" stroke-width="' + sw + '"/><circle class="np-ring-v" cx="' + h + '" cy="' + h + '" r="' + r + '" fill="none" stroke="' + col + '" stroke-width="' + sw + '" stroke-linecap="round" stroke-dasharray="' + c + '" stroke-dashoffset="' + (c * (1 - p)) + '" transform="rotate(-90 ' + h + ' ' + h + ')" style="--c:' + c + '"/></svg>';
}
function spark(vals, w, h){
  if (vals.length < 2) return '';
  var mn = 0, mx = 20, pts = vals.map(function(v, i){ return [4 + i * (w - 8) / (vals.length - 1), h - 4 - (v - mn) / (mx - mn) * (h - 8)]; });
  var d = pts.map(function(p, i){ return (i ? 'L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1); }).join(' ');
  var last = pts[pts.length - 1];
  return '<svg width="100%" height="' + h + '" viewBox="0 0 ' + w + ' ' + h + '" preserveAspectRatio="none"><path d="' + d + ' L' + last[0] + ' ' + h + ' L' + pts[0][0] + ' ' + h + ' Z" fill="rgba(79,70,229,.12)"/><path d="' + d + '" fill="none" stroke="#6366f1" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="' + last[0] + '" cy="' + last[1] + '" r="4" fill="#6366f1"/></svg>';
}
function toast(msg, err){
  var t = D.createElement('div'); t.className = 'np-toast' + (err ? ' err' : '');
  t.innerHTML = '<span>' + (err ? '⚠️' : '✅') + '</span><span>' + esc(msg) + '</span>';
  $('npToasts').appendChild(t);
  setTimeout(function(){ t.style.transition = '.3s'; t.style.opacity = '0'; setTimeout(function(){ t.remove(); }, 300); }, 4800);
}
function countUp(el){
  var to = parseFloat(el.getAttribute('data-to')), dec = parseInt(el.getAttribute('data-dec') || '0', 10);
  if (isNaN(to)) return;
  var t0 = null, dur = 700;
  function step(ts){ if (!t0) t0 = ts; var p = Math.min(1, (ts - t0) / dur), e = 1 - Math.pow(1 - p, 3); el.textContent = (to * e).toFixed(dec).replace(/\\.0+$/, ''); if (p < 1) requestAnimationFrame(step); else el.textContent = to.toFixed(dec).replace(/\\.0+$/, ''); }
  requestAnimationFrame(step);
}

/* ───────── calculs (moyenne pondérée sous-matière puis matière, comme le reste de l'app) ───────── */
function avgOf(notes){
  var by = {};
  notes.forEach(function(n){
    var d = by[n.mid] || (by[n.mid] = {p:0, c:0});
    var c = (n.smid && SMC[n.smid] && +SMC[n.smid].coefficient) ? +SMC[n.smid].coefficient : 1;
    d.p += n.v * c; d.c += c;
  });
  var tp = 0, tc = 0, per = {};
  Object.keys(by).forEach(function(k){ var m = by[k].p / by[k].c, cm = (MATS[k] && +MATS[k].coef) || 1; per[k] = m; tp += m * cm; tc += cm; });
  return {avg: tc ? tp / tc : null, per: per};
}
function filtNotes(e){
  return e.notes.filter(function(n){
    if (ST.tri !== 'all' && String(n.t) !== ST.tri) return false;
    if (ST.mat && String(n.mid) !== String(ST.mat)) return false;
    if (ST.sm && String(n.smid) !== String(ST.sm)) return false;
    if (ST.statut === 'pass' && n.v < 10) return false;
    if (ST.statut === 'fail' && n.v >= 10) return false;
    if (ST.statut === 'mod' && !n.mod) return false;
    return true;
  });
}
function build(){
  var rows = NP.eleves.map(function(e){
    var ns = filtNotes(e), a = avgOf(ns);
    var a1 = avgOf(ns.filter(function(n){ return +n.t === 1; })).avg, a2 = avgOf(ns.filter(function(n){ return +n.t === 2; })).avg;
    return {e:e, notes:ns, avg:a.avg, per:a.per, s1:a1, s2:a2, delta:(a1 != null && a2 != null) ? a2 - a1 : null, nmod:ns.filter(function(n){ return n.mod; }).length};
  });
  var ranked = rows.filter(function(r){ return r.avg != null; }).sort(function(a, b){ return b.avg - a.avg; });
  ranked.forEach(function(r, i){ r.rank = (i > 0 && Math.abs(ranked[i - 1].avg - r.avg) < 0.005) ? ranked[i - 1].rank : i + 1; });
  rows.forEach(function(r){ r.tot = ranked.length; });
  return rows;
}
function sortRows(rows){
  var s = ST.sort, cmpName = function(a, b){ return (a.e.n + ' ' + a.e.p).localeCompare(b.e.n + ' ' + b.e.p); };
  rows.sort(function(a, b){
    if (s === 'avg_desc' || s === 'avg_asc') { if (a.avg == null && b.avg == null) return cmpName(a, b); if (a.avg == null) return 1; if (b.avg == null) return -1; return s === 'avg_desc' ? b.avg - a.avg : a.avg - b.avg; }
    if (s === 'trend') { var da = a.delta == null ? -99 : a.delta, db = b.delta == null ? -99 : b.delta; return db - da || cmpName(a, b); }
    return cmpName(a, b);
  });
  return rows;
}
function nextExam(eid, mid, smid, tri){
  var e = EL[eid]; if (!e || !mid) return null; var c = 0;
  e.notes.forEach(function(n){ if (String(n.mid) === String(mid) && String(n.smid || '') === String(smid || '') && String(n.t) === String(tri)) c++; });
  return c + 1;
}
function canEdit(n){ return ADMIN || (ROLE === 'enseignant' && n.eid === UID && !n.mod); }
function noteLabel(n){ return esc(n.mat) + (n.sm ? ' · ' + esc(n.sm) + (n.ex ? ' <b>(Examen ' + n.ex + ')</b>' : '') : (n.ex ? ' · <b>Examen ' + n.ex + '</b>' : '')); }

/* ───────── en-tête / KPI ───────── */
function renderHero(){
  $('npEyebrow').textContent = 'Section ' + NP.cycle + (NP.niveau ? ' · ' + NP.niveau : '');
  $('npTitle').textContent = 'Notes' + (NP.classe ? ' — ' + NP.classe : '');
  $('npSub').textContent = (ADMIN ? 'Pilotage des évaluations' : 'Vos évaluations') + ' · ' + NP.eleves.length + ' élèves · ' + NP.mat.length + ' matière' + (NP.mat.length > 1 ? 's' : '');
  $('npBack').setAttribute('href', '/notes?cycle=' + encodeURIComponent(NP.cycle));
  var q = '?cycle=' + encodeURIComponent(NP.cycle) + (NP.classe_id ? '&classe_id=' + encodeURIComponent(NP.classe_id) : '');
  $('npXls').setAttribute('href', '/export/notes/excel' + q);
  $('npPdf').setAttribute('href', '/export/notes/pdf' + q);
}
function renderKpis(){
  var rated = RALL.filter(function(r){ return r.avg != null; });
  var tot = RALL.reduce(function(s, r){ return s + r.notes.length; }, 0);
  var cls = rated.length ? rated.reduce(function(s, r){ return s + r.avg; }, 0) / rated.length : null;
  var pass = rated.filter(function(r){ return r.avg >= 10; }).length;
  var risk = rated.filter(function(r){ return r.avg < 10; }).length;
  var best = rated.slice().sort(function(a, b){ return b.avg - a.avg; })[0];
  var s1 = avgOf([].concat.apply([], RALL.map(function(r){ return r.notes.filter(function(n){ return +n.t === 1; }); }))).avg;
  var s2 = avgOf([].concat.apply([], RALL.map(function(r){ return r.notes.filter(function(n){ return +n.t === 2; }); }))).avg;
  var dl = (s1 != null && s2 != null) ? s2 - s1 : null;
  var k = [
    ['👥', 'Élèves notés', rated.length, 0, '/ ' + NP.eleves.length, NP.eleves.length - rated.length ? (NP.eleves.length - rated.length) + ' sans note' : 'Tous notés'],
    ['📝', 'Notes saisies', tot, 0, '', RALL.reduce(function(s, r){ return s + r.nmod; }, 0) + ' modifiée(s)'],
    ['🎯', 'Moyenne de classe', LET ? null : (cls == null ? null : r2(cls / DIV)), 2, LET ? '' : '/' + MX, LET ? (cls == null ? '—' : letter(cls)) : (dl == null ? 'S1 → S2 à venir' : (dl > 0.05 ? '↗ +' + r2(dl / DIV) : (dl < -0.05 ? '↘ ' + r2(dl / DIV) : '→ stable')) + ' S1→S2')],
    ['✅', 'Taux de réussite', rated.length ? Math.round(pass / rated.length * 100) : null, 0, '%', pass + ' élève(s) ≥ 10/20'],
    ['🚨', 'À accompagner', risk, 0, '', risk ? 'Moyenne < 10/20' : 'Aucun élève en difficulté'],
    ['🏆', 'Meilleure moyenne', null, 0, '', best ? (best.e.p + ' ' + best.e.n + ' · ' + fmt(best.avg) + (LET ? '' : '/' + MX)) : '—']
  ];
  $('npKpis').innerHTML = k.map(function(x, i){
    var v = x[2] == null ? (x[1] === 'Moyenne de classe' && LET ? (cls == null ? '—' : letter(cls)) : '—') : '<span data-to="' + x[2] + '" data-dec="' + x[3] + '">0</span>';
    if (x[1] === 'Meilleure moyenne') v = best ? '<span style="font-size:1.1rem">' + esc(best.e.p) + '</span>' : '—';
    return '<div class="np-kpi" style="--i:' + i + '"><div class="np-kpi-l"><span>' + x[0] + '</span>' + x[1] + '</div><div class="np-kpi-v">' + v + (x[4] && x[2] != null ? '<small>' + x[4] + '</small>' : '') + '</div><div class="np-kpi-s">' + esc(x[5]) + '</div></div>';
  }).join('');
  $('npKpis').querySelectorAll('[data-to]').forEach(countUp);
}
function renderTabs(){
  var t = [['cards', '🪪 Élèves'], ['table', '📊 Tableau'], ['grid', '⚡ Saisie rapide'], ['stats', '📈 Analyses'], ['log', '🕑 Activité']];
  $('npTabs').innerHTML = t.map(function(x){ return '<button class="np-tab' + (ST.view === x[0] ? ' on' : '') + '" data-act="view" data-v="' + x[0] + '">' + x[1] + '</button>'; }).join('');
}

/* ───────── barre d'outils (rendue une seule fois) ───────── */
function renderTools(){
  var mo = '<option value="">Toutes les matières</option>' + NP.mat.map(function(m){ return '<option value="' + m.id + '">' + esc(m.nom) + '</option>'; }).join('');
  $('npTools').innerHTML =
    '<label class="np-search"><span>🔎</span><input id="npQ" type="text" placeholder="Rechercher un élève…" autocomplete="off"><kbd>/</kbd></label>' +
    '<div class="np-chips" id="npTri"><button class="np-chip" data-act="tri" data-v="all">Année</button><button class="np-chip" data-act="tri" data-v="1">S1</button><button class="np-chip" data-act="tri" data-v="2">S2</button></div>' +
    '<select class="np-sel" id="npMat">' + mo + '</select>' +
    '<select class="np-sel" id="npSm"></select>' +
    '<select class="np-sel" id="npStat"><option value="all">Toutes les notes</option><option value="pass">✅ Réussites (≥ 10/20)</option><option value="fail">❌ Échecs (&lt; 10/20)</option><option value="mod">✏️ Modifiées</option></select>' +
    '<select class="np-sel" id="npSort"><option value="name">Tri : Nom A→Z</option><option value="avg_desc">Tri : Meilleures moyennes</option><option value="avg_asc">Tri : Plus faibles moyennes</option><option value="trend">Tri : Progression S1→S2</option></select>' +
    '<button class="np-btn np-btn-o np-btn-sm" data-act="reset">↺ Réinitialiser</button>';
  $('npQ').addEventListener('input', function(){ ST.q = this.value; refresh(true); });
  $('npMat').addEventListener('change', function(){ ST.mat = this.value; ST.sm = ''; syncTools(); save(); refresh(); });
  $('npSm').addEventListener('change', function(){ ST.sm = this.value; save(); refresh(); });
  $('npStat').addEventListener('change', function(){ ST.statut = this.value; save(); refresh(); });
  $('npSort').addEventListener('change', function(){ ST.sort = this.value; save(); refresh(); });
}
function syncTools(){
  $('npMat').value = ST.mat; $('npStat').value = ST.statut; $('npSort').value = ST.sort;
  var list = ST.mat ? (NP.sm[ST.mat] || []) : [], sel = $('npSm');
  sel.style.display = list.length ? '' : 'none';
  sel.innerHTML = '<option value="">Toutes les sous-matières</option>' + list.map(function(s){ return '<option value="' + s.id + '">' + esc(s.nom) + '</option>'; }).join('');
  sel.value = ST.sm;
  $('npTri').querySelectorAll('.np-chip').forEach(function(b){ b.classList.toggle('on', b.getAttribute('data-v') === ST.tri); });
  $('npTools').style.display = ST.view === 'grid' ? 'none' : '';
}

/* ───────── rendu principal ───────── */
function refresh(keepFocus){
  RALL = build();
  var needle = norm(ST.q);
  RVIS = sortRows(RALL.filter(function(r){ return !needle || norm(r.e.p + ' ' + r.e.n).indexOf(needle) >= 0 || norm(r.e.n + ' ' + r.e.p).indexOf(needle) >= 0; }));
  renderTabs(); syncTools();
  if (!keepFocus) renderKpis();
  var act = [];
  if (ST.tri !== 'all') act.push('Semestre S' + ST.tri);
  if (ST.mat) act.push(MATS[ST.mat].nom + (ST.sm && SMC[ST.sm] ? ' › ' + SMC[ST.sm].nom : ''));
  if (ST.statut !== 'all') act.push({pass:'Réussites', fail:'Échecs', mod:'Modifiées'}[ST.statut]);
  $('npCount').innerHTML = ST.view === 'grid' ? '' : '<b>' + RVIS.length + '</b> élève' + (RVIS.length > 1 ? 's' : '') + (act.length ? ' · ' + act.map(function(a){ return '<span class="np-pill">' + esc(a) + '</span>'; }).join('') : '');
  var v = $('npView');
  if (ST.view === 'cards') v.innerHTML = viewCards();
  else if (ST.view === 'table') v.innerHTML = viewTable();
  else if (ST.view === 'grid') v.innerHTML = viewGrid();
  else if (ST.view === 'stats') v.innerHTML = viewStats();
  else v.innerHTML = viewLog();
  if (ST.view === 'grid') gridInit();
  if (DR.eid != null && $('npDrawer').classList.contains('on')) renderDrawer();
}

function viewCards(){
  if (!RVIS.length) return '<div class="np-empty"><b>🔎</b>Aucun élève ne correspond à votre recherche.</div>';
  return '<div class="np-grid">' + RVIS.map(function(r, i){
    var p = profil(r.avg), mats = Object.keys(r.per).slice(0, 4);
    var rk = r.rank ? '<span class="np-rank' + (r.rank <= 3 ? ' r' + r.rank : '') + '">' + (r.rank === 1 ? '🥇 ' : r.rank === 2 ? '🥈 ' : r.rank === 3 ? '🥉 ' : '#') + r.rank + '/' + r.tot + '</span>' : '';
    return '<article class="np-card" style="--i:' + Math.min(i, 24) + '" data-act="open" data-id="' + r.e.id + '">' +
      '<div class="np-card-h"><span class="np-av" style="background:' + grad(r.e.id) + '">' + esc(initials(r.e)) + '</span><div style="min-width:0"><div class="np-nm">' + esc(r.e.p) + ' ' + esc(r.e.n) + '</div><div class="np-meta">' + r.notes.length + ' note' + (r.notes.length > 1 ? 's' : '') + (r.nmod ? ' · ' + r.nmod + ' modifiée(s)' : '') + '</div></div>' + rk + '</div>' +
      '<div class="np-mid"><div class="np-ringbox">' + ring(r.avg) + '<div class="np-ringv"><span>' + fmt(r.avg) + '</span>' + (LET || r.avg == null ? '' : '<small>/' + MX + '</small>') + '</div></div><div class="np-badges">' +
      (p ? '<span class="np-badge"><i style="background:' + p.c + '"></i>' + p.l + '</span>' : '<span class="np-badge">📭 Aucune note</span>') + trendChip(r.delta) +
      (r.s1 != null ? '<span class="np-badge">S1 · ' + fmt(r.s1) + '</span>' : '') + (r.s2 != null ? '<span class="np-badge">S2 · ' + fmt(r.s2) + '</span>' : '') + '</div></div>' +
      (mats.length ? '<div class="np-bars">' + mats.map(function(k){ var v = r.per[k]; return '<div class="np-bar"><span title="' + esc(MATS[k] ? MATS[k].nom : '') + '">' + esc(MATS[k] ? MATS[k].nom : '') + '</span><div class="np-track"><div class="np-fill ' + tone(v) + '" style="width:' + Math.max(4, v / 20 * 100) + '%"></div></div><b>' + fmt(v) + '</b></div>'; }).join('') + '</div>' : '') +
      '<div class="np-card-f"><span class="np-meta">' + (Object.keys(r.per).length > 4 ? '+' + (Object.keys(r.per).length - 4) + ' matière(s)' : 'Voir le détail →') + '</span><button class="np-ic add" data-act="add" data-id="' + r.e.id + '" title="Ajouter une note">+</button></div></article>';
  }).join('') + '</div>';
}

function viewTable(){
  if (!RVIS.length) return '<div class="np-empty"><b>🔎</b>Aucun résultat.</div>';
  var ms = ST.mat ? [MATS[ST.mat]] : NP.mat;
  var arrow = function(k){ return ST.sort === k ? ' ▾' : ''; };
  var h = '<div class="np-panel"><div class="np-tw"><table class="np-table"><thead><tr><th>Rang</th><th class="l stk" data-act="sort" data-v="name">Élève' + (ST.sort === 'name' ? ' ▴' : '') + '</th>' +
    ms.map(function(m){ return '<th title="' + esc(m.nom) + '">' + esc(m.nom) + '</th>'; }).join('') +
    '<th>S1</th><th>S2</th><th data-act="sort" data-v="avg_desc">Moyenne' + arrow('avg_desc') + '</th><th data-act="sort" data-v="trend">Tendance' + arrow('trend') + '</th><th></th></tr></thead><tbody>';
  RVIS.forEach(function(r){
    var cell = function(v){ return '<span class="np-cell ' + tone(v) + '">' + fmt(v) + '</span>'; };
    h += '<tr><td>' + (r.rank ? '<b>' + r.rank + '</b>' : '—') + '</td><td class="l stk"><a href="#" data-act="open" data-id="' + r.e.id + '" style="color:inherit;font-weight:800;text-decoration:none">' + esc(r.e.n) + ' ' + esc(r.e.p) + '</a></td>' +
      ms.map(function(m){ return '<td>' + cell(r.per[m.id]) + '</td>'; }).join('') +
      '<td>' + cell(r.s1) + '</td><td>' + cell(r.s2) + '</td><td>' + cell(r.avg) + '</td><td>' + (trendChip(r.delta) || '—') + '</td>' +
      '<td><button class="np-ic add" data-act="add" data-id="' + r.e.id + '" title="Ajouter une note">+</button></td></tr>';
  });
  return h + '</tbody></table></div></div>';
}

/* ───────── saisie rapide en grille ───────── */
function qeInit(){
  if (!QE.mat || !MATS[QE.mat]) QE.mat = ST.mat || (NP.mat[0] ? NP.mat[0].id : '');
  var l = QE.mat ? (NP.sm[QE.mat] || []) : [];
  if (l.length && !l.some(function(s){ return String(s.id) === String(QE.sm); })) QE.sm = (ST.sm && l.some(function(s){ return String(s.id) === String(ST.sm); })) ? ST.sm : '';
  if (!l.length) QE.sm = '';
  if (!QE.ens) QE.ens = (MATS[QE.mat] && MATS[QE.mat].ens) || (NP.ens[0] ? NP.ens[0].id : '');
}
function viewGrid(){
  qeInit();
  if (!NP.mat.length) return '<div class="np-empty"><b>📚</b>Aucune matière disponible pour cette classe.</div>';
  var l = NP.sm[QE.mat] || [];
  var h = '<div class="np-panel"><div class="np-panel-h"><h3>⚡ Saisie rapide — toute la classe en une fois</h3></div><div class="np-panel-b">' +
    '<div class="np-qe-top"><label class="np-fld">Matière<select class="np-sel" id="qeMat">' + NP.mat.map(function(m){ return '<option value="' + m.id + '"' + (String(m.id) === String(QE.mat) ? ' selected' : '') + '>' + esc(m.nom) + '</option>'; }).join('') + '</select></label>' +
    (l.length ? '<label class="np-fld">Sous-matière<select class="np-sel" id="qeSm"><option value="">— Choisir —</option>' + l.map(function(s){ return '<option value="' + s.id + '"' + (String(s.id) === String(QE.sm) ? ' selected' : '') + '>' + esc(s.nom) + ' (coef ' + s.coefficient + ')</option>'; }).join('') + '</select></label>' : '') +
    '<label class="np-fld">Semestre<select class="np-sel" id="qeTri"><option value="1"' + (QE.tri === '1' ? ' selected' : '') + '>S1</option><option value="2"' + (QE.tri === '2' ? ' selected' : '') + '>S2</option></select></label>' +
    (ADMIN ? '<label class="np-fld">Enseignant valideur<select class="np-sel" id="qeEns">' + NP.ens.map(function(t){ return '<option value="' + t.id + '"' + (String(t.id) === String(QE.ens) ? ' selected' : '') + '>' + esc(t.nom) + '</option>'; }).join('') + '</select></label>' : '') +
    '</div>';
  if (l.length && !QE.sm) return h + '<div class="np-hint">👆 Choisissez d’abord la sous-matière pour afficher la grille de saisie.</div></div></div>';
  h += '<div class="np-hint">💡 Remplissez seulement les élèves à noter · <b>Entrée</b> ou <b>↓</b> pour passer au suivant · vous pouvez <b>coller une colonne Excel</b> dans la première case.</div>';
  var rows = sortRows(NP.eleves.map(function(e){ return {e:e, avg:null, delta:null}; }));
  h += '<div class="np-tw" style="margin-top:14px"><table class="np-table"><thead><tr><th class="l">Élève</th><th class="l">Notes déjà saisies</th><th>Nouvelle note' + (l.length ? '' : '') + '</th><th>État</th></tr></thead><tbody>';
  rows.forEach(function(r, i){
    var e = r.e, ex = e.notes.filter(function(n){ return String(n.mid) === String(QE.mat) && String(n.smid || '') === String(QE.sm || '') && String(n.t) === String(QE.tri); });
    var nx = QE.sm ? nextExam(e.id, QE.mat, QE.sm, QE.tri) : null;
    h += '<tr data-row="' + e.id + '"><td class="l"><b>' + esc(e.n) + '</b> ' + esc(e.p) + '</td><td class="l">' + (ex.length ? ex.map(function(n, j){ return '<span class="np-chipx">' + (n.ex ? 'Ex.' + n.ex : '#' + (j + 1)) + ' · ' + fmt(n.v) + '</span>'; }).join('') : '<span class="np-meta">—</span>') + '</td><td>' +
      (LET ? '<select class="np-inp" data-qe="' + e.id + '"><option value="">—</option><option>A</option><option>B</option><option>C</option></select>' : '<input class="np-inp" data-qe="' + e.id + '" data-i="' + i + '" inputmode="decimal" placeholder="' + (nx ? 'Examen ' + nx : '—') + '" autocomplete="off">') +
      '</td><td data-st="' + e.id + '"><span class="np-meta">—</span></td></tr>';
  });
  h += '</tbody></table></div><div class="np-sticky-f"><div><b id="qeCount">0</b> note(s) prête(s) · <span id="qeBad" style="color:#ef4444"></span><div class="np-prog" style="margin-top:6px"><i id="qeProg" style="width:0"></i></div></div><div style="display:flex;gap:10px"><button class="np-btn np-btn-o" data-act="qe-clear">Vider</button><button class="np-btn np-btn-p" id="qeSave" data-act="qe-save" disabled>💾 Enregistrer tout</button></div></div></div></div>';
  return h;
}
function qeParse(raw){
  raw = String(raw == null ? '' : raw).trim();
  if (raw === '') return {empty:true};
  if (LET) { raw = raw.toUpperCase(); return ['A','B','C'].indexOf(raw) >= 0 ? {ok:true, v:raw} : {bad:true}; }
  var x = parseFloat(raw.replace(',', '.'));
  if (isNaN(x) || x < 0 || x > MX || !/^[0-9]*[.,]?[0-9]*$/.test(raw)) return {bad:true};
  return {ok:true, v:x};
}
function qeUpdate(){
  var ok = 0, bad = 0, tot = 0;
  $('npView').querySelectorAll('[data-qe]').forEach(function(inp){
    tot++; var p = qeParse(inp.value), st = $('npView').querySelector('[data-st="' + inp.getAttribute('data-qe') + '"]');
    inp.classList.remove('ok', 'bad');
    if (p.ok) { ok++; inp.classList.add('ok'); st.innerHTML = '<span class="np-badge np-up">✓ prête</span>'; }
    else if (p.bad) { bad++; inp.classList.add('bad'); st.innerHTML = '<span class="np-badge np-down">0–' + MX + ' attendu</span>'; }
    else st.innerHTML = '<span class="np-meta">—</span>';
  });
  $('qeCount').textContent = ok; $('qeBad').textContent = bad ? bad + ' valeur(s) invalide(s)' : '';
  $('qeProg').style.width = (tot ? ok / tot * 100 : 0) + '%'; $('qeSave').disabled = !(ok && !bad);
  $('qeSave').textContent = ok ? '💾 Enregistrer ' + ok + ' note' + (ok > 1 ? 's' : '') : '💾 Enregistrer tout';
}
function gridInit(){
  var v = $('npView');
  var m = $('qeMat'); if (!m) return;
  m.addEventListener('change', function(){ QE.mat = this.value; QE.sm = ''; QE.ens = (MATS[QE.mat] && MATS[QE.mat].ens) || QE.ens; refresh(true); });
  var s = $('qeSm'); if (s) s.addEventListener('change', function(){ QE.sm = this.value; refresh(true); });
  $('qeTri').addEventListener('change', function(){ QE.tri = this.value; refresh(true); });
  var en = $('qeEns'); if (en) en.addEventListener('change', function(){ QE.ens = this.value; });
  var inputs = v.querySelectorAll('[data-qe]');
  inputs.forEach(function(inp, i){
    inp.addEventListener('input', qeUpdate);
    inp.addEventListener('change', qeUpdate);
    inp.addEventListener('keydown', function(ev){
      if (ev.key === 'Enter' || ev.key === 'ArrowDown') { ev.preventDefault(); if (inputs[i + 1]) inputs[i + 1].focus(); }
      else if (ev.key === 'ArrowUp') { ev.preventDefault(); if (inputs[i - 1]) inputs[i - 1].focus(); }
    });
    inp.addEventListener('paste', function(ev){
      var t = (ev.clipboardData || window.clipboardData).getData('text');
      var parts = String(t).split(/\\r?\\n/).filter(function(x){ return x.trim() !== ''; });
      if (parts.length > 1) { ev.preventDefault(); parts.forEach(function(x, j){ if (inputs[i + j]) inputs[i + j].value = x.trim(); }); qeUpdate(); }
    });
  });
  if ($('qeCount')) qeUpdate();
}
function qeSave(){
  var entries = [];
  $('npView').querySelectorAll('[data-qe]').forEach(function(inp){ var p = qeParse(inp.value); if (p.ok) entries.push({eleve_id:+inp.getAttribute('data-qe'), note:p.v}); });
  if (!entries.length) return;
  var sm = QE.sm && SMC[QE.sm] ? ' › ' + SMC[QE.sm].nom : '';
  if (!confirm('Enregistrer ' + entries.length + ' note(s) — ' + MATS[QE.mat].nom + sm + ' — S' + QE.tri + ' ?')) return;
  var b = $('qeSave'); b.disabled = true; b.textContent = '⏳ Enregistrement…';
  fetch('/notes/bulk', {method:'POST', headers:{'Content-Type':'application/json'}, credentials:'same-origin',
    body:JSON.stringify({cycle:NP.cycle, classe_id:NP.classe_id, matiere_id:QE.mat, sous_matiere_id:QE.sm || null, trimestre:QE.tri, enseignant_id:ADMIN ? QE.ens : null, entries:entries})})
  .then(function(r){ return r.json().catch(function(){ return {ok:false, error:'Réponse invalide du serveur.'}; }); })
  .then(function(d){
    if (d.ok) { try { sessionStorage.setItem('np_toast', d.saved + ' note(s) enregistrée(s) avec succès' + (d.errors && d.errors.length ? ' (' + d.errors.length + ' ignorée(s))' : '')); } catch (e) {} location.reload(); }
    else { toast(d.error || 'Échec de l’enregistrement.', true); qeUpdate(); }
  }).catch(function(){ toast('Erreur réseau : aucune note enregistrée.', true); qeUpdate(); });
}

/* ───────── analyses ───────── */
function viewStats(){
  var rated = RALL.filter(function(r){ return r.avg != null; });
  if (!rated.length) return '<div class="np-empty"><b>📭</b>Pas encore assez de notes pour afficher des analyses.</div>';
  var buckets, cols;
  if (LET) { buckets = [['C', 0, 7], ['B', 7, 13], ['A', 13, 21]]; cols = ['#ef4444', '#eab308', '#22c55e']; }
  else { buckets = [[0, 4], [4, 8], [8, 12], [12, 16], [16, 21]].map(function(b){ return [(b[0] / DIV) + '–' + (Math.min(b[1], 20) / DIV), b[0], b[1]]; }); cols = ['#ef4444', '#f97316', '#eab308', '#22c55e', '#3b82f6']; }
  var cnt = buckets.map(function(b){ return rated.filter(function(r){ return r.avg >= b[1] && r.avg < b[2]; }).length; }), mx = Math.max.apply(null, cnt) || 1;
  var dist = '<div class="np-dist">' + buckets.map(function(b, i){ return '<div class="np-dcol"><b>' + cnt[i] + '</b><div class="np-dbar" style="height:' + Math.max(3, cnt[i] / mx * 130) + 'px;background:' + cols[i] + '"></div><span>' + b[0] + '</span></div>'; }).join('') + '</div>';
  var mrows = NP.mat.map(function(m){
    var vals = rated.map(function(r){ return r.per[m.id]; }).filter(function(x){ return x != null; });
    if (!vals.length) return '';
    var av = vals.reduce(function(a, b){ return a + b; }, 0) / vals.length;
    return '<div class="np-mrow"><b style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="' + esc(m.nom) + '">' + esc(m.nom) + '</b><div><div class="np-track"><div class="np-fill ' + tone(av) + '" style="width:' + Math.max(3, av / 20 * 100) + '%"></div></div><div class="np-meta">min ' + fmt(Math.min.apply(null, vals)) + ' · max ' + fmt(Math.max.apply(null, vals)) + ' · ' + vals.length + ' élève(s)</div></div><span class="np-cell ' + tone(av) + '">' + fmt(av) + '</span></div>';
  }).join('');
  var li = function(r, extra){ return '<div class="np-rl" data-act="open" data-id="' + r.e.id + '"><span class="np-av" style="width:38px;height:38px;border-radius:12px;font-size:.8rem;background:' + grad(r.e.id) + '">' + esc(initials(r.e)) + '</span><div style="flex:1;min-width:0"><div class="np-nm">' + esc(r.e.p) + ' ' + esc(r.e.n) + '</div><div class="np-meta">' + extra + '</div></div><span class="np-cell ' + tone(r.avg) + '">' + fmt(r.avg) + '</span></div>'; };
  var top = rated.slice().sort(function(a, b){ return b.avg - a.avg; }).slice(0, 5);
  var low = rated.filter(function(r){ return r.avg < 10; }).sort(function(a, b){ return a.avg - b.avg; }).slice(0, 5);
  var up = rated.filter(function(r){ return r.delta != null && r.delta > 0.05; }).sort(function(a, b){ return b.delta - a.delta; }).slice(0, 4);
  var dn = rated.filter(function(r){ return r.delta != null && r.delta < -0.05; }).sort(function(a, b){ return a.delta - b.delta; }).slice(0, 4);
  return '<div class="np-2c"><div class="np-panel"><div class="np-panel-h"><h3>📊 Répartition des moyennes</h3></div><div class="np-panel-b">' + dist + '</div></div>' +
    '<div class="np-panel"><div class="np-panel-h"><h3>📚 Moyenne par matière</h3></div><div class="np-panel-b">' + (mrows || '<div class="np-meta">—</div>') + '</div></div></div>' +
    '<div class="np-2c"><div class="np-panel"><div class="np-panel-h"><h3>🏆 Top 5 de la classe</h3></div><div class="np-panel-b">' + top.map(function(r, i){ return li(r, 'Rang ' + r.rank + ' sur ' + r.tot); }).join('') + '</div></div>' +
    '<div class="np-panel"><div class="np-panel-h"><h3>🚨 À accompagner</h3></div><div class="np-panel-b">' + (low.length ? low.map(function(r){ return li(r, 'Moyenne sous 10/20 · ' + r.notes.length + ' note(s)'); }).join('') : '<div class="np-meta">🎉 Aucun élève sous la moyenne.</div>') + '</div></div></div>' +
    '<div class="np-2c"><div class="np-panel"><div class="np-panel-h"><h3>↗ Plus fortes progressions S1→S2</h3></div><div class="np-panel-b">' + (up.length ? up.map(function(r){ return li(r, 'S1 ' + fmt(r.s1) + ' → S2 ' + fmt(r.s2)); }).join('') : '<div class="np-meta">Pas de progression notable.</div>') + '</div></div>' +
    '<div class="np-panel"><div class="np-panel-h"><h3>↘ Baisses à surveiller</h3></div><div class="np-panel-b">' + (dn.length ? dn.map(function(r){ return li(r, 'S1 ' + fmt(r.s1) + ' → S2 ' + fmt(r.s2)); }).join('') : '<div class="np-meta">Aucune baisse notable.</div>') + '</div></div></div>';
}

/* ───────── activité ───────── */
function viewLog(){
  var all = [];
  RVIS.forEach(function(r){ r.notes.forEach(function(n){ all.push({r:r, n:n}); }); });
  all.sort(function(a, b){ return b.n.id - a.n.id; });
  if (!all.length) return '<div class="np-empty"><b>📭</b>Aucune note à afficher.</div>';
  return '<div class="np-panel"><div class="np-panel-h"><h3>🕑 Dernières notes saisies</h3><span class="np-pill">' + all.length + ' au total</span></div><div class="np-panel-b">' +
    all.slice(0, 60).map(function(x){
      var n = x.n, t = tone(n.v);
      return '<div class="np-log"><span class="np-dot np-cell ' + t + '">' + fmt(n.v) + '</span><div style="flex:1;min-width:0"><div class="np-nm" style="cursor:pointer" data-act="open" data-id="' + x.r.e.id + '">' + esc(x.r.e.p) + ' ' + esc(x.r.e.n) + '</div><div class="np-meta">' + noteLabel(n) + ' · S' + n.t + '</div>' +
        '<div class="np-meta">' + fdate(n.d) + (n.d && n.d.length > 10 ? ' à ' + esc(n.d.slice(11, 16)) : '') + (n.ens ? ' · par ' + esc(n.ens) : '') + '</div>' + (n.mod ? '<div class="np-meta" style="color:#b45309">✏️ Modifiée' + (n.c ? ' — « ' + esc(n.c) + ' »' : '') + '</div>' : '') + '</div>' +
        (canEdit(n) ? '<button class="np-ic" data-act="edit" data-nid="' + n.id + '" data-id="' + x.r.e.id + '" title="Modifier">✏️</button>' : '') + '</div>';
    }).join('') + (all.length > 60 ? '<div class="np-meta" style="text-align:center;padding-top:12px">… et ' + (all.length - 60) + ' autres (affinez avec les filtres)</div>' : '') + '</div></div>';
}

/* ───────── fiche élève (tiroir) ───────── */
function openDrawer(eid){ DR.eid = eid; DR.tri = ST.tri; renderDrawer(); $('npOv').classList.add('on'); $('npDrawer').classList.add('on'); }
function closeAll(){ $('npDrawer').classList.remove('on'); $('npModal').classList.remove('on'); $('npOv').classList.remove('on'); $('npMenu').parentNode.classList.remove('open'); DR.eid = null; }
function renderDrawer(){
  var e = EL[DR.eid]; if (!e) return;
  var ns = e.notes.filter(function(n){ return DR.tri === 'all' || String(n.t) === String(DR.tri); });
  var a = avgOf(ns), p = profil(a.avg), r = RALL.filter(function(x){ return x.e.id === e.id; })[0];
  var by = {}; ns.forEach(function(n){ (by[n.mid] = by[n.mid] || []).push(n); });
  var chrono = ns.slice().sort(function(x, y){ return x.id - y.id; }).map(function(n){ return n.v; });
  var h = '<div class="np-dr-h"><button class="np-x" data-act="close">✕</button><div style="display:flex;gap:14px;align-items:center"><span class="np-av" style="width:56px;height:56px;font-size:1.1rem;background:' + grad(e.id) + '">' + esc(initials(e)) + '</span><div><div style="font-size:1.25rem;font-weight:800">' + esc(e.p) + ' ' + esc(e.n) + '</div><div style="opacity:.85;font-size:.82rem">' + (NP.classe ? esc(NP.classe) + ' · ' : '') + ns.length + ' note(s)' + (r && r.rank && DR.tri === ST.tri ? ' · rang ' + r.rank + '/' + r.tot : '') + '</div></div></div>' +
    '<div style="display:flex;gap:16px;align-items:center;margin-top:16px;background:rgba(255,255,255,.14);border-radius:18px;padding:12px 14px"><div class="np-ringbox" style="width:70px;height:70px;color:#fff">' + ring(a.avg, 70, 8).replace(/var\\(--np-track\\)/g, 'rgba(255,255,255,.25)') + '<div class="np-ringv"><span>' + fmt(a.avg) + '</span></div></div><div style="flex:1"><div style="font-weight:800">' + (p ? p.l : 'Aucune note') + '</div><div style="opacity:.85;font-size:.78rem">Moyenne ' + (LET ? '' : '/' + MX) + ' pondérée</div></div><div style="width:42%">' + spark(chrono, 140, 46) + '</div></div></div>' +
    '<div class="np-dr-b"><div class="np-chips" style="margin-bottom:14px"><button class="np-chip' + (DR.tri === 'all' ? ' on' : '') + '" data-act="drtri" data-v="all">Année</button><button class="np-chip' + (DR.tri === '1' ? ' on' : '') + '" data-act="drtri" data-v="1">S1</button><button class="np-chip' + (DR.tri === '2' ? ' on' : '') + '" data-act="drtri" data-v="2">S2</button></div>';
  var keys = Object.keys(by);
  if (!keys.length) h += '<div class="np-empty"><b>📭</b>Aucune note pour cette période.</div>';
  keys.forEach(function(k){
    var list = by[k].slice().sort(function(x, y){ return x.id - y.id; }), m = a.per[k];
    h += '<div class="np-mblk"><div class="np-mblk-h"><span style="flex:1">' + esc(MATS[k] ? MATS[k].nom : list[0].mat) + '</span><span class="np-cell ' + tone(m) + '">' + fmt(m) + '</span></div>' +
      list.map(function(n){
        return '<div class="np-nrow"><span class="np-cell ' + tone(n.v) + '">' + fmt(n.v) + '</span><div class="grow"><div>' + (n.sm ? esc(n.sm) + ' · ' : '') + (n.ex ? '<b>Examen ' + n.ex + '</b>' : 'Note de matière') + ' <span class="np-badge" style="padding:1px 7px">S' + n.t + '</span>' + (n.mod ? ' <span class="np-badge np-down">✏️ modifiée</span>' : '') + '</div><small>' + fdate(n.d) + (n.ens ? ' · ' + esc(n.ens) : '') + (n.mod && n.c ? ' · « ' + esc(n.c) + ' »' : '') + '</small></div>' +
          (canEdit(n) ? '<button class="np-ic" data-act="edit" data-nid="' + n.id + '" title="Modifier">✏️</button>' : (ROLE === 'enseignant' && n.eid === UID ? '<span title="Verrouillée (1 seule modification)">🔒</span>' : '')) +
          (ISADMIN ? '<button class="np-ic del" data-act="del" data-nid="' + n.id + '" title="Supprimer">🗑</button>' : '') + '</div>';
      }).join('') + '</div>';
  });
  h += '</div><div class="np-dr-f"><button class="np-btn np-btn-p" data-act="add" data-id="' + e.id + '">＋ Ajouter une note</button>' +
    (ADMIN ? '<a class="np-btn np-btn-o" href="/export/bulletin/' + e.id + '?t=1" target="_blank">📄 Bulletin S1</a><a class="np-btn np-btn-o" href="/export/bulletin/' + e.id + '?t=2" target="_blank">📄 Bulletin S2</a>' : '') + '</div>';
  $('npDrawer').innerHTML = h;
}

/* ───────── modales : ajout / modification ───────── */
function hid(n, v){ return '<input type="hidden" name="' + n + '" value="' + esc(v) + '">'; }
function openAdd(eid){
  var mat = (ST.mat && MATS[ST.mat]) ? ST.mat : (NP.mat.length === 1 ? NP.mat[0].id : '');
  var tri = ST.tri !== 'all' ? ST.tri : '1';
  var h = '<div class="np-mbox"><h3>➕ Nouvelle note</h3><p class="sub">Enregistrée immédiatement et tracée dans l’historique.</p><form method="POST" action="/notes" id="npAddForm"><div class="np-fg">' + hid('cycle', NP.cycle) + (NP.classe_id ? hid('classe_id', NP.classe_id) : '') +
    '<label class="full">Élève<select class="np-sel" name="eleve_id" id="adEl" required>' + (eid ? '' : '<option value="">— Choisir un élève —</option>') + NP.eleves.slice().sort(function(a, b){ return (a.n + a.p).localeCompare(b.n + b.p); }).map(function(e){ return '<option value="' + e.id + '"' + (String(e.id) === String(eid) ? ' selected' : '') + '>' + esc(e.n) + ' ' + esc(e.p) + '</option>'; }).join('') + '</select></label>' +
    '<label>Matière<select class="np-sel" name="matiere_id" id="adMat" required><option value="">— Choisir —</option>' + NP.mat.map(function(m){ return '<option value="' + m.id + '"' + (String(m.id) === String(mat) ? ' selected' : '') + '>' + esc(m.nom) + '</option>'; }).join('') + '</select></label>' +
    '<label id="adSmG" style="display:none">Sous-matière<select class="np-sel" name="sous_matiere_id" id="adSm"></select></label>' +
    '<label>Semestre<div class="np-seg"><label><input type="radio" name="trimestre" value="1"' + (tri === '1' ? ' checked' : '') + '><span>S1</span></label><label><input type="radio" name="trimestre" value="2"' + (tri === '2' ? ' checked' : '') + '><span>S2</span></label></div></label>' +
    '<label>' + (LET ? 'Évaluation' : 'Note (/' + MX + ')') + (LET ? '<div class="np-seg"><label><input type="radio" name="note_lettre" value="A" required><span>A</span></label><label><input type="radio" name="note_lettre" value="B"><span>B</span></label><label><input type="radio" name="note_lettre" value="C"><span>C</span></label></div>' : '<input class="np-inp" type="number" name="note" step="0.25" min="0" max="' + MX + '" required placeholder="' + (MX === 10 ? '6.5' : '12.75') + '" id="adNote">') + '</label>' +
    (ADMIN ? '<label class="full">Enseignant valideur<select class="np-sel" name="enseignant_id" id="adEns" required>' + NP.ens.map(function(t){ return '<option value="' + t.id + '">' + esc(t.nom) + '</option>'; }).join('') + '</select></label>' : '') +
    '<div class="full np-prev" id="adPrev" style="display:none"></div></div><div class="np-mf"><button type="button" class="np-btn np-btn-o" data-act="close">Annuler</button><button type="submit" class="np-btn np-btn-p">💾 Enregistrer</button></div></form></div>';
  $('npModal').innerHTML = h; $('npModal').classList.add('on'); $('npOv').classList.add('on');
  var f = $('npAddForm');
  function upd(){
    var m = $('adMat').value, l = m ? (NP.sm[m] || []) : [], sel = $('adSm'), cur = sel.value;
    if (sel.getAttribute('data-m') !== String(m)) {
      sel.innerHTML = '<option value="">— Choisir —</option>' + l.map(function(s){ return '<option value="' + s.id + '">' + esc(s.nom) + ' (coef ' + s.coefficient + ')</option>'; }).join(''); sel.setAttribute('data-m', m); cur = '';
      if (ADMIN && m && MATS[m] && MATS[m].ens && $('adEns')) $('adEns').value = MATS[m].ens;
    }
    $('adSmG').style.display = l.length ? '' : 'none'; sel.required = l.length > 0; if (!l.length) sel.value = ''; else if (cur) sel.value = cur;
    var el = $('adEl').value, tr = (f.querySelector('[name=trimestre]:checked') || {}).value, pv = $('adPrev');
    if (el && m && (sel.value || !l.length)) { pv.style.display = ''; pv.textContent = '🏷️ Sera enregistrée comme « Examen ' + nextExam(el, m, sel.value, tr) + ' » — ' + (SMC[sel.value] ? SMC[sel.value].nom : (MATS[m] ? MATS[m].nom : '')) + ' · S' + tr; } else pv.style.display = 'none';
  }
  f.addEventListener('change', upd); upd();
  f.addEventListener('submit', function(){ var b = f.querySelector('button[type=submit]'); setTimeout(function(){ b.disabled = true; b.textContent = '⏳ …'; }, 0); });
}
function openEdit(nid){
  var note = null, el = null;
  NP.eleves.forEach(function(e){ e.notes.forEach(function(n){ if (String(n.id) === String(nid)) { note = n; el = e; } }); });
  if (!note) return;
  var cur = LET ? letter(note.v) : String(r2(note.v / DIV));
  var h = '<div class="np-mbox"><h3>✏️ Modifier la note</h3><p class="sub">' + esc(el.p) + ' ' + esc(el.n) + ' · ' + noteLabel(note) + ' · S' + note.t + '</p><form method="POST" action="/notes"><div class="np-fg">' + hid('action', 'edit') + hid('note_id', note.id) + hid('cycle', NP.cycle) + (NP.classe_id ? hid('classe_id', NP.classe_id) : '') +
    (ROLE === 'enseignant' ? '<div class="full np-warn">⚠️ Vous disposez d’<b>une seule modification</b> par note. Après enregistrement, elle sera verrouillée.</div>' : '') +
    '<label>' + (LET ? 'Nouvelle évaluation' : 'Nouvelle note (/' + MX + ')') + (LET ? '<div class="np-seg">' + ['A', 'B', 'C'].map(function(x){ return '<label><input type="radio" name="note_lettre" value="' + x + '"' + (x === cur ? ' checked' : '') + '><span>' + x + '</span></label>'; }).join('') + '</div>' : '<input class="np-inp" type="number" name="note" step="0.25" min="0" max="' + MX + '" required value="' + esc(cur) + '">') + '</label>' +
    '<label class="full">Justification' + (ROLE === 'enseignant' ? ' (obligatoire)' : ' (optionnelle)') + '<input class="np-inp" type="text" name="commentaire" ' + (ROLE === 'enseignant' ? 'required' : '') + ' placeholder="Ex : erreur lors de la correction…" value="' + esc(note.c || '') + '"></label></div>' +
    '<div class="np-mf"><button type="button" class="np-btn np-btn-o" data-act="close">Annuler</button><button type="submit" class="np-btn np-btn-p">💾 Enregistrer</button></div></form></div>';
  $('npModal').innerHTML = h; $('npModal').classList.add('on'); $('npOv').classList.add('on');
}
function doDelete(nid){
  if (!confirm('Supprimer définitivement cette note ?')) return;
  var f = D.createElement('form'); f.method = 'POST'; f.action = '/notes';
  f.innerHTML = hid('action', 'delete') + hid('note_id', nid) + hid('cycle', NP.cycle) + (NP.classe_id ? hid('classe_id', NP.classe_id) : '');
  D.body.appendChild(f); f.submit();
}

/* ───────── export CSV (notes filtrées) ───────── */
function exportCsv(){
  var rows = [['Élève', 'Matière', 'Sous-matière', 'Examen', 'Semestre', 'Note (' + (LET ? 'A/B/C' : '/' + MX) + ')', 'Date', 'Enseignant', 'Modifiée', 'Commentaire']];
  RVIS.forEach(function(r){ r.notes.slice().sort(function(a, b){ return a.id - b.id; }).forEach(function(n){ rows.push([r.e.n + ' ' + r.e.p, n.mat, n.sm || '', n.ex || '', 'S' + n.t, fmt(n.v), fdate(n.d), n.ens || '', n.mod ? 'Oui' : 'Non', n.c || '']); }); });
  var csv = rows.map(function(r){ return r.map(function(c){ c = String(c == null ? '' : c); return /[";\\n]/.test(c) ? '"' + c.replace(/"/g, '""') + '"' : c; }).join(';'); }).join('\\r\\n');
  var a = D.createElement('a'); a.href = URL.createObjectURL(new Blob(['\\ufeff' + csv], {type:'text/csv;charset=utf-8'}));
  a.download = 'notes_' + (NP.classe || NP.cycle).replace(/[^A-Za-z0-9_-]+/g, '_') + '_' + new Date().toISOString().slice(0, 10) + '.csv';
  D.body.appendChild(a); a.click(); setTimeout(function(){ URL.revokeObjectURL(a.href); a.remove(); }, 500);
  toast('Export CSV prêt (' + (rows.length - 1) + ' lignes)');
}

/* ───────── événements ───────── */
D.addEventListener('click', function(ev){
  var root = $('np'); if (!root || !root.contains(ev.target)) return;
  var t = ev.target.closest('[data-act]');
  if (!ev.target.closest('.np-menu')) $('npMenu').parentNode.classList.remove('open');
  if (ev.target === $('npOv') || ev.target === $('npModal')) { closeAll(); return; }
  if (!t) return;
  var act = t.getAttribute('data-act'), id = t.getAttribute('data-id'), nid = t.getAttribute('data-nid'), v = t.getAttribute('data-v');
  if (act !== 'menu' && act !== 'export-csv') { /* défaut */ }
  if (t.tagName === 'A' && act === 'open') ev.preventDefault();
  if (act === 'view') { ST.view = v; save(); refresh(); window.scrollTo({top:0, behavior:'smooth'}); }
  else if (act === 'go-grid') { ST.view = 'grid'; save(); refresh(); }
  else if (act === 'tri') { ST.tri = v; save(); refresh(); }
  else if (act === 'reset') { ST.q = ''; ST.tri = 'all'; ST.mat = ''; ST.sm = ''; ST.statut = 'all'; ST.sort = 'name'; $('npQ').value = ''; save(); refresh(); }
  else if (act === 'sort') { ST.sort = (ST.sort === v && v === 'avg_desc') ? 'avg_asc' : v; save(); refresh(); }
  else if (act === 'open') { if (ev.target.closest('[data-act="add"]')) return; openDrawer(+id); }
  else if (act === 'add') { ev.stopPropagation(); $('npDrawer').classList.remove('on'); openAdd(id ? +id : null); }
  else if (act === 'edit') { $('npDrawer').classList.remove('on'); openEdit(nid); }
  else if (act === 'del') doDelete(nid);
  else if (act === 'close') closeAll();
  else if (act === 'drtri') { DR.tri = v; renderDrawer(); }
  else if (act === 'menu') { t.parentNode.classList.toggle('open'); }
  else if (act === 'export-csv') { exportCsv(); $('npMenu').parentNode.classList.remove('open'); }
  else if (act === 'print') { window.print(); }
  else if (act === 'qe-save') qeSave();
  else if (act === 'qe-clear') { $('npView').querySelectorAll('[data-qe]').forEach(function(i){ i.value = ''; }); qeUpdate(); }
});
D.addEventListener('keydown', function(ev){
  if (!$('np')) return;
  if (ev.key === 'Escape') closeAll();
  else if (ev.key === '/' && !/^(INPUT|TEXTAREA|SELECT)$/.test((D.activeElement || {}).tagName || '') && $('npQ') && $('npTools').style.display !== 'none') { ev.preventDefault(); $('npQ').focus(); }
});

/* ───────── démarrage ───────── */
renderHero(); renderTools(); refresh();
try { var tm = sessionStorage.getItem('np_toast'); if (tm) { sessionStorage.removeItem('np_toast'); toast(tm); } } catch (e) {}
(window.NP_FLASH || []).forEach(function(f){ toast(f[1], f[0] !== 'success'); });
})();
</script>
{% else %}
<div class="nm-desk" style="margin:24px 0;padding:22px;border-radius:16px;background:#fef2f2;color:#991b1b;border:1px solid #fecaca;">
  <b>⚠️ Impossible d'afficher les notes pour le moment.</b><br>
  Une erreur est survenue lors du chargement de cette classe. <a href="/notes?cycle={{ cycle }}{% if classe_id %}&classe_id={{ classe_id }}{% endif %}" style="color:#991b1b;font-weight:700;text-decoration:underline;">Recharger la page</a>
</div>
{% endif %}
{% else %}
  {% for cat,msg in get_flashed_messages(with_categories=true) %}
  <div class="alert nm-desk {{'alert-success' if cat=='success' else 'alert-error'}}" style="margin-bottom:20px; padding:12px; border-radius:6px; background: {{'#d4edda' if cat=='success' else '#f8d7da'}}; color: {{'#155724' if cat=='success' else '#721c24'}}; border: 1px solid {{'#c3e6cb' if cat=='success' else '#f5c6cb'}};">
    {{ msg }}
  </div>
  {% endfor %}

  {% set nb_modifiees = notes|selectattr('modifiee','equalto',1)|list|length %}
  {% set moyenne_notes = ((notes|sum(attribute='note')) / (notes|length))|round(2) if notes|length else 0 %}
  <div class="lux-hero page-notes-hero nm-desk">
    <div class="lux-hero-top">
      <div class="lux-hero-title">
        <div class="lux-hero-icon">📝</div>
        <div>
          <h2>Notes — Section {{ cycle }}</h2>
          <p>Gestion des évaluations et relevés pour ce cycle</p>
        </div>
      </div>
      <div class="lux-hero-search">
        <a href="/notes" class="btn btn-outline" style="text-decoration:none;">← Changer de cycle</a>
      </div>
    </div>
    <div class="lux-stats">
      <div class="lux-stat-pill no-click">
        <span class="dot" style="background:#fff;"></span>
        <div><div class="num">{{ notes|length }}</div><div class="lbl">Notes saisies</div></div>
      </div>
      <div class="lux-stat-pill no-click">
        <span class="dot" style="background:#30D158;"></span>
        <div><div class="num">{% if systeme == '10' %}{{ note_aff(moyenne_notes, '10') }}/10{% else %}{{ moyenne_notes }}/20{% endif %}</div><div class="lbl">Moyenne générale</div></div>
      </div>
      <div class="lux-stat-pill no-click">
        <span class="dot" style="background:#FF9F0A;"></span>
        <div><div class="num">{{ nb_modifiees }}</div><div class="lbl">Notes modifiées</div></div>
      </div>
    </div>
    <!-- 🆕 Graphiques : répartition des profils + évolution de la moyenne de classe T1→T2 -->
    <div class="lux-charts-mobile-wrap">
    <div class="lux-charts-row">
      <div class="lux-chart-card">
        <div class="lux-chart-title"><span>🧭 Répartition des profils</span></div>
        <div class="lux-chart-canvas-wrap"><canvas id="notesProfilsChart"></canvas></div>
      </div>
      <div class="lux-chart-card">
        <div class="lux-chart-title"><span>📈 Moyenne de classe — S1 → S2</span><span id="notesEvolTag"></span></div>
        <div class="lux-chart-canvas-wrap"><canvas id="notesEvolutionChart"></canvas></div>
      </div>
    </div>
    <div class="lux-charts-arrow-hint" aria-hidden="true">›</div>
    </div>
  </div>

  {% if session.role in ['admin','agent_admin','enseignant'] %}
  <div id="edit-note-box" class="card mb-20 nm-desk" style="display:none; border:1px solid var(--amber); padding:20px;">
    <h3 style="font-size:1.1rem; font-weight:700; margin-bottom:15px;">✏️ Modifier la note sélectionnée</h3>
    <form action="/notes" method="POST">
      <input type="hidden" name="action" value="edit">
      <input type="hidden" name="note_id" id="edit_note_id">
      <input type="hidden" name="cycle" value="{{ cycle }}">
      {% if classe_id %}
      <input type="hidden" name="classe_id" value="{{ classe_id }}">
      {% endif %}
      <div style="display:grid; grid-template-columns: 1fr 2fr; gap:16px;">
        <div class="form-group">
          {% if systeme == 'lettres' %}
          <label>Nouvelle évaluation *</label>
          <select name="note_lettre" id="edit_note_lettre" required style="width:100%; padding:8px; border:1px solid #ccc; border-radius:6px;">
            <option value="A">A — Bon</option>
            <option value="B">B — Moyen</option>
            <option value="C">C — Bas</option>
          </select>
          {% else %}
          <label>Nouvelle Note (/{{ 10 if systeme == '10' else 20 }}) *</label>
          <input type="number" step="0.25" min="0" max="{{ 10 if systeme == '10' else 20 }}" name="note" id="edit_note_val" required style="width:100%; padding:8px; border:1px solid #ccc; border-radius:6px;">
          {% endif %}
        </div>
        <div class="form-group">
          <label>Justification / Commentaire {% if session.role == 'enseignant' %}(Obligatoire - Une seule modification possible){% endif %} *</label>
          <input type="text" name="commentaire" id="edit_note_comm" {% if session.role == 'enseignant' %}required{% endif %} placeholder="Ex: Erreur lors de la correction..." style="width:100%; padding:8px; border:1px solid #ccc; border-radius:6px;">
        </div>
      </div>
      <div style="margin-top:15px; display:flex; gap:10px;">
        <button type="submit" class="btn btn-primary btn-sm">💾 Enregistrer</button>
        <button type="button" onclick="document.getElementById('edit-note-box').style.display='none'" class="btn btn-outline btn-sm">Annuler</button>
      </div>
    </form>
  </div>

  <div id="add-note-box" class="card mb-20 nm-desk" style="display:none; border:1px solid var(--blue-mid); padding:20px;">
    <h3 style="font-size:1.1rem; font-weight:700; margin-bottom:15px;">➕ Ajouter une note — <span id="add_note_eleve_nom" style="color:var(--gray-900); font-weight:700;"></span></h3>
    <form action="/notes" method="POST">
      <input type="hidden" name="cycle" value="{{ cycle }}">
      {% if classe_id %}
      <input type="hidden" name="classe_id" value="{{ classe_id }}">
      {% endif %}
      <input type="hidden" name="eleve_id" id="add_note_eleve_id">
      <div class="form-grid" style="display:grid; grid-template-columns:repeat(auto-fit,minmax(150px,1fr)); gap:14px;">
        <div class="form-group">
          <label>Matière *</label>
          <select name="matiere_id" id="add_note_matiere_id" onchange="majSousMatieres(this.value)" required>
            <option value="">-- Sélectionner --</option>
            {% for m in matieres %}
            <option value="{{ m.id }}">{{ m.nom }}</option>
            {% endfor %}
          </select>
        </div>
        <div class="form-group" id="add_note_sous_matiere_group" style="display:none;">
          <label>Sous-matière *</label>
          <select name="sous_matiere_id" id="add_note_sous_matiere_id">
            <option value="">-- Sélectionner --</option>
          </select>
        </div>
        {% if session.role == 'admin' %}
        <div class="form-group">
          <label>Enseignant valideur *</label>
          <select name="enseignant_id" required>
            {% for t in enseignants %}
            <option value="{{ t.id }}">{{ t.prenom }} {{ t.nom }}</option>
            {% endfor %}
          </select>
        </div>
        {% endif %}
        <div class="form-group">
          <label>Trimestre *</label>
          <select name="trimestre" required>
            <option value="1">S1</option>
            <option value="2">S2</option>
          </select>
        </div>
        <div class="form-group">
          {% if systeme == 'lettres' %}
          <label>Évaluation *</label>
          <select name="note_lettre" required>
            <option value="A">A — Bon</option>
            <option value="B">B — Moyen</option>
            <option value="C">C — Bas</option>
          </select>
          {% else %}
          <label>Note (/{{ 10 if systeme == '10' else 20 }}) *</label>
          <input type="number" step="0.25" min="0" max="{{ 10 if systeme == '10' else 20 }}" name="note" placeholder="{{ '6.5' if systeme == '10' else '12.75' }}" required>
          {% endif %}
        </div>
      </div>
      <div style="margin-top:15px; display:flex; gap:10px;">
        <button type="submit" class="btn btn-primary btn-sm">💾 Enregistrer</button>
        <button type="button" onclick="document.getElementById('add-note-box').style.display='none'" class="btn btn-outline btn-sm">Annuler</button>
      </div>
    </form>
  </div>
  {% endif %}

  <div class="nm-desk" style="display:grid; grid-template-columns: minmax(0,1fr); gap:24px; align-items:start;">

    <!-- 🆕 Recherche d'élève — juste au-dessus des cartes de notes, sous le slider d'analyses -->
    <div class="notes-search-bar">
      <span class="notes-search-icon">🔎</span>
      <input type="text" id="notesEleveSearch" placeholder="Rechercher un élève par nom ou prénom..." oninput="filtrerElevesNotes(this.value)" autocomplete="off">
    </div>

    <div class="card">
      <div class="card-header" style="display:flex; justify-content:space-between; align-items:center;">
        <span class="card-title">📋 Notes par élève ({{ cycle }})</span>
        <div style="display:flex; gap:8px;">
           <a href="/export/notes/excel?cycle={{ cycle }}{% if classe_id %}&classe_id={{ classe_id }}{% endif %}" class="btn btn-outline btn-sm">📥 Excel</a>
           <a href="/export/notes/pdf?cycle={{ cycle }}{% if classe_id %}&classe_id={{ classe_id }}{% endif %}" class="btn btn-outline btn-sm">📄 PDF</a>
        </div>
      </div>
      <div class="card-body">
        <div class="notes-eleve-grid" id="notesEleveGrid">
          {% for e in eleves %}
          {% set mes_notes = notes_par_eleve.get(e.id, []) %}
          {% set moy_e = ((mes_notes|sum(attribute='note')) / (mes_notes|length))|round(2) if mes_notes|length else None %}
          {% set profil_matiere = None %}
          {% if moy_e is not none %}
            {% set matiere_moys = [] %}
            {% for mat_nom, notes_mat in mes_notes|groupby('mat_nom') %}
              {% set _ = matiere_moys.append({'nom': mat_nom, 'moy': (notes_mat|sum(attribute='note'))/(notes_mat|length)}) %}
            {% endfor %}
            {% if systeme == 'lettres' %}
              {% set lettre_e = lettre_note(moy_e) %}
              {% if lettre_e == 'A' %}{% set profil_label, profil_emoji, profil_css = 'Bon','🟢','leader' %}
              {% elif lettre_e == 'B' %}{% set profil_label, profil_emoji, profil_css = 'Moyen','🟡','stable' %}
              {% else %}{% set profil_label, profil_emoji, profil_css = 'Bas','🔴','critique' %}
              {% endif %}
            {% else %}
              {% if moy_e < 4 %}{% set profil_label, profil_emoji, profil_css = 'Critique','🔴','critique' %}
              {% elif moy_e < 8 %}{% set profil_label, profil_emoji, profil_css = 'Fragile','🟠','fragile' %}
              {% elif moy_e < 12 %}{% set profil_label, profil_emoji, profil_css = 'Stable','🟡','stable' %}
              {% elif moy_e < 16 %}{% set profil_label, profil_emoji, profil_css = 'Leader','🟢','leader' %}
              {% else %}{% set profil_label, profil_emoji, profil_css = 'Champion','🏆','champion' %}
              {% endif %}
            {% endif %}
            {% if matiere_moys|length and systeme != 'lettres' %}
              {% set profil_matiere = (matiere_moys|sort(attribute='moy', reverse=true)|first) if profil_label in ['Stable','Leader','Champion'] else (matiere_moys|sort(attribute='moy')|first) %}
            {% endif %}
          {% endif %}
          {% set t1_notes = mes_notes|selectattr('trimestre','equalto',1)|list %}
          {% set t2_notes = mes_notes|selectattr('trimestre','equalto',2)|list %}
          {% set moy_t1 = ((t1_notes|sum(attribute='note')) / (t1_notes|length)) if t1_notes|length else None %}
          {% set moy_t2 = ((t2_notes|sum(attribute='note')) / (t2_notes|length)) if t2_notes|length else None %}
          <div class="notes-eleve-card" id="notes-card-{{ e.id }}">
            <div class="notes-eleve-head">
              <a class="notes-eleve-link" href="/eleves/{{ e.id }}" title="Voir le dossier complet de {{ e.prenom }} {{ e.nom }}">
                <div class="notes-eleve-avatar">{{ (e.prenom[0] ~ e.nom[0])|upper }}</div>
                <div class="notes-eleve-titlewrap">
                  <div class="notes-eleve-name">{{ e.prenom }} {{ e.nom }}</div>
                  <div class="notes-eleve-sub">{{ mes_notes|length }} note{{ 's' if mes_notes|length != 1 else '' }}{% if e.classe_nom %} · {{ e.classe_nom }}{% endif %}</div>
                  {% if moy_t1 is not none and moy_t2 is not none %}
                    {% if systeme == 'lettres' %}
                      {% set lt1, lt2 = lettre_note(moy_t1), lettre_note(moy_t2) %}
                      {% if lt1 != lt2 %}
                      <div class="notes-eleve-trend {{ 'up' if lt2=='A' or (lt2=='B' and lt1=='C') else 'down' if lt2=='C' or (lt2=='B' and lt1=='A') else 'flat' }}">
                        {{ lt1 }} → {{ lt2 }} vs S1
                      </div>
                      {% endif %}
                    {% else %}
                      {% set delta_e = moy_t2 - moy_t1 %}
                      <div class="notes-eleve-trend {{ 'up' if delta_e > 0.05 else 'down' if delta_e < -0.05 else 'flat' }}">
                        {{ '↗' if delta_e > 0.05 else '↘' if delta_e < -0.05 else '→' }} {{ '%+.1f'|format(delta_e / (2 if systeme == '10' else 1)) }} pt vs S1
                      </div>
                    {% endif %}
                  {% endif %}
                </div>
              </a>
              {% if moy_e is not none %}
              <div class="notes-eleve-avg">
                {% if systeme == 'lettres' %}
                <div class="v {{'high' if lettre_note(moy_e)=='A' else 'mid' if lettre_note(moy_e)=='B' else 'low'}}">{{ lettre_note(moy_e) }}</div>
                <div class="l">{{ {'A':'Bon','B':'Moyen','C':'Bas'}[lettre_note(moy_e)] }}</div>
                {% else %}
                <div class="v {{'high' if moy_e>=14 else 'mid' if moy_e>=10 else 'low'}}">{{ note_aff(moy_e, systeme) }}</div>
                <div class="l">/{{ 10 if systeme == '10' else 20 }}</div>
                {% endif %}
              </div>
              {% endif %}
              {% if session.role in ['admin','agent_admin','enseignant'] %}
              <button type="button" title="Ajouter une note pour {{ e.prenom }} {{ e.nom }}" onclick="ouvrirAjoutNote('{{ e.id }}', '{{ e.prenom }} {{ e.nom }}')"
                style="flex-shrink:0; width:26px;height:26px;border-radius:50%;border:none;cursor:pointer;background:var(--blue-mid);color:#fff;font-size:.95rem;font-weight:700;display:flex;align-items:center;justify-content:center;line-height:1;margin-left:6px;">+</button>
              {% endif %}
            </div>
            {% if moy_e is not none %}
            <div style="padding:0 14px 10px;">
              <div class="badge-profil badge-profil-{{ profil_css }}">
                {{ profil_emoji }} {{ profil_label }}
                {% if profil_matiere %}
                <span class="badge-profil-matiere">· {{ profil_matiere.nom }} ({{ '%.1f'|format(profil_matiere.moy / (2 if systeme == '10' else 1)) }}/{{ 10 if systeme == '10' else 20 }})</span>
                {% endif %}
              </div>
            </div>
            {% endif %}
            {% if mes_notes|length %}
            <div class="notes-tri-toggle">
              <button type="button" class="active" onclick="filterNotesTri(this,'{{ e.id }}','tous')">Tous</button>
              <button type="button" onclick="filterNotesTri(this,'{{ e.id }}','1')">S1</button>
              <button type="button" onclick="filterNotesTri(this,'{{ e.id }}','2')">S2</button>
            </div>
            {% endif %}
            <div class="notes-eleve-body">
              {% for n in mes_notes %}
              <div class="notes-row" data-tri="{{ n.trimestre }}">
                <div class="notes-row-info">
                  <strong>{{ n.mat_nom }}{% if n.sous_mat_nom %} <span style="font-weight:400; color:var(--gray-500);">· {{ n.sous_mat_nom }}{% if n.exam_num %} (Examen {{ n.exam_num }}){% endif %}</span>{% elif n.exam_num %} <span style="font-weight:400; color:var(--gray-500);">· Examen {{ n.exam_num }}</span>{% endif %}</strong><span class="t">S{{ n.trimestre }}</span>
                  {% if n.modifiee == 1 %}<span class="modif" title="{{ n.commentaire }}">✏️ Modifiée</span>{% endif %}
                </div>
                <div class="notes-row-right">
                  {% if systeme == 'lettres' %}
                  <span class="note-chip {{'note-high' if lettre_note(n.note)=='A' else 'note-mid' if lettre_note(n.note)=='B' else 'note-low'}}" title="{{ {'A':'Bon','B':'Moyen','C':'Bas'}[lettre_note(n.note)] }}">{{ lettre_note(n.note) }}</span>
                  {% else %}
                  <span class="note-chip {{'note-high' if n.note>=14 else 'note-mid' if n.note>=10 else 'note-low'}}">{{ note_aff(n.note, systeme) }}/{{ 10 if systeme == '10' else 20 }}</span>
                  {% endif %}
                  {% if session.role in ['admin','agent_admin','enseignant'] %}
                  <div class="notes-row-actions">
                    {% if session.role == 'enseignant' %}
                      {% if n.modifiee == 0 %}
                      <button type="button" class="ed" title="Modifier (1 seule tentative)" onclick="ouvrirEditionNote('{{ n.id }}', '{{ note_aff(n.note, systeme) }}', '{{ n.commentaire or '' }}')">✏️</button>
                      {% else %}
                      <span title="Verrouillée" style="font-size:.7rem; color:var(--red);">🔒</span>
                      {% endif %}
                    {% endif %}
                    {% if session.role == 'admin' %}
                      <button type="button" class="ed" title="Modifier" onclick="ouvrirEditionNote('{{ n.id }}', '{{ note_aff(n.note, systeme) }}', '{{ n.commentaire or '' }}')">✏️</button>
                      <form action="/notes" method="POST" onsubmit="return confirm('Supprimer définitivement cette note ?');" style="display:inline;">
                        <input type="hidden" name="action" value="delete">
                        <input type="hidden" name="note_id" value="{{ n.id }}">
                        <input type="hidden" name="cycle" value="{{ cycle }}">
                        {% if classe_id %}<input type="hidden" name="classe_id" value="{{ classe_id }}">{% endif %}
                        <button type="submit" class="de" title="Supprimer">🗑️</button>
                      </form>
                    {% endif %}
                  </div>
                  {% endif %}
                </div>
              </div>
              {% else %}
              <div class="notes-empty-card">
                <div class="big">📭</div>
                <div>Aucune note enregistrée</div>
              </div>
              {% endfor %}
            </div>
          </div>
          {% else %}
          <div class="text-muted" style="grid-column:1/-1; text-align:center; padding:30px;">Aucun élève trouvé pour la section {{ cycle }}.</div>
          {% endfor %}
        </div>
        <div class="text-muted" id="notesEleveNoMatch" style="display:none; text-align:center; padding:30px;">🔎 Aucun élève ne correspond à la recherche.</div>
      </div>
    </div>

  </div>
{% endif %}
</div>

</div></div>

<script src="https://cdnjs.cloudflare.com/ajax/libs/Chart.js/3.9.1/chart.min.js"></script>
<script>
/* 🆕 Graphiques du hero : répartition des profils + évolution de la moyenne de classe */
(function(){
    var profils = {{ profils_chart_json|safe }};
    var evolClasse = {{ evolution_classe_json|safe }};
    var labels = Object.keys(profils);
    var couleurs = { 'Critique':'#FF453A','Fragile':'#FF9F0A','Stable':'#FFD60A','Leader':'#30D158','Champion':'#0A84FF' };

    var elProfils = document.getElementById('notesProfilsChart');
    if (elProfils && labels.some(function(k){ return profils[k] > 0; })) {
        new Chart(elProfils, {
            type: 'doughnut',
            data: { labels: labels, datasets: [{ data: labels.map(function(k){ return profils[k]; }),
                backgroundColor: labels.map(function(k){ return couleurs[k]; }), borderWidth: 0 }] },
            options: {
                maintainAspectRatio: false, cutout: '62%',
                plugins: { legend: { position: 'right', labels: { color: 'rgba(255,255,255,.8)', boxWidth: 10, font: { size: 10 } } } },
            }
        });
    } else if (elProfils) {
        elProfils.parentElement.innerHTML = '<div style="display:flex;align-items:center;justify-content:center;height:100%;color:rgba(255,255,255,.5);font-size:.78rem;">Pas encore de notes</div>';
    }

    var elEvol = document.getElementById('notesEvolutionChart');
    if (elEvol) {
        new Chart(elEvol, {
            type: 'line',
            data: { labels: ['Trimestre 1', 'Trimestre 2'], datasets: [{
                data: [evolClasse.t1, evolClasse.t2], borderColor: '#0A84FF', backgroundColor: 'rgba(10,132,255,.18)',
                borderWidth: 3, fill: true, tension: .35, spanGaps: true, pointRadius: 5, pointBackgroundColor: '#0A84FF',
            }] },
            options: {
                maintainAspectRatio: false,
                plugins: { legend: { display: false } },
                scales: {
                    y: { min: 0, max: 20, ticks: { color: 'rgba(255,255,255,.6)', stepSize: 5 }, grid: { color: 'rgba(255,255,255,.08)' } },
                    x: { ticks: { color: 'rgba(255,255,255,.6)' }, grid: { display: false } },
                },
            }
        });
        var tag = document.getElementById('notesEvolTag');
        if (tag && evolClasse.t1 !== null && evolClasse.t2 !== null) {
            var delta = Math.round((evolClasse.t2 - evolClasse.t1) * 100) / 100;
            var cls = delta > 0.05 ? 'up' : (delta < -0.05 ? 'down' : 'flat');
            var arrow = delta > 0.05 ? '↗' : (delta < -0.05 ? '↘' : '→');
            tag.innerHTML = '<span class="lux-trend-tag ' + cls + '">' + arrow + ' ' + (delta > 0 ? '+' : '') + delta.toFixed(2) + '</span>';
        }
    }
})();

/* 🆕 Carte matière -> sous-matières (ex: Arabe -> Dictée, Participation...), injectée depuis le serveur */
var SOUS_MATIERES_MAP = {{ sous_matieres_json|safe }};

function majSousMatieres(matiereId) {
    var group = document.getElementById('add_note_sous_matiere_group');
    var select = document.getElementById('add_note_sous_matiere_id');
    var liste = SOUS_MATIERES_MAP[matiereId];
    select.innerHTML = '<option value="">-- Sélectionner --</option>';
    if (liste && liste.length) {
        liste.forEach(function(sm){
            var opt = document.createElement('option');
            opt.value = sm.id;
            opt.textContent = sm.nom + ' (coef ' + sm.coefficient + ')';
            select.appendChild(opt);
        });
        group.style.display = 'block';
        select.required = true;
    } else {
        group.style.display = 'none';
        select.required = false;
        select.value = '';
    }
}

function ouvrirEditionNote(id, note, commentaire) {
    document.getElementById('edit_note_id').value = id;
    var valInput = document.getElementById('edit_note_val');
    var lettreSelect = document.getElementById('edit_note_lettre');
    if (valInput) { valInput.value = note; }
    if (lettreSelect) { lettreSelect.value = note; }
    document.getElementById('edit_note_comm').value = commentaire;
    document.getElementById('add-note-box').style.display = 'none';
    document.getElementById('edit-note-box').style.display = 'block';
    window.scrollTo({top: 0, behavior: 'smooth'});
}
function ouvrirAjoutNote(eleveId, eleveNom) {
    document.getElementById('add_note_eleve_id').value = eleveId;
    document.getElementById('add_note_eleve_nom').textContent = eleveNom;
    document.getElementById('edit-note-box').style.display = 'none';
    document.getElementById('add-note-box').style.display = 'block';
    majSousMatieres(document.getElementById('add_note_matiere_id').value);
    window.scrollTo({top: 0, behavior: 'smooth'});
}

/* 🆕 Filtre par trimestre (T1 / T2 / Tous) — indépendant pour chaque carte élève */
function filterNotesTri(btn, eleveId, tri){
    var card = document.getElementById('notes-card-' + eleveId);
    if(!card) return;
    card.querySelectorAll('.notes-row').forEach(function(row){
        var match = (tri === 'tous') || (row.dataset.tri === tri);
        row.classList.toggle('tri-hidden', !match);
    });
    var toggleGroup = btn.closest('.notes-tri-toggle');
    if(toggleGroup){
        toggleGroup.querySelectorAll('button').forEach(function(b){ b.classList.remove('active'); });
    }
    btn.classList.add('active');
}

/* 🆕 Recherche d'élève (par nom/prénom) parmi les cartes de notes */
function filtrerElevesNotes(q){
    var grid = document.getElementById('notesEleveGrid');
    var noMatch = document.getElementById('notesEleveNoMatch');
    if (!grid) return;
    var needle = (q || '').trim().toLowerCase();
    var visibleCount = 0;
    grid.querySelectorAll('.notes-eleve-card').forEach(function(card){
        var nameEl = card.querySelector('.notes-eleve-name');
        var name = nameEl ? nameEl.textContent.toLowerCase() : '';
        var match = !needle || name.indexOf(needle) !== -1;
        card.style.display = match ? '' : 'none';
        if (match) visibleCount++;
    });
    if (noMatch) noMatch.style.display = (needle && visibleCount === 0) ? 'block' : 'none';
}
</script>
</body></html>"""
