ABSENCES_PROF_TABLE_HTML = """<!DOCTYPE html><html><head><title>Absences - {{ classe.nom }}</title>""" + BASE_CSS + MACOS_CSS + """
<style>
  /* 🆕 Tableau des absences enseignant : un bouton par séance (4 séances/jour : 2 le matin,
     2 l'après-midi), aucun bouton "enregistrer" — tout se fait automatiquement en AJAX
     (voir script plus bas). */
  #tbl-absences-prof thead th{ font-size:.75rem; line-height:1.3; }
  #tbl-absences-prof tbody tr:hover{ background:rgba(10,132,255,.06); }
  .absence-seance-btn{
    border:1px solid rgba(15,23,42,.12); background:rgba(52,199,89,.10); border-radius:10px;
    padding:6px 10px; cursor:pointer; transition:background-color .15s ease, border-color .15s ease;
    min-width:44px;
  }
  .absence-seance-btn:hover{ filter:brightness(0.96); }
  .absence-seance-btn.absent{ background:rgba(255,59,48,.14); border-color:rgba(255,59,48,.35); }
  .absence-seance-btn .absence-badge-abs{ display:none; }
  .absence-seance-btn.absent .absence-badge-abs{ display:inline; }
  .absence-seance-btn.absent .absence-badge-ok{ display:none; }
  .absence-badge-ok, .absence-badge-abs{ font-size:1rem; }
  .absence-eleve-av{
    width:38px; height:38px; border-radius:50%; flex-shrink:0; overflow:hidden; display:flex;
    align-items:center; justify-content:center; background:linear-gradient(160deg,#409CFF,#0A66CC);
    color:#fff; font-size:.85rem; font-weight:700;
  }
</style>
</head><body><div class="layout">
{{ nav_html|safe }}
<script>document.getElementById('page-title').textContent='Absences';</script>

<div class="container" style="padding-top:20px;">
  <div class="lux-hero">
    <div class="lux-hero-top">
      <div class="lux-hero-title">
        <div class="lux-hero-icon">📅</div>
        <div>
          <div class="cls-breadcrumb"><a href="/absences">Mes classes</a> <span>/</span> <span>{{ classe.nom }}</span></div>
          <h2>Absences — {{ classe.nom }}</h2>
          <p>Cliquez sur une séance pour marquer l'élève absent aujourd'hui ({{ jour_nom }} {{ aujourdhui }}) — recliquez pour annuler</p>
        </div>
      </div>
    </div>
  </div>

  <div class="card">
    <div class="card-header"><span class="card-title">👥 Élèves de {{ classe.nom }}</span></div>
    {% if not seances_jour %}
    <div class="empty-state">Aucun créneau prévu à l'emploi du temps pour aujourd'hui ({{ jour_nom }}).</div>
    {% else %}
    <table id="tbl-absences-prof">
      <thead><tr>
        <th>Élève</th>
        {% for s in seances_jour %}
        <th style="text-align:center;">{{ s.icone }} {{ s.titre }}<br><span class="text-muted" style="font-weight:400;">{{ s.sous }}</span></th>
        {% endfor %}
      </tr></thead>
      <tbody>
        {% for e in eleves %}
        {% set seances_absentes = absents_par_eleve.get(e.id, []) %}
        <tr data-eleve-id="{{ e.id }}">
          <td>
            <div style="display:flex; align-items:center; gap:10px;">
              <div class="absence-eleve-av">
                {% if e.photo %}<img src="/eleves/photo/{{ e.photo }}" alt="" style="width:100%;height:100%;object-fit:cover;">
                {% else %}{{ (e.prenom[0] if e.prenom else '') }}{{ (e.nom[0] if e.nom else '') }}{% endif %}
              </div>
              <strong>{{ e.nom }} {{ e.prenom }}</strong>
            </div>
          </td>
          {% for s in seances_jour %}
          <td style="text-align:center;">
            <button type="button" class="btn btn-sm absence-seance-btn {{ 'absent' if s.num in seances_absentes else '' }}"
                    data-seance="{{ s.num }}" onclick="toggleAbsenceProf(this)" title="{{ s.titre }} ({{ s.sous }})">
              <span class="absence-badge-ok">🟢</span>
              <span class="absence-badge-abs">🔴</span>
            </button>
          </td>
          {% endfor %}
        </tr>
        {% else %}
        <tr><td colspan="{{ seances_jour|length + 1 }}" class="text-muted" style="text-align:center;padding:24px;">Aucun élève dans cette classe.</td></tr>
        {% endfor %}
      </tbody>
    </table>
    {% endif %}
  </div>
</div>

<script>
// 🆕 Marque/annule l'absence d'une séance précise automatiquement au clic sur le bouton —
// aucun bouton "enregistrer" nécessaire. Un clic = absent (bouton rouge) ; un second clic
// sur la même séance = annule.
function toggleAbsenceProf(btn){
  var tr = btn.closest('tr');
  var eleveId = tr.dataset.eleveId;
  var seance = btn.dataset.seance;
  if (btn.dataset.loading === '1') return; // évite le double-clic pendant la requête en cours
  btn.dataset.loading = '1';
  fetch('/api/absences/toggle', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({eleve_id: eleveId, seance: seance})
  })
    .then(function(r){ return r.json(); })
    .then(function(data){
      if (data.error) { alert(data.error); return; }
      btn.classList.toggle('absent', data.absent);
    })
    .catch(function(){ alert("Une erreur réseau est survenue, veuillez réessayer."); })
    .finally(function(){ btn.dataset.loading = '0'; });
}
</script>
</div></div></body></html>"""


