# ─────────────────────────────────────────────
ABSENCES_MARQUER_HTML = """<!DOCTYPE html><html><head><title>Marquer une absence</title>""" + BASE_CSS + MACOS_CSS + """
<style>
.abs-entite-list{ display:flex; flex-direction:column; gap:8px; max-height:360px; overflow-y:auto; margin-top:14px; }
.abs-entite-row{ display:flex; align-items:center; gap:12px; padding:10px 14px; border:1.5px solid var(--gray-200); border-radius:10px; cursor:pointer; transition:all .15s; }
.abs-entite-row:hover{ background:var(--gray-50); }
.abs-entite-row.selected{ border-color:var(--blue); background:var(--blue-light); }
.abs-entite-row input[type=radio]{ width:18px; height:18px; accent-color:var(--blue); }
.abs-seance-picker{ display:flex; flex-wrap:wrap; gap:8px; margin-top:6px; }
.abs-seance-chip{ display:flex; align-items:center; gap:8px; padding:9px 13px; border:1.5px solid var(--gray-200); border-radius:10px; cursor:pointer; transition:all .15s; font-size:.85rem; }
.abs-seance-chip:hover{ background:var(--gray-50); }
.abs-seance-chip input{ width:auto !important; accent-color:var(--red); }
.abs-seance-chip .asc-sous{ color:var(--gray-500); font-size:.75rem; display:block; }
.abs-seance-chip.selected{ border-color:var(--red); background:var(--red-light); color:#991b1b; }
.abs-seance-chip.selected .asc-sous{ color:#991b1b; }
</style>
</head><body><div class="layout">
{{ nav_html|safe }}
<script>document.getElementById('page-title').textContent='Marquer une absence';</script>
{% for cat,msg in get_flashed_messages(with_categories=true) %}<div class="alert {{'alert-success' if cat=='success' else 'alert-error'}}">{{ msg }}</div>{% endfor %}

<div class="container" style="padding-top:20px;">
  <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px; margin-bottom:24px;">
    <div>
      <h2 style="font-size:1.5rem; font-weight:700; color:var(--gray-900);">{{ infos.icone }} Marquer un absent — {{ infos.label }}</h2>
      {% if peut_choisir_date %}
      <p class="text-muted text-sm">Par défaut, l'absence est datée d'aujourd'hui ({{ aujourdhui }}) — modifiable ci-dessous.</p>
      {% else %}
      <p class="text-muted text-sm">La date d'absence est automatiquement celle d'aujourd'hui ({{ aujourdhui }}).</p>
      {% endif %}
    </div>
    <a href="{{ url_for('absences_dashboard', type_hub=type_hub) }}" class="btn btn-outline">← Retour</a>
  </div>

  {% if peut_choisir_date %}
  <div class="card" style="margin-bottom:20px;">
    <div class="card-body">
      <form method="get" class="form-group" style="margin:0; max-width:260px;">
        {% if classe_id %}<input type="hidden" name="classe_id" value="{{ classe_id }}">{% endif %}
        {% if q %}<input type="hidden" name="q" value="{{ q }}">{% endif %}
        <label>📅 Date d'absence</label>
        <input type="date" name="date_absence" value="{{ date_absence }}" onchange="this.form.submit()">
      </form>
    </div>
  </div>
  {% endif %}

  {% if type_hub == 'eleve' %}
  <div class="card" style="margin-bottom:20px;">
    <div class="card-body">
      <div class="form-grid" style="grid-template-columns:1fr 1fr; align-items:end;">
        <form method="get" class="form-group" style="margin:0;">
          {% if date_absence %}<input type="hidden" name="date_absence" value="{{ date_absence }}">{% endif %}
          <label>1. Choisir une classe</label>
          <select name="classe_id" onchange="this.form.submit()">
            <option value="">Sélectionner une classe...</option>
            {% for c in classes %}
            <option value="{{ c.id }}" {{ 'selected' if classe_id==c.id else '' }}>{{ c.niveau }} {{ c.nom }}</option>
            {% endfor %}
          </select>
        </form>
        <form method="get" class="form-group" style="margin:0;">
          {% if date_absence %}<input type="hidden" name="date_absence" value="{{ date_absence }}">{% endif %}
          <label>OU chercher un élève par nom</label>
          <div style="display:flex; gap:8px;">
            <input type="text" name="q" value="{{ q }}" placeholder="Nom ou prénom...">
            <button type="submit" class="btn btn-outline">🔍</button>
          </div>
        </form>
      </div>
    </div>
  </div>
  {% endif %}

  <div class="card">
    <div class="card-header"><span class="card-title">2. Sélectionner la personne puis enregistrer</span></div>
    <div class="card-body">
      <form method="post" id="form-marquer-absence">
        {% if type_hub != 'eleve' %}
        <div class="form-group" style="margin-bottom:14px;">
          <label>Rechercher</label>
          <input type="text" id="abs-filtre" onkeyup="filtrerEntites()" placeholder="Filtrer par nom...">
        </div>
        {% endif %}

        <div class="abs-entite-list" id="abs-liste">
          {% for e in entites %}
          <label class="abs-entite-row" data-nom="{{ e.nom|lower }}">
            <input type="radio" name="entite_id" value="{{ e.id }}" required
                   {% if type_hub == 'enseignant' %}data-creneaux='{{ e.creneaux_json }}'{% endif %}
                   onchange="onEntiteChange(this);">
            <div>
              <div style="font-weight:600;">{{ e.nom }}</div>
              {% if e.sous_titre %}<div class="text-sm text-muted">{{ e.sous_titre }}</div>{% endif %}
            </div>
          </label>
          {% else %}
          <p class="text-muted" style="text-align:center; padding:20px;">
            {% if type_hub == 'eleve' %}Choisissez une classe ou lancez une recherche pour voir les élèves.{% else %}Aucune personne trouvée.{% endif %}
          </p>
          {% endfor %}
        </div>

        {% if type_hub == 'eleve' and seances_jour %}
        <div class="form-group" style="margin-top:20px;">
          <label>Séance(s) absente(s) — {{ jour_nom }} <span class="text-muted" style="font-weight:400;">(laisser vide = journée entière)</span></label>
          <div class="abs-seance-picker">
            {% for s in seances_jour %}
            <label class="abs-seance-chip">
              <input type="checkbox" name="seances" value="{{ s.num }}" onchange="this.closest('.abs-seance-chip').classList.toggle('selected', this.checked);">
              <span>{{ s.icone }} {{ s.titre }}<span class="asc-sous">{{ s.sous }}</span></span>
            </label>
            {% endfor %}
          </div>
        </div>
        {% elif type_hub == 'eleve' and classe_id %}
        <p class="text-muted text-sm" style="margin-top:16px;">Aucun créneau à l'emploi du temps aujourd'hui pour cette classe — l'absence sera enregistrée pour la journée entière.</p>
        {% endif %}

        {% if type_hub == 'enseignant' %}
        <!-- 🆕 Créneau(x) de l'enseignant sélectionné, remplis en JS au clic (voir data-creneaux
             ci-dessus et onEntiteChange), à partir de ses classes assignées + leur emploi du
             temps réel — même principe que pour les élèves, sans rechargement de page. -->
        <div class="form-group" id="abs-creneaux-ens-wrap" style="display:none; margin-top:20px;">
          <label>Créneau(x) absent(s) aujourd'hui <span class="text-muted" style="font-weight:400;">(laisser vide = journée entière)</span></label>
          <div class="abs-seance-picker" id="abs-creneaux-ens-picker"></div>
        </div>
        <p class="text-muted text-sm" id="abs-creneaux-ens-vide" style="display:none; margin-top:16px;">Aucun créneau à l'emploi du temps aujourd'hui pour cet enseignant (aucune classe assignée, ou emploi du temps non saisi) — l'absence sera enregistrée pour la journée entière.</p>
        {% endif %}

        <div class="form-grid" style="grid-template-columns:1fr 1fr; margin-top:20px;">
          <div class="form-group">
            <label>Date de début d'absence</label>
            <input type="text" value="{{ date_absence }}{{ ' (date du jour)' if date_absence == aujourdhui else '' }}" disabled style="background:var(--gray-50);">
            <input type="hidden" name="date_absence" value="{{ date_absence }}">
          </div>
          <div class="form-group">
            <label>Date de fin d'absence</label>
            <input type="date" name="date_fin" id="abs-date-fin" min="{{ date_absence }}" value="{{ date_absence }}" onchange="calculerJoursOuvrablesAbsence()">
            <span class="text-xs text-muted" id="abs-jours-ouvrables-calc" style="display:block;margin-top:4px;">= 1 jour ouvrable</span>
          </div>
          <div class="form-group">
            <label><input type="checkbox" name="justifiee" style="width:auto;"> Absence justifiée</label>
          </div>
          <div class="form-group" style="grid-column:1/-1;">
            <label>Motif</label>
            <textarea name="motif" placeholder="Maladie, RDV médical..."></textarea>
          </div>
        </div>
        <p class="text-muted text-sm" style="margin-top:8px;">Si l'absence dure plus d'un jour : les séances/créneaux cochés ci-dessus ne s'appliquent qu'au 1er jour ({{ date_absence }}) — les jours suivants sont automatiquement comptés en journée complète. Le nombre de jours est calculé automatiquement entre la date de début et la date de fin, en ne comptant que les jours ouvrables (week-end — samedi et dimanche — exclu).</p>
        <button type="submit" class="btn btn-primary" style="margin-top:14px;">📋 Enregistrer l'absence</button>
      </form>
    </div>
  </div>
</div>

<script>
// 🆕 Calcul en direct (aperçu côté client) du nombre de jours OUVRABLES entre la date de
// début (fixe, ci-dessus) et la date de fin choisie : le week-end (samedi + dimanche) est
// exclu du décompte, exactement comme le fait le serveur au moment de l'enregistrement.
function calculerJoursOuvrablesAbsence(){
  var span = document.getElementById('abs-jours-ouvrables-calc');
  var finInput = document.getElementById('abs-date-fin');
  if (!span || !finInput || !finInput.value) return;
  var debut = new Date('{{ date_absence }}T00:00:00');
  var fin = new Date(finInput.value + 'T00:00:00');
  if (isNaN(debut.getTime()) || isNaN(fin.getTime()) || fin < debut) {
    span.textContent = '= 1 jour ouvrable';
    return;
  }
  var nb = 1; // le 1er jour (date de début) compte toujours
  var cur = new Date(debut);
  while (cur < fin) {
    cur.setDate(cur.getDate() + 1);
    var js = cur.getDay(); // 0=dimanche ... 6=samedi
    if (js !== 0 && js !== 6) nb++;
  }
  span.textContent = '= ' + nb + ' jour' + (nb > 1 ? 's' : '') + ' ouvrable' + (nb > 1 ? 's' : '');
}
</script>

<script>
function filtrerEntites(){
  var q = document.getElementById('abs-filtre').value.toLowerCase();
  document.querySelectorAll('#abs-liste .abs-entite-row').forEach(function(row){
    row.style.display = row.dataset.nom.indexOf(q) !== -1 ? 'flex' : 'none';
  });
}

// 🆕 Sélection d'une personne dans la liste : met en surbrillance la ligne et, pour un
// enseignant, affiche instantanément (sans rechargement) les créneaux de sa journée tirés de
// data-creneaux (JSON déjà calculé côté serveur pour cet enseignant précis).
function onEntiteChange(input){
  document.querySelectorAll('.abs-entite-row').forEach(function(r){ r.classList.remove('selected'); });
  input.closest('.abs-entite-row').classList.add('selected');

  var wrap = document.getElementById('abs-creneaux-ens-wrap');
  var picker = document.getElementById('abs-creneaux-ens-picker');
  var vide = document.getElementById('abs-creneaux-ens-vide');
  if (!wrap || !picker || !vide) return; // pas la page "enseignant"

  var creneaux = [];
  try { creneaux = JSON.parse(input.dataset.creneaux || '[]'); } catch(e) { creneaux = []; }

  if (creneaux.length === 0) {
    wrap.style.display = 'none';
    picker.innerHTML = '';
    vide.style.display = 'block';
    return;
  }
  vide.style.display = 'none';
  wrap.style.display = 'block';
  picker.innerHTML = creneaux.map(function(c){
    return '<label class="abs-seance-chip">' +
      '<input type="checkbox" name="creneaux" value="' + c.id + '" onchange="this.closest(\\'.abs-seance-chip\\').classList.toggle(\\'selected\\', this.checked);">' +
      '<span>' + c.icone + ' ' + c.titre + ' — ' + c.classe + '<span class="asc-sous">' + c.sous + '</span></span>' +
      '</label>';
  }).join('');
}
</script>
</div></body></html>"""

# 🆕 ─────────────────────────────────────────────
# ABSENCES — HISTORIQUE COMPLET
# ─────────────────────────────────────────────
ABSENCES_HISTORIQUE_HTML = """<!DOCTYPE html><html><head><title>Historique des absences</title>""" + BASE_CSS + MACOS_CSS + """
<style>
.abs-hist-row{ cursor:pointer; }
.abs-hist-row:hover{ background:var(--gray-50); }
.abs-detail-item{ display:flex; align-items:center; justify-content:space-between; gap:12px; padding:10px 12px; border:1.5px solid var(--gray-200); border-radius:10px; margin-bottom:8px; }
.abs-detail-item:last-child{ margin-bottom:0; }
</style>
</head><body><div class="layout">
{{ nav_html|safe }}
<script>document.getElementById('page-title').textContent='Historique des absences';</script>
<div class="container" style="padding-top:20px;">
  <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px; margin-bottom:24px;">
    <div>
      <h2 style="font-size:1.5rem; font-weight:700; color:var(--gray-900);">{{ infos.icone }} Historique complet — {{ infos.label }}</h2>
      <p class="text-muted text-sm">{{ nb_absences_total }} absence{{ 's' if nb_absences_total > 1 else '' }} enregistrée{{ 's' if nb_absences_total > 1 else '' }}, toutes dates confondues ({{ groupes|length }} entrée{{ 's' if groupes|length > 1 else '' }} — regroupées par jour).</p>
    </div>
    <a href="{{ url_for('absences_dashboard', type_hub=type_hub) }}" class="btn btn-outline">← Retour</a>
  </div>

  <div class="card">
    <table>
      <thead><tr><th>Nom</th><th>Détail</th><th>Date</th><th>Séance(s)</th><th>Justifiée</th><th>Motif</th><th>Actions</th></tr></thead>
      <tbody>
        {% for g in groupes %}
        <tr class="abs-hist-row" onclick="ouvrirDetailGroupe(this)"
            data-nom="{{ g.nom }}" data-sous="{{ g.sous_titre or '' }}" data-date="{{ g.date_absence }}"
            data-items='{{ g.detail_json }}'>
          <td><strong>{{ g.nom }}</strong></td>
          <td class="text-sm text-muted">{{ g.sous_titre or '—' }}</td>
          <td>{{ g.date_absence }}</td>
          <td>
            {% if g.lignes|length > 1 %}
            <span class="badge badge-blue">{{ g.lignes|length }} séances</span>
            {% else %}
            {{ g.lignes[0].label }}
            {% endif %}
          </td>
          <td><span class="badge {{ 'badge-green' if g.statut_justif=='toutes' else 'badge-amber' if g.statut_justif=='mixte' else 'badge-red' }}">{{ 'Oui' if g.statut_justif=='toutes' else 'Mixte' if g.statut_justif=='mixte' else 'Non' }}</span></td>
          <td class="text-sm text-muted">{{ g.motifs_resume or '—' }}</td>
          <td onclick="event.stopPropagation();">
            {% if g.lignes|length == 1 %}
            <div class="flex gap-8">
              <button type="button" class="eleve-action-btn eleve-action-btn--edit" title="Modifier"
                      data-id="{{ g.lignes[0].id }}" data-date="{{ g.date_absence }}" data-justifiee="{{ 1 if g.lignes[0].justifiee else '' }}" data-motif="{{ g.lignes[0].motif or '' }}" data-label="{{ g.lignes[0].label }}"
                      onclick="openEditAbsence(this.dataset.id,this.dataset.date,this.dataset.justifiee,this.dataset.motif,this.dataset.label)">✏️</button>
              <form method="POST" action="{{ url_for('absences_historique_delete', type_hub=type_hub, absence_id=g.lignes[0].id) }}"
                    onsubmit="return confirm('Annuler (supprimer) cette absence ?');" style="display:inline;">
                <button type="submit" class="eleve-action-btn eleve-action-btn--delete" title="Supprimer">🗑️</button>
              </form>
            </div>
            {% else %}
            <button type="button" class="btn btn-outline btn-sm" onclick="ouvrirDetailGroupe(this.closest('tr'))">👁️ Voir détail</button>
            {% endif %}
          </td>
        </tr>
        {% else %}
        <tr><td colspan="7" class="text-muted" style="text-align:center; padding:24px;">Aucune absence enregistrée pour l'instant.</td></tr>
        {% endfor %}
      </tbody>
    </table>
  </div>

  {% if retards_ens is not none %}
  <div class="card" style="margin-top:24px;">
    <div class="card-header"><span class="card-title">⏰ Retards des enseignants ({{ retards_ens|length }}) — issus du pointage</span></div>
    <table>
      <thead><tr><th>Nom</th><th>Date</th><th>Cours</th><th>Heure prévue</th><th>Pointé à</th><th>Retard</th></tr></thead>
      <tbody>
        {% for r in retards_ens %}
        <tr>
          <td><strong>{{ r.nom }}</strong></td><td>{{ r.date_retard }}</td><td class="text-sm text-muted">{{ r.creneau or '—' }}</td>
          <td>{{ r.heure_prevue or '—' }}</td><td>{{ (r.heure_pointage or '—')[:5] }}</td>
          <td><span class="badge badge-red">{{ r.duree_minutes }} min</span></td>
        </tr>
        {% else %}
        <tr><td colspan="6" class="text-muted" style="text-align:center; padding:24px;">Aucun retard enregistré pour l'instant.</td></tr>
        {% endfor %}
      </tbody>
    </table>
  </div>
  {% endif %}
</div>

<div id="modal-edit-absence" class="modal-overlay" onclick="if(event.target===this) this.classList.remove('open')">
  <div class="modal">
    <div class="modal-header">
      <span class="modal-title">✏️ Modifier l'absence</span>
      <button type="button" class="modal-close" onclick="document.getElementById('modal-edit-absence').classList.remove('open')">×</button>
    </div>
    <form method="POST" id="form-edit-absence">
      <div class="form-grid" style="grid-template-columns:minmax(0,1fr);gap:14px;">
        <div class="form-group" id="edit-abs-seance-wrap" style="display:none;"><label>Séance / Matière</label><input id="edit-abs-seance" readonly style="background:var(--gray-50);font-weight:600;"></div>
        <div class="form-group"><label>Date</label><input type="date" name="date_absence" id="edit-abs-date" required></div>
        <div class="form-group"><label class="flex gap-8" style="align-items:center;"><input type="checkbox" name="justifiee" id="edit-abs-justifiee" style="width:auto;"> Absence justifiée</label></div>
        <div class="form-group"><label>Motif</label><input name="motif" id="edit-abs-motif"></div>
        <div class="flex gap-12">
          <button type="submit" class="btn btn-primary">💾 Sauvegarder</button>
          <button type="button" onclick="document.getElementById('modal-edit-absence').classList.remove('open')" class="btn btn-outline">Annuler</button>
        </div>
      </div>
    </form>
  </div>
</div>

<!-- 🆕 Modal de détail d'un groupe (plusieurs séances absentées le même jour) : chaque
     séance est listée séparément avec ses propres boutons Modifier / Supprimer. -->
<div id="modal-detail-groupe" class="modal-overlay" onclick="if(event.target===this) this.classList.remove('open')">
  <div class="modal">
    <div class="modal-header">
      <span class="modal-title" id="detail-groupe-titre">📅 Détail de l'absence</span>
      <button type="button" class="modal-close" onclick="document.getElementById('modal-detail-groupe').classList.remove('open')">×</button>
    </div>
    <div id="detail-groupe-liste"></div>
  </div>
</div>

<!-- 🆕 Formulaire caché réutilisé pour supprimer une séance depuis le modal de détail. -->
<form method="POST" id="form-delete-absence-detail" style="display:none;"></form>

<script>
function openEditAbsence(id, date, justifiee, motif, label) {
  var wrap = document.getElementById('edit-abs-seance-wrap');
  if (label && label !== 'Journée entière') {
    document.getElementById('edit-abs-seance').value = label;
    wrap.style.display = '';
  } else {
    wrap.style.display = 'none';
  }
  document.getElementById('form-edit-absence').action = '/absences/historique/{{ type_hub }}/' + id + '/edit';
  document.getElementById('edit-abs-date').value = date;
  document.getElementById('edit-abs-justifiee').checked = !!justifiee;
  document.getElementById('edit-abs-motif').value = motif;
  document.getElementById('modal-edit-absence').classList.add('open');
}

function supprimerAbsenceDetail(id) {
  if (!confirm('Annuler (supprimer) cette absence ?')) return;
  var form = document.getElementById('form-delete-absence-detail');
  form.action = '/absences/historique/{{ type_hub }}/' + id + '/delete';
  form.submit();
}

function ouvrirDetailGroupe(tr) {
  var nom = tr.dataset.nom, sous = tr.dataset.sous, date = tr.dataset.date;
  var items = JSON.parse(tr.dataset.items);
  document.getElementById('detail-groupe-titre').textContent = '📅 ' + nom + (sous ? ' — ' + sous : '') + ' — ' + date;
  var liste = document.getElementById('detail-groupe-liste');
  liste.innerHTML = '';
  items.forEach(function(it){
    var div = document.createElement('div');
    div.className = 'abs-detail-item';
    var badgeClass = it.justifiee ? 'badge-green' : 'badge-red';
    var badgeTxt = it.justifiee ? 'Justifiée' : 'Non justifiée';
    div.innerHTML =
      '<div>' +
        '<div style="font-weight:600;">' + it.label + '</div>' +
        '<div class="text-sm text-muted">' + (it.motif || '—') + '</div>' +
      '</div>' +
      '<div class="flex gap-8" style="align-items:center;">' +
        '<span class="badge ' + badgeClass + '">' + badgeTxt + '</span>' +
        '<button type="button" class="eleve-action-btn eleve-action-btn--edit" title="Modifier">✏️</button>' +
        '<button type="button" class="eleve-action-btn eleve-action-btn--delete" title="Supprimer">🗑️</button>' +
      '</div>';
    div.querySelector('.eleve-action-btn--edit').addEventListener('click', function(){
      openEditAbsence(it.id, date, it.justifiee ? 1 : '', it.motif || '', it.label || '');
    });
    div.querySelector('.eleve-action-btn--delete').addEventListener('click', function(){
      supprimerAbsenceDetail(it.id);
    });
    liste.appendChild(div);
  });
  document.getElementById('modal-detail-groupe').classList.add('open');
}
</script>
</div></body></html>"""

TRANSPORT_ABSENCES_HISTORIQUE_HTML = """<!DOCTYPE html><html><head><title>Historique des absences transport</title>""" + BASE_CSS + MACOS_CSS + """</head><body><div class="layout">
{{ nav_html|safe }}
<script>document.getElementById('page-title').textContent='Absences transport';</script>
{% for cat,msg in get_flashed_messages(with_categories=true) %}<div class="alert {{'alert-success' if cat=='success' else 'alert-error'}}">{{ msg }}</div>{% endfor %}

<div class="container" style="padding-top:20px;">
  <div style="display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px; margin-bottom:24px;">
    <div>
      <h2 style="font-size:1.5rem; font-weight:700; color:var(--gray-900);">🚌 Historique des absences transport — {{ chauffeur.prenom }} {{ chauffeur.nom }}</h2>
      <p class="text-muted text-sm">{{ eleves_trajet|length }} élève{{ 's' if eleves_trajet|length > 1 else '' }} sur ce trajet — {{ 'du ' + date_debut + ' au ' + date_fin if date_debut != date_fin else 'le ' + date_debut }}.</p>
    </div>
    {% if session.role == 'admin' %}
      <a href="{{ url_for('personnel_hors_prof_detail', personnel_id=personnel_id) if personnel_id else url_for('personnel_hors_prof') }}" class="btn btn-outline">← Retour</a>
    {% else %}
      <a href="{{ url_for('espace_chauffeur') }}" class="btn btn-outline">← Retour</a>
    {% endif %}
  </div>

  <!-- 🆕 Filtres : élève + période -->
  <div class="card" style="margin-bottom:16px;">
    <div class="card-body">
      <form method="GET" class="phd-toolbar" style="align-items:flex-end;">
        {% if personnel_id %}<input type="hidden" name="personnel_id" value="{{ personnel_id }}">{% endif %}
        <div class="form-group">
          <label>👤 Élève</label>
          <select name="eleve_id">
            <option value="">Tous les élèves</option>
            {% for e in eleves_trajet %}
            <option value="{{ e.id }}" {% if eleve_filtre == e.id|string %}selected{% endif %}>{{ e.prenom }} {{ e.nom }}</option>
            {% endfor %}
          </select>
        </div>
        <div class="form-group">
          <label>📅 Du</label>
          <input type="date" name="date_debut" value="{{ date_debut }}">
        </div>
        <div class="form-group">
          <label>📅 Au</label>
          <input type="date" name="date_fin" value="{{ date_fin }}">
        </div>
        <button type="submit" class="btn btn-primary btn-sm">🔎 Filtrer</button>
        {% if eleve_filtre or date_debut != aujourdhui or date_fin != aujourdhui %}
        <a href="{{ url_for('transport_absences_historique', chauffeur_id=chauffeur.id, personnel_id=personnel_id) }}" class="btn btn-outline btn-sm">✖ Réinitialiser</a>
        {% endif %}
      </form>
    </div>
  </div>

  <div class="card">
    <table>
      <thead><tr><th>Nom complet</th><th>🌅 Matin</th><th>⏱️ Heure pointage matin</th><th>🌇 Après-midi</th><th>⏱️ Heure pointage après-midi</th><th>📅 Date de pointage</th></tr></thead>
      <tbody>
        {% for l in lignes %}
        <tr>
          <td><strong>{{ l.prenom }} {{ l.nom }}</strong></td>
          <td>
            {% if l.matin and l.matin.statut == 'absent' %}<span class="badge" style="background:#FDECEA;color:#C62828;">❌ Absent</span>
            {% elif l.matin and l.matin.statut == 'present' %}<span class="badge" style="background:#E8F5E9;color:#2E7D32;">✅ Présent</span>
            {% else %}<span class="badge" style="background:#F5F5F5;color:#757575;">⏳ À renseigner</span>{% endif %}
          </td>
          <td class="text-sm">{{ l.heure_matin[11:16] if l.heure_matin else '—' }}</td>
          <td>
            {% if l.soir and l.soir.statut == 'absent' %}<span class="badge" style="background:#FDECEA;color:#C62828;">🚫 Pas présent au transport</span>
            {% elif l.soir and l.soir.statut == 'present' %}<span class="badge" style="background:#E8F5E9;color:#2E7D32;">🚌 Monté au transport</span>
            {% else %}<span class="badge" style="background:#F5F5F5;color:#757575;">⏳ À renseigner</span>{% endif %}
          </td>
          <td class="text-sm">{{ l.heure_soir[11:16] if l.heure_soir else '—' }}</td>
          <td class="text-sm">{{ l.jour }}</td>
        </tr>
        {% else %}
        <tr><td colspan="6" class="text-muted" style="text-align:center; padding:24px;">Aucun élève assigné à ce trajet.</td></tr>
        {% endfor %}
      </tbody>
    </table>
  </div>
</div>
</div></body></html>"""


NOTIF_HTML = """<!DOCTYPE html><html><head><title>Notifications</title>""" + BASE_CSS + MACOS_CSS + """
<style>
/* 🆕 Notifications séparées par catégorie : Paiements / Devoirs / Communications / Messages / Notes / Autres */
.notif-list{display:flex;flex-direction:column;}
.notif-row{--c:#64748B;position:relative;padding:14px 22px 14px 20px;border-bottom:1px solid var(--gray-100);display:flex;gap:12px;align-items:flex-start;border-left:4px solid var(--c);}
.notif-row:last-child{border-bottom:none;}
.notif-row.unread{background:color-mix(in srgb,var(--c) 8%,var(--card-bg,#fff));}
.notif-row-ico{flex:0 0 38px;width:38px;height:38px;border-radius:13px;display:flex;align-items:center;justify-content:center;font-size:1.1rem;background:color-mix(in srgb,var(--c) 15%,transparent);}
.notif-row-main{flex:1;min-width:0;}
.notif-date{font-size:.72rem;color:var(--gray-500);white-space:nowrap;margin-top:4px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;}
.notif-new{font-size:.62rem;font-weight:800;letter-spacing:.04em;text-transform:uppercase;padding:2px 8px;border-radius:99px;color:#fff;background:var(--c);}
.notif-message{font-size:.9rem;color:var(--gray-900);line-height:1.45;word-break:break-word;}
.nt-chips{display:flex;gap:8px;overflow-x:auto;padding:4px 2px 14px;scrollbar-width:none;-webkit-overflow-scrolling:touch;}
.nt-chips::-webkit-scrollbar{display:none;}
.nt-chip{--c:#4F46E5;position:relative;flex:0 0 auto;display:inline-flex;align-items:center;gap:6px;padding:9px 15px;border-radius:99px;font-family:inherit;font-size:.82rem;font-weight:700;cursor:pointer;white-space:nowrap;color:var(--gray-900,#111);background:color-mix(in srgb,var(--c) 9%,transparent);border:1px solid color-mix(in srgb,var(--c) 28%,transparent);-webkit-tap-highlight-color:transparent;}
.nt-chip b{min-width:20px;height:20px;padding:0 6px;border-radius:99px;display:inline-flex;align-items:center;justify-content:center;font-size:.7rem;background:color-mix(in srgb,var(--c) 18%,transparent);}
.nt-chip.on{color:#fff;border-color:transparent;background:var(--c);box-shadow:0 10px 18px -10px var(--c);}
.nt-chip.on b{background:rgba(255,255,255,.28);}
.nt-chip .nt-dot{position:absolute;top:-2px;right:-2px;width:10px;height:10px;border-radius:50%;background:#EF4444;border:2px solid var(--card-bg,#fff);}
.nt-sec{--c:#64748B;margin-bottom:16px;overflow:hidden;}
.nt-sec.is-empty{display:none;}
.nt-sec-head{display:flex;align-items:center;gap:12px;padding:14px 20px;color:#fff;background:radial-gradient(circle at 95% -20%,rgba(255,255,255,.35),transparent 55%),linear-gradient(135deg,var(--c),color-mix(in srgb,var(--c) 60%,#000));}
.nt-sec-ico{flex:0 0 40px;width:40px;height:40px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.3rem;background:rgba(255,255,255,.24);box-shadow:inset 0 0 0 1px rgba(255,255,255,.35);}
.nt-sec-title{font-weight:800;font-size:1rem;letter-spacing:-.01em;}
.nt-sec-sub{font-size:.72rem;opacity:.85;}
.nt-count{margin-left:auto;padding:4px 12px;border-radius:99px;font-size:.78rem;font-weight:800;background:rgba(255,255,255,.24);}
.nt-empty{text-align:center;color:var(--gray-500);padding:32px 16px;font-size:.88rem;}
@media(max-width:480px){.notif-row{padding:12px 14px 12px 12px;gap:10px;}.nt-sec-head{padding:12px 14px;}}
</style>
</head><body><div class="layout">
{{ nav_html|safe }}
<script>document.getElementById('page-title').textContent='Notifications';</script>
<div class="nt-chips" id="ntChips">
  <button type="button" class="nt-chip on" data-k="all" style="--c:#4F46E5">🔔 Toutes <b>{{ total }}</b>{% if total_non_lues %}<i class="nt-dot"></i>{% endif %}</button>
  {% for g in groupes %}<button type="button" class="nt-chip" data-k="{{ g.key }}" style="--c:{{ g.color }}">{{ g.icone }} {{ g.label }} <b>{{ g.liste|length }}</b>{% if g.non_lues %}<i class="nt-dot"></i>{% endif %}</button>{% endfor %}
</div>
{% if total == 0 %}<div class="card"><div class="nt-empty">Aucune notification.</div></div>{% endif %}
{% for g in groupes %}
<div class="card nt-sec{{ ' is-empty' if not g.liste else '' }}" data-k="{{ g.key }}" style="--c:{{ g.color }}">
  <div class="nt-sec-head">
    <span class="nt-sec-ico">{{ g.icone }}</span>
    <div><div class="nt-sec-title">{{ g.label }}</div><div class="nt-sec-sub">{{ g.non_lues }} nouvelle{{ 's' if g.non_lues > 1 else '' }}</div></div>
    <span class="nt-count">{{ g.liste|length }}</span>
  </div>
  <div class="notif-list">{% for n in g.liste %}
    <div class="notif-row {{ 'unread' if not n.lu else '' }}">
      <span class="notif-row-ico">{{ g.icone }}</span>
      <div class="notif-row-main">
        <div class="notif-message">{{ n.message }}</div>
        <div class="notif-date"><span>{{ n.created_at[:16] }}</span>{% if not n.lu %}<span class="notif-new">Nouveau</span>{% endif %}</div>
      </div>
    </div>
  {% else %}<div class="nt-empty">Aucune notification de ce type.</div>{% endfor %}</div>
</div>
{% endfor %}
<script>
(function(){
  var chips = document.querySelectorAll('#ntChips .nt-chip');
  var secs = document.querySelectorAll('.nt-sec');
  function apply(k){
    chips.forEach(function(c){ c.classList.toggle('on', c.getAttribute('data-k') === k); });
    secs.forEach(function(s){
      var isEmpty = s.classList.contains('is-empty');
      if(k === 'all'){ s.style.display = isEmpty ? 'none' : ''; }
      else { s.style.display = (s.getAttribute('data-k') === k) ? 'block' : 'none'; }
    });
  }
  chips.forEach(function(c){ c.addEventListener('click', function(){ apply(c.getAttribute('data-k')); }); });
})();
</script>
</div></div></div></body></html>"""

PROFILE_HTML = """<!DOCTYPE html><html><head><title>Profil</title>""" + BASE_CSS + MACOS_CSS + ENS_PAGES_CSS + """</head><body class="{% if session.role == 'enseignant' %}em-t{% endif %}"><div class="layout">
{{ nav_html|safe }}
<script>document.getElementById('page-title').textContent='Mon profil';</script>
{% for cat,msg in get_flashed_messages(with_categories=true) %}<div class="alert {{'alert-success' if cat=='success' else 'alert-error'}}">{{ msg }}</div>{% endfor %}
{% if session.role == 'enseignant' %}
<!-- 🆕 ENSEIGNANT (mobile) — profil &amp; options : même design que le dashboard mobile. Masqué sur ordinateur. -->
<div class="em-root" id="emProfil">
  <div class="em-hero">
    <div class="em-top">
      <div style="min-width:0;">
        <div class="em-greet">Mon compte</div>
        <div class="em-name">{{ user.prenom }} {{ user.nom }}</div>
        <div class="em-date">🧑‍🏫 Enseignant · {{ user.email }}</div>
      </div>
      <form class="em-photo" action="/profile/photo" method="POST" enctype="multipart/form-data">
        <label>{{ avatar(user.photo, user.prenom, user.nom, 64) }}<span class="em-cam">📷</span>
          <input type="file" name="photo" accept=".jpg,.jpeg,.png,.webp" style="display:none;" onchange="this.form.submit()">
        </label>
      </form>
    </div>
    <div class="em-pills">
      <a class="em-pill" href="/notifications">🔔 {{ notif_count or 0 }} notification{{ 's' if (notif_count or 0) > 1 else '' }}</a>
      {% if user.photo %}<span class="em-pill">📷 Photo de profil définie</span>{% endif %}
    </div>
  </div>

  <div class="em-sec">
    <div class="em-sec-h"><h3>Mes informations</h3></div>
    <div class="em-box">
      <form method="post" class="em-form">
        <div class="em-f"><label>Prénom</label><input name="prenom" value="{{ user.prenom }}" required autocomplete="given-name"></div>
        <div class="em-f"><label>Nom</label><input name="nom" value="{{ user.nom }}" required autocomplete="family-name"></div>
        <div class="em-f"><label>Email</label><input type="email" name="email" value="{{ user.email }}" required autocomplete="email"></div>
        <details class="em-more">
          <summary>🔒 Changer mon mot de passe <span>▾</span></summary>
          <div style="display:grid;gap:12px;">
            <div class="em-f"><label>Ancien mot de passe</label><input type="password" name="old_password" autocomplete="current-password"></div>
            <div class="em-f"><label>Nouveau mot de passe</label><input type="password" name="new_password" minlength="6" autocomplete="new-password"></div>
            <div class="em-empty" style="padding:0;text-align:left;">Laissez vide pour ne pas changer le mot de passe.</div>
          </div>
        </details>
        <button type="submit" class="em-btn pri full">💾 Sauvegarder</button>
      </form>
      {% if user.photo %}
      <form action="/profile/photo" method="POST" style="padding:0 14px 14px;margin:0;" onsubmit="return confirm('Retirer votre photo de profil ?');">
        <input type="hidden" name="supprimer" value="1">
        <button type="submit" class="em-btn sec full">🗑️ Retirer ma photo</button>
      </form>
      {% endif %}
    </div>
  </div>

  <div class="em-sec">
    <div class="em-sec-h"><h3>Options</h3></div>
    <div class="em-box em-list">
      <button type="button" class="em-opt" onclick="emToggleTheme()">
        <span class="em-row-i" style="background:rgba(99,102,241,.15)">🌙</span>
        <span class="em-opt-b"><b>Thème sombre néon</b><small>Basculer entre le thème clair et néon</small></span>
        <span class="em-sw" id="emThemeSw"></span>
      </button>
      <div class="em-opt" style="cursor:default;">
        <span class="em-row-i" style="background:rgba(14,165,233,.15)">🌐</span>
        <span class="em-opt-b"><b>Langue</b><small>Langue d'affichage de l'application</small></span>
        <span class="em-seg"><a href="/set-language/fr" class="{{ 'on' if lang != 'ar' else '' }}">FR</a><a href="/set-language/ar" class="{{ 'on' if lang == 'ar' else '' }}">العربية</a></span>
      </div>
      <a class="em-opt" href="/notifications">
        <span class="em-row-i" style="background:rgba(245,158,11,.16)">🔔</span>
        <span class="em-opt-b"><b>Notifications</b><small>Alertes et rappels de l'école</small></span>
        {% if notif_count %}<span class="em-badge">{{ notif_count }}</span>{% endif %}
        <span class="em-go">›</span>
      </a>
      <button type="button" class="em-opt" id="emInstall" style="display:none;">
        <span class="em-row-i" style="background:rgba(34,197,94,.16)">📲</span>
        <span class="em-opt-b"><b>Installer l'application</b><small>Ajouter l'espace enseignant à l'écran d'accueil</small></span>
        <span class="em-go">›</span>
      </button>
    </div>
  </div>

  <div class="em-sec">
    <div class="em-sec-h"><h3>Raccourcis</h3></div>
    <div class="em-box em-list">
      <a class="em-opt" href="/formation"><span class="em-row-i" style="background:rgba(71,85,105,.16)">🎓</span><span class="em-opt-b"><b>Mes formations</b><small>Formations à passer et progression</small></span><span class="em-go">›</span></a>
      <a class="em-opt" href="/conges"><span class="em-row-i" style="background:rgba(20,184,166,.16)">🌴</span><span class="em-opt-b"><b>Mes congés</b><small>Demandes et suivi</small></span><span class="em-go">›</span></a>
      <a class="em-opt" href="/messages"><span class="em-row-i" style="background:rgba(225,29,72,.14)">✉️</span><span class="em-opt-b"><b>Messages</b><small>Parents et administration</small></span><span class="em-go">›</span></a>
      <a class="em-opt" href="/espace-enseignant"><span class="em-row-i" style="background:rgba(124,58,237,.16)">🏫</span><span class="em-opt-b"><b>Mon espace enseignant</b><small>Planning, classes, matières</small></span><span class="em-go">›</span></a>
    </div>
  </div>

  <div class="em-sec">
    <a class="em-btn dng full" href="/logout">⎋ Se déconnecter</a>
  </div>
</div>
<script>
(function(){
  var sw=document.getElementById('emThemeSw'), ins=document.getElementById('emInstall');
  function sync(){ if(sw){ sw.classList.toggle('on', document.documentElement.classList.contains('theme-neon')); } }
  window.emToggleTheme=function(){ var t=document.getElementById('theme-toggle-fab'); if(t){ t.click(); } setTimeout(sync,80); };
  sync();
  function chk(){ var b=document.getElementById('ensInstall'); if(ins && b && b.style.display==='block'){ ins.style.display='flex'; } }
  if(ins){ ins.addEventListener('click',function(){ var b=document.getElementById('ensInstall'); if(b){ b.click(); } }); }
  chk(); setTimeout(chk,800); setTimeout(chk,2500);
  window.addEventListener('beforeinstallprompt',function(){ setTimeout(chk,60); });
})();
</script>
{% endif %}
<div class="lux-hero{% if session.role == 'enseignant' %} em-old{% endif %}">
  <div class="lux-hero-top">
    <div class="lux-hero-title">
      <div class="lux-hero-icon">⚙️</div>
      <div>
        <h2>Mon profil</h2>
        <p>Gérez vos informations personnelles et votre mot de passe</p>
      </div>
    </div>
  </div>
</div>
<div class="card{% if session.role == 'enseignant' %} em-old{% endif %}" style="max-width:560px">
  <div class="card-header"><span class="card-title">⚙️ Mon profil</span></div>
  <div class="card-body">
    <div style="display:flex;align-items:center;gap:18px;flex-wrap:wrap;margin-bottom:20px;">
      {{ avatar(user.photo, user.prenom, user.nom, 96) }}
      <div>
        <form action="/profile/photo" method="POST" enctype="multipart/form-data" style="display:inline-block;margin:0 6px 6px 0;">
          <label class="btn btn-outline btn-sm" style="cursor:pointer;">📷 {{ 'Changer la photo' if user.photo else 'Ajouter une photo' }}
            <input type="file" name="photo" accept=".jpg,.jpeg,.png,.webp" style="display:none;" onchange="this.form.submit()">
          </label>
        </form>
        {% if user.photo %}
        <form action="/profile/photo" method="POST" style="display:inline-block;margin:0;" onsubmit="return confirm('Retirer votre photo de profil ?');">
          <input type="hidden" name="supprimer" value="1">
          <button type="submit" class="btn btn-outline btn-sm">🗑️ Retirer</button>
        </form>
        {% endif %}
      </div>
    </div>
    <form method="post">
      <div class="form-grid">
        <div class="form-group"><label>Nom *</label><input name="nom" value="{{ user.nom }}" required></div>
        <div class="form-group"><label>Prénom *</label><input name="prenom" value="{{ user.prenom }}" required></div>
        <div class="form-group" style="grid-column:1/-1"><label>Email *</label><input type="email" name="email" value="{{ user.email }}" required></div>
      </div>
      <hr style="margin:20px 0;border-color:var(--gray-200)">
      <p class="text-sm text-muted mb-20" style="margin-bottom:12px">Laissez vide pour ne pas changer le mot de passe :</p>
      <div class="form-grid">
        <div class="form-group"><label>Ancien mot de passe</label><input type="password" name="old_password"></div>
        <div class="form-group"><label>Nouveau mot de passe</label><input type="password" name="new_password" minlength="6"></div>
      </div>
      <button type="submit" class="btn btn-primary mt-20">💾 Sauvegarder</button>
    </form>
  </div>
</div>

{% if session.role == 'admin' %}
<!-- 🆕 Système de notation par cycle (admin) -->
<div class="card" style="max-width:560px; margin-top:20px;">
  <div class="card-header"><h3>🎓 Système de notation par cycle</h3></div>
  <div class="card-body">
    <p style="font-size:.85rem;color:var(--gray-500);line-height:1.6;margin-bottom:14px;">Choisissez comment les notes sont saisies, affichées et calculées pour chaque cycle. Les moyennes et classements suivent automatiquement le système choisi.</p>
    <form method="post">
      <input type="hidden" name="action" value="systemes_notes">
      {% for c in cycles_systemes %}
      <div class="form-group" style="display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;">
        <label style="margin:0;font-weight:700;">{{ c.icone }} {{ c.nom }}</label>
        <select name="systeme_{{ c.id }}" style="min-width:230px;">
          {% for k, lib in systemes_notes.items() %}<option value="{{ k }}" {{ 'selected' if c.systeme == k else '' }}>{{ lib }}</option>{% endfor %}
        </select>
      </div>
      {% endfor %}
      <button type="submit" class="btn btn-primary" style="margin-top:8px;">💾 Enregistrer</button>
    </form>
  </div>
</div>

<!-- 🆕 Identité visuelle de l'école — réservé à l'admin. Le logo remplace le texte "ecole
     test" en haut de la barre latérale, sur toute l'application. -->
<div class="card" style="max-width:560px; margin-top:20px;">
  <div class="card-header"><span class="card-title">🏫 Identité de l'école</span></div>
  <div class="card-body">
    <!-- 🆕 Nom de l'école : affiché partout dans l'application (menu, titres, PDF, notifications, WhatsApp...) -->
    <form action="/parametres/nom-ecole" method="POST" style="margin-bottom:20px; padding-bottom:18px; border-bottom:1px solid var(--gray-200);">
      <div class="form-group" style="margin-bottom:10px;">
        <label>Nom de l'école</label>
        <input type="text" name="nom_ecole" value="{{ nom_ecole_val }}" maxlength="80" required placeholder="Ex : Établissement Paul Gauguin">
      </div>
      <div class="form-group" style="margin-bottom:10px;">
        <label>Nom de l'école en arabe (facultatif)</label>
        <input type="text" name="nom_ecole_ar" value="{{ nom_ecole_ar_val }}" maxlength="80" dir="rtl" placeholder="{{ nom_ecole_ar_defaut }}">
      </div>
      <button type="submit" class="btn btn-primary btn-sm">💾 Enregistrer le nom</button>
      <p class="text-xs text-muted" style="margin-top:8px;">Ce nom remplace l'ancien partout dans l'application : menu, titres des pages, PDF, notifications et messages WhatsApp. Sans nom en arabe, les messages arabes utilisent le nom ci-dessus.</p>
    </form>
    <p class="text-sm text-muted" style="margin-bottom:16px;">
      Ce logo remplace le nom de l'école en haut du menu, sur toutes les pages et pour tous les comptes.
    </p>
    {% if logo_filename %}
    <div style="display:flex; align-items:center; gap:16px; margin-bottom:18px; padding:14px; background:var(--gray-50); border-radius:12px; border:1px solid var(--gray-200);">
      <img src="/logo-ecole" alt="Logo actuel" style="max-height:56px; max-width:180px; object-fit:contain;">
      <div style="margin-left:auto;">
        <form action="/parametres/logo/supprimer" method="POST" onsubmit="return confirm('Supprimer le logo et revenir à l\'affichage par défaut ?');">
          <button type="submit" class="btn btn-outline btn-sm">🗑️ Supprimer</button>
        </form>
      </div>
    </div>
    {% endif %}
    <form action="/parametres/logo/upload" method="POST" enctype="multipart/form-data" style="display:flex; gap:10px; align-items:center; flex-wrap:wrap;">
      <input type="file" name="logo" accept=".png,.jpg,.jpeg,.svg,.webp" required>
      <button type="submit" class="btn btn-primary btn-sm">⬆️ {{ 'Remplacer' if logo_filename else 'Uploader le logo' }}</button>
    </form>
    <p class="text-xs text-muted" style="margin-top:10px;">Formats acceptés : PNG, JPG, SVG, WEBP. Un fond transparent ou blanc donne le meilleur rendu.</p>
  </div>
</div>

<!-- 🆕 Bannière du bulletin PDF — réservée à l'admin. Remplace le bandeau bleu marine dessiné
     en haut du bulletin scolaire (export PDF) par une photo/bannière propre à l'école. -->
<div class="card" style="max-width:560px; margin-top:20px;">
  <div class="card-header"><span class="card-title">🖼️ Bannière du bulletin PDF</span></div>
  <div class="card-body">
    <p class="text-sm text-muted" style="margin-bottom:16px;">
      Cette photo remplace le bandeau bleu marine en haut du bulletin scolaire (PDF téléchargé), pour tous les élèves.
    </p>
    {% if banniere_bulletin_filename %}
    <div style="display:flex; align-items:center; gap:16px; margin-bottom:18px; padding:14px; background:var(--gray-50); border-radius:12px; border:1px solid var(--gray-200);">
      <img src="/banniere-bulletin-ecole" alt="Bannière actuelle" style="max-height:56px; max-width:280px; object-fit:contain;">
      <div style="margin-left:auto;">
        <form action="/parametres/banniere-bulletin/supprimer" method="POST" onsubmit="return confirm('Supprimer la bannière et revenir au bandeau par défaut ?');">
          <button type="submit" class="btn btn-outline btn-sm">🗑️ Supprimer</button>
        </form>
      </div>
    </div>
    {% endif %}
    <form action="/parametres/banniere-bulletin/upload" method="POST" enctype="multipart/form-data" style="display:flex; gap:10px; align-items:center; flex-wrap:wrap;">
      <input type="file" name="banniere" accept=".png,.jpg,.jpeg,.svg,.webp" required>
      <button type="submit" class="btn btn-primary btn-sm">⬆️ {{ 'Remplacer' if banniere_bulletin_filename else 'Uploader la bannière' }}</button>
    </form>
    <p class="text-xs text-muted" style="margin-top:10px;">Formats acceptés : PNG, JPG, SVG, WEBP. Une image large (ratio proche de 6:1, ex. 1800×300px) donne le meilleur rendu.</p>
  </div>
</div>

<!-- 🆕 Personnalisation des couleurs — réservée à l'admin. S'applique à toute l'application
     (texte, cartes, onglets/boutons) en mode clair et en mode néon (sombre). Design "luxe"
     réorganisé par sections, avec aperçu en direct et sélecteurs sous forme de pastilles. -->
<style>
.cl-card{ max-width:760px; margin-top:20px; overflow:visible; }
.cl-intro{ font-size:.85rem; color:var(--gray-500); line-height:1.6; margin-bottom:20px; }
/* Bandeau d'aperçu en direct : deux mini-scènes (clair / néon) qui se mettent à jour au fil
   des réglages, pour voir immédiatement le rendu avant d'enregistrer. */
.cl-preview-row{ display:grid; grid-template-columns:1fr 1fr; gap:16px; margin-bottom:26px; }
.cl-preview-box{ border-radius:18px; padding:16px; background:linear-gradient(150deg,#EEF2F9,#E2E8F0);
  border:1px solid rgba(0,0,0,.06); position:relative; overflow:hidden; }
.cl-preview-box.cl-preview-dark{ background:linear-gradient(150deg,#101116,#181920); border-color:rgba(255,255,255,.08); }
.cl-preview-tag{ position:absolute; top:12px; right:14px; font-size:.62rem; font-weight:800; letter-spacing:.05em;
  text-transform:uppercase; color:rgba(120,120,128,.5); }
.cl-preview-dark .cl-preview-tag{ color:rgba(255,255,255,.35); }
.cl-preview-card{ border-radius:14px; padding:16px 16px 14px; margin-top:20px; transition:background .2s ease; }
.cl-preview-title{ font-weight:800; font-size:.92rem; margin-bottom:6px; transition:color .2s ease; }
.cl-preview-text{ font-size:.76rem; line-height:1.5; margin-bottom:12px; transition:color .2s ease; }
.cl-preview-actions{ display:flex; gap:8px; }
.cl-preview-tab{ font-size:.68rem; font-weight:700; padding:5px 12px; border-radius:999px; transition:background .2s ease,color .2s ease; }
.cl-preview-btn{ font-size:.68rem; font-weight:700; padding:5px 12px; border-radius:8px; color:#fff; transition:background .2s ease; }
/* Sections thématiques : icône + titre + sous-titre, pour une lecture organisée au lieu d'un
   long formulaire uniforme. */
.cl-section{ padding:16px 0; border-top:1px solid rgba(120,120,128,.12); }
.cl-section:first-of-type{ border-top:none; padding-top:0; }
.cl-section-head{ display:flex; align-items:flex-start; gap:12px; margin-bottom:14px; }
.cl-section-ic{ width:34px; height:34px; border-radius:10px; background:linear-gradient(150deg,#D9B84A,#8E7419);
  display:flex; align-items:center; justify-content:center; font-size:1rem; flex-shrink:0; box-shadow:0 4px 10px rgba(142,116,25,.25); }
.cl-section-title{ font-weight:750; font-size:.9rem; color:var(--gray-900); }
.cl-section-sub{ font-size:.75rem; color:var(--gray-500); margin-top:1px; }
/* Pastilles de couleur : le carré <input type=color> natif est invisible et posé sur un joli
   rond de couleur, avec le libellé et le code hex à côté — plus lisible et plus "premium"
   qu'un simple carré de saisie brut. */
.cl-row-grid{ display:grid; grid-template-columns:1fr 1fr; gap:12px 20px; }
.cl-swatch-pair{ display:flex; align-items:center; gap:14px; flex-wrap:wrap; padding:10px 14px; border-radius:14px;
  background:rgba(120,120,128,.05); border:1px solid rgba(0,0,0,.05); }
html.theme-neon .cl-swatch-pair{ background:rgba(255,255,255,.04) !important; border-color:var(--neon-line,rgba(255,255,255,.1)) !important; }
.cl-dots{ display:flex; align-items:center; gap:6px; }
.cl-swatch{ position:relative; width:34px; height:34px; border-radius:50%; flex-shrink:0; cursor:pointer;
  box-shadow:0 0 0 3px var(--surface,#fff), 0 0 0 4px rgba(0,0,0,.08), 0 3px 8px rgba(0,0,0,.18); }
.cl-swatch input[type=color]{ position:absolute; inset:0; opacity:0; cursor:pointer; width:100%; height:100%; }
.cl-swatch-lbl{ font-size:.78rem; font-weight:650; color:var(--gray-700); }
.cl-swatch-hex{ font-size:.68rem; font-family:ui-monospace,Menlo,monospace; color:var(--gray-500); margin-left:auto; }
/* Actions : boutons regroupés dans un pied de carte discret et propre. */
.cl-actions{ display:flex; gap:10px; flex-wrap:wrap; margin-top:22px; padding-top:16px; border-top:1px solid rgba(120,120,128,.12); }
@media(max-width:640px){ .cl-preview-row, .cl-row-grid{ grid-template-columns:1fr; } }
</style>
<div class="card cl-card">
  <div class="card-header"><span class="card-title">🎨 Personnalisation des couleurs</span></div>
  <div class="card-body">
    <p class="cl-intro">
      Toute la palette de l'application se règle ici — textes, menu, cartes, onglets, boutons et
      arrière-plan — séparément en mode clair ☀️ et en mode néon 🌙. La couleur des textes se
      propage désormais à <strong>tous les textes hors des cartes</strong> (titres, paragraphes,
      libellés, texte atténué...) ; le texte à l'intérieur des cartes reste réglable à part.
    </p>

    <!-- Aperçu en direct -->
    <div class="cl-preview-row">
      <div class="cl-preview-box" id="cl-prev-clair">
        <span class="cl-preview-tag">☀️ Clair</span>
        <div class="cl-preview-card" id="cl-prev-clair-card">
          <div class="cl-preview-title" id="cl-prev-clair-title">Titre d'exemple</div>
          <div class="cl-preview-text" id="cl-prev-clair-text">Aperçu du texte et des couleurs choisies.</div>
          <div class="cl-preview-actions">
            <span class="cl-preview-tab" id="cl-prev-clair-tab">Onglet</span>
            <span class="cl-preview-btn" id="cl-prev-clair-btn">Bouton</span>
          </div>
        </div>
      </div>
      <div class="cl-preview-box cl-preview-dark" id="cl-prev-neon">
        <span class="cl-preview-tag">🌙 Néon</span>
        <div class="cl-preview-card" id="cl-prev-neon-card">
          <div class="cl-preview-title" id="cl-prev-neon-title">Titre d'exemple</div>
          <div class="cl-preview-text" id="cl-prev-neon-text">Aperçu du texte et des couleurs choisies.</div>
          <div class="cl-preview-actions">
            <span class="cl-preview-tab" id="cl-prev-neon-tab">Onglet</span>
            <span class="cl-preview-btn" id="cl-prev-neon-btn">Bouton</span>
          </div>
        </div>
      </div>
    </div>

    <form action="/parametres/couleurs/enregistrer" method="POST" id="cl-form" oninput="clMajApercu()">
      <div class="cl-section">
        <div class="cl-section-head">
          <div class="cl-section-ic">📝</div>
          <div>
            <div class="cl-section-title">Couleur des textes</div>
            <div class="cl-section-sub">S'applique à tous les textes hors des cartes : titres, paragraphes, libellés...</div>
          </div>
        </div>
        <div class="cl-row-grid">
          <label class="cl-swatch-pair">
            <span class="cl-swatch"><input type="color" id="cl-texte-clair" name="couleur_texte_clair" value="{{ couleurs.couleur_texte_clair }}"></span>
            <span class="cl-swatch-lbl">☀️ Mode clair</span>
            <span class="cl-swatch-hex">{{ couleurs.couleur_texte_clair }}</span>
          </label>
          <label class="cl-swatch-pair">
            <span class="cl-swatch"><input type="color" id="cl-texte-neon" name="couleur_texte_neon" value="{{ couleurs.couleur_texte_neon }}"></span>
            <span class="cl-swatch-lbl">🌙 Mode néon</span>
            <span class="cl-swatch-hex">{{ couleurs.couleur_texte_neon }}</span>
          </label>
        </div>
      </div>

      <div class="cl-section">
        <div class="cl-section-head">
          <div class="cl-section-ic">🧭</div>
          <div>
            <div class="cl-section-title">Liens du menu</div>
            <div class="cl-section-sub">Couleur des liens de la barre latérale, indépendante du texte général</div>
          </div>
        </div>
        <div class="cl-row-grid">
          <label class="cl-swatch-pair">
            <span class="cl-swatch"><input type="color" id="cl-navlink-clair" name="couleur_navlink_clair" value="{{ couleurs.couleur_navlink_clair }}"></span>
            <span class="cl-swatch-lbl">☀️ Mode clair</span>
            <span class="cl-swatch-hex">{{ couleurs.couleur_navlink_clair }}</span>
          </label>
          <label class="cl-swatch-pair">
            <span class="cl-swatch"><input type="color" id="cl-navlink-neon" name="couleur_navlink_neon" value="{{ couleurs.couleur_navlink_neon }}"></span>
            <span class="cl-swatch-lbl">🌙 Mode néon</span>
            <span class="cl-swatch-hex">{{ couleurs.couleur_navlink_neon }}</span>
          </label>
        </div>
      </div>

      <div class="cl-section">
        <div class="cl-section-head">
          <div class="cl-section-ic">🗂️</div>
          <div>
            <div class="cl-section-title">Fond des cartes</div>
            <div class="cl-section-sub">Dégradé fondu (2 teintes) appliqué à toutes les cartes de l'application</div>
          </div>
        </div>
        <div class="cl-row-grid">
          <label class="cl-swatch-pair">
            <span class="cl-dots">
              <span class="cl-swatch"><input type="color" id="cl-carte-clair-1" name="couleur_carte_clair" value="{{ couleurs.couleur_carte_clair }}"></span>
              <span class="cl-swatch"><input type="color" id="cl-carte-clair-2" name="couleur_carte_clair_2" value="{{ couleurs.couleur_carte_clair_2 }}"></span>
            </span>
            <span class="cl-swatch-lbl">☀️ Mode clair</span>
          </label>
          <label class="cl-swatch-pair">
            <span class="cl-dots">
              <span class="cl-swatch"><input type="color" id="cl-carte-neon-1" name="couleur_carte_neon" value="{{ couleurs.couleur_carte_neon }}"></span>
              <span class="cl-swatch"><input type="color" id="cl-carte-neon-2" name="couleur_carte_neon_2" value="{{ couleurs.couleur_carte_neon_2 }}"></span>
            </span>
            <span class="cl-swatch-lbl">🌙 Mode néon</span>
          </label>
        </div>
      </div>

      <div class="cl-section">
        <div class="cl-section-head">
          <div class="cl-section-ic">🔤</div>
          <div>
            <div class="cl-section-title">Texte à l'intérieur des cartes</div>
            <div class="cl-section-sub">Réglable indépendamment du texte général, propre au contenu des cartes</div>
          </div>
        </div>
        <div class="cl-row-grid">
          <label class="cl-swatch-pair">
            <span class="cl-swatch"><input type="color" id="cl-cartetexte-clair" name="couleur_cartetexte_clair" value="{{ couleurs.couleur_cartetexte_clair }}"></span>
            <span class="cl-swatch-lbl">☀️ Mode clair</span>
            <span class="cl-swatch-hex">{{ couleurs.couleur_cartetexte_clair }}</span>
          </label>
          <label class="cl-swatch-pair">
            <span class="cl-swatch"><input type="color" id="cl-cartetexte-neon" name="couleur_cartetexte_neon" value="{{ couleurs.couleur_cartetexte_neon }}"></span>
            <span class="cl-swatch-lbl">🌙 Mode néon</span>
            <span class="cl-swatch-hex">{{ couleurs.couleur_cartetexte_neon }}</span>
          </label>
        </div>
      </div>

      <div class="cl-section">
        <div class="cl-section-head">
          <div class="cl-section-ic">🏷️</div>
          <div>
            <div class="cl-section-title">Onglets & accent</div>
            <div class="cl-section-sub">Onglet actif du menu et couleur d'accentuation générale</div>
          </div>
        </div>
        <div class="cl-row-grid">
          <label class="cl-swatch-pair">
            <span class="cl-swatch"><input type="color" id="cl-onglet-clair" name="couleur_onglet_clair" value="{{ couleurs.couleur_onglet_clair }}"></span>
            <span class="cl-swatch-lbl">☀️ Mode clair</span>
            <span class="cl-swatch-hex">{{ couleurs.couleur_onglet_clair }}</span>
          </label>
          <label class="cl-swatch-pair">
            <span class="cl-swatch"><input type="color" id="cl-onglet-neon" name="couleur_onglet_neon" value="{{ couleurs.couleur_onglet_neon }}"></span>
            <span class="cl-swatch-lbl">🌙 Mode néon</span>
            <span class="cl-swatch-hex">{{ couleurs.couleur_onglet_neon }}</span>
          </label>
        </div>
      </div>

      <div class="cl-section">
        <div class="cl-section-head">
          <div class="cl-section-ic">🔘</div>
          <div>
            <div class="cl-section-title">Boutons</div>
            <div class="cl-section-sub">Couleur du bouton principal, indépendante des onglets</div>
          </div>
        </div>
        <div class="cl-row-grid">
          <label class="cl-swatch-pair">
            <span class="cl-swatch"><input type="color" id="cl-bouton-clair" name="couleur_bouton_clair" value="{{ couleurs.couleur_bouton_clair }}"></span>
            <span class="cl-swatch-lbl">☀️ Mode clair</span>
            <span class="cl-swatch-hex">{{ couleurs.couleur_bouton_clair }}</span>
          </label>
          <label class="cl-swatch-pair">
            <span class="cl-swatch"><input type="color" id="cl-bouton-neon" name="couleur_bouton_neon" value="{{ couleurs.couleur_bouton_neon }}"></span>
            <span class="cl-swatch-lbl">🌙 Mode néon</span>
            <span class="cl-swatch-hex">{{ couleurs.couleur_bouton_neon }}</span>
          </label>
        </div>
      </div>

      <div class="cl-section">
        <div class="cl-section-head">
          <div class="cl-section-ic">🖼️</div>
          <div>
            <div class="cl-section-title">Arrière-plan de page</div>
            <div class="cl-section-sub">Dégradé fondu (2 teintes) derrière tout le contenu</div>
          </div>
        </div>
        <div class="cl-row-grid">
          <label class="cl-swatch-pair">
            <span class="cl-dots">
              <span class="cl-swatch"><input type="color" id="cl-fond-clair-1" name="couleur_fond_clair" value="{{ couleurs.couleur_fond_clair }}"></span>
              <span class="cl-swatch"><input type="color" id="cl-fond-clair-2" name="couleur_fond_clair_2" value="{{ couleurs.couleur_fond_clair_2 }}"></span>
            </span>
            <span class="cl-swatch-lbl">☀️ Mode clair</span>
          </label>
          <label class="cl-swatch-pair">
            <span class="cl-dots">
              <span class="cl-swatch"><input type="color" id="cl-fond-neon-1" name="couleur_fond_neon" value="{{ couleurs.couleur_fond_neon }}"></span>
              <span class="cl-swatch"><input type="color" id="cl-fond-neon-2" name="couleur_fond_neon_2" value="{{ couleurs.couleur_fond_neon_2 }}"></span>
            </span>
            <span class="cl-swatch-lbl">🌙 Mode néon</span>
          </label>
        </div>
      </div>

      <div class="cl-actions">
        <button type="submit" class="btn btn-primary btn-sm">💾 Enregistrer les couleurs</button>
        <button type="submit" formaction="/parametres/couleurs/reinitialiser" class="btn btn-outline btn-sm" onclick="return confirm('Réinitialiser les couleurs par défaut de l\\'application ?');">↺ Réinitialiser</button>
      </div>
    </form>
  </div>
</div>
<script>
function clMajApercu(){
  function v(id, fallback){ var el = document.getElementById(id); return el ? el.value : fallback; }
  // Clair
  document.getElementById('cl-prev-clair-title').style.color = v('cl-texte-clair', '#0F172A');
  document.getElementById('cl-prev-clair-text').style.color = v('cl-texte-clair', '#0F172A');
  document.getElementById('cl-prev-clair-card').style.background =
    'linear-gradient(135deg,' + v('cl-carte-clair-1', '#FFFFFF') + ',' + v('cl-carte-clair-2', '#F1F5F9') + ')';
  document.getElementById('cl-prev-clair-card').style.color = v('cl-cartetexte-clair', '#0F172A');
  document.getElementById('cl-prev-clair-tab').style.background = v('cl-onglet-clair', '#2563EB') + '26';
  document.getElementById('cl-prev-clair-tab').style.color = v('cl-onglet-clair', '#2563EB');
  document.getElementById('cl-prev-clair-btn').style.background = v('cl-bouton-clair', '#2563EB');
  document.getElementById('cl-prev-clair').style.background =
    'linear-gradient(150deg,' + v('cl-fond-clair-1', '#F8FAFC') + ',' + v('cl-fond-clair-2', '#E0E9F5') + ')';
  // Néon
  document.getElementById('cl-prev-neon-title').style.color = v('cl-texte-neon', '#F5F5FF');
  document.getElementById('cl-prev-neon-text').style.color = v('cl-texte-neon', '#F5F5FF');
  document.getElementById('cl-prev-neon-card').style.background =
    'linear-gradient(135deg,' + v('cl-carte-neon-1', '#121220') + ',' + v('cl-carte-neon-2', '#1B1B30') + ')';
  document.getElementById('cl-prev-neon-card').style.color = v('cl-cartetexte-neon', '#F5F5FF');
  document.getElementById('cl-prev-neon-tab').style.background = v('cl-onglet-neon', '#00E5FF') + '26';
  document.getElementById('cl-prev-neon-tab').style.color = v('cl-onglet-neon', '#00E5FF');
  document.getElementById('cl-prev-neon-btn').style.background = v('cl-bouton-neon', '#00E5FF');
  document.getElementById('cl-prev-neon').style.background =
    'linear-gradient(150deg,' + v('cl-fond-neon-1', '#07070C') + ',' + v('cl-fond-neon-2', '#12081F') + ')';
  // Reflète le code hex à côté de chaque pastille simple
  document.querySelectorAll('.cl-swatch-pair').forEach(function(pair){
    var input = pair.querySelector('input[type=color]');
    var hex = pair.querySelector('.cl-swatch-hex');
    if (input && hex && !pair.querySelector('.cl-dots')) hex.textContent = input.value;
  });
}
document.addEventListener('DOMContentLoaded', clMajApercu);
</script>
{% endif %}
</div></div></div></body></html>"""

WHATSAPP_HTML = """<!DOCTYPE html><html><head><title>WhatsApp — Administration</title>""" + BASE_CSS + MACOS_CSS + '''
  <style>
    /* ── Page WhatsApp — alignée sur la charte graphique commune (cartes, tokens, sidebar) ── */
    .wa-header{ display:flex; align-items:center; justify-content:space-between; gap:14px; margin-bottom:20px; flex-wrap:wrap; }
    .wa-header h2{ font-size:1.15rem; font-weight:700; letter-spacing:-.01em; color:var(--gray-900); display:flex; align-items:center; gap:10px; }
    .wa-connect-btn{
      display:inline-flex; align-items:center; gap:7px; text-decoration:none; font-size:.84rem; font-weight:700;
      color:#1a7a34; background:linear-gradient(180deg,rgba(52,199,89,.16),rgba(52,199,89,.1));
      border:1px solid rgba(52,199,89,.35); padding:8px 16px; border-radius:999px; transition:filter .15s ease, transform .12s ease;
    }
    .wa-connect-btn:hover{ filter:brightness(1.05); }
    .wa-connect-btn:active{ transform:scale(.97); }

    .card{ padding:22px 24px; margin-bottom:20px; }
    .card h2{ font-size:.98rem; font-weight:650; color:var(--gray-900); margin-bottom:15px; padding-bottom:12px; border-bottom:1px solid var(--gray-200); letter-spacing:-.01em; }
    .flash-success { background:rgba(52,199,89,.13); color:#187a35; padding:12px 16px; border-radius:10px; margin-bottom:16px; font-size:.88rem; font-weight:500; border:1px solid rgba(52,199,89,.25); }
    .flash-error   { background:rgba(255,69,58,.12); color:#c62a20; padding:12px 16px; border-radius:10px; margin-bottom:16px; font-size:.88rem; font-weight:500; border:1px solid rgba(255,69,58,.22); }

    .badge-danger  { background:rgba(255,69,58,.13); color:#c62a20; padding:3px 11px; border-radius:999px; font-size:.76rem; font-weight:650; }
    .badge-warning { background:rgba(255,159,10,.16); color:#a15c00; padding:3px 11px; border-radius:999px; font-size:.76rem; font-weight:650; }

    input[type=text],input[type=tel] {
      border:1px solid var(--gray-200); background:rgba(255,255,255,.85); border-radius:10px;
      padding:7px 11px; font-size:.85rem; width:160px; font-family:inherit; color:var(--gray-900);
      transition:border-color .15s ease, box-shadow .15s ease;
    }
    input[type=text]:focus,input[type=tel]:focus{ outline:none; border-color:var(--blue-mid); box-shadow:0 0 0 3px rgba(10,132,255,.18); }

    .info-box {
      background:rgba(52,199,89,.09); border:1px solid rgba(52,199,89,.2); border-left:3px solid var(--green);
      padding:12px 16px; border-radius:10px; font-size:.86rem; color:#186b30; margin-bottom:20px;
    }

    /* Onglets — segmented control */
    .tabs {
      display:inline-flex; gap:2px; margin-bottom:22px;
      background:rgba(120,120,128,.12); padding:3px; border-radius:999px;
      border:none;
    }
    .tab-btn {
      padding:8px 20px; font-size:.85rem; font-weight:600; color:var(--gray-500); cursor:pointer;
      border:none; background:none; border-radius:999px; border-bottom:none; margin-bottom:0;
      transition:background .15s ease, color .15s ease, box-shadow .15s ease;
    }
    .tab-btn.active { color:var(--gray-900); background:#fff; box-shadow:0 1px 3px rgba(0,0,0,.14); }
    .tab-panel { display:none; }
    .tab-panel.active { display:block; }

    /* Filtres cycle / classe */
    .filter-bar { display:flex; gap:14px; align-items:flex-end; flex-wrap:wrap; }
    .filter-bar .form-group { display:flex; flex-direction:column; gap:5px; }
    .filter-bar label { font-size:.74rem; color:var(--gray-500); font-weight:650; text-transform:uppercase; letter-spacing:.03em; }
    .filter-bar select {
      border:1px solid var(--gray-200); border-radius:10px; padding:8px 11px; font-size:.85rem;
      min-width:200px; background:rgba(255,255,255,.9); color:var(--gray-900); font-family:inherit;
    }
    .filter-bar select:focus{ outline:none; border-color:var(--blue-mid); box-shadow:0 0 0 3px rgba(10,132,255,.18); }

    /* Liste de sélection des parents */
    .parent-select-list { max-height:280px; overflow-y:auto; border:1px solid var(--gray-200); border-radius:16px; margin:12px 0; background:rgba(255,255,255,.6); }
    .parent-select-list::-webkit-scrollbar{ width:9px; }
    .parent-select-list::-webkit-scrollbar-thumb{ background:rgba(0,0,0,.18); border-radius:99px; border:2px solid transparent; background-clip:content-box; }
    .parent-item { display:flex; align-items:center; gap:10px; padding:10px 14px; border-bottom:1px solid var(--gray-100); font-size:.86rem; }
    .parent-item:last-child { border-bottom:none; }
    .parent-item:hover { background:rgba(10,132,255,.05); }
    .parent-item input[type=checkbox] { width:16px; height:16px; accent-color:var(--green); }
    .parent-item .p-name { font-weight:600; color:var(--gray-900); }
    .parent-item .p-meta { color:var(--gray-500); font-size:.8rem; }
    .select-all-row { display:flex; align-items:center; gap:8px; padding:9px 4px; font-size:.85rem; font-weight:650; color:var(--gray-700); }
    .select-all-row input { width:16px; height:16px; accent-color:var(--green); }
    textarea, input[type=file] {
      width:100%; border:1px solid var(--gray-200); background:rgba(255,255,255,.85); border-radius:16px;
      padding:11px 13px; font-size:.88rem; font-family:inherit; color:var(--gray-900);
    }
    textarea { resize:vertical; }
    textarea:focus{ outline:none; border-color:var(--blue-mid); box-shadow:0 0 0 3px rgba(10,132,255,.18); }
    input[type=file]::file-selector-button{
      border:none; background:rgba(120,120,128,.14); color:var(--gray-700); font-weight:600; font-size:.82rem;
      padding:6px 13px; border-radius:999px; margin-right:10px; cursor:pointer;
    }
    input[type=file]::file-selector-button:hover{ background:rgba(120,120,128,.24); }
    .hint { font-size:.78rem; color:var(--gray-500); margin-top:7px; line-height:1.5; }
    .hint code { background:rgba(120,120,128,.12); padding:1px 6px; border-radius:5px; color:var(--gray-700); }
    .empty-state { text-align:center; padding:26px; color:var(--gray-500); font-size:.9rem; }

    /* ── Bandeau de statistiques (aligné sur .stat-card du reste de l'app) ── */
    .stats-row{ display:flex; gap:14px; flex-wrap:wrap; margin-bottom:20px; }
    .stat-chip{
      flex:1; min-width:168px; background:#fff; border:1px solid var(--gray-200);
      border-radius:16px; padding:16px 20px; box-shadow:var(--shadow);
      display:flex; align-items:center; gap:12px;
    }
    html.theme-neon .stat-chip{ background:rgba(18,18,32,.82); }
    .stat-chip .stat-icon{ font-size:1.3rem; line-height:1; }
    .stat-chip .stat-value{ font-size:1.4rem; font-weight:700; letter-spacing:-.02em; color:var(--gray-900); line-height:1.1; }
    .stat-chip .stat-label{ font-size:.72rem; color:var(--gray-500); text-transform:uppercase; letter-spacing:.04em; margin-top:2px; font-weight:650; }
    .stat-chip.stat-warn .stat-value{ color:#c62a20; }

    /* ── Section repliable (secondaire) ── */
    details.card{ padding:0; overflow:hidden; }
    details.card summary{
      list-style:none; cursor:pointer; padding:18px 22px; font-size:.98rem; font-weight:650;
      color:var(--gray-900); display:flex; align-items:center; gap:10px; user-select:none;
    }
    details.card summary::-webkit-details-marker{ display:none; }
    details.card summary::after{
      content:'›'; margin-left:auto; font-size:1.3rem; color:var(--gray-500); transform:rotate(90deg);
      transition:transform .18s ease;
    }
    details.card[open] summary::after{ transform:rotate(-90deg); }
    details.card summary:hover{ background:rgba(120,120,128,.06); }
    details.card .details-body{ padding:0 22px 22px; border-top:1px solid var(--gray-200); padding-top:18px; }

    /* ── Espace de travail 2 colonnes (Message / Fichier) ── */
    .workspace-grid{ display:grid; grid-template-columns:minmax(280px,340px) 1fr; gap:20px; align-items:start; }
    .workspace-col-side .card{ margin-bottom:16px; }
    .workspace-col-main .card{ position:relative; }
    .composer-actions{ display:flex; align-items:center; gap:12px; margin-top:16px; flex-wrap:wrap; }
    .composer-count{ font-size:.8rem; color:var(--gray-500); font-weight:600; }
    @media (max-width:760px){
      .workspace-grid{ grid-template-columns:minmax(0,1fr); }
    }
  </style>
</head><body><div class="layout">
{{ nav_html|safe }}
<script>document.getElementById('page-title').textContent='WhatsApp — Communication';</script>
<div class="container">

  <div class="wa-header">
    <h2>📱 WhatsApp — Communication avec les parents</h2>
  </div>

  {% with messages = get_flashed_messages(with_categories=true) %}
    {% for cat, msg in messages %}
      <div class="flash-{{ cat }}">{{ msg }}</div>
    {% endfor %}
  {% endwith %}

  <div class="tabs">
    <button type="button" class="tab-btn" id="tab-btn-rappels" onclick="showTab('rappels')">💰 Relances paiement</button>
    <button type="button" class="tab-btn" id="tab-btn-message" onclick="showTab('message')">💬 Envoyer un message</button>
    <button type="button" class="tab-btn" id="tab-btn-fichier" onclick="showTab('fichier')">📎 Envoyer un fichier</button>
  </div>

  <!-- ═══════════════ ONGLET 1 : RELANCES PAIEMENT (existant) ═══════════════ -->
  <div class="tab-panel" id="tab-rappels">

    <div class="info-box">
      💬 Envoi <strong>manuel via WhatsApp Web</strong> : au clic sur "Envoyer", un onglet WhatsApp Web s'ouvre pour chaque parent avec le message déjà rédigé — il ne reste plus qu'à cliquer sur le bouton d'envoi ➤ dans WhatsApp. Aucune connexion ni QR code à configurer.
    </div>

    <!-- Bandeau de statistiques : vue d'ensemble en un coup d'œil -->
    <div class="stats-row">
      <div class="stat-chip stat-warn">
        <span class="stat-icon">⚠️</span>
        <div>
          <div class="stat-value">{{ stats_impayes['n'] }}</div>
          <div class="stat-label">Parents impayés</div>
        </div>
      </div>
      {% if session.role != 'agent_admin' %}
      <div class="stat-chip stat-warn">
        <span class="stat-icon">💰</span>
        <div>
          <div class="stat-value">{{ "%.0f"|format(stats_impayes['t']) }} MAD</div>
          <div class="stat-label">Reste dû total</div>
        </div>
      </div>
      {% endif %}
      <div class="stat-chip">
        <span class="stat-icon">📇</span>
        <div>
          <div class="stat-value">{{ tous_parents|selectattr('telephone')|list|length }}/{{ tous_parents|length }}</div>
          <div class="stat-label">Numéros renseignés</div>
        </div>
      </div>
    </div>

    <!-- 🆕 Cibler les relances : cycle / classe / statut / mois d'échéance / reste minimum + langue -->
    <div class="card">
      <h2>🔎 Cibler les relances</h2>
      <form method="GET" action="/whatsapp/rappels" class="filter-bar">
        <input type="hidden" name="tab" value="rappels">
        <div class="form-group">
          <label>Cycle</label>
          <select name="r_cycle" onchange="this.form.submit()">
            <option value="">Tous les cycles</option>
            {% for cy in cycles_dispo %}
              <option value="{{ cy }}" {% if cy == r_cycle %}selected{% endif %}>{{ cy }}</option>
            {% endfor %}
          </select>
        </div>
        <div class="form-group">
          <label>Classe</label>
          <select name="r_classe" onchange="this.form.submit()">
            <option value="">Toutes les classes</option>
            {% for c in classes_rappels %}
              <option value="{{ c.id }}" {% if r_classe == c.id|string %}selected{% endif %}>{{ c.nom }} ({{ c.niveau }})</option>
            {% endfor %}
          </select>
        </div>
        <div class="form-group">
          <label>Situation</label>
          <select name="r_statut" onchange="this.form.submit()">
            <option value="" {% if not r_statut %}selected{% endif %}>Impayés + partiels</option>
            <option value="non_paye" {% if r_statut == 'non_paye' %}selected{% endif %}>Non payés</option>
            <option value="partiel" {% if r_statut == 'partiel' %}selected{% endif %}>Partiellement payés</option>
          </select>
        </div>
        <div class="form-group">
          <label>Mois d'échéance</label>
          <select name="r_mois" onchange="this.form.submit()">
            <option value="">Tous les mois</option>
            {% for m in mois_rappels %}
              <option value="{{ m.val }}" {% if r_mois == m.val %}selected{% endif %}>{{ m.label }}</option>
            {% endfor %}
          </select>
        </div>
        <div class="form-group" style="flex-basis:100%;">
          <label>Type de facture à relancer</label>
          <input type="hidden" name="r_type" id="wa-r-type" value="{{ r_type }}">
          <div class="wa-type-chips">
            {% for val, lib in [('', '📋 Tous les types'), ('Scolarité', '🎓 Scolarité'), ("Frais d'inscription", "📝 Frais d'inscription"), ('Autre', '🧾 Autres (voyage, achat, service…)')] %}
              <button type="button" class="wa-type-chip {% if r_type == val %}on{% endif %}" data-type="{{ val }}">{{ lib }}</button>
            {% endfor %}
          </div>
          {% if r_type %}<small style="color:#4338CA;font-weight:600;">Seules les factures « {{ 'Autres types' if r_type == 'Autre' else r_type }} » sont affichées, comptées et écrites dans le message.</small>{% endif %}
        </div>
        <style>
          .wa-type-chips{ display:flex; flex-wrap:wrap; gap:8px; }
          .wa-type-chip{ cursor:pointer; font:inherit; font-weight:700; font-size:.85rem; padding:9px 16px; border-radius:999px; border:1px solid #C7D2FE; background:#fff; color:#4338CA; transition:all .15s; }
          .wa-type-chip:hover{ background:#EEF2FF; }
          .wa-type-chip.on{ background:linear-gradient(135deg,#4F46E5,#7C3AED); color:#fff; border-color:transparent; box-shadow:0 8px 16px -8px rgba(79,70,229,.8); }
        </style>
        <script>
          document.addEventListener('DOMContentLoaded', function(){
            var h = document.getElementById('wa-r-type');
            document.querySelectorAll('.wa-type-chip').forEach(function(b){
              b.addEventListener('click', function(){ h.value = b.getAttribute('data-type'); h.form.submit(); });
            });
          });
        </script>
        <div class="form-group">
          <label>Reste dû minimum (MAD)</label>
          <input type="text" inputmode="decimal" name="r_min" value="{{ r_min }}" placeholder="ex : 500" style="width:140px;">
        </div>
        <div class="form-group" style="flex-direction:row;gap:8px;align-items:center;">
          <button type="submit" class="btn btn-blue">Filtrer</button>
          {% if filtres_rappels_actifs %}<a href="/whatsapp/rappels?tab=rappels" class="btn btn-gray">↺ Réinitialiser</a>{% endif %}
        </div>
      </form>
      <div class="filter-bar" style="margin-top:14px;">
        <div class="form-group">
          <label>Langue du message</label>
          <select id="wa-lang">
            <option value="both" selected>Français + العربية</option>
            <option value="fr">Français</option>
            <option value="ar">العربية</option>
          </select>
        </div>
      </div>
      <p class="hint">Les boutons d'envoi ci-dessous n'utilisent que les parents de la liste affichée : ce que vous voyez est exactement ce qui sera envoyé.</p>
    </div>

    <!-- Bouton envoi global (liste filtrée) -->
    <div class="card">
      <h2>📤 Envoi groupé</h2>
      <p style="color:var(--ink-mute);margin-bottom:14px;font-size:.9rem;">
        Ouvre l'assistant d'envoi pour {% if filtres_rappels_actifs %}les <strong>{{ parents_impayes|length }}</strong> parent(s) de la liste filtrée{% else %}<strong>tous</strong> les parents avec un paiement non réglé ou partiel{% endif %}, un par un. Les parents sans numéro sont ignorés.
      </p>
      <button type="button" class="btn btn-green" onclick="waLancerRappelsTous()" {% if not parents_impayes %}disabled{% endif %}>
        📱 {% if filtres_rappels_actifs %}Envoyer aux {{ parents_impayes|length }} parent(s) filtré(s){% else %}Envoyer à tous les parents impayés{% endif %}
      </button>
    </div>

    <!-- Table parents impayés -->
    <div class="card">
      <h2>⚠️ Parents avec paiements en attente ({{ parents_impayes|length }})</h2>
      {% if parents_impayes %}
      <table>
        <thead>
          <tr>
            <th>Parent</th>
            <th>Élève</th>
            <th>Reste dû</th>
            <th>Relances</th>
            <th>Téléphone WhatsApp</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
        {% for p in parents_impayes %}
          <tr>
            <td><strong>{{ p.nom }} {{ p.prenom }}</strong></td>
            <td>{{ p.eleve_nom }}{% if p.classes_noms %}<br><span style="color:var(--gray-500);font-size:.8rem;">{{ p.classes_noms }}</span>{% endif %}</td>
            <td><span class="badge-danger">{{ "%.2f"|format(p.reste_total) }} MAD</span></td>
            <td id="wa-rel-{{ p.id }}">
              {% set rr = relances_wa.get(p.id) %}
              {% if rr %}<span class="badge-warning">🔁 {{ rr.n }} {{ 'fois' if rr.n > 1 else 'fois' }}</span>{% if rr.depuis %} <span title="Dernière relance : {{ rr.derniere }}" style="color:#B45309;font-size:.78rem;font-weight:700;white-space:nowrap;">⏱ {{ rr.depuis }}</span>{% endif %}<br><span style="color:var(--gray-500);font-size:.78rem;">dernière : {{ rr.derniere }}</span>{% else %}<span style="color:var(--gray-500);font-size:.82rem;">Jamais relancé</span>{% endif %}
            </td>
            <td>
              <form method="POST" style="display:flex;gap:6px;align-items:center;">
                <input type="hidden" name="action" value="update_tel">
                <input type="hidden" name="user_id" value="{{ p.id }}">
                <input type="tel" name="telephone" value="{{ p.telephone or '' }}" placeholder="212612345678">
                <button class="btn btn-gray" style="padding:6px 10px;">💾</button>
              </form>
            </td>
            <td>
              {% if p.telephone %}
                <button type="button" class="btn btn-green" onclick="waLancerRappelUn({{ p.id }})">📱 Envoyer</button>
                <button type="button" class="btn btn-gray" onclick="waLancerTest({{ p.id }})" title="Premier message pour vérifier que c'est le bon parent et le bon numéro">🧪 Test</button>
              {% else %}
                <span style="color:#999;font-size:.82rem;">Numéro manquant</span>
              {% endif %}
            </td>
          </tr>
        {% endfor %}
        </tbody>
      </table>
      {% else %}
        <p style="color:#16a34a;text-align:center;padding:20px;">✅ Aucun paiement en attente — tout est réglé !</p>
      {% endif %}
    </div>

    {% if remerciements %}
    <!-- 🙏 Parents relancés qui ont payé rapidement (≤ 3 jours après la relance) -->
    <div class="card" id="wa-merci-card">
      <div class="card-header" style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;">
        <span class="card-title">🙏 Parents relancés ayant payé en 3 jours ou moins ({{ remerciements|length }})</span>
        <span style="font-size:.8rem;color:var(--gray-500);">Paiements des 60 derniers jours · le message suit la langue choisie plus haut</span>
      </div>
      <div class="card-body" style="overflow-x:auto;">
        <table>
          <thead><tr><th>Parent</th><th>Enfant(s)</th><th>Relancé le</th><th>Payé le</th><th>Montant reçu</th><th>Remerciement</th></tr></thead>
          <tbody>
          {% for r in remerciements %}
            <tr>
              <td><strong>{{ r.nom }}</strong></td>
              <td>{{ r.enfants }}</td>
              <td>{{ r.relance_txt }}</td>
              <td>{{ r.paiement_txt }} <span style="color:#16a34a;font-size:.78rem;font-weight:700;white-space:nowrap;">⚡ {{ r.delai_txt }}</span></td>
              <td><strong>{{ '%.2f'|format(r.montant) }} MAD</strong></td>
              <td>
                <span id="wa-merci-{{ r.parent_id }}-{{ r.relance_jour }}" style="margin-right:6px;">{% if r.remercie %}<span style="color:#16a34a;font-size:.8rem;font-weight:700;">✅ Remercié le {{ r.remercie_txt }}</span>{% endif %}</span>
                {% if r.telephone %}
                  <button type="button" class="btn btn-green" style="padding:6px 12px;font-size:.82rem;" onclick="waLancerRemerciement({{ r.parent_id }}, '{{ r.relance_jour }}')">🙏 {% if r.remercie %}Renvoyer{% else %}Remercier{% endif %}</button>
                {% else %}
                  <span style="color:#999;font-size:.82rem;">Numéro manquant</span>
                {% endif %}
              </td>
            </tr>
          {% endfor %}
          </tbody>
        </table>
      </div>
    </div>
    {% endif %}

    <!-- Gestion téléphones tous les parents — secondaire, repliée par défaut -->
    <details class="card">
      <summary>📋 Numéros WhatsApp de tous les parents ({{ tous_parents|length }})</summary>
      <div class="details-body">
        <p style="color:var(--ink-mute);margin-bottom:14px;font-size:.86rem;">Format international sans le + (ex: <code>212612345678</code> pour le Maroc)</p>
        <table>
          <thead><tr><th>Parent</th><th>Numéro WhatsApp</th><th>Enregistrer</th></tr></thead>
          <tbody>
          {% for u in tous_parents %}
            <tr>
              <td>{{ u.nom }} {{ u.prenom }}</td>
              <td>
                <form method="POST" style="display:flex;gap:6px;align-items:center;">
                  <input type="hidden" name="action" value="update_tel">
                  <input type="hidden" name="user_id" value="{{ u.id }}">
                  <input type="tel" name="telephone" value="{{ u.telephone or '' }}" placeholder="212612345678">
                  <button class="btn btn-blue" style="padding:6px 12px;">💾 Sauver</button>
                </form>
              </td>
              <td>
                {% if u.telephone %}
                  <span style="color:#16a34a;font-size:.85rem;">✅ Renseigné</span>
                  <button type="button" class="btn btn-gray" style="padding:4px 10px;font-size:.78rem;margin-left:6px;" onclick="waLancerTest({{ u.id }})" title="Envoyer un message de vérification à ce numéro">🧪 Test</button>
                {% else %}
                  <span style="color:#ef4444;font-size:.85rem;">❌ Manquant</span>
                {% endif %}
              </td>
            </tr>
          {% endfor %}
          </tbody>
        </table>
      </div>
    </details>

  </div>

  <!-- ═══════════════ ONGLET 2 : ENVOYER UN MESSAGE ═══════════════ -->
  <div class="tab-panel" id="tab-message">

    <div class="workspace-grid">
      <div class="workspace-col-side">

        <div class="card">
          <h2>🔎 Filtrer</h2>
          <form method="GET" action="/whatsapp/rappels" class="filter-bar">
            <input type="hidden" name="tab" value="message">
            <div class="form-group">
              <label>Cycle</label>
              <select name="cycle" onchange="this.form.submit()">
                <option value="">Tous les cycles</option>
                {% for cy in cycles_dispo %}
                  <option value="{{ cy }}" {% if cy == cycle_sel %}selected{% endif %}>{{ cy }}</option>
                {% endfor %}
              </select>
            </div>
            <div class="form-group">
              <label>Classe</label>
              <select name="classe_id" onchange="this.form.submit()">
                <option value="">Toutes les classes</option>
                {% for c in classes_dispo %}
                  <option value="{{ c.id }}" {% if classe_sel == c.id|string %}selected{% endif %}>{{ c.nom }} ({{ c.niveau }})</option>
                {% endfor %}
              </select>
            </div>
          </form>
        </div>

        <div class="card" id="form-message">
          <h2>👥 Destinataires ({{ parents_filtres|length }})</h2>
          {% if parents_filtres %}
          <div class="select-all-row">
            <input type="checkbox" id="select-all-msg" onclick="toggleAll('msg')">
            <label for="select-all-msg">Tout sélectionner</label>
          </div>
          <div class="parent-select-list">
            {% for p in parents_filtres %}
              <label class="parent-item">
                <input type="checkbox" name="parent_ids" value="{{ p.id }}" class="chk-msg" {% if not p.telephone %}disabled{% endif %}>
                <span>
                  <span class="p-name">{{ p.nom }} {{ p.prenom }}</span><br>
                  <span class="p-meta">{{ p.enfants }} — {{ p.classes_noms }}</span>
                </span>
                {% if not p.telephone %}<span class="badge-warning" style="margin-left:auto">Numéro manquant</span>{% endif %}
              </label>
            {% endfor %}
          </div>
          {% else %}
            <div class="empty-state">Aucun parent ne correspond à ce filtre.</div>
          {% endif %}
        </div>

      </div>

      <div class="workspace-col-main">
        <div class="card">
          <h2>✍️ Message</h2>
          <textarea id="msg-textarea" rows="9" placeholder="Bonjour {parent}, ..."></textarea>
          <p class="hint">Le message s'ouvrira <strong>individuellement</strong> dans WhatsApp Web pour chaque parent sélectionné, un par un. Variables disponibles :
            <code>{parent}</code> (nom du parent), <code>{enfant}</code> (nom de l'élève), <code>{classe}</code> (classe).</p>

          <div class="composer-actions">
            <button type="button" class="btn btn-green" onclick="waLancerMessage()">
              📨 Envoyer le message
            </button>
            <span class="composer-count">{{ parents_filtres|length }} destinataire(s) dans la liste filtrée</span>
          </div>
        </div>
      </div>

    </div>

  </div>

  <!-- ═══════════════ ONGLET 3 : ENVOYER UN FICHIER ═══════════════ -->
  <div class="tab-panel" id="tab-fichier">

    <div class="workspace-grid">
      <div class="workspace-col-side">

        <div class="card">
          <h2>🔎 Filtrer</h2>
          <form method="GET" action="/whatsapp/rappels" class="filter-bar">
            <input type="hidden" name="tab" value="fichier">
            <div class="form-group">
              <label>Cycle</label>
              <select name="cycle" onchange="this.form.submit()">
                <option value="">Tous les cycles</option>
                {% for cy in cycles_dispo %}
                  <option value="{{ cy }}" {% if cy == cycle_sel %}selected{% endif %}>{{ cy }}</option>
                {% endfor %}
              </select>
            </div>
            <div class="form-group">
              <label>Classe</label>
              <select name="classe_id" onchange="this.form.submit()">
                <option value="">Toutes les classes</option>
                {% for c in classes_dispo %}
                  <option value="{{ c.id }}" {% if classe_sel == c.id|string %}selected{% endif %}>{{ c.nom }} ({{ c.niveau }})</option>
                {% endfor %}
              </select>
            </div>
          </form>
        </div>

        <div class="card" id="form-fichier">
          <h2>👥 Destinataires ({{ parents_filtres|length }})</h2>
          {% if parents_filtres %}
          <div class="select-all-row">
            <input type="checkbox" id="select-all-file" onclick="toggleAll('file')">
            <label for="select-all-file">Tout sélectionner</label>
          </div>
          <div class="parent-select-list">
            {% for p in parents_filtres %}
              <label class="parent-item">
                <input type="checkbox" name="parent_ids" value="{{ p.id }}" class="chk-file" {% if not p.telephone %}disabled{% endif %}>
                <span>
                  <span class="p-name">{{ p.nom }} {{ p.prenom }}</span><br>
                  <span class="p-meta">{{ p.enfants }} — {{ p.classes_noms }}</span>
                </span>
                {% if not p.telephone %}<span class="badge-warning" style="margin-left:auto">Numéro manquant</span>{% endif %}
              </label>
            {% endfor %}
          </div>
          {% else %}
            <div class="empty-state">Aucun parent ne correspond à ce filtre.</div>
          {% endif %}
        </div>

      </div>

      <div class="workspace-col-main">
        <div class="card">
          <h2>📎 Fichier à envoyer</h2>
          <input type="file" id="fichier-input">
          <p class="hint">Formats acceptés : PDF, Word, Excel, PowerPoint, images (jpg/png/webp), txt.<br>
            ⚠️ WhatsApp Web ne permet pas de joindre un fichier automatiquement via un lien : le message texte s'ouvrira pour chaque contact,
            et un lien de téléchargement du fichier vous sera proposé pour le <strong>joindre manuellement</strong> (glisser-déposer dans WhatsApp) avant de cliquer sur Envoyer.</p>

          <div style="margin-top:16px">
            <input type="text" id="caption-input" placeholder="Légende / message d'accompagnement (optionnel)" style="width:100%">
          </div>

          <div class="composer-actions">
            <button type="button" class="btn btn-green" onclick="waLancerFichier()">
              📎 Envoyer le fichier
            </button>
            <span class="composer-count">{{ parents_filtres|length }} destinataire(s) dans la liste filtrée</span>
          </div>
        </div>
      </div>

    </div>

  </div>

</div>
  </div>
</div>

<!-- ═══════════════ ASSISTANT D'ENVOI MANUEL WHATSAPP WEB (liens wa.me) ═══════════════ -->
<div id="wa-wizard-overlay" style="display:none;position:fixed;inset:0;background:rgba(20,20,22,.45);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);z-index:9999;align-items:center;justify-content:center;">
  <div style="background:rgba(255,255,255,.92);backdrop-filter:blur(24px) saturate(180%);-webkit-backdrop-filter:blur(24px) saturate(180%);border:1px solid rgba(255,255,255,.6);border-radius:18px;max-width:560px;width:92%;max-height:85vh;padding:26px;box-shadow:0 30px 70px rgba(0,0,0,.35);display:flex;flex-direction:column;">
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:10px;">
      <span style="font-size:1.6rem">💬</span>
      <h3 style="font-size:1.02rem;font-weight:650;color:#1D1D1F;letter-spacing:-.01em;">Envoi manuel via WhatsApp Web</h3>
    </div>
    <div id="wa-wizard-fichier-box" style="display:none;background:rgba(10,132,255,.1);border:1px solid rgba(10,132,255,.25);border-radius:10px;padding:10px 12px;margin-bottom:10px;font-size:.83rem;color:#0a4a91;"></div>
    <div id="wa-wizard-progress" style="font-size:.85rem;color:#48484A;font-weight:600;margin-bottom:10px;">Préparation…</div>
    <div id="wa-wizard-log" style="background:rgba(120,120,128,.10);border:1px solid rgba(0,0,0,.06);border-radius:12px;padding:8px;overflow-y:auto;font-size:.84rem;line-height:1.5;margin-bottom:14px;flex:1;"></div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;">
      <button type="button" class="btn btn-outline" onclick="waOuvrirTout()">📤 Ouvrir tous les onglets</button>
      <button type="button" class="btn btn-gray" onclick="waClose()" style="margin-left:auto">✖ Fermer</button>
    </div>
  </div>
</div>

<script>
function showTab(name) {
  document.querySelectorAll('.tab-btn').forEach(t => t.classList.remove('active'));
  document.querySelectorAll('.tab-panel').forEach(c => c.classList.remove('active'));
  document.getElementById('tab-btn-' + name).classList.add('active');
  document.getElementById('tab-' + name).classList.add('active');
}
function toggleAll(prefix) {
  const master = document.getElementById('select-all-' + prefix);
  document.querySelectorAll('.chk-' + prefix).forEach(function(cb){
    if (!cb.disabled) cb.checked = master.checked;
  });
}
document.addEventListener('DOMContentLoaded', function () {
  showTab('{{ tab_actif|default("rappels") }}');
});

/* ─── Assistant d'envoi MANUEL WhatsApp Web (liens wa.me, aucune automatisation) ───
   Le serveur ne fait que préparer les messages et les liens https://wa.me/... .
   C'est l'administrateur qui ouvre chaque conversation (un onglet par contact) et
   clique lui-même sur le bouton d'envoi ➤ dans WhatsApp Web. */
let waListeCourante = [];
let waLotId = '';

function waOuvrirSuivi() {
  document.getElementById('wa-wizard-log').innerHTML = '';
  document.getElementById('wa-wizard-fichier-box').style.display = 'none';
  document.getElementById('wa-wizard-progress').textContent = '⏳ Préparation des messages…';
  document.getElementById('wa-wizard-overlay').style.display = 'flex';
  waListeCourante = [];
}

function waClose() {
  document.getElementById('wa-wizard-overlay').style.display = 'none';
}

/* 🆕 Enregistre la relance (une seule fois par parent et par envoi) et met à jour son compteur */
function waEnregistrerRelance(item) {
  if (!item || !item.compter || !item.parent_id) return;
  const l = document.getElementById('wa-lang');
  fetch('/whatsapp/api/enregistrer_relance', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({parent_id: item.parent_id, lot_id: waLotId, langue: l ? l.value : 'both',
                          type_facture: new URLSearchParams(window.location.search).get('r_type') || ''})
  })
    .then(r => r.json())
    .then(d => {
      const cell = document.getElementById('wa-rel-' + item.parent_id);
      if (!cell || d.n === undefined) return;
      cell.innerHTML = '';
      const b = document.createElement('span');
      b.className = 'badge-warning';
      b.textContent = '🔁 ' + d.n + ' fois';
      cell.appendChild(b);
      if (d.depuis) {
        const dp = document.createElement('span');
        dp.style.cssText = 'color:#B45309;font-size:.78rem;font-weight:700;white-space:nowrap;margin-left:6px;';
        dp.title = 'Dernière relance : ' + d.derniere;
        dp.textContent = '⏱ ' + d.depuis;
        cell.appendChild(dp);
      }
      cell.appendChild(document.createElement('br'));
      const sm = document.createElement('span');
      sm.style.cssText = 'color:var(--gray-500);font-size:.78rem;';
      sm.textContent = 'dernière : ' + d.derniere;
      cell.appendChild(sm);
    })
    .catch(() => {});
}

/* 🙏 Remerciement d'un parent relancé qui a payé en 3 jours ou moins */
function waLancerRemerciement(parentId, jour) {
  waOuvrirSuivi();
  const l = document.getElementById('wa-lang');
  fetch('/whatsapp/api/queue_remerciement/' + parentId + '?relance=' + encodeURIComponent(jour) +
        '&lang=' + encodeURIComponent(l ? l.value : 'both'))
    .then(r => r.json())
    .then(data => {
      if (data.erreur) { waAfficherErreur(data.erreur); return; }
      waAfficherListe(data.resultats);
    })
    .catch(() => waAfficherErreur('Erreur de communication avec le serveur.'));
}

function waEnregistrerRemerciement(item) {
  if (!item || !item.relance_jour || !item.parent_id) return;
  fetch('/whatsapp/api/enregistrer_remerciement', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({parent_id: item.parent_id, relance_jour: item.relance_jour})
  })
    .then(r => r.json())
    .then(d => {
      const cell = document.getElementById('wa-merci-' + item.parent_id + '-' + item.relance_jour);
      if (!cell || !d.date) return;
      cell.innerHTML = '';
      const s = document.createElement('span');
      s.style.cssText = 'color:#16a34a;font-size:.8rem;font-weight:700;';
      s.textContent = '✅ Remercié le ' + d.date;
      cell.appendChild(s);
    })
    .catch(() => {});
}

function waOuvrirLien(lien, btn, item) {
  window.open(lien, '_blank');
  waEnregistrerRelance(item);
  waEnregistrerRemerciement(item);
  if (btn) {
    btn.textContent = '✅ Ouvert';
    btn.disabled = true;
  }
}

function waOuvrirTout() {
  // Ouvre les onglets un par un, espacés dans le temps pour limiter le blocage de
  // popups par le navigateur. Si certains onglets sont malgré tout bloqués, il reste
  // toujours possible de cliquer individuellement sur "Ouvrir" pour chaque contact.
  // 🆕 La ligne « TOUT » (message récapitulatif) est ignorée ici : elle double les factures
  // individuelles, il faut donc l'ouvrir volontairement en cliquant sur son propre bouton.
  let rang = 0;
  waListeCourante.forEach(function (item, i) {
    if (item.tout) return;
    setTimeout(function () {
      window.open(item.lien, '_blank');
      waEnregistrerRelance(item);
      const btn = document.getElementById('wa-btn-' + i);
      if (btn) { btn.textContent = '✅ Ouvert'; btn.disabled = true; }
    }, (rang++) * 350);
  });
}

function waAfficherErreur(message) {
  document.getElementById('wa-wizard-progress').textContent = '❌ ' + message;
}

function waAfficherListe(resultats, nbSansTelephone) {
  waListeCourante = resultats || [];
  waLotId = 'L' + Date.now() + '-' + Math.random().toString(36).slice(2, 8);
  const log = document.getElementById('wa-wizard-log');
  log.innerHTML = '';
  waListeCourante.forEach(function (r, i) {
    const ligne = document.createElement('div');
    ligne.style.display = 'flex';
    ligne.style.alignItems = 'center';
    ligne.style.gap = '8px';
    ligne.style.padding = '6px 4px';
    ligne.style.borderBottom = '1px solid rgba(0,0,0,.05)';

    const span = document.createElement('span');
    span.style.flex = '1';
    span.style.minWidth = '0';
    span.style.overflow = 'hidden';
    span.style.textOverflow = 'ellipsis';
    const strong = document.createElement('strong');
    strong.textContent = r.nom;
    span.appendChild(strong);
    const telSpan = document.createElement('span');
    telSpan.style.color = '#8A8A8E';
    telSpan.textContent = ' (' + r.telephone + ')';
    span.appendChild(telSpan);
    if (r.libelle) {
      const lib = document.createElement('div');
      lib.style.fontSize = '.78rem';
      lib.style.whiteSpace = 'normal';
      lib.style.color = r.tout ? '#0a4a91' : '#48484A';
      lib.style.fontWeight = r.tout ? '700' : '500';
      lib.textContent = (r.tout ? '📦 ' : '🧾 ') + r.libelle;
      span.appendChild(lib);
    }
    if (r.tout) {
      ligne.style.background = 'rgba(10,132,255,.08)';
      ligne.style.borderRadius = '8px';
    }

    const btn = document.createElement('button');
    btn.type = 'button';
    btn.id = 'wa-btn-' + i;
    btn.className = 'btn btn-green';
    btn.style.padding = '5px 12px';
    btn.style.fontSize = '.8rem';
    btn.textContent = '📤 Ouvrir';
    // 🩹 CORRECTIF : le lien est attaché directement en JS (addEventListener), pas via
    // un attribut onclick="..." construit en concatenant des chaînes — sinon les guillemets
    // du lien wa.me (ajoutés par JSON.stringify) cassaient l'attribut HTML en plein milieu
    // et le clic ne déclenchait plus rien (bouton "mort").
    btn.addEventListener('click', function () {
      waOuvrirLien(r.lien, btn, r);
    });

    ligne.appendChild(span);
    ligne.appendChild(btn);
    log.appendChild(ligne);
  });
  let resume = waListeCourante.length + ' conversation(s) prête(s) à ouvrir. Cliquez sur "Ouvrir" (ou "Ouvrir tous les onglets") puis "Envoyer" dans chaque onglet WhatsApp.';
  if (nbSansTelephone) resume += ' (' + nbSansTelephone + ' sans numéro ignoré(s))';
  document.getElementById('wa-wizard-progress').textContent = resume;
}

/* 🆕 Filtres de la page (cycle, classe, statut, mois d'échéance, reste minimum) + langue choisie */
function waQS() {
  const cur = new URLSearchParams(window.location.search);
  const p = new URLSearchParams();
  ['r_cycle', 'r_classe', 'r_statut', 'r_mois', 'r_type', 'r_min'].forEach(function (k) {
    const v = cur.get(k);
    if (v) p.set(k, v);
  });
  const l = document.getElementById('wa-lang');
  p.set('lang', l ? l.value : 'both');
  return p.toString();
}

/* 🆕 Message de test : vérifie le parent et le numéro avant la vraie relance */
function waLancerTest(parentId) {
  waOuvrirSuivi();
  const l = document.getElementById('wa-lang');
  fetch('/whatsapp/api/queue_test/' + parentId + '?lang=' + encodeURIComponent(l ? l.value : 'both'))
    .then(r => r.json())
    .then(data => {
      if (data.erreur) { waAfficherErreur(data.erreur); return; }
      waAfficherListe(data.resultats);
    })
    .catch(() => waAfficherErreur('Erreur de communication avec le serveur.'));
}

/* Onglet Relances : tous les impayés (liste filtrée) */
function waLancerRappelsTous() {
  waOuvrirSuivi();
  fetch('/whatsapp/api/queue_rappels_tous?' + waQS())
    .then(r => r.json())
    .then(data => {
      if (data.erreur) { waAfficherErreur(data.erreur); return; }
      waAfficherListe(data.resultats);
    })
    .catch(() => waAfficherErreur('Erreur de communication avec le serveur.'));
}

/* Onglet Relances : un seul parent */
function waLancerRappelUn(parentId) {
  waOuvrirSuivi();
  fetch('/whatsapp/api/queue_rappel_un/' + parentId + '?' + waQS())
    .then(r => r.json())
    .then(data => {
      if (data.erreur) { waAfficherErreur(data.erreur); return; }
      waAfficherListe(data.resultats);
    })
    .catch(() => waAfficherErreur('Erreur de communication avec le serveur.'));
}

/* Onglet Message libre */
function waLancerMessage() {
  const message = document.getElementById('msg-textarea').value.trim();
  const parentIds = Array.from(document.querySelectorAll('.chk-msg:checked')).map(cb => cb.value);
  if (!message) { alert('Le message ne peut pas être vide.'); return; }
  if (parentIds.length === 0) { alert('Aucun parent sélectionné.'); return; }

  waOuvrirSuivi();
  fetch('/whatsapp/api/queue_message', {
    method: 'POST',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify({message: message, parent_ids: parentIds})
  })
    .then(r => r.json())
    .then(data => {
      if (data.erreur) { waAfficherErreur(data.erreur); return; }
      waAfficherListe(data.resultats, data.nb_sans_telephone);
    })
    .catch(() => waAfficherErreur('Erreur de communication avec le serveur.'));
}

/* Onglet Fichier */
function waLancerFichier() {
  const fichierInput = document.getElementById('fichier-input');
  const caption = document.getElementById('caption-input').value.trim();
  const parentIds = Array.from(document.querySelectorAll('.chk-file:checked')).map(cb => cb.value);
  if (!fichierInput.files.length) { alert('Sélectionnez un fichier.'); return; }
  if (parentIds.length === 0) { alert('Aucun parent sélectionné.'); return; }

  const fd = new FormData();
  fd.append('fichier', fichierInput.files[0]);
  fd.append('caption', caption);
  parentIds.forEach(id => fd.append('parent_ids', id));

  waOuvrirSuivi();
  fetch('/whatsapp/api/queue_fichier', {method: 'POST', body: fd})
    .then(r => r.json())
    .then(data => {
      if (data.erreur) { waAfficherErreur(data.erreur); return; }
      const box = document.getElementById('wa-wizard-fichier-box');
      box.style.display = 'block';
      box.innerHTML = '📎 <strong>' + data.fichier_nom + '</strong> — ' +
        '<a href="' + data.fichier_url + '" target="_blank" style="color:#0a4a91;font-weight:700;">Télécharger le fichier</a> ' +
        'puis joignez-le manuellement (glisser-déposer) dans chaque conversation WhatsApp avant de cliquer sur Envoyer.';
      waAfficherListe(data.resultats, data.nb_sans_telephone);
    })
    .catch(() => waAfficherErreur("Erreur d'envoi du fichier."));
}
</script>
</body>
</html>
'''

# ═══════════════════════════════════════════════════════════════════════════════
# 🎓 MODULE FORMATION  (🆕)
#  • ADMIN      : crée / lance / suit / relance / clôture des formations
#  • ENSEIGNANT : reçoit une notification + une carte en haut de l'écran tant qu'une
#                 formation n'est pas terminée ; peut commencer, s'arrêter au milieu
#                 et reprendre le lendemain exactement où il s'était arrêté.
#  • MOBILE     : coque « application » réservée au compte enseignant (barre d'onglets
#                 en bas, actions rapides, gestes, mode hors connexion, installable).
# Aucune route/table existante n'est modifiée : tout est additif.
# ═══════════════════════════════════════════════════════════════════════════════
FORMATION_CATEGORIES = ['Pédagogie', 'Gestion de classe', 'Numérique & outils', 'Sécurité & premiers secours',
                        'Langues', 'Évaluation & suivi', 'Administratif & règlement', 'Développement personnel', 'Autre']
FORMATION_NIVEAUX = ['Tous niveaux', 'Débutant', 'Intermédiaire', 'Avancé']
FORMATION_TYPES = {
    'presentiel': ('🏫', 'Présentiel'), 'en_ligne': ('💻', 'En ligne'), 'video': ('🎬', 'Vidéo'),
    'document': ('📄', 'Document / lecture'), 'atelier': ('🛠️', 'Atelier pratique'), 'mixte': ('🔀', 'Mixte'),
}
FORMATION_ETAPE_TYPES = {
    'lecture': ('📖', 'Lecture'), 'video': ('🎬', 'Vidéo'), 'document': ('📄', 'Document'),
    'exercice': ('✍️', 'Exercice'), 'seance': ('🏫', 'Séance'), 'evaluation': ('✅', 'Évaluation'),
}


# 📎 Fichiers et vidéos importés (même circuit que les devoirs : dossier dédié, inclus dans les sauvegardes/R2)
UPLOAD_FOLDER_FORMATIONS = os.path.join(os.path.dirname(__file__), 'uploads_formations')
os.makedirs(UPLOAD_FOLDER_FORMATIONS, exist_ok=True)
try:
    FORMATION_MAX_MO = int(os.environ.get('FORMATION_MAX_MO', '200'))  # taille max par fichier
except ValueError:
    FORMATION_MAX_MO = 200
FM_EXT_VIDEO = {'mp4', 'webm', 'mov', 'm4v', 'ogv'}
FM_EXT_AUDIO = {'mp3', 'm4a', 'wav', 'ogg', 'aac'}
FM_EXT_IMAGE = {'jpg', 'jpeg', 'png', 'webp', 'gif'}
FM_EXT_OFFICE = {'doc', 'docx', 'ppt', 'pptx', 'xls', 'xlsx', 'odt', 'odp', 'ods'}  # convertis en PDF à l'import
FM_EXT_OK = FM_EXT_VIDEO | FM_EXT_AUDIO | FM_EXT_IMAGE | {'pdf'} | FM_EXT_OFFICE
FM_ACCEPT = 'video/*,audio/*,image/*,.pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.odt,.odp,.ods'
FORMATION_SEUIL_PCT = 80  # temps minimum à passer (en % de la durée prévue) pour que la formation soit validée
try:
    FORMATION_SEUIL_PCT = min(100, max(1, int(os.environ.get('FORMATION_SEUIL_PCT', '80'))))
except ValueError:
    pass
FORMATION_RELANCE_JOURS = 2  # rappel automatique tous les N jours tant que la formation n'est pas terminée
try:
    FORMATION_RELANCE_JOURS = max(1, int(os.environ.get('FORMATION_RELANCE_JOURS', '2')))
except ValueError:
    pass


def _fm_ext(nom):
    return nom.rsplit('.', 1)[-1].lower() if nom and '.' in nom else ''


def _fm_kind(nom):
    e = _fm_ext(nom)
    return ('video' if e in FM_EXT_VIDEO else 'audio' if e in FM_EXT_AUDIO else 'image' if e in FM_EXT_IMAGE
            else 'pdf' if e == 'pdf' else 'doc')


def _fm_taille_txt(n):
    n = float(n or 0)
    for u in ('o', 'Ko', 'Mo', 'Go'):
        if n < 1024 or u == 'Go':
            return f"{n:.0f} {u}" if u == 'o' else f"{n:.1f} {u}".replace('.0 ', ' ')
        n /= 1024


def _fm_mmss(sec):
    s = int(sec or 0)
    return f"{s // 3600}:{(s % 3600) // 60:02d}:{s % 60:02d}" if s >= 3600 else f"{s // 60}:{s % 60:02d}"


def _fm_fichier_info(fid, eid, nom, orig, taille, pos=0):
    """Description d'un fichier importé pour les templates (None si aucun)."""
    if not nom:
        return None
    url = f"/formation/{fid}/etape/{eid}/fichier" if eid else f"/formation/{fid}/fichier"
    pos = float(pos or 0)
    return {'url': url, 'orig': orig or nom, 'taille': _fm_taille_txt(taille),
            'kind': _fm_kind(nom), 'eid': eid or 0, 'pos': pos, 'pos_txt': _fm_mmss(pos) if pos >= 5 else ''}


def _fm_valider_upload(fs):
    """Retourne '' si le fichier est acceptable, sinon le message d'erreur."""
    if not fs or not fs.filename:
        return ''
    if _fm_ext(fs.filename) not in FM_EXT_OK:
        return f"Format non accepté : « {fs.filename} ». Formats : vidéo (mp4, webm, mov), audio, image, PDF, ou Word / PowerPoint / Excel (convertis en PDF)."
    fs.stream.seek(0, 2)
    taille = fs.stream.tell()
    fs.stream.seek(0)
    if taille > FORMATION_MAX_MO * 1024 * 1024:
        return f"« {fs.filename} » dépasse {FORMATION_MAX_MO} Mo ({_fm_taille_txt(taille)})."
    return ''


def _fm_convertir_pdf(chemin):
    """Convertit un document Office en PDF avec LibreOffice (si installé sur le serveur). Retourne le chemin du PDF ou None."""
    import shutil, subprocess, tempfile, uuid
    exe = shutil.which('soffice') or shutil.which('libreoffice')
    if not exe:
        return None
    sortie = tempfile.mkdtemp(prefix='fm_pdf_')
    try:
        subprocess.run([exe, '-env:UserInstallation=file:///tmp/lo_profile_formation', '--headless', '--convert-to', 'pdf',
                        '--outdir', sortie, chemin], timeout=180, capture_output=True)
        produit = os.path.join(sortie, os.path.splitext(os.path.basename(chemin))[0] + '.pdf')
        if not os.path.isfile(produit):
            return None
        final = os.path.join(UPLOAD_FOLDER_FORMATIONS, uuid.uuid4().hex + '.pdf')
        shutil.move(produit, final)
        return final
    except Exception:
        return None
    finally:
        shutil.rmtree(sortie, ignore_errors=True)


def _fm_sauver_upload(fs, saved=None):
    """Enregistre le fichier sous un nom aléatoire. Retourne (nom_stocke, nom_original, taille).
    Word/PowerPoint/Excel sont convertis en PDF pour pouvoir être lus dans l'app (ValueError si conversion impossible)."""
    import uuid
    ext = _fm_ext(fs.filename)
    nom = f"{uuid.uuid4().hex}.{ext}"
    chemin = os.path.join(UPLOAD_FOLDER_FORMATIONS, nom)
    fs.save(chemin)
    if saved is not None:
        saved.append(nom)
    orig = re.sub(r'[\\/:*?"<>|\r\n]+', '_', os.path.basename(fs.filename)).strip()[:120] or nom
    if ext in FM_EXT_OFFICE:
        pdf = _fm_convertir_pdf(chemin)
        _fm_supprimer_fichiers([nom])
        if not pdf:
            raise ValueError(f"Impossible de convertir « {orig} » en PDF sur le serveur. "
                             f"Exportez-le en PDF depuis Word/PowerPoint/Excel puis importez le PDF.")
        nom = os.path.basename(pdf)
        chemin = pdf
        orig = os.path.splitext(orig)[0] + '.pdf'
        if saved is not None:
            saved.append(nom)
    return nom, orig, os.path.getsize(chemin)


def _fm_supprimer_fichiers(noms):
    for n in noms:
        if n:
            try:
                os.remove(os.path.join(UPLOAD_FOLDER_FORMATIONS, os.path.basename(n)))
            except OSError:
                pass


def upgrade_db_formations():
    """Crée les tables du module Formation (idempotent, sans toucher aux tables existantes)."""
    try:
        conn = get_db()
    except Exception:
        return
    try:
        conn.executescript("""
            CREATE TABLE IF NOT EXISTS formations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                titre TEXT NOT NULL,
                description TEXT DEFAULT '',
                categorie TEXT DEFAULT '',
                niveau TEXT DEFAULT '',
                type_formation TEXT DEFAULT 'en_ligne',
                formateur TEXT DEFAULT '',
                lieu TEXT DEFAULT '',
                lien_ressource TEXT DEFAULT '',
                objectifs TEXT DEFAULT '',
                prerequis TEXT DEFAULT '',
                consignes TEXT DEFAULT '',
                date_debut TEXT DEFAULT '',
                heure TEXT DEFAULT '',
                date_fin TEXT DEFAULT '',
                duree_heures REAL DEFAULT 0,
                obligatoire INTEGER DEFAULT 0,
                attestation INTEGER DEFAULT 0,
                public_cible TEXT DEFAULT 'tous',
                statut TEXT DEFAULT 'brouillon',
                cree_par INTEGER,
                created_at TEXT DEFAULT '',
                lancee_at TEXT DEFAULT ''
            );
            CREATE TABLE IF NOT EXISTS formation_etapes (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                formation_id INTEGER NOT NULL,
                ordre INTEGER DEFAULT 0,
                titre TEXT NOT NULL,
                description TEXT DEFAULT '',
                type_etape TEXT DEFAULT 'lecture',
                duree_min INTEGER DEFAULT 0,
                lien TEXT DEFAULT ''
            );
            CREATE TABLE IF NOT EXISTS formation_cibles (
                formation_id INTEGER NOT NULL,
                enseignant_id INTEGER NOT NULL,
                PRIMARY KEY (formation_id, enseignant_id)
            );
            CREATE TABLE IF NOT EXISTS formation_assignations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                formation_id INTEGER NOT NULL,
                enseignant_id INTEGER NOT NULL,
                statut TEXT DEFAULT 'a_faire',
                progression INTEGER DEFAULT 0,
                etape_courante_id INTEGER,
                date_debut_reel TEXT DEFAULT '',
                date_fin_reel TEXT DEFAULT '',
                derniere_activite TEXT DEFAULT '',
                note_perso TEXT DEFAULT '',
                UNIQUE (formation_id, enseignant_id)
            );
            CREATE TABLE IF NOT EXISTS formation_progression (
                assignation_id INTEGER NOT NULL,
                etape_id INTEGER NOT NULL,
                fait_le TEXT DEFAULT '',
                PRIMARY KEY (assignation_id, etape_id)
            );
            CREATE TABLE IF NOT EXISTS formation_video_pos (
                assignation_id INTEGER NOT NULL,
                etape_id INTEGER NOT NULL,
                pos REAL DEFAULT 0,
                PRIMARY KEY (assignation_id, etape_id)
            );
            CREATE TABLE IF NOT EXISTS formation_temps (
                assignation_id INTEGER NOT NULL,
                etape_id INTEGER NOT NULL,
                sec REAL DEFAULT 0,
                PRIMARY KEY (assignation_id, etape_id)
            );
            CREATE INDEX IF NOT EXISTS idx_fm_assign_ens ON formation_assignations(enseignant_id, statut);
            CREATE INDEX IF NOT EXISTS idx_fm_etapes_f ON formation_etapes(formation_id, ordre);
        """)
        for col in ("temps_total_sec REAL DEFAULT 0", "dernier_ping TEXT DEFAULT ''", "assigne_le TEXT DEFAULT ''",
                    "derniere_relance TEXT DEFAULT ''", "nb_relances INTEGER DEFAULT 0"):
            try:
                conn.execute(f"ALTER TABLE formation_assignations ADD COLUMN {col}")
            except sqlite3.OperationalError:
                pass
        for tbl, col in (('formations', "points_cles TEXT DEFAULT ''"),
                         ('formation_assignations', "fin_notifiee INTEGER DEFAULT 0")):
            try:
                conn.execute(f"ALTER TABLE {tbl} ADD COLUMN {col}")
            except sqlite3.OperationalError:
                pass
        for tbl in ('formations', 'formation_etapes'):
            for col in ("fichier_nom TEXT DEFAULT ''", "fichier_orig TEXT DEFAULT ''", "fichier_taille INTEGER DEFAULT 0"):
                try:
                    conn.execute(f"ALTER TABLE {tbl} ADD COLUMN {col}")
                except sqlite3.OperationalError:
                    pass  # colonne déjà présente
        conn.commit()
    except Exception as ex:
        print(f"  ⚠️  Migration formations : {ex}")
    finally:
        conn.close()


# ─────────────────────────── Helpers ───────────────────────────
def _fm_now():
    return datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')


def _fm_float(v, defaut=0.0):
    try:
        return max(0.0, float(str(v).replace(',', '.')))
    except Exception:
        return defaut


def _fm_int(v, defaut=0):
    try:
        return max(0, int(float(str(v).replace(',', '.'))))
    except Exception:
        return defaut


def _fm_echeance(date_fin, termine=False):
    """Retourne {'label','cls','jours'} : cls ∈ late | soon | ok | none | done."""
    if termine:
        return {'label': 'Terminée', 'cls': 'done', 'jours': None}
    try:
        d = datetime.date.fromisoformat(str(date_fin)[:10])
    except Exception:
        return {'label': 'Sans date limite', 'cls': 'none', 'jours': None}
    j = (d - datetime.date.today()).days
    if j < 0:
        return {'label': f"En retard de {-j} j", 'cls': 'late', 'jours': j}
    if j == 0:
        return {'label': "À terminer aujourd'hui", 'cls': 'soon', 'jours': 0}
    if j == 1:
        return {'label': 'À terminer demain', 'cls': 'soon', 'jours': 1}
    if j <= 5:
        return {'label': f"Encore {j} jours", 'cls': 'soon', 'jours': j}
    return {'label': f"Avant le {d.strftime('%d/%m/%Y')}", 'cls': 'ok', 'jours': j}


def _fm_depuis(dt_str):
    """« aujourd'hui à 17:40 », « hier », « il y a 3 j »…"""
    try:
        dt = datetime.datetime.strptime(str(dt_str)[:19], '%Y-%m-%d %H:%M:%S')
    except Exception:
        return ''
    j = (datetime.date.today() - dt.date()).days
    if j <= 0:
        return f"aujourd'hui à {dt.strftime('%H:%M')}"
    if j == 1:
        return f"hier à {dt.strftime('%H:%M')}"
    return f"il y a {j} jours"


def _fm_duree_txt(sec):
    s = int(float(sec or 0))
    if s <= 0:
        return '—'
    if s < 60:
        return f"{s} s"
    m = s // 60
    return f"{m} min" if m < 60 else f"{m // 60} h {m % 60:02d} min"


def _fm_seuil_sec(duree_h):
    """Temps minimum (secondes) = FORMATION_SEUIL_PCT % de la durée prévue."""
    return float(duree_h or 0) * 3600.0 * FORMATION_SEUIL_PCT / 100.0


def _fm_pct_temps(temps_sec, duree_h):
    """% du temps prévu réellement passé (None si aucune durée n'a été fixée)."""
    if not duree_h or float(duree_h) <= 0:
        return None
    return int(round(float(temps_sec or 0) * 100.0 / (float(duree_h) * 3600.0)))


def _fm_revision_requise(statut, temps_sec, duree_h):
    """Formation terminée mais temps passé < 80 % de la durée prévue → révision à faire."""
    return statut == 'termine' and float(duree_h or 0) > 0 and float(temps_sec or 0) < _fm_seuil_sec(duree_h)


def _fm_segment(statut, temps_sec, duree_h):
    """valide | insuffisant (terminé mais < 80 % du temps) | en_cours | pas_commence"""
    if statut == 'termine':
        return 'insuffisant' if _fm_revision_requise(statut, temps_sec, duree_h) else 'valide'
    return 'en_cours' if statut == 'en_cours' else 'pas_commence'


def _fm_get(f, k, d=None):
    try:
        v = f[k]
        return d if v is None else v
    except Exception:
        return d


def _fm_duree_msg(sec):
    """Comme _fm_duree_txt mais « 0 min » au lieu d'un tiret (pour les phrases des notifications)."""
    return '0 min' if float(sec or 0) <= 0 else _fm_duree_txt(sec)


def _fm_dt(s):
    try:
        return datetime.datetime.strptime(str(s)[:19], '%Y-%m-%d %H:%M:%S')
    except Exception:
        return None


def _fm_sql_revision(a='a', f='f'):
    return (f"({a}.statut='termine' AND COALESCE({f}.duree_heures,0)>0 AND "
            f"COALESCE({a}.temps_total_sec,0) < {f}.duree_heures*3600.0*{FORMATION_SEUIL_PCT}/100.0)")


def _fm_ctx(statut, progression, temps, duree_h):
    return {'statut': statut, 'progression': progression, 'temps': float(temps or 0),
            'revision': _fm_revision_requise(statut, temps, duree_h)}


def _fm_type(t):
    ico, lab = FORMATION_TYPES.get(t or '', ('🎓', 'Formation'))
    return ico, lab


def _fm_cibles_ids(conn, f):
    pc = (f['public_cible'] or 'tous')
    if pc.startswith('cycle:'):
        rows = conn.execute(
            """SELECT DISTINCT cp.enseignant_id FROM classe_profs cp JOIN classes c ON c.id=cp.classe_id
               JOIN users u ON u.id=cp.enseignant_id AND u.role='enseignant'
               WHERE COALESCE(NULLIF(c.cycle,''),'Primaire')=?""", (pc[6:],)).fetchall()
    elif pc == 'selection':
        rows = conn.execute(
            """SELECT fc.enseignant_id FROM formation_cibles fc JOIN users u ON u.id=fc.enseignant_id
               WHERE fc.formation_id=? AND u.role='enseignant'""", (f['id'],)).fetchall()
    else:
        rows = conn.execute("SELECT id FROM users WHERE role='enseignant'").fetchall()
    return {r[0] for r in rows}


def _fm_msg_revision(f, temps):
    """Texte commun : temps passé insuffisant → petite révision."""
    duree = float(_fm_get(f, 'duree_heures', 0) or 0)
    seuil = _fm_seuil_sec(duree)
    reste = max(0.0, seuil - float(temps or 0))
    pct = _fm_pct_temps(temps, duree) or 0
    return (f"📚 « {f['titre']} » : vous avez passé {_fm_duree_msg(temps)} sur {_fm_duree_txt(duree * 3600)} prévues ({pct} %). "
            f"Il faut au moins {FORMATION_SEUIL_PCT} % ({_fm_duree_txt(seuil)}) : encore {_fm_duree_msg(reste)}. "
            f"Faites une petite révision (points clés, supports) pour valider la formation.")


def _fm_notifier(conn, f, uid, rappel=False, ctx=None):
    titre_f = f['titre']
    ctx = ctx or {}
    duree = float(_fm_get(f, 'duree_heures', 0) or 0)
    ech, retard = '', False
    if f['date_fin']:
        e = _fm_echeance(f['date_fin'])
        ech = f" {e['label']}." if e['cls'] != 'none' else ''
        retard = e['cls'] == 'late'
    mini = ''
    if duree > 0:
        mini = (f" Temps minimum requis : {_fm_duree_txt(_fm_seuil_sec(duree))} "
                f"({FORMATION_SEUIL_PCT} % des {_fm_duree_txt(duree * 3600)} prévues).")
    meta = {'ico': '🎓', 'couleur': '#7C3AED', 'cta': 'Ouvrir la formation'}
    if rappel and ctx.get('revision'):
        titre, msg, prio = 'Révision à faire', _fm_msg_revision(f, ctx.get('temps', 0)) + ech, 'haute'
        meta = {'ico': '📚', 'couleur': '#D97706', 'cta': 'Faire ma révision'}
    elif rappel:
        if ctx.get('statut') == 'en_cours':
            base = f"Reprenez la formation « {titre_f} » ({ctx.get('progression', 0)} % réalisée)."
        else:
            base = f"Vous n'avez pas encore commencé la formation « {titre_f} »."
        titre = 'Formation en retard' if retard else 'Rappel de formation'
        msg = f"{'⚠️' if retard else '🎓'} Rappel : {base}{ech}{mini}"
        prio = 'haute' if (retard or f['obligatoire']) else 'normale'
    else:
        titre = 'Nouvelle formation'
        msg = (f"🎓 Nouvelle formation « {titre_f} » lancée par l'administration.{ech}{mini} "
               f"Vous pouvez la commencer et reprendre quand vous voulez.")
        prio = 'haute' if f['obligatoire'] else 'normale'
    try:
        notif_to_parent(uid, msg, conn, categorie='autre', titre=titre, url=f"/formation/{f['id']}",
                        meta=meta, prio=prio, tag=f"formation-{f['id']}")
    except Exception as ex:
        print(f"  ⚠️  Notification formation : {ex}")


def _fm_synchroniser(conn, fid):
    """Crée les assignations manquantes d'une formation lancée et notifie les nouveaux destinataires."""
    f = conn.execute("SELECT * FROM formations WHERE id=?", (fid,)).fetchone()
    if not f or f['statut'] != 'lancee':
        return 0
    cibles = _fm_cibles_ids(conn, f)
    existants = {r[0]: r[1] for r in conn.execute(
        "SELECT enseignant_id, statut FROM formation_assignations WHERE formation_id=?", (fid,)).fetchall()}
    nouveaux = [u for u in cibles if u not in existants]
    for uid in nouveaux:
        conn.execute("INSERT OR IGNORE INTO formation_assignations (formation_id, enseignant_id, statut, progression, assigne_le) "
                     "VALUES (?,?, 'a_faire', 0, ?)", (fid, uid, _fm_now()))
        _fm_notifier(conn, f, uid)
    # Les enseignants qui ne sont plus ciblés ET n'ont encore rien commencé sont retirés.
    for uid, st in existants.items():
        if uid not in cibles and st == 'a_faire':
            conn.execute("DELETE FROM formation_assignations WHERE formation_id=? AND enseignant_id=?", (fid, uid))
    return len(nouveaux)


def _fm_recalculer(conn, aid):
    """Recalcule progression + statut d'une assignation à partir des étapes cochées."""
    a = conn.execute("SELECT * FROM formation_assignations WHERE id=?", (aid,)).fetchone()
    if not a:
        return None
    total = conn.execute("SELECT COUNT(*) FROM formation_etapes WHERE formation_id=?", (a['formation_id'],)).fetchone()[0]
    fait = conn.execute("""SELECT COUNT(*) FROM formation_progression p
                           JOIN formation_etapes e ON e.id=p.etape_id
                           WHERE p.assignation_id=? AND e.formation_id=?""", (aid, a['formation_id'])).fetchone()[0]
    statut, fin = a['statut'], a['date_fin_reel'] or ''
    if total:
        prog = round(fait * 100 / total)
        if fait >= total:
            statut, fin = 'termine', (fin or _fm_now())
        elif fait > 0 or a['date_debut_reel']:
            statut, fin = 'en_cours', ''
        else:
            statut, fin = 'a_faire', ''
    else:
        prog = 100 if statut == 'termine' else 0
    conn.execute("UPDATE formation_assignations SET progression=?, statut=?, date_fin_reel=? WHERE id=?",
                 (prog, statut, fin, aid))
    return {'progression': prog, 'statut': statut, 'nb_fait': fait, 'nb_total': total,
            'vient_de_finir': statut == 'termine' and a['statut'] != 'termine'}


def _fm_nom_enseignant(conn, uid):
    u = conn.execute("SELECT prenom, nom FROM users WHERE id=?", (uid,)).fetchone()
    return f"{u['prenom']} {u['nom']}" if u else 'Un enseignant'


def _fm_notifier_admins(conn, msg, titre, fid, couleur, ico='🎓', cta='Voir le suivi', segment=''):
    try:
        url = f"/formation/{fid}" + (f"?seg={segment}" if segment else '')
        for r in conn.execute(f"SELECT id FROM users WHERE role IN ({ROLES_ADMIN_SQL})").fetchall():
            notif_to_parent(r['id'], msg, conn, categorie='autre', titre=titre, url=url,
                            meta={'ico': ico, 'couleur': couleur, 'cta': cta}, prio='haute' if segment else 'normale')
    except Exception as ex:
        print(f"  ⚠️  Notification admin formation : {ex}")


def _fm_notifier_admins_fin(conn, f, uid):
    _fm_notifier_admins(conn, f"✅ {_fm_nom_enseignant(conn, uid)} a terminé la formation « {f['titre']} ».",
                        'Formation terminée', f['id'], '#059669')


def _fm_apres_fin(conn, fid, uid, aid):
    """Appelé quand un enseignant vient de terminer toutes les étapes. Vérifie la règle des 80 % du temps :
    - temps suffisant (ou aucune durée fixée) → l'admin est simplement informé ;
    - temps < 80 % → l'enseignant ET l'admin sont notifiés, l'enseignant est invité à faire une petite révision."""
    a = conn.execute("SELECT temps_total_sec, fin_notifiee FROM formation_assignations WHERE id=?", (aid,)).fetchone()
    f = conn.execute("SELECT * FROM formations WHERE id=?", (fid,)).fetchone()
    if not a or not f or a['fin_notifiee']:
        return
    conn.execute("UPDATE formation_assignations SET fin_notifiee=1 WHERE id=?", (aid,))
    temps = float(a['temps_total_sec'] or 0)
    if not _fm_revision_requise('termine', temps, f['duree_heures']):
        _fm_notifier_admins_fin(conn, f, uid)
        return
    _fm_notifier(conn, f, uid, rappel=True, ctx={'statut': 'termine', 'revision': True, 'temps': temps})
    conn.execute("UPDATE formation_assignations SET derniere_relance=?, nb_relances=COALESCE(nb_relances,0)+1 WHERE id=?",
                 (_fm_now(), aid))
    duree = float(f['duree_heures'])
    _fm_notifier_admins(
        conn, (f"⚠️ {_fm_nom_enseignant(conn, uid)} a terminé « {f['titre']} » en {_fm_duree_msg(temps)} seulement "
               f"({_fm_pct_temps(temps, duree)} % des {_fm_duree_txt(duree * 3600)} prévues, minimum {FORMATION_SEUIL_PCT} %). "
               f"Une invitation à réviser lui a été envoyée."),
        'Temps de formation insuffisant', f['id'], '#D97706', ico='⚠️', cta='Voir les < 80 %', segment='moins80')


def _fm_validation_temps(conn, f, uid, aid):
    """L'enseignant (déjà « terminé ») vient d'atteindre le temps minimum grâce à sa révision → formation validée."""
    try:
        notif_to_parent(uid, (f"🎉 Révision terminée : vous avez atteint le temps minimum ({FORMATION_SEUIL_PCT} %) pour la "
                              f"formation « {f['titre']} ». Elle est maintenant validée. Bravo !"), conn, categorie='autre',
                        titre='Formation validée', url=f"/formation/{f['id']}",
                        meta={'ico': '🎓', 'couleur': '#059669', 'cta': 'Voir la formation'}, prio='normale',
                        tag=f"formation-{f['id']}")
    except Exception as ex:
        print(f"  ⚠️  Notification validation formation : {ex}")
    _fm_notifier_admins(conn, f"✅ {_fm_nom_enseignant(conn, uid)} a atteint le temps minimum ({FORMATION_SEUIL_PCT} %) "
                              f"pour « {f['titre']} » après révision : formation validée.",
                        'Formation validée', f['id'], '#059669')


def _fm_assignation_enseignant(conn, fid, uid):
    return conn.execute(
        """SELECT a.*, f.statut AS f_statut FROM formation_assignations a JOIN formations f ON f.id=a.formation_id
           WHERE a.formation_id=? AND a.enseignant_id=? AND f.statut IN ('lancee','cloturee')""", (fid, uid)).fetchone()


def formation_resume_enseignant(uid):
    """Données de la carte d'alerte : formations à passer + à réviser (terminées mais < 80 % du temps)."""
    conn = get_db()
    try:
        rows = conn.execute(
            """SELECT f.id, f.titre, f.date_fin, f.duree_heures, a.statut, a.progression, a.derniere_activite, a.temps_total_sec
               FROM formation_assignations a JOIN formations f ON f.id=a.formation_id
               WHERE a.enseignant_id=? AND f.statut='lancee'
               ORDER BY (a.statut='en_cours') DESC, CASE WHEN f.date_fin='' THEN '9999' ELSE f.date_fin END ASC""",
            (uid,)).fetchall()
    finally:
        conn.close()
    res = {'nb': 0, 'en_cours': 0, 'retard': 0, 'revision': 0, 'prochaine': None, 'cible': None, 'cible_titre': ''}
    dates, utiles = [], []
    for r in rows:
        rev = _fm_revision_requise(r['statut'], r['temps_total_sec'], r['duree_heures'])
        if r['statut'] == 'termine' and not rev:
            continue
        utiles.append(r)
        res['nb'] += 1
        if rev:
            res['revision'] += 1
        elif r['statut'] == 'en_cours':
            res['en_cours'] += 1
        e = _fm_echeance(r['date_fin'])
        if e['cls'] == 'late':
            res['retard'] += 1
        if e['cls'] in ('late', 'soon', 'ok'):
            dates.append((e['jours'], e['label']))
    if dates:
        res['prochaine'] = sorted(dates)[0][1]
    if utiles:
        res['cible'], res['cible_titre'] = utiles[0]['id'], utiles[0]['titre']
    return res


def _formation_banner_html(r, path=''):
    """Carte affichée en haut de l'écran de l'enseignant tant qu'il lui reste des formations à passer."""
    if str(path).startswith('/formation') or not r.get('nb'):
        return ''
    nb = r['nb']
    titre = f"{nb} formation{'s' if nb > 1 else ''} à passer"
    morceaux = []
    if r['en_cours']:
        morceaux.append(f"{r['en_cours']} en cours")
    if r.get('revision'):
        morceaux.append(f"{r['revision']} à réviser (moins de {FORMATION_SEUIL_PCT} % du temps)")
    if r['retard']:
        morceaux.append(f"{r['retard']} en retard")
    if r['prochaine']:
        morceaux.append(r['prochaine'])
    sous = ' · '.join(morceaux) or 'Commencez quand vous voulez, vous pourrez reprendre plus tard.'
    lien = f"/formation/{r['cible']}" if nb == 1 and r['cible'] else '/formation'
    cta = 'Réviser' if (r.get('revision') and nb == r['revision']) else ('Continuer' if (r['en_cours'] or r.get('revision')) else 'Commencer')
    cls = 'fm-banner late' if r['retard'] else 'fm-banner'
    return f"""
<style>
.fm-banner{{display:flex;align-items:center;gap:14px;margin:0 0 16px;padding:14px 16px;border-radius:18px;color:#fff;
  background:linear-gradient(135deg,#6D28D9,#4F46E5 60%,#2563EB);box-shadow:0 14px 30px -14px rgba(79,70,229,.7);position:relative;overflow:hidden;}}
.fm-banner.late{{background:linear-gradient(135deg,#DC2626,#EA580C);box-shadow:0 14px 30px -14px rgba(220,38,38,.7);}}
.fm-banner::after{{content:"";position:absolute;right:-30px;top:-40px;width:130px;height:130px;border-radius:50%;background:rgba(255,255,255,.12);}}
.fm-banner-ico{{flex:0 0 44px;height:44px;border-radius:14px;background:rgba(255,255,255,.2);display:flex;align-items:center;justify-content:center;font-size:1.4rem;position:relative;z-index:1;}}
.fm-banner-txt{{flex:1;min-width:0;position:relative;z-index:1;}}
.fm-banner-txt b{{display:block;font-size:.98rem;line-height:1.25;}}
.fm-banner-txt span{{display:block;font-size:.78rem;opacity:.92;margin-top:2px;}}
.fm-banner-btn{{position:relative;z-index:1;flex:0 0 auto;background:#fff;color:#4338CA;font-weight:800;font-size:.82rem;padding:10px 16px;border-radius:12px;white-space:nowrap;}}
.fm-banner.late .fm-banner-btn{{color:#B91C1C;}}
@media(max-width:560px){{.fm-banner{{flex-wrap:wrap;padding:13px 14px;}}.fm-banner-btn{{width:100%;text-align:center;}}}}
</style>
<a class="{cls}" href="{lien}" style="text-decoration:none;">
  <div class="fm-banner-ico">🎓</div>
  <div class="fm-banner-txt"><b>{titre}</b><span>{sous}</span></div>
  <div class="fm-banner-btn">{cta} →</div>
</a>"""


def formation_nav_extra(role, path=''):
    """Injecté par nav_html : carte « formations à passer » + coque mobile (enseignant),
    même coque mobile pour la secrétaire (sans carte formation)."""
    if role == 'secretaire':
        try:
            return sec_mobile_shell_html(path)
        except Exception as ex:
            print(f"  ⚠️  Coque secrétaire : {ex}")
            return ''
    if role != 'enseignant':
        return ''
    try:
        r = formation_resume_enseignant(session.get('user_id'))
    except Exception:
        r = {'nb': 0}
    try:
        return _formation_banner_html(r, path) + ens_mobile_shell_html(path, r.get('nb', 0))
    except Exception as ex:
        print(f"  ⚠️  Coque enseignant : {ex}")
        return ''


# ─────────────── Coque mobile « application » (compte enseignant uniquement) ───────────────
def ens_mobile_shell_html(path='', nb_formations=0, tabs_html=None, grid_html=None, avec_pwa=True):
    """Barre d'onglets en bas, feuille d'actions rapides, gestes, mode hors connexion, PWA.
    Entièrement inactive au-dessus de 960 px (ordinateur) : rien ne change sur grand écran."""
    def on(p, exact=False):
        return ' on' if (path == p if exact else (path == p or path.startswith(p + '/'))) else ''
    badge = f'<em class="ens-badge">{nb_formations}</em>' if nb_formations else ''
    if tabs_html is None:
        tabs_html = f"""  <a href="/dashboard" class="ens-tab{on('/dashboard', True)}"><i data-lucide="house"></i><span>Accueil</span></a>
  <a href="/notes" class="ens-tab{on('/notes')}"><i data-lucide="file-text"></i><span>Notes</span></a>
  <button type="button" class="ens-fab" onclick="ensToggleSheet()" aria-label="Actions rapides"><i data-lucide="plus"></i></button>
  <a href="/formation" class="ens-tab{on('/formation')}"><i data-lucide="graduation-cap"></i><span>Formation</span>{badge}</a>
  <a href="/messages" class="ens-tab{on('/messages')}"><i data-lucide="mail"></i><span>Messages</span></a>"""
    if grid_html is None:
        grid_html = f"""    <a class="ens-act" href="/absences"><b>🗓️</b>Faire l'appel</a>
    <a class="ens-act" href="/notes"><b>📝</b>Saisir des notes</a>
    <a class="ens-act" href="/devoirs"><b>📚</b>Nouveau devoir</a>
    <a class="ens-act" href="/communications"><b>📢</b>Communications</a>
    <a class="ens-act" href="/formation"><b>🎓</b>Mes formations</a>
    <a class="ens-act" href="/conges"><b>🌴</b>Mes congés</a>
    <a class="ens-act" href="/eleves"><b>🧒</b>Mes élèves</a>
    <a class="ens-act" href="/espace-enseignant"><b>🏫</b>Mon espace</a>
    <button type="button" class="ens-act" onclick="ensToggleSheet(false);toggleSidebar();"><b>☰</b>Tout le menu</button>
    <button type="button" class="ens-act" onclick="ensToggleSheet(false);var t=document.getElementById('theme-toggle-fab');if(t){{t.click();}}"><b>🌙</b>Thème clair / néon</button>"""
    if avec_pwa:
        install_html = '''<button type="button" class="ens-install" id="ensInstall">📲 Installer l'application sur mon téléphone</button>'''
        pwa_js = f"""  // PWA : manifeste + couleur de barre + invite d'installation
  var l=document.createElement('link'); l.rel='manifest'; l.href='/manifest-ens.webmanifest'; document.head.appendChild(l);
  var m=document.createElement('meta'); m.name='theme-color'; m.content='#1a3a5c'; document.head.appendChild(m);
  var dp=null;
  window.addEventListener('beforeinstallprompt', function(e){{ e.preventDefault(); dp=e; var b=document.getElementById('ensInstall'); if(b){{ b.style.display='block'; }} }});
  document.getElementById('ensInstall').addEventListener('click', function(){{ if(dp){{ dp.prompt(); dp=null; this.style.display='none'; }} }});"""
    else:
        # Compte secrétaire : même coque visuelle, sans manifeste « Espace enseignant » ni invite d'installation.
        install_html = ''
        pwa_js = """  var m=document.createElement('meta'); m.name='theme-color'; m.content='#1a3a5c'; document.head.appendChild(m);"""
    return f"""
<style>
:root{{--ens-nav-h:66px;}}
.ens-tabbar,.ens-sheet,.ens-sheet-bg,.ens-offline{{display:none;}}
@media(max-width:960px){{
  body.ens-mobile{{padding-bottom:calc(var(--ens-nav-h) + env(safe-area-inset-bottom,0px) + 8px);-webkit-tap-highlight-color:transparent;}}
  /* Le <body> ne doit jamais être sa propre zone de défilement : seul l'écran défile (sinon le doigt « s'arrête » avant le bas). */
  @supports (overflow:clip){{body.ens-mobile{{overflow-x:clip !important;overflow-y:visible !important;}}}}
  body.ens-mobile #theme-toggle-fab{{display:none !important;}}
  body.ens-mobile .content{{padding:14px 12px 18px !important;animation:ensIn .22s ease;}}
  body.ens-mobile .topbar{{position:sticky;top:0;z-index:60;backdrop-filter:saturate(1.6) blur(14px);-webkit-backdrop-filter:saturate(1.6) blur(14px);
      background:rgba(255,255,255,.82);padding-top:calc(8px + env(safe-area-inset-top,0px));}}
  body.ens-mobile .sidebar-toggle{{display:none !important;}}
  body.ens-mobile .card,body.ens-mobile .lux-hero{{border-radius:18px !important;}}
  body.ens-mobile input,body.ens-mobile select,body.ens-mobile textarea{{font-size:16px !important;}}
  body.ens-mobile .btn,body.ens-mobile button.btn{{min-height:42px;border-radius:12px;touch-action:manipulation;}}
  body.ens-mobile .ens-tscroll{{display:block;overflow-x:auto;-webkit-overflow-scrolling:touch;max-width:100%;border-radius:12px;}}
  body.ens-mobile .ens-tscroll.sticky-1 table th:first-child,body.ens-mobile .ens-tscroll.sticky-1 table td:first-child{{position:sticky;left:0;z-index:2;background:var(--card-bg,#fff);box-shadow:2px 0 6px -4px rgba(0,0,0,.25);}}
  body.ens-mobile.kb-open .ens-tabbar{{transform:translateY(120%);}}
  .ens-tabbar{{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:900;height:calc(var(--ens-nav-h) + env(safe-area-inset-bottom,0px));
      padding:6px 8px env(safe-area-inset-bottom,0px);align-items:center;justify-content:space-around;
      background:rgba(255,255,255,.86);backdrop-filter:saturate(1.8) blur(18px);-webkit-backdrop-filter:saturate(1.8) blur(18px);
      border-top:1px solid rgba(0,0,0,.07);box-shadow:0 -10px 30px -18px rgba(15,23,42,.35);transition:transform .22s ease;}}
  .ens-tab{{flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;height:100%;position:relative;
      font-size:.66rem;font-weight:700;color:#6b7280;touch-action:manipulation;}}
  .ens-tab svg{{width:22px;height:22px;stroke-width:2;transition:transform .2s ease;}}
  .ens-tab.on{{color:var(--blue-mid,#2563eb);}}
  .ens-tab.on svg{{transform:translateY(-2px) scale(1.08);}}
  .ens-tab.on::before{{content:"";position:absolute;top:2px;width:22px;height:3px;border-radius:99px;background:var(--blue-mid,#2563eb);}}
  .ens-badge{{position:absolute;top:5px;left:calc(50% + 6px);min-width:17px;height:17px;padding:0 4px;border-radius:99px;background:#EF4444;color:#fff;font-style:normal;font-size:.62rem;font-weight:800;display:flex;align-items:center;justify-content:center;border:2px solid #fff;}}
  .ens-fab{{flex:0 0 58px;width:58px;height:58px;margin-top:-26px;border:none;border-radius:50%;cursor:pointer;color:#fff;display:flex;align-items:center;justify-content:center;
      background:linear-gradient(135deg,#2563eb,#7c3aed);box-shadow:0 12px 24px -8px rgba(79,70,229,.8),0 0 0 5px rgba(255,255,255,.9);transition:transform .2s ease;touch-action:manipulation;}}
  .ens-fab svg{{width:26px;height:26px;transition:transform .25s ease;}}
  body.ens-sheet-open .ens-fab svg{{transform:rotate(45deg);}}
  .ens-sheet-bg{{display:block;position:fixed;inset:0;z-index:950;background:rgba(15,23,42,.45);opacity:0;pointer-events:none;transition:opacity .2s ease;}}
  body.ens-sheet-open .ens-sheet-bg{{opacity:1;pointer-events:auto;}}
  .ens-sheet{{display:block;position:fixed;left:0;right:0;bottom:0;z-index:960;background:var(--card-bg,#fff);border-radius:24px 24px 0 0;
      padding:10px 16px calc(18px + env(safe-area-inset-bottom,0px));transform:translateY(105%);transition:transform .28s cubic-bezier(.32,.72,0,1);max-height:82dvh;overflow-y:auto;}}
  body.ens-sheet-open .ens-sheet{{transform:translateY(0);}}
  .ens-sheet-grip{{width:42px;height:5px;border-radius:99px;background:#d1d5db;margin:0 auto 12px;}}
  .ens-sheet h3{{font-size:1rem;margin:0 0 12px;}}
  .ens-grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;}}
  .ens-act{{display:flex;flex-direction:column;align-items:center;gap:7px;padding:14px 6px;border-radius:16px;background:#f3f4f6;font-size:.72rem;font-weight:700;text-align:center;color:#111827;touch-action:manipulation;border:none;font-family:inherit;}}
  .ens-act:active{{transform:scale(.96);}}
  .ens-act b{{width:42px;height:42px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:1.3rem;background:#fff;box-shadow:0 4px 10px -6px rgba(0,0,0,.4);}}
  .ens-install{{display:none;margin-top:12px;width:100%;padding:13px;border:none;border-radius:14px;background:#111827;color:#fff;font-weight:800;font-family:inherit;}}
  .ens-offline{{display:block;position:fixed;top:calc(8px + env(safe-area-inset-top,0px));left:50%;z-index:1200;transform:translate(-50%,-160%);transition:transform .25s ease;
      background:#111827;color:#fff;padding:8px 16px;border-radius:99px;font-size:.78rem;font-weight:700;white-space:nowrap;box-shadow:0 10px 24px -10px rgba(0,0,0,.6);}}
  body.ens-offline-on .ens-offline{{transform:translate(-50%,0);}}
}}
/* opacité seulement : un transform animé sur .content ancrerait tous les éléments « fixed » (feuilles, modales) au bas de la page */
@keyframes ensIn{{from{{opacity:0;}}to{{opacity:1;}}}}
@media(prefers-reduced-motion:reduce){{body.ens-mobile .content{{animation:none;}}}}
</style>
<nav class="ens-tabbar" id="ensTabbar" aria-label="Navigation principale">
{tabs_html}
</nav>
<div class="ens-sheet-bg" id="ensSheetBg" onclick="ensToggleSheet(false)"></div>
<div class="ens-sheet" id="ensSheet" role="dialog" aria-label="Actions rapides">
  <div class="ens-sheet-grip"></div>
  <h3>⚡ Actions rapides</h3>
  <div class="ens-grid">
{grid_html}
  </div>
  {install_html}
</div>
<div class="ens-offline" id="ensOffline">📡 Hors connexion</div>
<script>
(function(){{
  var mq = window.matchMedia ? window.matchMedia('(max-width:960px)') : {{matches:false}};
  document.body.classList.add('ens-mobile');
  ['ensTabbar','ensSheetBg','ensSheet','ensOffline'].forEach(function(id){{
    var e=document.getElementById(id); if(e && e.parentNode!==document.body){{ document.body.appendChild(e); }}
  }});
  window.ensToggleSheet = function(force){{
    var open = (typeof force==='boolean') ? force : !document.body.classList.contains('ens-sheet-open');
    document.body.classList.toggle('ens-sheet-open', open);
    if(open && navigator.vibrate){{ navigator.vibrate(12); }}
  }};
  document.addEventListener('keydown', function(e){{ if(e.key==='Escape'){{ ensToggleSheet(false); }} }});
  // Retour haptique léger sur les onglets
  document.getElementById('ensTabbar').addEventListener('click', function(e){{
    if(e.target.closest('.ens-tab') && navigator.vibrate){{ navigator.vibrate(8); }}
  }});
  // Le clavier ne doit pas pousser la barre d'onglets au-dessus des champs
  document.addEventListener('focusin', function(e){{ if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)){{ document.body.classList.add('kb-open'); }} }});
  document.addEventListener('focusout', function(){{ setTimeout(function(){{
    var a=document.activeElement; if(!a || !/INPUT|TEXTAREA|SELECT/.test(a.tagName)){{ document.body.classList.remove('kb-open'); }} }}, 120); }});
  // Mode hors connexion
  function maj(){{ document.body.classList.toggle('ens-offline-on', !navigator.onLine); }}
  window.addEventListener('online', maj); window.addEventListener('offline', maj); maj();
  // Geste : glisser depuis le bord gauche pour ouvrir le menu, vers la gauche pour le fermer
  var sx=null, sy=null;
  document.addEventListener('touchstart', function(e){{ var t=e.touches[0]; sx=t.clientX; sy=t.clientY; }}, {{passive:true}});
  document.addEventListener('touchend', function(e){{
    if(sx===null || !mq.matches){{ return; }}
    var t=e.changedTouches[0], dx=t.clientX-sx, dy=Math.abs(t.clientY-sy);
    var ouvert=document.body.classList.contains('sidebar-open');
    if(!ouvert && sx<18 && dx>70 && dy<60){{ toggleSidebar(); }}
    else if(ouvert && dx<-70 && dy<60){{ closeSidebar(); }}
    sx=null;
  }}, {{passive:true}});
  // Tableaux : défilement horizontal propre (1re colonne figée si le tableau est large)
  document.addEventListener('DOMContentLoaded', function(){{
    if(!mq.matches){{ return; }}
    document.querySelectorAll('.content table').forEach(function(tb){{
      if(tb.closest('.ens-tscroll') || tb.closest('.ens-tabbar')){{ return; }}
      var p=tb.parentElement, cs=p?getComputedStyle(p):null;
      if(cs && (cs.overflowX==='auto' || cs.overflowX==='scroll')){{ return; }}
      var w=document.createElement('div'); w.className='ens-tscroll';
      var cols=tb.rows.length ? tb.rows[0].cells.length : 0;
      if(cols>4){{ w.className+=' sticky-1'; }}
      tb.parentNode.insertBefore(w,tb); w.appendChild(tb);
    }});
  }});
{pwa_js}
}})();
</script>"""


# ─────────────── Coque mobile « application » (compte secrétaire) ───────────────
# Même design que celle de l'enseignant (barre d'onglets, bouton +, feuille d'actions rapides),
# alimentée UNIQUEMENT par les pages que la secrétaire a déjà dans son menu (aucune option en plus).
_SEC_TAB_PRIORITE = ('/absences', '/pointage-professeurs', '/classes', '/emploi-temps', '/devoirs', '/messages')
_SEC_TAB_LABELS = {'/absences': 'Absences', '/pointage-professeurs': 'Pointage', '/classes': 'Classes',
                   '/emploi-temps': 'Planning', '/devoirs': 'Devoirs', '/messages': 'Messages'}


def sec_mobile_shell_html(path=''):
    from markupsafe import escape as _esc
    try:
        liens = _liens_nav_autorises('secretaire')
    except Exception:
        liens = list(NAV_LINKS.get('secretaire', []))
    icones = {chemin: ico for _l, ico, chemin in liens}
    chemins = [c for _l, _i, c in liens]

    def on(p, exact=False):
        return ' on' if (path == p if exact else (path == p or path.startswith(p + '/'))) else ''

    def tab(href, ico, label, exact=False):
        return (f'<a href="{href}" class="ens-tab{on(href, exact)}"><i data-lucide="{ico}"></i>'
                f'<span>{_esc(label)}</span></a>')

    choix = [c for c in _SEC_TAB_PRIORITE if c in chemins][:3]
    gauche = [tab('/secretaire/dashboard', 'house', 'Accueil', True)]
    droite = []
    for k, c in enumerate(choix):
        (gauche if k == 0 else droite).append(tab(c, icones.get(c, 'circle'), _SEC_TAB_LABELS.get(c, c)))
    fab = ('<button type="button" class="ens-fab" onclick="ensToggleSheet()" aria-label="Actions rapides">'
           '<i data-lucide="plus"></i></button>')
    tabs_html = '\n  '.join(gauche + [fab] + droite) + '\n'

    # Feuille « Actions rapides » : exactement les accès déjà proposés par son tableau de bord
    acts, vus = '', set()
    for label, _ico, chemin in liens:
        if chemin in ('/profile', '/secretaire/dashboard', '/dashboard') or chemin in vus:
            continue
        vus.add(chemin)
        acts += f'<a class="ens-act" href="{chemin}"><b>{_SD_ICONES.get(chemin, "📌")}</b>{_esc(label)}</a>\n    '
    for label, chemin in (('Messages', '/messages'), ('Notifications', '/notifications')):
        if chemin not in vus:
            acts += f'<a class="ens-act" href="{chemin}"><b>{_SD_ICONES.get(chemin, "📌")}</b>{label}</a>\n    '
    acts += ('<button type="button" class="ens-act" onclick="ensToggleSheet(false);toggleSidebar();"><b>☰</b>Tout le menu</button>\n    '
             '<button type="button" class="ens-act" onclick="ensToggleSheet(false);var t=document.getElementById(\'theme-toggle-fab\');'
             'if(t){t.click();}"><b>🌙</b>Thème clair / néon</button>\n')
    return ens_mobile_shell_html(path, 0, tabs_html=tabs_html, grid_html=acts, avec_pwa=False)


@app.route('/manifest-ens.webmanifest')
def manifest_enseignant():
    icons = []
    try:
        f = get_logo_filename()
        if f and f.rsplit('.', 1)[-1].lower() in ('png', 'jpg', 'jpeg', 'webp'):
            mime = {'png': 'image/png', 'jpg': 'image/jpeg', 'jpeg': 'image/jpeg', 'webp': 'image/webp'}[f.rsplit('.', 1)[-1].lower()]
            icons = [{'src': '/logo-ecole', 'sizes': '512x512', 'type': mime, 'purpose': 'any'}]
    except Exception:
        pass
    data = {'name': f"{get_nom_ecole()} — Espace enseignant", 'short_name': get_nom_ecole_court(),
            'start_url': '/dashboard', 'scope': '/', 'display': 'standalone', 'orientation': 'portrait',
            'background_color': '#f5f7fb', 'theme_color': '#1a3a5c', 'lang': 'fr', 'icons': icons}
    return app.response_class(json.dumps(data, ensure_ascii=False), mimetype='application/manifest+json')


