# ─────────────────────── Rappels automatiques ───────────────────────
def formation_relances_auto(forcer=False):
    """Tâche planifiée (toutes les heures, de 8 h à 20 h) :
    chaque enseignant qui n'a pas terminé une formation lancée est relancé tous les N jours (2 par défaut)
    jusqu'à ce qu'il la termine. Le décompte repart de zéro à chaque lancement, rappel ou activité de
    l'enseignant sur la formation : quelqu'un qui travaille dessus n'est donc pas harcelé."""
    if not forcer and not (8 <= datetime.datetime.now().hour < 20):
        return 0
    seuil = (FORMATION_RELANCE_JOURS * 24 - 1) * 3600  # -1 h : tolère le décalage horaire de la tâche
    now = datetime.datetime.now()
    envoyes = 0
    conn = get_db()
    try:
        rows = conn.execute("""
            SELECT a.id AS aid, a.enseignant_id AS uid, a.statut AS a_statut, a.progression, a.assigne_le,
                   a.derniere_relance, a.derniere_activite, a.temps_total_sec, f.id, f.titre, f.date_fin, f.obligatoire,
                   f.duree_heures, f.lancee_at, f.created_at
            FROM formation_assignations a JOIN formations f ON f.id=a.formation_id
            WHERE f.statut='lancee' AND (a.statut!='termine' OR """ + _fm_sql_revision() + """)""").fetchall()
        for r in rows:
            refs = [_fm_dt(r['assigne_le'] or r['lancee_at'] or r['created_at']), _fm_dt(r['derniere_relance']),
                    _fm_dt(r['derniere_activite'])]
            refs = [x for x in refs if x]
            if not refs or (now - max(refs)).total_seconds() < seuil:
                continue
            _fm_notifier(conn, dict(r), r['uid'], rappel=True, ctx=_fm_ctx(r['a_statut'], r['progression'], r['temps_total_sec'], r['duree_heures']))
            conn.execute("UPDATE formation_assignations SET derniere_relance=?, nb_relances=COALESCE(nb_relances,0)+1 WHERE id=?",
                         (_fm_now(), r['aid']))
            envoyes += 1
        conn.commit()
    except Exception as ex:
        print(f"  ⚠️  Relances formations : {ex}")
    finally:
        conn.close()
    if envoyes:
        print(f"  🎓  Relances formations envoyées : {envoyes}")
    return envoyes


# ─────────────────────────── Routes ───────────────────────────
def _fm_dict(row):
    return dict(row) if row is not None else None


def _fm_lire_formulaire(form, files=None):
    champs = ['titre', 'description', 'categorie', 'niveau', 'type_formation', 'formateur', 'lieu', 'lien_ressource',
              'objectifs', 'prerequis', 'consignes', 'points_cles', 'date_debut', 'heure', 'date_fin']
    d = {k: (form.get(k) or '').strip() for k in champs}
    if d['type_formation'] not in FORMATION_TYPES:
        d['type_formation'] = 'en_ligne'
    d['duree_heures'] = _fm_float(form.get('duree_heures'))
    d['obligatoire'] = 1 if form.get('obligatoire') else 0
    d['attestation'] = 1 if form.get('attestation') else 0
    mode = form.get('public_mode', 'tous')
    if mode == 'cycle':
        d['public_cible'] = 'cycle:' + (form.get('cycle') or 'Primaire')
    elif mode == 'selection':
        d['public_cible'] = 'selection'
    else:
        d['public_cible'] = 'tous'
    d['cibles'] = [_fm_int(x) for x in form.getlist('cibles') if _fm_int(x)]
    etapes = []
    ids, tit, typ, dur = (form.getlist('etape_id'), form.getlist('etape_titre'),
                          form.getlist('etape_type'), form.getlist('etape_duree'))
    des, lie = form.getlist('etape_desc'), form.getlist('etape_lien')
    cles, ret = form.getlist('etape_key'), form.getlist('etape_retirer')
    files = files or {}
    d['erreur'] = ''
    d['saved'] = []
    d['fichier_up'] = files.get('fichier_principal') if (files.get('fichier_principal') and files.get('fichier_principal').filename) else None
    d['fichier_retirer'] = bool(form.get('retirer_fichier'))
    d['erreur'] = _fm_valider_upload(d['fichier_up'])
    for i in range(len(tit)):
        if not tit[i].strip():
            continue
        t = typ[i] if i < len(typ) and typ[i] in FORMATION_ETAPE_TYPES else 'lecture'
        up = files.get('etape_fichier_' + cles[i]) if i < len(cles) else None
        up = up if (up and up.filename) else None
        d['erreur'] = d['erreur'] or _fm_valider_upload(up)
        etapes.append({'up': up, 'retirer': (i < len(ret) and ret[i] == '1'),
                       'id': _fm_int(ids[i]) if i < len(ids) else 0, 'titre': tit[i].strip()[:200],
                       'type_etape': t, 'duree_min': _fm_int(dur[i]) if i < len(dur) else 0,
                       'description': (des[i].strip() if i < len(des) else ''),
                       'lien': (lie[i].strip() if i < len(lie) else '')})
    d['etapes'] = etapes
    return d


def _fm_enregistrer(conn, fid, d, uid):
    cols = ['titre', 'description', 'categorie', 'niveau', 'type_formation', 'formateur', 'lieu', 'lien_ressource',
            'objectifs', 'prerequis', 'consignes', 'points_cles', 'date_debut', 'heure', 'date_fin', 'duree_heures',
            'obligatoire', 'attestation', 'public_cible']
    vals = [d[c] for c in cols]
    if fid:
        conn.execute("UPDATE formations SET " + ", ".join(f"{c}=?" for c in cols) + " WHERE id=?", vals + [fid])
    else:
        cur = conn.execute("INSERT INTO formations (" + ", ".join(cols) + ", statut, cree_par, created_at) VALUES ("
                           + ", ".join("?" for _ in cols) + ", 'brouillon', ?, ?)", vals + [uid, _fm_now()])
        fid = cur.lastrowid
    a_supprimer = []
    old = (conn.execute("SELECT fichier_nom FROM formations WHERE id=?", (fid,)).fetchone()[0] or '')
    if d['fichier_up']:
        nom, orig, taille = _fm_sauver_upload(d['fichier_up'], d['saved'])
        conn.execute("UPDATE formations SET fichier_nom=?, fichier_orig=?, fichier_taille=? WHERE id=?", (nom, orig, taille, fid))
        a_supprimer.append(old)
    elif d['fichier_retirer'] and old:
        conn.execute("UPDATE formations SET fichier_nom='', fichier_orig='', fichier_taille=0 WHERE id=?", (fid,))
        a_supprimer.append(old)
    conn.execute("DELETE FROM formation_cibles WHERE formation_id=?", (fid,))
    if d['public_cible'] == 'selection':
        for t in d['cibles']:
            conn.execute("INSERT OR IGNORE INTO formation_cibles (formation_id, enseignant_id) VALUES (?,?)", (fid, t))
    # Étapes : on conserve les identifiants existants pour ne pas perdre la progression des enseignants.
    existants = {r[0] for r in conn.execute("SELECT id FROM formation_etapes WHERE formation_id=?", (fid,)).fetchall()}
    gardes = set()
    for ordre, e in enumerate(d['etapes'], start=1):
        if e['id'] and e['id'] in existants:
            conn.execute("""UPDATE formation_etapes SET ordre=?, titre=?, description=?, type_etape=?, duree_min=?, lien=?
                            WHERE id=?""", (ordre, e['titre'], e['description'], e['type_etape'], e['duree_min'], e['lien'], e['id']))
            gardes.add(e['id'])
            eid_cur = e['id']
            vieux = conn.execute("SELECT fichier_nom FROM formation_etapes WHERE id=?", (eid_cur,)).fetchone()[0] or ''
            if e['up']:
                nom, orig, taille = _fm_sauver_upload(e['up'], d['saved'])
                conn.execute("UPDATE formation_etapes SET fichier_nom=?, fichier_orig=?, fichier_taille=? WHERE id=?",
                             (nom, orig, taille, eid_cur))
                a_supprimer.append(vieux)
            elif e['retirer'] and vieux:
                conn.execute("UPDATE formation_etapes SET fichier_nom='', fichier_orig='', fichier_taille=0 WHERE id=?", (eid_cur,))
                a_supprimer.append(vieux)
        else:
            nom, orig, taille = _fm_sauver_upload(e['up'], d['saved']) if e['up'] else ('', '', 0)
            cur = conn.execute("""INSERT INTO formation_etapes (formation_id, ordre, titre, description, type_etape, duree_min, lien,
                                  fichier_nom, fichier_orig, fichier_taille) VALUES (?,?,?,?,?,?,?,?,?,?)""",
                               (fid, ordre, e['titre'], e['description'], e['type_etape'], e['duree_min'], e['lien'], nom, orig, taille))
            gardes.add(cur.lastrowid)
    for eid in existants - gardes:
        r = conn.execute("SELECT fichier_nom FROM formation_etapes WHERE id=?", (eid,)).fetchone()
        a_supprimer.append(r[0] if r else '')
        conn.execute("DELETE FROM formation_progression WHERE etape_id=?", (eid,))
        conn.execute("DELETE FROM formation_video_pos WHERE etape_id=?", (eid,))
        conn.execute("DELETE FROM formation_etapes WHERE id=?", (eid,))
    for r in conn.execute("SELECT id FROM formation_assignations WHERE formation_id=?", (fid,)).fetchall():
        _fm_recalculer(conn, r[0])
    return fid, a_supprimer


def _fm_form_vide():
    return {'id': None, 'titre': '', 'description': '', 'categorie': '', 'niveau': 'Tous niveaux', 'type_formation': 'en_ligne',
            'formateur': '', 'lieu': '', 'lien_ressource': '', 'objectifs': '', 'prerequis': '', 'consignes': '',
            'points_cles': '', 'date_debut': '', 'heure': '', 'date_fin': '', 'duree_heures': 0, 'obligatoire': 0, 'attestation': 0,
            'public_cible': 'tous', 'statut': 'brouillon'}


def _fm_form_page(fid=None):
    conn = get_db()
    try:
        f = _fm_form_vide()
        etapes, cibles_ids = [], []
        if fid:
            row = conn.execute("SELECT * FROM formations WHERE id=?", (fid,)).fetchone()
            if not row:
                abort(404)
            f = dict(row)
            etapes = [dict(r) for r in conn.execute(
                "SELECT * FROM formation_etapes WHERE formation_id=? ORDER BY ordre, id", (fid,)).fetchall()]
            cibles_ids = [r[0] for r in conn.execute(
                "SELECT enseignant_id FROM formation_cibles WHERE formation_id=?", (fid,)).fetchall()]
        enseignants = [dict(r) for r in conn.execute(
            "SELECT id, nom, prenom FROM users WHERE role='enseignant' ORDER BY nom, prenom").fetchall()]
        cycles = [r[0] for r in conn.execute(
            "SELECT DISTINCT COALESCE(NULLIF(cycle,''),'Primaire') FROM classes ORDER BY 1").fetchall()] or \
                 ['Maternelle', 'Primaire', 'Collège']
        pc = f.get('public_cible') or 'tous'
        mode = 'cycle' if pc.startswith('cycle:') else ('selection' if pc == 'selection' else 'tous')
        return render_template_string(
            FM_ADMIN_FORM_HTML, f=f, etapes=etapes, cibles_ids=cibles_ids, enseignants=enseignants, cycles=cycles,
            public_mode=mode, public_cycle=pc[6:] if mode == 'cycle' else '', categories=FORMATION_CATEGORIES,
            niveaux=FORMATION_NIVEAUX, types=FORMATION_TYPES, etape_types=FORMATION_ETAPE_TYPES,
            accept=FM_ACCEPT, max_mo=FORMATION_MAX_MO, relance_jours=FORMATION_RELANCE_JOURS, seuil=FORMATION_SEUIL_PCT,
            notif_count=get_notif_count())
    finally:
        conn.close()


def _fm_form_post(fid=None):
    d = _fm_lire_formulaire(request.form, request.files)
    if d['erreur']:
        flash(d['erreur'], 'error')
        return redirect(request.url)
    if not d['titre']:
        flash('Le titre de la formation est obligatoire.', 'error')
        return redirect(request.url)
    if d['date_debut'] and d['date_fin'] and d['date_fin'] < d['date_debut']:
        flash('La date limite ne peut pas précéder la date de début.', 'error')
        return redirect(request.url)
    conn = get_db()
    try:
        try:
            fid, a_supprimer = _fm_enregistrer(conn, fid, d, session['user_id'])
        except ValueError as ex:  # conversion PDF impossible, etc.
            conn.rollback()
            _fm_supprimer_fichiers(d['saved'])
            flash(str(ex), 'error')
            return redirect(request.url)
        action = request.form.get('action', 'brouillon')
        f = conn.execute("SELECT * FROM formations WHERE id=?", (fid,)).fetchone()
        if action == 'lancer' and f['statut'] != 'lancee':
            conn.execute("UPDATE formations SET statut='lancee', lancee_at=? WHERE id=?", (_fm_now(), fid))
            n = _fm_synchroniser(conn, fid)
            flash(f"Formation lancée : {n} enseignant{'s' if n > 1 else ''} notifié{'s' if n > 1 else ''}.", 'success')
        elif f['statut'] == 'lancee':
            n = _fm_synchroniser(conn, fid)
            flash('Formation mise à jour' + (f" ({n} nouvel enseignant notifié)." if n else '.'), 'success')
        else:
            flash('Brouillon enregistré. Vous pourrez le lancer quand vous voulez.', 'success')
        conn.commit()
        _fm_supprimer_fichiers(a_supprimer)  # anciens fichiers remplacés/retirés, seulement après validation en base
    finally:
        conn.close()
    return redirect(url_for('formation_detail', fid=fid))


@app.route('/formation')
@login_required
@role_required('enseignant', 'admin')
def formation_index():
    conn = get_db()
    try:
        if is_admin_like():
            rows = conn.execute("""
                SELECT f.*,
                  (SELECT COUNT(*) FROM formation_etapes e WHERE e.formation_id=f.id) AS nb_etapes,
                  (SELECT COUNT(*) FROM formation_assignations a WHERE a.formation_id=f.id) AS nb_cibles,
                  (SELECT COUNT(*) FROM formation_assignations a WHERE a.formation_id=f.id AND a.statut='termine') AS nb_termine,
                  (SELECT COUNT(*) FROM formation_assignations a WHERE a.formation_id=f.id AND a.statut='en_cours') AS nb_en_cours
                FROM formations f
                ORDER BY CASE f.statut WHEN 'lancee' THEN 0 WHEN 'brouillon' THEN 1 ELSE 2 END, f.id DESC""").fetchall()
            items, tot_c, tot_t, retard = [], 0, 0, 0
            insuf = {x[0]: x[1] for x in conn.execute(
                "SELECT a.formation_id, COUNT(*) FROM formation_assignations a JOIN formations f ON f.id=a.formation_id "
                "WHERE " + _fm_sql_revision() + " GROUP BY a.formation_id").fetchall()}
            for r in rows:
                d = dict(r)
                d['nb_insuf'] = insuf.get(d['id'], 0)
                d['type_ico'], d['type_label'] = _fm_type(d['type_formation'])
                d['ech'] = _fm_echeance(d['date_fin'])
                d['taux'] = round(d['nb_termine'] * 100 / d['nb_cibles']) if d['nb_cibles'] else 0
                if d['statut'] == 'lancee':
                    tot_c += d['nb_cibles']
                    tot_t += d['nb_termine']
                    if d['ech']['cls'] == 'late':
                        retard += d['nb_cibles'] - d['nb_termine']
                items.append(d)
            st = {'lancees': sum(1 for i in items if i['statut'] == 'lancee'),
                  'brouillons': sum(1 for i in items if i['statut'] == 'brouillon'),
                  'taux': round(tot_t * 100 / tot_c) if tot_c else 0, 'retard': retard}
            return render_template_string(FM_ADMIN_LISTE_HTML, items=items, st=st, seuil=FORMATION_SEUIL_PCT,
                                          notif_count=get_notif_count())
        if session.get('role') != 'enseignant':
            return redirect(url_for('dashboard'))
        rows = conn.execute("""
            SELECT f.*, f.statut AS f_statut, a.statut AS a_statut, a.progression, a.derniere_activite, a.temps_total_sec,
              (SELECT COUNT(*) FROM formation_etapes e WHERE e.formation_id=f.id) AS nb_etapes,
              (SELECT COUNT(*) FROM formation_progression p JOIN formation_etapes e ON e.id=p.etape_id
                 WHERE p.assignation_id=a.id AND e.formation_id=f.id) AS nb_fait
            FROM formation_assignations a JOIN formations f ON f.id=a.formation_id
            WHERE a.enseignant_id=? AND f.statut IN ('lancee','cloturee')
            ORDER BY (a.statut='termine') ASC, (a.statut='en_cours') DESC,
                     CASE WHEN f.date_fin='' THEN '9999' ELSE f.date_fin END ASC, f.id DESC""",
                            (session['user_id'],)).fetchall()
        items = []
        for r in rows:
            d = dict(r)
            d['type_ico'], d['type_label'] = _fm_type(d['type_formation'])
            d['revision'] = _fm_revision_requise(d['a_statut'], d.get('temps_total_sec'), d.get('duree_heures'))
            d['pct_temps'] = _fm_pct_temps(d.get('temps_total_sec'), d.get('duree_heures'))
            d['s_aff'] = 'revision' if d['revision'] else d['a_statut']
            d['ech'] = _fm_echeance(d['date_fin'], d['a_statut'] == 'termine' and not d['revision'])
            d['depuis'] = _fm_depuis(d['derniere_activite'])
            d['temps_txt'] = _fm_duree_txt(d.get('temps_total_sec'))
            items.append(d)
        items.sort(key=lambda i: 1 if (i['a_statut'] == 'termine' and not i['revision']) else 0)
        st = {'a_traiter': sum(1 for i in items if i['f_statut'] == 'lancee' and (i['a_statut'] != 'termine' or i['revision'])),
              'en_cours': sum(1 for i in items if i['a_statut'] == 'en_cours'),
              'termine': sum(1 for i in items if i['a_statut'] == 'termine' and not i['revision'])}
        cands = [i for i in items if i['f_statut'] == 'lancee' and (i['a_statut'] == 'en_cours' or i['revision'])]
        reprendre = sorted(cands, key=lambda x: x['derniere_activite'] or '', reverse=True)[0] if cands else None
        return render_template_string(FM_ENS_LISTE_HTML, items=items, st=st, reprendre=reprendre, seuil=FORMATION_SEUIL_PCT,
                                      notif_count=get_notif_count())
    finally:
        conn.close()


