@app.route('/formation/<int:fid>')
@login_required
@role_required('enseignant', 'admin')
def formation_detail(fid):
    conn = get_db()
    try:
        row = conn.execute("SELECT * FROM formations WHERE id=?", (fid,)).fetchone()
        if not row:
            abort(404)
        f = dict(row)
        ico, lab = _fm_type(f['type_formation'])
        etapes = [dict(r) for r in conn.execute(
            "SELECT * FROM formation_etapes WHERE formation_id=? ORDER BY ordre, id", (fid,)).fetchall()]
        for e in etapes:
            e['type_ico'], e['type_label'] = FORMATION_ETAPE_TYPES.get(e['type_etape'], ('📖', 'Lecture'))
        if is_admin_like():
            f['fichier'] = _fm_fichier_info(fid, 0, f.get('fichier_nom'), f.get('fichier_orig'), f.get('fichier_taille'))
            for e in etapes:
                e['fichier'] = _fm_fichier_info(fid, e['id'], e.get('fichier_nom'), e.get('fichier_orig'), e.get('fichier_taille'))
            rows = []
            for r in conn.execute("""
                SELECT a.*, u.prenom, u.nom,
                  (SELECT COUNT(*) FROM formation_progression p JOIN formation_etapes e ON e.id=p.etape_id
                     WHERE p.assignation_id=a.id AND e.formation_id=a.formation_id) AS nb_fait
                FROM formation_assignations a JOIN users u ON u.id=a.enseignant_id
                WHERE a.formation_id=? ORDER BY u.nom, u.prenom""", (fid,)).fetchall():
                d = dict(r)
                duree_h = float(f.get('duree_heures') or 0)
                d['temps_sec'] = float(d.get('temps_total_sec') or 0)
                d['pct_temps'] = _fm_pct_temps(d['temps_sec'], duree_h)
                d['pct_bar'] = min(100, d['pct_temps'] or 0)
                d['segment'] = _fm_segment(d['statut'], d['temps_sec'], duree_h)
                d['initiales'] = ((d.get('prenom') or ' ')[:1] + (d.get('nom') or ' ')[:1]).upper()
                d['reste_txt'] = _fm_duree_txt(max(0.0, _fm_seuil_sec(duree_h) - d['temps_sec']))
                d['depuis'] = _fm_depuis(d['derniere_activite'])
                d['temps_txt'] = _fm_duree_txt(d.get('temps_total_sec'))
                det = []
                for t in conn.execute("""SELECT t.etape_id, t.sec, e.titre, e.ordre FROM formation_temps t
                                        LEFT JOIN formation_etapes e ON e.id=t.etape_id
                                        WHERE t.assignation_id=? ORDER BY COALESCE(e.ordre, 0)""", (d['id'],)).fetchall():
                    det.append((f"Étape « {t['titre']} »" if t['etape_id'] else 'Hors étape / fichier principal',
                                _fm_duree_txt(t['sec'])))
                d['temps_detail'] = det
                rows.append(d)
            pc = f['public_cible'] or 'tous'
            pub = 'Tous les enseignants' if pc == 'tous' else (f"Cycle {pc[6:]}" if pc.startswith('cycle:') else 'Sélection manuelle')
            duree_h = float(f.get('duree_heures') or 0)
            counts = {k: sum(1 for r in rows if r['segment'] == k) for k in ('valide', 'insuffisant', 'en_cours', 'pas_commence')}
            total = len(rows)
            coul = {'valide': '#10B981', 'insuffisant': '#F59E0B', 'en_cours': '#3B82F6', 'pas_commence': '#D1D5DB'}
            if total:
                cur, parts = 0.0, []
                for k in ('valide', 'insuffisant', 'en_cours', 'pas_commence'):
                    nxt = cur + counts[k] * 100.0 / total
                    if counts[k]:
                        parts.append(f"{coul[k]} {cur:.2f}% {nxt:.2f}%")
                    cur = nxt
                donut = "conic-gradient(" + ", ".join(parts) + ")"
            else:
                donut = '#e5e7eb'
            seg_init = request.args.get('seg', 'all')
            if seg_init not in ('all', 'passe', 'pas_passe', 'moins80', 'en_cours', 'pas_commence'):
                seg_init = 'all'
            moy = sum(r['temps_sec'] for r in rows) / total if total else 0
            return render_template_string(
                FM_ADMIN_DETAIL_HTML, f=f, etapes=etapes, rows=rows, type_ico=ico, type_label=lab,
                counts=counts, donut=donut, taux=round(counts['valide'] * 100 / total) if total else 0, seg_init=seg_init,
                has_duree=duree_h > 0, seuil_pct=FORMATION_SEUIL_PCT, seuil_txt=_fm_duree_txt(_fm_seuil_sec(duree_h)),
                duree_txt=_fm_duree_txt(duree_h * 3600), temps_moyen_txt=_fm_duree_txt(moy),
                ech=_fm_echeance(f['date_fin']), public_label=pub, nb_etapes=len(etapes),
                nb_termine=sum(1 for r in rows if r['statut'] == 'termine'),
                nb_en_cours=sum(1 for r in rows if r['statut'] == 'en_cours'),
                nb_a_faire=sum(1 for r in rows if r['statut'] == 'a_faire'), notif_count=get_notif_count(),
                temps_total_txt=_fm_duree_txt(sum(float(r.get('temps_total_sec') or 0) for r in rows)),
                relance_jours=FORMATION_RELANCE_JOURS)
        a = _fm_assignation_enseignant(conn, fid, session['user_id'])
        if not a:
            flash("Cette formation n'est pas disponible pour vous.", 'error')
            return redirect(url_for('formation_index'))
        a = dict(a)
        f['f_statut'] = f['statut']
        faits = {r[0] for r in conn.execute(
            "SELECT etape_id FROM formation_progression WHERE assignation_id=?", (a['id'],)).fetchall()}
        positions = {r[0]: r[1] for r in conn.execute(
            "SELECT etape_id, pos FROM formation_video_pos WHERE assignation_id=?", (a['id'],)).fetchall()}
        f['fichier'] = _fm_fichier_info(fid, 0, f.get('fichier_nom'), f.get('fichier_orig'), f.get('fichier_taille'),
                                        positions.get(0, 0))
        for i, e in enumerate(etapes, start=1):
            e['fait'] = e['id'] in faits
            e['ordre_aff'] = i
            e['fichier'] = _fm_fichier_info(fid, e['id'], e.get('fichier_nom'), e.get('fichier_orig'),
                                            e.get('fichier_taille'), positions.get(e['id'], 0))
        duree = float(f.get('duree_heures') or 0)
        temps = float(a.get('temps_total_sec') or 0)
        revision = _fm_revision_requise(a['statut'], temps, duree)
        pct = _fm_pct_temps(temps, duree)
        seuil_txt = _fm_duree_txt(_fm_seuil_sec(duree))
        reste_txt = _fm_duree_txt(max(0.0, _fm_seuil_sec(duree) - temps))
        if revision:
            tmsg = f"Étapes terminées, mais il manque encore {reste_txt} pour atteindre {FORMATION_SEUIL_PCT} % : faites une petite révision."
        elif pct is not None and pct >= FORMATION_SEUIL_PCT:
            tmsg = f"✅ Temps minimum atteint ({FORMATION_SEUIL_PCT} %)."
        else:
            tmsg = (f"Pour valider la formation, passez au moins {seuil_txt} ({FORMATION_SEUIL_PCT} % de la durée prévue). "
                    f"Le temps se compte automatiquement quand vous êtes actif sur cette page.")
        points = [l.strip() for l in (f.get('points_cles') or '').splitlines() if l.strip()]
        reprendre = None
        if etapes and a['statut'] != 'termine':
            cand = next((e for e in etapes if e['id'] == a['etape_courante_id'] and not e['fait']), None) \
                or next((e for e in etapes if not e['fait']), None)
            if cand:
                reprendre = {'id': cand['id'], 'titre': cand['titre'], 'pos': cand['ordre_aff']}
        return render_template_string(
            FM_ENS_DETAIL_HTML, f=f, a=a, etapes=etapes, type_ico=ico, type_label=lab,
            ech=_fm_echeance(f['date_fin'], a['statut'] == 'termine'), nb_total=len(etapes), nb_fait=len(faits),
            reprendre=reprendre, depuis=_fm_depuis(a['derniere_activite']), notif_count=get_notif_count(),
            temps_txt=_fm_duree_txt(a.get('temps_total_sec')),
            suivi_temps=(a['f_statut'] == 'lancee' and (a['statut'] != 'termine' or revision)),
            revision=revision, pct_temps=pct, seuil_pct=FORMATION_SEUIL_PCT, seuil_txt=seuil_txt, tmsg=tmsg,
            duree_txt=_fm_duree_txt(duree * 3600), duree_sec=duree * 3600, seuil_sec=_fm_seuil_sec(duree), points=points)
    finally:
        conn.close()


