@app.route('/formation/<int:fid>/supprimer', methods=['POST'])
@login_required
@role_required('admin')
def formation_supprimer(fid):
    conn = get_db()
    try:
        noms = [r[0] for r in conn.execute("SELECT fichier_nom FROM formations WHERE id=?", (fid,)).fetchall()]
        noms += [r[0] for r in conn.execute("SELECT fichier_nom FROM formation_etapes WHERE formation_id=?", (fid,)).fetchall()]
        conn.execute("DELETE FROM formation_video_pos WHERE assignation_id IN "
                     "(SELECT id FROM formation_assignations WHERE formation_id=?)", (fid,))
        conn.execute("DELETE FROM formation_progression WHERE assignation_id IN "
                     "(SELECT id FROM formation_assignations WHERE formation_id=?)", (fid,))
        for t in ('formation_assignations', 'formation_cibles', 'formation_etapes'):
            conn.execute(f"DELETE FROM {t} WHERE formation_id=?", (fid,))
        conn.execute("DELETE FROM formations WHERE id=?", (fid,))
        conn.commit()
        _fm_supprimer_fichiers(noms)
    finally:
        conn.close()
    flash('Formation supprimée.', 'success')
    return redirect(url_for('formation_index'))


@app.route('/formation/<int:fid>/relancer', methods=['POST'])
@login_required
@role_required('admin')
def formation_relancer(fid):
    """Relance : un enseignant (enseignant_id), une sélection (ids) ou tous les non-validés (aucun paramètre).
    Le message s'adapte : pas commencé / reprenez / « vous avez terminé mais < 80 % du temps → petite révision »."""
    conn = get_db()
    try:
        f = conn.execute("SELECT * FROM formations WHERE id=? AND statut='lancee'", (fid,)).fetchone()
        if not f:
            abort(404)
        voulus = {_fm_int(x) for x in request.form.getlist('ids') if _fm_int(x)}
        if _fm_int(request.form.get('enseignant_id')):
            voulus.add(_fm_int(request.form.get('enseignant_id')))
        lignes = conn.execute("SELECT id, enseignant_id, statut, progression, temps_total_sec FROM formation_assignations "
                              "WHERE formation_id=?", (fid,)).fetchall()
        envoyes, revisions = 0, 0
        for r in lignes:
            if voulus and r['enseignant_id'] not in voulus:
                continue
            ctx = _fm_ctx(r['statut'], r['progression'], r['temps_total_sec'], f['duree_heures'])
            if r['statut'] == 'termine' and not ctx['revision']:
                continue  # déjà validée
            _fm_notifier(conn, f, r['enseignant_id'], rappel=True, ctx=ctx)
            conn.execute("UPDATE formation_assignations SET derniere_relance=?, nb_relances=COALESCE(nb_relances,0)+1 WHERE id=?",
                         (_fm_now(), r['id']))
            envoyes += 1
            revisions += 1 if ctx['revision'] else 0
        conn.commit()
    finally:
        conn.close()
    if envoyes:
        flash(f"Rappel envoyé à {envoyes} enseignant{'s' if envoyes > 1 else ''}"
              + (f" (dont {revisions} invité{'s' if revisions > 1 else ''} à réviser)." if revisions else '.'), 'success')
    else:
        flash('Personne à relancer.', 'success')
    return redirect(url_for('formation_detail', fid=fid))


@app.route('/formation/<int:fid>/export.csv')
@login_required
@role_required('admin')
def formation_export_csv(fid):
    """Export du suivi (ouvrable directement dans Excel : séparateur « ; », encodage UTF-8 avec BOM)."""
    import csv
    conn = get_db()
    try:
        f = conn.execute("SELECT * FROM formations WHERE id=?", (fid,)).fetchone()
        if not f:
            abort(404)
        duree = float(f['duree_heures'] or 0)
        sortie = io.StringIO()
        w = csv.writer(sortie, delimiter=';')
        w.writerow(['Nom', 'Prénom', 'Situation', 'Statut', 'Progression %', 'Temps passé (min)', 'Durée prévue (min)',
                    f"Minimum {FORMATION_SEUIL_PCT} % (min)", '% du temps prévu', 'Dernière activité', 'Relances', 'Terminée le'])
        libelles = {'valide': 'A passé', 'insuffisant': f'Terminée, moins de {FORMATION_SEUIL_PCT} % du temps',
                    'en_cours': 'En cours', 'pas_commence': 'Pas commencée'}
        for r in conn.execute("""SELECT a.*, u.nom, u.prenom FROM formation_assignations a JOIN users u ON u.id=a.enseignant_id
                                 WHERE a.formation_id=? ORDER BY u.nom, u.prenom""", (fid,)).fetchall():
            t = float(r['temps_total_sec'] or 0)
            seg = _fm_segment(r['statut'], t, duree)
            pct = _fm_pct_temps(t, duree)
            w.writerow([r['nom'], r['prenom'], libelles[seg], r['statut'], r['progression'], round(t / 60, 1),
                        round(duree * 60, 1) if duree else '', round(_fm_seuil_sec(duree) / 60, 1) if duree else '',
                        pct if pct is not None else '', r['derniere_activite'] or '', r['nb_relances'] or 0,
                        (r['date_fin_reel'] or '')[:10]])
    finally:
        conn.close()
    nom = re.sub(r'[^A-Za-z0-9_-]+', '_', f['titre'])[:40] or f'formation_{fid}'
    rep_ = app.response_class('\ufeff' + sortie.getvalue(), mimetype='text/csv; charset=utf-8')
    rep_.headers['Content-Disposition'] = f'attachment; filename=suivi_{nom}.csv'
    return rep_


# ---- Téléchargement / lecture des fichiers importés (accès : admin, ou enseignant concerné) ----
def _fm_servir_fichier(fid, eid):
    conn = get_db()
    try:
        if eid:
            r = conn.execute("SELECT fichier_nom, fichier_orig FROM formation_etapes WHERE id=? AND formation_id=?",
                             (eid, fid)).fetchone()
        else:
            r = conn.execute("SELECT fichier_nom, fichier_orig FROM formations WHERE id=?", (fid,)).fetchone()
        if not r or not r['fichier_nom']:
            abort(404)
        if not is_admin_like() and not _fm_assignation_enseignant(conn, fid, session['user_id']):
            abort(403)
        nom, orig = os.path.basename(r['fichier_nom']), r['fichier_orig'] or r['fichier_nom']
    finally:
        conn.close()
    chemin = os.path.join(UPLOAD_FOLDER_FORMATIONS, nom)
    if not os.path.isfile(chemin):
        abort(404)
    # Lecture dans l'application uniquement : on refuse l'ouverture directe du fichier comme page
    # (barre d'adresse, nouvel onglet, iframe). Seuls le lecteur vidéo/audio, l'image et le lecteur PDF
    # intégré (requêtes fetch) y accèdent. Aucun bouton « télécharger » n'existe dans l'interface.
    if request.headers.get('Sec-Fetch-Dest', '') in ('document', 'iframe', 'embed', 'object', 'frame'):
        abort(403)
    mime = mimetypes.guess_type(nom)[0] or 'application/octet-stream'
    # conditional=True : prise en charge des requêtes Range (avance rapide / reprise des vidéos sur mobile)
    rep_ = send_file(chemin, mimetype=mime, as_attachment=False, conditional=True)
    rep_.headers['Content-Disposition'] = 'inline'
    rep_.headers['X-Content-Type-Options'] = 'nosniff'
    rep_.headers['Cache-Control'] = 'private, no-store'
    return rep_


