@app.route('/formation/<int:fid>/temps', methods=['POST'])
@login_required
@role_required('enseignant')
def formation_temps(fid):
    """Battement de cœur du suivi du temps. Le navigateur n'envoie que lorsque l'onglet est visible ET que
    l'enseignant est actif (ou qu'une vidéo/audio est en lecture). Le serveur plafonne chaque ajout à l'écart
    réel depuis le dernier battement : impossible de gonfler le temps en rejouant la requête."""
    data = request.get_json(silent=True) or {}
    try:
        s = float(data.get('s', 0))
        eid = int(data.get('e', 0) or 0)
    except (TypeError, ValueError):
        return jsonify({'ok': False}), 400
    conn = get_db()
    try:
        a = _fm_assignation_enseignant(conn, fid, session['user_id'])
        fm = conn.execute("SELECT * FROM formations WHERE id=?", (fid,)).fetchone()
        if not a or a['f_statut'] != 'lancee':
            return jsonify({'ok': False, 'stop': True})
        total = float(a['temps_total_sec'] or 0)
        rev_avant = _fm_revision_requise(a['statut'], total, fm['duree_heures'])
        if a['statut'] == 'termine' and not rev_avant:
            return jsonify({'ok': False, 'stop': True})  # formation validée : plus de décompte
        if eid and not conn.execute("SELECT 1 FROM formation_etapes WHERE id=? AND formation_id=?", (eid, fid)).fetchone():
            eid = 0
        dernier = _fm_dt(a['dernier_ping'])
        ecart = (datetime.datetime.now() - dernier).total_seconds() if dernier else 15.0
        delta = max(0.0, min(s, ecart, 30.0))
        if delta < 1:
            return jsonify({'ok': True, 'total': total, 'pct': _fm_pct_temps(total, fm['duree_heures']),
                            'valide': False, 'revision': rev_avant})
        now = _fm_now()
        conn.execute("""INSERT INTO formation_temps (assignation_id, etape_id, sec) VALUES (?,?,?)
                        ON CONFLICT(assignation_id, etape_id) DO UPDATE SET sec=sec+excluded.sec""", (a['id'], eid, delta))
        conn.execute("""UPDATE formation_assignations SET temps_total_sec=COALESCE(temps_total_sec,0)+?, dernier_ping=?,
                        derniere_activite=?, date_debut_reel=CASE WHEN date_debut_reel='' THEN ? ELSE date_debut_reel END,
                        statut=CASE WHEN statut='a_faire' THEN 'en_cours' ELSE statut END WHERE id=?""",
                     (delta, now, now, now, a['id']))
        valide = rev_avant and not _fm_revision_requise('termine', total + delta, fm['duree_heures'])
        if valide:
            _fm_validation_temps(conn, fm, session['user_id'], a['id'])
        conn.commit()
        return jsonify({'ok': True, 'total': total + delta, 'pct': _fm_pct_temps(total + delta, fm['duree_heures']),
                        'valide': valide, 'revision': rev_avant and not valide})
    finally:
        conn.close()


@app.route('/formation/<int:fid>/etape/<int:eid>/position', methods=['POST'])
@login_required
@role_required('enseignant')
def formation_video_position(fid, eid):
    """Mémorise la seconde atteinte dans une vidéo/audio : la lecture reprend là même le lendemain, sur n'importe quel appareil."""
    data = request.get_json(silent=True) or {}
    try:
        t = max(0.0, float(data.get('t', 0)))
        dur = float(data.get('d', 0) or 0)
    except (TypeError, ValueError):
        return jsonify({'ok': False}), 400
    conn = get_db()
    try:
        a = _fm_assignation_enseignant(conn, fid, session['user_id'])
        if not a or a['f_statut'] != 'lancee':
            return jsonify({'ok': False}), 404
        if eid and not conn.execute("SELECT 1 FROM formation_etapes WHERE id=? AND formation_id=?", (eid, fid)).fetchone():
            return jsonify({'ok': False}), 404
        if dur and data.get('k') != 'pdf' and t >= dur - 3:
            t = 0.0  # vidéo terminée : la prochaine lecture repart du début
        now = _fm_now()
        conn.execute("""INSERT INTO formation_video_pos (assignation_id, etape_id, pos) VALUES (?,?,?)
                        ON CONFLICT(assignation_id, etape_id) DO UPDATE SET pos=excluded.pos""", (a['id'], eid, t))
        conn.execute("UPDATE formation_assignations SET derniere_activite=?, "
                     "etape_courante_id=CASE WHEN ?>0 THEN ? ELSE etape_courante_id END, "
                     "date_debut_reel=CASE WHEN date_debut_reel='' THEN ? ELSE date_debut_reel END, "
                     "statut=CASE WHEN statut='a_faire' THEN 'en_cours' ELSE statut END WHERE id=?",
                     (now, eid, eid, now, a['id']))
        conn.commit()
        return jsonify({'ok': True})
    finally:
        conn.close()


