@app.route('/formation/<int:fid>/etape/<int:eid>/toggle', methods=['POST'])
@login_required
@role_required('enseignant')
def formation_etape_toggle(fid, eid):
    conn = get_db()
    try:
        a = _fm_assignation_enseignant(conn, fid, session['user_id'])
        e = conn.execute("SELECT id FROM formation_etapes WHERE id=? AND formation_id=?", (eid, fid)).fetchone()
        if not a or not e:
            return jsonify({'ok': False, 'erreur': 'Formation introuvable.'}), 404
        if a['f_statut'] != 'lancee':
            return jsonify({'ok': False, 'erreur': 'Formation clôturée.'}), 403
        deja = conn.execute("SELECT 1 FROM formation_progression WHERE assignation_id=? AND etape_id=?",
                            (a['id'], eid)).fetchone()
        now = _fm_now()
        if deja:
            conn.execute("DELETE FROM formation_progression WHERE assignation_id=? AND etape_id=?", (a['id'], eid))
        else:
            conn.execute("INSERT OR IGNORE INTO formation_progression (assignation_id, etape_id, fait_le) VALUES (?,?,?)",
                         (a['id'], eid, now))
        conn.execute("UPDATE formation_assignations SET derniere_activite=?, etape_courante_id=?, "
                     "date_debut_reel=CASE WHEN date_debut_reel='' THEN ? ELSE date_debut_reel END WHERE id=?",
                     (now, eid, now, a['id']))
        res = _fm_recalculer(conn, a['id'])
        if res['vient_de_finir']:
            _fm_apres_fin(conn, fid, session['user_id'], a['id'])
        fr = conn.execute("SELECT duree_heures FROM formations WHERE id=?", (fid,)).fetchone()
        tt = conn.execute("SELECT temps_total_sec FROM formation_assignations WHERE id=?", (a['id'],)).fetchone()[0] or 0
        rev = _fm_revision_requise(res['statut'], tt, fr['duree_heures'])
        conn.commit()
        return jsonify({'ok': True, 'fait': not deja, 'progression': res['progression'], 'nb_fait': res['nb_fait'],
                        'nb_total': res['nb_total'], 'termine': res['statut'] == 'termine', 'revision': rev,
                        'reste_txt': _fm_duree_txt(max(0.0, _fm_seuil_sec(fr['duree_heures']) - float(tt)))})
    finally:
        conn.close()


