@app.after_request
def _maj_injecter_avis(resp):
    """Ajoute le bandeau d'avis (admin / agent admin) ou le message « mise à jour effectuée » (tous) aux pages HTML."""
    try:
        if resp.status_code != 200 or resp.mimetype != 'text/html' or resp.direct_passthrough:
            return resp
        uid = session.get('user_id')
        if not uid or request.path.startswith('/static'):
            return resp
        etat = _maj_get()
        if not etat:
            return resp
        snippet = ''
        if etat['statut'] == 'programmee' and etat.get('date_maj') and session.get('role') in ('admin', 'agent_admin'):
            d = None
            try:
                d = datetime.datetime.strptime(etat['date_maj'], '%Y-%m-%dT%H:%M')
            except ValueError:
                pass
            if d:
                extra = ''
                if etat.get('message'):
                    extra = ('<div style="margin-top:4px;opacity:.95">📝 ' + _html_maj.escape(etat['message']) + '</div>')
                snippet = (_MAJ_BANDEAU_HTML.replace('__T__', etat['date_maj']).replace('__V__', str(etat['version']))
                           .replace('__DATE__', _html_maj.escape(_maj_date_txt(etat['date_maj'])))
                           .replace('__SHORT__', d.strftime('%d/%m à %H:%M')).replace('__EXTRA__', extra))
        elif etat['statut'] == 'terminee' and session.get('maj_vu') != etat['version']:
            recent = True
            try:
                fin = datetime.datetime.strptime(etat['termine_at'], '%Y-%m-%d %H:%M:%S')
                recent = (datetime.datetime.now() - fin).days < _MAJ_FIN_VISIBLE_JOURS
            except (TypeError, ValueError):
                pass
            if recent:
                conn = get_db()
                try:
                    deja = conn.execute("SELECT 1 FROM maj_vues WHERE user_id=? AND version=?",
                                        (uid, etat['version'])).fetchone()
                finally:
                    conn.close()
                if deja:
                    session['maj_vu'] = etat['version']
                else:
                    snippet = _MAJ_EFFECTUEE_HTML
        if not snippet:
            return resp
        html = resp.get_data(as_text=True)
        i = html.rfind('</body>')
        if i < 0:
            return resp
        resp.set_data(html[:i] + snippet + html[i:])
    except Exception as e:
        print(f"  ⚠️  avis mise à jour : {e}")
    return resp


