#bugrep-box textarea{width:100%;min-height:110px;resize:vertical;border:1px solid rgba(120,120,128,.4);border-radius:12px;padding:10px 12px;font:inherit;font-size:.92rem;background:#fff;color:#1d1d1f;box-sizing:border-box}
html.theme-neon #bugrep-box textarea{background:#1d1d2b;color:#EDEDF7}
#bugrep-box .bf{display:flex;gap:8px;justify-content:flex-end;padding:12px 18px;border-top:1px solid rgba(120,120,128,.25)}
#bugrep-box .bbtn{border:1px solid rgba(120,120,128,.4);background:transparent;color:inherit;border-radius:12px;padding:10px 18px;font:inherit;font-weight:700;font-size:.88rem;cursor:pointer}
#bugrep-box .bbtn.pri{background:#dc2626;border-color:#dc2626;color:#fff} #bugrep-box .bbtn[disabled]{opacity:.6;cursor:wait}
